using System.Linq;
using System.Configuration;

namespace INPS.Pensioni.Liquidazione.BLCommon
{
    public class GestioneCrossControls
    {
        #region ALL

        public static bool ALL_VerificaResidenzaEsteroTitolare(bool? isResidenteEstero, string codiceCatastale, string frazioneResidenza, out string messaggioVideo)
        {
            messaggioVideo = string.Empty;

            if (string.IsNullOrEmpty(codiceCatastale))
            {
                messaggioVideo = "Codice Catastale assente. Verificare e aggiornare su Arca le informazioni relative alla residenza estera prima di proseguire nella lavorazione";
                return false;
            }

            if (!isResidenteEstero.HasValue)
                return true;

            if ((isResidenteEstero.GetValueOrDefault() == true && !Utility.IsResidenteEstero(codiceCatastale)) || (isResidenteEstero.GetValueOrDefault() == false && Utility.IsResidenteEstero(codiceCatastale)))
            {
                messaggioVideo = "Verificare e aggiornare su Arca le informazioni relative alla residenza estera prima di proseguire nella lavorazione";
                return false;
            }

            if (isResidenteEstero.Value && string.IsNullOrEmpty(frazioneResidenza))
            {
                messaggioVideo = "Frazione assente. Verificare e aggiornare su Arca le informazioni relative alla frazione prima di proseguire nella lavorazione";
                return false;
            }

            return true;
        }

        public static bool ALL_VerificaResidenzaContributiveFiltroERI(GestionePensione.DatiPensione datiPensione, string cittadinanza, string codiceComuneResidenza, DateTime? decorrenzaPensione, out string messaggioVideo)
        {
            messaggioVideo = string.Empty;

            if (Utility.IsDomandaVOAUTContributivoOpzioneFiltroERI(datiPensione) || Utility.IsDomandaAGOTipoContributivoFiltroERI(datiPensione))
            {
                if (cittadinanza == "Z000")
                {
                    messaggioVideo = "La cittadinanza non può essere ITALIA";
                    return false;
                }
                if (cittadinanza != codiceComuneResidenza)
                {
                    messaggioVideo = "Il paese di residenza del titolare della domanda deve essere lo stesso di quello di cittadinanza";
                    return false;
                }
                var isUe = BLCommon.GestioneDecodifica.CheckPeriodiAppartenenzaUE(cittadinanza, decorrenzaPensione);
                if (isUe > 0)
                {
                    messaggioVideo = "Il paese di cittadinanza non può essere appartenente all'unione europea";
                    return false;
                }
            }

            return true;
        }

        public static bool ALL_VerificaProvinciaTitolare(string provinciaResidenza, out string messaggioVideo)
        {
            messaggioVideo = string.Empty;

            if (string.IsNullOrEmpty(provinciaResidenza) || string.IsNullOrEmpty(provinciaResidenza.Trim()))
            {
                messaggioVideo = "Provincia assente. Verificare e aggiornare su Arca le informazioni relative alla provincia prima di proseguire nella lavorazione";
                return false;
            }

            return true;
        }

        /// <summary>
        /// Verifica se ci sono delle incongruenze tra la residenza del titolare, l'eventuale esenzione fiscale e quando salvato a Db sul campo esenzione fiscale
        /// </summary>
        /// <param name="messaggioVideo"></param>
        /// <returns></returns>
        public static bool ALL_VerificaIncongruenzaEsenzioneFiscaleToDB(GestionePensione.DatiPensione datiPensione, string codiceComuneResidenza, GestioneDetrazioniImposta.DatiDetrazioni datiDetrazioni,
            bool isRiaperturaDomanda, byte? esenzioneFiscaleDB, out string messaggioVideo)
        {
            messaggioVideo = string.Empty;
            if (!Utility.IsDomandaINPDAP(datiPensione.Gestione))
            {
                if (!Utility.IsEsenzioneFiscaleEstero(datiPensione, codiceComuneResidenza, datiDetrazioni, isRiaperturaDomanda) && esenzioneFiscaleDB.GetValueOrDefault() == 2)
                {
                    messaggioVideo = "Incongruenza tra Esenzione Fiscale salvata e lo Stato Estero di residenza del titolare. Salvare o eliminare nuovamente i Dati Generici";
                    return false;
                }
            }
            else
            {
                if (!Utility.IsEsenzioneFiscaleEsteroINPDAP(codiceComuneResidenza) && esenzioneFiscaleDB.GetValueOrDefault() == 2)
                {
                    messaggioVideo = "Incongruenza tra Esenzione Fiscale salvata e lo Stato Estero di residenza del titolare. Salvare o eliminare nuovamente i Dati Generici";
                    return false;
                }
            }

            return true;
        }

        public static bool ALL_VerificaDecorrenzaEliminazioneWithRedditi(List<GestioneRedditi.RedditoDRedd> lstRedditiDB, DateTime? dataEventoElim, out string messaggioVideo)
        {
            bool ret = true;
            messaggioVideo = string.Empty;
            if (lstRedditiDB == null || lstRedditiDB.Count == 0 || !dataEventoElim.HasValue)
                return true;

            int maxYearRedditi = lstRedditiDB.OrderBy(elem => elem.AnnoReddito).Last().AnnoReddito;
            int yearDecorrenzaElim = dataEventoElim.Value.Year;
            if (yearDecorrenzaElim < maxYearRedditi)
            {
                messaggioVideo = "Sono stati acquisiti redditi successivi alla data evento eliminazione.";
                ret = false;
            }
            return ret;
        }

        public static bool ALL_VerificaRequisitoEtaPerTipoContributivo(GestionePensione.DatiPensione datiPensioneDB, GestionePensione.DatiPensione datiPensioneUI,
            DateTime? dataNascita, char? sesso, string tipoSettimaneBeneficio, out bool isWarning, out string messaggioVideo)
        {
            messaggioVideo = string.Empty;
            isWarning = false;

            //ENG - Memo 123/2024
            GestioneControlliDinamici.ControlloDinamico ctrlMemo123_2024 = null;
            GestioneControlliDinamici.GetControlloDinamicoByNomeControllo("AbilitazioneRIC_TRFMemo123_2024", out ctrlMemo123_2024);

            //ENG - Memo 123/2024
            GestioneControlliDinamici.ControlloDinamico ctrlMemo123_2024OpzioneContrib = null;
            GestioneControlliDinamici.GetControlloDinamicoByNomeControllo("AbilitazioneRIC_TRFMemo123_2024OpzioneContrib", out ctrlMemo123_2024OpzioneContrib);

            if ((!Utility.IsDomandaTipoContributivo(datiPensioneDB, null, null) && !Utility.isDomandaVecchiaiaTrasformazioneAOICalcoloContributivo(datiPensioneDB)) || (Utility.IsDomandaAnticipataFlessibileOpzioneContributivo(datiPensioneDB) || (!Utility.IsRicostituzione(datiPensioneDB.Gruppo) && !Utility.IsRiaperturaDomanda(datiPensioneDB.Id) && (Utility.IsDomandaAnticipataFlessibileLeggeBilancio2024(datiPensioneDB) || Utility.IsDomandaAnticipataFlessibileOpzioneContributivoLeggeBilancio2024(datiPensioneDB))) ||
                 ((Utility.IsRicostituzione(datiPensioneDB.Gruppo) || Utility.IsRiaperturaDomanda(datiPensioneDB.Id)) && ((ctrlMemo123_2024 != null && ctrlMemo123_2024.ValoreControllo == "SI" && Utility.IsDomandaAnticipataFlessibileLeggeBilancio2024(datiPensioneDB)) ||
                 (ctrlMemo123_2024OpzioneContrib != null && ctrlMemo123_2024OpzioneContrib.ValoreControllo == "SI" && Utility.IsDomandaAnticipataFlessibileOpzioneContributivoLeggeBilancio2024(datiPensioneDB)))) || Utility.IsDomandaVOAUTAnticipataFlessibileLeggeBilancio2024FiltroGSE(datiPensioneDB)))
                return true;

            Utility.TipoFondo? tipoFondo = Utility.GetTipoFondoByCategoria(datiPensioneDB.IndConvInt, datiPensioneDB.Gestione, datiPensioneDB.SiglaCategoria);
            Utility.TipoAppartenenza? tipoAppartenenza = Utility.GetTipoAppartenenza(datiPensioneDB.IndConvInt, datiPensioneDB.Gestione);
            bool isRiaperturaDomanda = Utility.IsRiaperturaDomanda(datiPensioneDB.Id);
            int sconto = 0;
            //se la scelta lavoratrici madri è pari a 1 (anticipo età) applico sconto di 4 mesi per ogni figlio
            if (sesso.GetValueOrDefault() == 'F' && datiPensioneUI.SceltaLavMadri.GetValueOrDefault() == 1)
            {
                sconto = 4 * datiPensioneUI.NumeroFigli.GetValueOrDefault();
                if (sconto > 12)
                    sconto = 12;
                DateTime DataPerfReq = (datiPensioneUI.DataPerfezionamentoRequisiti.Value != null ? datiPensioneUI.DataPerfezionamentoRequisiti.Value : new DateTime(1900, 1, 1));
                if (datiPensioneUI.NumeroFigli > 3 && checkMemo228_2025(datiPensioneDB) && Utility.DataStrettamenteSuccessivaA(DataPerfReq, new DateTime(2024, 12, 31)))
                    sconto = 4 * datiPensioneUI.NumeroFigli.GetValueOrDefault();
            }
            //ENG - Memo 166/2023
            if ((Utility.IsDomandaTipoContributivo(datiPensioneDB, false, false) || Utility.isDomandaVecchiaiaTrasformazioneAOICalcoloContributivo(datiPensioneDB)) &&
                datiPensioneUI.DataPerfezionamentoRequisiti.HasValue)
            {
                if (tipoAppartenenza.HasValue && tipoAppartenenza.Value == Utility.TipoAppartenenza.FS && !Utility.IsCTPSDocenti(datiPensioneDB.Gestione, datiPensioneDB.Fondo))
                {
                    DateTime dataPerfReq = new DateTime(datiPensioneUI.DataPerfezionamentoRequisiti.Value.Year, datiPensioneUI.DataPerfezionamentoRequisiti.Value.Month, 1);
                    if ((tipoFondo.HasValue && tipoFondo == Utility.TipoFondo.FS || tipoFondo == Utility.TipoFondo.PT) ||
                            Utility.IsDomandaINPDAP(datiPensioneDB.Gestione))
                        dataPerfReq = datiPensioneUI.DataPerfezionamentoRequisiti.Value;
                    if (!Utility.DataStrettamenteSuccessivaA(datiPensioneUI.DecorrenzaOriginaria.GetValueOrDefault(), dataPerfReq))
                    {
                        messaggioVideo = "La decorrenza originaria non può essere inferiore o uguale alla data perfezionamento requisito";
                        return false;
                    }
                }

                Utility.TipoUnicarpe tipoUnicarpe = Utility.IsDomandaUnicarpe(datiPensioneDB, true);
                if (tipoUnicarpe != Utility.TipoUnicarpe.Automatica &&
                    !GestioneBypassControllo.CheckAndLockBypassControlloByNomeBypass(datiPensioneDB, GestioneBypassControllo.NomeBypass.Requisito_Eta.REQUISITO_ETA))
                {
                    if (!ALL_VerificaRequisitoEtaVecchiaiaContributivoPuro(datiPensioneDB, datiPensioneUI, dataNascita, sesso, tipoSettimaneBeneficio, sconto, false, out messaggioVideo))
                        return false;
                    //Se controllo senza anticipo funziona regolarmente setto Warning
                    if (!isRiaperturaDomanda)
                    {
                        if (ALL_VerificaRequisitoEtaVecchiaiaContributivoPuro(datiPensioneDB, datiPensioneUI, dataNascita, sesso, tipoSettimaneBeneficio, sconto, true, out messaggioVideo))
                            isWarning = true;
                        else
                            messaggioVideo = string.Empty;
                    }
                }
            }
            else if (Utility.IsDomandaTipoContributivo(datiPensioneDB, true, false) &&
                datiPensioneUI.DataPerfezionamentoRequisiti.HasValue)
            {
                Utility.TipoUnicarpe tipoUnicarpe = Utility.IsDomandaUnicarpe(datiPensioneDB, true);
                if (tipoUnicarpe != Utility.TipoUnicarpe.Automatica)
                {
                    if (Utility.DataStrettamenteSuccessivaA(datiPensioneUI.DataPerfezionamentoRequisiti.Value, new DateTime(2011, 12, 31)))
                    {
                        //DATA MAGGIORE AL 31/12/2011
                        int reqAA = 0;
                        int reqMM = 0;
                        GestioneDecodifica.GetCtrlRequisitoEta_Anticipo(datiPensioneUI.DataPerfezionamentoRequisiti.Value, out reqAA, out reqMM);
                        if (!Utility.IsDomandaVOAUTAnticipataTipoContributivoFiltroGSE(datiPensioneDB) && Utility.DataStrettamenteSuccessivaA(dataNascita.Value.AddYears(reqAA).AddMonths(reqMM).AddMonths(-sconto), datiPensioneUI.DataPerfezionamentoRequisiti.Value))
                        {
                            if (sconto > 0)
                            {
                                reqMM -= sconto;
                                while (reqMM < 0)
                                {
                                    reqAA -= 1;
                                    reqMM += 12;
                                }
                            }

                            messaggioVideo = string.Format(
                                "Alla data perfezionamento requisiti ({0:dd/MM/yyyy}) non è stato raggiunto il requisito di età di {1} AA e {2} MM",
                                datiPensioneUI.DataPerfezionamentoRequisiti.Value, reqAA, reqMM
                            );
                            return false;
                        }
                    }
                    else
                    {
                        messaggioVideo = "La Data Perfezionamento Requisiti deve essere maggiore al 31/12/2011";
                        return false;
                    }
                }
            }
            else if (Utility.IsDomandaTipoContributivo(datiPensioneDB, false, true) &&
                datiPensioneUI.DataPerfezionamentoRequisiti.HasValue)
            {
                if (tipoAppartenenza.HasValue && tipoAppartenenza.Value == Utility.TipoAppartenenza.FS && !Utility.IsCTPSDocenti(datiPensioneDB.Gestione, datiPensioneDB.Fondo))
                {
                    DateTime dataPerfReq = new DateTime(datiPensioneUI.DataPerfezionamentoRequisiti.Value.Year, datiPensioneUI.DataPerfezionamentoRequisiti.Value.Month, 1);
                    if ((tipoFondo.HasValue && tipoFondo == Utility.TipoFondo.FS || tipoFondo == Utility.TipoFondo.PT) ||
                            Utility.IsDomandaINPDAP(datiPensioneDB.Gestione))
                        dataPerfReq = datiPensioneUI.DataPerfezionamentoRequisiti.Value;
                    if (!Utility.DataStrettamenteSuccessivaA(datiPensioneUI.DecorrenzaOriginaria.GetValueOrDefault(), dataPerfReq))
                    {
                        messaggioVideo = "La decorrenza originaria non può essere inferiore o uguale alla data perfezionamento requisito";
                        return false;
                    }
                }

                Utility.TipoUnicarpe tipoUnicarpe = Utility.IsDomandaUnicarpe(datiPensioneDB, true);
                if (tipoUnicarpe != Utility.TipoUnicarpe.Automatica)
                {
                    if (!ALL_VerificaRequisitoEtaVecchiaiaContributivoOpzione(datiPensioneDB, datiPensioneUI, dataNascita, sesso, tipoSettimaneBeneficio, sconto, false, out messaggioVideo))
                        return false;
                    if (!isRiaperturaDomanda)
                    {
                        //Se controllo senza anticipo funziona regolarmente setto Warning
                        if (ALL_VerificaRequisitoEtaVecchiaiaContributivoOpzione(datiPensioneDB, datiPensioneUI, dataNascita, sesso, tipoSettimaneBeneficio, sconto, true, out messaggioVideo))
                            isWarning = true;
                        else
                            messaggioVideo = string.Empty;
                    }
                }
            }
            else if (Utility.IsDomandaTipoContributivo(datiPensioneDB, true, true))
            {
                if (Utility.IsDomandaAnticipataConOpzionePL(datiPensioneDB))
                {
                    Utility.TipoUnicarpe tipoUnicarpe = Utility.IsDomandaUnicarpe(datiPensioneDB, true);
                    if (tipoUnicarpe != Utility.TipoUnicarpe.Automatica)
                    {
                        if (datiPensioneUI.DataPerfezionamentoRequisiti.HasValue && !Utility.DataSuccessivaA(datiPensioneUI.DataPerfezionamentoRequisiti.Value, new DateTime(2012, 01, 01)))
                        {
                            messaggioVideo = "Al momento è possibile lavorare le domande di pensione anticipata con opzione al contributivo per soggetti con data perfezionamento del requisito >= 01/01/2012. Inviare una mail a Supporto.IVS@inps.it.";
                            return false;
                        }

                        if (datiPensioneDB.DataOpzione.HasValue && !Utility.DataSuccessivaA(datiPensioneDB.DataPresentazioneDomanda, datiPensioneDB.DataOpzione.Value))
                        {
                            messaggioVideo = "Attenzione: la data di presentazione della domanda deve essere uguale o successiva alla data di opzione";
                            return false;
                        }
                    }
                }
            }
            //Domanda di tipo non contributivo oppure con data di perfezionamento non valorizzata
            return true;
        }

        private static bool ALL_VerificaRequisitoEtaVecchiaiaContributivoPuro(GestionePensione.DatiPensione datiPensioneDB, GestionePensione.DatiPensione datiPensioneUI,
            DateTime? dataNascita, char? sesso, string tipoSettimaneBeneficio, int sconto, bool isFlussoWarning, out string messaggioVideo)
        {
            messaggioVideo = string.Empty;
            Utility.TipoAppartenenza? tipoAppartenenza = Utility.GetTipoAppartenenza(datiPensioneDB.IndConvInt, datiPensioneDB.Gestione);
            bool isRiaperturaDomanda = Utility.IsRiaperturaDomanda(datiPensioneDB.Id);
            DateTime dataRiferimento = datiPensioneUI.DataPerfezionamentoRequisiti.Value;

            if (isFlussoWarning)
            {
                if (sconto == 0)
                    return false;
                dataRiferimento = new DateTime(datiPensioneUI.DecorrenzaOriginaria.Value.Year, datiPensioneUI.DecorrenzaOriginaria.Value.Month, 1).AddDays(-1);
                sconto = 0;
            }

            if (Utility.DataStrettamenteSuccessivaA(dataRiferimento, new DateTime(2007, 12, 31)))
            {
                //DATA MAGGIORE AL 31/12/2007
                if (Utility.DataStrettamenteSuccessivaA(dataRiferimento, new DateTime(2011, 12, 31)))
                {
                    if (!ALL_ControlsRequisitoEta(datiPensioneDB, tipoAppartenenza, isRiaperturaDomanda, datiPensioneUI, dataNascita, sesso,
                        null, null, null, tipoSettimaneBeneficio, isFlussoWarning ? dataRiferimento : (DateTime?)null, null, out messaggioVideo))
                    {
                        return false;
                    }
                }
                else
                {
                    //DATA MAGGIORE AL 31/12/2007 MA MINORE O UGUALE al 31/12/11

                    //Il titolare deve avere un’età anagrafica maggiore o uguale a 60 anni (F) o 65 anni (M)
                    if (sesso == 'F')
                    {
                        if (Utility.DataStrettamenteSuccessivaA(dataNascita.Value.AddYears(60).AddMonths(-sconto), dataRiferimento))
                        {
                            Utility.DifferenzaDateTime requisitoEta = new Utility.DifferenzaDateTime(60, -sconto, true);
                            messaggioVideo = string.Format("Il titolare deve avere un’età anagrafica maggiore o uguale a {0} alla data di perfezionamento del requisito", requisitoEta);
                            return false;
                        }
                    }
                    else if (sesso == 'M')
                    {
                        if (Utility.DataStrettamenteSuccessivaA(dataNascita.Value.AddYears(65), dataRiferimento))
                        {
                            messaggioVideo = "Il titolare deve avere un’età anagrafica maggiore o uguale 65 anni alla data di perfezionamento del requisito";
                            return false;
                        }
                    }
                }
            }
            else
            {
                //DATA MINORE O UGUALE A 31/12/2007

                //Il titolare deve avere un’età anagrafica maggiore o uguale a 57 anni (per entrambi i sessi)
                if (Utility.DataStrettamenteSuccessivaA(dataNascita.Value.AddYears(57).AddMonths(-sconto), dataRiferimento))
                {
                    Utility.DifferenzaDateTime requisitoEta = new Utility.DifferenzaDateTime(57, -sconto, true);
                    messaggioVideo = string.Format("Il titolare deve avere un’età anagrafica maggiore o uguale a {0} alla data di perfezionamento del requisito", requisitoEta);
                    return false;
                }
            }
            return true;
        }

        private static bool ALL_VerificaRequisitoEtaVecchiaiaContributivoOpzioneOld(GestionePensione.DatiPensione datiPensioneDB, GestionePensione.DatiPensione datiPensioneUI,
            DateTime? dataNascita, char? sesso, string tipoSettimaneBeneficio, int sconto, bool isFlussoWarning, out string messaggioVideo)
        {
            messaggioVideo = string.Empty;
            Utility.TipoAppartenenza? tipoAppartenenza = Utility.GetTipoAppartenenza(datiPensioneDB.IndConvInt, datiPensioneDB.Gestione);
            bool isRiaperturaDomanda = Utility.IsRiaperturaDomanda(datiPensioneDB.Id);

            DateTime dataRiferimento;
            string nomeDataRiferimento;
            Utility.GetDataRiferimento(datiPensioneDB.DataRaggiungimentoOpzione, datiPensioneUI.DataPerfezionamentoRequisiti, out dataRiferimento, out nomeDataRiferimento);
            if (isFlussoWarning)
            {
                if (sconto == 0)
                    return false;
                nomeDataRiferimento = "decorrenza";
                dataRiferimento = new DateTime(datiPensioneUI.DecorrenzaOriginaria.Value.Year, datiPensioneUI.DecorrenzaOriginaria.Value.Month, 1).AddDays(-1);
                sconto = 0;
            }

            if (Utility.DataStrettamenteSuccessivaA(dataRiferimento, new DateTime(2007, 12, 31)))
            {
                //DATA MAGGIORE AL 31/12/2007
                if (Utility.DataStrettamenteSuccessivaA(dataRiferimento, new DateTime(2011, 12, 31)))
                {
                    //DATA MAGGIORE AL 31/12/2011

                    //Il titolare deve avere un’età anagrafica maggiore o uguale a 
                    //60 anni (F) - (per il fondo volo 58 anni)
                    //o 65 anni (M) - (per il fondo volo 62 anni)
                    //Il “Numero Settimane” deve essere maggiore o uguale a 1040
                    //TODO: deve essere cambiato con la  tabella generale deALL_ControlsRequisitoEtal requisito di età per le vecchiaia(CtrlRequisitoEta)
                    //messaggioVideo = string.Format("Sostituire controllo con ALL_ControlsRequisitoEta");
                    //return false;

                    if (!ALL_ControlsRequisitoEta(datiPensioneDB, tipoAppartenenza, isRiaperturaDomanda, datiPensioneUI, dataNascita, sesso,
                        null, null, null, tipoSettimaneBeneficio, isFlussoWarning ? dataRiferimento : (DateTime?)null, null, out messaggioVideo))
                    {
                        return false;
                    }
                }
                else
                {
                    //DATA MAGGIORE AL 31/12/2007 MA MINORE O UGUALE al 31/12/11

                    //Il titolare deve avere un’età anagrafica maggiore o uguale a 60 anni (F) o 65 anni (M)
                    if (sesso == 'F')
                    {
                        if (Utility.DataStrettamenteSuccessivaA(dataNascita.Value.AddYears(60).AddMonths(-sconto), dataRiferimento))
                        {
                            Utility.DifferenzaDateTime requisitoEta = new Utility.DifferenzaDateTime(60, -sconto, true);
                            messaggioVideo = string.Format("Il titolare deve avere un’età anagrafica maggiore o uguale a {1} alla data di {0}", nomeDataRiferimento, requisitoEta);
                            return false;
                        }
                    }
                    else if (sesso == 'M')
                    {
                        if (Utility.DataStrettamenteSuccessivaA(dataNascita.Value.AddYears(65), dataRiferimento))
                        {
                            messaggioVideo = string.Format("Il titolare deve avere un’età anagrafica maggiore o uguale 65 anni alla data di {0}", nomeDataRiferimento);
                            return false;
                        }
                    }
                }
            }
            else
            {
                //DATA MINORE O UGUALE A 31/12/2007

                //Il titolare deve avere un’età anagrafica maggiore o uguale a 57 anni (per entrambi i sessi)
                if (Utility.DataStrettamenteSuccessivaA(dataNascita.Value.AddYears(57).AddMonths(-sconto), dataRiferimento))
                {
                    Utility.DifferenzaDateTime requisitoEta = new Utility.DifferenzaDateTime(57, -sconto, true);
                    messaggioVideo = string.Format("Il titolare deve avere un’età anagrafica maggiore o uguale a {1} alla data di {0}", nomeDataRiferimento, requisitoEta);
                    return false;
                }
            }
            return true;
        }

        private static bool ALL_VerificaRequisitoEtaVecchiaiaContributivoOpzione(GestionePensione.DatiPensione datiPensioneDB, GestionePensione.DatiPensione datiPensioneUI,
            DateTime? dataNascita, char? sesso, string tipoSettimaneBeneficio, int sconto, bool isFlussoWarning, out string messaggioVideo)
        {
            messaggioVideo = string.Empty;

            if (!Utility.IsDecPensioneValidaPerVecchOpzione(datiPensioneUI.DecorrenzaOriginaria, datiPensioneDB.DataRaggiungimentoOpzione, datiPensioneDB.DataOpzione, out messaggioVideo))
                return false;

            DateTime dataRiferimento;
            string nomeDataRiferimento;

            if (isFlussoWarning)
            {
                if (sconto == 0)
                    return false;
                nomeDataRiferimento = "decorrenza";
                dataRiferimento = new DateTime(datiPensioneUI.DecorrenzaOriginaria.Value.Year, datiPensioneUI.DecorrenzaOriginaria.Value.Month, 1).AddDays(-1);
                sconto = 0;
            }
            else
            {
                nomeDataRiferimento = "perfezionamento del requisito";
                dataRiferimento = datiPensioneUI.DataPerfezionamentoRequisiti.GetValueOrDefault();
            }

            if (!ALL_VerificaRequisitoEtaVecchiaiaContributivoOpzione_Base(datiPensioneDB, datiPensioneUI, dataNascita, sesso, tipoSettimaneBeneficio,
                sconto, isFlussoWarning, dataRiferimento, nomeDataRiferimento, out messaggioVideo))
                return false;

            //Modifica Contributivo v4.6
            if (isFlussoWarning) //|| Utility.DataStrettamenteSuccessivaA(datiPensioneUI.DataPerfezionamentoRequisiti.GetValueOrDefault(), new DateTime(2011, 12, 31)) ||
                //Utility.DataStrettamenteSuccessivaA(datiPensioneDB.DataRaggiungimentoOpzione.GetValueOrDefault(), new DateTime(2011, 12, 31)))
                return true;

            Utility.GetDataRiferimento(datiPensioneDB.DataRaggiungimentoOpzione, datiPensioneUI.DataPerfezionamentoRequisiti, out dataRiferimento, out nomeDataRiferimento);

            if (!ALL_VerificaRequisitoEtaVecchiaiaContributivoOpzione_Base(datiPensioneDB, datiPensioneUI, dataNascita, sesso, tipoSettimaneBeneficio,
                sconto, isFlussoWarning, dataRiferimento, nomeDataRiferimento, out messaggioVideo))
                return false;

            return true;
        }

        private static bool ALL_VerificaRequisitoEtaVecchiaiaContributivoOpzione_Base(GestionePensione.DatiPensione datiPensioneDB,
            GestionePensione.DatiPensione datiPensioneUI,
            DateTime? dataNascita, char? sesso, string tipoSettimaneBeneficio, int sconto, bool isFlussoWarning,
            DateTime dataRiferimento, string nomeDataRiferimento, out string messaggioVideo)
        {
            messaggioVideo = string.Empty;
            Utility.TipoAppartenenza? tipoAppartenenza = Utility.GetTipoAppartenenza(datiPensioneDB.IndConvInt, datiPensioneDB.Gestione);
            bool isRiaperturaDomanda = Utility.IsRiaperturaDomanda(datiPensioneDB.Id);
            DateTime dataPerfezionamentoRequisiti = datiPensioneUI.DataPerfezionamentoRequisiti.GetValueOrDefault();

            if (Utility.DataStrettamenteSuccessivaA(dataRiferimento, new DateTime(2007, 12, 31)))
            {
                //DATA MAGGIORE AL 31/12/2007
                if (Utility.DataStrettamenteSuccessivaA(dataRiferimento, new DateTime(2011, 12, 31)))
                {
                    //Modifica Contributivo v4.7
                    if (!Utility.DataStrettamenteSuccessivaA(dataPerfezionamentoRequisiti, new DateTime(2011, 12, 31)))
                    {
                        messaggioVideo = string.Format("La data di perfezionamento dei requisiti deve essere maggiore o uguale al 2012");
                        return false;
                    }
                    //DATA MAGGIORE AL 31/12/2011

                    //Il titolare deve avere un’età anagrafica maggiore o uguale a 
                    //60 anni (F) - (per il fondo volo 58 anni)
                    //o 65 anni (M) - (per il fondo volo 62 anni)
                    //Il “Numero Settimane” deve essere maggiore o uguale a 1040
                    //TODO: deve essere cambiato con la  tabella generale deALL_ControlsRequisitoEtal requisito di età per le vecchiaia(CtrlRequisitoEta)
                    //messaggioVideo = string.Format("Sostituire controllo con ALL_ControlsRequisitoEta");
                    //return false;

                    if (!ALL_ControlsRequisitoEta(datiPensioneDB, tipoAppartenenza, isRiaperturaDomanda, datiPensioneUI, dataNascita, sesso,
                        null, null, null, tipoSettimaneBeneficio, isFlussoWarning ? dataRiferimento : (DateTime?)null, null, out messaggioVideo))
                    {
                        return false;
                    }
                }
                else
                {
                    //DATA MAGGIORE AL 31/12/2007 MA MINORE O UGUALE al 31/12/11

                    //Il titolare deve avere un’età anagrafica maggiore o uguale a 60 anni (F) o 65 anni (M)
                    if (sesso == 'F')
                    {
                        //Modifica Contributivo v4.6
                        if (Utility.DataStrettamenteSuccessivaA(dataNascita.Value.AddYears(60).AddMonths(-sconto), dataPerfezionamentoRequisiti))
                        {
                            Utility.DifferenzaDateTime requisitoEta = new Utility.DifferenzaDateTime(60, -sconto, true);
                            messaggioVideo = string.Format("Il titolare deve avere un’età anagrafica maggiore o uguale a {1} alla data di {0}", nomeDataRiferimento, requisitoEta);
                            return false;
                        }
                    }
                    else if (sesso == 'M')
                    {
                        //Modifica Contributivo v4.6
                        if (Utility.DataStrettamenteSuccessivaA(dataNascita.Value.AddYears(65), dataPerfezionamentoRequisiti))
                        {
                            messaggioVideo = string.Format("Il titolare deve avere un’età anagrafica maggiore o uguale 65 anni alla data di {0}", nomeDataRiferimento);
                            return false;
                        }
                    }
                }
            }
            else
            {
                //DATA MINORE O UGUALE A 31/12/2007

                //Modifica Contributivo v4.6
                //Il titolare deve avere un’età anagrafica maggiore o uguale a 57 anni (per entrambi i sessi)
                if (Utility.DataStrettamenteSuccessivaA(dataNascita.Value.AddYears(57).AddMonths(-sconto), dataPerfezionamentoRequisiti))
                {
                    Utility.DifferenzaDateTime requisitoEta = new Utility.DifferenzaDateTime(57, -sconto, true);
                    messaggioVideo = string.Format("Il titolare deve avere un’età anagrafica maggiore o uguale a {1} alla data di {0}", nomeDataRiferimento, requisitoEta);
                    return false;
                }
            }
            return true;
        }

        public static bool ALL_VerificaDataPerfezionamentoPerPensioneTipoContributivo(GestionePensione.DatiPensione datiPensione,
            GestioneAnagrafica.DatiAnagrafici datiAnagraficiTitolare, int numSettimane, out string messaggioVideo)
        {
            messaggioVideo = string.Empty;

            GestioneControlliDinamici.ControlloDinamico ctrl28_2024 = null;
            GestioneControlliDinamici.GetControlloDinamicoByNomeControllo("AbilitazioneMemo28_2024", out ctrl28_2024);

            //ENG - Memo 123/2024
            GestioneControlliDinamici.ControlloDinamico ctrlMemo123_2024 = null;
            GestioneControlliDinamici.GetControlloDinamicoByNomeControllo("AbilitazioneRIC_TRFMemo123_2024", out ctrlMemo123_2024);

            //ENG - Memo 123/2024
            GestioneControlliDinamici.ControlloDinamico ctrlMemo123_2024OpzioneContrib = null;
            GestioneControlliDinamici.GetControlloDinamicoByNomeControllo("AbilitazioneRIC_TRFMemo123_2024OpzioneContrib", out ctrlMemo123_2024OpzioneContrib);

            if ((!Utility.IsDomandaTipoContributivo(datiPensione, null, null) && !(Utility.isDomandaVecchiaiaTrasformazioneAOICalcoloContributivo(datiPensione) && !Utility.IsDomandaAUT(datiPensione)) && !(Utility.IsDomandaVOCUM(datiPensione.SiglaCategoria) && !Utility.IsRiaperturaDomanda(datiPensione.Id) && datiPensione.IsCumuloAutomatica.GetValueOrDefault() &&
                    datiPensione.Gruppo == "0001" && datiPensione.Prodotto == "0002" && datiPensione.Tipo == "0017")) || (Utility.IsDomandaAnticipataFlessibileOpzioneContributivo(datiPensione) ||
                 (!Utility.IsRicostituzione(datiPensione.Gruppo) && !Utility.IsRiaperturaDomanda(datiPensione.Id) && (Utility.IsDomandaAnticipataFlessibileLeggeBilancio2024(datiPensione) || Utility.IsDomandaAnticipataFlessibileOpzioneContributivoLeggeBilancio2024(datiPensione))) ||
                  ((Utility.IsRicostituzione(datiPensione.Gruppo) || Utility.IsRiaperturaDomanda(datiPensione.Id)) && ((ctrlMemo123_2024 != null && ctrlMemo123_2024.ValoreControllo == "SI" && Utility.IsDomandaAnticipataFlessibileLeggeBilancio2024(datiPensione)) || (ctrlMemo123_2024OpzioneContrib != null && ctrlMemo123_2024OpzioneContrib.ValoreControllo == "SI" && Utility.IsDomandaAnticipataFlessibileOpzioneContributivoLeggeBilancio2024(datiPensione)))) ||
                   Utility.IsDomandaVOAUTAnticipataFlessibileLeggeBilancio2024FiltroGSE(datiPensione)))
                return true;

            Utility.TipoFondo? tipoFondo = Utility.GetTipoFondoByCategoria(datiPensione.IndConvInt, datiPensione.Gestione, datiPensione.SiglaCategoria);
            Utility.TipoAppartenenza? tipoAppartenenza = Utility.GetTipoAppartenenza(datiPensione.IndConvInt, datiPensione.Gestione);
            string messaggioCI = string.Empty;
            int sconto = 0;
            //se la scelta lavoratrici madri è pari a 1 (anticipo età) applico sconto di 4 mesi per ogni figlio
            if (datiAnagraficiTitolare.Sesso.GetValueOrDefault() == 'F' && datiPensione.SceltaLavMadri.GetValueOrDefault() == 1)
            {
                sconto = 4 * datiPensione.NumeroFigli.GetValueOrDefault();
                if (sconto > 12)
                    sconto = 12;
                DateTime DataPerfReq = (datiPensione.DataPerfezionamentoRequisiti.Value != null ? datiPensione.DataPerfezionamentoRequisiti.Value : new DateTime(1900, 1, 1));
                if (datiPensione.NumeroFigli > 3 && checkMemo228_2025(datiPensione) && Utility.DataStrettamenteSuccessivaA(DataPerfReq, new DateTime(2024, 12, 31)))
                    sconto = 4 * datiPensione.NumeroFigli.GetValueOrDefault();
            }

            if ((Utility.IsDomandaTipoContributivo(datiPensione, false, false) || Utility.isDomandaVecchiaiaTrasformazioneAOICalcoloContributivo(datiPensione) ||
                (Utility.IsDomandaVOCUM(datiPensione.SiglaCategoria) && !Utility.IsRiaperturaDomanda(datiPensione.Id) && datiPensione.IsCumuloAutomatica.GetValueOrDefault() &&
                datiPensione.Gruppo == "0001" && datiPensione.Prodotto == "0002" && datiPensione.Tipo == "0017")) &&
                datiPensione.DataPerfezionamentoRequisiti.HasValue)
            {
                Utility.TipoUnicarpe tipoUnicarpe = Utility.IsDomandaUnicarpe(datiPensione, true);
                if (tipoAppartenenza.GetValueOrDefault() == Utility.TipoAppartenenza.CI) messaggioCI = "italiane ed estere per il diritto ";
                //Bypass per automatiche e per AGO con filtro ERI
                if (tipoUnicarpe != Utility.TipoUnicarpe.Automatica && !(tipoAppartenenza.GetValueOrDefault() == Utility.TipoAppartenenza.AGO && datiPensione.GetFiltro() == "ERI"))
                {
                    if (GestioneBypassControllo.CheckAndLockBypassControlloByNomeBypass(datiPensione, GestioneBypassControllo.NomeBypass.LiquidazionePensione_Assicurativi_AGO.NUM_SET_CONTR))
                        return true;
                    if (Utility.DataStrettamenteSuccessivaA(datiPensione.DataPerfezionamentoRequisiti.Value, new DateTime(2007, 12, 31)))
                    {
                        //DATA MAGGIORE AL 31/12/2007
                        if (Utility.DataStrettamenteSuccessivaA(datiPensione.DataPerfezionamentoRequisiti.Value, new DateTime(2011, 12, 31)))
                        {
                            //DATA MAGGIORE AL 31/12/2011

                            //Il “Numero Settimane” deve essere maggiore o uguale a 1040
                            //oppure
                            //Il “Numero Settimane” deve essere maggiore o uguale a 260int reqAA = 0;
                            int reqMM = 0;
                            int reqAA = 0;
                            GestioneDecodifica.GetCtrlRequisitoEta_Avanzato(datiPensione.DataPerfezionamentoRequisiti.Value, tipoFondo == Utility.TipoFondo.VL ? datiPensione.GetCodCategoria() : null, null, tipoAppartenenza.ToString(), Utility.isDomandaVecchiaiaTrasformazioneAOICalcoloContributivo(datiPensione) ? "0017" : datiPensione.Tipo, out reqAA, out reqMM);

                            if (Utility.DataStrettamenteSuccessivaA(datiAnagraficiTitolare.DataNascita.Value.AddYears(reqAA).AddMonths(reqMM).AddMonths(-sconto), datiPensione.DataPerfezionamentoRequisiti.Value))
                            {
                                if (sconto > 0)
                                {
                                    reqMM -= sconto;
                                    if (reqMM < 0)
                                    {
                                        reqAA -= 1;
                                        reqMM += 12;
                                    }
                                }
                                string messaggioBase = string.Empty;
                                //ENG - messaggio modificato per fondi FS, PT e GDP con "Aspettative di vita"
                                if (tipoAppartenenza.GetValueOrDefault() == Utility.TipoAppartenenza.FS &&
                                    ((tipoFondo.HasValue && (tipoFondo == Utility.TipoFondo.FS || tipoFondo == Utility.TipoFondo.PT)) || Utility.IsDomandaINPDAP(datiPensione.Gestione)))
                                {
                                    messaggioBase = string.Format("“Numero Settimane” " + messaggioCI + "deve essere maggiore o uguale a 1040 in quanto non viene soddisfatto il requisito anagrafico dei {0} anni + aspettative di vita", reqAA);
                                }
                                else if (!Utility.IsDomandaVOAUTVecchiaiaTipoContributivoFiltroGSE(datiPensione))
                                {
                                    messaggioBase = string.Format("“Numero Settimane” " + messaggioCI + "deve essere maggiore o uguale a 1040 in quanto non viene soddisfatto il requisito anagrafico dei {0} anni e {1} mesi", reqAA, reqMM);
                                }

                                if (!Utility.IsDomandaVOAUTVecchiaiaTipoContributivoFiltroGSE(datiPensione))
                                {
                                    if (datiAnagraficiTitolare.Sesso == 'F')
                                    {
                                        if (tipoFondo == Utility.TipoFondo.VL)
                                        {
                                            if (!(numSettimane >= 1040))
                                            {
                                                messaggioVideo = messaggioBase;
                                                return false;
                                            }
                                        }
                                        else
                                        {
                                            if (!(numSettimane >= 1040))
                                            {
                                                messaggioVideo = messaggioBase;
                                                return false;
                                            }
                                        }
                                    }
                                    else if (datiAnagraficiTitolare.Sesso == 'M')
                                    {
                                        if (tipoFondo == Utility.TipoFondo.VL)
                                        {
                                            if (!(numSettimane >= 1040))
                                            {
                                                messaggioVideo = messaggioBase;
                                                return false;
                                            }
                                        }
                                        else
                                        {
                                            if (!(numSettimane >= 1040))
                                            {
                                                messaggioVideo = messaggioBase;
                                                return false;
                                            }
                                        }
                                    }
                                }
                            }
                            else
                            {
                                if (!(numSettimane >= 260) && !Utility.IsDomandaVOAUTVecchiaiaTipoContributivoFiltroGSE(datiPensione))
                                {
                                    messaggioVideo = "Il “Numero Settimane” " + messaggioCI + "deve essere maggiore o uguale a 260";
                                    return false;
                                }
                            }
                        }
                        else
                        {
                            //DATA MAGGIORE AL 31/12/2007 MA MINORE O UGUALE al 31/12/11

                            //Il “Numero Settimane” deve essere maggiore o uguale a 260
                            if (datiAnagraficiTitolare.Sesso == 'F')
                            {
                                if (!(numSettimane >= 260))
                                {
                                    messaggioVideo = "Il “Numero Settimane” " + messaggioCI + "deve essere maggiore o uguale a 260";
                                    return false;
                                }
                            }
                            else if (datiAnagraficiTitolare.Sesso == 'M')
                            {
                                if (!(numSettimane >= 260))
                                {
                                    messaggioVideo = "Il “Numero Settimane” " + messaggioCI + "deve essere maggiore o uguale a 260";
                                    return false;
                                }
                            }
                        }
                    }
                    else
                    {
                        //DATA MINORE O UGUALE A 31/12/2007

                        //Il “Numero Settimane” deve essere maggiore o uguale a 260
                        if (!(numSettimane >= 260))
                        {
                            messaggioVideo = "Il “Numero Settimane” " + messaggioCI + "deve essere maggiore o uguale a 260";
                            return false;
                        }
                    }
                }
            }
            else if ((Utility.IsDomandaTipoContributivo(datiPensione, true, false) || (tipoAppartenenza.GetValueOrDefault() == Utility.TipoAppartenenza.CI && Utility.IsDomandaRicAnticipataContributivaPura(datiPensione, 0))) &&
               datiPensione.DataPerfezionamentoRequisiti.HasValue)
            {
                Utility.TipoUnicarpe tipoUnicarpe = Utility.IsDomandaUnicarpe(datiPensione, true);
                if (tipoAppartenenza.GetValueOrDefault() == Utility.TipoAppartenenza.CI) messaggioCI = "italiane ed estere per il diritto ";
                if (tipoUnicarpe != Utility.TipoUnicarpe.Automatica)
                {
                    if (GestioneBypassControllo.CheckAndLockBypassControlloByNomeBypass(datiPensione, GestioneBypassControllo.NomeBypass.LiquidazionePensione_Assicurativi_AGO.NUM_SET_CONTR))
                        return true;

                    //ENG - memo 28/2024
                    if (ctrl28_2024 != null && !String.IsNullOrEmpty(ctrl28_2024.ValoreControllo) && ctrl28_2024.ValoreControllo.ToUpperInvariant() == "SI")
                    {
                        if ((datiPensione.Gruppo == "0001" && datiPensione.Prodotto == "0001" && datiPensione.Tipo == "0017") &&
                            Utility.DataStrettamenteSuccessivaA(datiPensione.DataPerfezionamentoRequisiti.Value, new DateTime(2023, 12, 31)) &&
                            datiAnagraficiTitolare.Sesso == 'F' && datiPensione.SceltaLavMadri.GetValueOrDefault() == 1)
                        {
                            int reqAA = 0;
                            int reqMM = 0;
                            GestioneDecodifica.GetCtrlRequisitoEta_Avanzato(datiPensione.DataPerfezionamentoRequisiti.Value, null, null, tipoAppartenenza.GetValueOrDefault().ToString(), datiPensione.Tipo, out reqAA, out reqMM);
                            Utility.DifferenzaDateTime etaPiuAspettativaDiVita = new Utility.DifferenzaDateTime(reqAA, reqMM - sconto, true);
                            Utility.DifferenzaDateTime etaTitolareAllaDPR = Utility.DifferenzaBetweenDate(datiPensione.DataPerfezionamentoRequisiti.Value, datiAnagraficiTitolare.DataNascita, tipoAppartenenza.GetValueOrDefault());
                            if (etaTitolareAllaDPR < etaPiuAspettativaDiVita)
                            {
                                if (numSettimane < 1040 && !Utility.IsDomandaVOAUTAnticipataTipoContributivoFiltroGSE(datiPensione))
                                {
                                    messaggioVideo = "Il numero settimane deve essere maggiore o uguale di 1040";
                                    return false;
                                }
                            }
                            if (!Utility.DataStrettamenteSuccessivaA(datiPensione.DataPerfezionamentoRequisiti.Value, new DateTime(2011, 12, 31)))
                            {
                                messaggioVideo = "La Data Perfezionamento Requisiti deve essere maggiore al 31/12/2011";
                                return false;
                            }
                        }
                        else
                        {
                            if (Utility.DataStrettamenteSuccessivaA(datiPensione.DataPerfezionamentoRequisiti.Value, new DateTime(2011, 12, 31)))
                            {
                                //DATA MAGGIORE AL 31/12/2011

                                //Il “Numero Settimane” deve essere maggiore o uguale a 1040
                                if (!(numSettimane >= 1040) && !Utility.IsDomandaVOAUTVecchiaiaTipoContributivoFiltroGSE(datiPensione) && !Utility.IsDomandaVOAUTAnticipataTipoContributivoFiltroGSE(datiPensione))
                                {
                                    messaggioVideo = "Il “Numero Settimane” " + messaggioCI + "deve essere maggiore o uguale a 1040";
                                    return false;
                                }
                            }
                            else
                            {
                                messaggioVideo = "La Data Perfezionamento Requisiti deve essere maggiore al 31/12/2011";
                                return false;
                            }
                        }
                    }
                    else
                    {
                        if (Utility.DataStrettamenteSuccessivaA(datiPensione.DataPerfezionamentoRequisiti.Value, new DateTime(2011, 12, 31)))
                        {
                            //DATA MAGGIORE AL 31/12/2011

                            //Il “Numero Settimane” deve essere maggiore o uguale a 1040
                            if (!(numSettimane >= 1040) && !Utility.IsDomandaVOAUTVecchiaiaTipoContributivoFiltroGSE(datiPensione) && !Utility.IsDomandaVOAUTAnticipataTipoContributivoFiltroGSE(datiPensione))
                            {
                                messaggioVideo = "Il “Numero Settimane” " + messaggioCI + "deve essere maggiore o uguale a 1040";
                                return false;
                            }
                        }
                        else
                        {
                            messaggioVideo = "La Data Perfezionamento Requisiti deve essere maggiore al 31/12/2011";
                            return false;
                        }
                    }
                }
            }
            else if (Utility.IsDomandaTipoContributivo(datiPensione, false, true) &&
                datiPensione.DataPerfezionamentoRequisiti.HasValue)
            {
                Utility.TipoUnicarpe tipoUnicarpe = Utility.IsDomandaUnicarpe(datiPensione, true);
                if (tipoUnicarpe != Utility.TipoUnicarpe.Automatica)
                {
                    if (GestioneBypassControllo.CheckAndLockBypassControlloByNomeBypass(datiPensione, GestioneBypassControllo.NomeBypass.LiquidazionePensione_Assicurativi_AGO.NUM_SET_CONTR))
                        return true;
                    DateTime dataRiferimento = datiPensione.DataPerfezionamentoRequisiti.GetValueOrDefault();
                    string nomeDataRiferimento = "perfezionamento del requisito";

                    if (!ALL_VerificaSettimaneVecchiaiaContributivoOpzione(datiPensione, datiAnagraficiTitolare, numSettimane, dataRiferimento, nomeDataRiferimento, out messaggioVideo))
                        return false;

                    if (Utility.DataStrettamenteSuccessivaA(datiPensione.DataPerfezionamentoRequisiti.GetValueOrDefault(), new DateTime(2011, 12, 31)) ||
                        Utility.DataStrettamenteSuccessivaA(datiPensione.DataRaggiungimentoOpzione.GetValueOrDefault(), new DateTime(2011, 12, 31)))
                        return true;

                    Utility.GetDataRiferimento(datiPensione.DataRaggiungimentoOpzione, datiPensione.DataPerfezionamentoRequisiti, out dataRiferimento, out nomeDataRiferimento);

                    if (!ALL_VerificaSettimaneVecchiaiaContributivoOpzione(datiPensione, datiAnagraficiTitolare, numSettimane, dataRiferimento, nomeDataRiferimento, out messaggioVideo))
                        return false;
                }
            }
            else if (Utility.IsDomandaTipoContributivo(datiPensione, true, true) &&
                datiPensione.DataPerfezionamentoRequisiti.HasValue)
            {
                Utility.TipoUnicarpe tipoUnicarpe = Utility.IsDomandaUnicarpe(datiPensione, true);
                if (tipoUnicarpe != Utility.TipoUnicarpe.Automatica)
                {
                    if (GestioneBypassControllo.CheckAndLockBypassControlloByNomeBypass(datiPensione, GestioneBypassControllo.NomeBypass.LiquidazionePensione_Assicurativi_AGO.NUM_SET_CONTR))
                        return true;
                    if (tipoAppartenenza.GetValueOrDefault() == Utility.TipoAppartenenza.CI) messaggioCI = "Non risulta perfezionato il requisito contributivo minimo, considerando le settimane italiane ed estere";
                    if (Utility.DataSuccessivaA(datiPensione.DataPerfezionamentoRequisiti.Value, new DateTime(2012, 01, 01)) ||
                        Utility.DataSuccessivaA(datiPensione.DataRaggiungimentoOpzione.GetValueOrDefault(), new DateTime(2012, 01, 01)))
                    {
                        if (datiAnagraficiTitolare.Sesso.GetValueOrDefault() == 'M' && !(numSettimane >= 2184))
                        {
                            messaggioVideo = string.IsNullOrEmpty(messaggioCI) ? "Il “Numero Settimane” deve essere maggiore o uguale a 2184" : messaggioCI;
                            return false;
                        }
                        if (datiAnagraficiTitolare.Sesso.GetValueOrDefault() == 'F' && !(numSettimane >= 2132))
                        {
                            messaggioVideo = string.IsNullOrEmpty(messaggioCI) ? "Il “Numero Settimane” deve essere maggiore o uguale a 2132" : messaggioCI;
                            return false;
                        }
                    }
                    else
                    {
                        messaggioVideo = string.Empty;
                        if (!(numSettimane >= 2080))
                        {
                            messaggioVideo = string.IsNullOrEmpty(messaggioCI) ? "Il “Numero Settimane” deve essere maggiore o uguale a 2080 " : messaggioCI;
                        }
                        else
                            return true;

                        if (!(numSettimane >= 1820) || Utility.DataStrettamenteSuccessivaA(datiAnagraficiTitolare.DataNascita.Value.AddYears(61).AddMonths(-sconto), datiPensione.DataPerfezionamentoRequisiti.Value))
                        {
                            if (tipoAppartenenza.GetValueOrDefault() == Utility.TipoAppartenenza.CI) messaggioCI = "italiane ed estere per il diritto ";
                            Utility.DifferenzaDateTime requisitoEta = new Utility.DifferenzaDateTime(61, -sconto, true);
                            messaggioVideo += string.Format(" oppure il “Numero Settimane” " + messaggioCI + "deve essere maggiore o uguale a 1820 e il titolare deve avere un’età anagrafica maggiore o uguale a {0} alla data di perfezionamento del requisito", requisitoEta);
                        }
                        else
                            return true;

                        if (!(numSettimane >= 1872) || Utility.DataStrettamenteSuccessivaA(datiAnagraficiTitolare.DataNascita.Value.AddYears(60).AddMonths(-sconto), datiPensione.DataPerfezionamentoRequisiti.Value))
                        {
                            if (tipoAppartenenza.GetValueOrDefault() == Utility.TipoAppartenenza.CI) messaggioCI = "italiane ed estere per il diritto ";
                            Utility.DifferenzaDateTime requisitoEta = new Utility.DifferenzaDateTime(60, -sconto, true);
                            messaggioVideo += string.Format(" oppure il “Numero Settimane” " + messaggioCI + "deve essere maggiore o uguale a 1872  e il titolare deve avere un’età anagrafica maggiore o uguale a {0} alla data di perfezionamento del requisito", requisitoEta);
                        }
                        else
                            return true;
                        if (!string.IsNullOrEmpty(messaggioVideo))
                            return false;
                    }
                }
            }
            //ENG - memo 28/2024
            else if (ctrl28_2024 != null && !String.IsNullOrEmpty(ctrl28_2024.ValoreControllo) && ctrl28_2024.ValoreControllo.ToUpperInvariant() == "SI")
            {
                Utility.TipoUnicarpe tipoUnicarpe = Utility.IsDomandaUnicarpe(datiPensione, true);
                if (tipoUnicarpe != Utility.TipoUnicarpe.Automatica)
                {
                    byte? codiceSpecifico = null;
                    if (tipoAppartenenza.GetValueOrDefault() == Utility.TipoAppartenenza.FS)
                    {
                        GestioneFondo.DatiFondo datiFondo = null;
                        GestioneFondo.GetFondoDatiGenericiByIdPensione(datiPensione.Id, out datiFondo);
                        if (datiFondo != null && datiFondo.CodiceSpecifico.HasValue)
                        {
                            List<GestioneDecodifica.CodiceSpecifico> elencoCodiceSpecifico = null;
                            GestioneDecodifica.GetCodiceSpecifico(out elencoCodiceSpecifico);
                            if (elencoCodiceSpecifico != null && elencoCodiceSpecifico.Count > 0)
                            {
                                GestioneDecodifica.CodiceSpecifico codice = elencoCodiceSpecifico.Find(x => x.Id == datiFondo.CodiceSpecifico.Value);
                                if (codice != null)
                                    codiceSpecifico = codice.Id;
                            }
                        }
                    }

                    if (Utility.IsRicostituzioneTipoContributivo(datiPensione) && datiPensione.IdTipoPLPerRIC.HasValue &&
                        datiPensione.DataPerfezionamentoRequisiti.HasValue && Utility.DataStrettamenteSuccessivaA(datiPensione.DataPerfezionamentoRequisiti.Value, new DateTime(2023, 12, 31)) &&
                        ((!string.IsNullOrEmpty(datiPensione.NaturaPensione) && (tipoAppartenenza.GetValueOrDefault() == Utility.TipoAppartenenza.CI || tipoAppartenenza.GetValueOrDefault() == Utility.TipoAppartenenza.AGO) &&
                        datiPensione.IdTipoPLPerRIC == 7 && (datiPensione.NaturaPensione.Substring(0, 1) == "1" || datiPensione.NaturaPensione.Substring(0, 1) == "2")) ||
                        (datiPensione.IdTipoPLPerRIC == 7 && tipoAppartenenza.GetValueOrDefault() == Utility.TipoAppartenenza.FS && tipoFondo.HasValue && codiceSpecifico.HasValue &&
                        ((tipoFondo == Utility.TipoFondo.PT && codiceSpecifico == 41) ||
                        (tipoFondo == Utility.TipoFondo.FS && codiceSpecifico == 47) ||
                        (tipoFondo == Utility.TipoFondo.TT && codiceSpecifico == 14) ||
                        (tipoFondo == Utility.TipoFondo.ET && codiceSpecifico == 22)))))
                    {
                        if (datiAnagraficiTitolare.Sesso == 'F' && datiPensione.SceltaLavMadri.GetValueOrDefault() == 1)
                        {
                            int reqAA = 0;
                            int reqMM = 0;
                            GestioneDecodifica.GetCtrlRequisitoEta_Avanzato(datiPensione.DataPerfezionamentoRequisiti.Value, null, null, tipoAppartenenza.GetValueOrDefault().ToString(), datiPensione.Tipo, out reqAA, out reqMM);
                            Utility.DifferenzaDateTime etaPiuAspettativaDiVita = new Utility.DifferenzaDateTime(reqAA, reqMM - sconto, true);
                            Utility.DifferenzaDateTime etaTitolareAllaDPR = Utility.DifferenzaBetweenDate(datiPensione.DataPerfezionamentoRequisiti.Value, datiAnagraficiTitolare.DataNascita, tipoAppartenenza.GetValueOrDefault());
                            if (etaTitolareAllaDPR < etaPiuAspettativaDiVita)
                            {
                                if (numSettimane < 1040)
                                {
                                    messaggioVideo = "Il numero settimane deve essere maggiore o uguale di 1040";
                                    return false;
                                }
                            }
                        }
                        else
                        {
                            if (numSettimane < 1040)
                            {
                                messaggioVideo = "Il numero settimane deve essere maggiore o uguale di 1040";
                                return false;
                            }
                        }
                    }
                }
            }
            //Domanda di tipo non contributivo oppure con data di perfezionamento non valorizzata
            return true;
        }

        private static bool ALL_VerificaSettimaneVecchiaiaContributivoOpzione(GestionePensione.DatiPensione datiPensione,
            GestioneAnagrafica.DatiAnagrafici datiAnagraficiTitolare, int numSettimane, DateTime dataRiferimento, string nomeDataRiferimento,
            out string messaggioVideo)
        {
            messaggioVideo = string.Empty;
            Utility.TipoAppartenenza? tipoAppartenenza = Utility.GetTipoAppartenenza(datiPensione.IndConvInt, datiPensione.Gestione);
            string messaggioCI = string.Empty;
            if (tipoAppartenenza.GetValueOrDefault() == Utility.TipoAppartenenza.CI) messaggioCI = "italiane ed estere per il diritto ";

            if (Utility.DataStrettamenteSuccessivaA(dataRiferimento, new DateTime(2007, 12, 31)))
            {
                //DATA MAGGIORE AL 31/12/2007
                if (!Utility.DataStrettamenteSuccessivaA(dataRiferimento, new DateTime(2011, 12, 31)))
                {
                    //DATA MAGGIORE AL 31/12/2007 MA MINORE O UGUALE al 31/12/11

                    //Il “Numero Settimane” deve essere maggiore o uguale a 260
                    if (datiAnagraficiTitolare.Sesso == 'F')
                    {
                        if (!(numSettimane >= 260))
                        {
                            messaggioVideo = "Il “Numero Settimane” " + messaggioCI + "deve essere maggiore o uguale a 260";
                            return false;
                        }
                    }
                    else if (datiAnagraficiTitolare.Sesso == 'M')
                    {
                        if (!(numSettimane >= 260))
                        {
                            messaggioVideo = "Il “Numero Settimane” " + messaggioCI + "deve essere maggiore o uguale a 260";
                            return false;
                        }
                    }
                }
                else
                {
                    //Il “Numero Settimane” deve essere maggiore o uguale a 1040
                    if (!(numSettimane >= 1040) && !Utility.IsDomandaVOAUTVecchiaiaTipoContributivoFiltroGSE(datiPensione) && !Utility.IsDomandaVOAUTAnticipataTipoContributivoFiltroGSE(datiPensione))
                    {
                        messaggioVideo = "Il “Numero Settimane” " + messaggioCI + "deve essere maggiore o uguale a 1040";
                        return false;
                    }
                }
            }
            else
            {
                //DATA MINORE O UGUALE A 31/12/2007
                //Il “Numero Settimane” deve essere maggiore o uguale a 260
                if (!(numSettimane >= 260))
                {
                    messaggioVideo = "Il “Numero Settimane” " + messaggioCI + "deve essere maggiore o uguale a 260";
                    return false;
                }
            }
            return true;
        }

        public static bool ALL_VerificaDataPerfezionamentoPerTrasfAOI(GestionePensione.DatiPensione datiPensione,
            GestioneAnagrafica.DatiAnagrafici datiAnagraficiTitolare, int numSettimane, bool? facoltaComputo, out string messaggioVideo)
        {
            messaggioVideo = string.Empty;
            Utility.TipoAppartenenza? tipoAppartenenza = Utility.GetTipoAppartenenza(datiPensione.IndConvInt, datiPensione.Gestione);

            //Bypass per VOAUT con filtro ERI        
            //ENG - Memo 166/2023
            if (((Utility.IsDomandaVecchiaiaTrasformazioneAOI(datiPensione).GetValueOrDefault() || Utility.isDomandaVecchiaiaTrasformazioneAOICalcoloContributivo(datiPensione)) && Utility.IsDomandaVOAUT(datiPensione.SiglaCategoria) &&
                !(Utility.IsDomandaVOAUT(datiPensione.SiglaCategoria) && datiPensione.GetFiltro() == "ERI")))
            {
                int sconto = 0;
                //se la scelta lavoratrici madri è pari a 1 (anticipo età) applico sconto di 4 mesi per ogni figlio
                if (datiAnagraficiTitolare.Sesso.GetValueOrDefault() == 'F' && datiPensione.SceltaLavMadri.GetValueOrDefault() == 1)
                {
                    sconto = 4 * datiPensione.NumeroFigli.GetValueOrDefault();
                    if (sconto > 12)
                        sconto = 12;
                    DateTime DataPerfReq = (datiPensione.DataPerfezionamentoRequisiti.Value != null ? datiPensione.DataPerfezionamentoRequisiti.Value : new DateTime(1900, 1, 1));
                    if (datiPensione.NumeroFigli > 3 && checkMemo228_2025(datiPensione) && Utility.DataStrettamenteSuccessivaA(DataPerfReq, new DateTime(2024, 12, 31)))
                        sconto = 4 * datiPensione.NumeroFigli.GetValueOrDefault();
                }

                if (Utility.DataStrettamenteSuccessivaA(datiPensione.DataPerfezionamentoRequisiti.Value, new DateTime(2007, 12, 31)))
                {
                    //DATA MAGGIORE AL 31/12/2007
                    if (Utility.DataStrettamenteSuccessivaA(datiPensione.DataPerfezionamentoRequisiti.Value, new DateTime(2011, 12, 31)))
                    {
                        //DATA MAGGIORE AL 31/12/2011                        
                        if (facoltaComputo.GetValueOrDefault())
                        {
                            //facoltà computo = SI
                            //Il “Numero Settimane” deve essere maggiore o uguale a 780
                            if (!(numSettimane >= 780))
                            {
                                messaggioVideo = "Il “Numero Settimane” della scheda Assicurativi deve essere maggiore o uguale a 780";
                                return false;
                            }
                        }
                        else
                        {
                            //facoltà computo = NO
                            //Il “Numero Settimane” deve essere maggiore o uguale a 1040
                            //oppure
                            //Il “Numero Settimane” deve essere maggiore o uguale a 260int reqAA = 0;
                            int reqMM = 0;
                            int reqAA = 0;
                            GestioneDecodifica.GetCtrlRequisitoEta_Avanzato(datiPensione.DataPerfezionamentoRequisiti.Value, null, null, Utility.TipoAppartenenza.AGO.ToString(), "0017", out reqAA, out reqMM);

                            if (Utility.DataStrettamenteSuccessivaA(datiAnagraficiTitolare.DataNascita.Value.AddYears(reqAA).AddMonths(reqMM).AddMonths(-sconto), datiPensione.DataPerfezionamentoRequisiti.Value))
                            {
                                if (sconto > 0)
                                {
                                    reqMM -= sconto;
                                    if (reqMM < 0)
                                    {
                                        reqAA -= 1;
                                        reqMM += 12;
                                    }
                                }
                                string messaggioBase = string.Format("“Numero Settimane” della scheda Assicurativi deve essere maggiore o uguale a 1040 in quanto non viene soddisfatto il requisito anagrafico dei {0} anni e {1} mesi", reqAA, reqMM);

                                if (!(numSettimane >= 1040))
                                {
                                    messaggioVideo = messaggioBase;
                                    return false;
                                }
                            }
                            else
                            {
                                if (!(numSettimane >= 260))
                                {
                                    messaggioVideo = "Il “Numero Settimane” della scheda Assicurativi deve essere maggiore o uguale a 260";
                                    return false;
                                }
                            }
                        }
                    }
                    else
                    {
                        //DATA MAGGIORE AL 31/12/2007 MA MINORE O UGUALE al 31/12/11

                        if (facoltaComputo.GetValueOrDefault())
                        {
                            //facoltà computo = SI
                            //Il “Numero Settimane” deve essere maggiore o uguale a 780
                            if (!(numSettimane >= 780))
                            {
                                messaggioVideo = "Il “Numero Settimane” della scheda Assicurativi deve essere maggiore o uguale a 780";
                                return false;
                            }

                        }
                        else
                        {
                            //facoltà computo = NO
                            //Il “Numero Settimane” deve essere maggiore o uguale a 260
                            if (!(numSettimane >= 260))
                            {
                                messaggioVideo = "Il “Numero Settimane” della scheda Assicurativi deve essere maggiore o uguale a 260";
                                return false;
                            }
                        }
                    }
                }
                else
                {
                    //DATA MINORE O UGUALE A 31/12/2007
                    if (facoltaComputo.GetValueOrDefault())
                    {
                        //facoltà computo = SI
                        //Il “Numero Settimane” deve essere maggiore o uguale a 780
                        if (!(numSettimane >= 780))
                        {
                            messaggioVideo = "Il “Numero Settimane” della scheda Assicurativi deve essere maggiore o uguale a 780";
                            return false;
                        }
                    }
                    else
                    {
                        //facoltà computo = NO
                        //Il “Numero Settimane” deve essere maggiore o uguale a 260
                        if (!(numSettimane >= 260))
                        {
                            messaggioVideo = "Il “Numero Settimane” della scheda Assicurativi deve essere maggiore o uguale a 260";
                            return false;
                        }
                    }
                }
            }
            return true;
        }

        public static bool ALL_VerificaRequisitoEtaPerVOAUT(GestionePensione.DatiPensione datiPensioneDB, GestionePensione.DatiPensione datiPensioneUI,
           DateTime? dataNascita, char? sesso, string tipoSettimaneBeneficio, DateTime? dataAssunzioneCarico, out string messaggioVideo)
        {
            messaggioVideo = string.Empty;

            if (!Utility.IsPensioneVecchiaiaOrRicostituzione(datiPensioneDB, null) || !Utility.IsDomandaVOAUT(datiPensioneDB.SiglaCategoria) ||
                (Utility.IsPensioneVecchiaiaOrRicostituzione(datiPensioneDB, null) && dataAssunzioneCarico.HasValue && Utility.DataStrettamenteSuccessivaA(new DateTime(2021, 03, 01), dataAssunzioneCarico.Value)) ||
                (Utility.IsDomandaVOAUT(datiPensioneDB.SiglaCategoria) && datiPensioneDB.Prodotto == "0002" &&
                (datiPensioneDB.Tipo == "0017" || datiPensioneDB.Tipo == "0030"))
                || GestioneBypassControllo.CheckAndLockBypassControlloByNomeBypass(datiPensioneDB, GestioneBypassControllo.NomeBypass.Titolare_Anagrafica_AGO.APPLICAZIONE_SENTENZA_VOAUT))
                return true;

            Utility.TipoAppartenenza? tipoAppartenenza = Utility.GetTipoAppartenenza(datiPensioneDB.IndConvInt, datiPensioneDB.Gestione);
            bool isRiaperturaDomanda = Utility.IsRiaperturaDomanda(datiPensioneDB.Id);
            int sconto = 0;
            //se la scelta lavoratrici madri è pari a 1 (anticipo età) applico sconto di 4 mesi per ogni figlio
            if (sesso.GetValueOrDefault() == 'F' && datiPensioneUI.SceltaLavMadri.GetValueOrDefault() == 1)
            {
                sconto = 4 * datiPensioneUI.NumeroFigli.GetValueOrDefault();
                if (sconto > 12)
                    sconto = 12;
                DateTime DataPerfReq = (datiPensioneUI.DataPerfezionamentoRequisiti.Value != null ? datiPensioneUI.DataPerfezionamentoRequisiti.Value : new DateTime(1900, 1, 1));
                if (datiPensioneUI.NumeroFigli > 3 && checkMemo228_2025(datiPensioneDB) && Utility.DataStrettamenteSuccessivaA(DataPerfReq, new DateTime(2024, 12, 31)))
                    sconto = 4 * datiPensioneUI.NumeroFigli.GetValueOrDefault();
            }

            DateTime dataRiferimento = datiPensioneUI.DecorrenzaOriginaria.GetValueOrDefault();
            string nomeRiferimento = "decorrenza originaria";

            if (datiPensioneUI.DataPerfezionamentoRequisiti.HasValue)
            {
                dataRiferimento = datiPensioneUI.DataPerfezionamentoRequisiti.Value;
                nomeRiferimento = "data di perfezionamento del requisito";
            }
            if (Utility.DataStrettamenteSuccessivaA(dataRiferimento, new DateTime(2007, 12, 31)))
            {
                //DATA MAGGIORE AL 31/12/2007
                if (Utility.DataStrettamenteSuccessivaA(dataRiferimento, new DateTime(2011, 12, 31)))
                {
                    if (!ALL_ControlsRequisitoEta(datiPensioneDB, tipoAppartenenza, isRiaperturaDomanda, datiPensioneUI, dataNascita, sesso,
                        null, null, null, tipoSettimaneBeneficio, null, dataAssunzioneCarico, out messaggioVideo))
                    {
                        return false;
                    }
                }
                else
                {
                    //DATA MAGGIORE AL 31/12/2007 MA MINORE O UGUALE al 31/12/11

                    //Verifico se esiste Bypass per 1/2/45 
                    if (Utility.IsDomandaVecchiaiaInComputo(datiPensioneDB) && GestioneBypassControllo.CheckAndLockBypassControlloByNomeBypass(datiPensioneDB, GestioneBypassControllo.NomeBypass.Requisito_Eta.REQUISITO_ETA))
                        return true;

                    //Il titolare deve avere un’età anagrafica maggiore o uguale a 60 anni (F) o 65 anni (M)
                    if (sesso == 'F')
                    {
                        if (Utility.DataStrettamenteSuccessivaA(dataNascita.Value.AddYears(60).AddMonths(-sconto), dataRiferimento))
                        {
                            Utility.DifferenzaDateTime requisitoEta = new Utility.DifferenzaDateTime(60, -sconto, true);
                            messaggioVideo = string.Format("Il titolare deve avere un’età anagrafica maggiore o uguale a {0} alla {1}", requisitoEta, nomeRiferimento);
                            return false;
                        }
                    }
                    else if (sesso == 'M')
                    {
                        if (Utility.DataStrettamenteSuccessivaA(dataNascita.Value.AddYears(65), dataRiferimento))
                        {
                            messaggioVideo = string.Format("Il titolare deve avere un’età anagrafica maggiore o uguale 65 anni alla {0}", nomeRiferimento);
                            return false;
                        }
                    }
                }
            }
            else
            {
                //DATA MINORE O UGUALE A 31/12/2007

                //Verifico se esiste Bypass per 1/2/45 
                if (Utility.IsDomandaVecchiaiaInComputo(datiPensioneDB) && GestioneBypassControllo.CheckAndLockBypassControlloByNomeBypass(datiPensioneDB, GestioneBypassControllo.NomeBypass.Requisito_Eta.REQUISITO_ETA))
                    return true;

                //Il titolare deve avere un’età anagrafica maggiore o uguale a 57 anni (per entrambi i sessi)
                if (Utility.DataStrettamenteSuccessivaA(dataNascita.Value.AddYears(57).AddMonths(-sconto), dataRiferimento))
                {
                    Utility.DifferenzaDateTime requisitoEta = new Utility.DifferenzaDateTime(57, -sconto, true);
                    messaggioVideo = string.Format("Il titolare deve avere un’età anagrafica maggiore o uguale a {0} alla {1}", requisitoEta, nomeRiferimento);
                    return false;
                }
            }

            return true;
        }

        public static bool ALL_VerificaRequisitoEtaPerAnticipoVOAUT(GestionePensione.DatiPensione datiPensioneDB, GestionePensione.DatiPensione datiPensioneUI,
           DateTime? dataNascita, char? sesso, string tipoSettimaneBeneficio, int? nSettimaneOBG, string naturaPensione, bool isQuadroTitolare, DateTime? dataAssunzioneCarico, out string messaggioVideo)
        {
            messaggioVideo = string.Empty;
            messaggioVideo = string.Empty;

            GestioneControlliDinamici.ControlloDinamico ctrl = null;
            GestioneControlliDinamici.GetControlloDinamicoByNomeControllo("AbilitazioneMemo123_2021", out ctrl);

            //ENG - Memo 123/2024
            GestioneControlliDinamici.ControlloDinamico ctrlMemo123_2024 = null;
            GestioneControlliDinamici.GetControlloDinamicoByNomeControllo("AbilitazioneRIC_TRFMemo123_2024", out ctrlMemo123_2024);

            //ENG - Memo 123/2024
            GestioneControlliDinamici.ControlloDinamico ctrlMemo123_2024OpzioneContrib = null;
            GestioneControlliDinamici.GetControlloDinamicoByNomeControllo("AbilitazioneRIC_TRFMemo123_2024OpzioneContrib", out ctrlMemo123_2024OpzioneContrib);

            if (!Utility.IsDomandaVOAUT(datiPensioneDB.SiglaCategoria))
                return true;

            if (Utility.IsDomandaQuota100(datiPensioneDB) || Utility.IsDomandaAPEPrecoci(datiPensioneDB) || Utility.IsDomandaQuota102(datiPensioneDB) || Utility.IsDomandaAnticipataFlessibile(datiPensioneDB) || Utility.IsDomandaAnticipataFlessibileOpzioneContributivo(datiPensioneDB) ||
                (!Utility.IsRicostituzione(datiPensioneDB.Gruppo) && !Utility.IsRiaperturaDomanda(datiPensioneDB.Id) && (Utility.IsDomandaAnticipataFlessibileLeggeBilancio2024(datiPensioneDB) || Utility.IsDomandaAnticipataFlessibileOpzioneContributivoLeggeBilancio2024(datiPensioneDB))) ||
                 ((Utility.IsRicostituzione(datiPensioneDB.Gruppo) || Utility.IsRiaperturaDomanda(datiPensioneDB.Id)) && ((ctrlMemo123_2024 != null && ctrlMemo123_2024.ValoreControllo == "SI" && Utility.IsDomandaAnticipataFlessibileLeggeBilancio2024(datiPensioneDB)) || (ctrlMemo123_2024OpzioneContrib != null && ctrlMemo123_2024OpzioneContrib.ValoreControllo == "SI" && Utility.IsDomandaAnticipataFlessibileOpzioneContributivoLeggeBilancio2024(datiPensioneDB)))) ||
                 Utility.IsDomandaVOAUTAnticipataFlessibileLeggeBilancio2024FiltroGSE(datiPensioneDB))
                return true;

            if (!sesso.HasValue)
            {
                messaggioVideo = "Non è stato possibile recuperare il sesso del titolare";
                return false;
            }

            if (!datiPensioneUI.DecorrenzaOriginaria.HasValue)
            {
                messaggioVideo = "Decorrenza Pensione obbligatoria";
                return false;
            }

            if (!dataNascita.HasValue)
            {
                messaggioVideo = "Non è stato possibile recuperare la data nascita del titolare";
                return false;
            }

            // Per una pensione di anzianità
            if (!(Utility.IsDomandaAUTAnticipataInComputo(datiPensioneDB, false) && ctrl != null && ctrl.ValoreControllo == "SI") && Utility.IsPensioneAnzianitaOrRicostituzione(datiPensioneDB, null) && !(dataAssunzioneCarico.HasValue && Utility.DataStrettamenteSuccessivaA(new DateTime(2021, 03, 01), dataAssunzioneCarico.Value)))
            {
                int sconto = 0;
                //se la scelta lavoratrici madri è pari a 1 (anticipo età) applico sconto di 4 mesi per ogni figlio
                if (sesso.GetValueOrDefault() == 'F' && datiPensioneUI.SceltaLavMadri.GetValueOrDefault() == 1)
                {
                    sconto = 4 * datiPensioneUI.NumeroFigli.GetValueOrDefault();
                    if (sconto > 12)
                        sconto = 12;
                    DateTime DataPerfReq = (datiPensioneUI.DataPerfezionamentoRequisiti.Value != null ? datiPensioneUI.DataPerfezionamentoRequisiti.Value : new DateTime(1900, 1, 1));
                    if (datiPensioneUI.NumeroFigli > 3 && checkMemo228_2025(datiPensioneDB) && Utility.DataStrettamenteSuccessivaA(DataPerfReq, new DateTime(2024, 12, 31)))
                        sconto = 4 * datiPensioneUI.NumeroFigli.GetValueOrDefault();
                }

                //ENG - fix Per memo 123/2021 del computo per le RIC/TRF di pensioni anticipate senza filtro PAV (IDTipoPLperRIC= 21). 
                //Nel Pannello Titolare rimosso messaggio "La decorrenza originaria non può essere inferiore a Gennaio 2012"
                if (datiPensioneUI.DataPerfezionamentoRequisiti.HasValue)
                {
                    if (!Utility.DataStrettamenteSuccessivaA(datiPensioneUI.DataPerfezionamentoRequisiti.Value, new DateTime(2011, 12, 31)) && !(ctrl != null && ctrl.ValoreControllo == "SI" && Utility.IsDomandaAUTAnticipataInComputo(datiPensioneDB, false)))
                    {
                        messaggioVideo = "La Data Perfezionamento Requisiti deve essere maggiore al 31/12/2011";
                        return false;
                    }
                    int reqAA = 0;
                    int reqMM = 0;
                    GestioneDecodifica.GetCtrlRequisitoEta_Anticipo(datiPensioneUI.DataPerfezionamentoRequisiti.Value, out reqAA, out reqMM);
                    //ENG - Gestione RIC Anticipate Computo Senza Filtro PAV
                    if (!(Utility.IsDomandaAUTAnticipataInComputo(datiPensioneDB, false) && ctrl != null && ctrl.ValoreControllo == "NO") && !(datiPensioneDB.IdTipoPLPerRIC.HasValue && datiPensioneDB.IdTipoPLPerRIC.Value == (byte?)Utility.TipoPLPerRIC.RicAnticipateComputoSenzaFiltroPAV) &&
                        !Utility.IsDomandaVOAUTAnticipataTipoContributivoFiltroGSE(datiPensioneDB) && Utility.DataStrettamenteSuccessivaA(dataNascita.Value.AddYears(reqAA).AddMonths(reqMM).AddMonths(-sconto), datiPensioneUI.DataPerfezionamentoRequisiti.Value))
                    {

                        if (sconto > 0)
                        {
                            reqMM -= sconto;
                            while (reqMM < 0)
                            {
                                reqAA -= 1;
                                reqMM += 12;
                            }
                        }

                        messaggioVideo = string.Format(
                            "Alla data perfezionamento requisiti ({0:dd/MM/yyyy}) non è stato raggiunto il requisito di età di {1} AA e {2} MM",
                            datiPensioneUI.DataPerfezionamentoRequisiti.Value, reqAA, reqMM
                        );
                        return false;
                    }
                }
            }

            // Primo codice natura pari a 5
            if (!isQuadroTitolare && !string.IsNullOrEmpty(naturaPensione) && naturaPensione.Substring(0, 1) == "5")
            {
                if (!GestioneCrossControls.ALL_ControlsRequisitoEta(datiPensioneDB, Utility.TipoAppartenenza.AGO, Utility.IsRiaperturaDomanda(datiPensioneDB.Id), datiPensioneUI, dataNascita, sesso,
                    null, null, null, tipoSettimaneBeneficio, null, dataAssunzioneCarico, out messaggioVideo))
                    return false;
            }

            if (Utility.IsDomandaVOAUTVecchiaiaTipoContributivoFiltroGSE(datiPensioneDB) && datiPensioneUI.DataPerfezionamentoRequisiti.HasValue)
            {
                if (!Utility.DataStrettamenteSuccessivaA(datiPensioneUI.DataPerfezionamentoRequisiti.Value, new DateTime(2011, 12, 31)))
                {
                    messaggioVideo = "La Data Perfezionamento Requisiti deve essere maggiore al 31/12/2011";
                    return false;
                }
            }
            return true;
        }

        public static bool ALL_VerificaRequisitoEtaSPED(GestionePensione.DatiPensione datiPensioneDB, GestionePensione.DatiPensione datiPensioneUI,
           GestioneAnagrafica.DatiAnagrafici datiAnagraficiTitolare, out string messaggioVideo)
        {
            messaggioVideo = string.Empty;
            if (Utility.IsDomandaVOSPED(datiPensioneDB.SiglaCategoria) && !Utility.IsRicostituzioneOrRiapertura(datiPensioneDB, Utility.IsRiaperturaDomanda(datiPensioneDB.Id)))
            {
                DateTime decorrenzaOriginaria = datiPensioneUI.DecorrenzaOriginaria.HasValue ? datiPensioneUI.DecorrenzaOriginaria.Value : DateTime.MinValue;
                DateTime dataPerfezionamentoRequisiti = datiPensioneUI.DataPerfezionamentoRequisiti.HasValue ? datiPensioneUI.DataPerfezionamentoRequisiti.Value : DateTime.MinValue;
                //Per DP precedente a 02/2011. Per le AGO la data perfezionamento requisiti non è acquisibile per date precedenti al 02/2011
                if (!Utility.DataSuccessivaA(decorrenzaOriginaria, new DateTime(2011, 2, 1)))
                {
                    //Se la Categoria (RACATEG) è = a “VOSPED” verifica se il pensionando alla
                    //Decorrenza Originaria (RAU104) fino giugno 1998 abbia compiuto 63 anni
                    if (!Utility.DataStrettamenteSuccessivaA(decorrenzaOriginaria, new DateTime(1998, 6, 1)))
                    {
                        if (Utility.DataStrettamenteSuccessivaA(datiAnagraficiTitolare.DataNascita.Value.AddYears(63), decorrenzaOriginaria))
                        {
                            messaggioVideo = "Il pensionando deve aver compiuto 63 anni rispetto alla data di decorrenza originaria";
                            return false;
                        }
                    }
                    //Se la Categoria (RACATEG) è = a “VOSPED” verifica se il pensionando alla
                    //Decorrenza Originaria (RAU104) da luglio 1998 a dicembre 1999 abbia
                    //compiuto 64 anni
                    if (!Utility.DataStrettamenteSuccessivaA(decorrenzaOriginaria, new DateTime(1999, 12, 1)) &&
                        Utility.DataSuccessivaA(decorrenzaOriginaria, new DateTime(1998, 7, 1)))
                    {
                        if (Utility.DataStrettamenteSuccessivaA(datiAnagraficiTitolare.DataNascita.Value.AddYears(64), decorrenzaOriginaria))
                        {
                            messaggioVideo = "Il pensionando deve aver compiuto 64 anni rispetto alla data di decorrenza originaria";
                            return false;
                        }
                    }
                    //Se la Categoria (RACATEG) è = a “VOSPED” verifica se il pensionando alla
                    //Decorrenza Originaria (RAU104) da gennaio 2000 in poi abbia compiuto 65
                    //anni
                    if (Utility.DataSuccessivaA(decorrenzaOriginaria, new DateTime(2000, 1, 1)))
                    {
                        if (Utility.DataStrettamenteSuccessivaA(datiAnagraficiTitolare.DataNascita.Value.AddYears(65), decorrenzaOriginaria))
                        {
                            messaggioVideo = "Il pensionando deve aver compiuto 65 anni rispetto alla data di decorrenza originaria";
                            return false;
                        }
                    }
                }
                else
                {
                    if (!Utility.DataStrettamenteSuccessivaA(dataPerfezionamentoRequisiti, new DateTime(2014, 1, 1)) &&
                        Utility.DataSuccessivaA(dataPerfezionamentoRequisiti, new DateTime(2000, 2, 1)))
                    {
                        if (Utility.DataStrettamenteSuccessivaA(datiAnagraficiTitolare.DataNascita.Value.AddYears(65), dataPerfezionamentoRequisiti))
                        {
                            messaggioVideo = "Il pensionando deve aver compiuto 65 anni rispetto alla data di perfezionamento requisiti";
                            return false;
                        }
                    }

                    if (Utility.DataSuccessivaA(dataPerfezionamentoRequisiti, new DateTime(2014, 2, 1)))
                    {
                        if (Utility.DataStrettamenteSuccessivaA(datiAnagraficiTitolare.DataNascita.Value.AddYears(66).AddMonths(3), dataPerfezionamentoRequisiti))
                        {
                            messaggioVideo = "Il pensionando deve aver compiuto 66 anni e 3 mesi rispetto alla data di perfezionamento requisiti";
                            return false;
                        }
                    }
                }

            }
            return true;
        }

        public static bool ALL_VerificaRequisitoEtaINDCOM(GestionePensione.DatiPensione datiPensioneDB, GestionePensione.DatiPensione datiPensioneUI,
          GestioneAnagrafica.DatiAnagrafici datiAnagraficiTitolare, out string messaggioVideo)
        {
            messaggioVideo = string.Empty;
            if (Utility.IsDomandaINDCOM(datiPensioneDB.SiglaCategoria) && Utility.IsDomandaPL(datiPensioneDB))
            {
                DateTime decorrenzaOriginaria = datiPensioneUI.DecorrenzaOriginaria.HasValue ? datiPensioneUI.DecorrenzaOriginaria.Value : DateTime.MinValue;
                var sesso = datiAnagraficiTitolare.Sesso;

                if (sesso.GetValueOrDefault() == 'F')
                {

                    if (Utility.DataStrettamenteSuccessivaA(datiAnagraficiTitolare.DataNascita.Value.AddYears(57), decorrenzaOriginaria))
                    {
                        messaggioVideo = "Il pensionando deve aver compiuto 57 anni rispetto alla data di decorrenza originaria";
                        return false;
                    }
                }

                else if (sesso.GetValueOrDefault() == 'M')
                {
                    if (Utility.DataStrettamenteSuccessivaA(datiAnagraficiTitolare.DataNascita.Value.AddYears(62), decorrenzaOriginaria))
                    {
                        messaggioVideo = "Il pensionando deve aver compiuto 62 anni rispetto alla data di decorrenza originaria";
                        return false;
                    }
                }
            }
            return true;
        }


        public static bool ALL_VerificaRequisitoEtaPerVOMIN(GestionePensione.DatiPensione datiPensioneDB, GestionePensione.DatiPensione datiPensioneUI,
          DateTime? dataNascita, char? sesso, string naturaPensione, out string messaggioVideo)
        {
            messaggioVideo = string.Empty;

            if (!(Utility.IsPensioneVecchiaiaOrRicostituzione(datiPensioneDB, null) && Utility.IsDomandaVOMIN(datiPensioneDB.SiglaCategoria)))
                return true;

            //DR = DP se DP <= 01/2011, altrimenti DPR
            //Se primo byte del codice natura diverso da 0, 8 o 9 allora deve avere un’età anagrafica maggiore o uguale a 55 anni alla DR
            //Altrimenti deve avere un’età anagrafica maggiore o uguale a 60 anni alla DR

            DateTime dataRiferimento = datiPensioneUI.DecorrenzaOriginaria.GetValueOrDefault();
            string nomeRiferimento = "decorrenza originaria";

            if (datiPensioneUI.DataPerfezionamentoRequisiti.HasValue)
            {
                dataRiferimento = datiPensioneUI.DataPerfezionamentoRequisiti.Value;
                nomeRiferimento = "data di perfezionamento del requisito";
            }

            if (!string.IsNullOrEmpty(naturaPensione) && naturaPensione.Substring(0, 1) != "0" && naturaPensione.Substring(0, 1) != "8" && naturaPensione.Substring(0, 1) != "9")
            {
                if (Utility.DataStrettamenteSuccessivaA(dataNascita.Value.AddYears(55), dataRiferimento))
                {
                    messaggioVideo = string.Format("Il titolare deve avere un’età anagrafica maggiore o uguale 55 anni alla {0}", nomeRiferimento);
                    return false;
                }
            }
            else
            {
                if (Utility.DataStrettamenteSuccessivaA(dataNascita.Value.AddYears(60), dataRiferimento))
                {
                    messaggioVideo = string.Format("Il titolare deve avere un’età anagrafica maggiore o uguale 60 anni alla {0}", nomeRiferimento);
                    return false;
                }
            }

            return true;
        }


        public static bool ALL_VerificaRequisitoEtaVecchiaiaPerPescatori(GestionePensione.DatiPensione datiPensioneDB, GestionePensione.DatiPensione datiPensioneUI,
         DateTime? dataNascita, char? sesso, string tipoSettimaneBeneficio, DateTime? dataAssunzioneCarico, out string messaggioVideo)
        {
            messaggioVideo = string.Empty;

            if (!(Utility.IsDomandaVOP(datiPensioneDB.SiglaCategoria) && Utility.IsPensioneVecchiaiaOrRicostituzione(datiPensioneDB, null) && !Utility.IsRicostituzioneOrRiapertura(datiPensioneDB, Utility.IsRiaperturaDomanda(datiPensioneDB.Id)) &&
                !Utility.IsDomandaAutomatica(datiPensioneDB)))
                return true;

            Utility.TipoAppartenenza? tipoAppartenenza = Utility.GetTipoAppartenenza(datiPensioneDB.IndConvInt, datiPensioneDB.Gestione);
            bool isRiaperturaDomanda = Utility.IsRiaperturaDomanda(datiPensioneDB.Id);

            DateTime dataRiferimento = datiPensioneUI.DecorrenzaOriginaria.GetValueOrDefault();
            string nomeRiferimento = "decorrenza originaria";

            if (datiPensioneUI.DataPerfezionamentoRequisiti.HasValue)
            {
                dataRiferimento = datiPensioneUI.DataPerfezionamentoRequisiti.Value;
                nomeRiferimento = "data di perfezionamento del requisito";
            }

            //Se DP > 01 / 2011
            if (Utility.DataStrettamenteSuccessivaA(dataRiferimento, new DateTime(2011, 12, 31)))
            {
                if (Utility.IsDomandaPescatoriFiltroL80(datiPensioneDB))
                {
                    //codice tipo richiesta = C8)
                    //•	se donna sono richiesti almeno 55 anni alla DPR
                    //•	se uomo sono richiesti almeno 60 anni alla DPR
                    if (sesso == 'F')
                    {
                        if (Utility.DataStrettamenteSuccessivaA(dataNascita.Value.AddYears(55), dataRiferimento))
                        {
                            messaggioVideo = string.Format("Il titolare deve avere un’età anagrafica maggiore o uguale a 55 anni alla {0}", nomeRiferimento);
                            return false;
                        }
                    }
                    else if (sesso == 'M')
                    {
                        if (Utility.DataStrettamenteSuccessivaA(dataNascita.Value.AddYears(60), dataRiferimento))
                        {
                            messaggioVideo = string.Format("Il titolare deve avere un’età anagrafica maggiore o uguale 60 anni alla {0}", nomeRiferimento);
                            return false;
                        }
                    }
                }
                else
                {
                    //codice tipo richiesta<> C8 --> CtrlRequisitiEta 
                    if (!ALL_ControlsRequisitoEta(datiPensioneDB, tipoAppartenenza, isRiaperturaDomanda, datiPensioneUI, dataNascita, sesso,
                        null, null, null, tipoSettimaneBeneficio, null, dataAssunzioneCarico, out messaggioVideo))
                    {
                        return false;
                    }
                }
            }
            else
            {
                //  Se DP <= 01 / 2011(DPR non è visibile) allora:
                //•	se donna sono richiesti almeno 55 anni alla DP
                //•	se uomo sono richiesti almeno 60 anni alla DP
                if (sesso == 'F')
                {
                    if (Utility.DataStrettamenteSuccessivaA(dataNascita.Value.AddYears(55), dataRiferimento))
                    {
                        messaggioVideo = string.Format("Il titolare deve avere un’età anagrafica maggiore o uguale a 55 anni alla {0}", nomeRiferimento);
                        return false;
                    }
                }
                else if (sesso == 'M')
                {
                    if (Utility.DataStrettamenteSuccessivaA(dataNascita.Value.AddYears(60), dataRiferimento))
                    {
                        messaggioVideo = string.Format("Il titolare deve avere un’età anagrafica maggiore o uguale 60 anni alla {0}", nomeRiferimento);
                        return false;
                    }
                }
            }

            return true;
        }


        /// <summary>
        /// Verifica se il titolare è residente all'estero o se ha una modalità di pagamento estera
        /// </summary>
        /// <param name="codComuneResidenzaTitolare"></param>
        /// <param name="datiPagamento"></param>
        /// <returns>TRUE: se è soddisfatta la condizione di cui sopra</returns>
        public static bool ALL_VerificaBloccoCalcoloEstero(string codComuneResidenzaTitolare, GestionePagamento.DatiPagamento datiPagamento)
        {
            if (Utility.IsResidenteEstero(codComuneResidenzaTitolare) ||
                (datiPagamento != null && datiPagamento.TipoPagamento == 'E'))
                return true;

            return false;
        }

        public static bool ALL_VerificaBloccoCalcoloAnticipata2019(GestionePensione.DatiPensione datipensione, Utility.TipoAppartenenza? tipoApp, DateTime dataSistema, out string messaggioVideo)
        {
            messaggioVideo = string.Empty;
            if (Utility.IsDomandaAnzianitaPerLeggeBilancio2019OrRicostituzione(datipensione))
            {
                switch (tipoApp.GetValueOrDefault())
                {
                    case Utility.TipoAppartenenza.FS:
                        if (GestioneCtrlControlliApplicativi.CheckControlloApplicativoAttivoByData(GestioneCtrlControlliApplicativi.EnumNomeControllo.FS.BLOCCOCALCOLO_ANTICIPATA2019, dataSistema))
                        {
                            messaggioVideo = "Invio al calcolo temporaneamente non disponibile per domande di pensione anticipata per legge bilancio 2019";
                            return false;
                        }
                        break;
                    case Utility.TipoAppartenenza.AGO:
                        if (GestioneCtrlControlliApplicativi.CheckControlloApplicativoAttivoByData(GestioneCtrlControlliApplicativi.EnumNomeControllo.AGO.BLOCCOCALCOLO_ANTICIPATA2019, dataSistema))
                        {
                            messaggioVideo = "Invio al calcolo temporaneamente non disponibile per domande di pensione anticipata per legge bilancio 2019";
                            return false;
                        }
                        break;
                    case Utility.TipoAppartenenza.CI:
                        if (GestioneCtrlControlliApplicativi.CheckControlloApplicativoAttivoByData(GestioneCtrlControlliApplicativi.EnumNomeControllo.CI.BLOCCOCALCOLO_ANTICIPATA2019, dataSistema))
                        {
                            messaggioVideo = "Invio al calcolo temporaneamente non disponibile per domande di pensione anticipata per legge bilancio 2019";
                            return false;
                        }
                        break;
                }
            }
            return true;
        }

        #region Familiari
        /// <summary>
        /// Verifica nella tabella Familiare, che per la stessa domanda da calcolare, non ci siano C.F. uguali
        /// </summary>
        /// <param name="Lfamiliare">Lista dei familiari</param>
        /// <returns>true se è presente almeno un duplicato, false altrimenti</returns>
        public static bool ALL_VerificaFamiliariDuplicati(List<GestioneFamiliari.Familiare> Lfamiliare, out string messaggioVideo)
        {
            messaggioVideo = null;

            if (Lfamiliare == null || Lfamiliare.Count == 0)
                return true;
            List<GestioneFamiliari.Familiare> ListaDuplicati = new List<GestioneFamiliari.Familiare>();
            ListaDuplicati = Lfamiliare.FindAll(delegate
                (GestioneFamiliari.Familiare fam1)
            {
                return Lfamiliare.FindAll(delegate
                    (GestioneFamiliari.Familiare fam2)
                {
                    return fam1.CodiceFiscale == fam2.CodiceFiscale && fam1.Confermato && fam2.Confermato;
                }).Count > 1;
            }).Distinct().ToList();

            if (ListaDuplicati.Count > 0)
            {
                messaggioVideo = string.Format("Dati Familiari: Familiare già presente ({0})", string.Join(", ", ListaDuplicati.Select(x => x.CodiceFiscale).GroupBy(x => x).Select(x => x.First()).ToArray()));
                return false;
            }
            else
                return true;
        }

        /// <summary>
        /// Verifica nella tabella Familiare, che per la stessa domanda da calcolare, non ci siano più di due record con SiglaFamiliare = G
        /// </summary>
        /// <param name="Lfamiliare">Lista dei familiari</param>
        /// <returns>false se sono presenti più di due genitori, false altrimenti</returns>
        public static bool ALL_VerificaFamiliariGenitori(List<GestioneFamiliari.Familiare> Lfamiliare, out string messaggioVideo)
        {
            messaggioVideo = null;

            if (Lfamiliare == null || Lfamiliare.Count == 0)
                return true;
            var iconiugi = Lfamiliare.FindAll(delegate
                (GestioneFamiliari.Familiare f)
            {
                return (f.SiglaFamiliare.HasValue && f.SiglaFamiliare.Value.ToString().ToUpperInvariant() == "G" && f.Confermato);
            });

            if (iconiugi != null && iconiugi.Count > 2)
            {
                messaggioVideo = string.Format("Non è possibile inserire più di due familiari 'genitori' ({0}).", string.Join(", ", iconiugi.Select(x => x.CodiceFiscale).ToArray()));
                return false;
            }
            return true;
        }

        /// <summary>  
        /// Verifica (fase acquisizione + fase calcolo domanda)    se Titolare.CodiceStatoCivile != 2 (relativa alla decorr. più recente), allora  non deve esistere nella tabella Familiare il coniuge (SiglaFamiliare = C)
        /// Verifica (fase calcolo domanda) se Titolare.CodiceStatoCivile == 2 (relativa alla decorr. più recente), allora  non deve esistere nella tabella Familiare il coniuge (SiglaFamiliare = C) 
        /// </summary>
        /// <param name="LdatiAnagrafici">Lista dei dati anagrafici</param>
        /// <param name="Lfamiliare">Lista dei familiari</param>
        /// <returns>true se è presente almeno un coniuge nella tabella familiari con CodiceStatoCivileTitolare != 2, false altrimenti</returns>
        public static bool ALL_VerificaFamiliariConiugiTitolareConiugato(GestionePensione.DatiPensione datiPensione, Entity.AreaTitolare areaTitolare, List<GestioneFamiliari.Familiare> Lfamiliare,
            bool IsInvioCalcolo, GestioneDanteCausa.DatiDanteCausa danteCausa, bool isRiaperturaDomanda, out string msgVideo)
        {
            msgVideo = string.Empty;

            GestioneControlliDinamici.ControlloDinamico controlloDinamicoSpacchettate024 = null;
            GestioneControlliDinamici.GetControlloDinamicoByNomeControllo("AbilitazioneSpacchettate024", out controlloDinamicoSpacchettate024);

            if (Lfamiliare == null || Lfamiliare.Count == 0)
                return true;

            if (IsInvioCalcolo)
                msgVideo = "Controlli Incrociati - Dati Familiari:<br/>" + msgVideo;

            if ((!Utility.IsDomandaPensioneSuperstitiOrRicostituzione(datiPensione) || Utility.IsDomandaSpacchettamentoENPALS(datiPensione) || Utility.IsDomandaSpacchettamentoINPDAP(datiPensione) || Utility.IsDomandaSpacchettamentoSOPGIPost072022(datiPensione, danteCausa)
                || (controlloDinamicoSpacchettate024 != null && controlloDinamicoSpacchettate024.ValoreControllo.ToUpperInvariant() == "SI" && Utility.IsDomandaSpacchettamento024(datiPensione, Utility.IsRiaperturaDomanda(datiPensione.Id))) || Utility.IsDomandaSpacchettamentoSO(datiPensione, isRiaperturaDomanda)
                || Utility.IsDomandaSpacchettamentoSOART(datiPensione, isRiaperturaDomanda) || Utility.IsDomandaSpacchettamentoSOCOM(datiPensione, isRiaperturaDomanda) || Utility.IsDomandaSpacchettamentoSR(datiPensione, isRiaperturaDomanda)) &&
                (Lfamiliare.FindAll(x => x.IsConiugeOrUnitoCivile() && x.Confermato).Count != 0) && areaTitolare.ElencoStatiCivili.LastOrDefault().Codice == '1')
            {
                msgVideo += "Non è possibile inserire un Coniuge se è presente il solo stato civile Celibe/Nubile";
                return false;
            }

            if ((Utility.IsDomandaPensioneSuperstitiOrRicostituzione(datiPensione) && !Utility.IsDomandaSpacchettamentoENPALS(datiPensione) && !Utility.IsDomandaSpacchettamentoINPDAP(datiPensione) && !Utility.IsDomandaSpacchettamentoSOPGIPost072022(datiPensione, danteCausa)
                && !(controlloDinamicoSpacchettate024 != null && controlloDinamicoSpacchettate024.ValoreControllo.ToUpperInvariant() == "SI" && Utility.IsDomandaSpacchettamento024(datiPensione, Utility.IsRiaperturaDomanda(datiPensione.Id))) && !Utility.IsDomandaSpacchettamentoSO(datiPensione, isRiaperturaDomanda)
                && !Utility.IsDomandaSpacchettamentoSOART(datiPensione, isRiaperturaDomanda) && !Utility.IsDomandaSpacchettamentoSOCOM(datiPensione, isRiaperturaDomanda) && !Utility.IsDomandaSpacchettamentoSR(datiPensione, isRiaperturaDomanda)) &&
                (areaTitolare.ElencoStatiCivili.LastOrDefault().Codice == '2' || areaTitolare.ElencoStatiCivili.LastOrDefault().Codice == '7') &&
                    Lfamiliare.Count > 0 && Lfamiliare.First().IsConiugeOrUnitoCivile() && Lfamiliare.First().Confermato)
            {
                msgVideo += "Il titolare non può avere il grado di parentela 'Coniuge' o 'Unito/a Civilmente'";
                return false;
            }

            if ((Utility.IsDomandaPensioneSuperstitiOrRicostituzione(datiPensione) && !Utility.IsDomandaSpacchettamentoENPALS(datiPensione) && !Utility.IsDomandaSpacchettamentoINPDAP(datiPensione) && !Utility.IsDomandaSpacchettamentoSOPGIPost072022(datiPensione, danteCausa) &&
                !(controlloDinamicoSpacchettate024 != null && controlloDinamicoSpacchettate024.ValoreControllo.ToUpperInvariant() == "SI" && Utility.IsDomandaSpacchettamento024(datiPensione, Utility.IsRiaperturaDomanda(datiPensione.Id))) && !Utility.IsDomandaSpacchettamentoSO(datiPensione, isRiaperturaDomanda)
                && !Utility.IsDomandaSpacchettamentoSOART(datiPensione, isRiaperturaDomanda) && !Utility.IsDomandaSpacchettamentoSOCOM(datiPensione, isRiaperturaDomanda) && !Utility.IsDomandaSpacchettamentoSR(datiPensione, isRiaperturaDomanda)) &&
                (areaTitolare.ElencoStatiCivili.LastOrDefault().Codice == '2' || areaTitolare.ElencoStatiCivili.LastOrDefault().Codice == '7') &&
                Lfamiliare.Count > 0 && Lfamiliare.FirstOrDefault().SiglaFamiliare != 'C' && Lfamiliare.First().Confermato)
            {
                msgVideo += "Il titolare non può avere stato civile 'Coniugato/a' o 'Unito/a Civilmente'";
                return false;
            }

            if (!IsInvioCalcolo)  // fase acquisizione
            {
                if ((Lfamiliare.FindAll(x => x.IsConiugeOrUnitoCivile() && x.Confermato).Count != 0) && (areaTitolare.ElencoStatiCivili.FindAll(x => x.Codice == '2' || x.Codice == '7')).Count == 0)
                {
                    if (!Utility.IsDomandaPensioneSuperstitiOrRicostituzione(datiPensione) || Utility.IsDomandaSpacchettamentoENPALS(datiPensione) || Utility.IsDomandaSpacchettamentoINPDAP(datiPensione) || Utility.IsDomandaSpacchettamentoSOPGIPost072022(datiPensione, danteCausa)
                        || (controlloDinamicoSpacchettate024 != null && controlloDinamicoSpacchettate024.ValoreControllo.ToUpperInvariant() == "SI" && Utility.IsDomandaSpacchettamento024(datiPensione, Utility.IsRiaperturaDomanda(datiPensione.Id))) || Utility.IsDomandaSpacchettamentoSO(datiPensione, isRiaperturaDomanda) ||
                        Utility.IsDomandaSpacchettamentoSOART(datiPensione, isRiaperturaDomanda) || Utility.IsDomandaSpacchettamentoSOCOM(datiPensione, isRiaperturaDomanda) || Utility.IsDomandaSpacchettamentoSR(datiPensione, isRiaperturaDomanda))
                    {
                        msgVideo = "Non è possibile inserire un 'Coniuge' o 'Unito/a Civilmente' se non è presente almeno uno stato civile del Titolare 'Coniugato/a' o 'Unito/a civilmente'.";
                        return false;
                    }
                }
            }
            else // fase calcolo domanda
            {
                if (areaTitolare.ElencoStatiCivili.FindAll(x => x.Codice == '2' || x.Codice == '7').Count == 0)
                {
                    if ((Lfamiliare.FindAll(x => x.IsConiugeOrUnitoCivile() && x.Confermato).Count != 0))
                    {
                        if (!Utility.IsDomandaPensioneSuperstitiOrRicostituzione(datiPensione) || Utility.IsDomandaSpacchettamentoENPALS(datiPensione) || Utility.IsDomandaSpacchettamentoINPDAP(datiPensione) || Utility.IsDomandaSpacchettamentoSOPGIPost072022(datiPensione, danteCausa)
                            || (controlloDinamicoSpacchettate024 != null && controlloDinamicoSpacchettate024.ValoreControllo.ToUpperInvariant() == "SI" && Utility.IsDomandaSpacchettamento024(datiPensione, Utility.IsRiaperturaDomanda(datiPensione.Id))) || Utility.IsDomandaSpacchettamentoSO(datiPensione, isRiaperturaDomanda) ||
                            Utility.IsDomandaSpacchettamentoSOART(datiPensione, isRiaperturaDomanda) || Utility.IsDomandaSpacchettamentoSOCOM(datiPensione, isRiaperturaDomanda) || Utility.IsDomandaSpacchettamentoSR(datiPensione, isRiaperturaDomanda))
                        {
                            msgVideo += "Non è possibile inserire un 'Coniuge' o 'Unito/a Civilmente' se l'ultimo stato civile del Titolare è diverso da 'Coniugato/a' o 'Unito/a civilmente'.";
                            return false;
                        }
                    }
                }
                else
                {
                    if (Lfamiliare.Count == 0)
                    {
                        msgVideo += "Familiare obbligatorio";
                        return false;
                    }

                    if (Lfamiliare.Count(x => x.Confermato && x.IsConiugeOrUnitoCivile()) == 0)
                    {
                        msgVideo += "'Coniuge' o 'Unito/a Civilmente' non presente nell'elenco dei familiari";
                        return false;
                    }
                }
            }

            msgVideo = string.Empty;
            return true;
        }

        /// <summary>
        /// Verifica che per ciascun familiare presente il codice fiscale del Titolare sia diverso dal codice fiscale del familiare
        /// </summary>
        /// <param name="Lfamiliare">Lista dei familiari</param>
        /// <param name="areaTitolare">Area del titolare</param>
        /// <returns>false se la lista contiene il codice fiscale da ricercare, true altrimenti</returns>
        public static bool ALL_VerificaFamiliariTitolare(List<GestioneFamiliari.Familiare> Lfamiliare, Entity.AreaTitolare areaTitolare, GestionePensione.DatiPensione datiPensione,
            Utility.TipoAppartenenza? tipoApp, bool isRiaperturaDomanda, GestioneDanteCausa.DatiDanteCausa danteCausa)
        {
            if (Lfamiliare == null || Lfamiliare.Count == 0)
                return true;

            GestioneControlliDinamici.ControlloDinamico controlloDinamicoSpacchettate024 = null;
            GestioneControlliDinamici.GetControlloDinamicoByNomeControllo("AbilitazioneSpacchettate024", out controlloDinamicoSpacchettate024);

            if (Utility.IsDomandaPensioneSuperstitiOrRicostituzione(datiPensione) && !Utility.IsDomandaSpacchettamentoENPALS(datiPensione) && !Utility.IsDomandaSpacchettamentoINPDAP(datiPensione) && !Utility.IsDomandaSpacchettamentoSOPGIPost072022(datiPensione, danteCausa)
                && !(controlloDinamicoSpacchettate024 != null && controlloDinamicoSpacchettate024.ValoreControllo.ToUpperInvariant() == "SI" && Utility.IsDomandaSpacchettamento024(datiPensione, isRiaperturaDomanda)) && !Utility.IsDomandaSpacchettamentoSO(datiPensione, isRiaperturaDomanda) &&
                !Utility.IsDomandaSpacchettamentoSOART(datiPensione, isRiaperturaDomanda) && !Utility.IsDomandaSpacchettamentoSOCOM(datiPensione, isRiaperturaDomanda) && !Utility.IsDomandaSpacchettamentoSR(datiPensione, isRiaperturaDomanda))
                return true;

            if ((Utility.IsRicostituzioneOrRiapertura(datiPensione, isRiaperturaDomanda) || Utility.IsDomandaRipristino(datiPensione).GetValueOrDefault()) && tipoApp.HasValue && tipoApp.Value == Utility.TipoAppartenenza.AGO)
                return true;

            List<String> CodiciFiscaliFamiliari = new List<String>();
            foreach (GestioneFamiliari.Familiare familiare in Lfamiliare)
                if (familiare.Confermato)
                    CodiciFiscaliFamiliari.Add(familiare.CodiceFiscale);

            return !CodiciFiscaliFamiliari.Contains(areaTitolare.Anagrafica.CodiceFiscale);
        }

        /// <summary>
        /// Verifica che se esistono due o più coniugi (Familiare.SiglaFamiliare = C) devono avere decorrenze diverse (CodMaggiorazioneFamiliari.Decorrenza)
        /// </summary>
        /// <param name="Lfamiliari">Lista dei familiari</param>
        /// <param name="listaCodMaggFamiliari">Lista dei codici maggiorazione dei familiari</param>
        /// <returns>false se esistono due o più coniugi che hanno la stessa decorrenza, true altrimenti</returns>
        public static bool ALL_VerificaDecorrenzaCodMaggFamiliariConiugi(List<GestioneFamiliari.Familiare> Lfamiliari, List<GestioneFamiliari.CodMaggFamiliari> listaCodMaggFamiliari, out string messaggioVideo)
        {
            messaggioVideo = null;

            if (Lfamiliari == null || Lfamiliari.Count == 0 || Lfamiliari.Count(x => x.Confermato && x.IsConiugeOrUnitoCivile()) == 1)
                return true;

            if (listaCodMaggFamiliari != null && listaCodMaggFamiliari.Count > 0 && listaCodMaggFamiliari.Count(x => Lfamiliari.Any(y => y.Confermato && y.IsConiugeOrUnitoCivile() && y.IdAnagrafica == x.IdAnagrafica)) > 0)
            {
                List<GestioneFamiliari.CodMaggFamiliari> listaCodMaggConiugi = listaCodMaggFamiliari.FindAll(x => Lfamiliari.Any(y => y.Confermato && y.IsConiugeOrUnitoCivile() && y.IdAnagrafica == x.IdAnagrafica));
                List<long> listaIdConiugi = listaCodMaggConiugi.FindAll(x => listaCodMaggConiugi.Any(y => y.IdAnagrafica != x.IdAnagrafica && DateTime.Compare(y.Decorrenza.Value.Date, x.Decorrenza.Value.Date) == 0)).Select(x => x.IdAnagrafica).ToList();
                if (listaIdConiugi != null && listaIdConiugi.Count > 0)
                {
                    messaggioVideo = string.Format("Dati Familiari: Non è possibile inserire più coniugi con la stessa decorrenza ({0})", string.Join(", ", Lfamiliari.FindAll(x => listaIdConiugi.Any(y => y == x.IdAnagrafica)).Select(x => x.CodiceFiscale).ToArray()));
                    return false;
                }
            }
            return true;
        }

        public static bool ALL_VerificaSovrapposizioneCodMaggFamiliariConiugi(List<GestioneFamiliari.Familiare> Lfamiliari, List<GestioneFamiliari.CodMaggFamiliari> listaCodMaggFamiliari,
            out string messaggioVideo)
        {
            messaggioVideo = string.Empty;

            if (Lfamiliari == null || Lfamiliari.Count == 0)
                return true;

            if (Lfamiliari.Count > 0 && listaCodMaggFamiliari != null && listaCodMaggFamiliari.Count > 0)
            {
                List<GestioneFamiliari.CodMaggFamiliari> lCodMaggConiuge = listaCodMaggFamiliari.FindAll(x =>
                    Lfamiliari.FindAll(y => y.IsConiugeOrUnitoCivile() && y.Confermato).Select(y => y.IdAnagrafica).Contains(x.IdAnagrafica)
                );

                foreach (var codMaggConiuge in lCodMaggConiuge)
                {
                    if (lCodMaggConiuge.Exists(x => !x.Equals(codMaggConiuge) &&
                        !Utility.DataSuccessivaA(x.Decorrenza.Value, codMaggConiuge.Cessazione.HasValue ? codMaggConiuge.Cessazione.Value : DateTime.MaxValue) && //a.start < b.end
                        !Utility.DataSuccessivaA(codMaggConiuge.Decorrenza.Value, x.Cessazione.HasValue ? x.Cessazione.Value : DateTime.MaxValue) // b.start < a.end;
                        ))
                    {
                        messaggioVideo = "I periodi di carico dei codici maggiorazione dei familiari coniugi o uniti civilmente non possono sovrapporsi.";
                        return false;
                    }
                }
            }

            return true;
        }

        /// <summary>
        /// Verifica per ogni familiare che sia presente una DecorrenzaCarico = DecorrenzaPensione
        /// </summary>
        /// <param name="Lfamiliari">Lista dei familiari</param>
        /// <param name="listaCodMaggFamiliari">Lista dei codici maggiorazione dei familiari</param>
        /// <returns>false se un familiare non ha una DecorrenzaCarico = DecorrenzaPensione</returns>
        public static bool ALL_VerificaDecorrenzaCarico(List<GestioneFamiliari.Familiare> Lfamiliari, List<GestioneFamiliari.CodMaggFamiliari> listaCodMaggFamiliari, GestionePensione.DatiPensione datiPensione,
            GestioneDanteCausa.DatiDanteCausa datiDanteCausa, out string messaggioVideo)
        {
            messaggioVideo = null;

            if (Lfamiliari == null || Lfamiliari.Count == 0)
                return true;

            Utility.TipoFondo? tipoFondo = Utility.GetTipoFondoByCategoria(Utility.TipoAppartenenza.FS, datiPensione.SiglaCategoria);

            foreach (GestioneFamiliari.Familiare fam in Lfamiliari)
            {
                List<GestioneFamiliari.CodMaggFamiliari> LcodMaggFam = listaCodMaggFamiliari.FindAll(x => x.IdAnagrafica == fam.IdAnagrafica);
                GestioneAnagrafica.DatiAnagrafici datiAnagraficiFamiliare = null;
                GestioneAnagrafica.GetAnagraficaByIdAnagrafica(fam.IdAnagrafica, out datiAnagraficiFamiliare);

                //per Coniuge e Figlio postumo nato entro 300 giorni dalla morte del Dante Causa il controllo sulla decorrenza carico non va effettuato
                if (!GestioneBypassControllo.CheckAndLockBypassControlloByNomeBypass(datiPensione, GestioneBypassControllo.NomeBypass.Sentenza_Nati_Dopo_300_Giorni.SENTENZA_NATI_DOPO_300_GIORNI) &&
                    Utility.IsDomandaPensioneSuperstitiOrRicostituzione(datiPensione) && !(fam.SiglaFamiliare == 'C' || ((fam.SiglaFamiliare == 'M' || fam.SiglaFamiliare == 'S' || fam.SiglaFamiliare == 'U' || fam.SiglaFamiliare == 'I') && datiAnagraficiFamiliare != null && datiAnagraficiFamiliare.DataNascita.HasValue &&
                datiDanteCausa != null && datiDanteCausa.DataMorte.HasValue && Utility.DataStrettamenteSuccessivaA(datiAnagraficiFamiliare.DataNascita.Value, datiDanteCausa.DataMorte.Value) &&
                !Utility.DataStrettamenteSuccessivaA(datiAnagraficiFamiliare.DataNascita.Value, datiDanteCausa.DataMorte.Value.AddDays(300)))))
                {
                    DateTime? decorrenzaOriginariaDaConfrontare = datiPensione.DecorrenzaOriginaria;
                    if (Utility.IsRicostituzioneOrRiapertura(datiPensione, Utility.IsRiaperturaDomanda(datiPensione.Id)) && Utility.IsDomandaPensioneSuperstitiOrRicostituzione(datiPensione) && (tipoFondo == Utility.TipoFondo.FS || tipoFondo == Utility.TipoFondo.PT)
                        && datiPensione.DecorrenzaOriginaria.HasValue && !Utility.DataSuccessivaA(datiPensione.DecorrenzaOriginaria.Value, new DateTime(1995, 9, 1)))
                        decorrenzaOriginariaDaConfrontare = new DateTime(datiPensione.DecorrenzaOriginaria.Value.Year, datiPensione.DecorrenzaOriginaria.Value.Month, 1);

                    if (!LcodMaggFam.Exists(x => x.Decorrenza == decorrenzaOriginariaDaConfrontare))
                    {
                        messaggioVideo = string.Format("È necessario avere un grado di parentela con data decorrenza carico uguale alla decorrenza della pensione.");
                        return false;
                    }
                }
            }

            return true;
        }

        /// <summary>
        /// Verifica se la singola decorrenza del codice maggiorazione è maggiore o uguale alla decorrenza della pensione
        /// </summary>
        /// <param name="IdAnagrafici">Id Anagrafica</param>
        /// <param name="listaCodMaggFamiliari">Lista dei codici maggiorazione dei familiari</param>
        /// <param name="DecorrenzaPensione">Data decorrenza pensione</param>
        /// <returns>false se la decorrenza pensione è maggiore della prima decorrenza del codice maggiorazione benefici, true altrimenti</returns>
        public static bool ALL_VerificaDecorrenzaCodMaggDecorrenzaPensione(long IdAnagrafica, List<GestioneFamiliari.CodMaggFamiliari> elencoCodMaggFamiliari, DateTime? DecorrenzaPensione)
        {
            return elencoCodMaggFamiliari.Exists(delegate
                (GestioneFamiliari.CodMaggFamiliari code)
            { return (code.IdAnagrafica == IdAnagrafica && code.Decorrenza.Value.CompareTo(new DateTime(DecorrenzaPensione.Value.Year, DecorrenzaPensione.Value.Month, 01)) < 0); });
        }

        /// <summary>
        /// Verifica cessazione non superiore al gennaio dell'anno successivo per i Nipoti
        /// </summary>
        /// <param name="Lfamiliari">Lista dei familiari</param>
        /// <param name="listaCodMaggFamiliari">Lista dei codici maggiorazione dei familiari</param>
        /// <returns>false se cessazione maggiore di gennaio dell'anno in corso + 1, true altrimenti</returns>
        public static bool ALL_VerificaDecorrenzaCodMaggFamiliariNipoti(List<GestioneFamiliari.Familiare> Lfamiliari, List<GestioneFamiliari.CodMaggFamiliari> listaCodMaggFamiliari, DateTime dataSistema)
        {
            if (Lfamiliari == null || Lfamiliari.Count == 0)
                return true;

            if (Lfamiliari.Count > 0 && listaCodMaggFamiliari != null && listaCodMaggFamiliari.Count > 0)
            {
                List<GestioneFamiliari.Familiare> LNipoti = Lfamiliari.FindAll(x => x.Confermato && x.SiglaFamiliare.HasValue && (x.SiglaFamiliare == 'N' || x.SiglaFamiliare == 'J'));

                if (LNipoti != null && LNipoti.Count > 0)
                {
                    foreach (GestioneFamiliari.Familiare nip in LNipoti)
                    {
                        List<GestioneFamiliari.CodMaggFamiliari> listaCodMaggNipoti = listaCodMaggFamiliari.FindAll(x => x.IdAnagrafica == nip.IdAnagrafica);
                        if (listaCodMaggNipoti != null && listaCodMaggNipoti.Count > 0)
                        {
                            foreach (GestioneFamiliari.CodMaggFamiliari codMaggNip in listaCodMaggNipoti)
                            {
                                if (codMaggNip.Cessazione.HasValue && DateTime.Compare(codMaggNip.Cessazione.Value.Date, new DateTime(dataSistema.Year + 1, 01, 01).Date) > 0)
                                {
                                    return false;
                                }
                            }
                        }
                    }
                }
            }
            return true;
        }


        public static bool ALL_VerificaDataMorte(DateTime? DecorrenzaOriginaria, DateTime? DataMorte)
        {
            if (DecorrenzaOriginaria.HasValue && DataMorte.HasValue)
            {
                if (!Utility.DataSuccessivaA(DataMorte.Value, DecorrenzaOriginaria.Value))
                    return false;
            }
            return true;
        }

        /// <summary>
        /// Verifica presenza codice maggiorazione
        /// </summary>
        /// <param name="IdAnagrafici">Id Anagrafica</param>
        /// <param name="listaCodMaggFamiliari">Lista dei codici maggiorazione dei familiari</param>
        /// <returns>false se lcodice maggiorazione non presente, true altrimenti</returns>
        public static bool ALL_VerificaPresenzaCodMaggiorazione(GestionePensione.DatiPensione datiPensione, GestioneAnagrafica.DatiAnagrafici datiAnagraficiFamiliare, List<GestioneFamiliari.CodMaggFamiliari> elencoCodMaggFamiliari,
            out string messaggioVideo)
        {
            messaggioVideo = string.Empty;

            if (Utility.IsDomandaVOCOOP_COOP28(datiPensione.SiglaCategoria) || Utility.IsDomandaVOCRED_CRED27(datiPensione.SiglaCategoria) || Utility.IsDomandaVOESO(datiPensione.SiglaCategoria) ||
                Utility.IsDomandaAPESociale(datiPensione.SiglaCategoria) || Utility.IsDomandaVOAUT_IOAUT(datiPensione.SiglaCategoria))
            {
                if (elencoCodMaggFamiliari.Exists(x => x.IdAnagrafica == datiAnagraficiFamiliare.Id && x.CodiceMaggiorazione.HasValue && x.CodiceMaggiorazione.Value != 0))
                {
                    messaggioVideo = "Non devono essere presenti i codici maggiorazione per il Familiare " + datiAnagraficiFamiliare.Cognome + " " + datiAnagraficiFamiliare.Nome;
                    return false;
                }
            }
            else
            {
                if (!elencoCodMaggFamiliari.Exists(x => x.IdAnagrafica == datiAnagraficiFamiliare.Id && x.CodiceMaggiorazione.HasValue))
                {
                    messaggioVideo = "Codice Maggiorazione mancante per il Familiare " + datiAnagraficiFamiliare.Cognome + " " + datiAnagraficiFamiliare.Nome;
                    return false;
                }
            }

            return true;
        }

        /// <summary>
        /// Controlla se, in presenza di stati civili con decorrenza successiva a quella di coniugato/a, le cessazioni dei Familiari sono corrette
        /// </summary>
        /// <param name="familiari"></param>
        /// <param name="elencoCodMaggFamiliari"></param>
        /// <param name="AreaTit"></param>
        /// <param name="messaggioVideo"></param>
        /// <returns></returns>
        public static bool ALL_ControlsFamiliariWithStatiCivili(List<GestioneFamiliari.Familiare> familiari, List<GestioneFamiliari.CodMaggFamiliari> elencoCodMaggFamiliari, List<GestioneAnagrafica.DatiStatoCivile> elencoStatiCivili,
            Utility.TipoAppartenenza? tipoApp, DateTime? dataMorteTitolare, out string messaggioVideo)
        {
            messaggioVideo = string.Empty;
            bool precedenteIsConiugatoOrUnito = false;
            DateTime? precedenteDecorrenza = null;

            if (elencoStatiCivili.Exists(x => x.Codice == '2' || x.Codice == '7'))
            {
                // Recupero l'elenco di stati civili a partire dall'ultimo avente valore 2: Coniugato/a o 7: Unito/a civilmente
                int lastIndex = elencoStatiCivili.FindLastIndex(x => x.Codice == '2' || x.Codice == '7');
                foreach (GestioneAnagrafica.DatiStatoCivile statoCivile in elencoStatiCivili.GetRange(lastIndex, elencoStatiCivili.Count - lastIndex))
                {
                    if (precedenteIsConiugatoOrUnito)
                    {
                        foreach (GestioneFamiliari.Familiare fam in familiari)
                        {
                            if (fam.IsConiugeOrUnitoCivile() && fam.Confermato)
                            {
                                List<GestioneFamiliari.CodMaggFamiliari> elencoCodMagg = elencoCodMaggFamiliari.FindAll(x => x.IdAnagrafica == fam.IdAnagrafica);

                                if (elencoCodMagg != null && elencoCodMagg.Count > 0)
                                {
                                    GestioneFamiliari.CodMaggFamiliari codMaggFam = elencoCodMagg.Last();
                                    if (!codMaggFam.Cessazione.HasValue && statoCivile.Codice != '2' && statoCivile.Codice != '7')
                                    {
                                        // Bypasso il controllo se il titolare è morto prima del familiare coniuge morto
                                        if (!(fam.DataMorte.HasValue && dataMorteTitolare.HasValue && !Utility.DataSuccessivaA(dataMorteTitolare.Value, fam.DataMorte.Value)))
                                        {
                                            messaggioVideo = "La data Fine Carico non deve essere acquisita";
                                            return false;
                                        }
                                    }

                                    if (codMaggFam.Decorrenza.HasValue && Utility.DataStrettamenteSuccessivaA(statoCivile.Decorrenza.Value, codMaggFam.Decorrenza.Value) &&
                                        precedenteDecorrenza.HasValue && Utility.DataSuccessivaA(codMaggFam.Decorrenza.Value, precedenteDecorrenza.Value))
                                    {
                                        if (elencoCodMagg.Last().Cessazione.HasValue && elencoCodMagg.Last().Cessazione.Value != statoCivile.Decorrenza)
                                        {
                                            messaggioVideo = "La data Fine Carico deve essere uguale alla decorrenza dello stato civile successivo allo stato coniugato/a (" + String.Format("{0:MM/yyyy}", statoCivile.Decorrenza) + ")";
                                            return false;
                                        }
                                    }
                                }
                            }
                        }
                        precedenteIsConiugatoOrUnito = false;
                    }

                    if (statoCivile.Codice == '2' || statoCivile.Codice == '7') // Coniugato/a o Unito civilmente
                    {
                        precedenteIsConiugatoOrUnito = true;
                        precedenteDecorrenza = statoCivile.Decorrenza;
                    }
                }
            }

            if (elencoCodMaggFamiliari != null && elencoCodMaggFamiliari.Count > 0)
            {
                // Se l'ultimo stato civile è coniugato o unito civilmente allora deve esistere UN coniuge che non ha la data Fine Carico
                if (elencoStatiCivili.Last().Codice == '2' || elencoStatiCivili.Last().Codice == '7')
                {
                    // Recupero il numero di Coniugi non cessati
                    int familiariConiugiNonCessati = familiari.Count(fam =>
                    {
                        if (fam.IsConiugeOrUnitoCivile())
                        {
                            List<GestioneFamiliari.CodMaggFamiliari> elencoCodMagg = elencoCodMaggFamiliari.FindAll(x => x.IdAnagrafica == fam.IdAnagrafica);
                            if (elencoCodMagg != null && elencoCodMagg.Count > 0 && !elencoCodMagg.Last().Cessazione.HasValue)
                                return true;
                        }

                        return false;
                    });

                    if (familiariConiugiNonCessati > 1)
                    {
                        messaggioVideo = "Non possono essere presenti più coniugi senza la data Fine Carico.";
                        return false;
                    }
                    else if (familiariConiugiNonCessati == 0)
                    {
                        // Possono esserci zero familiari non cessati solo se questi sono morti dopo il titolare
                        // Posso prendere in considerazione direttamente quello che ha decorrenza carico pari alla decorrenza dello stato civile
                        if ((familiari.Exists(fam =>
                        {
                            if (fam.IsConiugeOrUnitoCivile())
                            {
                                List<GestioneFamiliari.CodMaggFamiliari> elencoCodMagg = elencoCodMaggFamiliari.FindAll(x => x.IdAnagrafica == fam.IdAnagrafica);
                                if (elencoCodMagg != null && elencoCodMagg.Count > 0 && elencoCodMagg.Last().Decorrenza.HasValue && elencoCodMagg.Last().Decorrenza.Value == elencoStatiCivili.Last().Decorrenza.Value)
                                {
                                    if (!(fam.DataMorte.HasValue && dataMorteTitolare.HasValue && !Utility.DataSuccessivaA(dataMorteTitolare.Value, fam.DataMorte.Value)))
                                        return true;
                                }
                            }
                            return false;
                        })))
                        {
                            messaggioVideo = "La data Fine Carico non deve essere acquisita";
                            return false;
                        }
                    }
                }

                foreach (GestioneFamiliari.Familiare fam in familiari)
                {
                    if (fam.IsConiugeOrUnitoCivile() && fam.Confermato)
                    {
                        List<GestioneFamiliari.CodMaggFamiliari> elencoCodMagg = elencoCodMaggFamiliari.FindAll(x => x.IdAnagrafica == fam.IdAnagrafica);
                        GestioneFamiliari.CodMaggFamiliari codMaggFamiliariCompare = null;

                        if (elencoCodMagg != null && elencoCodMagg.Count > 0)
                        {
                            foreach (GestioneFamiliari.CodMaggFamiliari codMaggFamiliari in elencoCodMagg)
                            {
                                if (codMaggFamiliariCompare != null)
                                {
                                    if (tipoApp.HasValue && tipoApp.Value != Utility.TipoAppartenenza.FS)
                                    {
                                        if (codMaggFamiliari.CodiceMaggiorazione == codMaggFamiliariCompare.CodiceMaggiorazione)
                                        {
                                            messaggioVideo = "Il codice maggiorazione deve essere diverso da quello precedente";
                                            return false;
                                        }
                                    }

                                    if (codMaggFamiliari.Decorrenza.Value.CompareTo(codMaggFamiliariCompare.Cessazione) < 0)
                                    {
                                        messaggioVideo = "La Decorrenza Carico deve essere posteriore o uguale alla Fine Carico del periodo di carico precedente";
                                        return false;
                                    }
                                }
                                codMaggFamiliariCompare = codMaggFamiliari;
                            }
                        }
                    }
                }

                // Il numero di stati civile coniugato deve essere minore o uguale al numero totale di maggiorazioni familiari dei coniugi/uniti civilmente
                if (elencoStatiCivili.Count(x => x.Codice == '2' || x.Codice == '7') > elencoCodMaggFamiliari.Count(x => familiari.Select(y => y.IdAnagrafica).Contains(x.IdAnagrafica)))
                {
                    messaggioVideo = "Gli stati civili Coniugato/a e/o Unito/a civilmente inseriti sono incongruenti con i familiari inseriti.";
                    return false;
                }
            }

            return true;
        }

        public static bool ALL_VerificaNuovoCodMaggConCessazionePrecedente(List<GestioneFamiliari.CodMaggFamiliari> elencoCodMaggFamiliari, out string messaggioVideo)
        {
            messaggioVideo = string.Empty;
            bool isCessazioneAssente = false;

            if (elencoCodMaggFamiliari != null && elencoCodMaggFamiliari.Count > 0)
            {
                foreach (GestioneFamiliari.CodMaggFamiliari codMaggFamiliare in elencoCodMaggFamiliari)
                {
                    if (isCessazioneAssente)
                    {
                        messaggioVideo = "Inserire la fine carico prima di aggiungere un nuovo periodo di carico";
                        return false;
                    }

                    if (!codMaggFamiliare.Cessazione.HasValue)
                        isCessazioneAssente = true;
                    else
                        isCessazioneAssente = false;
                }
            }

            return true;
        }

        /// <summary>
        /// Controlla se il familiare è morto
        /// Controlla se la data fine carico è presente in caso di familiare morto
        /// Controlla se la data fine carico è successiva alla data morte + 1 mese
        /// </summary>
        /// <param name="familiari"></param>
        /// <param name="elencoCodMaggFamiliare"></param>
        /// <param name="decorrenzaOriginaria"></param>
        /// <param name="messaggioVideo"></param>
        /// <returns></returns>
        public static bool ALL_VerificaFamiliariMorti(List<GestioneFamiliari.Familiare> familiari, List<GestioneFamiliari.CodMaggFamiliari> elencoCodMaggFamiliare, DateTime? decorrenzaOriginaria, Utility.TipoAppartenenza? tipoAppartenenza, out string messaggioVideo,
            GestionePensione.DatiPensione datiPensione, GestionePensione.DatiEliminazione datiEliminazione)
        {
            messaggioVideo = string.Empty;

            if (familiari != null && familiari.Count > 0)
            {
                foreach (GestioneFamiliari.Familiare fam in familiari)
                {
                    List<GestioneFamiliari.CodMaggFamiliari> codMaggFamiliare = null;
                    if (elencoCodMaggFamiliare != null && elencoCodMaggFamiliare.Count > 0)
                        codMaggFamiliare = elencoCodMaggFamiliare.FindAll(x => x.IdAnagrafica == fam.IdAnagrafica);

                    if (fam.Confermato)
                    {
                        if (fam.DataMorte.HasValue)
                        {
                            if (Utility.DataStrettamenteSuccessivaA(decorrenzaOriginaria.Value, fam.DataMorte.Value))
                            {
                                messaggioVideo = "Non è possibile acquisire il familiare " + fam.CodiceFiscale + ". La data morte è antecedente la decorrenza pensione";
                                return false;
                            }

                            if (Utility.DataSuccessivaA(fam.DataMorte.Value, decorrenzaOriginaria.Value))
                            {
                                if (fam.TipoComponente != 'T' && (codMaggFamiliare == null || codMaggFamiliare.Count == 0 || !codMaggFamiliare.Last().Cessazione.HasValue)
                                    && !(familiari.Count == 1 && fam.FlagTitolare == true && (tipoAppartenenza == Utility.TipoAppartenenza.AGO || tipoAppartenenza == Utility.TipoAppartenenza.CI)) &&
                                    !(Utility.IsRicostituzione(datiPensione.Gruppo) && datiEliminazione != null && datiEliminazione.DecorrenzaEliminazione.HasValue &&
                                      Utility.DataStrettamenteSuccessivaA(fam.DataMorte.Value, datiEliminazione.DecorrenzaEliminazione.Value
                                      )))
                                {
                                    messaggioVideo = "Per familiare defunto bisogna acquisire la data fine carico";
                                    return false;
                                }

                                if (codMaggFamiliare != null && codMaggFamiliare.Count > 0 && codMaggFamiliare.Last().Cessazione.HasValue &&
                                    Utility.DataStrettamenteSuccessivaA(codMaggFamiliare.Last().Cessazione.Value, fam.DataMorte.Value.AddMonths(1)))
                                {
                                    messaggioVideo = "La data fine carico non può essere successiva alla Data Morte + 1 mese";
                                    return false;
                                }
                            }
                        }
                    }
                }
            }

            return true;
        }

        public static bool ALL_VerificaCessazioneCodMagg(List<GestioneFamiliari.Familiare> Lfamiliari, List<GestioneFamiliari.CodMaggFamiliari> listaCodMaggFamiliari, DateTime dataSistema,
            out string messaggioVideo)
        {
            messaggioVideo = string.Empty;

            if (Lfamiliari == null || Lfamiliari.Count == 0)
                return true;

            if (Lfamiliari.Count > 0 && listaCodMaggFamiliari != null && listaCodMaggFamiliari.Count > 0)
            {
                List<GestioneFamiliari.Familiare> listaFamiliari = Lfamiliari.FindAll(x => x.Confermato && x.SiglaFamiliare.HasValue &&
                    (x.IsConiugeOrUnitoCivile() || x.SiglaFamiliare == 'I' || x.SiglaFamiliare == 'F' || x.SiglaFamiliare == 'Y'));

                if (listaFamiliari != null && listaFamiliari.Count > 0)
                {
                    foreach (GestioneFamiliari.Familiare familiare in listaFamiliari)
                    {
                        List<GestioneFamiliari.CodMaggFamiliari> listaCodMagg = listaCodMaggFamiliari.FindAll(x => x.IdAnagrafica == familiare.IdAnagrafica);
                        if (listaCodMagg != null && listaCodMagg.Count > 0)
                        {
                            foreach (GestioneFamiliari.CodMaggFamiliari codMagg in listaCodMagg)
                            {
                                if (codMagg.Cessazione.HasValue)
                                {
                                    if (Utility.DataStrettamenteSuccessivaA(codMagg.Cessazione.Value, Utility.FirstDayOfMonth(dataSistema.AddMonths(1))))
                                    {
                                        messaggioVideo = "La fine carico non può essere posteriore al mese successivo alla data odierna.";
                                        return false;
                                    }
                                }
                            }
                        }
                    }
                }
            }

            return true;
        }

        /// <summary>
        /// Memo 33
        /// Il metodo esegue delle verifiche sulle decorrenze/ cessazioni dei familiari 'N' e 'J' 
        /// </summary>
        /// <param name="datiPensione"></param>
        /// <param name="tipoAppartenenza"></param>
        /// <param name="familiariApp"></param>
        /// <param name="elencoCodMaggFamiliari"></param>
        /// <param name="messaggioVideo"></param>
        /// <returns></returns>
        public static bool ALL_VerificaMaggiorazioneFamiliariNeJ(GestionePensione.DatiPensione datiPensione, Utility.TipoAppartenenza? tipoAppartenenza, GestioneFamiliari.Familiare familiareApp, List<GestioneFamiliari.CodMaggFamiliari> elencoMaggiorazioniFamiliare, out string messaggioVideo)
        {
            messaggioVideo = string.Empty;
            DateTime dataConfronto = new DateTime(2022, 03, 01);

            if (tipoAppartenenza.HasValue)
            {
                GestioneControlliDinamici.ControlloDinamico abilitazioneMemo33 = null;
                GestioneControlliDinamici.GetControlloDinamicoByNomeControllo("AbilitazioneMemo33" + tipoAppartenenza.Value, out abilitazioneMemo33);

                if (abilitazioneMemo33 != null && !String.IsNullOrEmpty(abilitazioneMemo33.ValoreControllo) && abilitazioneMemo33.ValoreControllo.Trim().ToUpperInvariant() == "SI")
                {
                    //Gli Id delle maggiorazioni sono diverse a seconda della linea di appartenenza
                    //Per la linea FS i codici Maggiorazioni non sono gestiti
                    byte? codiceMaggiorazioneSI = null;
                    byte? codiceMaggiorazioneNO = null;
                    switch (tipoAppartenenza.Value)
                    {
                        case Utility.TipoAppartenenza.AGO:
                            codiceMaggiorazioneSI = 2;
                            codiceMaggiorazioneNO = 1;
                            break;
                        case Utility.TipoAppartenenza.CI:
                            codiceMaggiorazioneSI = 1;
                            codiceMaggiorazioneNO = 2;
                            break;
                    }

                    if (elencoMaggiorazioniFamiliare != null && elencoMaggiorazioniFamiliare.Count > 0)
                    {
                        //Domande Dirette
                        if (!Utility.IsDomandaPensioneSuperstitiOrRicostituzione(datiPensione))
                        {
                            //Per la linea FS i controlli sulle dirette non devono essere effettuati
                            if (tipoAppartenenza != Utility.TipoAppartenenza.FS)
                            {
                                //Le cessazioni devono essere necessariamente minori/ uguali di 03/2022
                                if (elencoMaggiorazioniFamiliare.Exists(x => x.SiglaFamiliare == familiareApp.SiglaFamiliare && Utility.DataStrettamenteSuccessivaA(x.Cessazione.GetValueOrDefault(), dataConfronto)))
                                {
                                    messaggioVideo = "I soggetti N e J devono avere necessariamente una data fine carico pari o minore di 03/2022";
                                    return false;
                                }

                                //Per le maggiorazioni a SI, non può essere inserita una decorrenza maggiore di 03/2022                                    
                                List<GestioneFamiliari.CodMaggFamiliari> elencoMaggiorazioniSI = elencoMaggiorazioniFamiliare.FindAll(x => x.SiglaFamiliare == familiareApp.SiglaFamiliare && x.CodiceMaggiorazione.GetValueOrDefault() == codiceMaggiorazioneSI);
                                if (elencoMaggiorazioniSI != null && elencoMaggiorazioniSI.Count > 0)
                                {
                                    if (elencoMaggiorazioniSI.Exists(x => Utility.DataSuccessivaA(x.Decorrenza.GetValueOrDefault(), dataConfronto)))
                                    {
                                        messaggioVideo = "Per i soggetti N e J, la decorrenza carico per la maggiorazione SI deve essere minore di 03/2022";
                                        return false;
                                    }
                                }
                            }
                        }
                        else
                        {
                            if (tipoAppartenenza == Utility.TipoAppartenenza.AGO || tipoAppartenenza == Utility.TipoAppartenenza.CI)
                            {
                                List<GestioneFamiliari.CodMaggFamiliari> elencoMaggiorazioniSI = elencoMaggiorazioniFamiliare.FindAll(x => x.SiglaFamiliare == familiareApp.SiglaFamiliare && x.CodiceMaggiorazione.GetValueOrDefault() == codiceMaggiorazioneSI);
                                if (elencoMaggiorazioniSI != null && elencoMaggiorazioniSI.Count > 0)
                                {
                                    //Per le maggiorazioni a SI, non può essere inserita una decorrenza maggiore o uguale di 03/2022
                                    if (elencoMaggiorazioniSI.Exists(x => Utility.DataSuccessivaA(x.Decorrenza.GetValueOrDefault(), dataConfronto)))
                                    {
                                        messaggioVideo = "Per i soggetti N e J, la decorrenza carico per la maggiorazione SI deve essere minore di 03/2022";
                                        return false;
                                    }

                                    //Per le maggiorazioni a SI che hanno cessazione pari a 03/2022, si deve prevedere anche una maggiorazione a NO con decorrenza da 03/2022 fino al 18 anno di età compiuto
                                    GestioneAnagrafica.DatiAnagrafici datiAnagrafici = null;
                                    GestioneAnagrafica.GetAnagraficaByIdAnagrafica(familiareApp.IdAnagrafica, out datiAnagrafici);
                                    if (datiAnagrafici != null)
                                    {
                                        DateTime dataDiciottesimoAnno = Utility.FirstDayOfMonth(datiAnagrafici.DataNascita.GetValueOrDefault()).AddMonths(1).AddYears(18);
                                        List<GestioneFamiliari.CodMaggFamiliari> elencoMaggiorazioniNO = elencoMaggiorazioniFamiliare.FindAll(x => x.SiglaFamiliare == familiareApp.SiglaFamiliare && x.CodiceMaggiorazione.GetValueOrDefault() == codiceMaggiorazioneNO);
                                        int countCessazioneSI = elencoMaggiorazioniSI.Count(x => Utility.DataSuccessivaA(x.Cessazione.GetValueOrDefault(), dataConfronto) && !Utility.DataStrettamenteSuccessivaA(x.Cessazione.GetValueOrDefault(), dataConfronto));
                                        int countCessazioneNO = elencoMaggiorazioniNO.Count(x => Utility.DataSuccessivaA(x.Decorrenza.GetValueOrDefault(), dataConfronto) && !Utility.DataStrettamenteSuccessivaA(x.Decorrenza.GetValueOrDefault(), dataConfronto) && Utility.DataSuccessivaA(x.Cessazione.GetValueOrDefault(), dataDiciottesimoAnno) && !Utility.DataStrettamenteSuccessivaA(x.Cessazione.GetValueOrDefault(), dataDiciottesimoAnno));

                                        if ((elencoMaggiorazioniSI.Exists(x => Utility.DataSuccessivaA(x.Cessazione.GetValueOrDefault(), dataConfronto)) && (dataDiciottesimoAnno.Month != dataConfronto.Month || dataDiciottesimoAnno.Year != dataConfronto.Year) && countCessazioneNO == 0)
                                            || (countCessazioneSI > 0 && (dataDiciottesimoAnno.Month != dataConfronto.Month || dataDiciottesimoAnno.Year != dataConfronto.Year) && countCessazioneSI != countCessazioneNO))
                                        {
                                            messaggioVideo = "Per i soggetti N e J con cessazione al 3/2022, suddividere il periodo in 2 periodi consecutivi il primo con scadenza 3/2022 e il secondo con inizio 3/2022";
                                            return false;
                                        }
                                    }
                                }
                            }
                            else
                            {
                                //Il controllo va effettuato solo se la Decorrenza Pensione è minore di 03/2022
                                if (elencoMaggiorazioniFamiliare != null && elencoMaggiorazioniFamiliare.Count > 0 && !Utility.DataSuccessivaA(datiPensione.DecorrenzaOriginaria.GetValueOrDefault(), dataConfronto))
                                {
                                    GestioneAnagrafica.DatiAnagrafici datiAnagrafici = null;
                                    GestioneAnagrafica.GetAnagraficaByIdAnagrafica(familiareApp.IdAnagrafica, out datiAnagrafici);
                                    if (datiAnagrafici != null)
                                    {
                                        DateTime dataDiciottesimoAnno = Utility.FirstDayOfMonth(datiAnagrafici.DataNascita.GetValueOrDefault()).AddMonths(1).AddYears(18);
                                        int countCessazione = elencoMaggiorazioniFamiliare.Count(x => Utility.DataSuccessivaA(x.Cessazione.GetValueOrDefault(), dataConfronto) && !Utility.DataStrettamenteSuccessivaA(x.Cessazione.GetValueOrDefault(), dataConfronto));
                                        int countDecorrenza = elencoMaggiorazioniFamiliare.Count(x => Utility.DataSuccessivaA(x.Decorrenza.GetValueOrDefault(), dataConfronto) && !Utility.DataStrettamenteSuccessivaA(x.Decorrenza.GetValueOrDefault(), dataConfronto) && Utility.DataSuccessivaA(x.Cessazione.GetValueOrDefault(), dataDiciottesimoAnno) && !Utility.DataStrettamenteSuccessivaA(x.Cessazione.GetValueOrDefault(), dataDiciottesimoAnno));
                                        if ((elencoMaggiorazioniFamiliare.Exists(x => Utility.DataStrettamenteSuccessivaA(x.Cessazione.GetValueOrDefault(), dataConfronto) && countDecorrenza == 0)) ||
                                            ((dataDiciottesimoAnno.Month != dataConfronto.Month || dataDiciottesimoAnno.Year != dataConfronto.Year) && countCessazione != countDecorrenza))
                                        {
                                            messaggioVideo = "Per i soggetti N e J con cessazione maggiore a 3/2022, suddividere il periodo in 2 periodi consecutivi il primo con scadenza 3/2022 e il secondo con inizio 3/2022";
                                            return false;
                                        }
                                    }
                                }
                            }
                        }
                    }

                }
            }

            return true;
        }

        /// <summary>
        /// Memo 33
        /// Il metodo verifica che la decorrenza della sigla familiare V sia successiva ad almeno una delle fine carico delle sigle familiari S, U oppure L
        /// IL metodo verifica che la sigla familiare V può essere presente solo se il familiare era precedentemente S, U oppure L
        /// </summary>
        /// <param name="datiPensione"></param>
        /// <param name="tipoAppartenenza"></param>
        /// <param name="familiariApp"></param>
        /// <param name="elencoCodMaggFamiliari"></param>
        /// <param name="messaggioVideo"></param>
        /// <returns></returns>
        public static bool ALL_VerificaSiglaFamiliareV(GestionePensione.DatiPensione datiPensione, Utility.TipoAppartenenza? tipoAppartenenza, List<GestioneFamiliari.Familiare> familiariApp, List<GestioneFamiliari.CodMaggFamiliari> elencoCodMaggFamiliari, out string messaggioVideo)
        {
            messaggioVideo = string.Empty;

            if (tipoAppartenenza.HasValue)
            {
                GestioneControlliDinamici.ControlloDinamico abilitazioneMemo33 = null;
                GestioneControlliDinamici.GetControlloDinamicoByNomeControllo("AbilitazioneMemo33" + tipoAppartenenza.Value, out abilitazioneMemo33);

                if (abilitazioneMemo33 != null && !String.IsNullOrEmpty(abilitazioneMemo33.ValoreControllo) && abilitazioneMemo33.ValoreControllo.Trim().ToUpperInvariant() == "SI")
                {
                    if (familiariApp != null && familiariApp.Count > 0)
                    {
                        foreach (GestioneFamiliari.Familiare fam in familiariApp)
                        {
                            if (fam.Confermato)
                            {
                                if (elencoCodMaggFamiliari != null && elencoCodMaggFamiliari.Count > 0)
                                {
                                    if (elencoCodMaggFamiliari.Exists(x => x.IdAnagrafica == fam.IdAnagrafica && x.SiglaFamiliare == 'V') && !elencoCodMaggFamiliari.Exists(x => x.IdAnagrafica == fam.IdAnagrafica && (x.SiglaFamiliare == 'S' || x.SiglaFamiliare == 'U' || x.SiglaFamiliare == 'M')))
                                    {
                                        messaggioVideo = "Il Codice Maggiorazione 'V' può essere associato solo ai codici: 'S', 'U', 'M'";
                                        return false;
                                    }

                                    List<GestioneFamiliari.CodMaggFamiliari> codiciMaggiorazioniAmmissibiliPerV = elencoCodMaggFamiliari.FindAll(x => x.IdAnagrafica == fam.IdAnagrafica && (x.SiglaFamiliare == 'S' || x.SiglaFamiliare == 'U' || x.SiglaFamiliare == 'M'));
                                    List<GestioneFamiliari.CodMaggFamiliari> listaSiglaFamiliareV = elencoCodMaggFamiliari.FindAll(x => x.IdAnagrafica == fam.IdAnagrafica && x.SiglaFamiliare == 'V');
                                    if (listaSiglaFamiliareV != null && listaSiglaFamiliareV.Count > 0 && codiciMaggiorazioniAmmissibiliPerV != null && codiciMaggiorazioniAmmissibiliPerV.Count > 0)
                                    {
                                        foreach (GestioneFamiliari.CodMaggFamiliari siglaV in listaSiglaFamiliareV)
                                        {
                                            if (codiciMaggiorazioniAmmissibiliPerV.Count(x => Utility.DataSuccessivaA(siglaV.Decorrenza.GetValueOrDefault(), x.Cessazione.GetValueOrDefault())) < 1)
                                            {
                                                messaggioVideo = "Il Codice Maggiorazione 'V' può essere registrato solo se precedentemente il familiare era identificato con: 'S', 'U', 'M'";
                                                return false;
                                            }
                                        }
                                    }
                                }
                            }
                        }
                    }
                }
            }

            return true;
        }


        /// <summary>
        /// Memo 33
        /// Il metodo esegue delle verifiche sulle decorrenze/ cessazioni dei familiari 'U', 'S', 'M', 'L' 
        /// </summary>
        /// <param name="datiPensione"></param>
        /// <param name="tipoAppartenenza"></param>
        /// <param name="familiariApp"></param>
        /// <param name="elencoCodMaggFamiliari"></param>
        /// <param name="messaggioVideo"></param>
        /// <returns></returns>
        public static bool ALL_VerificaDecorrenzaCessazioneFamiliari(GestionePensione.DatiPensione datiPensione, Utility.TipoAppartenenza? tipoAppartenenza, GestioneFamiliari.Familiare familiareApp, List<GestioneFamiliari.CodMaggFamiliari> elencoMaggiorazioniFamiliare)
        {
            DateTime dataConfronto = new DateTime(2022, 03, 01);

            if (tipoAppartenenza.HasValue)
            {
                GestioneControlliDinamici.ControlloDinamico abilitazioneMemo33 = null;
                GestioneControlliDinamici.GetControlloDinamicoByNomeControllo("AbilitazioneMemo33" + tipoAppartenenza.Value, out abilitazioneMemo33);

                if (abilitazioneMemo33 != null && !String.IsNullOrEmpty(abilitazioneMemo33.ValoreControllo) && abilitazioneMemo33.ValoreControllo.Trim().ToUpperInvariant() == "SI")
                {
                    if (familiareApp.SiglaFamiliare.GetValueOrDefault() == 'S' || familiareApp.SiglaFamiliare.GetValueOrDefault() == 'U' || familiareApp.SiglaFamiliare.GetValueOrDefault() == 'M' ||
                        familiareApp.SiglaFamiliare.GetValueOrDefault() == 'L')
                    {
                        //Gli Id delle maggiorazioni sono diverse a seconda della linea di appartenenza
                        //Per la linea FS i codici Maggiorazioni non sono gestiti
                        byte? codiceMaggiorazioneSI = null;
                        switch (tipoAppartenenza.Value)
                        {
                            case Utility.TipoAppartenenza.AGO:
                                codiceMaggiorazioneSI = 2;
                                break;
                            case Utility.TipoAppartenenza.CI:
                                codiceMaggiorazioneSI = 1;
                                break;
                        }

                        if (elencoMaggiorazioniFamiliare != null && elencoMaggiorazioniFamiliare.Count > 0)
                        {
                            if (tipoAppartenenza != Utility.TipoAppartenenza.FS)
                            {
                                List<GestioneFamiliari.CodMaggFamiliari> elencoMaggiorazioniSI = elencoMaggiorazioniFamiliare.FindAll(x => x.SiglaFamiliare == familiareApp.SiglaFamiliare && x.CodiceMaggiorazione.GetValueOrDefault() == codiceMaggiorazioneSI);
                                if (elencoMaggiorazioniSI != null && elencoMaggiorazioniSI.Count > 0)
                                {
                                    if (elencoMaggiorazioniSI.Exists(x => Utility.DataSuccessivaA(x.Decorrenza.GetValueOrDefault(), dataConfronto))
                                        || elencoMaggiorazioniSI.Exists(x => Utility.DataStrettamenteSuccessivaA(x.Cessazione.GetValueOrDefault(), dataConfronto)))
                                    {
                                        return false;
                                    }
                                }
                            }
                        }
                    }
                }
            }

            return true;
        }

        //ENG - Memo 22/2024
        public static bool ALL_VerificaPlurimeRegistrazioniConiugeUnitoCivile(GestionePensione.DatiPensione datiPensione, Utility.TipoAppartenenza? tipoAppartenenza,
            List<GestioneFamiliari.Familiare> familiariApp, List<GestioneFamiliari.CodMaggFamiliari> elencoCodMaggFamiliari, out string messaggioVideo)
        {

            messaggioVideo = string.Empty;
            GestioneControlliDinamici.ControlloDinamico ctrlMemo22_2024 = null;
            GestioneControlliDinamici.GetControlloDinamicoByNomeControllo("AbilitazioneMemo22_2024", out ctrlMemo22_2024);

            if (ctrlMemo22_2024 != null && !String.IsNullOrEmpty(ctrlMemo22_2024.ValoreControllo) && !String.IsNullOrEmpty(ctrlMemo22_2024.ValoreControllo.Trim())
                && ctrlMemo22_2024.ValoreControllo.Trim().ToUpperInvariant() == "SI")
            {
                if (!Utility.IsDomandaPensioneSuperstitiOrRicostituzione(datiPensione))
                {
                    if (familiariApp != null && familiariApp.Count > 0)
                    {
                        foreach (GestioneFamiliari.Familiare fam in familiariApp)
                        {
                            if (fam.Confermato)
                            {
                                if (fam.IsConiugeOrUnitoCivile())
                                {
                                    List<GestioneFamiliari.CodMaggFamiliari> listaMaggFam = elencoCodMaggFamiliari.FindAll(x => x.IdAnagrafica == fam.IdAnagrafica);

                                    if (listaMaggFam != null && listaMaggFam.Count > 0)
                                    {
                                        DateTime? dataFineCaricoPrecedente = null;

                                        foreach (GestioneFamiliari.CodMaggFamiliari codiceMaggiorazione in listaMaggFam)
                                        {
                                            if (tipoAppartenenza == Utility.TipoAppartenenza.FS || codiceMaggiorazione.SiglaFamiliare.HasValue && codiceMaggiorazione.SiglaFamiliare.Value == 'C')
                                            {
                                                if (codiceMaggiorazione.Decorrenza.HasValue && dataFineCaricoPrecedente.HasValue
                                                    && (Utility.DataStrettamenteSuccessivaA(codiceMaggiorazione.Decorrenza.Value, dataFineCaricoPrecedente.Value)
                                                    || !Utility.DataSuccessivaA(codiceMaggiorazione.Decorrenza.Value, dataFineCaricoPrecedente.Value)))
                                                {

                                                    messaggioVideo = "Familiare (" + fam.CodiceFiscale + "): per il grado di parentela 'C – Coniuge o Unito Civile' i periodi delle registrazioni devono essere consequenziali";
                                                    return false;
                                                }

                                                dataFineCaricoPrecedente = codiceMaggiorazione.Cessazione;
                                            }
                                        }
                                    }
                                }
                            }
                        }

                    }

                }
            }


            return true;
        }

        #endregion Familiari

        #region Titolare
        /// <summary>
        /// Verifica che la decorrenza della pensione sia uguale alla data perfezionamento requisiti + 13 mesi per una pensione di anzianità e vecchiaia
        /// </summary>
        /// <param name="datiPensione"></param>
        /// <param name="msg"></param>
        /// <returns></returns>
        public static bool ALL_VerificaPerfezRequisitiDecPensioneAnzianitaVecchiaia(GestionePensione.DatiPensione datiPensione, DateTime? DecorrenzaOriginaria, DateTime? DataPerfezionamentoRequisiti,
            char? derogaTraduzioneSuGP, bool isRiaperturaDomanda, out string msg)
        {
            msg = string.Empty;

            string Gruppo = datiPensione.Gruppo;
            string Prodotto = datiPensione.Prodotto;
            DateTime? DecorrenzaPensione = DecorrenzaOriginaria;
            DateTime? PerfezionamentoRequisiti = DataPerfezionamentoRequisiti;
            Utility.TipoAppartenenza? tipoAppartenenza = Utility.GetTipoAppartenenza(datiPensione.IndConvInt, datiPensione.Gestione);
            Utility.TipoUnicarpe tipoUnicarpe = Utility.IsDomandaUnicarpe(datiPensione, true);
            bool isGestioneSpeciale = Utility.IsGestioneSpeciale(datiPensione);

            if (!DecorrenzaPensione.HasValue || !PerfezionamentoRequisiti.HasValue || String.IsNullOrEmpty(Gruppo) || String.IsNullOrEmpty(Prodotto))
            {
                msg = "Dati obbligatori mancanti";
                return false;
            }

            TipoDecPensione? tipoDecPensione = ALL_VerificaDecPensioneProdottoForVecchiaiaOrAnzianitaSperDonna(DecorrenzaPensione, Gruppo, Prodotto, string.Empty);
            if (!tipoDecPensione.HasValue)
            {
                msg = "Dati obbligatori mancanti";
                return false;
            }

            if (tipoDecPensione.Value == TipoDecPensione.Ante2008Anzianita || tipoDecPensione.Value == TipoDecPensione.Ante2008Vecchiaia)
                return true;

            //per AGO da Unicarpe salto il controllo in caso di gestioni speciali
            if (tipoAppartenenza.HasValue && tipoAppartenenza.Value == Utility.TipoAppartenenza.AGO && (tipoUnicarpe == Utility.TipoUnicarpe.Automatica || datiPensione.IsPLUnicarpe.GetValueOrDefault()) &&
                isGestioneSpeciale)
                return true;
            //per VESO33, VESO92, VOCOOP, COOP28, VOCRED, CRED27 e per COMPARTO_SCUOLA bypassate salto il controllo
            if (!Utility.IsDomandaVESO33(datiPensione.SiglaCategoria) && !Utility.IsDomandaVESO92(datiPensione.SiglaCategoria) && !Utility.IsDomandaVOCRED_CRED27(datiPensione.SiglaCategoria) &&
                !Utility.IsDomandaVOCOOP_COOP28(datiPensione.SiglaCategoria) && !Utility.IsDomandaCumulo(datiPensione.SiglaCategoria) && !Utility.IsDomandaINPDAP(datiPensione.Gestione) &&
                !Utility.IsDomandaVESO29(datiPensione.SiglaCategoria) && !Utility.IsDomandaVOESO(datiPensione.SiglaCategoria) && !Utility.IsDomandaESOTEL(datiPensione.SiglaCategoria) &&
                !Utility.IsDomandaESOAMB(datiPensione.SiglaCategoria) && !Utility.IsDomandaESPA(datiPensione.SiglaCategoria) &&
                !ALL_VerificaPerfezRequisitiDecorPensione(datiPensione, DecorrenzaPensione, PerfezionamentoRequisiti, derogaTraduzioneSuGP, isRiaperturaDomanda, out msg))
                return false;

            return true;
        }

        /// <summary>
        /// Verifica che si tratta di una pensione di anzianità sperimentale donna
        /// </summary>
        /// <param name="datiPensione"></param>
        /// <param name="areaTitolare"></param>
        /// <param name="msg"></param>
        /// <returns></returns>
        public static bool ALL_VerificaSperimentaleDonnaTitolare(GestionePensione.DatiPensione datiPensione, Entity.AreaTitolare areaTitolare, char? derogaTraduzioneSuGP, out string msg)
        {
            msg = string.Empty;

            if (Utility.IsDomandaSperimentaleDonna(datiPensione))
            {
                GestioneCrossControls.TipoDecPensione? tipoDec = GestioneCrossControls.ALL_VerificaDecPensioneProdottoForVecchiaiaOrAnzianitaSperDonna(areaTitolare.Pensione.DecorrenzaOriginaria, datiPensione.Gruppo, datiPensione.Prodotto, datiPensione.Tipo);
                if (!tipoDec.HasValue || tipoDec.Value == GestioneCrossControls.TipoDecPensione.Ante2008AnzSpDonna)
                {
                    msg = "Decorrenza pensione anteriore al 2008 non compatibile con lo sperimentale donna";
                    return false;
                }

                if (areaTitolare.Pensione.DataPerfezionamentoRequisiti.HasValue)
                {
                    if ((DateTime.Compare(areaTitolare.Pensione.DataPerfezionamentoRequisiti.Value, new DateTime(2011, 1, 1)) >= 0 && DateTime.Compare(areaTitolare.Pensione.DataPerfezionamentoRequisiti.Value, new DateTime(2015, 1, 1)) < 0))
                    {
                        if (!GestioneCrossControls.ALL_VerificaEtaTitolareCompreso20112014SperDonna(datiPensione, areaTitolare.Pensione.DataPerfezionamentoRequisiti, areaTitolare.Anagrafica.DataNascita, out msg))
                            return false;
                    }

                    if ((DateTime.Compare(areaTitolare.Pensione.DataPerfezionamentoRequisiti.Value, new DateTime(2015, 1, 1)) >= 0))
                    {
                        if (!GestioneCrossControls.ALL_VerificaEtaTitolarePost2014AnzSpDonna(datiPensione, areaTitolare.Pensione.DataPerfezionamentoRequisiti, areaTitolare.Anagrafica.DataNascita, out msg))
                            return false;
                    }
                }
            }
            else if (Utility.IsDomandaSperimentaleDonna_DL_4_2019(datiPensione))
            {
                if (areaTitolare.Pensione.DataPerfezionamentoRequisiti.HasValue)
                {
                    if (!ALL_VerificaEtaTitolareAnzSpDonna_DL_4_2019(datiPensione, areaTitolare.Pensione.DataPerfezionamentoRequisiti, areaTitolare.Anagrafica.DataNascita, out msg))
                        return false;
                }
            }

            return true;
        }

        public static bool ALL_ControlsPerfezionamentoRequisitiSperimentaleDonna(GestionePensione.DatiPensione datiPensione, GestioneAnagrafica.DatiAnagrafici datiAnagrafici, DateTime? dataPerfezionamentoRequisiti, Utility.TipoAppartenenza? tipoAppartenenza, out string messaggioVideo)
        {
            messaggioVideo = string.Empty;
            DateTime? dataCompare = null;
            bool isIntervallo2016 = false;

            if (datiPensione == null)
                return false;

            string categoria = datiPensione.GetCodCategoria();
            int catNumerica = 0;
            int.TryParse(categoria, out catNumerica);

            if (Utility.IsDomandaSperimentaleDonna(datiPensione))
            {
                if (((IsLavoratriceDipendente(catNumerica, tipoAppartenenza, datiPensione)) && (Utility.DataSuccessivaA(datiAnagrafici.DataNascita.Value, new DateTime(1958, 10, 1)))
                                                                                          && (!Utility.DataStrettamenteSuccessivaA(datiAnagrafici.DataNascita.Value, new DateTime(1958, 12, 31))))
                   || ((!IsLavoratriceDipendente(catNumerica, tipoAppartenenza, datiPensione)) && (Utility.DataSuccessivaA(datiAnagrafici.DataNascita.Value, new DateTime(1957, 10, 1)))
                                                                                          && (!Utility.DataStrettamenteSuccessivaA(datiAnagrafici.DataNascita.Value, new DateTime(1957, 12, 31)))))
                {
                    dataCompare = new DateTime(2016, 7, 31);
                    isIntervallo2016 = true;
                }
                else
                    dataCompare = new DateTime(2015, 12, 31);
            }
            else if (Utility.IsDomandaSperimentaleDonna_DL_4_2019(datiPensione))
            {
                GestioneControlliDinamici.ControlloDinamico ctrl = null;
                GestioneControlliDinamici.GetControlloDinamicoByNomeControllo("DataControlloSperimantaleDonna_DL_4_2019", out ctrl);
                if (ctrl != null)
                    dataCompare = Utility.DataFromString(ctrl.ValoreControllo, Utility.FormatoData.AAAAmmGG);
                else
                    dataCompare = new DateTime(2019, 12, 31);
            }

            if (dataPerfezionamentoRequisiti.HasValue)
            {
                if (dataCompare.HasValue && Utility.DataStrettamenteSuccessivaA(dataPerfezionamentoRequisiti.Value, dataCompare.Value))
                {
                    messaggioVideo = String.Format("La data perfezionamento requisiti non può essere successiva al {0:dd/MM/yyyy}", dataCompare.Value);
                    return false;
                }
                if (isIntervallo2016 && !Utility.DataSuccessivaA(dataPerfezionamentoRequisiti.Value, new DateTime(2016, 1, 1)))
                {
                    messaggioVideo = String.Format("La data perfezionamento non può essere antecedente al  {0:dd/MM/yyyy}", new DateTime(2016, 1, 1));
                    return false;
                }
            }

            return true;
        }

        public static bool ALL_ControlsDecorrenzaOriginariaOpzioneDonna_Legge197_2022_Art1_Comma292(GestionePensione.DatiPensione datiPensione, DateTime? decorrenzaOriginaria, DateTime? dataPerfezionamentoRequisiti, Utility.TipoAppartenenza? tipoAppartenenza, out string messaggioVideo)
        {
            messaggioVideo = string.Empty;
            DateTime? dataLimiteInf = null;
            Utility.TipoFondo? tipoFondo = Utility.GetTipoFondoByCategoria(datiPensione.IndConvInt, datiPensione.Gestione, datiPensione.SiglaCategoria);

            //ENG - Appunto 13_2023 OpzioneDonna2023_2024
            int anno = 2023;
            GestioneControlliDinamici.ControlloDinamico ctrl = null;
            GestioneControlliDinamici.GetControlloDinamicoByNomeControllo("OpzioneDonna2023_2024", out ctrl);
            if (dataPerfezionamentoRequisiti.HasValue && ctrl != null && ctrl.ValoreControllo.ToUpperInvariant() == "SI" &&
                    Utility.DataStrettamenteSuccessivaA(dataPerfezionamentoRequisiti.Value, new DateTime(2022, 12, 31)) &&
                    Utility.DataStrettamenteSuccessivaA(new DateTime(2024, 01, 01), dataPerfezionamentoRequisiti.Value))
            {
                anno = 2024;
            }

            if (datiPensione == null)
                return false;

            if (Utility.IsOpzioneDonna_Legge197_2022_Art1_Comma292_LetteraA(datiPensione, true, true) || Utility.IsOpzioneDonna_Legge197_2022_Art1_Comma292_LetteraB(datiPensione, true, true) ||
                Utility.IsOpzioneDonna_Legge197_2022_Art1_Comma292_LetteraC(datiPensione, true, true))
            {
                if (tipoAppartenenza == Utility.TipoAppartenenza.FS && (Utility.IsDomandaINPDAP(datiPensione.Gestione) || (tipoFondo.HasValue && (tipoFondo == Utility.TipoFondo.FS || tipoFondo == Utility.TipoFondo.PT))))
                    dataLimiteInf = new DateTime(anno, 01, 02);
                else
                    dataLimiteInf = new DateTime(anno, 02, 01);

                //ENG - INPDAP Comparto Scuola (Ente 32) / AFAM (Ente 33)
                if (tipoAppartenenza == Utility.TipoAppartenenza.FS && Utility.IsDomandaINPDAP(datiPensione.Gestione) && datiPensione.Fondo == "002" && (datiPensione.Ente == "32" || datiPensione.Ente == "33"))
                {
                    if (!Utility.IsDomandaAutomatica(datiPensione))
                    {
                        if (datiPensione.Ente == "32" && (decorrenzaOriginaria.GetValueOrDefault().Month != 9 || decorrenzaOriginaria.GetValueOrDefault().Day != 1))
                        {
                            messaggioVideo = string.Format("La Decorrenza Originaria deve essere pari al 1 Settembre");
                            return false;
                        }

                        if (datiPensione.Ente == "33" && (decorrenzaOriginaria.GetValueOrDefault().Month != 11 || decorrenzaOriginaria.GetValueOrDefault().Day != 1))
                        {
                            messaggioVideo = string.Format("La Decorrenza Originaria deve essere pari al 1 Novembre");
                            return false;
                        }
                    }
                }
                else
                {
                    if (dataLimiteInf.HasValue && decorrenzaOriginaria.HasValue)
                    {
                        if (!Utility.DataSuccessivaA(decorrenzaOriginaria.Value, dataLimiteInf.Value))
                        {
                            messaggioVideo = "La decorrenza pensione non può essere minore della data " + String.Format("{0:dd/MM/yyyy}", dataLimiteInf);
                            return false;
                        }
                    }

                    if (tipoAppartenenza == Utility.TipoAppartenenza.FS &&
                        (Utility.IsDomandaINPDAP(datiPensione.Gestione) || (tipoFondo.HasValue && (tipoFondo == Utility.TipoFondo.FS || tipoFondo == Utility.TipoFondo.PT || tipoFondo == Utility.TipoFondo.EL))))
                    {
                        if (decorrenzaOriginaria.HasValue && Utility.DataSuccessivaA(datiPensione.DataPresentazioneDomanda, decorrenzaOriginaria.Value))
                        {
                            messaggioVideo = "La decorrenza pensione non può essere precedente alla data presentazione";
                            return false;
                        }
                    }
                }

                if (!GestioneCrossControls.ALL_ControlsPerfezionamentoRequisitiOpzioneDonna_Legge197_2022_Art1_Comma292(datiPensione, dataPerfezionamentoRequisiti, out messaggioVideo))
                    return false;

                if (!(Utility.IsDomandaUnicarpe(datiPensione, true) == Utility.TipoUnicarpe.Automatica || datiPensione.IsPLUnicarpe.GetValueOrDefault()))
                {
                    string strCatNum = datiPensione.GetCodCategoria();
                    int catNum;
                    int.TryParse(strCatNum, out catNum);

                    // La decorrenza della pensione deve essere maggiore o uguale di 12 mesi per la gestione AGO (VO, INPGI, VDAI, VOP), CI(VOS), FS, ENPALS e GDP
                    if (catNum == 1 || catNum == 4 || catNum == 82 || catNum == 243 || catNum == 7 || tipoAppartenenza == Utility.TipoAppartenenza.FS || Utility.IsDomandaENPALS(datiPensione.Gestione) || Utility.IsDomandaINPDAP(datiPensione.Gestione))
                    {
                        // La decorrenza deve partire dalla data perfezionamento requisiti + 12 mesi
                        DateTime dateCompare = dataPerfezionamentoRequisiti.Value.AddMonths(12).AddDays(1);
                        if (decorrenzaOriginaria.Value.CompareTo(dateCompare) < 0)
                        {
                            messaggioVideo = "Attenzione non è soddisfatta la finestra temporale di 12 mesi.";
                            return false;
                        }
                    }
                    // La decorrenza della pensione deve essere maggiore o uguale di 18 mesi per la gestione Autonoma
                    else
                    {
                        // La decorrenza deve partire dalla data perfezionamento requisiti + 18 mesi
                        DateTime dateCompare = dataPerfezionamentoRequisiti.Value.AddMonths(18).AddDays(1);
                        if (decorrenzaOriginaria.Value.CompareTo(dateCompare) < 0)
                        {
                            messaggioVideo = "Attenzione non è soddisfatta la finestra temporale di 18 mesi.";
                            return false;
                        }
                    }
                }
            }

            return true;
        }

        public static bool ALL_ControlsPerfezionamentoRequisitiOpzioneDonna_Legge197_2022_Art1_Comma292(GestionePensione.DatiPensione datiPensione, DateTime? dataPerfezionamentoRequisiti, out string messaggioVideo)
        {
            messaggioVideo = string.Empty;
            DateTime? dataCompare = null;

            if (datiPensione == null)
                return false;

            if (Utility.IsOpzioneDonna_Legge197_2022_Art1_Comma292_LetteraA(datiPensione, true, true) || Utility.IsOpzioneDonna_Legge197_2022_Art1_Comma292_LetteraB(datiPensione, true, true) ||
                Utility.IsOpzioneDonna_Legge197_2022_Art1_Comma292_LetteraC(datiPensione, true, true))
            {
                GestioneControlliDinamici.ControlloDinamico ctrl = null;
                GestioneControlliDinamici.GetControlloDinamicoByNomeControllo("DataControlloOpzioneDonna_2023", out ctrl);
                if (ctrl != null)
                    dataCompare = Utility.DataFromString(ctrl.ValoreControllo, Utility.FormatoData.AAAAmmGG);
                else
                    dataCompare = new DateTime(2022, 12, 31);
            }

            if (dataPerfezionamentoRequisiti.HasValue)
            {
                //Eng - Il messaggio non deve essere bloccante Segnalazione 31811
                if (!Utility.IsDomandaVOPGI(datiPensione.SiglaCategoria) && !Utility.DataSuccessivaA(dataPerfezionamentoRequisiti.Value, new DateTime(2022, 01, 01)))
                {
                    messaggioVideo = String.Format("ATTENZIONE: collocandosi la data perfezionamento requisiti nell’anno 2021, verificare se risultano perfezionati i requisiti per l’accesso alla pensione di cui all’articolo 16, comma 1, del d.l. n. 4/2019 convertito dalla l. n. 26/2019. In tal caso contattare l’interessata come indicato nel messaggio Hermes n. 1611/2023");
                    return true;
                }

                if (dataCompare.HasValue && Utility.DataStrettamenteSuccessivaA(dataPerfezionamentoRequisiti.Value, dataCompare.Value))
                {
                    messaggioVideo = String.Format("La data perfezionamento requisiti non può essere successiva al {0:dd/MM/yyyy}", dataCompare.Value);
                    return false;
                }
            }

            return true;
        }

        public static bool ALL_VerificaRequisitoEtaOpzioneDonna_Legge197_2022_Art1_Comma292(GestionePensione.DatiPensione datiPensione, DateTime? dataPerfezionamentoRequisiti, byte? numeroFigli, GestioneAnagrafica.DatiAnagrafici datiAnagrafici, out string messaggioVideo)
        {
            messaggioVideo = string.Empty;

            if (datiPensione == null)
                return false;
            //ENG - memo 13 - opzionedonna2023 ddlFigli valorizzabile da view
            if (dataPerfezionamentoRequisiti.HasValue)
            {
                //ENG - Appunto 13_2023 OpzioneDonna2023_2024
                int anno = 0;
                int scostamento = 0;
                GestioneControlliDinamici.ControlloDinamico ctrl = null;
                GestioneControlliDinamici.GetControlloDinamicoByNomeControllo("OpzioneDonna2023_2024", out ctrl);

                if (ctrl != null && ctrl.ValoreControllo.ToUpperInvariant() == "SI" &&
                    Utility.DataStrettamenteSuccessivaA(dataPerfezionamentoRequisiti.Value, new DateTime(2022, 12, 31)) &&
                    Utility.DataStrettamenteSuccessivaA(new DateTime(2025, 01, 01), dataPerfezionamentoRequisiti.Value))
                {
                    scostamento = 1;
                }
                if (Utility.IsOpzioneDonna_Legge197_2022_Art1_Comma292_LetteraA(datiPensione, true, true) || Utility.IsOpzioneDonna_Legge197_2022_Art1_Comma292_LetteraB(datiPensione, true, true))
                {
                    if (!numeroFigli.HasValue || numeroFigli == 0)
                    {
                        anno = 60 + scostamento;
                        if (Utility.DataStrettamenteSuccessivaA(datiAnagrafici.DataNascita.Value.AddYears(anno), dataPerfezionamentoRequisiti.Value))
                        {
                            messaggioVideo = string.Format("Alla data perfezionamento requisiti ({0:dd/MM/yyyy}) non è stato raggiunto il requisito di età di {1} anni", dataPerfezionamentoRequisiti.Value, anno);
                            return false;
                        }
                    }
                    else if (numeroFigli == 1)
                    {
                        anno = 59 + scostamento;
                        if (Utility.DataStrettamenteSuccessivaA(datiAnagrafici.DataNascita.Value.AddYears(anno), dataPerfezionamentoRequisiti.Value))
                        {
                            messaggioVideo = string.Format("Alla data perfezionamento requisiti ({0:dd/MM/yyyy}) non è stato raggiunto il requisito di età di {1} anni", dataPerfezionamentoRequisiti.Value, anno);
                            return false;
                        }
                    }
                    else if (numeroFigli > 1)
                    {
                        anno = 58 + scostamento;
                        if (Utility.DataStrettamenteSuccessivaA(datiAnagrafici.DataNascita.Value.AddYears(anno), dataPerfezionamentoRequisiti.Value))
                        {
                            messaggioVideo = string.Format("Alla data perfezionamento requisiti ({0:dd/MM/yyyy}) non è stato raggiunto il requisito di età di {1} anni", dataPerfezionamentoRequisiti.Value, anno);
                            return false;
                        }
                    }
                }
                else if (Utility.IsOpzioneDonna_Legge197_2022_Art1_Comma292_LetteraC(datiPensione, true, true))
                {
                    anno = 58 + scostamento;
                    if (Utility.DataStrettamenteSuccessivaA(datiAnagrafici.DataNascita.Value.AddYears(anno), dataPerfezionamentoRequisiti.Value))
                    {
                        messaggioVideo = string.Format("Alla data perfezionamento requisiti ({0:dd/MM/yyyy}) non è stato raggiunto il requisito di età di {1} anni", dataPerfezionamentoRequisiti.Value, anno);
                        return false;
                    }
                }
            }

            return true;
        }

        private static bool ALL_VerificaEtaTitolareCompreso20112014SperDonna(GestionePensione.DatiPensione datiPensione, DateTime? DataPerfezionamentoRequisiti, DateTime? dataNascitaTitolare,
            out string msgVideo)
        {
            msgVideo = string.Empty;

            if (!DataPerfezionamentoRequisiti.HasValue || !dataNascitaTitolare.HasValue)
            {
                msgVideo = "Data Perferzionamento Requisiti e Data Nascita Titolare obbligatori";
                return false;
            }

            string strCatNum = datiPensione.GetCodCategoria();
            int catNum;
            int.TryParse(strCatNum, out catNum);

            Utility.TipoAppartenenza? tipoAppartenenza = Utility.GetTipoAppartenenza(datiPensione.IndConvInt, datiPensione.Gestione);

            // La decorrenza della pensione deve essere maggiore di 12 mesi per la gestione AGO (VO, VOS, VDAI) e FS
            if (catNum == 1 || catNum == 4 || catNum == 82 || tipoAppartenenza == Utility.TipoAppartenenza.FS || Utility.IsDomandaENPALS(datiPensione.Gestione))
            {
                if (Utility.DataStrettamenteSuccessivaA(dataNascitaTitolare.Value.AddYears(57), DataPerfezionamentoRequisiti.Value))
                {
                    msgVideo = string.Format("Età del titolare inferiore a 57 anni al {0:dd/MM/yyyy}.", DataPerfezionamentoRequisiti.Value);
                    return false;
                }
            }
            else
            {
                if (Utility.DataStrettamenteSuccessivaA(dataNascitaTitolare.Value.AddYears(58), DataPerfezionamentoRequisiti.Value))
                {
                    msgVideo = string.Format("Età del titolare inferiore a 58 anni al {0:dd/MM/yyyy}.", DataPerfezionamentoRequisiti.Value);
                    return false;
                }
            }
            return true;
        }

        private static bool ALL_VerificaEtaTitolarePost2014AnzSpDonna(GestionePensione.DatiPensione datiPensione, DateTime? DataPerfezionamentoRequisiti, DateTime? dataNascitaTitolare, out string msgVideo)
        {
            msgVideo = string.Empty;

            if (!DataPerfezionamentoRequisiti.HasValue || !dataNascitaTitolare.HasValue)
            {
                msgVideo = "Data Perferzionamento Requisiti e Data Nascita Titolare obbligatori";
                return false;
            }

            string strCatNum = datiPensione.GetCodCategoria();
            int catNum;
            int.TryParse(strCatNum, out catNum);

            Utility.TipoAppartenenza? tipoAppartenenza = Utility.GetTipoAppartenenza(datiPensione.IndConvInt, datiPensione.Gestione);

            // La decorrenza della pensione deve essere maggiore di 12 mesi per la gestione AGO (VO, VOS, VDAI) e FS
            if (catNum == 1 || catNum == 4 || catNum == 82 || tipoAppartenenza == Utility.TipoAppartenenza.FS || Utility.IsDomandaENPALS(datiPensione.Gestione))
            {
                //Lavoratrici dipendenti nate dal 01/01/1958 fino al 30/09/1958
                if (!Utility.DataStrettamenteSuccessivaA(dataNascitaTitolare.Value, new DateTime(1958, 9, 30)))
                {
                    if (!Utility.DataSuccessivaA(DataPerfezionamentoRequisiti.Value, dataNascitaTitolare.Value.AddYears(57).AddMonths(3)))
                    {
                        msgVideo = "Attenzione non è soddisfatto il requisito di 57 anni e 3 mesi.";
                        return false;
                    }
                }
                else

                    //Lavoratrici dipendenti nate dal 01/10/1958 fino al 31/12/1958
                    if (!Utility.DataStrettamenteSuccessivaA(dataNascitaTitolare.Value, new DateTime(1958, 12, 31)))
                    {
                        if (!Utility.DataSuccessivaA(DataPerfezionamentoRequisiti.Value, dataNascitaTitolare.Value.AddYears(57).AddMonths(7)))
                        {
                            msgVideo = "Attenzione non è soddisfatto il requisito di 57 anni e 7 mesi.";
                            return false;
                        }
                    }
            }
            else
            {
                //Lavoratrici autonome nate dal 01/01/1957 fino al 30/09/1957
                if (!Utility.DataStrettamenteSuccessivaA(dataNascitaTitolare.Value, new DateTime(1957, 9, 30)))
                {
                    if (!Utility.DataSuccessivaA(DataPerfezionamentoRequisiti.Value, dataNascitaTitolare.Value.AddYears(58).AddMonths(3)))
                    {
                        msgVideo = "Attenzione non è soddisfatto il requisito di 58 anni e 3 mesi.";
                        return false;
                    }
                }
                else
                    //Lavoratrici autonome nate dal 01/10/1957 fino al 31/12/1957
                    if (!Utility.DataStrettamenteSuccessivaA(dataNascitaTitolare.Value, new DateTime(1957, 12, 31)))
                    {
                        if (!Utility.DataSuccessivaA(DataPerfezionamentoRequisiti.Value, dataNascitaTitolare.Value.AddYears(58).AddMonths(7)))
                        {
                            msgVideo = "Attenzione non è soddisfatto il requisito di 58 anni e 7 mesi.";
                            return false;
                        }
                    }
            }

            return true;
        }

        private static bool ALL_VerificaEtaTitolareAnzSpDonna_DL_4_2019(GestionePensione.DatiPensione datiPensione, DateTime? DataPerfezionamentoRequisiti, DateTime? dataNascitaTitolare, out string msgVideo)
        {
            msgVideo = string.Empty;

            if (!DataPerfezionamentoRequisiti.HasValue || !dataNascitaTitolare.HasValue)
            {
                msgVideo = "Data Perferzionamento Requisiti e Data Nascita Titolare obbligatori";
                return false;
            }

            string strCatNum = datiPensione.GetCodCategoria();
            int catNum;
            int.TryParse(strCatNum, out catNum);

            Utility.TipoAppartenenza? tipoAppartenenza = Utility.GetTipoAppartenenza(datiPensione.IndConvInt, datiPensione.Gestione);

            if (catNum == 1 || catNum == 4 || catNum == 82 || catNum == 7 || tipoAppartenenza == Utility.TipoAppartenenza.FS || Utility.IsDomandaENPALS(datiPensione.Gestione)
                || (Utility.IsDomandaINPDAP(datiPensione.Gestione) && Utility.IsDomandaUnicarpe(datiPensione, true) != Utility.TipoUnicarpe.Automatica))
            {
                //Lavoratrici dipendenti
                if (!Utility.DataSuccessivaA(DataPerfezionamentoRequisiti.Value, dataNascitaTitolare.Value.AddYears(58)))
                {
                    msgVideo = "Attenzione non è soddisfatto il requisito di 58 anni.";
                    return false;
                }
            }
            else
            {
                //Lavoratrici autonome
                if (!Utility.DataSuccessivaA(DataPerfezionamentoRequisiti.Value, dataNascitaTitolare.Value.AddYears(59)))
                {
                    msgVideo = "Attenzione non è soddisfatto il requisito di 59 anni.";
                    return false;
                }
            }

            return true;
        }

        public static TipoDecPensione? ALL_VerificaDecPensioneProdottoForVecchiaiaOrAnzianitaSperDonna(DateTime? DecorrenzaPensione, string Gruppo, string Prodotto, string Tipo)
        {
            TipoDecPensione tipoDecPensione = new TipoDecPensione();

            if (!DecorrenzaPensione.HasValue || String.IsNullOrEmpty(Gruppo) || String.IsNullOrEmpty(Prodotto))
                return null;

            if (Gruppo.Trim() != "0001")
                tipoDecPensione = TipoDecPensione.ByPass;

            DateTime duemilaotto = new DateTime(2008, 01, 01);
            DateTime duemilaundici = new DateTime(2011, 01, 01);
            DateTime febbraioDuemiladodici = new DateTime(2012, 02, 01);
            DateTime duemilasedici = new DateTime(2016, 01, 01);


            switch (Prodotto.Trim())
            {
                case "0002": // vecchiaia
                    if (DateTime.Compare(DecorrenzaPensione.Value, duemilaotto) < 0)
                        tipoDecPensione = TipoDecPensione.Ante2008Vecchiaia;
                    else if (DateTime.Compare(DecorrenzaPensione.Value, duemilaotto) >= 0 && DateTime.Compare(DecorrenzaPensione.Value, duemilaundici) < 0)
                        tipoDecPensione = TipoDecPensione.Compreso0810Vecchiaia;
                    else if (DateTime.Compare(DecorrenzaPensione.Value, duemilaundici) >= 0 && DateTime.Compare(DecorrenzaPensione.Value, febbraioDuemiladodici) <= 0)
                        tipoDecPensione = TipoDecPensione.Compreso11Febb12Vecchiaia;
                    else if (DateTime.Compare(DecorrenzaPensione.Value, febbraioDuemiladodici) > 0)
                        tipoDecPensione = TipoDecPensione.PostFebb2012Vecchiaia;
                    break;
                case "0001": // anzianità

                    if (Tipo.Trim() == "0050") // sperimentale donna
                    {
                        if (DateTime.Compare(DecorrenzaPensione.Value, duemilaotto) < 0)
                            tipoDecPensione = TipoDecPensione.Ante2008AnzSpDonna;
                        else if (DateTime.Compare(DecorrenzaPensione.Value, duemilaotto) >= 0 && DateTime.Compare(DecorrenzaPensione.Value, duemilaundici) < 0)
                            tipoDecPensione = TipoDecPensione.Compreso0810AnzSpDonna;
                        else if (DateTime.Compare(DecorrenzaPensione.Value, duemilaundici) >= 0 && DateTime.Compare(DecorrenzaPensione.Value, duemilasedici) < 0)
                            tipoDecPensione = TipoDecPensione.Compreso1115AnzSpDonna;
                        else if (DateTime.Compare(DecorrenzaPensione.Value, duemilasedici) >= 0)
                            tipoDecPensione = TipoDecPensione.Post2015AnzSpDonna;
                    }
                    else
                    {
                        if (DateTime.Compare(DecorrenzaPensione.Value, duemilaotto) < 0)
                            tipoDecPensione = TipoDecPensione.Ante2008Anzianita;
                        else
                            tipoDecPensione = TipoDecPensione.Post2008Anzianita;
                    }
                    break;
                default:
                    tipoDecPensione = TipoDecPensione.ByPass;
                    break;
            }

            return tipoDecPensione;
        }

        /// <summary>
        /// Verifica coerenza stati civili
        /// </summary>
        /// <param name="datiPensione"></param>
        /// <returns></returns>
        public static bool ALL_VerificaStatiCivili(DateTime? decorrenzaOriginaria, GestionePensione.DatiPensione datiPensione, List<GestioneAnagrafica.DatiStatoCivile> listaStatiCivili,
            List<GestioneFamiliari.Familiare> listaFamiliari, List<GestioneAnagrafica.DatiAnagrafici> listaAnagraficheFamiliari, List<GestioneFamiliari.CodMaggFamiliari> elencoCodMaggFamiliari,
            DateTime? dataNascita, DateTime? dataMatrimonioDC, char? sessoTitolare, char? sessoDanteCausa, string codiceFiscaleTitolare, DateTime dataSistema, out string messaggioVideo)
        {
            messaggioVideo = string.Empty;

            Utility.TipoDomanda tipoDomanda = Utility.GetTipoDomanda(datiPensione.Gruppo, datiPensione.Prodotto);
            Utility.TipoAppartenenza? tipoAppartenenza = Utility.GetTipoAppartenenza(datiPensione.IndConvInt, datiPensione.Gestione);

            if (listaStatiCivili == null || listaStatiCivili.Count == 0)
            {
                messaggioVideo = "Attenzione! E' obbligatorio inserire almeno uno stato civile.";
                return false;
            }

            foreach (GestioneAnagrafica.DatiStatoCivile sc in listaStatiCivili)
            {
                if (!sc.Decorrenza.HasValue)
                {
                    messaggioVideo = "Attenzione! E' obbligatorio inserire tutte le Decorrenze Stato Civile.";
                    return false;
                }

                if (!Utility.IsDomandaINPDAP(datiPensione.Gestione) && Utility.DataStrettamenteSuccessivaA(sc.Decorrenza.Value, dataSistema.AddMonths(1)))
                {
                    messaggioVideo = "La decorrenza dello stato civile non può essere posteriore al mese in corso + 1";
                    return false;
                }

                if (tipoDomanda == Utility.TipoDomanda.Superstiti)
                {
                    if (listaFamiliari.Exists(x => x.CodiceFiscale == codiceFiscaleTitolare && x.IsConiugeOrUnitoCivile()))
                    {
                        if (sc.Codice != '3' && sc.Codice != 'C')
                        {
                            messaggioVideo = "Nel caso di coniuge o unito/a civile del dante causa è possibile inserire soltanto gli stati civili VEDOVO/A e VEDOVO/A DA UNIONE CIVILE.";
                            return false;
                        }
                    }
                    else if (listaFamiliari.Exists(x => x.CodiceFiscale == codiceFiscaleTitolare && x.IsAscendenteOrGenitore()))
                    {
                        if (sc.Codice != '1' && sc.Codice != '3' && sc.Codice != 'C' && sc.Codice != '2' && sc.Codice != '7')
                        {
                            messaggioVideo = "Nel caso di ascendente/genitore del dante causa è possibile inserire soltanto gli stati civili CELIBE/NUBILE, CONIUGATO/A, UNITO/A CIVILMENTE, VEDOVO/A e VEDOVO/A DA UNIONE CIVILE.";
                            return false;
                        }
                    }
                    else if (listaFamiliari.Exists(x => x.CodiceFiscale == codiceFiscaleTitolare && x.IsExConiugeOrScioltoDallUnione()))
                    {
                        if (sc.Codice != '5' && sc.Codice != '8')
                        {
                            messaggioVideo = "Nel caso di ex-coniuge del dante causa è possibile inserire soltanto gli stati civili DIVORZIATO/A e SCIOLTO/A DALL'UNIONE.";
                            return false;
                        }
                    }
                    else
                    {
                        if (sc.Codice != '1' && sc.Codice != '3' && sc.Codice != 'C')
                        {
                            messaggioVideo = "Nel caso di familiare del dante causa è possibile inserire soltanto gli stati civili CELIBE/NUBILE, VEDOVO/A e VEDOVO/A DA UNIONE CIVILE.";
                            return false;
                        }
                    }
                }
            }

            listaStatiCivili.Sort(delegate
                (GestioneAnagrafica.DatiStatoCivile c1, GestioneAnagrafica.DatiStatoCivile c2)
            { return c1.Decorrenza.Value.CompareTo(c2.Decorrenza); });

            if (!decorrenzaOriginaria.HasValue)
            {
                messaggioVideo = "Attenzione! Salvare la Decorrenza Pensione prima di procedere con il salvataggio dello Stato Civile";
                return false;
            }

            if (listaStatiCivili[0].Decorrenza.HasValue)
            {
                string certificato = datiPensione.NCertificato.HasValue ? datiPensione.NCertificato.Value.ToString().PadLeft(8, '0') : "00000000";

                //Se trattasi di Pensione Indiretta (PDIRSUP = 1) la Decorrenza (RASTDEC) del 1° elemento della Tabella dello 
                //Stato Civile (RASTATOCIV) deve essere uguale o minore alla Decorrenza Originaria (RAU104) e comunque non inferiore alla data di nascita (RADANAS)
                if (tipoDomanda == Utility.TipoDomanda.Superstiti ||
                    (datiPensione.SiglaCategoria == "PMO" && (certificato.Substring(2, 1) == "3" || certificato.Substring(2, 1) == "6")))
                {
                    if (Utility.DataStrettamenteSuccessivaA(listaStatiCivili[0].Decorrenza.Value, decorrenzaOriginaria.Value))
                    {
                        messaggioVideo = "La decorrenza dello stato civile più remota deve essere uguale o minore alla decorrenza originaria";
                        return false;
                    }
                    if (!Utility.DataSuccessivaA(listaStatiCivili[0].Decorrenza.Value, dataNascita.Value))
                    {
                        messaggioVideo = "La decorrenza dello stato civile più remota deve essere non inferiore alla data di nascita";
                        return false;
                    }
                }
                //Se trattasi di Pensione Diretta (PDIRSUP = 0) la Decorrenza (RASTDEC) del 1° elemento della Tabella dello 
                //Stato Civile (RASTATOCIV) deve essere uguale alla Decorrenza Originaria (RAU104)
                else
                {
                    DateTime? decorrenzaStatoCivile = Utility.DataFromInt(listaStatiCivili[0].Decorrenza.Value.Year, listaStatiCivili[0].Decorrenza.Value.Month, 01);
                    DateTime? decorrenzaOriginariaFirstDay = Utility.DataFromInt(decorrenzaOriginaria.Value.Year, decorrenzaOriginaria.Value.Month, 01);

                    if (decorrenzaStatoCivile.HasValue && decorrenzaOriginariaFirstDay.HasValue && (Utility.DataStrettamenteSuccessivaA(decorrenzaStatoCivile.Value, decorrenzaOriginariaFirstDay.Value) ||
                                !Utility.DataSuccessivaA(decorrenzaStatoCivile.Value, decorrenzaOriginariaFirstDay.Value)))
                    {
                        string strDecorrenza = "decorrenza originaria";

                        if (Utility.IsDomandaVESO33(datiPensione.SiglaCategoria) || Utility.IsDomandaVESO92(datiPensione.SiglaCategoria) || Utility.IsDomandaVOCRED_CRED27(datiPensione.SiglaCategoria) ||
                            Utility.IsDomandaVOCOOP_COOP28(datiPensione.SiglaCategoria) || Utility.IsDomandaVESO29(datiPensione.SiglaCategoria) || Utility.IsDomandaVOESO(datiPensione.SiglaCategoria) ||
                            Utility.IsDomandaESOTEL(datiPensione.SiglaCategoria) || Utility.IsDomandaESOAMB(datiPensione.SiglaCategoria))
                            strDecorrenza = "decorrenza dell'assegno";

                        messaggioVideo = string.Format("La decorrenza dello stato civile più remota deve essere uguale alla {0}", strDecorrenza);
                        return false;
                    }
                }
            }
            for (int i = 0; i < listaStatiCivili.Count - 1; i++)
            {
                if (!listaStatiCivili[i].Decorrenza.HasValue || !listaStatiCivili[i + 1].Decorrenza.HasValue)
                {
                    messaggioVideo = "La decorrenza dello stato civile è obbligatoria.";
                    return false;
                }

                if (listaStatiCivili[i].Codice == '0')
                {
                    messaggioVideo = "Lo Stato Civile è obbligatorio";
                    return false;
                }

                if (!Utility.DataSuccessivaA(listaStatiCivili[i].Decorrenza.Value, new DateTime(dataNascita.Value.Year, dataNascita.Value.Month, 1)))
                {
                    messaggioVideo = "La decorrenza dello stato civile non può essere inferiore alla data di nascita del titolare";
                    return false;
                }

                //Il Codice che segue non può essere uguale al precedente 
                if (listaStatiCivili[i].Codice == listaStatiCivili[i + 1].Codice)
                {
                    messaggioVideo = "Non è possibile inserire stati civili uguali in stretta successione cronologica";
                    return false;
                }

                //Se il Codice Stato Civile è = a 1 il successivo può essere soltanto 2 
                if (listaStatiCivili[i].Codice == '1' && listaStatiCivili[i + 1].Codice != '2' && listaStatiCivili[i + 1].Codice != '7')
                {
                    messaggioVideo = "Dopo aver inserito lo stato civile Celibe/Nubile, cronologicamente è possibile inserire solo lo stato civile Coniugato/a o Unito/a civilmente.";
                    return false;
                }

                //Se il Codice Stato Civile è = a 2 il successivo può essere 3, 4 5 
                if ((listaStatiCivili[i].Codice == '2' || listaStatiCivili[i].Codice == '7') && listaStatiCivili[i + 1].Codice == '1')
                {
                    messaggioVideo = "Dopo aver inserito lo stato civile Coniugato/a o Unito/a civilmente, cronologicamente non è possibile inserire lo stato civile Celibe/Nubile";
                    return false;
                }

                //Se il Codice Stato Civile è = a 3 il successivo può essere soltanto 2 
                if ((listaStatiCivili[i].Codice == '3' || listaStatiCivili[i].Codice == 'C') && listaStatiCivili[i + 1].Codice != '2' && listaStatiCivili[i + 1].Codice != '7')
                {
                    messaggioVideo = "Dopo aver inserito lo stato civile Vedovo/a o Vedovo/a da unione civile, cronologicamente è possibile inserire solo lo stato civile Coniugato/a o Unito/a civilmente.";
                    return false;
                }

                //Se il Codice Stato Civile è = a 4 il successivo può essere 3, 5 
                if (listaStatiCivili[i].Codice == '4' && listaStatiCivili[i + 1].Codice != '3' && listaStatiCivili[i + 1].Codice != '5')
                {
                    messaggioVideo = "Dopo aver inserito lo stato civile Separato/a, cronologicamente è possibile inserire solo lo stato civile Vedovo/a oppure Divorziato/a ";
                    return false;
                }

                //Se il Codice Stato Civile è = a 5 il successivo può essere soltanto 2 
                if ((listaStatiCivili[i].Codice == '5' || listaStatiCivili[i].Codice == '8') && listaStatiCivili[i + 1].Codice != '2' && listaStatiCivili[i + 1].Codice != '7')
                {
                    messaggioVideo = "Dopo aver inserito lo stato civile Divorziato/a o Sciolto/a dall'unione, cronologicamente è possibile inserire solo lo stato civile Coniugato/a o Unito/a civilmente.";
                    return false;
                }

                //Se il Codice Stato Civile è = a 5 il successivo può essere soltanto 2 
                if (listaStatiCivili[i].Codice == '2' && (listaStatiCivili[i + 1].Codice == '7' || listaStatiCivili[i + 1].Codice == '8' || listaStatiCivili[i + 1].Codice == 'C'))
                {
                    messaggioVideo = "Dopo aver inserito lo stato civile Coniugato/a, cronologicamente non è possibile inserire solo lo stato civile Unito/a civilmente, Sciolto/a dall'unione o Vedovo/a da unione civile.";
                    return false;
                }

                //Se il Codice Stato Civile è = a 5 il successivo può essere soltanto 2 
                if (listaStatiCivili[i].Codice == '7' && (listaStatiCivili[i + 1].Codice == '2' || listaStatiCivili[i + 1].Codice == '3' || listaStatiCivili[i + 1].Codice == '4' || listaStatiCivili[i + 1].Codice == '5'))
                {
                    messaggioVideo = "Dopo aver inserito lo stato civile Unito/a civilmente, cronologicamente non è possibile inserire solo lo stato civile Coniugato/a, Separato/a, Divorziato/a o Vedovo/a.";
                    return false;
                }

                //Le decorrenze in tabella devono essere cronologiche
                if (Utility.DataSuccessivaA(listaStatiCivili[i].Decorrenza.Value, listaStatiCivili[i + 1].Decorrenza.Value))
                {
                    messaggioVideo = "Le decorrenze degli stati civili devono essere cronologiche (dalla più remota alla più recente)";
                    return false;
                }

                //Le decorrenze non possono essere superiori al mese ed anno del Sistema 
                if (Utility.DataStrettamenteSuccessivaA(listaStatiCivili[i].Decorrenza.Value, dataSistema))
                {
                    messaggioVideo = "Le decorrenze degli stati civili non possono essere superiori alla data odierna";
                    return false;
                }
            }

            //La decorrenza del 2° elemento non deve essere comunque inferiore alla Decorrenza Originaria (RAU104)
            if (listaStatiCivili.Count > 1)
            {
                if (!Utility.DataSuccessivaA(listaStatiCivili[1].Decorrenza.Value, decorrenzaOriginaria.Value))
                {
                    messaggioVideo = "La seconda decorrenza dello stato civile (a partire da quella più remota) non deve essere inferiore alla decorrenza originaria";
                    return false;
                }
            }

            //modifica mail 20/12/2016- controllo praticolarizzato (1 di 2)
            // non supertiste, non coniugato o unito civilmente, se esiste coniuge o unito civile
            if (!datiPensione.SiglaCategoria.StartsWith("S") && listaStatiCivili != null && listaStatiCivili.Find(x => x.Codice == '2' || x.Codice == '7') == null) //codice = 2: coniugato, 7: unito/a civilmente
            {
                if (listaFamiliari.Exists(x => x.Confermato && x.IsConiugeOrUnitoCivile()))
                {
                    messaggioVideo = "Attenzione! E' necessario rimuovere il 'Coniuge' e/o 'Unito/a civilmente' presente tra i Familiari prima di salvare uno Stato Civile diverso da Coniugato/a.";
                    return false;
                }
            }

            //AGO: Non sono comunque ammessi più di 2 decorrenze nell'anno solare oltre alla prima decorrenza
            if (tipoAppartenenza.HasValue && tipoAppartenenza.Value == Utility.TipoAppartenenza.AGO)
            {
                for (int i = 0; i < listaStatiCivili.Count; i++)
                {
                    int contaAnnoSolare = 0;
                    for (int j = i + 1; j < listaStatiCivili.Count; j++)
                    {
                        if (listaStatiCivili[i].Decorrenza.Value.Year == listaStatiCivili[j].Decorrenza.Value.Year)
                            contaAnnoSolare++;
                    }
                    if (contaAnnoSolare > 2)
                    {
                        messaggioVideo = "Oltre al primo stato civile non sono ammesse più di 2 decorrenze nello stesso anno solare";
                        return false;
                    }
                }
            }

            // CI: Non sono comunque ammessi più di 2 decorrenze nell'anno solare
            if (tipoAppartenenza.HasValue && tipoAppartenenza.Value == Utility.TipoAppartenenza.CI)
            {
                for (int i = 0; i < listaStatiCivili.Count; i++)
                {
                    int contaAnnoSolare = 1;
                    for (int j = i + 1; j < listaStatiCivili.Count; j++)
                    {
                        if (listaStatiCivili[i].Decorrenza.Value.Year == listaStatiCivili[j].Decorrenza.Value.Year)
                            contaAnnoSolare++;
                    }
                    if (contaAnnoSolare > 2)
                    {
                        messaggioVideo = "Non sono ammesse più di 2 decorrenze dello stato civile nell'anno solare";
                        return false;
                    }
                }
            }

            bool precedenteIsConiugato = false;
            if (listaStatiCivili.Exists(x => x.Codice == '2' || x.Codice == '7'))
            {
                // Recupero l'elenco di stati civili a partire dall'ultimo avente valore 2: Coniugato/a o 7: Unito/a civilmente
                int lastIndex = listaStatiCivili.FindLastIndex(x => x.Codice == '2' || x.Codice == '7');
                foreach (GestioneAnagrafica.DatiStatoCivile statoCivile in listaStatiCivili.GetRange(lastIndex, listaStatiCivili.Count - lastIndex))
                {
                    if (precedenteIsConiugato)
                    {
                        foreach (GestioneFamiliari.Familiare fam in listaFamiliari)
                        {
                            if (fam.Confermato && fam.IsConiugeOrUnitoCivile())
                            {
                                List<GestioneFamiliari.CodMaggFamiliari> elencoCodMagg = elencoCodMaggFamiliari.FindAll(x => x.IdAnagrafica == fam.IdAnagrafica);
                                int indexVedovo = listaStatiCivili.FindLastIndex(x => x.Codice == '3');

                                if (elencoCodMagg.Count > 0)
                                {
                                    //Ricostituzioni AGO: è possibile inserire lo stato 'Separato/a' tra gli stati 'Coniugato/a' e 'Vedovo/a' con decorrenza minore della data di fine carico.
                                    if (!(tipoAppartenenza.Value == Utility.TipoAppartenenza.AGO && Utility.IsRicostituzione(datiPensione.Gruppo) && listaStatiCivili.Exists(x => x.Codice == '2' || x.Codice == '7') &&
                                        listaStatiCivili.Exists(x => x.Codice == '3') && (indexVedovo > lastIndex) && listaStatiCivili.GetRange(lastIndex + 1, indexVedovo - (lastIndex + 1)).Count > 0 && listaStatiCivili.GetRange(lastIndex + 1, indexVedovo - (lastIndex + 1)).Exists(x => x.Codice == '4')))
                                    {
                                        if (elencoCodMagg.Count == 1)
                                        {
                                            if (elencoCodMagg.Last().Cessazione.HasValue && elencoCodMagg.Last().Cessazione.Value > statoCivile.Decorrenza && (!fam.DataMorte.HasValue || Utility.FirstDayOfMonth(fam.DataMorte.Value.AddMonths(1)) != statoCivile.Decorrenza))
                                            {
                                                messaggioVideo = "La decorrenza dello stato civile successivo allo stato coniugato/a deve essere maggiore o uguale alla data Fine Carico (" + String.Format("{0:MM/yyyy}", elencoCodMagg.Last().Cessazione.Value) + ")";
                                                return false;
                                            }
                                        }
                                        else
                                        {
                                            if (elencoCodMagg.Last().Cessazione.HasValue && elencoCodMagg.Last().Cessazione.Value != statoCivile.Decorrenza && (!fam.DataMorte.HasValue || Utility.FirstDayOfMonth(fam.DataMorte.Value.AddMonths(1)) != statoCivile.Decorrenza)
                                                && !GestioneBypassControllo.CheckAndLockBypassControlloByNomeBypass(datiPensione, GestioneBypassControllo.NomeBypass.Titolare_Vedovo_Multiplo.TITOLARE_VEDOVO_MULTIPLO))
                                            {
                                                messaggioVideo = "La decorrenza dello stato civile successivo allo stato coniugato/a deve essere uguale alla data Fine Carico (" + String.Format("{0:MM/yyyy}", elencoCodMagg.Last().Cessazione.Value) + ")";
                                                return false;
                                            }
                                        }
                                    }
                                }
                            }
                        }

                        precedenteIsConiugato = false;
                    }

                    if (statoCivile.Codice == '2' || statoCivile.Codice == '7')
                        precedenteIsConiugato = true;
                }
            }

            if (listaStatiCivili.LastOrDefault().Codice == '2' && listaFamiliari.Exists(x => x.IsUnitoCivile()))
            {
                messaggioVideo = "Nel caso di stato civile 'Coniugato/a', non può essere presente un familiare con parentela 'Unito/a Civilmente'.";
                return false;
            }

            if (listaStatiCivili.LastOrDefault().Codice == '7')
            {
                List<GestioneFamiliari.Familiare> listaConiugiApp = null;
                if (listaFamiliari.Exists(x => x.IsConiuge()))
                {
                    listaConiugiApp = listaFamiliari.FindAll(x => x.IsConiuge());
                    if (listaConiugiApp != null && listaConiugiApp.Count > 0 && elencoCodMaggFamiliari != null && elencoCodMaggFamiliari.Count > 0)
                    {
                        foreach (GestioneFamiliari.Familiare coniuge in listaConiugiApp)
                        {
                            List<GestioneFamiliari.CodMaggFamiliari> listaCodMagFamiliariApp = elencoCodMaggFamiliari.FindAll(x => x.IdAnagrafica == coniuge.IdAnagrafica);
                            if (listaCodMagFamiliariApp != null && listaCodMagFamiliariApp.Count > 0 && !listaCodMagFamiliariApp.OrderBy(x => x.Decorrenza).LastOrDefault().Cessazione.HasValue)
                            {
                                messaggioVideo = "Nel caso di stato civile 'Unito/a civilmente', non può essere presente un familiare con parentela 'Coniuge'.";
                                return false;
                            }

                        }
                    }
                }

                if (listaFamiliari.Exists(x => x.IsConiugeOrUnitoCivile()))
                {
                    listaConiugiApp = listaFamiliari.FindAll(x => x.IsConiugeOrUnitoCivile());
                    if (listaConiugiApp != null && listaConiugiApp.Count > 0 && elencoCodMaggFamiliari != null && elencoCodMaggFamiliari.Count > 0)
                    {
                        foreach (GestioneFamiliari.Familiare coniugeUnitoCivilmente in listaConiugiApp)
                        {
                            List<GestioneFamiliari.CodMaggFamiliari> listaCodMagFamApp = elencoCodMaggFamiliari.FindAll(x => x.IdAnagrafica == coniugeUnitoCivilmente.IdAnagrafica);
                            if (listaCodMagFamApp != null && listaCodMagFamApp.Count > 0 && !listaCodMagFamApp.OrderBy(x => x.Decorrenza).LastOrDefault().Cessazione.HasValue && listaAnagraficheFamiliari.First(y => y.Id == coniugeUnitoCivilmente.IdAnagrafica).Sesso != sessoTitolare)
                            {
                                messaggioVideo = "Nel caso di stato civile 'Unito/a civilmente', il titolare non può avere sesso diverso dal 'Coniuge'.";
                                return false;

                            }
                        }
                    }
                }
            }

            if (listaStatiCivili.LastOrDefault().Codice == '2' && listaFamiliari.Count(x => x.IsConiugeOrUnitoCivile() && listaAnagraficheFamiliari.First(y => y.Id == x.IdAnagrafica).Sesso == sessoTitolare) > 0)
            {
                messaggioVideo = "Nel caso di stato civile 'Coniugato/a', il titolare non può avere lo stesso sesso del 'Coniuge'.";
                return false;
            }

            if (listaStatiCivili.LastOrDefault().Codice == '3' && datiPensione.SiglaCategoria.StartsWith("S") &&
                listaFamiliari.Count(x => x.IsConiugeOrUnitoCivile() && listaAnagraficheFamiliari.First(y => y.Id == x.IdAnagrafica).Sesso == sessoDanteCausa) > 0)
            {
                messaggioVideo = "Nel caso di stato civile 'Vedovo/a', il titolare non può avere lo stesso sesso del Dante Causa.";
                return false;
            }

            if (listaStatiCivili.LastOrDefault().Codice == 'C' && datiPensione.SiglaCategoria.StartsWith("S") &&
                listaFamiliari.Count(x => x.IsConiugeOrUnitoCivile() && listaAnagraficheFamiliari.First(y => y.Id == x.IdAnagrafica).Sesso != sessoDanteCausa) > 0)
            {
                messaggioVideo = "Nel caso di stato civile 'Vedovo/a da unione civile', il titolare non può avere sesso diverso dal Dante Causa.";
                return false;
            }

            return true;
        }

        public static bool ALL_VerificaDataMatrimonioDC(GestionePensione.DatiPensione datiPensione, bool isRiaperturaDomanda, DateTime? dataMatrimonioDC, List<GestioneFamiliari.Familiare> lFamiliare, Utility.TipoAppartenenza? tipoApp, out string messaggioVideo)
        {
            messaggioVideo = string.Empty;

            Utility.TipoDomanda tipoDomanda = Utility.GetTipoDomanda(datiPensione.Gruppo, datiPensione.Prodotto);
            Utility.TipoFondo? tipoFondo = Utility.GetTipoFondoByCategoria(datiPensione.IndConvInt, datiPensione.Gestione, datiPensione.SiglaCategoria);

            //modifica mail 20/12/2016- controllo praticolarizzato (2 di 2)
            // se superstite e non esiste data matrimonio, e se esiste coiniuge o unito civile
            if (datiPensione.SiglaCategoria.StartsWith("S") && !dataMatrimonioDC.HasValue)
            {
                if (tipoApp == Utility.TipoAppartenenza.FS || Utility.IsDomandaINPDAP(datiPensione.Gestione))
                {
                    if ((!Utility.IsRicostituzione(datiPensione.Gruppo) || tipoFondo == Utility.TipoFondo.FS || tipoFondo == Utility.TipoFondo.PT || Utility.IsDomandaINPDAP(datiPensione.Gestione)) && datiPensione.DecorrenzaOriginaria.HasValue && Utility.DataSuccessivaA(datiPensione.DecorrenzaOriginaria.Value, new DateTime(2012, 1, 1)) &&
                        lFamiliare != null && lFamiliare.Exists(x => x.Confermato && x.IsConiugeOrUnitoCivile()))
                    {
                        messaggioVideo = "Attenzione! In presenza del Coniuge o Unito/a civilmente è necessario inserire la Data Matrimonio.";
                        return false;
                    }
                }
                else
                {
                    if (!isRiaperturaDomanda && tipoDomanda != Utility.TipoDomanda.Ricostituzione)
                    {
                        if (lFamiliare != null && lFamiliare.Exists(x => x.Confermato && x.IsConiugeOrUnitoCivile()))
                        {
                            messaggioVideo = "Attenzione! In presenza del Coniuge o Unito/a civilmente è necessario inserire la Data Matrimonio.";
                            return false;
                        }
                    }
                }
            }

            return true;
        }

        private static bool ALL_VerificaEtaTitolareSperDonna(GestionePensione.DatiPensione datiPensione, DateTime? DataPerfezionamentoRequisiti, DateTime? dataNascitaTitolare,
            out string msgVideo)
        {
            msgVideo = string.Empty;

            if (!DataPerfezionamentoRequisiti.HasValue || !dataNascitaTitolare.HasValue)
            {
                msgVideo = "Data Perferzionamento Requisiti e Data Nascita Titolare obbligatori";
                return false;
            }

            string strCatNum = datiPensione.GetCodCategoria();
            int catNum;
            int.TryParse(strCatNum, out catNum);

            Utility.TipoAppartenenza? tipoAppartenenza = Utility.GetTipoAppartenenza(datiPensione.IndConvInt, datiPensione.Gestione);

            // La decorrenza della pensione deve essere maggiore di 12 mesi per la gestione AGO (VO, VOS, VDAI) e FS
            if (catNum == 1 || catNum == 4 || catNum == 82 || tipoAppartenenza == Utility.TipoAppartenenza.FS)
            {
                // per titolare nato fino al 30/09/1958
                if (!Utility.DataStrettamenteSuccessivaA(dataNascitaTitolare.Value, new DateTime(1958, 9, 30)))
                {
                    if (Utility.DataStrettamenteSuccessivaA(dataNascitaTitolare.Value.AddYears(57).AddMonths(3), DataPerfezionamentoRequisiti.Value))
                    {
                        msgVideo = string.Format("Età del titolare inferiore a 57 anni e 3 mesi al {0:dd/MM/yyyy}.", DataPerfezionamentoRequisiti.Value);
                        return false;
                    }
                }
                // per titolare nato dal il 1/10/1958
                else if (Utility.DataSuccessivaA(dataNascitaTitolare.Value, new DateTime(1958, 10, 1)))
                {
                    if (Utility.DataStrettamenteSuccessivaA(dataNascitaTitolare.Value.AddYears(57), DataPerfezionamentoRequisiti.Value))
                    {
                        msgVideo = string.Format("Età del titolare inferiore a 57 anni al {0:dd/MM/yyyy}", DataPerfezionamentoRequisiti.Value);
                        return false;
                    }
                }
            }
            else
            {
                // per titolare nato fino al 30/09/1957
                if (!Utility.DataStrettamenteSuccessivaA(dataNascitaTitolare.Value, new DateTime(1957, 9, 30)))
                {
                    if (Utility.DataStrettamenteSuccessivaA(dataNascitaTitolare.Value.AddYears(58).AddMonths(3), DataPerfezionamentoRequisiti.Value))
                    {
                        msgVideo = string.Format("Età del titolare inferiore a 58 anni e 3 mesi al {0:dd/MM/yyyy}.", DataPerfezionamentoRequisiti.Value);
                        return false;
                    }
                }
                // per titolare nato dal il 1/10/1957
                else if (Utility.DataSuccessivaA(dataNascitaTitolare.Value, new DateTime(1957, 10, 1)))
                {
                    if (Utility.DataStrettamenteSuccessivaA(dataNascitaTitolare.Value.AddYears(58), DataPerfezionamentoRequisiti.Value))
                    {
                        msgVideo = string.Format("Età del titolare inferiore a 58 anni al {0:dd/MM/yyyy}.", DataPerfezionamentoRequisiti.Value);
                        return false;
                    }
                }
            }

            return true;
        }

        /// <summary>
        /// Verifica che la decorrenza della pensione sia uguale alla data perfezionamento requisiti + 13 mesi
        /// </summary>
        /// <param name="datiPensione"></param>
        /// <returns>false se la data perfezionamento requisiti è maggiore della decorrenza pensione, true altrimenti</returns>
        private static bool ALL_VerificaPerfezRequisitiDecorPensione(GestionePensione.DatiPensione datiPensione, DateTime? DecorrenzaPensione, DateTime? PerfezionamentoRequisiti, char? derogaTraduzioneSuGP,
            bool isRiaperturaDomanda, out string messaggioVideo)
        {
            messaggioVideo = string.Empty;

            if (!DecorrenzaPensione.HasValue || !PerfezionamentoRequisiti.HasValue)
            {
                messaggioVideo = "Decorrenza pensione e/o data di perfezionamento dei requisiti assenti";
                return false;
            }
            Utility.TipoAppartenenza? tipoApp = Utility.GetTipoAppartenenza(datiPensione.IndConvInt, datiPensione.Gestione);

            if (DecorrenzaPensione.Value >= new DateTime(2008, 1, 1) && tipoApp == Utility.TipoAppartenenza.AGO &&
                datiPensione.GetFiltro() == "SAA" && datiPensione.Gruppo == "0001" && datiPensione.Prodotto == "0001" && (datiPensione.Tipo == "0042" || datiPensione.Tipo == "0050"))
            {
                int yearPerfezRequisiti = PerfezionamentoRequisiti.Value.Year;
                DateTime? minDecorrenzaPensione = null;
                switch (datiPensione.SiglaCategoria.Trim())
                {
                    case "VO":
                        //Per dataPerReq <= giugno
                        if (PerfezionamentoRequisiti.Value.Month < 7)
                        {
                            minDecorrenzaPensione = new DateTime((yearPerfezRequisiti + 1), 1, 1);
                        }
                        else
                        {
                            minDecorrenzaPensione = new DateTime((yearPerfezRequisiti + 1), 7, 1);
                        }
                        break;
                    case "VOART":
                    case "VOCOM":
                    case "VR":
                        //Per dataPerReq <= giugno
                        if (PerfezionamentoRequisiti.Value.Month < 7)
                        {
                            minDecorrenzaPensione = new DateTime((yearPerfezRequisiti + 1), 7, 1);
                        }
                        else
                        {
                            minDecorrenzaPensione = new DateTime((yearPerfezRequisiti + 2), 1, 1);
                        }
                        break;
                    default:
                        break;

                }
                if (minDecorrenzaPensione.HasValue && DecorrenzaPensione.Value < minDecorrenzaPensione)
                {
                    messaggioVideo = "La decorrenza pensione deve essere maggiore o uguale a " + minDecorrenzaPensione.Value.ToString("MM/yyyy");
                    return false;
                }
            }
            else
            {
                // Per le domande di salvaguardia L.122 dei fondi EL, TT, ET, GAS, DZ, ES, PM, PI, VL non va applicato il confronto tra data di perfezionamento requisiti e decorrenza pensione 
                if (Utility.IsDomandaSalvaguardia122_FS_2011_2012(datiPensione, derogaTraduzioneSuGP))
                    return true;

                //Vecchiaia tipologia ENAV
                if (tipoApp == Utility.TipoAppartenenza.AGO && Utility.IsDomandaVecchiaiaENAV(datiPensione))
                {
                    if (!Utility.DataSuccessivaA(DecorrenzaPensione.Value, new DateTime(2019, 4, 1)))
                    {
                        messaggioVideo = "La decorrenza della pensione deve essere maggiore o uguale a 04/2019";
                        return false;
                    }

                    int annoPerfRequisiti = PerfezionamentoRequisiti.Value.Year;
                    //Per PerfezionamentoRequisiti <= 31/03/aaaa la DecorrenzaPensione deve essere >= 1/07/aaaa
                    if (Utility.DataSuccessivaA(new DateTime(annoPerfRequisiti, 3, 31), PerfezionamentoRequisiti.Value))
                    {
                        if (!Utility.DataSuccessivaA(DecorrenzaPensione.Value, new DateTime(annoPerfRequisiti, 7, 1)))
                        {
                            messaggioVideo = "La decorrenza della pensione deve essere maggiore o uguale al 07/" + annoPerfRequisiti;
                            return false;
                        }
                    }
                    //Per PerfezionamentoRequisiti <= 30/06/aaaa la DecorrenzaPensione deve essere >= 1/10/aaaa
                    else if (Utility.DataSuccessivaA(new DateTime(annoPerfRequisiti, 6, 30), PerfezionamentoRequisiti.Value))
                    {
                        if (!Utility.DataSuccessivaA(DecorrenzaPensione.Value, new DateTime(annoPerfRequisiti, 10, 1)))
                        {
                            messaggioVideo = "La decorrenza della pensione deve essere maggiore o uguale al 10/" + annoPerfRequisiti;
                            return false;
                        }
                    }
                    //Per PerfezionamentoRequisiti <= 30/09/aaaa la DecorrenzaPensione deve essere >= 1/01/aaaa + 1
                    else if (Utility.DataSuccessivaA(new DateTime(annoPerfRequisiti, 9, 30), PerfezionamentoRequisiti.Value))
                    {
                        if (!Utility.DataSuccessivaA(DecorrenzaPensione.Value, new DateTime(annoPerfRequisiti + 1, 1, 1)))
                        {
                            annoPerfRequisiti += 1;
                            messaggioVideo = "La decorrenza della pensione deve essere maggiore o uguale al 01/" + annoPerfRequisiti;
                            return false;
                        }
                    }
                    //Per PerfezionamentoRequisiti <= 31/12/aaaa la DecorrenzaPensione deve essere >= 1/04/aaaa + 1
                    else if (Utility.DataSuccessivaA(new DateTime(annoPerfRequisiti, 12, 31), PerfezionamentoRequisiti.Value))
                    {
                        if (!Utility.DataSuccessivaA(DecorrenzaPensione.Value, new DateTime(annoPerfRequisiti + 1, 4, 1)))
                        {
                            annoPerfRequisiti += 1;
                            messaggioVideo = "La decorrenza della pensione deve essere maggiore o uguale al 04/" + annoPerfRequisiti;
                            return false;
                        }
                    }
                }
                else if (!Utility.IsRicostituzioneOrRiapertura(datiPensione, isRiaperturaDomanda) && !Utility.IsDomandaSPED(datiPensione))
                {
                    DateTime dateCompare = PerfezionamentoRequisiti.Value;
                    DateTime dataPensione = DecorrenzaPensione.Value.AddMonths(1).AddDays(-1);
                    int mesi = Utility.IsGestioneART_COM_CDCM(datiPensione) ? 19 : 13;
                    dateCompare = dateCompare.AddMonths(mesi);
                    //modifica per competenza 2013
                    if (!(tipoApp == Utility.TipoAppartenenza.AGO && GestioneBypassControllo.CheckAndLockBypassControlloByNomeBypass(datiPensione, GestioneBypassControllo.NomeBypass.Titolare_Anagrafica_AGO.PERFEZIONAMENTO_REQ_2011)) &&
                        (Utility.DataSuccessivaA(PerfezionamentoRequisiti.Value, new DateTime(2011, 1, 1)) && !Utility.DataSuccessivaA(PerfezionamentoRequisiti.Value, new DateTime(2012, 1, 1))) ||
                        (Utility.IsDomandaSalvaguardia178_2020(datiPensione) && !Utility.IsDomandaSalvaguardiaAutomatica(datiPensione)))
                    {
                        if (dateCompare.CompareTo(dataPensione) > 0)
                        {
                            if (Utility.IsDomandaSalvaguardia178_2020(datiPensione) && !Utility.IsDomandaSalvaguardiaAutomatica(datiPensione))
                                messaggioVideo = "La decorrenza della pensione deve essere successiva di almeno " + (mesi - 1).ToString() + " mesi dalla data di perfezionamento dei requisiti.";
                            else
                                messaggioVideo = "Se il perfezionamento dei requisiti si colloca nel 2011, la decorrenza della pensione dovrà essere successiva di almeno " + (mesi - 1).ToString() + " mesi da detto perfezionamento.";

                            return false;
                        }
                    }
                }
            }

            if (Utility.DataSuccessivaA(PerfezionamentoRequisiti.Value, new DateTime(2012, 1, 1)) &&
               !(Utility.IsDomandaVOCUM(datiPensione.SiglaCategoria) && Utility.IsDomandaAPEPrecoci(datiPensione) && GestioneBypassControllo.CheckAndLockBypassControlloByNomeBypass(datiPensione, GestioneBypassControllo.NomeBypass.Titolare_Anagrafica_AGO.COMPARTO_SCUOLA)))
            {
                //la Data Perfezionamento Requisiti dovrà essere inferiore alla decorrenza Pensione
                if (!Utility.DataStrettamenteSuccessivaA(DecorrenzaPensione.Value, PerfezionamentoRequisiti.Value))
                {
                    if (Utility.IsDomandaVOAUT(datiPensione.SiglaCategoria) && (Utility.IsDomandaAnzianitaInComputo(datiPensione) || Utility.IsDomandaVecchiaiaInComputo(datiPensione)))
                        messaggioVideo = "La decorrenza della pensione deve essere successiva sia alla data di perfezionamento dei requisiti che alla data di presentazione della domanda";
                    else
                        messaggioVideo = "Per data di perfezionamento dei requisiti uguale o successiva a Gennaio 2012, la decorrenza pensione deve essere successiva alla data di perfezionamento dei requisiti";
                    return false;
                }
            }
            return true;
        }

