        public static bool ALL_VerificaDecorPensioneSalvaguardia214(GestionePensione.DatiPensione datiPensione, DateTime? decorrenzaOriginaria, out string msgVideo)
        {
            msgVideo = string.Empty;

            // Mail 24-08-2015 - Liq Pens - Salvaguardia memo33 65000 Salvaguardati
            // Messa la data 2013-01-02 in modo tale ce per PS e PT la data minima inseribile sarà 2013-1-2 
            //(avendo il dettaglio del giorno) mentre in tutti gli altri casi sarà 2013-02-01 poichè non si ha
            // il dettaglio del giorno.
            if (Utility.IsDomandaSalvaguardia214(datiPensione) && decorrenzaOriginaria.HasValue &&
                    !Utility.DataSuccessivaA(decorrenzaOriginaria.Value, new DateTime(2013, 1, 2)))
            {
                msgVideo = "Decorrenza pensione non compatibile con domanda in Salvaguardia L. 214";
                return false;
            }
            return true;
        }

