        public static bool ALL_VerificaDecorPensioneUsuranti(GestionePensione.DatiPensione datiPensione, DateTime? decorrenzaOriginaria, out string msgVideo)
        {
            msgVideo = string.Empty;
            if (Utility.IsDomandaUsuranti(datiPensione))
            {
                if (decorrenzaOriginaria.HasValue &&
                        !Utility.DataSuccessivaA(decorrenzaOriginaria.Value, new DateTime(2011, 6, 1)))
                {
                    msgVideo = "Decorrenza pensione non compatibile con domanda di usuranti. La decorrenza pensione non può essere inferiore a giugno 2011";
                    return false;
                }

                if (Utility.IsDomandaUnicarpe(datiPensione, true) == Utility.TipoUnicarpe.Manuale)
                {
                    List<GestioneOneri.DatiOneri> listaOneri = null;
                    GestioneOneri.GetOneriByIdPensione(datiPensione.Id, out listaOneri);
                    if (listaOneri != null && listaOneri.Count > 0 && listaOneri[0].Decorrenza.HasValue)
                    {
                        if (decorrenzaOriginaria.HasValue &&
                            !Utility.DataSuccessivaA(decorrenzaOriginaria.Value, listaOneri[0].Decorrenza.Value))
                        {
                            msgVideo = "Decorrenza pensione non compatibile con domanda di usuranti. La decorrenza pensione non può essere inferiore alla decorrenza onere (" +
                                 listaOneri[0].Decorrenza.Value.ToString("dd-MM-yyyy") + ")";
                            return false;
                        }
                    }
                }
            }
            return true;
        }

