        public static bool ALL_ControlsDecorrenzaOriginariaSperimentaleDonna(GestionePensione.DatiPensione datiPensione, DateTime? decorrenzaOriginaria, out string messaggioVideo)
        {
            messaggioVideo = string.Empty;

            if (datiPensione == null)
                return false;

            Utility.TipoAppartenenza? tipoAppartenenza = Utility.GetTipoAppartenenza(datiPensione.IndConvInt, datiPensione.Gestione);
            Utility.TipoFondo? tipoFondo = Utility.GetTipoFondoByCategoria(tipoAppartenenza, datiPensione.SiglaCategoria);
            DateTime? dataLimiteInf = null;
            if (Utility.IsDomandaSperimentaleDonna(datiPensione))
                dataLimiteInf = new DateTime(2009, 01, 01);
            else if (Utility.IsDomandaSperimentaleDonna_DL_4_2019(datiPensione))
            {
                if (Utility.IsDomandaINPDAP(datiPensione.Gestione) || (tipoFondo.HasValue && (tipoFondo.Value == Utility.TipoFondo.FS || tipoFondo.Value == Utility.TipoFondo.PT)))
                    dataLimiteInf = new DateTime(2019, 01, 30);
                else
                    dataLimiteInf = new DateTime(2019, 02, 01);
            }

            if (dataLimiteInf.HasValue && decorrenzaOriginaria.HasValue)
            {
                if (!Utility.DataSuccessivaA(decorrenzaOriginaria.Value, dataLimiteInf.Value))
                {
                    messaggioVideo = "La decorrenza pensione non può essere minore della data " + String.Format("{0:dd/MM/yyyy}", dataLimiteInf);
                    return false;
                }
            }

            if (Utility.IsDomandaSperimentaleDonna_DL_4_2019(datiPensione) && (tipoFondo.HasValue && (tipoFondo.Value == Utility.TipoFondo.FS || tipoFondo.Value == Utility.TipoFondo.PT))
                && !GestioneBypassControllo.CheckAndLockBypassControlloByNomeBypass(datiPensione, GestioneBypassControllo.NomeBypass.Decorr_Chiarimento_Normativo.DECORR_CHIARIMENTO_NORMATIVO))
            {
                if (decorrenzaOriginaria.HasValue && Utility.DataSuccessivaA(datiPensione.DataPresentazioneDomanda, decorrenzaOriginaria.Value))
                {
                    messaggioVideo = "La decorrenza pensione non può essere precedente alla data presentazione";
                    return false;
                }
            }

            return true;
        }

        // Memo 79 2025
        public static bool ALL_VerificaDecorPensione_DomandeOrganizzazioniInternazionali(GestionePensione.DatiPensione datiPensione, GestioneDanteCausa.DatiDanteCausa datiDanteCausa, DateTime? decorrenzaOriginaria, out string messaggioVideo)
        {
            bool retVal = true;
            messaggioVideo = string.Empty;

            if (Utility.IsDomandaOrganizzazioniInternazionali_Vecchiaia_Invialidita(datiPensione))
            {
                DateTime dataMinima = new DateTime(2016, 2, 1);
                // Calcolo il primo giorno del mese successivo a quello di presentazione
                DateTime primoGiornoMeseSuccessivo = new DateTime(
                    datiPensione.DataPresentazioneDomanda.Month == 12 ? datiPensione.DataPresentazioneDomanda.Year + 1 : datiPensione.DataPresentazioneDomanda.Year
                    , datiPensione.DataPresentazioneDomanda.Month == 12 ? 1 : datiPensione.DataPresentazioneDomanda.Month + 1, 1
                );

                // La decorrenza non può essere inferiore al massimo tra il primo giorno del mese successivo
                // e la data minima
                DateTime limiteInferiore = primoGiornoMeseSuccessivo > dataMinima ? primoGiornoMeseSuccessivo : dataMinima;

                if (decorrenzaOriginaria < limiteInferiore)
                {
                    // La decorrenza NON è valida
                    messaggioVideo = "La decorrenza non può essere inferiore al primo giorno del mese successivo alla presentazione della domanda di pensione di vecchiaia e invalidità, e comunque non inferiore al 01/02/2016";
                    retVal = false;
                }
            }

            if (Utility.IsDomandaOrganizzazioniInternazionali_Superstiti(datiPensione))
            {

                DateTime dataMinima = new DateTime(2016, 2, 1);
                // Calcolo il primo giorno del mese successivo alla data di decesso
                DateTime primoGiornoMeseSuccessivo = new DateTime(
                    datiDanteCausa.DataMorte.Value.Month == 12 ? datiDanteCausa.DataMorte.Value.Year + 1 : datiDanteCausa.DataMorte.Value.Year,
                    datiDanteCausa.DataMorte.Value.Month == 12 ? 1 : datiDanteCausa.DataMorte.Value.Month + 1,
                    1
                );

                // La decorrenza non può essere inferiore al massimo tra il primo giorno del mese successivo
                // e la data minima
                DateTime limiteInferiore = primoGiornoMeseSuccessivo > dataMinima ? primoGiornoMeseSuccessivo : dataMinima;

                if (decorrenzaOriginaria < limiteInferiore)
                {
                    // La decorrenza NON è valida
                    messaggioVideo = "La decorrenza non può essere inferiore al primo giorno del mese successivo alla data di decesso del dante causa in caso di domanda di pensione ai superstiti, e comunque non inferiore al 01/02/2016";
                    retVal = false;
                }
            }

            if (Utility.IsDomandaOrganizzazioniInternazionali_Anticipate(datiPensione))
            {
                DateTime dataMinima = new DateTime(2023, 7, 1);

                // Calcolo il primo giorno del mese successivo alla presentazione
                DateTime primoGiornoMeseSuccessivo = new DateTime(
                    datiPensione.DataPresentazioneDomanda.Month == 12 ? datiPensione.DataPresentazioneDomanda.Year + 1 : datiPensione.DataPresentazioneDomanda.Year,
                    datiPensione.DataPresentazioneDomanda.Month == 12 ? 1 : datiPensione.DataPresentazioneDomanda.Month + 1,
                    1
                );

                // Il limite inferiore è il massimo tra il primo giorno del mese successivo e il 01/07/2023
                DateTime limiteInferiore = primoGiornoMeseSuccessivo > dataMinima ? primoGiornoMeseSuccessivo : dataMinima;

                if (decorrenzaOriginaria < limiteInferiore)
                {
                    // Decorrenza NON valida
                    messaggioVideo = "La decorrenza non può essere inferiore al primo giorno del mese successivo alla presentazione della domanda di pensione anticipata e comunque non inferiore al 01/07/2023";
                    retVal = false;
                }
            }

            return retVal;
        }

        public static bool ALL_VerificaDecorPensione(GestionePensione.DatiPensione datiPensione, DateTime? decorrenzaOriginaria, DateTime? dataPerfReq, out string messaggioVideo)
        {
            messaggioVideo = string.Empty;

            if (Utility.IsDomandaRiliquidazione(datiPensione) == true && datiPensione.SiglaCategoria.StartsWith("I") && !Utility.DataSuccessivaA(decorrenzaOriginaria.Value, new DateTime(datiPensione.DataPresentazioneDomanda.Year, datiPensione.DataPresentazioneDomanda.Month, 1)))
            {
                messaggioVideo = "La decorrenza originaria deve essere maggiore della data di presentazione";
                return false;

            }

            if (Utility.IsDomandaRiliquidazione(datiPensione) == true && datiPensione.SiglaCategoria.StartsWith("I") && !Utility.DataSuccessivaA(decorrenzaOriginaria.Value, new DateTime(datiPensione.DataPresentazioneDomanda.Year, datiPensione.DataPresentazioneDomanda.Month, 1)))
            {
                messaggioVideo = "La decorrenza originaria deve essere maggiore della data di presentazione";
                return false;

            }

            if (Utility.IsDomandaRipristino(datiPensione).GetValueOrDefault())
                return true;

            if (Utility.IsDomandaRiliquidazioneAnzianitaAnticipata(datiPensione))
            {
                if (Utility.GetTipoAppartenenza(datiPensione.IndConvInt, datiPensione.Gestione) == Utility.TipoAppartenenza.AGO && !Utility.DataStrettamenteSuccessivaA(decorrenzaOriginaria.Value, datiPensione.DataPresentazioneDomanda))
                {
                    messaggioVideo = "La decorrenza originaria deve essere maggiore della data di presentazione";
                    return false;
                }
            }

            if (datiPensione.Gruppo == "0001" && datiPensione.Prodotto == "0001" && datiPensione.Tipo != "0158" &&
                !BypassVerificaDecorPensioneForFondiSpeciali(datiPensione, dataPerfReq, decorrenzaOriginaria) &&
                !BypassVerificaDecorPensionePerAPESocialeEPrecoci(datiPensione, dataPerfReq) &&
                !Utility.IsPrepensionamentoEditoriaFiltroEAA(datiPensione) && !Utility.IsPrepensionamentoEditoriaArt1c154L205_2017(datiPensione) &&
                !GestioneBypassControllo.CheckAndLockBypassControlloByNomeBypass(datiPensione, GestioneBypassControllo.NomeBypass.Titolare_Anagrafica_AGO.DECORR_PRECEDENTE_PRESENTAZ))
            {
                if (Utility.GetTipoAppartenenza(datiPensione.IndConvInt, datiPensione.Gestione) == Utility.TipoAppartenenza.AGO ? !Utility.DataStrettamenteSuccessivaA(decorrenzaOriginaria.Value, datiPensione.DataPresentazioneDomanda) :
                    !Utility.DataSuccessivaA(decorrenzaOriginaria.Value, datiPensione.DataPresentazioneDomanda))
                {
                    if (Utility.IsDomandaVOAUT(datiPensione.SiglaCategoria) && (Utility.IsDomandaAnzianitaInComputo(datiPensione) || Utility.IsDomandaVecchiaiaInComputo(datiPensione)))
                        messaggioVideo = "La decorrenza della pensione deve essere successiva sia alla data di perfezionamento dei requisiti che alla data di presentazione della domanda";
                    else
                        messaggioVideo = "La decorrenza originaria deve essere maggiore della data di presentazione";
                    return false;
                }
            }

            if (!Utility.IsDomandaINPDAP(datiPensione.Gestione) &&
                Utility.IsDomandaAPESociale(datiPensione.SiglaCategoria) && !Utility.IsRicostituzione(datiPensione.Gruppo) && dataPerfReq.HasValue &&
                !(Utility.DataSuccessivaA(new DateTime(2017, 12, 31), dataPerfReq.Value) ||
                (Utility.DataStrettamenteSuccessivaA(dataPerfReq.Value, new DateTime(2017, 12, 31)) && Utility.DataSuccessivaA(new DateTime(2018, 03, 31), datiPensione.DataPresentazioneDomanda))))
            {
                if (!Utility.DataSuccessivaA(decorrenzaOriginaria.Value, datiPensione.DataPresentazioneDomanda))
                {
                    messaggioVideo = "La decorrenza originaria deve essere maggiore della data di presentazione";
                    return false;
                }
            }

            if (Utility.GetTipoAppartenenza(datiPensione.IndConvInt, datiPensione.Gestione) == Utility.TipoAppartenenza.FS && Utility.IsDomandaAssegnoInvaliditaOrdinario(datiPensione)
                && !Utility.DataStrettamenteSuccessivaA(decorrenzaOriginaria.Value, datiPensione.DataPresentazioneDomanda))
            {
                messaggioVideo = "La decorrenza originaria deve essere maggiore della data di presentazione";
                return false;
            }

            if (Utility.GetTipoAppartenenza(datiPensione.IndConvInt, datiPensione.Gestione) == Utility.TipoAppartenenza.CI && Utility.IsDomandaRiliquidazioneAnzianitaAnticipata(datiPensione)
            && decorrenzaOriginaria.HasValue && datiPensione.DataPresentazioneDomanda != null && !Utility.DataStrettamenteSuccessivaA(decorrenzaOriginaria.Value, datiPensione.DataPresentazioneDomanda))
            {
                messaggioVideo = "La decorrenza originaria deve essere maggiore della data di presentazione";
                return false;
            }

            return true;
        }

        public static bool ALL_VerificaBloccoDecorrenzaPensione(GestionePensione.DatiPensione datiPensione, bool isRiaperturaDomanda, out string messaggioVideo)
        {
            messaggioVideo = string.Empty;

            GestioneControlliDinamici.ControlloDinamico ctrl = null;
            GestioneControlliDinamici.GetControlloDinamicoByNomeControllo("BloccoPerCoeffTrasfNoAgg", out ctrl);
            DateTime dataSistema = GestioneControlliDinamici.GetDataSistema(Utility.GetTipoAppartenenza(datiPensione.IndConvInt, datiPensione.Gestione));
            if (Utility.IsDomandaUnicarpe(datiPensione, true) != Utility.TipoUnicarpe.Automatica && !Utility.IsRicostituzioneOrRiapertura(datiPensione, isRiaperturaDomanda))
            {
                if (ctrl != null && ctrl.ValoreControllo == "SI" && datiPensione.DecorrenzaOriginaria.GetValueOrDefault().Year > dataSistema.Year)
                {
                    messaggioVideo = "Pensione con decorrenza " + String.Format("{0}", datiPensione.DecorrenzaOriginaria.GetValueOrDefault().Year) + " non lavorabile in attesa di aggiornamento coefficienti di trasformazione";
                    return false;
                }
            }
            return true;
        }

        public static bool BypassVerificaDecorPensionePerAPESocialeEPrecoci(GestionePensione.DatiPensione datiPensione, DateTime? dataPerfReq)
        {
            bool ret = false;
            if ((Utility.IsDomandaAPESociale(datiPensione.SiglaCategoria) && dataPerfReq.HasValue &&
                (Utility.DataSuccessivaA(new DateTime(2017, 12, 31), dataPerfReq.Value) ||
                (Utility.DataStrettamenteSuccessivaA(dataPerfReq.Value, new DateTime(2017, 12, 31)) && Utility.DataSuccessivaA(new DateTime(2018, 03, 31), datiPensione.DataPresentazioneDomanda))))
                ||
                (Utility.IsDomandaAPEPrecoci(datiPensione) && dataPerfReq.HasValue &&
                (Utility.DataSuccessivaA(new DateTime(2017, 12, 31), dataPerfReq.Value) ||
                (Utility.DataStrettamenteSuccessivaA(dataPerfReq.Value, new DateTime(2017, 12, 31)) && Utility.DataSuccessivaA(new DateTime(2018, 03, 01), datiPensione.DataPresentazioneDomanda)))))
                ret = true;
            return ret;
        }

        public static bool BypassVerificaDecorPensioneForFondiSpeciali(GestionePensione.DatiPensione datiPensione, DateTime? dataPerfReq, DateTime? decorrenzaPensione)
        {
            bool ret = false;
            if (Utility.GetTipoAppartenenza(datiPensione.IndConvInt, datiPensione.Gestione) == Utility.TipoAppartenenza.FS)
            {
                if (Utility.IsDomandaINPDAP(datiPensione.Gestione))
                    ret = true;
                else
                    switch (Utility.GetTipoFondoByCategoria(datiPensione.IndConvInt, datiPensione.Gestione, datiPensione.SiglaCategoria))
                    {
                        case Utility.TipoFondo.VL:
                            if (dataPerfReq.HasValue && decorrenzaPensione.HasValue)
                            {
                                Utility.DifferenzaDateTime diff = Utility.DifferenzaBetweenDate(datiPensione.DataPresentazioneDomanda, dataPerfReq.Value, Utility.TipoAppartenenza.FS);
                                if (diff <= new Utility.DifferenzaDateTime(2, 0, 0))
                                    ret = true;
                            }
                            break;
                        case Utility.TipoFondo.PT:
                        case Utility.TipoFondo.FS:
                        case Utility.TipoFondo.EL:
                            ret = true;
                            break;
                    }
            }
            return ret;
        }

        public static bool ALL_VerificaDecorrenzaPensionePerfRequisitiSperimentaleDonna(GestionePensione.DatiPensione datiPensione, Utility.TipoAppartenenza? tipoAppartenenza,
            DateTime? decorrenzaOriginaria, DateTime? dataPerfezionamentoRequisiti, DateTime? dataNascitaTitolare, out string messaggioVideo)
        {
            messaggioVideo = string.Empty;
            Utility.TipoFondo? tipoFondo = Utility.GetTipoFondoByCategoria(tipoAppartenenza, datiPensione.SiglaCategoria);

            // Solo per le Prime Liquidate
            if (Utility.IsDomandaSperimentaleDonna(datiPensione))
            {
                string strCatNum = datiPensione.GetCodCategoria();
                int catNum;
                int.TryParse(strCatNum, out catNum);

                if (!dataPerfezionamentoRequisiti.HasValue || !dataNascitaTitolare.HasValue)
                    return true;

                // La decorrenza della pensione deve essere maggiore di 12 mesi per la gestione AGO (VO, VOS, VDAI) e FS
                if (IsLavoratriceDipendente(catNum, tipoAppartenenza, datiPensione))
                {
                    // La decorrenza deve partire dal mese successivo rispetto alla data perfezionamento requisiti + 12 mesi
                    DateTime dateCompare = dataPerfezionamentoRequisiti.Value.AddMonths(12).AddDays(1);
                    if (decorrenzaOriginaria.Value.CompareTo(dateCompare) < 0)
                    {
                        messaggioVideo = "Attenzione non è soddisfatta la finestra temporale di 12 mesi.";
                        return false;
                    }
                }
                // La decorrenza della pensione deve essere maggiore di 18 mesi per la gestione Autonoma
                else
                {
                    // La decorrenza deve partire dal mese successivo rispetto alla data perfezionamento requisiti + 18 mesi
                    DateTime dateCompare = dataPerfezionamentoRequisiti.Value.AddMonths(18).AddDays(1);
                    if (decorrenzaOriginaria.Value.CompareTo(dateCompare) < 0)
                    {
                        messaggioVideo = "Attenzione non è soddisfatta la finestra temporale di 18 mesi.";
                        return false;
                    }
                }
            }
            else if (Utility.IsDomandaSperimentaleDonna_DL_4_2019(datiPensione) && !(Utility.IsDomandaUnicarpe(datiPensione, true) == Utility.TipoUnicarpe.Automatica || datiPensione.IsPLUnicarpe.GetValueOrDefault()))
            {
                string strCatNum = datiPensione.GetCodCategoria();
                int catNum;
                int.TryParse(strCatNum, out catNum);

                if (!dataPerfezionamentoRequisiti.HasValue || !dataNascitaTitolare.HasValue)
                    return true;

                // La decorrenza della pensione deve essere maggiore o uguale di 12 mesi per la gestione AGO (VO, VOS, VDAI, VOP) e FS
                if (IsLavoratriceDipendente(catNum, tipoAppartenenza, datiPensione) || catNum == 7)
                {
                    if ((Utility.IsDomandaINPDAP(datiPensione.Gestione) || (tipoFondo.HasValue && (tipoFondo.Value == Utility.TipoFondo.FS || tipoFondo.Value == Utility.TipoFondo.PT))) &&
                        GestioneBypassControllo.CheckAndLockBypassControlloByNomeBypass(datiPensione, GestioneBypassControllo.NomeBypass.Titolare_Anagrafica_FS.DECORRENZA_SPERDONNA_FSPT))
                        return true;

                    // La decorrenza deve partire dalla data perfezionamento requisiti + 12 mesi
                    DateTime dateCompare = dataPerfezionamentoRequisiti.Value.AddMonths(12).AddDays(1);
                    if (decorrenzaOriginaria.Value.CompareTo(dateCompare) < 0)
                    {
                        messaggioVideo = "Attenzione non è soddisfatta la finestra temporale di 12 mesi.";
                        return false;
                    }
                }
                // La decorrenza della pensione deve essere maggiore o uguale di 18 mesi per la gestione Autonoma
                else
                {
                    // La decorrenza deve partire dalla data perfezionamento requisiti + 18 mesi              
                    DateTime dateCompare = dataPerfezionamentoRequisiti.Value.AddMonths(18).AddDays(1);
                    if (decorrenzaOriginaria.Value.CompareTo(dateCompare) < 0)
                    {
                        messaggioVideo = "Attenzione non è soddisfatta la finestra temporale di 18 mesi.";
                        return false;
                    }
                }
            }

            return true;
        }

        /// <summary>
        /// controlli sulla decorrenza degli stati civili per le unioni civili
        /// </summary>
        /// <param name="datiPensione"></param>
        /// <param name="messaggioVideo"></param>
        /// <returns></returns>
        public static bool ALL_VerificaDecorrenzaUnioniCivili(List<GestioneAnagrafica.DatiStatoCivile> listaStatiCivili, GestionePensione.DatiPensione datiPensione, out string messaggioVideo)
        {
            messaggioVideo = string.Empty;
            DateTime dataDecorrenzaUnioniCivili = new DateTime(2016, 06, 01);

            if (GestioneBypassControllo.CheckAndLockBypassControlloByNomeBypass(datiPensione, GestioneBypassControllo.NomeBypass.Sentenza_Unioni_Civili.SENTENZA_UNIONI_CIVILI))
                return true;

            if (listaStatiCivili != null && listaStatiCivili.Count > 0)
            {
                foreach (GestioneAnagrafica.DatiStatoCivile sc in listaStatiCivili)
                {
                    if (sc.Codice == '7' || sc.Codice == '8' || sc.Codice == 'C')
                    {
                        if (sc.Decorrenza.HasValue && !Utility.DataSuccessivaA(sc.Decorrenza.Value, dataDecorrenzaUnioniCivili))
                        {
                            //messaggioVideo = "Non sono ammessi stati civili relativi alle Unioni Civili successivi alla data: " + String.Format("{0:dd/MM/yyyy}", dataDecorrenzaUnioniCivili);
                            messaggioVideo = string.Format("Non sono ammessi stati civili relativi alle Unioni Civili precedenti alla data: {0:dd/MM/yyyy}", dataDecorrenzaUnioniCivili);
                            return false;
                        }
                    }
                }
            }
            return true;
        }

        /// <summary>
        /// Per domande ai superstiti in cui il dante causa è unito civilmente, la decorrenza della domanda del superstite deve essere maggiore o uguale a 07/2016
        /// </summary>
        /// <param name="datiPensione"></param>
        /// <param name="listaFamiliari"></param>
        /// <param name="decorrenzaOriginaria"></param>
        /// <param name="messaggioVideo"></param>
        /// <returns></returns>
        public static bool ALL_VerificaDecorrenzaUnioniCiviliSuperstiti(GestionePensione.DatiPensione datiPensione, List<GestioneFamiliari.Familiare> listaFamiliari, DateTime? decorrenzaOriginaria, out string messaggioVideo)
        {
            messaggioVideo = string.Empty;

            if (Utility.IsDomandaPensioneSuperstitiOrRicostituzione(datiPensione))
            {
                if (GestioneBypassControllo.CheckAndLockBypassControlloByNomeBypass(datiPensione, GestioneBypassControllo.NomeBypass.Sentenza_Unioni_Civili.SENTENZA_UNIONI_CIVILI))
                    return true;

                if (listaFamiliari != null && listaFamiliari.Count > 0)
                {
                    // Se esiste un familiare unito civile, allora il dante causa è unito civile
                    if (listaFamiliari.Exists(x => x.IsUnitoCivile()))
                    {
                        if (decorrenzaOriginaria.HasValue && !Utility.DataSuccessivaA(decorrenzaOriginaria.Value, new DateTime(2016, 7, 1)))
                        {
                            messaggioVideo = "Per domande ai superstiti in cui il dante causa è unito civilmente, la decorrenza della domanda del superstite deve essere maggiore o uguale a 07/2016.";
                            return false;
                        }
                    }
                }
            }

            return true;
        }

        public static bool ALL_VerificaDecorrenzaPensioneAPEPrecoce(GestionePensione.DatiPensione datiPensione, DateTime? decorrenzaOriginaria, GestioneAnagrafica.DatiAnagrafici datiAnagrafici,
            out string messaggioVideo)
        {
            messaggioVideo = string.Empty;

            if (Utility.IsDomandaAPEPrecoci(datiPensione))
            {
                if (decorrenzaOriginaria.HasValue &&
                    (!Utility.DataSuccessivaA(decorrenzaOriginaria.Value, new DateTime(2017, 5, 1))))
                {
                    messaggioVideo = "La Decorrenza Pensione dovrà essere maggiore o uguale al 01/05/2017";
                    return false;
                }
            }

            return true;
        }

        public static bool ALL_VerificaRequisitoEtaDomandaRequisitoAnticipatoArt1(GestionePensione.DatiPensione datiPensioneDB, GestionePensione.DatiPensione datiPensioneUI, DateTime? dataNascitaTitolare, out string messaggioVideo)
        {
            messaggioVideo = string.Empty;
            if ((Utility.IsDomandaVecchiaiaRequisitoAnticipatoArt1(datiPensioneDB) ||
                Utility.IsDomandaVecchiaiaRequisitoAnticipatoArt1OpzioneContributivo(datiPensioneDB)) && datiPensioneUI.DataPerfezionamentoRequisiti.HasValue &&
                Utility.DataSuccessivaA(datiPensioneUI.DataPerfezionamentoRequisiti.Value, new DateTime(2019, 1, 1)) && !Utility.DataStrettamenteSuccessivaA(datiPensioneUI.DataPerfezionamentoRequisiti.Value, new DateTime(2022, 12, 31)))
            {
                int sconto = 0;
                if (Utility.IsDomandaVecchiaiaRequisitoAnticipatoArt1OpzioneContributivo(datiPensioneDB) && datiPensioneUI.SceltaLavMadri.GetValueOrDefault() == 1)
                {
                    sconto = 4 * datiPensioneUI.NumeroFigli.GetValueOrDefault();
                    if (sconto > 12)
                        sconto = 12;
                    DateTime DataPerfReq = (datiPensioneUI.DataPerfezionamentoRequisiti.Value != null ? datiPensioneUI.DataPerfezionamentoRequisiti.Value : new DateTime(1900, 1, 1));
                    if (datiPensioneUI.NumeroFigli > 3 && checkMemo228_2025(datiPensioneDB) && Utility.DataStrettamenteSuccessivaA(DataPerfReq, new DateTime(2024, 12, 31)))
                        sconto = 4 * datiPensioneUI.NumeroFigli.GetValueOrDefault();
                }
                Utility.DifferenzaDateTime requisitoEta = new Utility.DifferenzaDateTime(66, 7, 0);
                if (DateTime.IsLeapYear(dataNascitaTitolare.GetValueOrDefault().Year) && dataNascitaTitolare.GetValueOrDefault().Month == 2 && dataNascitaTitolare.GetValueOrDefault().Day == 29 &&
                    !DateTime.IsLeapYear(datiPensioneUI.DataPerfezionamentoRequisiti.GetValueOrDefault().Year))
                {
                    DateTime dataTitolare = dataNascitaTitolare.GetValueOrDefault().AddYears(66).AddMonths(7).AddMonths(-sconto);
                    dataTitolare = dataTitolare.AddDays(1);
                    if (Utility.DataStrettamenteSuccessivaA(dataTitolare, datiPensioneUI.DataPerfezionamentoRequisiti.GetValueOrDefault()))
                    {
                        messaggioVideo = string.Format("Il titolare della domanda non ha compiuto {0} alla data di perfezionamento del requisito ({1:dd/MM/yyyy})", requisitoEta, datiPensioneUI.DataPerfezionamentoRequisiti);
                        return false;
                    }
                }
                else
                {
                    Utility.DifferenzaDateTime diff = new Utility.DifferenzaDateTime();
                    if (Utility.IsDomandaVecchiaiaRequisitoAnticipatoArt1(datiPensioneDB))
                    {
                        if (!Utility.DataSuccessivaA(datiPensioneUI.DataPerfezionamentoRequisiti.GetValueOrDefault(), dataNascitaTitolare.GetValueOrDefault().AddYears(requisitoEta.Year).AddMonths(requisitoEta.Month).AddMonths(-sconto)))
                        {
                            messaggioVideo = string.Format("Il titolare della domanda non ha compiuto {0} alla data di perfezionamento del requisito ({1:dd/MM/yyyy})", requisitoEta, datiPensioneUI.DataPerfezionamentoRequisiti);
                            return false;
                        }
                    }
                    else
                    {
                        diff = Utility.DifferenzaBetweenDate(datiPensioneUI.DataPerfezionamentoRequisiti, dataNascitaTitolare.GetValueOrDefault().AddMonths(-sconto), Utility.GetTipoAppartenenza(datiPensioneDB.IndConvInt, datiPensioneDB.Gestione));
                        if (diff < requisitoEta)
                        {
                            messaggioVideo = string.Format("Il titolare della domanda non ha compiuto {0} alla data di perfezionamento del requisito ({1:dd/MM/yyyy})", requisitoEta, datiPensioneUI.DataPerfezionamentoRequisiti);
                            return false;
                        }
                    }
                }
            }
            return true;
        }

        public static bool ALL_VerificaFinestraDomandaAnzianitaPerLeggeBilancio2019(GestionePensione.DatiPensione datiPensione, DateTime? decorrenzaOriginaria, DateTime? dataPerfReq,
            bool isRiaperturaDomanda, Utility.TipoAppartenenza? tipoAppartenenza, out string messaggioVideo)
        {
            messaggioVideo = string.Empty;

            Utility.TipoFondo? tipoFondo = Utility.GetTipoFondoByCategoria(datiPensione.IndConvInt, datiPensione.Gestione, datiPensione.SiglaCategoria);
            if ((Utility.IsDomandaUnicarpe(datiPensione, true) == Utility.TipoUnicarpe.Automatica || datiPensione.IsPLUnicarpe.GetValueOrDefault()) && !Utility.IsDomandaRiliquidazioneAnzianitaAnticipata(datiPensione))
                return true;

            if ((Utility.IsDomandaAnzianitaPerLeggeBilancio2019OrRicostituzione(datiPensione, dataPerfezionamentoRequisiti: dataPerfReq) || Utility.IsDomandaRiliquidazioneAnzianitaAnticipataConFinestraDecorrenza(datiPensione, dataPerfezionamentoRequisiti: dataPerfReq)
                || (!Utility.IsDomandaAutomatica(datiPensione) && Utility.IsDomandaAnticipataConOpzionePL(datiPensione)))
                && !Utility.IsDomandaMIN(datiPensione.SiglaCategoria))
            {
                DateTime dataLimite = new DateTime(2019, 4, 1);
                if (!Utility.DataSuccessivaA(decorrenzaOriginaria.Value, dataLimite) && !Utility.IsDomandaCTPS(datiPensione.SiglaCategoria))
                {
                    messaggioVideo = string.Format("La Decorrenza Pensione dovrà essere successiva o uguale al {0:dd/MM/yyyy}", dataLimite);
                    return false;
                }

                if (dataPerfReq.HasValue)
                {
                    // Per cumulo comparto scuola non devono essere applicati i controlli sulla finestra di uscita
                    if (Utility.IsDomandaCumulo(datiPensione.SiglaCategoria) && (!string.IsNullOrEmpty(datiPensione.NaturaPensione) && datiPensione.NaturaPensione.Substring(2, 1) == "S"))
                        return true;

                    if (Utility.IsRicostituzioneOrRiapertura(datiPensione, isRiaperturaDomanda) &&
                        (dataPerfReq.Value == new DateTime(2019, 1, 30) || dataPerfReq.Value == new DateTime(2019, 1, 31)) &&
                        decorrenzaOriginaria.Value.Year == 2019 && decorrenzaOriginaria.Value.Month == 4)
                        return true;

                    if (tipoFondo != Utility.TipoFondo.FS && tipoFondo != Utility.TipoFondo.PT && !Utility.IsDomandaINPDAP(datiPensione.Gestione))
                    {
                        if (((tipoFondo == Utility.TipoFondo.ET || tipoFondo == Utility.TipoFondo.EL || tipoFondo == Utility.TipoFondo.TT) &&
                            GestioneBypassControllo.CheckAndLockBypassControlloByNomeBypass(datiPensione, GestioneBypassControllo.NomeBypass.Titolare_Anagrafica_FS.DECORRENZA_RIC_FONDI)) ||
                            (tipoAppartenenza.HasValue && tipoAppartenenza.Value == Utility.TipoAppartenenza.AGO &&
                            GestioneBypassControllo.CheckAndLockBypassControlloByNomeBypass(datiPensione, GestioneBypassControllo.NomeBypass.Titolare_Anagrafica_AGO.DECORRENZA_PL_RIC_AGO)))
                            return true;

                        DateTime dataMinima = Utility.FirstDayOfMonth(dataPerfReq.Value.AddMonths(4));
                        if (Utility.DataSuccessivaA(dataPerfReq.Value, new DateTime(2019, 1, 1)) && !Utility.DataStrettamenteSuccessivaA(dataPerfReq.Value, new DateTime(2019, 1, 29)))
                            dataMinima = new DateTime(2019, 4, 1);
                        if (decorrenzaOriginaria.HasValue && !Utility.DataSuccessivaA(decorrenzaOriginaria.Value, dataMinima))
                        {
                            messaggioVideo = string.Format("La Decorrenza Pensione dovrà essere successiva o uguale al {0:MM/yyyy}", dataMinima);
                            return false;
                        }
                    }
                    else
                    {
                        if (!GestioneBypassControllo.CheckAndLockBypassControlloByNomeBypass(datiPensione, GestioneBypassControllo.NomeBypass.Titolare_Anagrafica_FS.DECORRENZA_ANTICIPATA_FSPT))
                        {
                            DateTime? dataMinima = null;
                            if (Utility.DataSuccessivaA(dataPerfReq.Value, new DateTime(2019, 1, 1)) && !Utility.DataStrettamenteSuccessivaA(dataPerfReq.Value, new DateTime(2019, 1, 29)))
                                dataMinima = new DateTime(2019, 4, 1);
                            else
                            {
                                try
                                {
                                    int numMesi = 3;
                                    dataMinima = dataPerfReq.Value.AddMonths(numMesi).AddDays(1);
                                }
                                catch (Exception)
                                {
                                    dataMinima = Utility.FirstDayOfMonth(dataPerfReq.Value.AddMonths(4));
                                }
                            }

                            if ((!dataMinima.HasValue || (decorrenzaOriginaria.HasValue && !Utility.DataSuccessivaA(decorrenzaOriginaria.Value, dataMinima.Value))) && !Utility.IsDomandaCTPS(datiPensione.SiglaCategoria))
                            {
                                messaggioVideo = string.Format("La Decorrenza Pensione dovrà essere successiva o uguale al {0:dd/MM/yyyy}", dataMinima);
                                return false;
                            }
                        }
                    }
                }
            }

            return true;
        }

        public static bool ALL_VerificaDecorrenzaPensioneQuota100(GestionePensione.DatiPensione datiPensione, DateTime? decorrenzaOriginaria, DateTime? dataPerfezionamentoRequisiti,
            bool? lavoratorePubblico, out string messaggioVideo)
        {
            messaggioVideo = string.Empty;

            if (Utility.IsDomandaQuota100(datiPensione))
            {
                if (decorrenzaOriginaria.HasValue)
                {
                    DateTime dataLimite = lavoratorePubblico.GetValueOrDefault() ? new DateTime(2019, 8, 1) : new DateTime(2019, 4, 1);
                    if (!Utility.DataSuccessivaA(decorrenzaOriginaria.Value, dataLimite) && !Utility.IsDomandaCTPS(datiPensione.SiglaCategoria))
                    {
                        messaggioVideo = string.Format("La Decorrenza Pensione dovrà essere successiva o uguale al {0:dd/MM/yyyy}", dataLimite);
                        return false;
                    }

                    if (!dataPerfezionamentoRequisiti.HasValue)
                    {
                        Utility.TipoFondo? tipoFondo = Utility.GetTipoFondoByCategoria(datiPensione.IndConvInt, datiPensione.Gestione, datiPensione.SiglaCategoria);
                        Utility.TipoAppartenenza? tipoAppartenenza = Utility.GetTipoAppartenenza(datiPensione.IndConvInt, datiPensione.Gestione);
                        if (!(tipoAppartenenza.Value == Utility.TipoAppartenenza.FS && (tipoFondo == Utility.TipoFondo.FS || tipoFondo == Utility.TipoFondo.PT) && (Utility.IsRicostituzione_MotiviDocumentali(datiPensione) || Utility.IsRicEsenzioneFiscaleVittimeDelDovere(datiPensione) || Utility.IsRicostituzione_Reddituale(datiPensione) || Utility.IsRicostituzione_TrattamentoDiFamiglia(datiPensione))))
                        {
                            messaggioVideo = "Data Perfezionamento Requisiti obbligatoria.";
                            return false;
                        }
                    }
                    else
                    {
                        // Per cumulo comparto scuola non devono essere applicati i controlli sulla finestra di uscita
                        if (Utility.IsDomandaCumulo(datiPensione.SiglaCategoria) && lavoratorePubblico.GetValueOrDefault() &&
                            (!datiPensione.IsCumuloAutomatica.GetValueOrDefault() || (!string.IsNullOrEmpty(datiPensione.NaturaPensione) && datiPensione.NaturaPensione.Substring(2, 1) == "S")))
                            return true;

                        Utility.TipoFondo? tipoFondo = Utility.GetTipoFondoByCategoria(datiPensione.IndConvInt, datiPensione.Gestione, datiPensione.SiglaCategoria);
                        if (!(Utility.IsDomandaUnicarpe(datiPensione, true) == Utility.TipoUnicarpe.Automatica || datiPensione.IsPLUnicarpe.GetValueOrDefault()))
                        {
                            if (tipoFondo != Utility.TipoFondo.FS && tipoFondo != Utility.TipoFondo.PT && !Utility.IsDomandaINPDAP(datiPensione.Gestione))
                            {
                                int mesiLimite = lavoratorePubblico.GetValueOrDefault() ? 7 : 4;
                                if (!Utility.DataSuccessivaA(decorrenzaOriginaria.Value, Utility.FirstDayOfMonth(dataPerfezionamentoRequisiti.Value.AddMonths(mesiLimite))))
                                {
                                    messaggioVideo = string.Format("La decorrenza pensione deve essere di almeno {0} mesi successiva alla data di perfezionamento dei requisiti.", mesiLimite - 1);
                                    return false;
                                }
                            }
                            else
                            {
                                if (!GestioneBypassControllo.CheckAndLockBypassControlloByNomeBypass(datiPensione, GestioneBypassControllo.NomeBypass.Titolare_Anagrafica_FS.DECORRENZA_QUOTA100_FSPT))
                                {
                                    int mesiLimite = lavoratorePubblico.GetValueOrDefault() ? 6 : 3;
                                    DateTime? dataMinima = null;
                                    try
                                    {
                                        dataMinima = dataPerfezionamentoRequisiti.Value.AddMonths(mesiLimite).AddDays(1);
                                    }
                                    catch (Exception)
                                    {
                                        dataMinima = Utility.FirstDayOfMonth(dataPerfezionamentoRequisiti.Value.AddMonths(mesiLimite + 1));
                                    }
                                    if (!Utility.DataSuccessivaA(decorrenzaOriginaria.Value, dataMinima.Value) && !Utility.IsDomandaCTPS(datiPensione.SiglaCategoria))
                                    {
                                        messaggioVideo = string.Format("La Decorrenza Pensione dovrà essere successiva o uguale al {0:dd/MM/yyyy}", dataMinima);
                                        return false;
                                    }
                                }
                            }
                        }
                    }
                }
            }

            return true;
        }

        public static bool ALL_VerificaRequisitoEtaQuota100(GestionePensione.DatiPensione datiPensione, DateTime? dataPerfezionamentoRequisiti, DateTime? dataNascitaTitolare, out string messaggioVideo)
        {
            messaggioVideo = string.Empty;

            Utility.TipoFondo? tipoFondo = Utility.GetTipoFondoByCategoria(datiPensione.IndConvInt, datiPensione.Gestione, datiPensione.SiglaCategoria);
            Utility.TipoAppartenenza? tipoAppartenenza = Utility.GetTipoAppartenenza(datiPensione.IndConvInt, datiPensione.Gestione);
            Utility.DifferenzaDateTime requisitoEta = new Utility.DifferenzaDateTime(62, 0, 0);
            if (Utility.IsDomandaQuota100(datiPensione))
            {
                if (!(tipoAppartenenza.Value == Utility.TipoAppartenenza.FS && (tipoFondo == Utility.TipoFondo.FS || tipoFondo == Utility.TipoFondo.PT) && (Utility.IsRicostituzione_MotiviDocumentali(datiPensione) || Utility.IsRicEsenzioneFiscaleVittimeDelDovere(datiPensione) || Utility.IsRicostituzione_Reddituale(datiPensione) || Utility.IsRicostituzione_TrattamentoDiFamiglia(datiPensione))))
                {
                    Utility.DifferenzaDateTime diff = Utility.DifferenzaBetweenDate(dataPerfezionamentoRequisiti, dataNascitaTitolare, Utility.GetTipoAppartenenza(datiPensione.IndConvInt, datiPensione.Gestione));
                    if (diff < requisitoEta)
                    {
                        messaggioVideo = string.Format("Il titolare della domanda non ha compiuto {0} alla data di perfezionamento del requisito ({1:dd/MM/yyyy})", requisitoEta, dataPerfezionamentoRequisiti);
                        return false;
                    }
                }
            }

            return true;
        }

        /// <summary>
        /// Per le domande di quota 100 manuali, la Data Perfezionamento Requisiti non può essere successiva al 31/12/2021
        /// </summary>
        /// <param name="datiPensione"></param>
        /// <param name="dataPerfezionamentoRequisiti"></param>
        /// <param name="messaggioVideo"></param>
        /// <returns></returns>
        public static bool ALL_VerificaPerfezionamentoRequisitiQuota100(GestionePensione.DatiPensione datiPensione, DateTime? dataPerfezionamentoRequisiti, out string messaggioVideo)
        {
            messaggioVideo = string.Empty;
            DateTime dataCompare = new DateTime(2021, 12, 31);

            if (Utility.IsDomandaQuota100(datiPensione))
            {
                if (!(Utility.IsDomandaUnicarpe(datiPensione, true) == Utility.TipoUnicarpe.Automatica || datiPensione.IsPLUnicarpe.GetValueOrDefault()))
                {
                    if (dataPerfezionamentoRequisiti.HasValue)
                    {
                        if (Utility.DataStrettamenteSuccessivaA(dataPerfezionamentoRequisiti.Value, dataCompare))
                        {
                            messaggioVideo = string.Format("La Data Perfezionamento Requisiti non può essere successiva al {0:dd/MM/yyyy}", dataCompare);
                            return false;
                        }
                    }
                }
            }

            return true;
        }

        public static bool ALL_VerificaDecorrenzaPensionePrecoci(GestionePensione.DatiPensione datiPensione, DateTime? decorrenzaOriginaria, DateTime? dataPerfezionamentoRequisiti, out string messaggioVideo)
        {
            messaggioVideo = string.Empty;

            Utility.TipoFondo? tipoFondo = Utility.GetTipoFondoByCategoria(datiPensione.IndConvInt, datiPensione.Gestione, datiPensione.SiglaCategoria);

            if (Utility.IsDomandaAPEPrecoci(datiPensione))
            {
                if (decorrenzaOriginaria.HasValue)
                {
                    //ENG - Modifica TRF Precoci 024
                    GestioneControlliDinamici.ControlloDinamico ctrlDataAcquisizionePLPrecoci = null;
                    DateTime? dataLimiteAcquisizionePL = null;
                    GestionePensione.DatiPensione datiPensionePrimaLiquidata = null;
                    if ((tipoFondo == Utility.TipoFondo.FS || tipoFondo == Utility.TipoFondo.PT) && Utility.IsRiaperturaDomanda(datiPensione.Id))
                    {
                        GestioneControlliDinamici.GetControlloDinamicoByNomeControllo("DataLimiteAcquisizionePLPrecoci024", out ctrlDataAcquisizionePLPrecoci);
                        if (ctrlDataAcquisizionePLPrecoci != null && !String.IsNullOrEmpty(ctrlDataAcquisizionePLPrecoci.ValoreControllo) && !String.IsNullOrEmpty(ctrlDataAcquisizionePLPrecoci.ValoreControllo.Trim()))
                            dataLimiteAcquisizionePL = Utility.DataFromString(ctrlDataAcquisizionePLPrecoci.ValoreControllo.Trim(), Utility.FormatoData.AAAAmmGG);
                        GestionePensione.GetPensioneByNumeroDomandaAndProg(datiPensione.NDomus, 1, out datiPensionePrimaLiquidata); //Recupero la PL della TRF
                    }

                    DateTime dataLimite = new DateTime(2017, 5, 1);
                    if (!Utility.DataSuccessivaA(decorrenzaOriginaria.Value, dataLimite) && !Utility.IsDomandaCTPS(datiPensione.SiglaCategoria))
                    {
                        messaggioVideo = string.Format("La Decorrenza Pensione dovrà essere successiva o uguale al {0:dd/MM/yyyy}", dataLimite);
                        return false;
                    }

                    if (dataPerfezionamentoRequisiti.HasValue && Utility.DataSuccessivaA(dataPerfezionamentoRequisiti.Value, new DateTime(2019, 1, 1)) &&
                        !Utility.DataStrettamenteSuccessivaA(dataPerfezionamentoRequisiti.Value, new DateTime(2026, 12, 31)))
                    {
                        if (!(Utility.IsDomandaUnicarpe(datiPensione, true) == Utility.TipoUnicarpe.Automatica || datiPensione.IsPLUnicarpe.GetValueOrDefault()))
                        {
                            if (tipoFondo != Utility.TipoFondo.FS && tipoFondo != Utility.TipoFondo.PT && !Utility.IsDomandaINPDAP(datiPensione.Gestione))
                            {
                                int mesiLimite = 4;
                                if (!Utility.DataSuccessivaA(decorrenzaOriginaria.Value, Utility.FirstDayOfMonth(dataPerfezionamentoRequisiti.Value.AddMonths(mesiLimite))) &&
                                   !((Utility.IsDomandaVOCUM(datiPensione.SiglaCategoria) && GestioneBypassControllo.CheckAndLockBypassControlloByNomeBypass(datiPensione, GestioneBypassControllo.NomeBypass.Titolare_Anagrafica_AGO.COMPARTO_SCUOLA))
                                   || Utility.IsDomandaVOCUM(datiPensione.SiglaCategoria) && (!string.IsNullOrEmpty(datiPensione.NaturaPensione) && datiPensione.NaturaPensione.Substring(2, 1) == "S")))
                                {
                                    messaggioVideo = string.Format("La decorrenza pensione deve essere di almeno {0} mesi successiva alla data di perfezionamento dei requisiti.", mesiLimite - 1);
                                    return false;
                                }
                            }
                            else
                            {
                                if (!GestioneBypassControllo.CheckAndLockBypassControlloByNomeBypass(datiPensione, GestioneBypassControllo.NomeBypass.Titolare_Anagrafica_FS.DECORRENZA_PRECOCI_FSPT))
                                {
                                    int mesiLimite = 3;
                                    DateTime? dataMinima = null;
                                    try
                                    {
                                        int numMesi = mesiLimite;
                                        if (dataPerfezionamentoRequisiti.Value.Month != dataPerfezionamentoRequisiti.Value.AddDays(1).Month)
                                            numMesi += 1;
                                        int year = dataPerfezionamentoRequisiti.Value.AddMonths(mesiLimite).Year;
                                        int month = dataPerfezionamentoRequisiti.Value.AddMonths(mesiLimite).Month;
                                        int day = dataPerfezionamentoRequisiti.Value.AddDays(1).Day;
                                        dataMinima = new DateTime(year, month, day);
                                    }
                                    catch (Exception)
                                    {
                                        dataMinima = Utility.FirstDayOfMonth(dataPerfezionamentoRequisiti.Value.AddMonths(mesiLimite + 1));
                                    }
                                    if (!Utility.DataSuccessivaA(decorrenzaOriginaria.Value, dataMinima.Value) && !Utility.IsDomandaCTPS(datiPensione.SiglaCategoria))
                                    {
                                        messaggioVideo = string.Format("La decorrenza pensione deve essere di almeno {0} mesi successiva alla data di perfezionamento dei requisiti.", mesiLimite);
                                        return false;
                                    }
                                }
                            }
                        }
                    }

                    //ENG - Modifica TRF Precoci 024
                    if ((tipoFondo == Utility.TipoFondo.FS || tipoFondo == Utility.TipoFondo.PT) && Utility.IsRiaperturaDomanda(datiPensione.Id)
                        && (datiPensionePrimaLiquidata == null || (datiPensionePrimaLiquidata.DataAcquisizione.HasValue && dataLimiteAcquisizionePL.HasValue && !Utility.DataSuccessivaA(datiPensionePrimaLiquidata.DataAcquisizione.Value, dataLimiteAcquisizionePL.Value)))
                        && Utility.DataSuccessivaA(datiPensione.DataPresentazioneDomanda, decorrenzaOriginaria.Value))
                    {
                        messaggioVideo = "La decorrenza pensione non può essere precedente alla data presentazione";
                        return false;
                    }
                }
            }

            return true;
        }

        public static bool ALL_ControlsRequisitoEta(GestionePensione.DatiPensione datiPensioneDB, Utility.TipoAppartenenza? tipoAppartenenza, bool isRiaperturaDomanda, GestionePensione.DatiPensione datiPensioneUI, DateTime? dataNascitaTitolare, char? sessoTitolare, byte? legge44997,
                long? codiceParticolareSoggettoDerogato, char? derogaTraduzioneSuGP, string tipoSettimaneBeneficio, DateTime? dataWarning, DateTime? dataAssunzioneCarico, out string messaggioVideo)
        {
            messaggioVideo = string.Empty;

            GestioneControlliDinamici.ControlloDinamico ctrlMemo123 = null;
            GestioneControlliDinamici.GetControlloDinamicoByNomeControllo("AbilitazioneMemo123_2021", out ctrlMemo123);

            //ENG - Memo 123/2024
            GestioneControlliDinamici.ControlloDinamico ctrlMemo123_2024 = null;
            GestioneControlliDinamici.GetControlloDinamicoByNomeControllo("AbilitazioneRIC_TRFMemo123_2024", out ctrlMemo123_2024);

            //ENG - Memo 123/2024
            GestioneControlliDinamici.ControlloDinamico ctrlMemo123_2024OpzioneContrib = null;
            GestioneControlliDinamici.GetControlloDinamicoByNomeControllo("AbilitazioneRIC_TRFMemo123_2024OpzioneContrib", out ctrlMemo123_2024OpzioneContrib);

            if (GestioneCtrlControlliApplicativi.CheckControlloApplicativoAttivoByData(GetEnumBypassRequisitoEta(tipoAppartenenza), GestioneControlliDinamici.GetDataSistema(tipoAppartenenza)) ||
                (
                (Utility.IsRicostituzioneOrRiapertura(datiPensioneDB, isRiaperturaDomanda) ||
                (!(datiPensioneDB.Gruppo == "0001" && datiPensioneDB.Prodotto == "0002") && !Utility.IsDomandaRiliquidazioneVecchiaia(datiPensioneDB))) &&
                !Utility.IsForceCtrlRequisitoEtaPerAUT(datiPensioneDB, dataAssunzioneCarico)) ||
                (!Utility.IsForceCtrlRequisitoEtaPerPescatori(datiPensioneUI, datiPensioneDB) && Utility.IsDomandaVOP(datiPensioneDB.SiglaCategoria)) ||
                Utility.IsDomandaAutomatica(datiPensioneDB) || Utility.IsDomandaQuota100(datiPensioneDB) || Utility.IsDomandaQuota102(datiPensioneDB) || Utility.IsDomandaAnticipataFlessibile(datiPensioneDB) || Utility.IsDomandaAPEPrecoci(datiPensioneDB) ||
                Utility.IsDomandaAnticipataFlessibileOpzioneContributivo(datiPensioneDB) ||
                Utility.IsDomandaAnzianitaPerLeggeBilancio2019OrRicostituzione(datiPensioneDB, datiPensioneUI.DataPerfezionamentoRequisiti) ||
                Utility.IsDomandaSperimentaleDonnaOrRicostituzione(datiPensioneDB) || Utility.IsDomandaSperimentaleDonna_DL_4_2019OrRicostituzione(datiPensioneDB) ||
                Utility.IsDomandaSalvaguardia122(datiPensioneDB) || Utility.IsDomandaSalvaguardia122_FS_2011_2012(datiPensioneDB, derogaTraduzioneSuGP) || Utility.IsDomandaSalvaguardia124(datiPensioneDB) ||
                Utility.IsDomandaSalvaguardia124Art11Bis(datiPensioneDB) || Utility.IsDomandaSalvaguardia135(datiPensioneDB) || Utility.IsDomandaSalvaguardia147(datiPensioneDB) ||
                Utility.IsDomandaSalvaguardia147_2014(datiPensioneDB) || Utility.IsDomandaSalvaguardia208_2015(datiPensioneDB) || Utility.IsDomandaSalvaguardia214(datiPensioneDB) ||
                Utility.IsDomandaSalvaguardia228(datiPensioneDB) || Utility.IsDomandaSalvaguardia232_2016(datiPensioneDB) ||
                Utility.IsDomandaSalvaguardia178_2020(datiPensioneDB) || Utility.IsDomandaSalvaguardiaAutomatica(datiPensioneDB) ||
                Utility.IsDomandaVecchiaiaRequisitoAnticipatoArt1_NoCheck(datiPensioneDB, datiPensioneUI.DataPerfezionamentoRequisiti) ||
                Utility.IsDomandaVOSPED(datiPensioneDB.SiglaCategoria) || Utility.IsDomandaINDCOM(datiPensioneDB.SiglaCategoria) ||
                GestioneBypassControllo.CheckAndLockBypassControlloByNomeBypass(datiPensioneDB, GestioneBypassControllo.NomeBypass.Titolare_Anagrafica_AGO.LIMITE_ETA_ENAV) ||
                GestioneBypassControllo.CheckAndLockBypassControlloByNomeBypass(datiPensioneDB, GestioneBypassControllo.NomeBypass.Titolare_Anagrafica_AGO.APPLICAZIONE_SENTENZA) ||
                GestioneBypassControllo.CheckAndLockBypassControlloByNomeBypass(datiPensioneDB, GestioneBypassControllo.NomeBypass.Requisito_Eta.REQUISITO_ETA)
                || Utility.IsDomandaPensioneAnticipataTipo0008(datiPensioneDB) || (tipoAppartenenza == Utility.TipoAppartenenza.AGO && Utility.IsDomandaManualeInvaliditaOver80(datiPensioneDB)) ||
                Utility.IsDomandaVOPGI_AGI(datiPensioneDB) || Utility.IsDomandaPersonaleViaggianteConPerditaTitoloAbilitante(datiPensioneDB) || Utility.IsDomandaPersonaleViaggianteConPerditaTitoloAbilitanteVOCPDEL(datiPensioneDB) ||
                (!Utility.IsRicostituzioneOrRiapertura(datiPensioneDB, isRiaperturaDomanda) && (Utility.IsDomandaAnticipataFlessibileLeggeBilancio2024(datiPensioneDB) || Utility.IsDomandaAnticipataFlessibileOpzioneContributivoLeggeBilancio2024(datiPensioneDB))) ||
                (Utility.IsRicostituzioneOrRiapertura(datiPensioneDB, isRiaperturaDomanda) && ((ctrlMemo123_2024 != null && ctrlMemo123_2024.ValoreControllo == "SI" && Utility.IsDomandaAnticipataFlessibileLeggeBilancio2024(datiPensioneDB)) ||
                (ctrlMemo123_2024OpzioneContrib != null && ctrlMemo123_2024OpzioneContrib.ValoreControllo == "SI" && Utility.IsDomandaAnticipataFlessibileOpzioneContributivoLeggeBilancio2024(datiPensioneDB)))) || Utility.IsDomandaVOAUTAnticipataFlessibileLeggeBilancio2024FiltroGSE(datiPensioneDB))
            {
                return true;
            }
            switch (tipoAppartenenza)
            {
                case Utility.TipoAppartenenza.AGO:
                    if (Utility.IsDomandaAPESociale(datiPensioneDB.SiglaCategoria) || Utility.IsDomandaVOCOOP_COOP28(datiPensioneDB.SiglaCategoria) ||
                        Utility.IsDomandaVOCRED_CRED27(datiPensioneDB.SiglaCategoria) || Utility.IsDomandaVESO29(datiPensioneDB.SiglaCategoria) ||
                        Utility.IsDomandaVESO33(datiPensioneDB.SiglaCategoria) || Utility.IsDomandaVESO92(datiPensioneDB.SiglaCategoria) ||
                        Utility.IsDomandaVOESO(datiPensioneDB.SiglaCategoria) || Utility.IsDomandaESOTEL(datiPensioneDB.SiglaCategoria) ||
                        Utility.IsDomandaESOAMB(datiPensioneDB.SiglaCategoria) || Utility.IsDomandaESPA(datiPensioneDB.SiglaCategoria) ||
                        (!string.IsNullOrEmpty(tipoSettimaneBeneficio) && tipoSettimaneBeneficio == "10"))
                        return true;
                    break;
                case Utility.TipoAppartenenza.FS:

                    if (!string.IsNullOrEmpty(tipoSettimaneBeneficio) && tipoSettimaneBeneficio == "05")
                        return true;
                    break;
                case Utility.TipoAppartenenza.CI:
                    // Se 
                    //•	Flag “Cieco / Ex Combattente” = TRUE
                    //oppure
                    //•	Codice Requisiti Ridotti = “INVALIDO ALL’80%”
                    //oppure
                    //•	Soggetto Derogato <> 0
                    // allora bypasso il controllo
                    if (datiPensioneDB.ExCombattente.GetValueOrDefault() || legge44997.GetValueOrDefault() == 6 || codiceParticolareSoggettoDerogato.GetValueOrDefault() != 0 ||
                        Utility.IsPensioneAnzianitaOrRicostituzione(datiPensioneDB, null) ||
                        (!string.IsNullOrEmpty(tipoSettimaneBeneficio) && tipoSettimaneBeneficio == "10"))
                        return true;
                    break;
            }

            string codCategoria = datiPensioneDB.GetCodCategoria();

            if (!dataNascitaTitolare.HasValue)
            {
                messaggioVideo = "Errore: data nascita del titolare non presente.";
                return false;
            }

            if (datiPensioneUI.DataPerfezionamentoRequisiti.HasValue)
            {
                if (tipoAppartenenza == Utility.TipoAppartenenza.AGO && Utility.IsDomandaVecchiaiaENAV(datiPensioneDB))
                {
                    if (Utility.DataStrettamenteSuccessivaA(dataNascitaTitolare.Value.AddYears(60), datiPensioneUI.DataPerfezionamentoRequisiti.Value))
                    {
                        messaggioVideo = string.Format("Alla data perfezionamento requisiti ({0:dd/MM/yyyy}) non è stato raggiunto il requisito di età di 60 anni", datiPensioneUI.DataPerfezionamentoRequisiti.Value);
                        return false;
                    }
                }
                else
                {
                    //Nel caso di gestione lavoratrici madri, se la scelta lavoratrici madri è pari a 1 (anticipo età) applico sconto di 4 mesi per ogni figlio
                    bool isApplicazioneSconto = Utility.IsGestioneLavoratriciMadri(datiPensioneDB) && sessoTitolare.GetValueOrDefault() == 'F' && datiPensioneUI.SceltaLavMadri.GetValueOrDefault() == 1;
                    DateTime dataRiferimento = datiPensioneUI.DataPerfezionamentoRequisiti.Value;
                    string nomeDataRiferimento = string.Empty;
                    //Modifica Contributivo v4.6
                    //if (Utility.IsDomandaTipoContributivo(datiPensioneDB, false, true))
                    //    Utility.GetDataRiferimento(datiPensioneDB.DataRaggiungimentoOpzione, datiPensioneUI.DataPerfezionamentoRequisiti, out dataRiferimento, out nomeDataRiferimento);
                    if (dataWarning.HasValue)
                    {
                        if (!isApplicazioneSconto)
                            return false;
                        nomeDataRiferimento = "decorrenza";
                        dataRiferimento = dataWarning.Value;
                    }
                    int reqAA = 0;
                    int reqMM = 0;
                    GestioneDecodifica.GetCtrlRequisitoEta_Base(dataRiferimento, codCategoria, sessoTitolare.GetValueOrDefault(), tipoAppartenenza.ToString(), out reqAA, out reqMM);
                    if (reqAA > 0 || reqMM > 0)
                    {
                        int sconto = 0;
                        if (!dataWarning.HasValue && isApplicazioneSconto)
                        {
                            sconto = 4 * datiPensioneUI.NumeroFigli.GetValueOrDefault();
                            if (sconto > 12)
                                sconto = 12;
                            DateTime DataPerfReq = (datiPensioneUI.DataPerfezionamentoRequisiti.Value != null ? datiPensioneUI.DataPerfezionamentoRequisiti.Value : new DateTime(1900, 1, 1));
                            if (datiPensioneUI.NumeroFigli > 3 && checkMemo228_2025(datiPensioneDB) && Utility.DataStrettamenteSuccessivaA(DataPerfReq, new DateTime(2024, 12, 31)))
                                sconto = 4 * datiPensioneUI.NumeroFigli.GetValueOrDefault();

                        }
                        // Se la data di raggiungimento del requisito è strettamente successiva alla data perferzionamento requisiti lancio errore
                        if (Utility.DataStrettamenteSuccessivaA(dataNascitaTitolare.Value.AddYears(reqAA).AddMonths(reqMM).AddMonths(-sconto), dataRiferimento))
                        {

                            if (sconto > 0)
                            {
                                reqMM -= sconto;
                                while (reqMM < 0)
                                {
                                    reqAA -= 1;
                                    reqMM += 12;
                                }
                            }

                            messaggioVideo = string.Format(
                                "Alla data perfezionamento requisiti ({0:dd/MM/yyyy}) non è stato raggiunto il requisito di età di {1} AA e {2} MM",
                                datiPensioneUI.DataPerfezionamentoRequisiti.Value, reqAA, reqMM
                            );
                            return false;
                        }
                    }
                }


            }

            return true;
        }

        public static bool checkMemo228_2025(GestionePensione.DatiPensione datiPensioneDB)
        {
            bool retVal = false;

            GestioneControlliDinamici.ControlloDinamico abilitazioneMemo228_2025 = null;
            GestioneControlliDinamici.GetControlloDinamicoByNomeControllo("AbilitazioneMemo228_2025", out abilitazioneMemo228_2025);
            if (!string.IsNullOrEmpty(abilitazioneMemo228_2025.ValoreControllo))
            {
                DateTime DataLimite = new DateTime(1900, 1, 1);
                if (DateTime.TryParse(abilitazioneMemo228_2025.ValoreControllo, out DataLimite))
                {
                    if (DateTime.Now.Date >= DataLimite)
                    {
                        if ((datiPensioneDB.Gruppo == "0001" && datiPensioneDB.Prodotto == "0001" && datiPensioneDB.Tipo == "0017") ||
                           (datiPensioneDB.Gruppo == "0001" && datiPensioneDB.Prodotto == "0002" && datiPensioneDB.Tipo == "0017") ||
                           (datiPensioneDB.Gruppo == "0001" && datiPensioneDB.Prodotto == "0002" && datiPensioneDB.Tipo == "0030") ||
                           (datiPensioneDB.Gruppo == "0001" && datiPensioneDB.Prodotto == "0002" && datiPensioneDB.Tipo == "0045") ||
                           (datiPensioneDB.Gruppo == "0001" && datiPensioneDB.Prodotto == "0001" && datiPensioneDB.Tipo == "0045" &&
                                 datiPensioneDB.CodiceTipoRichiesta == "AV") || Utility.IsRicostituzione(datiPensioneDB.Gruppo))
                        {
                            retVal = true;
                        }
                    }
                }
                else
                {
                    throw new INPS.DNA.DnaApplicationException("Errore nel Parse della Data del Controllo Dinamico controlloDinamicoMemo228_2025");
                }
            }

            return retVal;
        }

        public static bool AGO_ControlsRequisitoEtaInvaliditaOver80(GestionePensione.DatiPensione datiPensioneDB, GestionePensione.DatiPensione datiPensioneUI, DateTime? dataNascitaTitolare, char? sessoTitolare, out string messaggioVideo)
        {
            messaggioVideo = string.Empty;

            //ENG - Estesa gestione alla linea AGO per le invalidità over 80
            Utility.TipoAppartenenza? tipoAppartenenza = Utility.GetTipoAppartenenza(datiPensioneDB.IndConvInt, datiPensioneDB.Gestione);

            if (tipoAppartenenza == Utility.TipoAppartenenza.AGO && Utility.IsDomandaManualeInvaliditaOver80(datiPensioneDB))
            {
                if (!dataNascitaTitolare.HasValue)
                {
                    messaggioVideo = "Errore: data nascita del titolare non presente.";
                    return false;
                }

                int annoRiferimento = datiPensioneUI.DataPerfezionamentoRequisiti.Value.Year;
                string requisitoEta = string.Empty;

                if (annoRiferimento <= 2012)
                {
                    if (sessoTitolare == 'M' && Utility.DataStrettamenteSuccessivaA(dataNascitaTitolare.Value.AddYears(60), datiPensioneUI.DataPerfezionamentoRequisiti.Value))
                        requisitoEta = "60 anni";
                    else if (sessoTitolare == 'F' && Utility.DataStrettamenteSuccessivaA(dataNascitaTitolare.Value.AddYears(55), datiPensioneUI.DataPerfezionamentoRequisiti.Value))
                        requisitoEta = "55 anni";
                }
                else
                {
                    switch (annoRiferimento)
                    {
                        case 2013:
                        case 2014:
                        case 2015:
                            if (sessoTitolare == 'M' && Utility.DataStrettamenteSuccessivaA(dataNascitaTitolare.Value.AddYears(60).AddMonths(3), datiPensioneUI.DataPerfezionamentoRequisiti.Value))
                                requisitoEta = "60 anni e 3 mesi";
                            else if (sessoTitolare == 'F' && Utility.DataStrettamenteSuccessivaA(dataNascitaTitolare.Value.AddYears(55).AddMonths(3), datiPensioneUI.DataPerfezionamentoRequisiti.Value))
                                requisitoEta = "55 anni e 3 mesi";
                            break;
                        case 2016:
                        case 2017:
                        case 2018:
                            if (sessoTitolare == 'M' && Utility.DataStrettamenteSuccessivaA(dataNascitaTitolare.Value.AddYears(60).AddMonths(7), datiPensioneUI.DataPerfezionamentoRequisiti.Value))
                                requisitoEta = "60 anni e 7 mesi";
                            else if (sessoTitolare == 'F' && Utility.DataStrettamenteSuccessivaA(dataNascitaTitolare.Value.AddYears(55).AddMonths(7), datiPensioneUI.DataPerfezionamentoRequisiti.Value))
                                requisitoEta = "55 anni e 7 mesi";
                            break;
                        case 2019:
                        case 2020:
                        case 2021:
                        case 2022:
                            if (sessoTitolare == 'M' && Utility.DataStrettamenteSuccessivaA(dataNascitaTitolare.Value.AddYears(61), datiPensioneUI.DataPerfezionamentoRequisiti.Value))
                                requisitoEta = "61 anni";
                            else if (sessoTitolare == 'F' && Utility.DataStrettamenteSuccessivaA(dataNascitaTitolare.Value.AddYears(56), datiPensioneUI.DataPerfezionamentoRequisiti.Value))
                                requisitoEta = "56 anni";
                            break;
                        case 2023:
                        case 2024:
                            if (sessoTitolare == 'M' && Utility.DataStrettamenteSuccessivaA(dataNascitaTitolare.Value.AddYears(61), datiPensioneUI.DataPerfezionamentoRequisiti.Value))
                                requisitoEta = "61 anni";
                            else if (sessoTitolare == 'F' && Utility.DataStrettamenteSuccessivaA(dataNascitaTitolare.Value.AddYears(56), datiPensioneUI.DataPerfezionamentoRequisiti.Value))
                                requisitoEta = "56 anni";
                            break;
                        case 2025:
                        case 2026:
                            if (sessoTitolare == 'M' && Utility.DataStrettamenteSuccessivaA(dataNascitaTitolare.Value.AddYears(61), datiPensioneUI.DataPerfezionamentoRequisiti.Value))
                                requisitoEta = "61 anni";
                            else if (sessoTitolare == 'F' && Utility.DataStrettamenteSuccessivaA(dataNascitaTitolare.Value.AddYears(56), datiPensioneUI.DataPerfezionamentoRequisiti.Value))
                                requisitoEta = "56 anni";
                            break;
                        case 2027:
                        case 2028:
                            if (sessoTitolare == 'M' && Utility.DataStrettamenteSuccessivaA(dataNascitaTitolare.Value.AddYears(61), datiPensioneUI.DataPerfezionamentoRequisiti.Value))
                                requisitoEta = "61 anni";
                            else if (sessoTitolare == 'F' && Utility.DataStrettamenteSuccessivaA(dataNascitaTitolare.Value.AddYears(56), datiPensioneUI.DataPerfezionamentoRequisiti.Value))
                                requisitoEta = "56 anni";
                            break;
                        case 2029:
                        case 2030:
                            if (sessoTitolare == 'M' && Utility.DataStrettamenteSuccessivaA(dataNascitaTitolare.Value.AddYears(61).AddMonths(1), datiPensioneUI.DataPerfezionamentoRequisiti.Value))
                                requisitoEta = "61 anni e 1 mese";
                            else if (sessoTitolare == 'F' && Utility.DataStrettamenteSuccessivaA(dataNascitaTitolare.Value.AddYears(56).AddMonths(1), datiPensioneUI.DataPerfezionamentoRequisiti.Value))
                                requisitoEta = "56 anni e 1 mese";
                            break;
                        default:
                            break;
                    }
                }

                if (!string.IsNullOrEmpty(requisitoEta) && !GestioneBypassControllo.CheckAndLockBypassControlloByNomeBypass(datiPensioneUI, GestioneBypassControllo.NomeBypass.Titolare_Anagrafica_AGO.BYPASS_FINESTRA_12MESI))
                {
                    messaggioVideo = string.Format("Alla data di perfezionamento dei requisiti({0:dd/MM/yyyy}) il titolare non ha raggiunto i termini di età previsti ({1})", datiPensioneUI.DataPerfezionamentoRequisiti.Value, requisitoEta);
                    return false;
                }
            }

            return true;
        }

        public static bool ALL_VerificaResidenzeEstereWithAnagrafica(GestioneAnagrafica.DatiAnagrafici anagrafica, List<GestioneAnagrafica.DatiResidenzaEstero> elencoResidenzeEstere, out string messaggioVideo)
        {
            messaggioVideo = string.Empty;
            if (elencoResidenzeEstere == null || elencoResidenzeEstere.Count == 0)
                return true;
            if (anagrafica.CodiceComuneResidenza.ToUpperInvariant().Trim().StartsWith("Z"))  // estero
            {
                if (elencoResidenzeEstere.Last().CodCatastaleStatoEE.ToUpperInvariant().Trim() != anagrafica.CodiceComuneResidenza.ToUpperInvariant().Trim())
                {
                    messaggioVideo = "Lo Stato Estero di residenza corrispondente alla decorrenza più recente non coincide con quello presente nell'anagrafica.";
                    return false;
                }
            }
            else // italia
            {
                if (elencoResidenzeEstere.Last().CodCatastaleStatoEE.ToUpperInvariant().Trim() != "Z000")
                {
                    messaggioVideo = "Lo Stato Estero di residenza corrispondente alla decorrenza più recente non coincide con quello presente nell'anagrafica.";
                    return false;
                }
            }
            return true;
        }

        public static bool ALL_VerificaRequisitoEtaQuota102(GestionePensione.DatiPensione datiPensione, DateTime? dataPerfezionamentoRequisiti, DateTime? dataNascitaTitolare, out string messaggioVideo)
        {
            messaggioVideo = string.Empty;

            Utility.TipoFondo? tipoFondo = Utility.GetTipoFondoByCategoria(datiPensione.IndConvInt, datiPensione.Gestione, datiPensione.SiglaCategoria);
            Utility.TipoAppartenenza? tipoAppartenenza = Utility.GetTipoAppartenenza(datiPensione.IndConvInt, datiPensione.Gestione);
            Utility.DifferenzaDateTime requisitoEta = new Utility.DifferenzaDateTime(64, 0, 0);
            if (Utility.IsDomandaQuota102(datiPensione))
            {
                if (!(tipoAppartenenza.Value == Utility.TipoAppartenenza.FS && (tipoFondo == Utility.TipoFondo.FS || tipoFondo == Utility.TipoFondo.PT) && (Utility.IsRicostituzione_MotiviDocumentali(datiPensione) || Utility.IsRicEsenzioneFiscaleVittimeDelDovere(datiPensione) || Utility.IsRicostituzione_Reddituale(datiPensione) || Utility.IsRicostituzione_TrattamentoDiFamiglia(datiPensione))))
                {
                    Utility.DifferenzaDateTime diff = Utility.DifferenzaBetweenDate(dataPerfezionamentoRequisiti, dataNascitaTitolare, Utility.GetTipoAppartenenza(datiPensione.IndConvInt, datiPensione.Gestione));
                    if (diff < requisitoEta)
                    {
                        messaggioVideo = string.Format("Il titolare della domanda non ha compiuto {0} alla data di perfezionamento del requisito ({1:dd/MM/yyyy})", requisitoEta, dataPerfezionamentoRequisiti);
                        return false;
                    }
                }
            }

            return true;
        }


        public static bool ALL_VerificaDecorrenzaPensioneQuota102(GestionePensione.DatiPensione datiPensione, DateTime? decorrenzaOriginaria, DateTime? dataPerfezionamentoRequisiti,
            bool? lavoratorePubblico, out string messaggioVideo)
        {
            messaggioVideo = string.Empty;

            if (Utility.IsDomandaQuota102(datiPensione))
            {
                if (decorrenzaOriginaria.HasValue)
                {
                    Utility.TipoFondo? tipoFondo = Utility.GetTipoFondoByCategoria(datiPensione.IndConvInt, datiPensione.Gestione, datiPensione.SiglaCategoria);
                    DateTime dataLimite = lavoratorePubblico.GetValueOrDefault() ? ((tipoFondo != Utility.TipoFondo.FS && tipoFondo != Utility.TipoFondo.PT && !Utility.IsDomandaINPDAP(datiPensione.Gestione)) ? new DateTime(2022, 8, 1) : new DateTime(2022, 7, 2)) : ((tipoFondo != Utility.TipoFondo.FS && tipoFondo != Utility.TipoFondo.PT && !Utility.IsDomandaINPDAP(datiPensione.Gestione)) ? new DateTime(2022, 5, 1) : new DateTime(2022, 4, 2));
                    if (!Utility.DataSuccessivaA(decorrenzaOriginaria.Value, dataLimite) && !Utility.IsDomandaCTPS(datiPensione.SiglaCategoria))
                    {
                        messaggioVideo = string.Format("La Decorrenza Pensione dovrà essere successiva o uguale al {0:dd/MM/yyyy}", dataLimite);
                        return false;
                    }

                    if (!dataPerfezionamentoRequisiti.HasValue)
                    {
                        Utility.TipoAppartenenza? tipoAppartenenza = Utility.GetTipoAppartenenza(datiPensione.IndConvInt, datiPensione.Gestione);
                        if (!(tipoAppartenenza.Value == Utility.TipoAppartenenza.FS && (tipoFondo == Utility.TipoFondo.FS || tipoFondo == Utility.TipoFondo.PT) && (Utility.IsRicostituzione_MotiviDocumentali(datiPensione) || Utility.IsRicEsenzioneFiscaleVittimeDelDovere(datiPensione) || Utility.IsRicostituzione_Reddituale(datiPensione) || Utility.IsRicostituzione_TrattamentoDiFamiglia(datiPensione))))
                        {
                            messaggioVideo = "Data Perfezionamento Requisiti obbligatoria.";
                            return false;
                        }
                    }
                    else
                    {
                        // Per cumulo comparto scuola non devono essere applicati i controlli sulla finestra di uscita
                        if (Utility.IsDomandaCumulo(datiPensione.SiglaCategoria) && lavoratorePubblico.GetValueOrDefault() &&
                            (!datiPensione.IsCumuloAutomatica.GetValueOrDefault() || (!string.IsNullOrEmpty(datiPensione.NaturaPensione) && datiPensione.NaturaPensione.Substring(2, 1) == "S")))
                            return true;

                        if (!(Utility.IsDomandaUnicarpe(datiPensione, true) == Utility.TipoUnicarpe.Automatica || datiPensione.IsPLUnicarpe.GetValueOrDefault()))
                        {
                            DateTime dataLimiteInferirorePerfezionamentoRequisiti = new DateTime(2022, 1, 1);
                            DateTime dataLimiteSuperiorePerfezionamentoRequisiti = new DateTime(2022, 12, 31);
                            if (!Utility.DataSuccessivaA(dataPerfezionamentoRequisiti.Value, dataLimiteInferirorePerfezionamentoRequisiti) || Utility.DataStrettamenteSuccessivaA(dataPerfezionamentoRequisiti.Value, dataLimiteSuperiorePerfezionamentoRequisiti))
                            {
                                messaggioVideo = string.Format("La Data Perfezionamento Requisiti dovrà essere successiva o uguale al {0:dd/MM/yyyy} e antecedente o uguale al {1:dd/MM/yyyy} ", dataLimiteInferirorePerfezionamentoRequisiti, dataLimiteSuperiorePerfezionamentoRequisiti);
                                return false;
                            }

                            if (tipoFondo != Utility.TipoFondo.FS && tipoFondo != Utility.TipoFondo.PT && !Utility.IsDomandaINPDAP(datiPensione.Gestione))
                            {
                                int mesiLimite = lavoratorePubblico.GetValueOrDefault() ? 7 : 4;
                                if (!Utility.DataSuccessivaA(decorrenzaOriginaria.Value, Utility.FirstDayOfMonth(dataPerfezionamentoRequisiti.Value.AddMonths(mesiLimite))))
                                {
                                    messaggioVideo = string.Format("La decorrenza pensione deve essere di almeno {0} mesi successiva alla data di perfezionamento dei requisiti.", mesiLimite - 1);
                                    return false;
                                }
                            }
                            else
                            {
                                int mesiLimite = lavoratorePubblico.GetValueOrDefault() ? 6 : 3;
                                DateTime? dataMinima = null;
                                try
                                {
                                    dataMinima = dataPerfezionamentoRequisiti.Value.AddMonths(mesiLimite).AddDays(1);
                                }
                                catch (Exception)
                                {
                                    dataMinima = Utility.FirstDayOfMonth(dataPerfezionamentoRequisiti.Value.AddMonths(mesiLimite + 1));
                                }
                                if (!Utility.DataSuccessivaA(decorrenzaOriginaria.Value, dataMinima.Value) && !Utility.IsDomandaCTPS(datiPensione.SiglaCategoria))
                                {
                                    messaggioVideo = string.Format("La Decorrenza Pensione dovrà essere successiva o uguale al {0:dd/MM/yyyy}", dataMinima);
                                    return false;
                                }
                            }
                        }
                    }
                }
            }

            return true;
        }

        public static bool ALL_VerificaRequisitoEtaAnticipataFlessibile(GestionePensione.DatiPensione datiPensione, DateTime? dataPerfezionamentoRequisiti, DateTime? dataNascitaTitolare, out string messaggioVideo)
        {
            messaggioVideo = string.Empty;

            Utility.DifferenzaDateTime requisitoEta = new Utility.DifferenzaDateTime(62, 0, 0);
            if (Utility.IsDomandaAnticipataFlessibile(datiPensione) || Utility.IsDomandaAnticipataFlessibileOpzioneContributivo(datiPensione))
            {
                Utility.DifferenzaDateTime diff = Utility.DifferenzaBetweenDate(dataPerfezionamentoRequisiti, dataNascitaTitolare, Utility.GetTipoAppartenenza(datiPensione.IndConvInt, datiPensione.Gestione));
                if (diff < requisitoEta)
                {
                    messaggioVideo = string.Format("Il titolare della domanda non ha compiuto {0} alla data di perfezionamento del requisito ({1:dd/MM/yyyy})", requisitoEta, dataPerfezionamentoRequisiti);
                    return false;
                }
            }

            return true;
        }

