        public static bool ALL_VerificaDecorrenzaPensioneAnticipataFlessibile(GestionePensione.DatiPensione datiPensione, DateTime? decorrenzaOriginaria, DateTime? dataPerfezionamentoRequisiti,
           bool? lavoratorePubblico, out string messaggioVideo)
        {
            messaggioVideo = string.Empty;
            DateTime dataLimitePerfezionamentoRequisiti = new DateTime(2023, 12, 31);
            Utility.TipoFondo? tipoFondo = Utility.GetTipoFondoByCategoria(datiPensione.IndConvInt, datiPensione.Gestione, datiPensione.SiglaCategoria);
            Utility.TipoAppartenenza? tipoAppartenenza = Utility.GetTipoAppartenenza(datiPensione.IndConvInt, datiPensione.Gestione);

            if (Utility.IsDomandaAnticipataFlessibile(datiPensione) || Utility.IsDomandaAnticipataFlessibileOpzioneContributivo(datiPensione))
            {
                if (!dataPerfezionamentoRequisiti.HasValue)
                {
                    messaggioVideo = "Data Perfezionamento Requisiti obbligatoria.";
                    return false;
                }
                else
                {
                    if (Utility.DataStrettamenteSuccessivaA(dataPerfezionamentoRequisiti.Value, dataLimitePerfezionamentoRequisiti))
                    {
                        messaggioVideo = string.Format("La Data Perfezionamento Requisiti dovrà essere antecedente o uguale al {0:dd/MM/yyyy} ", dataLimitePerfezionamentoRequisiti);
                        return false;
                    }

                    //ENG - Per Cumulo Comparto Scuola non devono essere eseguiti i controlli seguenti
                    if (Utility.IsDomandaCumulo(datiPensione.SiglaCategoria) && lavoratorePubblico.GetValueOrDefault() &&
                        (!datiPensione.IsCumuloAutomatica.GetValueOrDefault() || (!string.IsNullOrEmpty(datiPensione.NaturaPensione) && datiPensione.NaturaPensione.Substring(2, 1) == "S")))
                        return true;

                    //ENG - I controlli valgono solo per le domande manuali
                    if (!Utility.IsDomandaAutomatica(datiPensione))
                    {
                        //ENG - INPDAP Comparto Scuola (Ente 32) / AFAM (Ente 33)
                        if (tipoAppartenenza == Utility.TipoAppartenenza.FS && Utility.IsDomandaINPDAP(datiPensione.Gestione) && datiPensione.Fondo == "002" && (datiPensione.Ente == "32" || datiPensione.Ente == "33"))
                        {
                            if (datiPensione.Ente == "32" && (decorrenzaOriginaria.GetValueOrDefault().Month != 9 || decorrenzaOriginaria.GetValueOrDefault().Day != 1))
                            {
                                messaggioVideo = string.Format("La Decorrenza Originaria deve essere pari al 1 Settembre");
                                return false;
                            }

                            if (datiPensione.Ente == "33" && (decorrenzaOriginaria.GetValueOrDefault().Month != 11 || decorrenzaOriginaria.GetValueOrDefault().Day != 1))
                            {
                                messaggioVideo = string.Format("La Decorrenza Originaria deve essere pari al 1 Novembre");
                                return false;
                            }

                            if (dataPerfezionamentoRequisiti.GetValueOrDefault().Year != decorrenzaOriginaria.GetValueOrDefault().Year)
                            {
                                messaggioVideo = string.Format("Il Perfezionamento Requisiti e la Decorrenza Originaria devono essere nello stesso anno");
                                return false;
                            }
                        }
                        else
                        {
                            //Per le INPDAP e le 024, la decorrenza originaria è inframensile
                            DateTime perfezionamentoRequisiti = (tipoFondo == Utility.TipoFondo.FS || tipoFondo == Utility.TipoFondo.PT || Utility.IsDomandaINPDAP(datiPensione.Gestione)) ? dataPerfezionamentoRequisiti.Value.AddDays(1) : Utility.FirstDayOfMonth(dataPerfezionamentoRequisiti.Value).AddMonths(1);

                            if (lavoratorePubblico.GetValueOrDefault())
                            {
                                int mesiLimiteLavoratorePubblico = 6;
                                DateTime decorrenzaMinima = new DateTime(2023, 08, 01);

                                //requisiti entro il 31/12/2022
                                if (!Utility.DataStrettamenteSuccessivaA(dataPerfezionamentoRequisiti.Value, new DateTime(2022, 12, 31)))
                                {
                                    //decorrenza maggiore/uguale al 01/08/2023                            
                                    if (!Utility.DataSuccessivaA(decorrenzaOriginaria.Value, decorrenzaMinima))
                                    {
                                        messaggioVideo = string.Format("La Decorrenza Originaria deve essere successiva o uguale al  {0:dd/MM/yyyy}", decorrenzaMinima);
                                        return false;
                                    }
                                }
                                else // requisiti dal 01/01/2023 con finestra di 6 mesi e decorrenza successiva/uguale al 01/08/2023
                                {
                                    if (!Utility.DataSuccessivaA(decorrenzaOriginaria.Value, decorrenzaMinima))
                                    {
                                        messaggioVideo = string.Format("La Decorrenza Originaria deve essere successiva o uguale al  {0:dd/MM/yyyy}", decorrenzaMinima);
                                        return false;
                                    }

                                    if (!Utility.DataSuccessivaA(decorrenzaOriginaria.Value, perfezionamentoRequisiti.AddMonths(mesiLimiteLavoratorePubblico)) && !(Utility.IsDomandaINPDAP(datiPensione.Gestione) && Utility.IsRicostituzione(datiPensione.Gruppo)) && !Utility.IsDomandaCTPS(datiPensione.SiglaCategoria))
                                    {
                                        messaggioVideo = string.Format("La decorrenza pensione deve essere di almeno {0} mesi successiva alla data di perfezionamento dei requisiti.", mesiLimiteLavoratorePubblico);
                                        return false;
                                    }
                                }
                            }
                            else
                            {
                                int mesiLimiteLavoratorePrivato = 3;

                                //requisiti entro il 31/12/2022
                                if (!Utility.DataStrettamenteSuccessivaA(dataPerfezionamentoRequisiti.Value, new DateTime(2022, 12, 31)))
                                {
                                    DateTime decorrenzaMinima = new DateTime(2023, 04, 01);
                                    if (!Utility.DataSuccessivaA(decorrenzaOriginaria.Value, decorrenzaMinima))
                                    {
                                        messaggioVideo = string.Format("La Decorrenza Originaria deve essere successiva o uguale al  {0:dd/MM/yyyy}", decorrenzaMinima);
                                        return false;
                                    }
                                }
                                else  //requisiti successivi al 31/12/2022                  
                                {

                                    if (Utility.IsDomandaINPDAP(datiPensione.Gestione) || tipoFondo == Utility.TipoFondo.FS || tipoFondo == Utility.TipoFondo.PT)
                                    {
                                        DateTime decorrenzaMinima = new DateTime(2023, 04, 02);
                                        if (!Utility.DataSuccessivaA(decorrenzaOriginaria.Value, decorrenzaMinima))
                                        {
                                            messaggioVideo = string.Format("La Decorrenza Originaria deve essere successiva o uguale al  {0:dd/MM/yyyy}", decorrenzaMinima);
                                            return false;
                                        }
                                    }
                                    else
                                    {
                                        DateTime decorrenzaMinima = new DateTime(2023, 05, 01);
                                        if (!Utility.DataSuccessivaA(decorrenzaOriginaria.Value, decorrenzaMinima))
                                        {
                                            messaggioVideo = string.Format("La Decorrenza Originaria deve essere successiva o uguale al  {0:dd/MM/yyyy}", decorrenzaMinima);
                                            return false;
                                        }
                                    }
                                }

                                //per i lavoratori privati la finestra deve essere di 3 mesi
                                if (!Utility.DataSuccessivaA(decorrenzaOriginaria.Value, perfezionamentoRequisiti.AddMonths(mesiLimiteLavoratorePrivato)) && !Utility.IsDomandaCTPS(datiPensione.SiglaCategoria))
                                {
                                    messaggioVideo = string.Format("La decorrenza pensione deve essere di almeno {0} mesi successiva alla data di perfezionamento dei requisiti.", mesiLimiteLavoratorePrivato);
                                    return false;
                                }
                            }
                        }
                    }
                }
            }

            return true;
        }

        //ENG - Memo 123/2024
        public static bool ALL_VerificaDecorrenzaPensioneAnticipataFlessibileLeggeDiBilancio2024(GestionePensione.DatiPensione datiPensione, DateTime? decorrenzaOriginaria, DateTime? dataPerfezionamentoRequisiti,
           bool? lavoratorePubblico, out string messaggioVideo)
        {
            messaggioVideo = string.Empty;
            //ENG - Memo 123/2024 aggiornato al 27/03/2025

            if (!Utility.IsRicostituzione(datiPensione.Gruppo) && !Utility.IsRiaperturaDomanda(datiPensione.Id) &&
                Utility.IsDomandaAnticipataFlessibileLeggeBilancio2024(datiPensione) || Utility.IsDomandaAnticipataFlessibileOpzioneContributivoLeggeBilancio2024(datiPensione))
            {
                if (!dataPerfezionamentoRequisiti.HasValue)
                {
                    messaggioVideo = "Data Perfezionamento Requisiti obbligatoria.";
                    return false;
                }
                else
                {
                    int anno = dataPerfezionamentoRequisiti.Value.Year;
                    int annoLimitePerfezionamentoRequisiti = 0;
                    GestioneControlliDinamici.ControlloDinamico controlloDinamicoAnnoControlloMemo123_2024 = null;
                    GestioneControlliDinamici.GetControlloDinamicoByNomeControllo("AnnoControlloMemo123_2024", out controlloDinamicoAnnoControlloMemo123_2024);
                    Utility.TipoFondo? tipoFondo = Utility.GetTipoFondoByCategoria(datiPensione.IndConvInt, datiPensione.Gestione, datiPensione.SiglaCategoria);
                    Utility.TipoAppartenenza? tipoAppartenenza = Utility.GetTipoAppartenenza(datiPensione.IndConvInt, datiPensione.Gestione);

                    if (controlloDinamicoAnnoControlloMemo123_2024 != null && !String.IsNullOrEmpty(controlloDinamicoAnnoControlloMemo123_2024.ValoreControllo) && !String.IsNullOrEmpty(controlloDinamicoAnnoControlloMemo123_2024.ValoreControllo.Trim()))
                        annoLimitePerfezionamentoRequisiti = Convert.ToInt32(controlloDinamicoAnnoControlloMemo123_2024.ValoreControllo.Trim());

                    DateTime dataLimitePerfezionamentoRequisiti = new DateTime(annoLimitePerfezionamentoRequisiti, 12, 31);

                    if (!Utility.DataSuccessivaA(dataPerfezionamentoRequisiti.Value, new DateTime(2024, 01, 01)))
                    {
                        if (Utility.IsDomandaAnticipataFlessibileLeggeBilancio2024(datiPensione))
