                                if (!Utility.DataSuccessivaA(decorrenzaOriginaria.Value, perfezionamentoRequisiti.AddMonths(mesiLimiteLavoratorePubblico)) && !Utility.IsDomandaCTPS(datiPensione.SiglaCategoria))
