        //ENG - Memo 28
        public static bool ALL_VerificaDecorrenzaTipo0017_0045Pav(GestionePensione.DatiPensione datiPensione, DateTime? decorrenzaOriginaria, DateTime? dataPerfezionamentoRequisiti, out string messaggioVideo)
        {
            messaggioVideo = string.Empty;
            Utility.TipoFondo? tipoFondo = Utility.GetTipoFondoByCategoria(datiPensione.IndConvInt, datiPensione.Gestione, datiPensione.SiglaCategoria);
            Utility.TipoAppartenenza? tipoAppartenenza = Utility.GetTipoAppartenenza(datiPensione.IndConvInt, datiPensione.Gestione);

            if ((datiPensione.Gruppo == "0001" && datiPensione.Prodotto == "0001" && datiPensione.Tipo == "0017") || (Utility.IsDomandaAnzianitaInComputo(datiPensione) && datiPensione.CodiceTipoRichiesta == "AV"))
            {
                if (dataPerfezionamentoRequisiti.HasValue && Utility.DataStrettamenteSuccessivaA(dataPerfezionamentoRequisiti.Value, new DateTime(2023, 12, 31)))
                {
                    //Per le INPDAP e le 024, la decorrenza originaria è inframensile
                    DateTime perfezionamentoRequisiti = (tipoFondo == Utility.TipoFondo.FS || tipoFondo == Utility.TipoFondo.PT || Utility.IsDomandaINPDAP(datiPensione.Gestione)) ? dataPerfezionamentoRequisiti.Value.AddMonths(3).AddDays(1) : Utility.FirstDayOfMonth(dataPerfezionamentoRequisiti.Value).AddMonths(1).AddMonths(3);

                    if (!Utility.DataSuccessivaA(decorrenzaOriginaria.Value, perfezionamentoRequisiti) && !Utility.IsDomandaCTPS(datiPensione.SiglaCategoria))
                    {
                        messaggioVideo = string.Format("La decorrenza pensione deve essere di almeno {0} mesi successiva alla data di perfezionamento dei requisiti.", 3);
                        return false;
                    }
                }
            }

            return true;
        }

        private static Enum GetEnumBypassRequisitoEta(Utility.TipoAppartenenza? tipoAppartenenza)
        {
            Enum ctrl = null;
            switch (tipoAppartenenza.Value)
            {
                case Utility.TipoAppartenenza.AGO:
                    ctrl = GestioneCtrlControlliApplicativi.EnumNomeControllo.AGO.BYPASS_REQUISITI_ETA;
                    break;
                case Utility.TipoAppartenenza.FS:
                    ctrl = GestioneCtrlControlliApplicativi.EnumNomeControllo.FS.BYPASS_REQUISITI_ETA;
                    break;
                case Utility.TipoAppartenenza.CI:
                    ctrl = GestioneCtrlControlliApplicativi.EnumNomeControllo.CI.BYPASS_REQUISITI_ETA;
                    break;
            }
            return ctrl;
        }

