        public static bool ALL_VerificaCodiceArretratiWithEliminazione(byte? codiceEliminazione, byte? codiceArretrati, GestionePensione.DatiPensione datiPensione, out string messaggioVideo, bool isRiaperturaDomanda = false)
        {
            messaggioVideo = string.Empty;

            if (Utility.IsDomandaVOESO(datiPensione.SiglaCategoria) || Utility.IsDomandaVESO33(datiPensione.SiglaCategoria) ||
                Utility.IsDomandaVESO92(datiPensione.SiglaCategoria) || Utility.IsDomandaVOCRED_CRED27(datiPensione.SiglaCategoria) ||
                Utility.IsDomandaVOCOOP_COOP28(datiPensione.SiglaCategoria) || Utility.IsDomandaVESO29(datiPensione.SiglaCategoria) ||
                Utility.IsDomandaESOTEL(datiPensione.SiglaCategoria) || Utility.IsDomandaESOAMB(datiPensione.SiglaCategoria) ||
                Utility.IsDomandaESPA(datiPensione.SiglaCategoria))
            {
                // quadro eliminazione non valorizzato
                if (codiceEliminazione.GetValueOrDefault() == 0)
                {
                    //accantonamento arretrati valorizzato con SI = 8
                    //non deve scattare per TRF/RIC VOCOOP, VOCRED, VESO92 
                    if (codiceArretrati.GetValueOrDefault() == 8
                        && !(Utility.IsRicostituzioneOrRiapertura(datiPensione, isRiaperturaDomanda) && (Utility.IsDomandaVOCOOP(datiPensione.SiglaCategoria) ||
                        Utility.IsDomandaVOCRED(datiPensione.SiglaCategoria) || Utility.IsDomandaVESO92(datiPensione.SiglaCategoria) ||
                        Utility.IsDomandaESPA(datiPensione.SiglaCategoria) || Utility.IsDomandaVESO29(datiPensione.SiglaCategoria) || Utility.IsDomandaVESO33(datiPensione.SiglaCategoria) ||
                        Utility.IsDomandaVOESO(datiPensione.SiglaCategoria) || Utility.IsDomandaESOTEL(datiPensione.SiglaCategoria))))
                    {
                        messaggioVideo = "Per le pensioni non eliminate non è possibile selezionare il codice accantonamento arretrati uguale a SI";
                        return false;
                    }
                }
            }

            if (codiceEliminazione.GetValueOrDefault() != 0)
            {
                //saltato per tutte le isopensioni TFR/RIC a meno delle 127, 128, 196, 197 
                if (codiceArretrati.GetValueOrDefault() != 8
                    && !(Utility.IsRicostituzioneOrRiapertura(datiPensione, isRiaperturaDomanda)
                        && (Utility.IsDomandaVOCOOP(datiPensione.SiglaCategoria) || Utility.IsDomandaVOCRED(datiPensione.SiglaCategoria) || Utility.IsDomandaVESO92(datiPensione.SiglaCategoria)
                        || Utility.IsDomandaVESO29(datiPensione.SiglaCategoria) || Utility.IsDomandaVESO33(datiPensione.SiglaCategoria) || Utility.IsDomandaVOESO(datiPensione.SiglaCategoria) ||
                        Utility.IsDomandaESPA(datiPensione.SiglaCategoria) || Utility.IsDomandaESOTEL(datiPensione.SiglaCategoria))))
                {
                    messaggioVideo = "Per le pensioni eliminate il codice accantonamento arretrati deve essere pari a SI.";
                    return false;
                }
            }

            return true;
        }

        public static bool ALL_VerificaBeneficiPerOpzioneTipoContributivo(GestionePensione.DatiPensione datiPensione, bool? checkBenefici, out string messaggioVideo)
        {
            messaggioVideo = null;

            if (Utility.IsGestioneLavoratriciMadri(datiPensione))
            {
                if (datiPensione.SceltaLavMadri.GetValueOrDefault() > 0 && !checkBenefici.GetValueOrDefault())
                {
                    messaggioVideo = "La check dei Benefici deve essere spuntata.";
                    return false;
                }
            }

            return true;
        }

        public static bool ALL_VerificaAnnoRichiestaBonus154(GestionePensione.DatiPensione datiPensione, string annoRichiestaBonus, out string messaggioVideo)
        {
            messaggioVideo = null;

            if (string.IsNullOrEmpty(annoRichiestaBonus))
            {
                messaggioVideo = "Anno Richiesta Bonus è obbligatorio.";
                return false;
            }

            if (int.Parse(annoRichiestaBonus) < datiPensione.DecorrenzaOriginaria.GetValueOrDefault().Year)
            {
                messaggioVideo = "Anno Richiesta Bonus deve essere uguale o successivo all'anno della decorrenza.";
                return false;
            }

            return true;
        }
