        #region Dati Assicurativi
        public static bool ALL_VerificaFineAssicurazioneForReversibilita(Utility.TipoDomanda tipoDomanda, DateTime? dataFineAssicurazione, DateTime? decorrenzaOriginaria, DateTime? decorrenzaPensioneDiretta, Utility.TipoAppartenenza? tipoAppartenenza, string siglaCategoria, out string messaggioVideo)
        {
            messaggioVideo = string.Empty;

            if (tipoDomanda == Utility.TipoDomanda.Superstiti)
            {
                if (dataFineAssicurazione.HasValue)
                {
                    if (decorrenzaOriginaria.HasValue)
                    {
                        if (Utility.DataStrettamenteSuccessivaA(dataFineAssicurazione.Value, decorrenzaOriginaria.Value))
                        {
                            messaggioVideo = "Data Ultimo Contributo posteriore alla Decorrenza Pensione.";
                            return false;
                        }
                    }

                    if (decorrenzaPensioneDiretta.HasValue)
                    {
                        Utility.CategoriaFondoPI? categoriaFondoPI = Utility.GetCategoriaFondoPI(tipoAppartenenza, siglaCategoria);
                        if (categoriaFondoPI != null && categoriaFondoPI != Utility.CategoriaFondoPI.V && categoriaFondoPI != Utility.CategoriaFondoPI.U && Utility.DataSuccessivaA(new DateTime(1999, 09, 30), decorrenzaPensioneDiretta.Value))
                            return true;

                        if (Utility.DataStrettamenteSuccessivaA(dataFineAssicurazione.Value, decorrenzaPensioneDiretta.Value))
                        {
                            messaggioVideo = "Data Ultimo Contributo posteriore a Decorrenza Pensione Diretta.";
                            return false;
                        }
                    }
                }
            }
            return true;
        }

        public static bool ALL_ControlsInizioAssicurazioneSperimentaleDonna(GestionePensione.DatiPensione datiPensione, DateTime? inizioAssicurazione, out string messaggioVideo)
        {
            messaggioVideo = string.Empty;
            DateTime dataCompare = new DateTime(1996, 01, 01);

            if (datiPensione == null)
                return false;

            Utility.TipoAppartenenza? tipoAppartenenza = Utility.GetTipoAppartenenza(datiPensione.IndConvInt, datiPensione.Gestione);

            if (tipoAppartenenza.HasValue && tipoAppartenenza.Value != Utility.TipoAppartenenza.CI)
            {
                if (inizioAssicurazione.HasValue && Utility.IsDomandaSperimentaleDonna(datiPensione))
                {
                    if (Utility.DataSuccessivaA(inizioAssicurazione.Value, dataCompare))
                    {
                        messaggioVideo = "La data d'inizio assicurazione deve essere antecedente al " + string.Format("{0:dd/MM/yyyy}", dataCompare);
                        return false;
                    }
                }
            }

            return true;
        }
