        #region Istruttoria
        public static bool ALL_VerificaRiduzioneRetributiva(GestionePensione.DatiPensione datiPensione, GestionePensione.DatiPensione datiPensioneBL, bool isRiaperturaDomanda, bool riduzioneRetributiva, decimal? riduzioneRetributivaPercentuale, out string messaggioVideo)
        {
            messaggioVideo = string.Empty;

            DateTime? decorrenzaOriginaria = datiPensioneBL.DecorrenzaOriginaria;
            DateTime? dataPerfezionamentoRequisiti = datiPensioneBL.DataPerfezionamentoRequisiti;

            if (datiPensione != null && Utility.IsDomandaVOCRED_CRED27(datiPensione.SiglaCategoria) || (Utility.IsAssegnoStraordinarioFerrovieDelloStato(datiPensione) && datiPensione.CodiceTipoRichiesta == "74"))
                return true;

            if (datiPensione != null && Utility.GetTipoAppartenenza(datiPensione.IndConvInt, datiPensione.Gestione) == Utility.TipoAppartenenza.CI && !Utility.IsRicostituzioneOrRiapertura(datiPensione, isRiaperturaDomanda))
                return true;

            if (decorrenzaOriginaria.HasValue && Utility.DataSuccessivaA(decorrenzaOriginaria.Value, new DateTime(2015, 1, 1)) &&
                dataPerfezionamentoRequisiti.HasValue && !Utility.DataStrettamenteSuccessivaA(dataPerfezionamentoRequisiti.Value, new DateTime(2017, 12, 31)))
            {
                if (riduzioneRetributiva || riduzioneRetributivaPercentuale.HasValue)
                {
                    messaggioVideo = "La Riduzione Retributiva non può essere acquisita.";
                    return false;
                }
            }

            return true;
        }
