        #region Cross
        public static bool ALL_VerificaNaturaPensioneEAssicurazione_PensioneOpzioneContributivo(GestionePensione.DatiPensione datiPensione, string naturaPensione, DateTime? dataInizioAssicurazione,
            out string messaggioVideo)
        {
            messaggioVideo = null;
            Utility.TipoAppartenenza? tipoAppartenenza = Utility.GetTipoAppartenenza(datiPensione.IndConvInt, datiPensione.Gestione);

            if (Utility.IsDomandaTipoContributivo(datiPensione, null, true) || Utility.IsDomandaAnticipataFlessibileOpzioneContributivo(datiPensione) || Utility.IsDomandaAnticipataFlessibileLeggeBilancio2024(datiPensione) || Utility.IsDomandaAnticipataFlessibileOpzioneContributivoLeggeBilancio2024(datiPensione))
            {
                if (!Utility.IsDomandaAnticipataFlessibileLeggeBilancio2024(datiPensione) && (string.IsNullOrEmpty(naturaPensione) || naturaPensione.Substring(1, 1) != "J"))
                {
                    messaggioVideo = "Il secondo byte del Codice Natura deve essere pari a J";
                    return false;
                }

                if ((!(tipoAppartenenza.HasValue && tipoAppartenenza == Utility.TipoAppartenenza.CI &&
                    (Utility.IsDomandaAnticipataFlessibile(datiPensione) || Utility.IsDomandaAnticipataFlessibileLeggeBilancio2024(datiPensione) || Utility.IsDomandaAnticipataFlessibileOpzioneContributivo(datiPensione) || Utility.IsDomandaAnticipataFlessibileOpzioneContributivoLeggeBilancio2024(datiPensione) || Utility.IsDomandaTipoContributivo(datiPensione, true, null) || Utility.IsDomandaTipoContributivo(datiPensione, false, true))) &&
                      dataInizioAssicurazione.HasValue && Utility.DataSuccessivaA(dataInizioAssicurazione.Value, new DateTime(1996, 1, 1))))
                {
                    messaggioVideo = "La data di Inizio Assicurazione non può essere successivo al 01/01/1996.";
                    return false;
                }
            }

            return true;
        }
