        #region Supplementi
        /// <summary>
        /// Verifica che Il supplemento non abbia una data antecedente alla decorrenza della pensione (Supplementi.DecorrenzaSupplemento >= Pensione.DecorrenzaPensione)
        /// </summary>
        /// <param name="listDatiSupplementi">Lista dati supplementi</param>
        /// <param name="datiPensione">Dati pensione</param>
        /// <returns>true se la data DecorrenzaSupplemento è >= alla data DecorrenzaPensione, false altrimenti</returns>
        public static bool FS_VerificaDecorrenzaSupplementoDecorrenzaPensione(List<Entity.DatiSupplementi> listDatiSupplementi, DateTime? decorrenzaPensioneOrDiretta)
        {
            if (listDatiSupplementi == null || listDatiSupplementi.Count == 0)
                return true;

            int index = listDatiSupplementi.FindIndex(delegate
                (Entity.DatiSupplementi code)
            {
                return (DateTime.Compare(code.DecorrenzaSupplemento.Value, Utility.FirstDayOfMonth(decorrenzaPensioneOrDiretta.Value)) < 0);
            });

            if (index >= 0)
                return false;

            return true;
        }

        /// <summary>
        /// Verifica che Il supplemento abbia data pari alla decorrenza della pensione del titolare superstite.
        /// </summary>
        /// <param name="dSuppRecordEnpals">dati supplemento</param>
        /// <param name="datiPensione">Dati pensione</param>
        /// <returns>true se la data DecorrenzaSupplemento è == alla data DecorrenzaPensione, false altrimenti</returns>
        public static bool AGO_VerificaDecorrenzaSupplementoDecorrenzaPensioneENPALS(BLCommon.Entity.DatiSuppRecordENPALS dSuppRecordEnpals, GestionePensione.DatiPensione datiPensione)
        {
            if (dSuppRecordEnpals != null)
                if ((Utility.IsDomandaReversibilita(datiPensione) && (!dSuppRecordEnpals.IsFromGP) && (dSuppRecordEnpals.Decorrenza != datiPensione.DecorrenzaOriginaria)))
                    return false;

            return true;
        }
