        #region Deleghe/Tutele
        public static bool ALL_VerificaDelegheTuteleByIdPensione(GestionePensione.DatiPensione datiPensione, string CodFiscDelegato, string CodFiscTutore, char? codiceTutore, DateTime? cessValAmmSost,
            string codFiscTitolare, bool isRiapertura, out string messaggioVideo)
        {
            messaggioVideo = string.Empty;

            if (string.IsNullOrEmpty(CodFiscDelegato))
            {
                GestioneAnagrafica.DatiAnagrafici datiDelegato = null;
                GestioneDelegatoTutore.GetDelegatoByIdPensione(datiPensione.Id, out datiDelegato);
                if (datiDelegato != null)
                    CodFiscDelegato = datiDelegato.CodiceFiscale;
            }

            if (string.IsNullOrEmpty(CodFiscTutore))
            {
                GestioneAnagrafica.DatiAnagrafici datiTutore = null;
                GestioneDelegatoTutore.GetTutoreByIdPensione(datiPensione.Id, out datiTutore);
                if (datiTutore != null)
                    CodFiscTutore = datiTutore.CodiceFiscale;
            }

            if (!string.IsNullOrEmpty(CodFiscDelegato) && !string.IsNullOrEmpty(CodFiscTutore))
            {
                if (CodFiscDelegato.Trim().ToUpperInvariant() == CodFiscTutore.Trim().ToUpperInvariant())
                {
                    messaggioVideo = "L'incaricato alla delega non può coincidere con l'incaricato alla tutela";
                    return false;
                }
            }

            if (!string.IsNullOrEmpty(CodFiscDelegato))
            {
                if (!string.IsNullOrEmpty(codFiscTitolare) &&
                    CodFiscDelegato.Trim().ToUpperInvariant() == codFiscTitolare.Trim().ToUpperInvariant())
                {
                    messaggioVideo = "L'incaricato alla delega non può coincidere con il titolare";
                    return false;
                }
            }
            if (!string.IsNullOrEmpty(CodFiscTutore))
            {
                if (!string.IsNullOrEmpty(codFiscTitolare) &&
                    CodFiscTutore.Trim().ToUpperInvariant() == codFiscTitolare.Trim().ToUpperInvariant())
                {
                    messaggioVideo = "L'incaricato alla tutela non può coincidere con il titolare";
                    return false;
                }
            }

            Utility.TipoDomanda tipoDomanda = Utility.GetTipoDomanda(datiPensione.Gruppo, datiPensione.Prodotto);
            Utility.TipoAppartenenza? tipoAppartenenza = Utility.GetTipoAppartenenza(datiPensione.IndConvInt, datiPensione.Gestione);

            if (!((tipoDomanda == Utility.TipoDomanda.Ricostituzione || isRiapertura) && (tipoAppartenenza == Utility.TipoAppartenenza.AGO || tipoAppartenenza == Utility.TipoAppartenenza.CI)))
                if (!string.IsNullOrEmpty(CodFiscDelegato))
                {
                    GestionePagamento.DatiPagamento datiPagamento = null;
                    GestionePagamento.GetPagamentoByIdPensione(datiPensione.Id, out datiPagamento);
                    if (datiPagamento != null)
                    {
                        if (datiPagamento.ModalitaPagamento.HasValue && datiPagamento.ModalitaPagamento.Value != 'S')
                        {
                            messaggioVideo = "L'incaricato alla delega non può essere acquisito in quanto la modalità di pagamento prevista è differente dallo sportello";
                            return false;
                        }
                    }
                }

            if (!string.IsNullOrEmpty(CodFiscTutore) && codiceTutore.HasValue)
            {
                if (codiceTutore.Value == 'A' && !cessValAmmSost.HasValue && !(tipoDomanda == Utility.TipoDomanda.Ricostituzione && tipoAppartenenza == Utility.TipoAppartenenza.AGO))
                {
                    messaggioVideo = "In presenza di un amministratore di sostegno è obbligatorio indicare la data di Cess.Val.Amm.Sost.";
                    return false;
                }
                else if (codiceTutore.Value != 'A' && cessValAmmSost.HasValue)
                {
                    messaggioVideo = "La data di Cess.Val.Amm.Sost. è ammessa solo in presenza di un amministratore di sostegno";
                    return false;
                }
            }

            return true;
        }
        #endregion Deleghe/Tutele

        #region Oneri
        public static bool ALL_VerificaOneri(GestionePensione.DatiPensione datiPensione, List<GestioneOneri.DatiOneri> listaOneri, char? derogaTraduzioneSuGP, bool isRiaperturaDomanda, GestioneAnagrafica.DatiAnagrafici datiAnagraficiTitolare, Utility.TipoAppartenenza? tipoAppartenenza, out string messaggioVideo)
        {
            messaggioVideo = string.Empty;
            Utility.TipoSalvaguardia TipoSalvaguardia = Utility.GetTipoSalvaguardia(datiPensione);
            string descrizioneDomanda = TipoSalvaguardia == Utility.TipoSalvaguardia.Usuranti ? "Usuranti" : TipoSalvaguardia == Utility.TipoSalvaguardia.EsuberiPA ? "Esuberi" :
                Utility.IsDomandaSperimentaleDonna(datiPensione) ? "tipologia Sperimentale Lavoratrici" : "Salvaguardia";

            GestioneControlliDinamici.ControlloDinamico ctrlEliminazioneScartoOneri0031_0105_0112 = null;
            GestioneControlliDinamici.GetControlloDinamicoByNomeControllo("EliminazioneScartoOneri0031_0105_0112", out ctrlEliminazioneScartoOneri0031_0105_0112);

            if (Utility.IsDomandaUsuranti(datiPensione) || Utility.IsDomandaSalvaguardia124(datiPensione) || Utility.IsDomandaSalvaguardia124Art11Bis(datiPensione) ||
                Utility.IsDomandaSalvaguardia147(datiPensione) || Utility.IsDomandaSalvaguardia214(datiPensione) || Utility.IsDomandaSalvaguardia228(datiPensione) ||
                Utility.IsDomandaEsuberiPA(datiPensione) || Utility.IsDomandaSalvaguardia147_2014(datiPensione) || Utility.IsDomandaSalvaguardia135(datiPensione) ||
                Utility.IsDomandaSalvaguardia208_2015(datiPensione) || Utility.IsDomandaSalvaguardia178_2020(datiPensione) ||
                (Utility.IsDomandaAPEPrecoci(datiPensione) && !Utility.IsDomandaPensioneSuperstitiOrRicostituzione(datiPensione)) ||
                Utility.IsOneriSperDonnaObbligatoriPerControlli(datiPensione, isRiaperturaDomanda, datiPensione.DecorrenzaOriginaria, datiPensione.NaturaPensione))
            {
                if (listaOneri == null || listaOneri.Count == 0)
                {
                    messaggioVideo = "Oneri non presenti per la domanda di " + descrizioneDomanda + " in lavorazione";
                    return false;
                }
            }

            if (listaOneri != null && listaOneri.Count > 0)
            {
                List<GestioneDecodifica.GruppoOneri> listaGruppoOneriDB = null;
                GestioneDecodifica.GetGruppoOneri(out listaGruppoOneriDB);
                DateTime? scadenzaOnerePrecedente = null;

                foreach (GestioneOneri.DatiOneri onere in listaOneri)
                {
                    string codGruppoOnere = listaGruppoOneriDB.Find(x => x.Id == onere.IdCodeGruppo).Code;
                    List<GestioneDecodifica.SottoGruppoOneri> elencoSottoGruppoOneri = null;
                    GestioneDecodifica.GetSottoGruppoOneri(out elencoSottoGruppoOneri);
                    GestioneDecodifica.SottoGruppoOneri SottoGruppoOnereDec = elencoSottoGruppoOneri.Find(x => x.Id == onere.IdCodeSottoGruppo);

                    if (!ALL_VerificaDecorrenzeOneri(datiPensione, codGruppoOnere, onere.Decorrenza, onere.Scadenza, onere.ScadenzaBeneficio, derogaTraduzioneSuGP, isRiaperturaDomanda, SottoGruppoOnereDec.Code, scadenzaOnerePrecedente, datiAnagraficiTitolare, tipoAppartenenza, ctrlEliminazioneScartoOneri0031_0105_0112, out messaggioVideo))
                        return false;

                    scadenzaOnerePrecedente = onere.Scadenza;
                }
            }

            return true;
        }

        public static bool ALL_VerificaDecorrenzeOneri(GestionePensione.DatiPensione datiPensione, string codGruppoOnere, DateTime? decOnere, DateTime? scadenzaOnere, DateTime? scadenzaBeneficioOnere, char? derogaTraduzioneSuGP, bool isRiaperturaDomanda,
            string codSottogruppoOnere, DateTime? scadenzaOnerePrecedente, GestioneAnagrafica.DatiAnagrafici datiAnagraficiTitolare, Utility.TipoAppartenenza? tipoAppartenenza, GestioneControlliDinamici.ControlloDinamico ctrlEliminazioneScartoOneri0031_0105_0112, out string messaggioVideo)
        {
            messaggioVideo = string.Empty;
            Utility.TipoFondo? tipoFondo = Utility.GetTipoFondoByCategoria(tipoAppartenenza, datiPensione.SiglaCategoria);

            short codGruppo = 0;
            short.TryParse(codGruppoOnere, out codGruppo);

            //ENG - Memo 121_2023
            GestioneControlliDinamici.ControlloDinamico ctrlMemo121_2023 = null;
            GestioneControlliDinamici.GetControlloDinamicoByNomeControllo("Abilitazione_Memo_121_2023", out ctrlMemo121_2023);

            if (codGruppo != 2000 && !scadenzaOnere.HasValue && !(Utility.IsPrepensionamentoEditoriaFiltroEBA(datiPensione) && codSottogruppoOnere == "0908") && !Utility.CheckMemo97(datiPensione))
            {
                messaggioVideo = "Scadenza onere non valorizzata";
                return false;
            }

            if ((codGruppo == 5000 || codGruppo == 5300 || codGruppo == 5800 || codGruppo == 6000 || codGruppo == 6100) && !scadenzaBeneficioOnere.HasValue)
            {
                messaggioVideo = "Cess. incumulabilità non valorizzata";
                return false;
            }

            //Eng - in attesa completamento lavorazione memo 121/2023
            //if ((codGruppo == 5300 || codGruppo == 5800 || codGruppo == 6000) && !Utility.IsDomandaCumulo(datiPensione.SiglaCategoria) &&
            //    !Utility.DataSuccessivaA(scadenzaBeneficioOnere.Value, Utility.FirstDayOfMonth(scadenzaOnere.Value)))
            //{
            //    messaggioVideo = "La Cess. Incumulabilità deve essere maggiore o uguale alla Cess. Ben.";
            //    return false;
            //}

            if (decOnere.HasValue)
            {
                if (derogaTraduzioneSuGP.HasValue)
                {
                    if (Utility.IsDomandaENPALS(datiPensione.Gestione))
                    {
                        switch (codGruppo)
                        {
                            case 3600:
                            case 3700:
                            case 3800:
                            case 3900:
                            case 4000:
                            case 4100:
                            case 4200:
                            case 4300:
                            case 4500:
                            case 4600:
                            case 4800:
                            case 5700:
                                switch (derogaTraduzioneSuGP.Value)
                                {
                                    // Salvaguardie a costo zero
                                    case '8':
                                    case 'B':
                                    case 'D':
                                    case 'F':
                                    case 'H':
                                    case 'L':
                                    case 'N':
                                    case 'P':
                                    case 'R':
                                    case 'T':
                                        if (decOnere.Value != scadenzaOnere.Value)
                                        {
                                            messaggioVideo = "La scadenza onere (" + scadenzaOnere.Value.ToString("dd-MM-yyyy") +
                                                    ") deve essere uguale alla decorrenza onere (" + decOnere.Value.ToString("dd-MM-yyyy") + ")";
                                            return false;
                                        }
                                        break;
                                    default:
                                        if (Utility.DataStrettamenteSuccessivaA(decOnere.Value, scadenzaOnere.Value))
                                        {
                                            messaggioVideo = "La decorrenza onere (" + decOnere.Value.ToString("dd-MM-yyyy") +
                                                    ") è maggiore della scadenza onere (" + scadenzaOnere.Value.ToString("dd-MM-yyyy") + ")";
                                            return false;
                                        }
                                        break;

                                }
                                break;
                        }
                    }
                    else
                    {
                        switch (codGruppo)
                        {
                            case 3600:
                            case 3700:
                            case 3800:
                            case 3900:
                            case 4000:
                            case 4100:
                            case 4200:
                            case 4300:
                            case 4500:
                            case 4600:
                            case 4800:
                            case 5700:
                                // Per le domande di salvaguardia NON a costo zero la cessazione deve essere strettamente maggiore alla decorrenza - IsDomandaSalvaguardia
                                switch (derogaTraduzioneSuGP.Value)
                                {
                                    case '7':
                                    case 'A':
                                    case 'C':
                                    case 'E':
                                    case 'G':
                                    case 'S':
                                        if (Utility.DataSuccessivaA(decOnere.Value, scadenzaOnere.Value))
                                        {
                                            messaggioVideo = "La scadenza onere (" + scadenzaOnere.Value.ToString("dd-MM-yyyy") +
                                                    ") deve essere maggiore della decorrenza onere (" + decOnere.Value.ToString("dd-MM-yyyy") + ")";
                                            return false;
                                        }
                                        break;
                                    case 'L':
                                    case 'T':
                                        if (decOnere.Value != scadenzaOnere.Value)
                                        {
                                            messaggioVideo = "La scadenza onere (" + scadenzaOnere.Value.ToString("dd-MM-yyyy") +
                                                    ") deve essere uguale alla decorrenza onere (" + decOnere.Value.ToString("dd-MM-yyyy") + ")";
                                            return false;
                                        }
                                        break;
                                    default:
                                        if (Utility.DataStrettamenteSuccessivaA(decOnere.Value, scadenzaOnere.Value))
                                        {
                                            messaggioVideo = "La decorrenza onere (" + decOnere.Value.ToString("dd-MM-yyyy") +
                                                    ") è maggiore della scadenza onere (" + scadenzaOnere.Value.ToString("dd-MM-yyyy") + ")";
                                            return false;
                                        }
                                        break;
                                }
                                break;
                        }
                    }
                }
                switch (codGruppo)
                {
                    case 4900:
                    case 5100:
                    case 5400:
                    case 5500:
                    case 5000:
                    case 5300:
                    case 5800:
                    case 0900:
                    case 4700:
                    case 6000:
                    case 6100:
                        if (Utility.DataStrettamenteSuccessivaA(decOnere.Value, scadenzaOnere.Value))
                        {
                            messaggioVideo = "La decorrenza onere (" + decOnere.Value.ToString("dd-MM-yyyy") +
                                    ") è maggiore della scadenza onere (" + scadenzaOnere.Value.ToString("dd-MM-yyyy") + ")";
                            return false;
                        }
                        if (!string.IsNullOrEmpty(codSottogruppoOnere))
                        {
                            switch (codSottogruppoOnere.Trim())
                            {
                                case "0906":
                                    if (Utility.DataStrettamenteSuccessivaA(scadenzaOnere.Value, new DateTime(2028, 01, 01)))
                                    {
                                        messaggioVideo = "La cessazione del primo onere non deve essere maggiore di 01/2028.";
                                        return false;
                                    }
                                    if (!(Utility.IsRicostituzioneOrRiapertura(datiPensione, isRiaperturaDomanda) &&
                                        ((datiPensione.Gruppo == "0001" && datiPensione.Prodotto == "0001" && datiPensione.Tipo == "0179") || datiPensione.IdTipoPLPerRIC == (byte)Utility.TipoPLPerRIC.RicPrepensionamentoEditoriaArt1c500L160_2019)))
                                    {
                                        //ENG - memo 57 introdotto controllo dinamico GIORNI_DEC_SCADENZA1_TIPO0179
                                        GestioneControlliDinamici.ControlloDinamico controlloDinamico = null;
                                        GestioneControlliDinamici.GetControlloDinamicoByNomeControllo("GIORNI_DEC_SCADENZA1_TIPO0179", out controlloDinamico);
                                        if (controlloDinamico != null && !String.IsNullOrEmpty(controlloDinamico.ValoreControllo) && !String.IsNullOrEmpty(controlloDinamico.ValoreControllo.Trim()))
                                        {
                                            Int16? limiteGiorni = Convert.ToInt16(controlloDinamico.ValoreControllo);
                                            if ((scadenzaOnere.Value - decOnere.Value).TotalDays > limiteGiorni)
                                            {
                                                messaggioVideo = string.Format("Tra la decorrenza e la cessazione del primo onere non deve intercorrere un numero di giorni superiore a {0}.", limiteGiorni);
                                                return false;
                                            }
                                        }
                                    }
                                    if (decOnere.Value != datiPensione.DecorrenzaOriginaria)
                                    {
                                        messaggioVideo = "La decorrenza dell'onere art. 1 comma 500 L. 160/2019 deve essere uguale alla decorrenza della pensione.";
                                        return false;
                                    }
                                    break;
                                case "0901":
                                    if (Utility.IsPrepensionamentoEditoriaFiltroEAA(datiPensione) && !Utility.IsRicostituzioneOrRiapertura(datiPensione, isRiaperturaDomanda))
                                    {
                                        int diffSettimaneScadDecOnere = (int)((scadenzaOnere.Value - decOnere.Value).TotalDays) / 7;
                                        if (diffSettimaneScadDecOnere > 260)
                                        {
                                            messaggioVideo = "La data indicata al campo ‘Cessazione beneficio’ deve essere coincidente con la decorrenza della pensione secondo i requisiti vigenti (Monti-Fornero).";
                                            return false;
                                        }
                                    }
                                    break;
                                case "0903"://nuovo sottogruppo che va a sostituire "0901" per le pl prepensionamento editoria(tipo = 0162)
                                case "0907"://sottogruppo per le domande prepensionamento editoria(tipo = 0162) con filtro EBA
                                    //Eng - BypassControllo per EAA sul Pannello Oneri "range inferiore ai 5 anni tra cessazione e decorrenza benefici"
                                    if (((Utility.IsPrepensionamentoEditoriaFiltroEAA(datiPensione) && !GestioneBypassControllo.CheckAndLockBypassControlloByNomeBypass(datiPensione, GestioneBypassControllo.NomeBypass.Req_Contr_Prep_Editoria.REQ_CONTR_PREP_EDITORIA)) || Utility.IsPrepensionamentoEditoriaFiltroEBA(datiPensione)) && !Utility.IsRicostituzioneOrRiapertura(datiPensione, isRiaperturaDomanda))
                                    {
                                        int diffSettimaneScadDecOnere = (int)((scadenzaOnere.Value - decOnere.Value).TotalDays) / 7;
                                        if (diffSettimaneScadDecOnere > 260)
                                        {
                                            messaggioVideo = "La data indicata al campo ‘Cessazione beneficio’ deve essere coincidente con la decorrenza della pensione secondo i requisiti vigenti (Monti-Fornero).";
                                            return false;
                                        }
                                    }
                                    break;
                                default:
                                    break;
                            }
                        }
                        if (codGruppo == 5400)
                        {
                            GestioneControlliDinamici.ControlloDinamico ctrl = null;
                            GestioneControlliDinamici.GetControlloDinamicoByNomeControllo("AbilitazioneControlloMemo20_2019", out ctrl);

                            //ENG - Bypass CESSAZIONE_BENEFICIO_ART15_DL4 (solo TRF)
                            if (ctrl != null && ctrl.ValoreControllo == "SI" && !Utility.IsDomandaAutomatica(datiPensione) && codSottogruppoOnere.Trim() == "5401" &&
                                Utility.DataStrettamenteSuccessivaA(scadenzaOnere.Value, decOnere.Value.AddMonths(6)) && !(GestioneBypassControllo.CheckAndLockBypassControlloByNomeBypass(datiPensione, GestioneBypassControllo.NomeBypass.Cessazione_Beneficio_ART15_DL4.CESSAZIONE_BENEFICIO_ART15_DL4) && isRiaperturaDomanda))
                            {
                                messaggioVideo = "La data di cessazione beneficio inserita implica un periodo di onere superiore al massimo possibile in applicazione dell’art. 15, D.L. 28 gennaio 2019, n. 4. Si prega di correggere la data inserita e procedere al salvataggio del pannello.";
                                return false;
                            }
                        }
                        break;
                    case 4400:
                        if (!string.IsNullOrEmpty(codSottogruppoOnere))
                        {
                            switch (codSottogruppoOnere.Trim())
                            {
                                case "4401":
                                case "4402":
                                case "4403":
                                    if (Utility.DataStrettamenteSuccessivaA(decOnere.Value, scadenzaOnere.Value))
                                    {
                                        messaggioVideo = "La decorrenza onere (" + decOnere.Value.ToString("dd-MM-yyyy") +
                                                ") è maggiore della scadenza onere (" + scadenzaOnere.Value.ToString("dd-MM-yyyy") + ")";
                                        return false;
                                    }
                                    else if (Utility.DataStrettamenteSuccessivaA(datiPensione.DecorrenzaOriginaria.Value, decOnere.Value))
                                    {
                                        messaggioVideo = "La decorrenza pensione (" + datiPensione.DecorrenzaOriginaria.Value.ToString("dd-MM-yyyy") +
                                                ") è maggiore della decorrenza onere (" + decOnere.Value.ToString("dd-MM-yyyy") + ")";
                                        return false;
                                    }
                                    break;
                                case "4404":
                                case "4405":
                                case "4406":
                                    if (!(tipoAppartenenza == Utility.TipoAppartenenza.AGO && ctrlEliminazioneScartoOneri0031_0105_0112 != null && !String.IsNullOrEmpty(ctrlEliminazioneScartoOneri0031_0105_0112.ValoreControllo)
                                        && ctrlEliminazioneScartoOneri0031_0105_0112.ValoreControllo.Trim().ToUpperInvariant() == "SI" && Utility.IsDomandaBeneficioTerrorismoLegge206_2004(datiPensione)))
                                    {
                                        if (scadenzaOnerePrecedente != null && scadenzaOnerePrecedente.GetValueOrDefault().AddMonths(1) != decOnere.Value && !(Utility.IsDomandaRipristino(datiPensione).HasValue ? Utility.IsDomandaRipristino(datiPensione).Value : false))
                                        {
                                            messaggioVideo = "La decorrenza del secondo onere deve essere immediatamente successiva alla data di cessazione del primo onere";
                                            return false;
                                        }
                                    }
                                    break;
                                default:
                                    break;
                            }
                        }
                        else
                        {
                            if (Utility.DataStrettamenteSuccessivaA(decOnere.Value, scadenzaOnere.Value))
                            {
                                messaggioVideo = "La decorrenza onere (" + decOnere.Value.ToString("dd-MM-yyyy") +
                                        ") è maggiore della scadenza onere (" + scadenzaOnere.Value.ToString("dd-MM-yyyy") + ")";
                                return false;
                            }
                            else if (Utility.DataStrettamenteSuccessivaA(datiPensione.DecorrenzaOriginaria.Value, decOnere.Value))
                            {
                                messaggioVideo = "La decorrenza pensione (" + datiPensione.DecorrenzaOriginaria.Value.ToString("dd-MM-yyyy") +
                                        ") è maggiore della decorrenza onere (" + decOnere.Value.ToString("dd-MM-yyyy") + ")";
                                return false;
                            }
                        }
                        break;
                }

                if (Utility.IsDomandaVecchiaiaENAV(datiPensione))
                {
                    if (scadenzaOnere.HasValue && !Utility.DataSuccessivaA(scadenzaOnere.Value, decOnere.Value))
                    {
                        messaggioVideo = "La scadenza onere (" + scadenzaOnere.Value.ToString("dd-MM-yyyy") +
                                     ") deve essere maggiore o uguale alla decorrenza onere (" + decOnere.Value.ToString("dd-MM-yyyy") + ")";
                        return false;
                    }

                    //Tra decorrenza beneficio e cessazione beneficio non possono intercorrere più di 7 anni e 6 mesi
                    if (decOnere.HasValue && scadenzaOnere.HasValue && Utility.DataStrettamenteSuccessivaA(scadenzaOnere.Value, decOnere.Value.AddYears(7).AddMonths(6)))
                    {
                        messaggioVideo = "La data di cessazione beneficio inserita implica un periodo di onere superiore al massimo possibile. Si prega di correggere la data inserita e procedere al salvataggio del pannello.";
                        return false;
                    }

                }

                //ENG - Memo 121_2023
                if (Utility.IsDomandaQuota102(datiPensione) && !Utility.IsDomandaAutomatica(datiPensione))
                {
                    if (ctrlMemo121_2023 == null || String.IsNullOrEmpty(ctrlMemo121_2023.ValoreControllo) || ctrlMemo121_2023.ValoreControllo.Trim().ToUpperInvariant() == "NO")
                    {
                        if (datiAnagraficiTitolare != null && datiAnagraficiTitolare.DataNascita.HasValue && scadenzaBeneficioOnere.HasValue && decOnere.HasValue)
                        {
                            DateTime limiteEta;
                            if (tipoAppartenenza == Utility.TipoAppartenenza.FS && (Utility.IsDomandaINPDAP(datiPensione.Gestione) || tipoFondo == Utility.TipoFondo.PT || tipoFondo == Utility.TipoFondo.FS))
                                limiteEta = Utility.FirstDayOfMonth(datiAnagraficiTitolare.DataNascita.Value).AddYears(67);
                            else
                                limiteEta = Utility.FirstDayOfMonth(datiAnagraficiTitolare.DataNascita.Value).AddMonths(1).AddYears(67);

                            if (limiteEta < Utility.FirstDayOfMonth(decOnere.Value))
                            {
                                if (Utility.DataStrettamenteSuccessivaA(scadenzaBeneficioOnere.Value, Utility.FirstDayOfMonth(decOnere.Value)) || !Utility.DataSuccessivaA(scadenzaBeneficioOnere.Value, Utility.FirstDayOfMonth(decOnere.Value)))
                                {
                                    messaggioVideo = "La Cess.Incumulabilità deve essere uguale alla Dec.Ben per decorrenza vecchiaia minore a decorrenza beneficio.";
                                    return false;
                                }
                            }
                            else
                            {
                                if (Utility.DataStrettamenteSuccessivaA(scadenzaBeneficioOnere.Value, limiteEta) || !Utility.DataSuccessivaA(scadenzaBeneficioOnere.Value, limiteEta))
                                {
                                    messaggioVideo = "La data di cessazione incumulabilità inserita non è coerente con la data di raggiungimento del requisito anagrafico previsto per la pensione di vecchiaia. Si prega di correggere la data inserita e procedere al salvataggio del pannello.";
                                    return false;
                                }

                            }

                        }
                    }

                    if (Utility.DifferenzaBetweenDate(scadenzaOnere, decOnere, tipoAppartenenza) > new Utility.DifferenzaDateTime(3, 0, 0))
                    {
                        messaggioVideo = "La data di cessazione beneficio inserita implica un periodo di onere superiore al massimo possibile. Si prega di correggere la data inserita e procedere al salvataggio del pannello";
                        return false;
                    }
                }

                //ENG - Memo 121_2023
                if ((Utility.IsDomandaAnticipataFlessibile(datiPensione) || Utility.IsDomandaAnticipataFlessibileOpzioneContributivo(datiPensione)))
                {
                    //ENG - Aggiornamento Memo 19/2023: il controllo tra decorrenza e cessazione beneficio non deve essere più effettuato per RIC/TRF
                    if (!Utility.IsRicostituzioneOrRiapertura(datiPensione, isRiaperturaDomanda) && datiPensione.SiglaCategoria.Trim() != "VOCTPS" && !(datiPensione.SiglaCategoria.Trim() == "VOCUM" && !String.IsNullOrEmpty(datiPensione.NaturaPensione) && datiPensione.NaturaPensione.Substring(2, 1) == "S"))
                    {
                        int anni = 2;
                        //ENG - PL: per le opzione al contributivo deve controllare 4 anni e 3 mesi
                        if (Utility.IsDomandaAnticipataFlessibileOpzioneContributivo(datiPensione))
                        {
                            anni = 4;
                        }
                        //ENG - Aggiornamento Memo 19/2023: il controllo vale anche per le automatiche e deve controllare 2 anni e 3 mesi                    
                        if (decOnere.HasValue && scadenzaOnere.HasValue && Utility.DataStrettamenteSuccessivaA(scadenzaOnere.Value, decOnere.Value.AddYears(anni).AddMonths(3)))
                        {
                            messaggioVideo = "La data di cessazione beneficio inserita implica un periodo di onere superiore al massimo possibile. Si prega di correggere la data inserita e procedere al salvataggio del pannello";
                            return false;
                        }
                    }

                    if (!Utility.IsDomandaAutomatica(datiPensione))
                    {
                        if (ctrlMemo121_2023 == null || String.IsNullOrEmpty(ctrlMemo121_2023.ValoreControllo) || ctrlMemo121_2023.ValoreControllo.Trim().ToUpperInvariant() == "NO")
                        {
                            //ENG - Quota 103 Gestione Pubblica/024 - il controllo non deve essere effettuato per le RIC Documentali
                            if (!((Utility.IsDomandaINPDAP(datiPensione.Gestione) || tipoFondo == Utility.TipoFondo.FS || tipoFondo == Utility.TipoFondo.PT) && Utility.IsRicostituzione_MotiviDocumentali(datiPensione)))
                            {
                                int reqAA = 0;
                                int reqMM = 0;
                                string codCategoria = datiPensione.GetCodCategoria();

                                if (scadenzaBeneficioOnere.HasValue && datiAnagraficiTitolare != null && datiAnagraficiTitolare.DataNascita.HasValue)
                                {
                                    GestioneDecodifica.GetCtrlRequisitoEta_Base(scadenzaBeneficioOnere.Value, codCategoria, datiAnagraficiTitolare.Sesso.GetValueOrDefault(), tipoAppartenenza.ToString(), out reqAA, out reqMM);
                                    if (reqAA > 0 || reqMM > 0)
                                    {
                                        DateTime limiteEta = new DateTime();

                                        //ENG - Anticipate Flessibili 024/INPDAP - Il mese di nascita deve essere accettato(se ultimo giorno del mese però viene preso quello successivo)
                                        if (tipoAppartenenza == Utility.TipoAppartenenza.FS && (Utility.IsDomandaINPDAP(datiPensione.Gestione) || tipoFondo == Utility.TipoFondo.FS || tipoFondo == Utility.TipoFondo.PT))
                                            limiteEta = Utility.FirstDayOfMonth(datiAnagraficiTitolare.DataNascita.Value.AddDays(1)).AddYears(reqAA).AddMonths(reqMM);
                                        else
                                            limiteEta = Utility.FirstDayOfMonth(datiAnagraficiTitolare.DataNascita.Value).AddMonths(1).AddYears(reqAA).AddMonths(reqMM);

                                        if (Utility.DataStrettamenteSuccessivaA(scadenzaBeneficioOnere.Value, limiteEta) || !Utility.DataSuccessivaA(scadenzaBeneficioOnere.Value, limiteEta))
                                        {
                                            messaggioVideo = string.Format("Alla Cessazione Incumulabilità ({0:dd/MM/yyyy}) non è stato raggiunto il requisito di età di {1} AA e {2} MM", scadenzaBeneficioOnere.Value, reqAA, reqMM);
                                            return false;
                                        }
                                    }
                                }
                            }
                        }
                    }
                }

                //ENG - Memo 123/2024
                if ((Utility.IsDomandaAnticipataFlessibileLeggeBilancio2024(datiPensione) || Utility.IsDomandaAnticipataFlessibileOpzioneContributivoLeggeBilancio2024(datiPensione)) && datiPensione.SiglaCategoria.Trim() != "VOCTPS" && !(datiPensione.SiglaCategoria.Trim() == "VOCUM" && !String.IsNullOrEmpty(datiPensione.NaturaPensione) && datiPensione.NaturaPensione.Substring(2, 1) == "S"))
                {
                    if (!Utility.IsRicostituzioneOrRiapertura(datiPensione, isRiaperturaDomanda))
                    {
                        int anni = 2;
                        //per le opzione al contributivo deve controllare 4 anni e 3 mesi
                        if (Utility.IsDomandaAnticipataFlessibileOpzioneContributivoLeggeBilancio2024(datiPensione))
                        {
                            anni = 4;
                        }
                        if (decOnere.HasValue && scadenzaOnere.HasValue && Utility.DataStrettamenteSuccessivaA(scadenzaOnere.Value, decOnere.Value.AddYears(anni).AddMonths(3)))
                        {
                            messaggioVideo = "La data di cessazione beneficio inserita implica un periodo di onere superiore al massimo possibile. Si prega di correggere la data inserita e procedere al salvataggio del pannello";
                            return false;
                        }
                    }
                }

                if (Utility.IsOpzioneDonna_Legge197_2022_Art1_Comma292_LetteraA(datiPensione, true, true) || Utility.IsOpzioneDonna_Legge197_2022_Art1_Comma292_LetteraB(datiPensione, true, true) ||
                    Utility.IsOpzioneDonna_Legge197_2022_Art1_Comma292_LetteraC(datiPensione, true, true))
                {
                    if (scadenzaOnere.HasValue && !Utility.DataSuccessivaA(scadenzaOnere.Value, decOnere.Value))
                    {
                        messaggioVideo = "La scadenza onere (" + scadenzaOnere.Value.ToString("dd-MM-yyyy") +
                                     ") deve essere maggiore o uguale alla decorrenza onere (" + decOnere.Value.ToString("dd-MM-yyyy") + ")";
                        return false;
                    }
                }
            }

            return true;
        }
        #endregion Oneri

        #region Usuranti
        public static bool ALL_VerificaCodNaturaUsuranti(GestionePensione.DatiPensione datiPensione, out string messaggioVideo)
        {
            messaggioVideo = string.Empty;
            if (Utility.IsDomandaUsuranti(datiPensione))
            {
                if (string.IsNullOrEmpty(datiPensione.NaturaPensione) || datiPensione.NaturaPensione.Length < 3 || datiPensione.NaturaPensione.Substring(2) != "Z")
                {
                    messaggioVideo = "Codice natura 3 non valorizzato a Z per la domanda di usuranti in lavorazione. E' necessario risalvare l'intero quadro 'Liquidazione Pensione'";
                    return false;
                }
            }

            return true;
        }
        #endregion Usuranti

        #region Memo 79 - Organizzazioni Internazionali
        public static bool ALL_CodNaturOrganizzazioniInternazionali(GestionePensione.DatiPensione datiPensione, string CodiceNatura, out string messaggioVideo)
        {
            messaggioVideo = string.Empty;
            if (Utility.IsDomandaOrganizzazioniInternazionali(datiPensione))
            {
                char codNat1 = ' ';
                char codNat2 = ' ';
                char codNat3 = ' ';
                Utility.GetCodiciNatura(CodiceNatura, out codNat1, out codNat2, out codNat3);

                if (codNat3.ToString().Trim() == "V")
                {
                    DateTime dataMinima = new DateTime(2025, 1, 1);
                    if (datiPensione.DecorrenzaOriginaria < dataMinima)
                    {
                        messaggioVideo = "In presenza del valore “V” al 3° byte del codice natura non può essere inserita una decorrenza anteriore al 1/1/2025";
                        return false;
                    }
                }
            }

            return true;
        }

        public static bool ALL_NSettimane_OrganizzazioniInternazionali(GestionePensione.DatiPensione datiPensione, GestioneAnagrafica.DatiAnagrafici datiAnagrafica, GestioneFondo.DatiFondo datiFondo, out string messaggioVideo)
        {
            messaggioVideo = string.Empty;
            if (Utility.IsDomandaOrganizzazioniInternazionali(datiPensione))
            {   // Tripletta 0001 – 0001 – 0001 filtro C9A
                if (datiPensione.Gruppo == "0001" && datiPensione.Prodotto == "0001" && datiPensione.Tipo == "0001")
                {
                    int? NsettimaneTot = datiFondo.SettimaneUtiliDiritto.Value + datiFondo.SettimaneUtiliDirittoOI.Value;
                    if (datiAnagrafica.Sesso == 'M' && NsettimaneTot < 2227)
                    {
                        messaggioVideo = "IL NUMERO SETTIMANE NON PUÒ ESSERE INFERIORE A 2227 (42 ANNI E 10 MESI DI CONTRIBUZIONE)";
                        return false;
                    }
                    else if (datiAnagrafica.Sesso == 'F' && NsettimaneTot < 2175)
                    {
                        messaggioVideo = "IL NUMERO SETTIMANE NON PUÒ ESSERE INFERIORE A 2175 (41 ANNI E 10 MESI DI CONTRIBUZIONE)";
                        return false;
                    }
                }
                else if (datiPensione.Gruppo == "0001" && datiPensione.Prodotto == "0002" && datiPensione.Tipo == "0001")
                {
                    int? NsettimaneTot = datiFondo.SettimaneUtiliDiritto.Value + datiFondo.SettimaneUtiliDirittoOI.Value;
                    if (NsettimaneTot < 1040)
                    {
                        messaggioVideo = "IL NUMERO SETTIMANE NON PUÒ ESSERE INFERIORE A 1040";
                        return false;
                    }
                }
                else if (datiPensione.Gruppo == "0003" && datiPensione.Prodotto == "0022" && datiPensione.Tipo == "0001")
                {
                    int? NsettimaneTot = datiFondo.SettimaneUtiliDiritto.Value + datiFondo.SettimaneUtiliDirittoOI.Value;
                    if (NsettimaneTot < 260)
                    {
                        messaggioVideo = "IL NUMERO SETTIMANE NON PUÒ ESSERE INFERIORE A 260";
                        return false;
                    }
                }
            }

            return true;
        }

