        public static bool ALL_ControlsDecorrenzaExCombattenteWithDataPresentazione(DateTime? decorrenzaExCambattente, GestionePensione.DatiPensione datiPensione, out string messaggioVideo)
        {
            messaggioVideo = string.Empty;
            Utility.TipoDomanda tipoDomanda = Utility.GetTipoDomanda(datiPensione.Gruppo, datiPensione.Prodotto);
            bool ret = true;
            if (tipoDomanda == Utility.TipoDomanda.Normale || tipoDomanda == Utility.TipoDomanda.Superstiti)
            {
                switch (Utility.GetTipoAppartenenza(datiPensione.IndConvInt, datiPensione.Gestione))
                {
                    case Utility.TipoAppartenenza.CI:
                    case Utility.TipoAppartenenza.AGO:
                        if (decorrenzaExCambattente.HasValue && decorrenzaExCambattente.Value <= datiPensione.DataPresentazioneDomanda)
                        {
                            messaggioVideo = string.Format("La decorrenza ({0}) nel tab 'Cieco/ExCombattente' deve essere maggiore della data presentazione della domanda ({1})", decorrenzaExCambattente.Value.ToString("MM/yyyy"), datiPensione.DataPresentazioneDomanda.ToString("dd/MM/yyyy"));
                            ret = false;
                        }
                        break;
                    case Utility.TipoAppartenenza.FS:
                        break;
                }
            }
            return ret;
        }

        public static bool ALL_IsTipoBeneficioArt24Comma15BisAmmesso(GestionePensione.DatiPensione datiPensione, char? codiceSpecificoTraduzioneSuGP, DateTime? decorrenzaOriginaria, string naturaPensione, char? sessoTitolare,
            DateTime? dataNascitaTitolare, int? settimaneUtiliDiritto)
        {
            DateTime dataCompare = new DateTime(2012, 1, 31);
            Utility.TipoAppartenenza? tipoAppartenenza = Utility.GetTipoAppartenenza(datiPensione.IndConvInt, datiPensione.Gestione);

            // Il beneficio 10 potrà essere valorizzato solo per pensioni con decorrenze >= 01.2012
            if (!decorrenzaOriginaria.HasValue || !Utility.DataStrettamenteSuccessivaA(decorrenzaOriginaria.Value, dataCompare))
                return false;

            // Se è una pensione di vecchiaia
            if (Utility.IsPensioneVecchiaiaOrRicostituzione(datiPensione, codiceSpecificoTraduzioneSuGP))
            {
                // Per le pensioni di vecchiaia (natura blank o “6” al primo byte), il campo potrà essere valorizzato con il nuovo codice solo per le donne con almeno 64 anni di età alla 
                // decorrenza della pensione e 20 anni di settimane utili al diritto
                if (!(sessoTitolare == 'F' && dataNascitaTitolare.HasValue && Utility.DataSuccessivaA(decorrenzaOriginaria.Value, dataNascitaTitolare.Value.AddYears(64))))
                    return false;

                // Solo per FS esiste il bypass
                if (!tipoAppartenenza.HasValue || tipoAppartenenza.Value != Utility.TipoAppartenenza.FS ||
                    (tipoAppartenenza.Value == Utility.TipoAppartenenza.FS &&
                        (!GestioneBypassControllo.CheckAndLockBypassControlloByNomeBypass(datiPensione, GestioneBypassControllo.NomeBypass.MaggiorazioniBenefici_Benefici_FS.BENEFICIO_ART24COMMA15BIS) &&
                        !GestioneBypassControllo.CheckAndLockBypassControlloByNomeBypass(datiPensione, GestioneBypassControllo.NomeBypass.MaggiorazioniBenefici_Benefici_FS.BENEF_ULT_ART24COMMA15BIS))))
                {
                    if (!(settimaneUtiliDiritto >= 1040))
                        return false;
                }
            }
            // Se è una pensione anticipata
            else if (Utility.IsPensioneAnzianitaOrRicostituzione(datiPensione, codiceSpecificoTraduzioneSuGP))
            {
                // Per le pensioni anticipate (natura 1 o 2 al primo byte), il campo potrà essere valorizzato con il nuovo codice a prescindere dal sesso per titolari con almeno 64 anni 
                // di età alla decorrenza della pensione e almeno 35 anni di settimane utili al diritto
                if (!(dataNascitaTitolare.HasValue && Utility.DataSuccessivaA(decorrenzaOriginaria.Value, dataNascitaTitolare.Value.AddYears(64))))
                    return false;

                // Solo per FS esiste il bypass
                if (!tipoAppartenenza.HasValue || tipoAppartenenza.Value != Utility.TipoAppartenenza.FS ||
                    (tipoAppartenenza.Value == Utility.TipoAppartenenza.FS &&
                     (!GestioneBypassControllo.CheckAndLockBypassControlloByNomeBypass(datiPensione, GestioneBypassControllo.NomeBypass.MaggiorazioniBenefici_Benefici_FS.BENEFICIO_ART24COMMA15BIS) &&
                     !GestioneBypassControllo.CheckAndLockBypassControlloByNomeBypass(datiPensione, GestioneBypassControllo.NomeBypass.MaggiorazioniBenefici_Benefici_FS.BENEF_ULT_ART24COMMA15BIS))))
                {
                    if (!(settimaneUtiliDiritto >= 1820))
                        return false;
                }
            }
            else
                return false;

            return true;
        }

        public static bool ALL_ControlsLavoratoriNonVedenti(string tipoSettimaneBeneficio, int? nSettimaneBeneficio, short? settAnzContr311295, GestionePensione.DatiPensione datiPensione, GestioneDanteCausa.DatiDanteCausa datiDanteCausa, out string messaggioVideo)
        {
            messaggioVideo = string.Empty;
            DateTime? decorrenzaPensioneOrDecorrenzaPensioneDC = Utility.GetDecorrenzaPensioneOrDecorrenzaDantecausa(datiPensione.DecorrenzaOriginaria, datiDanteCausa != null ? datiDanteCausa.DecorrenzaPensione : null);
            Utility.TipoAppartenenza? tipoAppartenenza = Utility.GetTipoAppartenenza(datiPensione.IndConvInt, datiPensione.Gestione);
            Utility.TipoFondo? tipoFondo = Utility.GetTipoFondoByCategoria(tipoAppartenenza, datiPensione.SiglaCategoria);

            if (tipoSettimaneBeneficio == "01")
            {
                if (tipoAppartenenza != Utility.TipoAppartenenza.FS || !Utility.IsRicostituzione(datiPensione.Gruppo) || Utility.IsDomandaINPDAP(datiPensione.Gestione) || tipoFondo == Utility.TipoFondo.FS || tipoFondo == Utility.TipoFondo.PT || (Utility.IsRicostituzione_MotiviContributivi(datiPensione) && decorrenzaPensioneOrDecorrenzaPensioneDC.HasValue && Utility.DataSuccessivaA(decorrenzaPensioneOrDecorrenzaPensioneDC.Value, new DateTime(2017, 01, 01))))
                {
                    if (!nSettimaneBeneficio.HasValue)
                    {
                        messaggioVideo = "Numero settimane beneficio obbligatorio.";
                        return false;
                    }
                }

                if (settAnzContr311295.GetValueOrDefault() > nSettimaneBeneficio.GetValueOrDefault())
                {
                    messaggioVideo = "Il valore del “Settimane anz. contrib. quota contributiva” deve essere inferiore o uguale al valore del “Numero settimane beneficio”.";
                    return false;
                }
            }
            return true;
        }

