        #region Modalità Pagamento
        public static bool ALL_ControlsDatiPagamento(char? tipoPagamento, char? modalitaPagamento, string iban, string libretto, out string errori)
        {
            errori = "";

            if (!tipoPagamento.HasValue || !modalitaPagamento.HasValue)
            {
                errori = "Modalità pagamento non valorizzata";
                return false;
            }

            switch (tipoPagamento.Value)
            {
                case 'B':
                    switch (modalitaPagamento.Value)
                    {
                        case 'S': // Sportello
                            if (!string.IsNullOrEmpty(iban))
                            {
                                errori = "L'IBAN non va valorizzato";
                                return false;
                            }
                            break;
                        case 'C': // Conto corrente
                        case 'L': // Libretto
                            if (string.IsNullOrEmpty(iban))
                            {
                                errori = "L'IBAN deve essere valorizzato";
                                return false;
                            }
                            break;
                    }

                    if (!string.IsNullOrEmpty(iban) && (iban.ToUpperInvariant().Substring(5, 5) == "07601" || (iban.ToUpperInvariant().Substring(5, 5) == "36081" && iban.ToUpperInvariant().Substring(10, 5) == "05138")))
                    {
                        errori = "L'Iban inserito non è di tipo bancario ma postale";
                        return false;
                    }

                    break;
                case 'P':
                    switch (modalitaPagamento.Value)
                    {
                        case 'S': // Sportello
                            if (!string.IsNullOrEmpty(iban))
                            {
                                errori = "L'IBAN non va valorizzato";
                                return false;
                            }
                            break;
                        case 'C': // Conto corrente
                            if (string.IsNullOrEmpty(iban))
                            {
                                errori = "L'IBAN deve essere valorizzato";
                                return false;
                            }
                            if (iban.ToUpperInvariant().Substring(10, 5) == "03384")
                            {
                                errori = "L'Iban inserito non è valido. Trattasi di libretto";
                                return false;
                            }
                            if (iban.ToUpperInvariant().Substring(10, 5) == "05138")
                            {
                                errori = "L'Iban inserito non è valido. Trattasi di Postepay Evolution.";
                                return false;
                            }
                            break;
                        case 'L': // Libretto
                            if (!string.IsNullOrEmpty(libretto))
                            {
                                errori = "Il Libretto non va valorizzato. Acquisire l'IBAN.";
                                return false;
                            }
                            if (string.IsNullOrEmpty(iban))
                            {
                                errori = "L'IBAN deve essere valorizzato";
                                return false;
                            }
                            if (iban.ToUpperInvariant().Substring(10, 5) == "05138")
                            {
                                errori = "L'Iban inserito non è valido. Trattasi di Postepay Evolution.";
                                return false;
                            }
                            if (!string.IsNullOrEmpty(iban) && iban.ToUpperInvariant().Substring(10, 5) != "03384")
                            {
                                errori = "L'Iban inserito non è valido, perchè diverso da libretto.";
                                return false;
                            }
                            break;
                        case 'K': // Conto corrente
                            if (string.IsNullOrEmpty(iban))
                            {
                                errori = "L'IBAN deve essere valorizzato";
                                return false;
                            }
                            if (iban.ToUpperInvariant().Substring(10, 5) == "03384")
                            {
                                errori = "L'Iban inserito non è valido. Trattasi di libretto";
                                return false;
                            }
                            if (iban.ToUpperInvariant().Substring(10, 5) != "05138")
                            {
                                errori = "L'Iban inserito non è valido. Trattasi di Postepay Evolution.";
                                return false;
                            }
                            break;
                    }

                    if (!string.IsNullOrEmpty(iban) && iban.ToUpperInvariant().Substring(5, 5) != "07601" && !(iban.ToUpperInvariant().Substring(5, 5) == "36081" && iban.ToUpperInvariant().Substring(10, 5) == "05138"))
                    {
                        errori = "L'Iban inserito non è di tipo postale ma bancario";
                        return false;
                    }

                    break;
            }

            return true;
        }

        public static bool ALL_ControlsBancaItalia(GestionePensione.DatiPensione datiPensione, int? abi, int? cab, out string errori)
        {
            errori = "";

            if (abi.GetValueOrDefault() == 1000 && (cab.GetValueOrDefault() == 03203 || cab.GetValueOrDefault() == 6603203))
            {
                if (Utility.GetCodiceSedeLavorazione(datiPensione, Utility.IsRiaperturaDomanda(datiPensione.Id)) != 7000 && Utility.GetCentroOperativoLavorazione(datiPensione, Utility.IsRiaperturaDomanda(datiPensione.Id)) != 0)
                {
                    errori = "La modalità di pagamento ABI 01000, è ammessa solo per le domande su sede 700000";
                    return false;
                }

                GestionePensione.DatiPatronato datiPatronato = null;
                GestionePensione.GetPatronatoByIdPensione(datiPensione.Id, out datiPatronato);
                if (datiPatronato == null || string.IsNullOrEmpty(datiPatronato.TipoUfficio) ||
                    datiPatronato.TipoUfficio.Trim() != "23" || string.IsNullOrEmpty(datiPatronato.CodiceUfficio) ||
                    datiPatronato.CodiceUfficio.Trim() != "03203")
                {
                    errori = "La modalità di pagamento ABI 01000, è ammessa solo per le domande provenienti dalla Banca d’Italia (fonte Banca e codice ufficio 03203)";
                    return false;
                }
            }

            return true;
        }

        public static bool AGO_ControlsDatiPagamentoByDatiCalcolo(GestionePensione.DatiPensione datiPensione, char? tipoPagamento, char? modalitaPagamento, out string errori)
        {
            errori = "";

            GestioneControlliDinamici.ControlloDinamico ctrlAbilitazioneMemo93 = null;
            GestioneControlliDinamici.GetControlloDinamicoByNomeControllo("AbilitazioneMemo93", out ctrlAbilitazioneMemo93);

            if (tipoPagamento.HasValue)
            {
                if (Utility.IsDomandaIOTOT(datiPensione.SiglaCategoria) || Utility.IsDomandaSOTOT(datiPensione.SiglaCategoria))
                {
                    if (tipoPagamento.Value == 'C')
                    {
                        List<GestioneCalcolo.QuotePensione> listaQuotePensione = null;
                        GestioneCalcolo.GetQuotePensioneByIdPensione(datiPensione.Id, out listaQuotePensione);
                        if (listaQuotePensione != null)
                        {

                            List<string> listaCodici = new List<string> { "F0", "F1", "G0", "H0", "I0", "J0", "K0", "L0", "N0", "O0", "P0", "Q0", "R0", "S0", "SP", "T0", "U0", "V0", "Z0", "Z1", "PR" };
                            if (ctrlAbilitazioneMemo93 != null && !String.IsNullOrEmpty(ctrlAbilitazioneMemo93.ValoreControllo) && ctrlAbilitazioneMemo93.ValoreControllo.ToUpperInvariant().Trim() == "SI")
                                listaCodici.Remove("F0");

                            List<GestioneDecodifica.DecEnteGestioneFondo> listaDecEnteGestioneFondo = null;
                            GestioneDecodifica.GetDecEnteGestioneFondo(out listaDecEnteGestioneFondo);

                            var lstRecordCodGestione = from Record in listaQuotePensione
                                                       join dec in listaDecEnteGestioneFondo on Record.EnteGestioneFondo equals dec.Id
                                                       select new { Record, TraduzioneSuGP = dec.Codice.Trim() };

                            var lst = lstRecordCodGestione.Select(x => x.TraduzioneSuGP).Where(x => listaCodici.Contains(x)).ToList();
                            if (lst.Count > 0)
                            {
                                errori = string.Format("Non è possibile utilizzare la modalità cassa sede se è presente una delle seguenti gestioni: {0} ", listaCodici.Aggregate((a, b) => { return a + ", " + b; }));
                                return false;
                            }
                        }
                    }
                }
                else if (Utility.IsDomandaCumulo(datiPensione.SiglaCategoria))
                {
                    if (tipoPagamento.Value == 'C')
                    {
                        GestioneDatiGenericiAgoCi.PensioniDatiGenerici datiPensioniDatiGenerici = null;
                        GestioneDatiGenericiAgoCi.GetDatiGenericiByIdPensione(datiPensione.Id, out datiPensioniDatiGenerici);
                        if (datiPensioniDatiGenerici != null)
                        {
                            //Tipo cumulo esterno
                            if (datiPensioniDatiGenerici.TipoCumulo.HasValue && !datiPensioniDatiGenerici.TipoCumulo.GetValueOrDefault())
                            {
                                errori = "Non è possibile utilizzare la modalità cassa sede se il tipo cumulo è 'esterno'";
                                return false;
                            }
                        }
                    }
                }
            }

            return true;
        }


