        public static bool AGO_CI_ControlsEsenzioneFiscaleVittimaTerrorismo(GestionePensione.DatiPensione datiPensione, bool isRiaperturaDomanda, byte? esenzioneFiscale, out string messaggioVideo)
        {
            messaggioVideo = string.Empty;

            if (!Utility.IsRicostituzioneOrRiapertura(datiPensione, isRiaperturaDomanda) && esenzioneFiscale == 1)
            {
                messaggioVideo = "Non è possibile acquisire l'esenzione fiscale per Vittime Terrorismo";
                return false;
            }

            return true;
        }

        public static bool AGO_CI_ControlsEsenzioneFiscaleDoppiaImposizione(GestionePensione.DatiPensione datiPensione, string codiceComuneResidenza, bool isRiapertura, byte? esenzioneFiscale, out string messaggioVideo)
        {
            messaggioVideo = string.Empty;

            if (!isRiapertura && esenzioneFiscale.GetValueOrDefault() == 2)
            {
                if (!Utility.IsEsenzioneFiscaleEsteroAutonomi(datiPensione, codiceComuneResidenza))
                {
                    messaggioVideo = "Categoria e stato di residenza incompatibile con detassazione";
                    return false;
                }
            }
            return true;
        }

        public static bool AGO_CI_ControlsRedditiSentenza495_93(List<BLCommon.GestioneDanteCausa.DatiRedditoSentenza495_93> lRedditiSentenza495_93, DateTime? decorrenzaOriginaria, DateTime? dataMorteDC,
            DateTime? decorrenzaPensioneDiretta, byte? provenienzaPensione, GestionePensione.DatiPensione datiPensione, List<GestioneFamiliari.Familiare> listaFamiliari, Utility.TipoAppartenenza? tipoAppartenenza,
             GestioneDanteCausa.DatiDanteCausa datiDanteCausa, bool isRiaperturaDomanda, out string errore)
        {
            errore = string.Empty;

            lRedditiSentenza495_93 = lRedditiSentenza495_93.Where(x => x.FlagSentenza == null).ToList();

            if (lRedditiSentenza495_93 != null && lRedditiSentenza495_93.Count > 0)
            {
                //ENG - Aggiornamento Modifica Sentenza 495 
                if (tipoAppartenenza == Utility.TipoAppartenenza.CI && Utility.IsDomandaPensioneSuperstitiOrRicostituzione(datiPensione))
                {
                    if (lRedditiSentenza495_93.Exists(x => !x.IsPre2009.GetValueOrDefault() && !x.AnnoReddito.HasValue))
                    {
                        errore = "E' obbligatorio acquisire l'anno";
                        return false;
                    }
                }
                else
                {

                    if (lRedditiSentenza495_93.Exists(x => !x.AnnoReddito.HasValue || (!x.RedditoConiuge.HasValue && !x.RedditoDaPensioneConiuge.HasValue && !x.RedditoDaPensioneDC.HasValue && !x.RedditoTitolare.HasValue)))
                    {
                        errore = "E' obbligatorio acquisire l'anno e almeno un importo per ogni record";
                        return false;
                    }
                }

                lRedditiSentenza495_93.Sort(delegate
                    (BLCommon.GestioneDanteCausa.DatiRedditoSentenza495_93 r1, BLCommon.GestioneDanteCausa.DatiRedditoSentenza495_93 r2)
                { return r1.AnnoReddito.Value.CompareTo(r2.AnnoReddito); });

                if (lRedditiSentenza495_93.Count != lRedditiSentenza495_93.Select(x => x.AnnoReddito).Distinct().Count())
                {
                    errore = "Non è possibile inserire due record con lo stesso anno";
                    return false;
                }

                if (dataMorteDC.HasValue)
                {
                    //Controlli mail 2015-10-06 - LIQPENS - Dante Causa / Sentenza 495
                    //I controlli devono valere solo per le pensioni indirette
                    if (provenienzaPensione.GetValueOrDefault() == 0)
                    {
                        if (dataMorteDC.Value.Month != 12)
                        {
                            //mese data morte dante causa diversa da dicembre
                            DateTime dataEstremoSuperiore = new DateTime(1995, 12, 31);
                            if (lRedditiSentenza495_93.Count != 1 || lRedditiSentenza495_93.Exists(x => x.AnnoReddito != dataMorteDC.Value.Year) && !(tipoAppartenenza == Utility.TipoAppartenenza.CI &&
                                (datiPensione.DecorrenzaOriginaria != null && Utility.DataSuccessivaA(dataEstremoSuperiore, datiPensione.DecorrenzaOriginaria.GetValueOrDefault()) || (decorrenzaPensioneDiretta != null && Utility.DataSuccessivaA(dataEstremoSuperiore, decorrenzaPensioneDiretta.GetValueOrDefault())))))
                            {
                                errore = string.Format("Deve essere acquisito un solo record con l'anno di morte del dante causa ({0})", dataMorteDC.Value.Year);
                                return false;
                            }
                        }
                        else
                        {

                            //ENG - Gestione Pensione Estera e redditi Sentenza 495
                            if (tipoAppartenenza == Utility.TipoAppartenenza.CI && Utility.IsDomandaPensioneSuperstitiOrRicostituzione(datiPensione))
                            {
                                if (lRedditiSentenza495_93 != null && lRedditiSentenza495_93.Exists(x => !x.IsPre2009.GetValueOrDefault() && x.AnnoReddito != dataMorteDC.Value.Year))
                                {
                                    errore = "Nel pannello sentenza 495 occorre indicare esclusivamente i redditi riferiti all'anno di morte del dante causa.";
                                    return false;
                                }

                            }
                            else
                                //mese data morte dante causa uguale a dicembre
                                if (lRedditiSentenza495_93.Count != 2 || lRedditiSentenza495_93.Exists(x => x.AnnoReddito != dataMorteDC.Value.Year && x.AnnoReddito != decorrenzaOriginaria.Value.Year))
                                {
                                    errore = "Nel pannello sentenza 495 occorre indicare esclusivamente i redditi riferiti all'anno di morte del dante causa e quelli riferiti all'anno di decorrenza della pensione del beneficiario.";
                                    return false;
                                }
                        }
                        //ENG - Aggiornamento Modifica Sentenza 495 
                        if (tipoAppartenenza != Utility.TipoAppartenenza.CI || !Utility.IsDomandaPensioneSuperstitiOrRicostituzione(datiPensione))
                        {

                            if (listaFamiliari != null && listaFamiliari.FindIndex(x => x.IsConiugeOrUnitoCivile()) > -1 && decorrenzaOriginaria > new DateTime(1992, 12, 31) && lRedditiSentenza495_93.Exists(x => !x.RedditoConiuge.HasValue && !x.RedditoDaPensioneConiuge.HasValue))
                            {
                                errore = "E' obbligatorio acquisire il reddito del coniuge.";
                                return false;
                            }
                            if (lRedditiSentenza495_93.Exists(x => !x.RedditoDaPensioneDC.HasValue && !x.RedditoTitolare.HasValue))
                            {
                                errore = "E' obbligatorio acquisire il reddito del dante causa.";
                                return false;
                            }
                        }
                    }
                    //Fine controlli mail 2010-10-06 - LIQPENS - Dante Causa / Sentenza 495
                    else
                    {
                        //ENG - Aggiornamento Modifica Sentenza 495 
                        if (tipoAppartenenza == Utility.TipoAppartenenza.CI && Utility.IsDomandaPensioneSuperstitiOrRicostituzione(datiPensione))
                        {
                            if (lRedditiSentenza495_93 != null && lRedditiSentenza495_93.Exists(x => !x.IsPre2009.GetValueOrDefault() && x.AnnoReddito != dataMorteDC.Value.Year))
                            {
                                errore = "Nel pannello sentenza 495 occorre indicare esclusivamente i redditi riferiti all'anno di morte del dante causa.";
                                return false;
                            }

                        }
                        else
                        {

                            if (dataMorteDC.Value.Month != 12)
                            {

                                //per le sobanc con deco diretta <83 salto il controllo su la decorrenza della pensione diretta
                                //saltare anche per ante96 e per categore ante96 in assenza di decorrenza della pensione diretta (sono icasi in cui non si riesce ad imputare come ante96)
                                List<string> sigleCategorieAmmesse = new List<string>();
                                sigleCategorieAmmesse.AddRange(Utility.getCategorieDipendenti());
                                sigleCategorieAmmesse.AddRange(Utility.getCategorieGestioniSpeciali());
                                var saltaPerAnte96 = Utility.IsDomandaAnte96(datiPensione, datiPensione, datiDanteCausa, isRiaperturaDomanda) != null ||
                                                    (sigleCategorieAmmesse.Contains(datiPensione.SiglaCategoria.Trim()) && !decorrenzaPensioneDiretta.HasValue);
                                var saltaControlloDecDiretta = (Utility.IsDomandaSOBANC(datiPensione.SiglaCategoria) && decorrenzaPensioneDiretta.Value.Year < 1983);

                                //mese data morte dante causa diversa da dicembre
                                if (!saltaPerAnte96 && (!lRedditiSentenza495_93.Exists(x => x.AnnoReddito == decorrenzaOriginaria.Value.Year)
                                    || (!saltaControlloDecDiretta && !lRedditiSentenza495_93.Exists(x => x.AnnoReddito == decorrenzaPensioneDiretta.Value.Year))) &&
                                    !(Utility.IsDomandaENPALS(datiPensione.Gestione) && Utility.IsDomandaPensioneSuperstitiOrRicostituzione(datiPensione) &&
                                     decorrenzaPensioneDiretta.HasValue && decorrenzaPensioneDiretta.Value.Year < 1983 && lRedditiSentenza495_93.Exists(x => x.AnnoReddito >= 1995)))
                                {
                                    errore = "Nel pannello sentenza 495 occorre indicare anche i redditi riferiti all'anno di decorrenza della pensione del beneficiario e quelli riferiti all'anno di decorrenza della pensione del dante causa.";
                                    return false;
                                }
                            }
                            else
                            {

                                int annoDecorrenzaPensioneDiretta = decorrenzaPensioneDiretta.HasValue ? (decorrenzaPensioneDiretta.Value.Year < 1983 ? 1983 : decorrenzaPensioneDiretta.Value.Year) : 0;

                                //mese data morte dante causa uguale a dicembre
                                if (!lRedditiSentenza495_93.Exists(x => x.AnnoReddito == dataMorteDC.Value.Year) || !lRedditiSentenza495_93.Exists(x => x.AnnoReddito == decorrenzaOriginaria.Value.Year) || !lRedditiSentenza495_93.Exists(x => x.AnnoReddito == annoDecorrenzaPensioneDiretta))
                                {
                                    errore = "Nel pannello sentenza 495 occorre indicare anche i redditi riferiti all'anno di morte del dante causa, quelli riferiti all'anno di decorrenza della pensione del beneficiario e quelli riferiti all'anno di decorrenza della pensione del dante causa.";
                                    return false;
                                }
                            }
                        }
                    }
                }

                foreach (BLCommon.GestioneDanteCausa.DatiRedditoSentenza495_93 redditiSentenza495_93 in lRedditiSentenza495_93)
                {
                    if (redditiSentenza495_93.AnnoReddito.Value < 2009)
                    {
                        //pensione di reversibilità
                        if (redditiSentenza495_93.AnnoReddito.HasValue && redditiSentenza495_93.AnnoReddito.Value.ToString().Length != 4)
                        {
                            errore = "Campo 'Anno' non valido per 'Sentenza 495/93' Dante Causa ante 2009";
                            return false;
                        }
                        //if (provenienzaPensione.GetValueOrDefault() == 0)
                        //{
                        //    if (dataMorteDC.HasValue)
                        //    {
                        //        if (lRedditiSentenza495_93.Count(x => x.AnnoReddito.GetValueOrDefault() < 2009) > 1 || (lRedditiSentenza495_93.First().AnnoReddito != dataMorteDC.Value.Year && lRedditiSentenza495_93.First().AnnoReddito != dataMorteDC.Value.Year - 1))
                        //        {
                        //            errore = "Deve essere acquisito solo un record Ante 2009 con anno pari a quello del decesso o pari a quello del decesso – 1";
                        //            return false;
                        //        }
                        //    }
                        //}
                        //else
                        if (provenienzaPensione.GetValueOrDefault() != 0)
                        {
                            //pensione di reversibilità
                            if (decorrenzaPensioneDiretta.HasValue && decorrenzaOriginaria.HasValue)
                            {
                                if (redditiSentenza495_93.AnnoReddito.Value > decorrenzaOriginaria.Value.Year || redditiSentenza495_93.AnnoReddito.Value < decorrenzaPensioneDiretta.Value.Year)
                                {
                                    errore = "Redditi Ante 2009: l'anno deve essere compreso tra la decorrenza della pensione diretta e l'anno di decorrenza originaria";
                                    return false;
                                }
                            }
                        }
                    }
                    else
                    {
                        if (redditiSentenza495_93.AnnoReddito.HasValue && redditiSentenza495_93.AnnoReddito.Value.ToString().Length != 4)
                        {
                            errore = "Campo 'Anno' non valido per 'Sentenza 495/93' Dante Causa post 2008";
                            return false;
                        }

                        //if (provenienzaPensione.GetValueOrDefault() == 0)
                        //{
                        //    if (dataMorteDC.HasValue && decorrenzaOriginaria.HasValue)
                        //    {
                        //        if (dataMorteDC.Value.Year == decorrenzaOriginaria.Value.Year)
                        //        {
                        //            if (lRedditiSentenza495_93.Count(x => x.AnnoReddito.GetValueOrDefault() > 2008) > 1 || (lRedditiSentenza495_93.First().AnnoReddito != dataMorteDC.Value.Year))
                        //            {
                        //                errore = "E' possibile acquisire solo un record con anno pari a quello del decesso";
                        //                return false;
                        //            }
                        //        }
                        //        else
                        //        {
                        //            if (lRedditiSentenza495_93.Count(x => x.AnnoReddito.GetValueOrDefault() > 2008) > 2 || (lRedditiSentenza495_93.Exists(x => x.AnnoReddito != dataMorteDC.Value.Year && x.AnnoReddito != decorrenzaOriginaria.Value.Year)))
                        //            {
                        //                errore = "E' possibile acquisire solo 2 record con anno pari a quello del decesso o a quello della decorrenza pensione";
                        //                return false;
                        //            }

                        //        }
                        //    }
                        //}
                        //else
                        if (provenienzaPensione.GetValueOrDefault() != 0)
                        {
                            if (decorrenzaPensioneDiretta.HasValue && decorrenzaOriginaria.HasValue)
                            {
                                if (redditiSentenza495_93.AnnoReddito.Value > decorrenzaOriginaria.Value.Year || redditiSentenza495_93.AnnoReddito.Value < decorrenzaPensioneDiretta.Value.Year)
                                {
                                    errore = "Redditi Post 2008: l'anno deve essere compreso tra la decorrenza della pensione diretta e l'anno di decorrenza originaria";
                                    return false;
                                }
                            }
                        }
                    }
                }
            }

            return true;
        }

        public static bool AGO_CI_ControlsDecorrenzaResidenzaDanteCausa(string statoEEResidenza, DateTime? decorrenzaResidenza, DateTime? dataMorteDC, DateTime? dataNascitaDC, out string messaggioVideo)
        {
            messaggioVideo = string.Empty;
            if (decorrenzaResidenza.HasValue && (string.IsNullOrEmpty(statoEEResidenza) || statoEEResidenza == "Z000"))
            {
                messaggioVideo = "La decorrenza 'Dal' non può essere acquisita.";
                return false;
            }

            if (!decorrenzaResidenza.HasValue && !string.IsNullOrEmpty(statoEEResidenza) && statoEEResidenza != "Z000")
            {
                messaggioVideo = "La decorrenza 'Dal' deve essere acquisita";
                return false;
            }

            if (decorrenzaResidenza.HasValue && dataMorteDC.HasValue && Utility.DataStrettamenteSuccessivaA(decorrenzaResidenza.Value, dataMorteDC.Value))
            {
                messaggioVideo = "La data di residenza 'Dal' è successiva alla data di morte";
                return false;
            }

            if (decorrenzaResidenza.HasValue && dataNascitaDC.HasValue && Utility.DataStrettamenteSuccessivaA(new DateTime(dataNascitaDC.Value.Year, dataNascitaDC.Value.Month, 01), decorrenzaResidenza.Value))
            {
                messaggioVideo = "La data di residenza 'Dal' è antecedente alla data di nascita";
                return false;
            }

            return true;
        }

        public static bool AGO_CI_ControlsDatiEliminazione(GestionePensione.DatiPensione datiPensione, byte? codiceEliminazione, DateTime? decorrenzaEliminazione, DateTime? dataEvento,
            DateTime? dataFineCalcoloArretrati, bool? flagProvvisoria, DateTime? dataRinunciaTrattenutaInpdap, DateTime? scadenzaRevisioneSanitaria, DateTime? decorrenzaCalcoloArretrati, bool isRiaperturaDomanda, BLCommon.GestioneDanteCausa.DatiDanteCausa danteCausa,
            out string messaggioVideo)
        {
            messaggioVideo = string.Empty;

            DateTime dataSistema = GestioneControlliDinamici.GetDataSistema(Utility.GetTipoAppartenenza(datiPensione.IndConvInt, datiPensione.Gestione));

            GestioneControlliDinamici.ControlloDinamico controlloDinamico = null;
            GestioneControlliDinamici.GetControlloDinamicoByNomeControllo("AbilitazioneMemo102", out controlloDinamico);

            #region Recupero Dati
            if (datiPensione == null)
            {
                messaggioVideo = "Dati pensione non disponibili";
                return false;
            }

            GestioneAnagrafica.DatiAnagrafici datiAnagrafici = null;
            GestioneAnagrafica.GetAnagraficaByIdPensione(datiPensione.Id, out datiAnagrafici);

            List<GestioneDecodifica.CodiceEliminazione> lstDecCodiceEliminazione;
            Utility.TipoAppartenenza? tipApp = Utility.GetTipoAppartenenza(datiPensione.IndConvInt, datiPensione.Gestione);
            GestioneDecodifica.GetCodiceEliminazioneByTipologia(out lstDecCodiceEliminazione, tipApp);
            char? codiceEliminazioneTraduzioneGP = null;
            if (codiceEliminazione.HasValue && lstDecCodiceEliminazione != null && lstDecCodiceEliminazione.Exists(x => x.Id == codiceEliminazione.ToString()))
                codiceEliminazioneTraduzioneGP = lstDecCodiceEliminazione.Find(x => x.Id == codiceEliminazione.ToString()).TraduzioneSuGP;

            #endregion Recupero Dati

            #region AGO - CI
            if (controlloDinamico != null && controlloDinamico.ValoreControllo == "SI")
            {
                if (!((Utility.IsDomandaVOCOOP_COOP28(datiPensione.SiglaCategoria) || Utility.IsDomandaVOCRED_CRED27(datiPensione.SiglaCategoria) || Utility.IsDomandaVOESO(datiPensione.SiglaCategoria) || Utility.IsDomandaVESO92(datiPensione.SiglaCategoria) ||
                Utility.IsDomandaVESO33(datiPensione.SiglaCategoria) || Utility.IsDomandaESOTEL(datiPensione.SiglaCategoria) || Utility.IsDomandaESOAMB(datiPensione.SiglaCategoria) || Utility.IsDomandaESPA(datiPensione.SiglaCategoria)) &&
                codiceEliminazioneTraduzioneGP.HasValue && codiceEliminazioneTraduzioneGP.Value == '6'))
                {
                    if (!((codiceEliminazioneTraduzioneGP.HasValue && decorrenzaEliminazione.HasValue && dataEvento.HasValue) ||
                    (!codiceEliminazioneTraduzioneGP.HasValue && !decorrenzaEliminazione.HasValue && !dataEvento.HasValue)))
                    {
                        messaggioVideo = "I dati eliminazione devono essere presenti contemporaneamente";
                        return false;
                    }
                }
            }
            else
            {
                if (!((codiceEliminazioneTraduzioneGP.HasValue && decorrenzaEliminazione.HasValue && dataEvento.HasValue) ||
                    (!codiceEliminazioneTraduzioneGP.HasValue && !decorrenzaEliminazione.HasValue && !dataEvento.HasValue)))
                {
                    messaggioVideo = "I dati eliminazione devono essere presenti contemporaneamente";
                    return false;
                }
            }

            List<char> codiciEliminazioneAmmessi = new List<char> { '1', '3', '4', 'A', 'N' };

            if (controlloDinamico != null && controlloDinamico.ValoreControllo == "SI")
            {
                if (Utility.IsDomandaVOCOOP_COOP28(datiPensione.SiglaCategoria) || Utility.IsDomandaVOCRED_CRED27(datiPensione.SiglaCategoria) || Utility.IsDomandaVOESO(datiPensione.SiglaCategoria) || Utility.IsDomandaVESO92(datiPensione.SiglaCategoria) ||
                Utility.IsDomandaVESO33(datiPensione.SiglaCategoria) || Utility.IsDomandaESOTEL(datiPensione.SiglaCategoria) || Utility.IsDomandaESOAMB(datiPensione.SiglaCategoria) || Utility.IsDomandaESPA(datiPensione.SiglaCategoria))
                {
                    codiciEliminazioneAmmessi.Remove('4');
                    codiciEliminazioneAmmessi.Remove('N');
                    if (!Utility.IsRicostituzioneOrRiapertura(datiPensione, isRiaperturaDomanda))
                    {
                        codiciEliminazioneAmmessi.Remove('A');
                        codiciEliminazioneAmmessi.Add('6');
                    }
                }
            }

            if (Utility.IsDomandaIndennitaUnaTantum_AGO(datiPensione))
                codiciEliminazioneAmmessi.Add('8');
            if (codiceEliminazioneTraduzioneGP.HasValue && !(codiciEliminazioneAmmessi.Contains(codiceEliminazioneTraduzioneGP.Value)) && !Utility.IsDomandaMIN(datiPensione.SiglaCategoria))
            {
                messaggioVideo = "Il codice eliminazione può contenere uno tra i seguenti valori: " + string.Join(", ", codiciEliminazioneAmmessi.Select(c => c.ToString()).ToArray());
                return false;
            }
            if ((Utility.IsDomandaVOCOOP_COOP28(datiPensione.SiglaCategoria) || Utility.IsDomandaVOCRED_CRED27(datiPensione.SiglaCategoria) || Utility.IsDomandaVOESO(datiPensione.SiglaCategoria) || Utility.IsDomandaVESO92(datiPensione.SiglaCategoria) ||
                Utility.IsDomandaVESO33(datiPensione.SiglaCategoria) || Utility.IsDomandaESOTEL(datiPensione.SiglaCategoria) || Utility.IsDomandaESOAMB(datiPensione.SiglaCategoria) || Utility.IsDomandaESPA(datiPensione.SiglaCategoria) ||
                Utility.IsDomandaVESO29(datiPensione.SiglaCategoria)))
            {
                if (codiceEliminazioneTraduzioneGP.HasValue && codiceEliminazioneTraduzioneGP.GetValueOrDefault() == '3')
                {
                    if (dataEvento.HasValue && (!Utility.DataSuccessivaA(dataEvento.Value, datiPensione.DecorrenzaOriginaria.Value) || dataEvento.Value.Year > dataSistema.Year || (dataEvento.Value.Year == dataSistema.Year && dataEvento.Value.Month > dataSistema.Month)))
                    {
                        messaggioVideo = "La Data Evento deve essere compresa fra la decorrenza originaria dell’assegno e la fine del mese corrente.";
                        return false;
                    }
                }
                // La Data Eliminazione Ratei (RADATAELIM) non può essere successiva 
                // alla data del Sistema
                else if (dataEvento.HasValue && Utility.DataStrettamenteSuccessivaA(dataEvento.Value, dataSistema))
                {
                    messaggioVideo = "La Data Evento non può essere successiva alla data odierna";
                    return false;
                }
            }

            if (!Utility.IsRicostituzioneOrRiapertura(datiPensione, isRiaperturaDomanda))
            {
                //La Data Decorrenza Eliminazione (RADECELIM) deve essere il mese
                //successivo alla Data Eliminazione Ratei (RADATAELIM)
                if (decorrenzaEliminazione.HasValue && dataEvento.HasValue)
                {
                    if (Utility.DataStrettamenteSuccessivaA(decorrenzaEliminazione.Value, new DateTime(dataEvento.Value.AddMonths(1).Year, dataEvento.Value.AddMonths(1).Month, 1)) ||
                        !Utility.DataSuccessivaA(decorrenzaEliminazione.Value, new DateTime(dataEvento.Value.AddMonths(1).Year, dataEvento.Value.AddMonths(1).Month, 1)))
                    {
                        messaggioVideo = "La decorrenza eliminazione deve essere pari al mese successivo alla data evento";
                        return false;
                    }
                }
            }

            if (datiAnagrafici != null && datiAnagrafici.DataMorte.HasValue)
            {
                if (codiceEliminazioneTraduzioneGP.GetValueOrDefault() == '3' && dataEvento.HasValue)
                {
                    if (Utility.DataSuccessivaA(dataEvento.Value, datiAnagrafici.DataMorte.Value))
                    {
                        messaggioVideo = string.Format("Per titolare deceduto, il codice eliminazione 3 è ammesso solo se la data evento è antecedente la data morte ({0:dd/MM/yyyy}).",
                            datiAnagrafici.DataMorte.Value);
                        return false;
                    }
                }
                else if (codiceEliminazioneTraduzioneGP.GetValueOrDefault() == '1' && dataEvento.HasValue)
                {
                    if (!dataEvento.Equals(datiAnagrafici.DataMorte))
                    {
                        messaggioVideo = "Per codice eliminazione 1, la data Evento deve essere uguale alla Data Morte";
                        return false;
                    }
                }
            }
            else
            {
                if (codiceEliminazioneTraduzioneGP.GetValueOrDefault() == '1' && !Utility.IsDomandaIndennitaUnaTantum_AGO(datiPensione))
                {
                    messaggioVideo = "Codice eliminazione 1 non ammesso per titolare vivo.";
                    return false;
                }
            }
            #endregion AGO - CI

            #region CI
            if (Utility.GetTipoAppartenenza(datiPensione.IndConvInt, datiPensione.Gestione) == Utility.TipoAppartenenza.CI)
            {
                //Se TP1ELIM (DecorrenzaEliminazione) non è posteriore a IW1DEORIG impostare MSG-ERR-TESTO con “Decorrenza eliminazione non posteriore a dec.originaria"
                if (decorrenzaEliminazione.HasValue && datiPensione.DecorrenzaOriginaria.HasValue && !Utility.DataStrettamenteSuccessivaA(decorrenzaEliminazione.Value, datiPensione.DecorrenzaOriginaria.Value))
                {
                    messaggioVideo = "Decorrenza Eliminazione non posteriore a Decorrenza Originaria";
                    return false;
                }

                //Se il valore costituito dai primi 6 caratteri di DECELIMRED (DataEvento) è antecedente a  IW1DEORIG impostare MSG-ERR-TESTO con “Data evento anteriore a dec.originaria"
                if (dataEvento.HasValue && datiPensione.DecorrenzaOriginaria.HasValue && !Utility.DataSuccessivaA(new DateTime(dataEvento.Value.Year, dataEvento.Value.Month, 1),
                    datiPensione.DecorrenzaOriginaria.Value))
                {
                    messaggioVideo = "Data Evento anteriore a Decorrenza Originaria";
                    return false;
                }
            }
            #endregion CI

            #region AGO
            if (Utility.GetTipoAppartenenza(datiPensione.IndConvInt, datiPensione.Gestione) == Utility.TipoAppartenenza.AGO)
            {
                //Se il Campo DO-NOTE è = a “SUT” si precompila obbligatoriamente il
                //Campo Codice Eliminazione (RACODELIM) = a 8 e si protegge senza altri
                //controlli
                if (datiPensione.GetFiltro() == "SUT" && (!codiceEliminazioneTraduzioneGP.HasValue || codiceEliminazioneTraduzioneGP.Value != '8'))
                {
                    messaggioVideo = "Il codice eliminazione deve essere 8";
                    return false;
                }

                //Se la Categoria (RACATEG) inizia con “V” il Campo Codice Eliminazione (RACODELIM) può contenere “1”, “3”
                //Se la Categoria (RACATEG) inizia con “S” il Campo Codice Eliminazione (RACODELIM) può contenere “1”, “3”, “4”, “N”
                if (datiPensione.SiglaCategoria.StartsWith("V") || datiPensione.SiglaCategoria.StartsWith("S"))
                {
                    List<char> listaCodiciAmmessi = datiPensione.SiglaCategoria.StartsWith("V") ? new List<char> { '1', '3' } : (datiPensione.SiglaCategoria.StartsWith("S") ? new List<char> { '1', '3', '4', 'N' } : null);

                    if (controlloDinamico != null && controlloDinamico.ValoreControllo == "SI")
                    {
                        if (Utility.IsDomandaVOCOOP_COOP28(datiPensione.SiglaCategoria) || Utility.IsDomandaVOCRED_CRED27(datiPensione.SiglaCategoria) || Utility.IsDomandaVOESO(datiPensione.SiglaCategoria) || Utility.IsDomandaVESO92(datiPensione.SiglaCategoria) ||
                        Utility.IsDomandaVESO33(datiPensione.SiglaCategoria) || Utility.IsDomandaESOTEL(datiPensione.SiglaCategoria) || Utility.IsDomandaESOAMB(datiPensione.SiglaCategoria) || Utility.IsDomandaESPA(datiPensione.SiglaCategoria))
                        {
                            if (Utility.IsRicostituzioneOrRiapertura(datiPensione, isRiaperturaDomanda))
                                listaCodiciAmmessi.Add('A');
                            else
                                listaCodiciAmmessi.Add('6');
                        }
                    }

                    if (Utility.IsDomandaIndennitaUnaTantum_AGO(datiPensione))
                        listaCodiciAmmessi.Add('8');
                    if (codiceEliminazioneTraduzioneGP.HasValue && listaCodiciAmmessi != null && !listaCodiciAmmessi.Contains(codiceEliminazioneTraduzioneGP.GetValueOrDefault()) && !Utility.IsDomandaMIN(datiPensione.SiglaCategoria))
                    {
                        messaggioVideo = string.Format("Il codice eliminazione può contenere uno tra i seguenti valori:  {0}", string.Join(", ", listaCodiciAmmessi.Select(x => x.ToString()).ToArray()));
                        return false;
                    }
                }

                //Se il Campo Codice Eliminazione (RACODELIM) è = a “1” la Data
                //Eliminazione Ratei (RADATAELIM) non può essere antecedente alla Data
                //Domanda (RAUE24)
                if (codiceEliminazioneTraduzioneGP.HasValue && codiceEliminazioneTraduzioneGP.Value == '1')
                {
                    if (dataEvento.HasValue && !Utility.DataSuccessivaA(dataEvento.Value, datiPensione.DecorrenzaOriginaria.Value))
                    {
                        messaggioVideo = "La data evento non può essere antecedente alla decorrenza originaria";
                        return false;
                    }
                }

                ////La Data Decorrenza Eliminazione (RADECELIM) deve essere pari o minore
                ////al 1°giorno del mese successivo alla Data del Sistema
                //if (decorrenzaEliminazione.HasValue && Utility.DataStrettamenteSuccessivaA(decorrenzaEliminazione.Value, new DateTime(dataSistema.AddMonths(1).Year, dataSistema.AddMonths(1).Month, 1)))
                //{
                //    messaggioVideo = "La decorrenza eliminazione deve essere pari o minore al 1° giorno del mese successivo alla data odierna";
                //    return false;
                //}

                if (Utility.IsRicostituzioneOrRiapertura(datiPensione, isRiaperturaDomanda) && dataEvento.HasValue &&
                    Utility.DataStrettamenteSuccessivaA(dataEvento.Value, Utility.FirstDayOfMonth(dataSistema.AddMonths(2))))
                {
                    messaggioVideo = "La data evento deve essere pari o minore al 1° giorno del secondo mese successivo alla data odierna";
                    return false;
                }

                //Se la Categoria (RACATEG) è = a “INDCOM”e se il Soggetto ha compiuto 65
                //anni se maschio, 60 anni se femmina prima della Data del Sistema oppure lo
                //compirà dopo il 2020
                if (datiPensione.SiglaCategoria == "INDCOM")
                {
                    if (datiAnagrafici != null && datiAnagrafici.Sesso.HasValue)
                    {
                        if ((datiAnagrafici.Sesso.Value == 'M' &&
                            (!Utility.DataStrettamenteSuccessivaA(datiAnagrafici.DataNascita.Value.AddYears(65), dataSistema) ||
                            Utility.DataStrettamenteSuccessivaA(datiAnagrafici.DataNascita.Value.AddYears(65), new DateTime(2020, 12, 31))))
                            || (datiAnagrafici.Sesso.Value == 'F' &&
                            (!Utility.DataStrettamenteSuccessivaA(datiAnagrafici.DataNascita.Value.AddYears(60), dataSistema) ||
                            Utility.DataStrettamenteSuccessivaA(datiAnagrafici.DataNascita.Value.AddYears(60), new DateTime(2020, 12, 31)))))
                        {
                            //il Codice Eliminazione (RACODELIM) deve essere
                            //acquisito
                            if (!codiceEliminazioneTraduzioneGP.HasValue)
                            {
                                messaggioVideo = "Il codice eliminazione deve essere acquisito";
                                return false;
                            }

                            //il Codice Eliminazione (RACODELIM) può contenere 1 o 3
                            if (codiceEliminazioneTraduzioneGP.HasValue && codiceEliminazioneTraduzioneGP.Value != '1' && codiceEliminazioneTraduzioneGP.Value != '3')
                            {
                                messaggioVideo = "Il codice eliminazione può contenere 1 o 3";
                                return false;
                            }

                            //la Data Eliminazione Ratei (RADATAELIM) viene precompilata con la
                            //data del compimento dell'età che può essere variata ma comunque
                            //non inferiore alla Data del Sistema
                            if (dataEvento.HasValue && !Utility.DataSuccessivaA(dataEvento.Value, dataSistema))
                            {
                                messaggioVideo = "La data evento non può essere inferiore alla data odierna";
                                return false;
                            }

                            //la Data Decorrenza Eliminazione (RADECELIM) non può essere
                            //inferiore al 1° maggio 1996 e non superiore al 2020
                            if (decorrenzaEliminazione.HasValue && (!Utility.DataSuccessivaA(decorrenzaEliminazione.Value, new DateTime(1996, 05, 01)) ||
                                Utility.DataStrettamenteSuccessivaA(decorrenzaEliminazione.Value, new DateTime(2020, 12, 31))))
                            {
                                messaggioVideo = "La decorrenza eliminazione non può essere inferiore al 1° maggio 1996 e non superiore al 2020";
                                return false;
                            }

                            //la Data Decorrenza Eliminazione (RADECELIM) deve essere pari o
                            //maggiore al mese successivo al compimento del 57° anno per le
                            //femmine e 62° per i maschi e non superiore al compimento del 60°
                            //anno di età per le femmine e il 65° anno per i maschi e comunque non
                            //oltre il 2020
                            if (decorrenzaEliminazione.HasValue)
                            {
                                DateTime dataRif = new DateTime();
                                if (datiAnagrafici.Sesso.Value == 'M')
                                {
                                    dataRif = new DateTime(datiAnagrafici.DataNascita.Value.AddYears(62).AddMonths(1).Year,
                                    datiAnagrafici.DataNascita.Value.AddYears(62).AddMonths(1).Month, 1);
                                    if (!Utility.DataSuccessivaA(decorrenzaEliminazione.Value, dataRif))
                                    {
                                        messaggioVideo = "La decorrenza eliminazione non può essere inferiore alla data di compimento del 62° anno di età maggiorata di un mese";
                                        return false;
                                    }
                                    dataRif = new DateTime(datiAnagrafici.DataNascita.Value.AddYears(65).Year,
                                    datiAnagrafici.DataNascita.Value.AddYears(65).Month, 1);
                                    if (Utility.DataStrettamenteSuccessivaA(decorrenzaEliminazione.Value, dataRif))
                                    {
                                        messaggioVideo = "La decorrenza eliminazione non può essere superiore alla data di compimento del 65° anno di età";
                                        return false;
                                    }
                                }
                                else if (datiAnagrafici.Sesso.Value == 'F')
                                {
                                    dataRif = new DateTime(datiAnagrafici.DataNascita.Value.AddYears(57).AddMonths(1).Year,
                                    datiAnagrafici.DataNascita.Value.AddYears(57).AddMonths(1).Month, 1);
                                    if (!Utility.DataSuccessivaA(decorrenzaEliminazione.Value, dataRif))
                                    {
                                        messaggioVideo = "La decorrenza eliminazione non può essere inferiore alla data di compimento del 57° anno di età maggiorata di un mese";
                                        return false;
                                    }
                                    dataRif = new DateTime(datiAnagrafici.DataNascita.Value.AddYears(60).Year,
                                    datiAnagrafici.DataNascita.Value.AddYears(60).Month, 1);
                                    if (Utility.DataStrettamenteSuccessivaA(decorrenzaEliminazione.Value, dataRif))
                                    {
                                        messaggioVideo = "La decorrenza eliminazione non può essere superiore alla data di compimento del 60° anno di età";
                                        return false;
                                    }
                                }
                                dataRif = new DateTime(2020, 12, 31);
                                if (Utility.DataStrettamenteSuccessivaA(decorrenzaEliminazione.Value, dataRif))
                                {
                                    messaggioVideo = "La decorrenza eliminazione non può essere superiore al 2020";
                                    return false;
                                }
                            }
                        }
                    }
                }

                if (Utility.IsDomandaIndennitaUnaTantum_AGO(datiPensione))
                {
                    if (DateTime.Compare(datiPensione.DecorrenzaOriginaria.Value, decorrenzaEliminazione.Value.AddMonths(-1)) != 0)
                    {
                        messaggioVideo = "La “Decorrenza Originaria” deve essere il mese precedente la “Decorrenza Eliminazione”";
                        return false;
                    }
                }

                if (!Utility.IsRicostituzioneOrRiaperturaAGOAbilitata(datiPensione, isRiaperturaDomanda) && !datiPensione.SiglaCategoria.StartsWith("V")
                    && !Utility.IsDomandaIOTOT(datiPensione.SiglaCategoria) && !Utility.IsDomandaIOCUM(datiPensione.SiglaCategoria)//ENG - Bypassare controllo per IOTOT/IOCUM
                    && !(Utility.IsRicostituzioneOrRiapertura(datiPensione, isRiaperturaDomanda) && (datiPensione.SiglaCategoria.Trim() == "IOSPETT" || datiPensione.SiglaCategoria.Trim() == "IOSPORT")))
                {
                    //La Data (RAU112) non può essere superiore alla Decorrenza Eliminazione
                    //(RADECELIM) quando presente
                    if (decorrenzaEliminazione.HasValue && scadenzaRevisioneSanitaria.HasValue)
                    {
                        if (Utility.DataStrettamenteSuccessivaA(scadenzaRevisioneSanitaria.Value, decorrenzaEliminazione.Value))
                        {
                            messaggioVideo = "La scadenza revisione sanitaria non può essere superiore alla decorrenza eliminazione";
                            return false;
                        }
                    }
                }

                //La Data Decorrenza Trattenuta INPDAP (GP1AN87D) non può essere
                //superiore alla Data Decorrenza Eliminazione (RADECELIM) quando
                //presente
                if (decorrenzaEliminazione.HasValue && dataRinunciaTrattenutaInpdap.HasValue)
                {
                    if (Utility.DataStrettamenteSuccessivaA(dataRinunciaTrattenutaInpdap.Value, decorrenzaEliminazione.Value))
                    {
                        messaggioVideo = "La decorrenza trattenuta Fondo Credito non può essere superiore alla decorrenza eliminazione";
                        return false;
                    }
                }

                //La Data fine calcolo arretrati (GP1AP2Z) è un campo obbligatorio
                if (Utility.GetTipoDomanda(datiPensione.Gruppo, datiPensione.Prodotto) == Utility.TipoDomanda.Ricostituzione && !dataFineCalcoloArretrati.HasValue)
                {
                    messaggioVideo = "La Decorrenza Fine Calcolo Arretrati è un campo obbligatorio";
                    return false;
                }

                //La Data fine calcolo arretrati (GP1AP2Z) per codice eliminazione diverso da morte (1) non può essere antecedente 
                //alla decorrenza arretrati (GP1AT03Z) o posteriore/uguale alla decorrenza eliminazione (GP1AM02Z)
                if (codiceEliminazioneTraduzioneGP.HasValue && codiceEliminazioneTraduzioneGP.Value != '1')
                {
                    if ((decorrenzaCalcoloArretrati.HasValue && dataFineCalcoloArretrati.HasValue && Utility.DataStrettamenteSuccessivaA(decorrenzaCalcoloArretrati.Value, dataFineCalcoloArretrati.Value)) ||
                        (decorrenzaEliminazione.HasValue && dataFineCalcoloArretrati.HasValue && Utility.DataSuccessivaA(dataFineCalcoloArretrati.Value, decorrenzaEliminazione.Value)))
                    {
                        messaggioVideo = "La Decorrenza Fine Calcolo Arretrati deve essere successiva o uguale alla Decorrenza Arretrati " +
                            (decorrenzaCalcoloArretrati.HasValue ? string.Format("{0:(MM/yyyy)}", decorrenzaCalcoloArretrati.Value) : string.Empty) +
                            " e antecedente alla Decorrenza Eliminazione";
                        return false;
                    }
                }

                //ENG - Spacchettate SOPGI
                if ((Utility.IsDomandaENPALS(datiPensione.Gestione) && Utility.IsDomandaPensioneSuperstitiOrRicostituzione(datiPensione))
                    || Utility.IsDomandaSpacchettamentoSOPGIPost072022(datiPensione, danteCausa) || Utility.IsDomandaSpacchettamentoSO(datiPensione, isRiaperturaDomanda) || Utility.IsDomandaSpacchettamentoSOART(datiPensione, isRiaperturaDomanda) ||
                    Utility.IsDomandaSpacchettamentoSOCOM(datiPensione, isRiaperturaDomanda) || Utility.IsDomandaSpacchettamentoSR(datiPensione, isRiaperturaDomanda))
                {
                    List<GestioneAventiDiritto.AventiDiritto> listaAventiDiritto = null;
                    GestioneAventiDiritto.GetAventiDirittoByIdPensione(datiPensione.Id, out listaAventiDiritto);
                    if (listaAventiDiritto != null && listaAventiDiritto.Count > 0 && listaAventiDiritto.Exists(x => x.IdAnagrafica == datiAnagrafici.Id))
                    {
                        List<GestionePeriodiAventiDiritto.PeriodoAventiDiritto> listaPeriodi = null;
                        GestionePeriodiAventiDiritto.GetPeriodiAventiDiritto(datiPensione.Id, listaAventiDiritto.FirstOrDefault(x => x.IdAnagrafica == datiAnagrafici.Id).Id, out listaPeriodi);
                        if (listaPeriodi != null && listaPeriodi.Count > 0)
                        {
                            GestionePeriodiAventiDiritto.PeriodoAventiDiritto ultimoPeriodo = listaPeriodi.OrderBy(x => x.CessazionePeriodo).Last();
                            if (ultimoPeriodo != null && ultimoPeriodo.CessazionePeriodo.HasValue && decorrenzaEliminazione.HasValue &&
                                decorrenzaEliminazione.Value.Date != ultimoPeriodo.CessazionePeriodo.Value.Date)
                            {
                                messaggioVideo = string.Format("La Decorrenza Eliminazione deve essere uguale alla cessazione dell'ultimo periodo inserito nel quadro Periodi ({0}).", ultimoPeriodo.CessazionePeriodo.Value.ToString("MM/yyyy"));
                                return false;
                            }
                        }
                    }
                }
            }
            #endregion AGO

            return true;
        }

        public static bool ALL_ControlsDecorrenzaOriginariaPerIndirette(DateTime? decorrenzaOrig, string codiceFiscaleTitolare, DateTime? dataNascitaTitolare, DateTime? dataMorteDanteCausa, List<GestioneFamiliari.Familiare> lstFamiliari, GestionePensione.DatiPensione datiPensione, BLCommon.GestioneDanteCausa.DatiDanteCausa datiDanteCausa, List<GestioneFamiliari.CodMaggFamiliari> listaCodMaggFamiliari, out string messaggio)
        {
            messaggio = string.Empty;

            if (lstFamiliari == null || lstFamiliari.Count == 0)
                return true;
            if (dataMorteDanteCausa == null || dataNascitaTitolare == null)
                return true;
            GestioneFamiliari.Familiare titolare = lstFamiliari.FirstOrDefault(f => f.CodiceFiscale == codiceFiscaleTitolare);
            if (titolare == null)
                return true;

            Utility.TipoAppartenenza? tipoAppartenenza = Utility.GetTipoAppartenenza(datiPensione.IndConvInt, datiPensione.Gestione);
            Utility.TipoFondo? tipoFondo = Utility.GetTipoFondoByCategoria(tipoAppartenenza, datiPensione.SiglaCategoria);

            //ENG - RIC REVERSIBILITA 024: implementazione flusso per riconoscere le reversibilità "vecchie" 
            GestioneLavorazione.DatiLavorazione datiLavorazione = null;
            GestioneLavorazione.GetLavorazioneByIdPensione(datiPensione.Id, out datiLavorazione);

            if (dataNascitaTitolare > dataMorteDanteCausa)
            {
                //figli postumi
                if (dataNascitaTitolare > dataMorteDanteCausa.Value.AddDays(300) && !(tipoAppartenenza.HasValue && tipoAppartenenza == Utility.TipoAppartenenza.AGO && GestioneBypassControllo.CheckBypassControlloByNomeBypass(datiPensione, GestioneBypassControllo.NomeBypass.Titolare_Anagrafica_AGO.TITOLARE_NATO_DOPO_300_GIORNI)))
                {
                    messaggio = "Pensione non lavorabile. Titolare nato più di 300 giorni dopo la data di morte del dante causa ";
                    return false;
                }
                if (decorrenzaOrig.Value.Month != dataNascitaTitolare.Value.AddMonths(1).Month || decorrenzaOrig.Value.Year != dataNascitaTitolare.Value.AddMonths(1).Year)
                {
                    bool isContitolareNonCessatoNatoPrimaDellaDecPensione = false;
                    if (tipoAppartenenza == Utility.TipoAppartenenza.AGO && Utility.IsRicostituzione_VariazioneDatiContitolari(datiPensione))
                    {
                        foreach (GestioneFamiliari.Familiare fam in lstFamiliari)
                        {
                            GestioneAnagrafica.DatiAnagrafici datiAnagrafici = null;
                            GestioneAnagrafica.GetAnagraficaByIdAnagrafica(fam.IdAnagrafica, out datiAnagrafici);

                            if (listaCodMaggFamiliari != null && listaCodMaggFamiliari.Count() > 0)
                            {
                                List<GestioneFamiliari.CodMaggFamiliari> LcodMaggFam = listaCodMaggFamiliari.FindAll(x => x.IdAnagrafica == fam.IdAnagrafica).OrderBy(x => x.Decorrenza).ToList();
                                if (LcodMaggFam != null && LcodMaggFam.Count > 0)
                                {
                                    foreach (GestioneFamiliari.CodMaggFamiliari c in LcodMaggFam)
                                    {
                                        if (c.Cessazione.HasValue && Utility.DataStrettamenteSuccessivaA(c.Cessazione.Value, Utility.DataSistemaAgo) &&
                                           datiAnagrafici != null && datiAnagrafici.DataNascita.HasValue && !Utility.DataStrettamenteSuccessivaA(datiAnagrafici.DataNascita.Value, decorrenzaOrig.Value))
                                            isContitolareNonCessatoNatoPrimaDellaDecPensione = true;
                                    }
                                }
                            }
                        }
                    }

                    if (!(tipoAppartenenza == Utility.TipoAppartenenza.AGO && Utility.IsRicostituzione_VariazioneDatiContitolari(datiPensione) && titolare.FlagTitolare.HasValue && !titolare.FlagTitolare.Value) &&
                        !(titolare.FlagTitolare.HasValue && titolare.FlagTitolare.Value && dataNascitaTitolare.GetValueOrDefault() > decorrenzaOrig.GetValueOrDefault() && isContitolareNonCessatoNatoPrimaDellaDecPensione))
                    {
                        messaggio = "La decorrenza pensione deve essere uguale al mese successivo alla data di nascita del titolare (" + dataNascitaTitolare.Value.ToString("MM/yyyy") + ")";
                        return false;
                    }
                }
            }
            else
            {
                //ENG - RIC/TRF SUPERSTITI 024: blocco per Ante Settembre 95
                if (decorrenzaOrig.HasValue && Utility.IsRicostituzioneOrRiapertura(datiPensione, Utility.IsRiaperturaDomanda(datiPensione.Id))
                    && Utility.IsDomandaPensioneSuperstitiOrRicostituzione(datiPensione)
                    && (tipoFondo == Utility.TipoFondo.PT || tipoFondo == Utility.TipoFondo.FS) && !Utility.DataSuccessivaA(decorrenzaOrig.Value, new DateTime(1995, 9, 1)))
                {
                    DateTime dataCompare = dataMorteDanteCausa.Value.AddDays(1);
                    if (!GestioneBypassControllo.CheckAndLockBypassControlloByNomeBypass(datiPensione, GestioneBypassControllo.NomeBypass.Titolare_Anagrafica_AGO.DECORRENZA_SUPERSTITI) &&
                        (Utility.DataStrettamenteSuccessivaA(decorrenzaOrig.Value, dataCompare) || !Utility.DataSuccessivaA(decorrenzaOrig.Value, dataCompare)))
                    {
                        bool eseguiControlloDecorrenzaPerMemoAlbania = true;
                        eseguiControlloDecorrenzaPerMemoAlbania = ControlloEsecuzioneControlliDecorrenzaMemoAlbania(datiPensione, datiDanteCausa);

                        //if (eseguiControlloDecorrenzaPerMemoAlbania)
                            //ENG - Se è una Reversibilita continua a scattare il controllo. Se la domanda è una indiretta 024 ante settembre 1995, prima di far scattare il controllo bisogna verificare se la decorrenza è uguale al 
                            //mese successivo alla morte del Dante Causa. Se è vero, allora il controllo non deve scattare
                            if (Utility.IsDomandaReversibilitaOrRicostituzione(datiPensione, datiDanteCausa, datiLavorazione) ||
                                (Utility.isDomandaRicSuperstitiIndiretta024AnteSettembre1995(datiPensione, datiDanteCausa, datiLavorazione, Utility.IsRiaperturaDomanda(datiPensione.Id)) &&
                                 (decorrenzaOrig.Value.Month != dataMorteDanteCausa.Value.AddMonths(1).Month || decorrenzaOrig.Value.Year != dataMorteDanteCausa.Value.AddMonths(1).Year)))
                            {
                                messaggio = "La decorrenza deve essere il giorno successivo alla data morte del dante causa (data morte: " + dataMorteDanteCausa.Value.ToString("dd/MM/yyyy") + ")";
                                return false;
                            }
                    }
                }
                else {

                    if (!(Utility.IsDomandaBancRicAnte1991(datiPensione, datiDanteCausa) && Utility.IsDomandaSOBANC(datiPensione.SiglaCategoria)) && Utility.isAnte96Prestabilita(datiPensione, datiDanteCausa) == null)
                    {
                        bool eseguiControlloDecorrenzaPerMemoAlbania = true;
                        eseguiControlloDecorrenzaPerMemoAlbania = ControlloEsecuzioneControlliDecorrenzaMemoAlbania(datiPensione, datiDanteCausa);

                        //superstiti normali
                        //If esterno dovuto a causa del Memo Albania
                        //if (eseguiControlloDecorrenzaPerMemoAlbania)
                            if (!GestioneBypassControllo.CheckAndLockBypassControlloByNomeBypass(datiPensione, GestioneBypassControllo.NomeBypass.Titolare_Anagrafica_AGO.DECORRENZA_SUPERSTITI) &&
                                (decorrenzaOrig.Value.Month != dataMorteDanteCausa.Value.AddMonths(1).Month || decorrenzaOrig.Value.Year != dataMorteDanteCausa.Value.AddMonths(1).Year))
                            {
                                messaggio = "La decorrenza pensione deve essere uguale al mese successivo alla morte del dante causa (data morte: " + dataMorteDanteCausa.Value.ToString("MM/yyyy") + ").";
                                return false;
                            }
                    }
                }
            }
            return true;
        }

        /// <summary>
        /// Verifica se la decorrenza originaria è posteriore alla data morte del titolare
