        }

        public static bool AGO_CI_ControlsTipoBeneficioWithCodNatura(string tipoBeneficio, string naturaPensione, bool isInvioAlCalcolo, out string messaggioVideo)
        {
            messaggioVideo = string.Empty;

            if (isInvioAlCalcolo || !string.IsNullOrEmpty(tipoBeneficio))
            {
                if (!string.IsNullOrEmpty(naturaPensione) && naturaPensione.Length == 3 && naturaPensione[2] == 'G' && tipoBeneficio != "08")
