                    messaggioVideo = "E' obbligatorio inserire il codice beneficio pari a 8 per il terzo codice natura G.";
                    return false;
                }
            }

            return true;
        }

        public static bool AGO_CI_ControlsConfermaInvalidita(GestionePensione.DatiPensione datiPensione, DateTime? dataEventoEliminazione, byte? nRiconoscimentiInvalidita, DateTime dataSistema,
             bool isRiaperturaDomanda, out string messaggioVideo)
        {
            messaggioVideo = string.Empty;
            Utility.TipoAppartenenza? tipoAppartenenza = Utility.GetTipoAppartenenza(datiPensione.IndConvInt, datiPensione.Gestione);

            if ((datiPensione.Gruppo == "0002" && datiPensione.Prodotto == "0011" && !isRiaperturaDomanda && !Utility.IsDomandaSPED(datiPensione)) ||
                (datiPensione.Gruppo == "0051" && (datiPensione.Prodotto == "0321" || datiPensione.Prodotto == "0322") && datiPensione.Tipo == "0023"))
            {
                // Il termine primo giorno del mese successivo alla data odierna si riferisce all'anno di competenza INPS e non all'anno solare,
                // quindi se è già scattato il nuovo anno di competenza, se l'anno solare è ancora il precedente allora il primo giorno del mese 
                // successivo è il primo Febbraio dell'anno di competenza
                int annoCompetenza = 0;
                GestioneControlliDinamici.GetAnnoCompetenza(tipoAppartenenza, out annoCompetenza);
                DateTime primoGiornoDelMeseSuccessivo = dataSistema.Year != annoCompetenza ? new DateTime(annoCompetenza, 2, 1) : Utility.FirstDayOfMonth(dataSistema.AddMonths(1));

                Utility.DifferenzaDateTime differenza;
                if (dataEventoEliminazione.HasValue && datiPensione.DecorrenzaOriginaria.HasValue) // domande eliminate
                    differenza = Utility.DifferenzaBetweenDate(dataEventoEliminazione, datiPensione.DecorrenzaOriginaria, tipoAppartenenza);
                else // domande non eliminate
                    differenza = Utility.DifferenzaBetweenDate(primoGiornoDelMeseSuccessivo, datiPensione.DecorrenzaOriginaria, tipoAppartenenza);

                // Per le domande eliminate l'intervallo è [0, 3] 
                // Per le domande non eliminate l'intervallo è [0, 3)
                if ((dataEventoEliminazione.HasValue && differenza <= (new Utility.DifferenzaDateTime(3, 0, 0)) && nRiconoscimentiInvalidita.HasValue) ||
                    (!dataEventoEliminazione.HasValue && differenza < (new Utility.DifferenzaDateTime(3, 0, 0)) && nRiconoscimentiInvalidita.HasValue))
                {
                    messaggioVideo = "Conferma Invalidità non deve essere selezionato";
                    return false;
                }

                // Per le domande eliminate l'intervallo è (3, 6] 
                // Per le domande non eliminate l'intervallo è [3, 6)
                if ((dataEventoEliminazione.HasValue && differenza > (new Utility.DifferenzaDateTime(3, 0, 0)) && differenza <= (new Utility.DifferenzaDateTime(6, 0, 0)) && nRiconoscimentiInvalidita.HasValue && nRiconoscimentiInvalidita.Value != 2) ||
                    (!dataEventoEliminazione.HasValue && differenza >= (new Utility.DifferenzaDateTime(3, 0, 0)) && differenza < (new Utility.DifferenzaDateTime(6, 0, 0)) && nRiconoscimentiInvalidita.HasValue && nRiconoscimentiInvalidita.Value != 2))
                {
                    messaggioVideo = "Conferma Invalidità può essere solo vuoto o 2";
                    return false;
                }

                // Per le domande eliminate l'intervallo è (6, inf) 
                // Per le domande non eliminate l'intervallo è [6, inf)
                if ((dataEventoEliminazione.HasValue && differenza > (new Utility.DifferenzaDateTime(6, 0, 0)) && nRiconoscimentiInvalidita.HasValue && nRiconoscimentiInvalidita.Value != 2 && nRiconoscimentiInvalidita.Value != 3) ||
                    (!dataEventoEliminazione.HasValue && differenza >= (new Utility.DifferenzaDateTime(6, 0, 0)) && nRiconoscimentiInvalidita.HasValue && nRiconoscimentiInvalidita.Value != 2 && nRiconoscimentiInvalidita.Value != 3))
                {
                    messaggioVideo = "Conferma Invalidità può essere solo vuoto o 2 o 3";
                    return false;
                }
            }

            return true;
        }

        public static bool AGO_CI_ControlsEliminazioneConfermaInvalidita(GestionePensione.DatiPensione datiPensione, DateTime? dataEventoEliminazione, byte? nRiconoscimentiInvalidita,
            DateTime dataSistema, bool isRiaperturaDomanda, out string messaggioVideo)
        {
            messaggioVideo = string.Empty;
            Utility.TipoAppartenenza? tipoAppartenenza = Utility.GetTipoAppartenenza(datiPensione.IndConvInt, datiPensione.Gestione);

            if ((datiPensione.Gruppo == "0002" && datiPensione.Prodotto == "0011" && !isRiaperturaDomanda && !Utility.IsDomandaSPED(datiPensione)) || (datiPensione.Gruppo == "0051" && datiPensione.Prodotto == "0322" && datiPensione.Tipo == "0023"))
            {
                // Il termine primo giorno del mese successivo alla data odierna si riferisce all'anno di competenza INPS e non all'anno solare,
                // quindi se è già scattato il nuovo anno di competenza, se l'anno solare è ancora il precedente allora il primo giorno del mese 
                // successivo è il primo Febbraio dell'anno di competenza
                int annoCompetenza = 0;
                GestioneControlliDinamici.GetAnnoCompetenza(tipoAppartenenza, out annoCompetenza);
                DateTime primoGiornoDelMeseSuccessivo = dataSistema.Year != annoCompetenza ? new DateTime(annoCompetenza, 2, 1) : Utility.FirstDayOfMonth(dataSistema.AddMonths(1));

                Utility.DifferenzaDateTime differenza;
                if (dataEventoEliminazione.HasValue && datiPensione.DecorrenzaOriginaria.HasValue) // domande eliminate
                    differenza = Utility.DifferenzaBetweenDate(dataEventoEliminazione, datiPensione.DecorrenzaOriginaria, tipoAppartenenza);
                else // domande non eliminate
                    differenza = Utility.DifferenzaBetweenDate(primoGiornoDelMeseSuccessivo, datiPensione.DecorrenzaOriginaria, tipoAppartenenza);

                // Per le domande eliminate l'intervallo è (3, 6] 
                // Per le domande non eliminate l'intervallo è [3, 6)
                if ((dataEventoEliminazione.HasValue && differenza > (new Utility.DifferenzaDateTime(3, 0, 0)) && differenza <= (new Utility.DifferenzaDateTime(6, 0, 0)) && !nRiconoscimentiInvalidita.HasValue) ||
                    (!dataEventoEliminazione.HasValue && differenza >= (new Utility.DifferenzaDateTime(3, 0, 0)) && differenza < (new Utility.DifferenzaDateTime(6, 0, 0)) && !nRiconoscimentiInvalidita.HasValue))
                {
                    messaggioVideo = "E' obbligatorio inserire la conferma invalidità pari a 2 oppure una data evento eliminazione minore o uguale al " +
                        String.Format("{0:MM/yyyy}", datiPensione.DecorrenzaOriginaria.Value.AddYears(3));
                    return false;
                }

                // Per le domande eliminate l'intervallo è (6, inf) 
                // Per le domande non eliminate l'intervallo è [6, inf)
                if ((dataEventoEliminazione.HasValue && differenza > (new Utility.DifferenzaDateTime(6, 0, 0)) && (!nRiconoscimentiInvalidita.HasValue || nRiconoscimentiInvalidita.Value == 2)) ||
                    (!dataEventoEliminazione.HasValue && differenza >= (new Utility.DifferenzaDateTime(6, 0, 0)) && (!nRiconoscimentiInvalidita.HasValue || nRiconoscimentiInvalidita.Value == 2)))
                {
                    messaggioVideo = "E' obbligatorio inserire la conferma invalidità pari a 3 oppure una data evento eliminazione minore o uguale al " +
                        (!nRiconoscimentiInvalidita.HasValue ? String.Format("{0:MM/yyyy}", datiPensione.DecorrenzaOriginaria.Value.AddYears(3)) :
                        String.Format("{0:MM/yyyy}", datiPensione.DecorrenzaOriginaria.Value.AddYears(6)));
                    return false;
                }
            }
            return true;
        }

        public static bool IsLavoratriceDipendente(int catNumerica, Utility.TipoAppartenenza? tipoAppartenenza, GestionePensione.DatiPensione datiPensione)
        {
            if (catNumerica == 1 || catNumerica == 4 || catNumerica == 82 || tipoAppartenenza == Utility.TipoAppartenenza.FS || Utility.IsDomandaENPALS(datiPensione.Gestione))
                return true;

            return false;
        }

        public static bool AGO_ControlsCodiceLiquidazioneWithTipoCalcolo(DatiSupplementi supp, Utility.TipoCalcolo tipoCalcolo, out string messaggioVideo)
        {
            messaggioVideo = string.Empty;
            if (supp.TipoSupplemento.HasValue && supp.TipoSupplemento.Value == 'C')
            {
                //Il codice liquidazione C = 3 è ammesso solo se il tipo di calcolo è MISTO o CONTRIBUTIVO
                if (supp.CodiceLiquidazione == 3 && (tipoCalcolo != Utility.TipoCalcolo.Contributivo && tipoCalcolo != Utility.TipoCalcolo.Misto))
                {
                    messaggioVideo = "Per i supplementi contributivi il 'Codice Tipo Liquidazione' uguale a 'C' è ammesso solo per tipo calcolo 'MISTO' o 'CONTRIBUTIVO'.";
                    return false;

                }
            }
            if (supp.TipoSupplemento.HasValue && supp.TipoSupplemento.Value == 'R')
            {
                //I supplementi retributivi sono ammessi solo se il tipo di calcolo è MISTO o RETRIBUTIVO 
                if (tipoCalcolo != Utility.TipoCalcolo.Misto && tipoCalcolo != Utility.TipoCalcolo.Retributivo && tipoCalcolo != Utility.TipoCalcolo.RetributivoMonti)
                {
                    messaggioVideo = "I supplementi retributivi sono ammessi solo per tipo calcolo 'RETRIBUTIVO' o 'MISTO'.";
                    return false;
                }
            }
            return true;
        }

        public static bool AGO_CI_ControlsCodiceLiquidazioneForContributivo(DatiSupplementi supp, out string messaggioVideo)
        {
            messaggioVideo = string.Empty;
            if (supp.TipoSupplemento.HasValue && supp.TipoSupplemento.Value == 'C')
            {
                //Se il tipo supplemento è di tipo contributivo il codice tipo liquidazione deve essere C o D
                if (supp.CodiceLiquidazione != 3 && supp.CodiceLiquidazione != 4)
                {
                    messaggioVideo = "Per i supplementi contributivi il 'Codice Tipo Liquidazione' è un campo obbligatorio.";
                    return false;
                }
            }
            return true;
        }

        public static bool ALL_ControlsDecorrenzaMaggiorazioneWithDataPresentazione(DateTime? decorrenzaMaggiorazione, GestionePensione.DatiPensione datiPensione, DateTime? dataNascitaTitolare,
            bool IsDecorrenzaMaggiorazioneFromPrelievo, GestioneDanteCausa.DatiDanteCausa datiDanteCausa, bool isRiaperturaDomanda, out string messaggioVideo)
        {
            messaggioVideo = string.Empty;
            bool ret = true;

            if (!IsDecorrenzaMaggiorazioneFromPrelievo && decorrenzaMaggiorazione.HasValue)
            {
                string siglaCategoria = datiPensione.SiglaCategoria.Trim();
                char codNat1 = ' ';
                char codNat2 = ' ';
                char codNat3 = ' ';
                Utility.GetCodiciNatura(datiPensione.NaturaPensione, out codNat1, out codNat2, out codNat3);
                GestioneControlliDinamici.ControlloDinamico ctrl = null;
                GestioneControlliDinamici.GetControlloDinamicoByNomeControllo("AbilitazioneControlliMemo72", out ctrl);

                bool isControlloMemo72 = false;
                Utility.TipoAppartenenza? tipoAppartenenza = Utility.GetTipoAppartenenza(datiPensione.IndConvInt, datiPensione.Gestione);

                //Memo 72
                switch (tipoAppartenenza)
                {
                    case Utility.TipoAppartenenza.AGO:
                        //categorie IR, IOART, IOCOM, IOTOT, IDAI, IOCUM, IOP, IOBANC, IO, IOSPETT, IOSPORT con decorrenza maggiore di 31/07/1984,
                        //primo byte codice natura uguale a 1, 2, 3 o 4 e decorrenza maggiorazione sociale maggiore di 31/07/2020 e età titolare < 60
                        isControlloMemo72 = ((siglaCategoria == "IDAI" || siglaCategoria == "IR" || siglaCategoria == "IOART" || siglaCategoria == "IOCOM" || siglaCategoria == "IOTOT" || siglaCategoria == "IOCUM" ||
                                            siglaCategoria == "IOP" || siglaCategoria == "IOBANC" || siglaCategoria == "IO" || siglaCategoria == "IOSPETT" || siglaCategoria == "IOSPORT") &&
                                            Utility.DataStrettamenteSuccessivaA(datiPensione.DecorrenzaOriginaria.Value, new DateTime(1984, 7, 31)) && (codNat1 == '1' || codNat1 == '2' || codNat1 == '3' || codNat1 == '4') &&
                                            Utility.DataStrettamenteSuccessivaA(decorrenzaMaggiorazione.Value, new DateTime(2020, 7, 31)) && !Utility.DataStrettamenteSuccessivaA(decorrenzaMaggiorazione.Value, dataNascitaTitolare.Value.AddYears(60)));
                        break;
                    case Utility.TipoAppartenenza.CI:
                        //IOS, IRS, IOARTS, IOCOMS con decorrenza maggiore di 31/07/1984,
                        //primo byte codice natura uguale a 1, 2, 3 o 4 e decorrenza maggiorazione sociale maggiore di 31/07/2020 e età titolare < 60
                        isControlloMemo72 = ((siglaCategoria == "IOS" || siglaCategoria == "IRS" || siglaCategoria == "IOARTS" || siglaCategoria == "IOCOMS") &&
                                            Utility.DataStrettamenteSuccessivaA(datiPensione.DecorrenzaOriginaria.Value, new DateTime(1984, 7, 31)) && (codNat1 == '1' || codNat1 == '2' || codNat1 == '3' || codNat1 == '4') &&
                                            Utility.DataStrettamenteSuccessivaA(decorrenzaMaggiorazione.Value, new DateTime(2020, 7, 31)) && !Utility.DataStrettamenteSuccessivaA(decorrenzaMaggiorazione.Value, dataNascitaTitolare.Value.AddYears(60)));
                        break;
                    case Utility.TipoAppartenenza.FS:
                        Utility.TipoFondo? tipoFondo = Utility.GetTipoFondoByCategoria(Utility.TipoAppartenenza.FS, datiPensione.SiglaCategoria);
                        char? codiceSpecificoTraduzioneSuGP = null;
                        GestioneFondo.DatiFondo datiFondo = null;
                        GestioneFondo.GetFondoDatiGenericiByIdPensione(datiPensione.Id, out datiFondo);
                        if (datiFondo != null && datiFondo.CodiceSpecifico.HasValue)
                        {
                            List<GestioneDecodifica.CodiceSpecifico> elencoCodiceSpecifico = null;
                            GestioneDecodifica.GetCodiceSpecifico(out elencoCodiceSpecifico);
                            if (elencoCodiceSpecifico != null && elencoCodiceSpecifico.Count > 0)
                            {
                                GestioneDecodifica.CodiceSpecifico codice = elencoCodiceSpecifico.Find(x => x.Id == datiFondo.CodiceSpecifico.Value);
                                if (codice != null)
                                    codiceSpecificoTraduzioneSuGP = codice.TraduzioneGp;
                            }
                        }
                        //fondi VL, ET, TT, EL oppure fondi FS, PT con GP2NB14 CLF = F
                        //con decorrenza maggiore di 31/07/1984,
                        //Ricostituzioni: terzo byte numero certificato uguale a 2 o 5
                        //PL: sigla categoria che inizia con 'I'
                        //GP1AV37N uguale a 6 
                        //e decorrenza maggiorazione sociale maggiore di 31/07/2020 e età titolare < 60
                        isControlloMemo72 = (codiceSpecificoTraduzioneSuGP != null && (((tipoFondo == Utility.TipoFondo.VL && codiceSpecificoTraduzioneSuGP == 'E') || (tipoFondo == Utility.TipoFondo.ET && (codiceSpecificoTraduzioneSuGP == 'Q' || codiceSpecificoTraduzioneSuGP == 'I')) || ((tipoFondo == Utility.TipoFondo.TT || tipoFondo == Utility.TipoFondo.EL) && codiceSpecificoTraduzioneSuGP == 'Q')) ||
                                            ((tipoFondo == Utility.TipoFondo.FS || tipoFondo == Utility.TipoFondo.PT) && codiceSpecificoTraduzioneSuGP == 'F')) &&
                                            ((Utility.IsRicostituzione(datiPensione.Gruppo) && datiPensione.NCertificato.HasValue && (datiPensione.NCertificato.Value.ToString().PadLeft(8, '0').Substring(2, 1) == "2" || datiPensione.NCertificato.Value.ToString().PadLeft(8, '0').Substring(2, 1) == "5")) ||
                                            (!Utility.IsRicostituzione(datiPensione.Gruppo) && datiPensione.SiglaCategoria.StartsWith("I"))) &&
                                            Utility.DataStrettamenteSuccessivaA(datiPensione.DecorrenzaOriginaria.Value, new DateTime(1984, 7, 31)) && Utility.DataStrettamenteSuccessivaA(decorrenzaMaggiorazione.Value, new DateTime(2020, 7, 31)) &&
                                            !Utility.DataStrettamenteSuccessivaA(decorrenzaMaggiorazione.Value, dataNascitaTitolare.Value.AddYears(60)));
                        break;
                    default:
                        break;
                }

                if (ctrl != null && ctrl.ValoreControllo == "SI" && isControlloMemo72)
                {
                    if (((!Utility.IsRicostituzione(datiPensione.Gruppo) || Utility.DataStrettamenteSuccessivaA(datiPensione.DataPresentazioneDomanda, new DateTime(2020, 10, 30)) && !(Utility.IsDomandaAnte96(datiPensione, datiPensione, datiDanteCausa, isRiaperturaDomanda) != null && Utility.IsDomandaRipristinoOrRiliquidazione(datiPensione))))
                        && !(tipoAppartenenza == Utility.TipoAppartenenza.FS && Utility.IsRicostituzione(datiPensione.Gruppo) && Utility.IsDomandaPensioneSuperstitiOrRicostituzione(datiPensione)))
                    {
                        if (decorrenzaMaggiorazione.HasValue && decorrenzaMaggiorazione.Value <= datiPensione.DataPresentazioneDomanda)
                        {
                            messaggioVideo = string.Format("La decorrenza ({0}) nel tab 'Maggiorazioni' deve essere maggiore della data presentazione della domanda ({1})", decorrenzaMaggiorazione.Value.ToString("MM/yyyy"), datiPensione.DataPresentazioneDomanda.ToString("dd/MM/yyyy"));
                            ret = false;
                        }
                    }
                }
                else if ((decorrenzaMaggiorazione.Value <= datiPensione.DataPresentazioneDomanda && !(Utility.IsDomandaAnte96(datiPensione, datiPensione, datiDanteCausa, isRiaperturaDomanda) != null && Utility.IsDomandaRipristinoOrRiliquidazione(datiPensione))) && !(tipoAppartenenza == Utility.TipoAppartenenza.FS && Utility.IsRicostituzione(datiPensione.Gruppo) && Utility.IsDomandaPensioneSuperstitiOrRicostituzione(datiPensione)))
                {
                    messaggioVideo = string.Format("La decorrenza ({0}) nel tab 'Maggiorazioni' deve essere maggiore della data presentazione della domanda ({1})", decorrenzaMaggiorazione.Value.ToString("MM/yyyy"), datiPensione.DataPresentazioneDomanda.ToString("dd/MM/yyyy"));
                    ret = false;
                }
            }

            return ret;
        }

        public static bool AGO_CI_ControlsProvenienzaPensione(byte? provenienzaPensione, out string messaggioVideo)
        {
            messaggioVideo = string.Empty;

            if (!provenienzaPensione.HasValue)
            {
                messaggioVideo = "Il Codice Provenienza è obbligatorio.";
                return false;
            }

            return true;
        }

        public static bool AGO_CI_VerificaFamiliariConiugiRicostituzioneOrRiapertura(GestionePensione.DatiPensione datiPensione, GestionePensione.DatiEliminazione datiEliminazione, List<GestioneFamiliari.Familiare> lFamiliare,
            List<GestioneFamiliari.CodMaggFamiliari> elencoCodMaggFamiliari, bool isRiaperturaDomanda, out string msgVideo)
        {
            msgVideo = string.Empty;
            Utility.TipoAppartenenza? tipoAppartenenza = Utility.GetTipoAppartenenza(datiPensione.IndConvInt, datiPensione.Gestione);
            if (Utility.IsRicostituzioneOrRiapertura(datiPensione, isRiaperturaDomanda) && tipoAppartenenza != null &&
                ((tipoAppartenenza == Utility.TipoAppartenenza.AGO && !Utility.IsDomandaENPALS(datiPensione.Gestione)) || tipoAppartenenza == Utility.TipoAppartenenza.CI))
            {
                if (lFamiliare == null || lFamiliare.Count == 0 || !lFamiliare.Any(x => x.IsConiugeOrUnitoCivile() && (!x.Provenienza.HasValue || x.Provenienza.Value != 'P')))
                    return true;

                GestioneFamiliari.Familiare coniuge = lFamiliare.FirstOrDefault(x => x.IsConiugeOrUnitoCivile() && (!x.Provenienza.HasValue || x.Provenienza.Value != 'P'));
                if (elencoCodMaggFamiliari == null || elencoCodMaggFamiliari.Count == 0 || !elencoCodMaggFamiliari.Any(x => x.IdAnagrafica == coniuge.IdAnagrafica))
                    return true;

                GestioneFamiliari.CodMaggFamiliari lastCodMaggiorazione = elencoCodMaggFamiliari.FindAll(x => x.IdAnagrafica == coniuge.IdAnagrafica).OrderBy(x => x.Decorrenza).Last();
                if (!lastCodMaggiorazione.Cessazione.HasValue && datiEliminazione == null && !Utility.IsDomandaPensioneSuperstitiOrRicostituzione(datiPensione) &&
                    !(datiPensione.SiglaCategoria == "PMO" && (datiPensione.NCertificato.GetValueOrDefault().ToString().PadLeft(8, '0').Substring(2, 1) == "3" || datiPensione.NCertificato.ToString().PadLeft(8, '0').Substring(2, 1) == "6")))
                {
                    msgVideo = "Attenzione è necessario acquisire prima il Coniuge/Unito civilmente con la procedura VARIAZIONE PENSIONI opzione NUOVE NOZZE";
                    return false;
                }
            }
            return true;
        }
        #endregion AGO - CI

        #region AGO - FS

        public static bool AGO_FS_ControlsDataMatrimonioWithGradoParentelaAndDataMorte(GestionePensione.DatiPensione datiPensione, DateTime? dataMatrimonio, DateTime? dataMorte, DateTime? dataNascitaDC,
            List<GestioneFamiliari.Familiare> listaFamiliari, List<GestioneAnagrafica.DatiAnagrafici> listaAnagraficaFamiliari, GestioneAnagrafica.DatiAnagrafici anagraficaTitolare,
            Utility.TipoAppartenenza? tipoApp, bool isRiaperturaDomanda, GestioneDanteCausa.DatiDanteCausa danteCausa, out string messaggioVideo)
        {
            messaggioVideo = string.Empty;

            if (listaFamiliari != null && listaFamiliari.Count > 0)
            {
                if (tipoApp == Utility.TipoAppartenenza.FS || Utility.IsDomandaINPDAP(datiPensione.Gestione))
                {
                    if (listaFamiliari.FindIndex(x => x.IsConiugeOrUnitoCivile() || x.IsExConiugeOrScioltoDallUnione()) > -1 && datiPensione.DecorrenzaOriginaria.HasValue &&
                        Utility.DataSuccessivaA(datiPensione.DecorrenzaOriginaria.Value, new DateTime(2012, 1, 1)) && !dataMatrimonio.HasValue)
                    {
                        messaggioVideo = "Data Matrimonio obbligatoria in presenza di un familiare avente come grado di parentela 'Coniuge' o 'Unito/a Civilmente'";
                        return false;
                    }
                }
                else
                {
                    if (listaFamiliari.FindIndex(x => x.IsConiugeOrUnitoCivile() || x.IsExConiugeOrScioltoDallUnione()) > -1 && !dataMatrimonio.HasValue && !Utility.IsDomandaSpacchettamentoENPALS(datiPensione) && !Utility.IsDomandaSpacchettamentoINPDAP(datiPensione) && !Utility.IsDomandaSpacchettamentoSOPGIPost072022(datiPensione, danteCausa) && !Utility.IsDomandaSpacchettamentoSO(datiPensione, isRiaperturaDomanda) && !Utility.IsDomandaSpacchettamentoSOART(datiPensione, isRiaperturaDomanda)
                        && !Utility.IsDomandaSpacchettamentoSOCOM(datiPensione, isRiaperturaDomanda) && !Utility.IsDomandaSpacchettamentoSR(datiPensione, isRiaperturaDomanda))
                    {
                        messaggioVideo = "Data Matrimonio obbligatoria in presenza di un familiare avente come grado di parentela 'Coniuge' o 'Unito/a Civilmente'" + ((Utility.IsDomandaSpacchettamentoENPALS(datiPensione) || Utility.IsDomandaSpacchettamentoINPDAP(datiPensione) || Utility.IsDomandaSpacchettamentoSOPGIPost072022(datiPensione, danteCausa) || Utility.IsDomandaSpacchettamentoSO(datiPensione, isRiaperturaDomanda) ||
                            Utility.IsDomandaSpacchettamentoSOART(datiPensione, isRiaperturaDomanda) || Utility.IsDomandaSpacchettamentoSOCOM(datiPensione, isRiaperturaDomanda) || Utility.IsDomandaSpacchettamentoSR(datiPensione, isRiaperturaDomanda)) ? " o 'Ex-Coniuge'" : string.Empty);
                        return false;
                    }
                }

                if (Utility.IsDomandaSpacchettamentoENPALS(datiPensione) || Utility.IsDomandaSpacchettamentoSOPGIPost072022(datiPensione, danteCausa) || Utility.IsDomandaSpacchettamentoSO(datiPensione, isRiaperturaDomanda) ||
                    Utility.IsDomandaSpacchettamentoSOART(datiPensione, isRiaperturaDomanda) || Utility.IsDomandaSpacchettamentoSOCOM(datiPensione, isRiaperturaDomanda) || Utility.IsDomandaSpacchettamentoSR(datiPensione, isRiaperturaDomanda))
                {
                    if (listaFamiliari.FindIndex(x => x.CodiceFiscale == anagraficaTitolare.CodiceFiscale && x.IsConiugeOrUnitoCivile()) > -1 && !dataMatrimonio.HasValue)
                    {
                        messaggioVideo = "Data Matrimonio obbligatoria in presenza di un familiare avente come grado di parentela 'Coniuge' o 'Unito/a Civilmente'";
                        return false;
                    }

                    if (!Utility.IsRicostituzioneOrRiapertura(datiPensione, isRiaperturaDomanda) &&
                        listaFamiliari.FindIndex(x => x.CodiceFiscale == anagraficaTitolare.CodiceFiscale && !x.IsConiugeOrUnitoCivile() && !x.IsExConiugeOrScioltoDallUnione()) > -1 && dataMatrimonio.HasValue)
                    {
                        messaggioVideo = "La Data Matrimonio non può essere acquisita per il corrente grado di parentela del titolare.";
                        return false;
                    }
                }
            }

            if (dataMatrimonio.HasValue)
            {
                if (!Utility.VerificaData(dataMatrimonio, tipoApp, out messaggioVideo))
                {
                    messaggioVideo = "Data Matrimonio illogica: " + messaggioVideo;
                    return false;
                }

                if (dataMorte.HasValue && !Utility.DataSuccessivaA(dataMorte.Value, dataMatrimonio.Value))
                {
                    messaggioVideo = "Data Matrimonio successiva a Data Morte";
                    return false;
                }

                if (listaAnagraficaFamiliari != null && listaAnagraficaFamiliari.Count > 0 && listaFamiliari != null && listaFamiliari.Count > 0 &&
                    listaFamiliari.Exists(x => x.CodiceFiscale == anagraficaTitolare.CodiceFiscale) &&
                    (listaFamiliari.Find(x => x.CodiceFiscale == anagraficaTitolare.CodiceFiscale).IsConiugeOrUnitoCivile() || listaFamiliari.Find(x => x.CodiceFiscale == anagraficaTitolare.CodiceFiscale).IsExConiugeOrScioltoDallUnione()) &&
                    Utility.DataSuccessivaA(listaAnagraficaFamiliari.Find(x => x.CodiceFiscale == anagraficaTitolare.CodiceFiscale).DataNascita.Value, dataMatrimonio.Value))
                {
                    messaggioVideo = "Data Matrimonio antecedente a Data Nascita Richiedente";
                    return false;
                }

                if (dataNascitaDC.HasValue && Utility.DataStrettamenteSuccessivaA(dataNascitaDC.Value, dataMatrimonio.Value))
                {
                    messaggioVideo = "Data Matrimonio antecedente a Data Nascita Dante Causa";
                    return false;
                }
            }

            return true;
        }


        public static bool? IsCodiceNatura2Enabled(GestionePensione.DatiPensione datiPensione)
        {
            GestioneCtrlCodiceNatura2.CtrlCodiceNatura2 codiceNatura2;
            GestioneCtrlCodiceNatura2.GetCtrlCodiceNatura2ByCodiceTipoRichiesta(datiPensione.CodiceTipoRichiesta, out codiceNatura2);
            bool enabled = true;
            if (codiceNatura2 != null)
                enabled = false;
            return enabled;
        }

        public static string GetCodiceNaturaFromCodiceTipoRichiesta(string codiceTipoRichiesta, Utility.TipoFondo? tipoFondo, Utility.TipoAppartenenza tipoAppartenenza)
        {
            GestioneCtrlCodiceNatura2.CtrlCodiceNatura2 ctrlCodiceNatura2;
            GestioneCtrlCodiceNatura2.GetCtrlCodiceNatura2ByCodiceTipoRichiesta(codiceTipoRichiesta, out ctrlCodiceNatura2);

            string ret = null;
            switch (tipoAppartenenza)
            {
                case Utility.TipoAppartenenza.AGO:
                    ret = ((ctrlCodiceNatura2 != null) ? (" " + ctrlCodiceNatura2.CodiceNatura2 + " ") : null);
                    break;
                case Utility.TipoAppartenenza.FS:
                    List<GestioneDecodifica.CodiciNatura> LcodiciNatura = null;
                    GestioneDecodifica.GetCodiciNatura(out LcodiciNatura);
                    string first = " ";
                    if (tipoFondo.HasValue)
                    {
                        GestioneDecodifica.CodiciNatura item = LcodiciNatura.Find(x => x.Fondo == tipoFondo.Value.ToString() && x.Posizione == 1);
                        if (item != null)
                            first = item.TraduzioneSuGP.HasValue ? item.TraduzioneSuGP.Value.ToString() : " ";
                    }
                    ret = ((ctrlCodiceNatura2 != null) ? (first + ctrlCodiceNatura2.CodiceNatura2 + " ") : null);
                    break;
                default:
                    //do nothing
                    break;
            }
            return ret;
        }

        public static bool AGO_FS_ControlsOneriSperDonna(GestionePensione.DatiPensione datiPensione, bool isRiaperturaDomanda, List<GestioneOneri.DatiOneri> listaDatiOneri, out string messaggioVideo)
        {
            messaggioVideo = string.Empty;
            bool recordOneriChanged = false;

            //ENG - Memo 123/2024
            GestioneControlliDinamici.ControlloDinamico ctrlMemo123_2024 = null;
            GestioneControlliDinamici.GetControlloDinamicoByNomeControllo("AbilitazioneRIC_TRFMemo123_2024", out ctrlMemo123_2024);

            //ENG - Memo 123/2024
            GestioneControlliDinamici.ControlloDinamico ctrlMemo123_2024OpzioneContrib = null;
            GestioneControlliDinamici.GetControlloDinamicoByNomeControllo("AbilitazioneRIC_TRFMemo123_2024OpzioneContrib", out ctrlMemo123_2024OpzioneContrib);

            // Per le domande automatiche non deve essere effettuato il controllo, nè tanto meno l'inserimento / cancellazione del record
            if (Utility.IsDomandaUnicarpe(datiPensione, true) == Utility.TipoUnicarpe.Automatica || datiPensione.IsPLUnicarpe.GetValueOrDefault())
                return true;

            if (!isRiaperturaDomanda && Utility.IsDomandaSperimentaleDonna(datiPensione))
            {
                List<GestioneDecodifica.GruppoOneri> decGruppoOnere = null;
                GestioneDecodifica.GetGruppoOneri(out decGruppoOnere);
                List<GestioneDecodifica.SottoGruppoOneri> decSottoGruppoOneri = null;
                GestioneDecodifica.GetSottoGruppoOneri(out decSottoGruppoOneri);
                GestioneQuadri.DatiQuadroOneri datiQuadroOneri = null;
                GestioneQuadri.GetQuadroOneriByDatiPensione(datiPensione, out datiQuadroOneri);

                try
                {
                    using (System.Transactions.TransactionScope transactionScope = INPS.DNA.Data.TransactionScopeFactory.Create(System.Transactions.TransactionScopeOption.Required,
                       new System.Transactions.TransactionOptions { IsolationLevel = System.Transactions.IsolationLevel.ReadCommitted }))
                    {
                        GestioneOneri.DatiOneri datiOneriSperDonna = listaDatiOneri != null ? listaDatiOneri.Where(x => x.IdCodeGruppo == decGruppoOnere.Find(y => y.Code == "4700").Id && (x.IdCodeSottoGruppo == (Utility.IsDomandaINPDAP(datiPensione.Gestione) ? decSottoGruppoOneri.Find(y => y.Code == "4702").Id : decSottoGruppoOneri.Find(y => y.Code == "4701").Id))).FirstOrDefault() : null;
                        if (Utility.IsOneriSperDonnaObbligatoriPerControlli(datiPensione, isRiaperturaDomanda, datiPensione.DecorrenzaOriginaria, datiPensione.NaturaPensione) && datiOneriSperDonna == null)
                        {
                            GestioneOneri.DatiOneri newOneri = new GestioneOneri.DatiOneri { IdCodeGruppo = decGruppoOnere.Find(y => y.Code == "4700").Id, IdCodeSottoGruppo = Utility.IsDomandaINPDAP(datiPensione.Gestione) ? decSottoGruppoOneri.Find(y => y.Code == "4702").Id : decSottoGruppoOneri.Find(y => y.Code == "4701").Id, Decorrenza = datiPensione.DecorrenzaOriginaria, IdPensione = datiPensione.Id };
                            GestioneOneri.SalvaOneriOnere(newOneri);
                            recordOneriChanged = true;

                            messaggioVideo = "Dati incongruenti. E' richiesto il salvataggio degli Oneri.";
                        }
                        else if (!Utility.IsOneriSperDonnaObbligatoriPerControlli(datiPensione, isRiaperturaDomanda, datiPensione.DecorrenzaOriginaria, datiPensione.NaturaPensione) && datiOneriSperDonna != null)
                        {
                            GestioneOneri.EliminaOneriByIdPensione(datiPensione.Id);
                            listaDatiOneri.Where(x => x.IdCodeGruppo != decGruppoOnere.Find(y => y.Code == "4700").Id && x.IdCodeSottoGruppo != (Utility.IsDomandaINPDAP(datiPensione.Gestione) ? decSottoGruppoOneri.Find(y => y.Code == "4702").Id : decSottoGruppoOneri.Find(y => y.Code == "4701").Id))
                                .ToList()
                                .ForEach(x => GestioneOneri.SalvaOneriOnere(x));
                            recordOneriChanged = true;

                            messaggioVideo = "Oneri incongruenti. Salvare nuovamente il quadro Oneri o riprovare l'invio al calcolo.";
                        }

                        if (recordOneriChanged)
                        {
                            // Oneri
                            if ((Utility.IsDomandaSalvaguardia124(datiPensione) || Utility.IsDomandaSalvaguardia214(datiPensione) || Utility.IsDomandaSalvaguardia228(datiPensione) ||
                                 Utility.IsDomandaSalvaguardia124Art11Bis(datiPensione) || Utility.IsDomandaUsuranti(datiPensione) || Utility.IsDomandaSalvaguardia147(datiPensione) ||
                                 Utility.IsDomandaEsuberiPA(datiPensione) || Utility.IsDomandaSalvaguardia147_2014(datiPensione) || Utility.IsDomandaSalvaguardia135(datiPensione) ||
                                 Utility.IsDomandaSalvaguardia208_2015(datiPensione) || Utility.IsDomandaSalvaguardia178_2020(datiPensione) || Utility.IsDomandaAPEPrecoci(datiPensione))
                                ||
                                Utility.IsDomandaConBeneficioAmianto181(datiPensione.AttivitaEconomica, datiPensione.ProfessioneIndividuale) ||
                                //si passano i datiBeneficioTerrorismo a null in quanto i controlli effettuati sono solo per sperimentale donna if (!isRiaperturaDomanda && Utility.IsDomandaSperimentaleDonna(datiPensione))
                                Utility.IsDomandaBeneficioTerrorismoOver80(datiPensione, null) || Utility.IsDomandaBeneficioTerrorismoUnder80(datiPensione, null) ||
                                Utility.IsOneriSperDonnaObbligatoriPerControlli(datiPensione, isRiaperturaDomanda, datiPensione.DecorrenzaOriginaria, datiPensione.NaturaPensione) ||
                                Utility.IsPrepensionamentoEditoriaFiltroEAA(datiPensione) || Utility.IsPrepensionamentoEditoriaFiltroEBA(datiPensione) || Utility.IsPrepensionamentoEditoriaArt1c154L205_2017(datiPensione) ||
                                Utility.IsPrepensionamentoEditoriaArt1c500L160_2019(datiPensione) || Utility.IsDomandaInabilitaAmianto(datiPensione) ||
                                Utility.IsDomandaVecchiaiaRequisitoAnticipatoArt1(datiPensione) || Utility.IsDomandaVecchiaiaRequisitoAnticipatoArt1OpzioneContributivo(datiPensione) ||
                                Utility.IsDomandaQuota100(datiPensione) || Utility.IsDomandaQuota102(datiPensione) || Utility.IsDomandaSperimentaleDonna_DL_4_2019(datiPensione) || Utility.IsDomandaAnzianitaPerLeggeBilancio2019OrRicostituzione(datiPensione) || Utility.IsDomandaAnticipataFlessibile(datiPensione)
                                || Utility.IsDomandaAnticipataFlessibileOpzioneContributivo(datiPensione) || (!Utility.IsRicostituzioneOrRiapertura(datiPensione, isRiaperturaDomanda) && (Utility.IsDomandaAnticipataFlessibileLeggeBilancio2024(datiPensione) || Utility.IsDomandaAnticipataFlessibileOpzioneContributivoLeggeBilancio2024(datiPensione))) ||
                                (Utility.IsRicostituzioneOrRiapertura(datiPensione, isRiaperturaDomanda) && ((ctrlMemo123_2024 != null && ctrlMemo123_2024.ValoreControllo == "SI" && Utility.IsDomandaAnticipataFlessibileLeggeBilancio2024(datiPensione)) || (ctrlMemo123_2024OpzioneContrib != null && ctrlMemo123_2024OpzioneContrib.ValoreControllo == "SI" && Utility.IsDomandaAnticipataFlessibileOpzioneContributivoLeggeBilancio2024(datiPensione)))) ||
                                Utility.IsDomandaVOAUTAnticipataFlessibileLeggeBilancio2024FiltroGSE(datiPensione))
                            {
                                if (datiQuadroOneri.TabOneri == null ||
                                    (datiQuadroOneri.TabOneri == 2 && recordOneriChanged))
                                    datiQuadroOneri.TabOneri = 0; //rosso
                            }
                            else
                                datiQuadroOneri.TabOneri = null;

                            //condizione visibilità oneri
                            if ((Utility.IsDomandaSalvaguardia124(datiPensione) || Utility.IsDomandaSalvaguardia214(datiPensione) || Utility.IsDomandaSalvaguardia228(datiPensione) ||
                                 Utility.IsDomandaSalvaguardia124Art11Bis(datiPensione) || Utility.IsDomandaUsuranti(datiPensione) || Utility.IsDomandaSalvaguardia147(datiPensione) ||
                                 Utility.IsDomandaEsuberiPA(datiPensione) || Utility.IsDomandaSalvaguardia147_2014(datiPensione) || Utility.IsDomandaSalvaguardia135(datiPensione) ||
                                 Utility.IsDomandaSalvaguardia208_2015(datiPensione) || Utility.IsDomandaSalvaguardia178_2020(datiPensione) ||
                                 Utility.IsDomandaAPEPrecoci(datiPensione) || Utility.IsDomandaConBeneficioAmianto181(datiPensione.AttivitaEconomica, datiPensione.ProfessioneIndividuale) ||
                                //si passano i datiBeneficioTerrorismo a null in quanto i controlli effettuati sono solo per sperimentale donna if (!isRiaperturaDomanda && Utility.IsDomandaSperimentaleDonna(datiPensione))
                                 Utility.IsDomandaBeneficioTerrorismoOver80(datiPensione, null) || Utility.IsDomandaBeneficioTerrorismoUnder80(datiPensione, null) ||
                                 Utility.IsOneriSperDonnaObbligatoriPerControlli(datiPensione, isRiaperturaDomanda, datiPensione.DecorrenzaOriginaria, datiPensione.NaturaPensione) ||
                                 Utility.IsPrepensionamentoEditoriaFiltroEAA(datiPensione) || Utility.IsPrepensionamentoEditoriaFiltroEBA(datiPensione) || Utility.IsPrepensionamentoEditoriaArt1c154L205_2017(datiPensione) ||
                                 Utility.IsPrepensionamentoEditoriaArt1c500L160_2019(datiPensione) || Utility.IsDomandaInabilitaAmianto(datiPensione) ||
                                 Utility.IsDomandaVecchiaiaRequisitoAnticipatoArt1(datiPensione) || Utility.IsDomandaVecchiaiaRequisitoAnticipatoArt1OpzioneContributivo(datiPensione) ||
                                 Utility.IsDomandaQuota100(datiPensione) || Utility.IsDomandaQuota102(datiPensione) || Utility.IsDomandaSperimentaleDonna_DL_4_2019(datiPensione) || Utility.IsDomandaAnzianitaPerLeggeBilancio2019OrRicostituzione(datiPensione) || Utility.IsDomandaAnticipataFlessibile(datiPensione) ||
                                 Utility.IsDomandaAnticipataFlessibileOpzioneContributivo(datiPensione) || Utility.IsOpzioneDonna_Legge197_2022_Art1_Comma292_LetteraA(datiPensione, true, true) || Utility.IsOpzioneDonna_Legge197_2022_Art1_Comma292_LetteraB(datiPensione, true, true) || Utility.IsOpzioneDonna_Legge197_2022_Art1_Comma292_LetteraC(datiPensione, true, true) ||
                                 (!Utility.IsRicostituzioneOrRiapertura(datiPensione, isRiaperturaDomanda) && (Utility.IsDomandaAnticipataFlessibileLeggeBilancio2024(datiPensione) || Utility.IsDomandaAnticipataFlessibileOpzioneContributivoLeggeBilancio2024(datiPensione))) ||
                                 (Utility.IsRicostituzioneOrRiapertura(datiPensione, isRiaperturaDomanda) && ((ctrlMemo123_2024 != null && ctrlMemo123_2024.ValoreControllo == "SI" && Utility.IsDomandaAnticipataFlessibileLeggeBilancio2024(datiPensione)) || (ctrlMemo123_2024OpzioneContrib != null && ctrlMemo123_2024OpzioneContrib.ValoreControllo == "SI" && Utility.IsDomandaAnticipataFlessibileOpzioneContributivoLeggeBilancio2024(datiPensione)))) ||
                                 Utility.IsDomandaVOAUTAnticipataFlessibileLeggeBilancio2024FiltroGSE(datiPensione))
                                ||
                                //condizione visibilità prepensionamento
                                (Utility.IsTabPrepensionamentoVisible(datiPensione, datiPensione.AttivitaEconomica, datiPensione.ProfessioneIndividuale, datiPensione.NaturaPensione) &&
                                 !Utility.IsDomandaSalvaguardia122(datiPensione) && Utility.GetTipoDomanda(datiPensione.Gruppo, datiPensione.Prodotto) != Utility.TipoDomanda.Ricostituzione &&
                                 Utility.GetTipoDomanda(datiPensione.Gruppo, datiPensione.Prodotto) != Utility.TipoDomanda.RipristinoSuperstiti &&
                                 Utility.GetTipoDomanda(datiPensione.Gruppo, datiPensione.Prodotto) != Utility.TipoDomanda.Ripristino && !isRiaperturaDomanda))
                            {
                                datiQuadroOneri.Tipo = 2;
                            }
                            else
                                datiQuadroOneri.Tipo = 0;

                            GestioneQuadri.SalvaQuadroOneri(datiPensione.Id, datiQuadroOneri);
                        }
                        transactionScope.Complete();
                    }
                }
                catch (Exception ex)
                {
                    messaggioVideo = ex.Message;
                    return false;
                }
            }

            if (!string.IsNullOrEmpty(messaggioVideo))
                return false;

            return true;
        }

        public static bool AGO_FS_VerificaDipendenzaPerfezRequisitiRiduzioneRetributiva(GestionePensione.DatiPensione datiPensione, bool riduzioneRetributiva, Utility.TipoCalcolo tipoCalcolo)
        {
            if ((!string.IsNullOrEmpty(datiPensione.Gruppo) && datiPensione.Gruppo == "0001" && !string.IsNullOrEmpty(datiPensione.Prodotto) && datiPensione.Prodotto == "0001" &&
               (tipoCalcolo == Utility.TipoCalcolo.Retributivo || tipoCalcolo == Utility.TipoCalcolo.Misto || tipoCalcolo == Utility.TipoCalcolo.RetributivoMonti))
                //Condizione di visibilità riduzione retributiva per categoria VESO92 
               || (Utility.IsDomandaVESO92(datiPensione.SiglaCategoria) && (datiPensione.Tipo == "0039") && datiPensione.GetFiltro() == "AGO"))
            {
                if (datiPensione.DataPerfezionamentoRequisiti.HasValue && datiPensione.DataPerfezionamentoRequisiti.Value.CompareTo(new DateTime(2012, 01, 01)) < 0 &&
                    !Utility.IsDomandaBeneficioTerrorismoOver80(datiPensione, null) && !Utility.IsDomandaBeneficioTerrorismoUnder80(datiPensione, null))
                {
                    if (riduzioneRetributiva)
                        return false;
                }
            }
            return true;
        }
