        #region FS

        #region Titolare
        /// <summary>
        /// Verifica la decorrenza pensione con la data invalidità e la data fine assicurazione
        /// </summary>
        /// <param name="datiPensione"></param>
        /// <param name="datiFondoVL"></param>
        /// <param name="messaggioVideo"></param>
        /// <returns></returns>
        public static bool FS_VerificaDecPensWithDataInvaliditaCodeArt22FondoVL(GestionePensione.DatiPensione datiPensione, GestioneDanteCausa.DatiDanteCausa datiDanteCausa, DateTime? dataUltimoVersamento,
            DateTime? dataInvalidita, byte? codiceArt22, DateTime? decorrenzaOriginaria, bool isRiaperturaDomanda, out string messaggioVideo)
        {
            messaggioVideo = string.Empty;

            DateTime? decorrenzaPensioneOrDecorrenzaPensioneDC = Utility.GetDecorrenzaPensioneOrDecorrenzaDantecausa(decorrenzaOriginaria, datiDanteCausa != null ? datiDanteCausa.DecorrenzaPensione : null);

            if (!dataUltimoVersamento.HasValue)
            {
                messaggioVideo = "La Data Ultimo Versamento è obbligatoria";
                return false;
            }

            if (!codiceArt22.HasValue)
            {
                messaggioVideo = "Il Codice Art.22 è obbligatorio";
                return false;
            }

            if (datiPensione.SiglaCategoria.Substring(0, 1) == "I" && !dataInvalidita.HasValue)
            {
                messaggioVideo = "La Data Invalidità è obbligatoria";
                return false;
            }

            //in caso di invalidità specifica la decorrenza pensione deve essere successiva alla data più recente tra “Data Ultimo Versamento” e “Data Invalidità”
            if (codiceArt22.Value == 3)
            {
                int result = dataInvalidita.HasValue ? dataUltimoVersamento.Value.CompareTo(dataInvalidita.Value) : 1;

                if (result > 0)
                {
                    if (decorrenzaOriginaria.HasValue && decorrenzaOriginaria.Value <= dataUltimoVersamento.Value)
                    {
                        messaggioVideo = "La decorrenza pensione deve essere successiva alla data più recente tra 'Data Ultimo Versamento' e 'Data Invalidità'";
                        return false;
                    }
                }
                else
                {
                    if (decorrenzaOriginaria.HasValue && dataInvalidita.HasValue && decorrenzaOriginaria.Value <= dataInvalidita.Value)
                    {
                        messaggioVideo = "La decorrenza pensione deve essere successiva alla data più recente tra 'Data Ultimo Versamento' e 'Data Invalidità'";
                        return false;
                    }
                }
            }
            //in caso di invalidità generica la decorrenza pensione deve essere il primo giorno del mese successivo della data di presentazione domanda
            // Si escludono dal controllo le reversibilità ante armonizzazione, le ricostituzioni di reversibilità ante armonizzazione e le ricostituzioni e trasformazioni
            else if (codiceArt22.Value == 4 && !(Utility.IsDomandaReversibilitaOrRicostituzione(datiPensione, datiDanteCausa) &&
                Utility.IsDomandaAnteArmonizzazione(datiPensione, Utility.GetTipoFondoByCategoria(datiPensione.IndConvInt, datiPensione.Gestione, datiPensione.SiglaCategoria),
                decorrenzaPensioneOrDecorrenzaPensioneDC)) && !Utility.IsRicostituzioneOrRiapertura(datiPensione, isRiaperturaDomanda) && !Utility.IsDomandaAssegnoInvaliditaOrdinario(datiPensione))
            {
                DateTime dataCompare = new DateTime(datiPensione.DataPresentazioneDomanda.Year, datiPensione.DataPresentazioneDomanda.Month, 1).AddMonths(1);

                if (decorrenzaOriginaria.HasValue && DateTime.Compare(decorrenzaOriginaria.Value, dataCompare) != 0)
                {
                    messaggioVideo = "La Decorrenza Pensione deve essere uguale al primo giorno del mese successivo alla Data Presentazione Domanda";
                    return false;
                }
            }

            return true;
        }

