        public static bool FS_ControlsDecorrenzaPersonaleViaggianteSenzaPerditaTitoloAbilitante(DateTime? decorrenzaOriginaria, DateTime? dataPerfezionamentoRequisiti, out string messaggioVideo)
        {
            messaggioVideo = string.Empty;

            if (decorrenzaOriginaria.HasValue && dataPerfezionamentoRequisiti.HasValue)
            {
                if (!Utility.DataSuccessivaA(decorrenzaOriginaria.Value, Utility.FirstDayOfMonth(dataPerfezionamentoRequisiti.Value.AddMonths(1))))
                {
                    messaggioVideo = "La decorrenza pensione deve essere maggiore o uguale al mese successivo alla data Perfezionamento Requisiti.";
                    return false;
                }
            }

            return true;
        }

        public static bool FS_VerificaCompatibilitaPerfezionamentoPersonaleViaggianteSenzaPerditaTitoloAbilitante(DateTime? dataPerfezionamentoRequisiti, DateTime? dataNascitaTitolare,
            out string messaggioVideo)
        {
            messaggioVideo = string.Empty;

            if (dataPerfezionamentoRequisiti.HasValue && !Utility.DataStrettamenteSuccessivaA(dataPerfezionamentoRequisiti.Value, new DateTime(2013, 12, 31)) &&
                dataNascitaTitolare.HasValue && Utility.DataSuccessivaA(dataNascitaTitolare.Value, new DateTime(1954, 1, 1)))
            {
                messaggioVideo = "Prestazione non compatibile con data perfezionamento requisiti e data di nascita.";
                return false;
            }

            return true;
        }

