                    /*9*/ new DateTime(2030, 12, 31), /*10*/ new DateTime(2032, 12, 31), /*11*/ new DateTime(2034, 12, 31), /*12*/ new DateTime(2036, 12, 31), /*13*/ new DateTime(2038, 12, 31), 
                    /*14*/ new DateTime(2040, 12, 31), /*15*/ new DateTime(2042, 12, 31), /*16*/ new DateTime(2044, 12, 31), /*17*/ new DateTime(2046, 12, 31), /*18*/ new DateTime(2048, 12, 31), 
                    /*19*/ new DateTime(2050, 12, 31), /*20*/ new DateTime(2052, 12, 31), /*21*/ new DateTime(2054, 12, 31), /*22*/ new DateTime(2056, 12, 31), /*23*/ new DateTime(2058, 12, 31), 
                    /*24*/ new DateTime(2060, 12, 31), /*25*/ new DateTime(2062, 12, 31), /*26*/ new DateTime(2064, 12, 31), /*27*/ new DateTime(2065, 12, 31) };

                List<Utility.DifferenzaDateTime> listaEtaLimiteDonna = new List<Utility.DifferenzaDateTime>{ /*1*/ new Utility.DifferenzaDateTime(61, 3, 0), 
                    /*2*/ new Utility.DifferenzaDateTime(61, 7, 0), /*3*/ new Utility.DifferenzaDateTime(61, 7, 0), /*4*/ new Utility.DifferenzaDateTime(62, 0, 0), 
                    /*5*/ new Utility.DifferenzaDateTime(62, 0, 0), /*6*/ new Utility.DifferenzaDateTime(62, 0, 0), /*7*/ new Utility.DifferenzaDateTime(62, 0, 0), 
                    /*8*/ new Utility.DifferenzaDateTime(67, 2, 0), /*9*/ new Utility.DifferenzaDateTime(62, 5, 0), /*10*/ new Utility.DifferenzaDateTime(63, 5, 0), 
                    /*11*/ new Utility.DifferenzaDateTime(63, 8, 0), /*12*/ new Utility.DifferenzaDateTime(63, 10, 0), /*13*/ new Utility.DifferenzaDateTime(64, 0, 0), 
                    /*14*/ new Utility.DifferenzaDateTime(64, 2, 0), /*15*/ new Utility.DifferenzaDateTime(64, 4, 0), /*16*/ new Utility.DifferenzaDateTime(64, 6, 0), 
                    /*17*/ new Utility.DifferenzaDateTime(64, 8, 0), /*18*/ new Utility.DifferenzaDateTime(64, 10, 0), /*19*/ new Utility.DifferenzaDateTime(65, 0, 0), 
                    /*20*/ new Utility.DifferenzaDateTime(65, 2, 0), /*21*/ new Utility.DifferenzaDateTime(65, 4, 0), /*22*/ new Utility.DifferenzaDateTime(65, 6, 0), 
                    /*23*/ new Utility.DifferenzaDateTime(65, 8, 0), /*24*/ new Utility.DifferenzaDateTime(65, 10, 0), /*25*/ new Utility.DifferenzaDateTime(66, 0, 0), 
                    /*26*/ new Utility.DifferenzaDateTime(66, 2, 0), /*27*/ new Utility.DifferenzaDateTime(66, 3, 0)};

                List<Utility.DifferenzaDateTime> listaEtaLimiteUomo = new List<Utility.DifferenzaDateTime>{ /*1*/ new Utility.DifferenzaDateTime(61, 3, 0), 
                    /*2*/ new Utility.DifferenzaDateTime(61, 7, 0), /*3*/ new Utility.DifferenzaDateTime(61, 7, 0), /*4*/ new Utility.DifferenzaDateTime(62, 0, 0), 
                    /*5*/ new Utility.DifferenzaDateTime(62, 0, 0), /*6*/ new Utility.DifferenzaDateTime(62, 0, 0), /*7*/ new Utility.DifferenzaDateTime(62, 0, 0), 
                    /*8*/ new Utility.DifferenzaDateTime(67, 2, 0), /*9*/ new Utility.DifferenzaDateTime(62, 5, 0), /*10*/ new Utility.DifferenzaDateTime(63, 5, 0), 
                    /*11*/ new Utility.DifferenzaDateTime(63, 8, 0), /*12*/ new Utility.DifferenzaDateTime(63, 10, 0), /*13*/ new Utility.DifferenzaDateTime(64, 0, 0), 
                    /*14*/ new Utility.DifferenzaDateTime(64, 2, 0), /*15*/ new Utility.DifferenzaDateTime(64, 4, 0), /*16*/ new Utility.DifferenzaDateTime(64, 6, 0), 
                    /*17*/ new Utility.DifferenzaDateTime(64, 8, 0), /*18*/ new Utility.DifferenzaDateTime(64, 10, 0), /*19*/ new Utility.DifferenzaDateTime(65, 0, 0), 
                    /*20*/ new Utility.DifferenzaDateTime(65, 2, 0), /*21*/ new Utility.DifferenzaDateTime(65, 4, 0), /*22*/ new Utility.DifferenzaDateTime(65, 6, 0), 
                    /*23*/ new Utility.DifferenzaDateTime(65, 8, 0), /*24*/ new Utility.DifferenzaDateTime(65, 10, 0), /*25*/ new Utility.DifferenzaDateTime(66, 0, 0), 
                    /*26*/ new Utility.DifferenzaDateTime(66, 2, 0), /*27*/ new Utility.DifferenzaDateTime(66, 3, 0)};

                int index = listaDataLimiteInferiore.FindLastIndex(x => !Utility.DataStrettamenteSuccessivaA(x, dataPerfezionamentoRequisiti.Value));

                if (index > -1)
                {
                    dataLimiteInferiore = listaDataLimiteInferiore.ElementAt(index);
                    dataLimiteSuperiore = listaDataLimiteSuperiore.ElementAt(index);

                    if (Utility.DataSuccessivaA(dataPerfezionamentoRequisiti.Value, dataLimiteInferiore.Value) &&
                        !Utility.DataStrettamenteSuccessivaA(dataPerfezionamentoRequisiti.Value, dataLimiteSuperiore.Value))
                    {
                        switch (sessoTitolare.Value)
                        {
                            case 'F':
                                etaLimiteTitolare = listaEtaLimiteDonna.ElementAt(index);
                                break;
                            case 'M':
                                etaLimiteTitolare = listaEtaLimiteUomo.ElementAt(index);
                                break;
                        }

                        if (etaLimiteTitolare != null && Utility.DifferenzaBetweenDate(dataPerfezionamentoRequisiti, dataNascitaTitolare, Utility.TipoAppartenenza.FS) < etaLimiteTitolare)
                        {
                            messaggioVideo = "Il titolare non ha raggiunto i requisiti di età al " + String.Format("({0:dd/MM/yyyy})", dataPerfezionamentoRequisiti.Value) +
                                " (requisito " + etaLimiteTitolare.Year + " AA " + etaLimiteTitolare.Month + " MM)";
                            return false;
                        }
                    }
                }
            }

            return true;
        }

        public static bool FS_ControlsDecorrenzaPersonaleViaggianteConPerditaTitoloAbilitante(DateTime? decorrenzaOriginaria, DateTime? dataPerfezionamentoRequisiti, GestionePensione.DatiPensione datiPensione, out string messaggioVideo)
        {
            messaggioVideo = string.Empty;

            if (decorrenzaOriginaria.HasValue && dataPerfezionamentoRequisiti.HasValue && Utility.DataSuccessivaA(dataPerfezionamentoRequisiti.Value, new DateTime(2008, 1, 1)))
            {
                //ENG - Personale Viaggiante Fondo ET 
                if (Utility.IsDomandaPersonaleViaggianteConPerditaTitoloAbilitante(datiPensione) || Utility.IsDomandaPersonaleViaggianteConPerditaTitoloAbilitanteVOCPDEL(datiPensione))
                {
                    DateTime dataConfronto = Utility.FirstDayOfMonth(dataPerfezionamentoRequisiti.Value).AddMonths(3);
                    if (!Utility.DataStrettamenteSuccessivaA(decorrenzaOriginaria.Value, dataConfronto))
                    {
                        messaggioVideo = "La decorrenza pensione deve essere successiva di almeno tre mesi alla data perfezionamento requisiti";
                        return false;
                    }
                }
                else
                {
                    if (!Utility.DataStrettamenteSuccessivaA(dataPerfezionamentoRequisiti.Value, new DateTime(dataPerfezionamentoRequisiti.Value.Year, 3, 31)))
                    {
                        if (!Utility.DataSuccessivaA(decorrenzaOriginaria.Value, new DateTime(dataPerfezionamentoRequisiti.Value.Year, 7, 1)))
                        {
                            messaggioVideo = "La decorrenza della pensione deve essere successiva o uguale al " + String.Format("{0:MM/yyyy}", new DateTime(dataPerfezionamentoRequisiti.Value.Year, 7, 1));
                            return false;
                        }
                    }
                    else if (!Utility.DataStrettamenteSuccessivaA(dataPerfezionamentoRequisiti.Value, new DateTime(dataPerfezionamentoRequisiti.Value.Year, 6, 30)))
                    {
                        if (!Utility.DataSuccessivaA(decorrenzaOriginaria.Value, new DateTime(dataPerfezionamentoRequisiti.Value.Year, 10, 1)))
                        {
                            messaggioVideo = "La decorrenza della pensione deve essere successiva o uguale al " + String.Format("{0:MM/yyyy}", new DateTime(dataPerfezionamentoRequisiti.Value.Year, 10, 1));
                            return false;
                        }
                    }
                    else if (!Utility.DataStrettamenteSuccessivaA(dataPerfezionamentoRequisiti.Value, new DateTime(dataPerfezionamentoRequisiti.Value.Year, 9, 30)))
                    {
                        if (!Utility.DataSuccessivaA(decorrenzaOriginaria.Value, new DateTime(dataPerfezionamentoRequisiti.Value.Year + 1, 1, 1)))
                        {
                            messaggioVideo = "La decorrenza della pensione deve essere successiva o uguale al " + String.Format("{0:MM/yyyy}", new DateTime(dataPerfezionamentoRequisiti.Value.Year + 1, 1, 1));
                            return false;
                        }
                    }
                    else if (!Utility.DataStrettamenteSuccessivaA(dataPerfezionamentoRequisiti.Value, new DateTime(dataPerfezionamentoRequisiti.Value.Year, 12, 31)))
                    {
                        if (!Utility.DataSuccessivaA(decorrenzaOriginaria.Value, new DateTime(dataPerfezionamentoRequisiti.Value.Year + 1, 4, 1)))
                        {
                            messaggioVideo = "La decorrenza della pensione deve essere successiva o uguale al " + String.Format("{0:MM/yyyy}", new DateTime(dataPerfezionamentoRequisiti.Value.Year + 1, 4, 1));
                            return false;
                        }
                    }
                }
            }

            return true;
        }

        public static bool FS_VerificaEtaTitolarePersonaleViaggianteConPerditaTitoloAbilitante(DateTime? dataPerfezionamentoRequisiti, DateTime? dataNascitaTitolare, char? sessoTitolare,
            out string messaggioVideo)
        {
            messaggioVideo = string.Empty;
            DateTime? dataLimiteInferiore = null;
            DateTime? dataLimiteSuperiore = null;
            Utility.DifferenzaDateTime etaLimiteTitolare = null;

            if (!sessoTitolare.HasValue)
            {
                messaggioVideo = "Il Sesso del Titolare non è valorizzato.";
                return false;
            }

            dataLimiteSuperiore = new DateTime(2007, 12, 31);
            if (!Utility.DataStrettamenteSuccessivaA(dataPerfezionamentoRequisiti.Value, dataLimiteSuperiore.Value))
            {
                switch (sessoTitolare.Value)
                {
                    case 'F':
                        return true;
                    case 'M':
                        etaLimiteTitolare = new Utility.DifferenzaDateTime(60, 0, 0);
                        break;
                }

                if (etaLimiteTitolare != null && Utility.DifferenzaBetweenDate(dataPerfezionamentoRequisiti, dataNascitaTitolare, Utility.TipoAppartenenza.FS) < etaLimiteTitolare)
                {
                    messaggioVideo = "Il titolare non ha raggiunto i requisiti di età al " + String.Format("({0:dd/MM/yyyy})", dataPerfezionamentoRequisiti.Value) +
                        " (requisito " + etaLimiteTitolare.Year + " AA " + etaLimiteTitolare.Month + " MM)";
                    return false;
                }
            }

            dataLimiteInferiore = new DateTime(2008, 1, 1);
            dataLimiteSuperiore = new DateTime(2015, 12, 31);
            if (Utility.DataSuccessivaA(dataPerfezionamentoRequisiti.Value, dataLimiteInferiore.Value) &&
                        !Utility.DataStrettamenteSuccessivaA(dataPerfezionamentoRequisiti.Value, dataLimiteSuperiore.Value))
            {
                switch (sessoTitolare.Value)
                {
                    case 'F':
                        return true;
                    case 'M':
                        etaLimiteTitolare = new Utility.DifferenzaDateTime(60, 0, 0);
                        break;
                }

                if (etaLimiteTitolare != null && Utility.DifferenzaBetweenDate(dataPerfezionamentoRequisiti, dataNascitaTitolare, Utility.TipoAppartenenza.FS) < etaLimiteTitolare)
                {
                    messaggioVideo = "Il titolare non ha raggiunto i requisiti di età al " + String.Format("({0:dd/MM/yyyy})", dataPerfezionamentoRequisiti.Value) +
                        " (requisito " + etaLimiteTitolare.Year + " AA " + etaLimiteTitolare.Month + " MM)";
                    return false;
                }
            }

            dataLimiteInferiore = new DateTime(2016, 1, 1);
            dataLimiteSuperiore = new DateTime(2065, 12, 31);
            if (Utility.DataSuccessivaA(dataPerfezionamentoRequisiti.Value, dataLimiteInferiore.Value) &&
                        !Utility.DataStrettamenteSuccessivaA(dataPerfezionamentoRequisiti.Value, dataLimiteSuperiore.Value))
            {
                etaLimiteTitolare = new Utility.DifferenzaDateTime(60, 0, 0);

                if (Utility.DifferenzaBetweenDate(dataPerfezionamentoRequisiti, dataNascitaTitolare, Utility.TipoAppartenenza.FS) < etaLimiteTitolare)
                {
                    messaggioVideo = "Il titolare non ha raggiunto i requisiti di età al " + String.Format("({0:dd/MM/yyyy})", dataPerfezionamentoRequisiti.Value) +
                        " (requisito " + etaLimiteTitolare.Year + " AA " + etaLimiteTitolare.Month + " MM)";
                    return false;
                }
            }

            return true;
        }

        public static bool FS_GAS_ControlliPerfezionamentoRequisiti(GestionePensione.DatiPensione datiPensione, DateTime? dataPerfRequisiti, DateTime? decorrenzaOriginaria, out string errori)
        {
            errori = string.Empty;
            Utility.TipoDomanda tipoDomanda = Utility.GetTipoDomanda(datiPensione.Gruppo, datiPensione.Prodotto);
            Utility.TipoFondo? tipoFondo = Utility.GetTipoFondoByCategoria(datiPensione.IndConvInt, datiPensione.Gestione, datiPensione.SiglaCategoria);
            if (tipoFondo == Utility.TipoFondo.GAS && tipoDomanda != Utility.TipoDomanda.Ricostituzione)
            {
                //Controllo: per decorrenze inferiori al 2011 la dataPerfReq non deve essere acquisita
                if (dataPerfRequisiti.HasValue && (decorrenzaOriginaria.HasValue && decorrenzaOriginaria.Value.Year < 2011))
                {
                    errori = "La data perfezionamento requisiti non deve essere acquisita.";
                    return false;
                }
                //Condizioni per cui la dataPerf requisiti non deve essere acquisita
                if (dataPerfRequisiti.HasValue && Utility.IsDomandaReversibilita(datiPensione))
                {
                    errori = "La data perfezionamento requisiti non deve essere acquisita.";
                    return false;
                }
                //Condizioni per cui la dataPeff requisiti deve essere acquisita
                if (!dataPerfRequisiti.HasValue && !Utility.IsDomandaReversibilita(datiPensione)
                    && (decorrenzaOriginaria.HasValue && decorrenzaOriginaria.Value.Year >= 2011))
                {
                    errori = "La data perfezionamento requisiti deve essere acquisita.";
                    return false;
                }
                //Condizione di cessazione fondo GAS   
                if (dataPerfRequisiti.HasValue && dataPerfRequisiti > new DateTime(2015, 11, 30))
                {
                    errori = "FONDO GAS SOPPRESSO - LIQUIDARE IN AGO";
                    return false;
                }
            }
            return true;
        }

        /// <summary>
        /// Questo metodo controlla la coerenza dei dati salvati quando si va cambiare la decorrenza.
        /// ATTENZIONE: vengono effettuate delle get all'interno del metodo per eviare get inutili sul salvataggio del titolare.
        /// </summary>
        public static bool FS_ControlsDecorrenzaPostAnteArmonizzazione(GestionePensione.DatiPensione datiPensione, GestioneDanteCausa.DatiDanteCausa datiDanteCausa,
            ref GestioneCalcolo.DatiCalcoloContributivo datiContributivi, ref GestioneCalcolo.DatiCalcoloRetributivo datiRetributivi, ref GestioneDL407.DatiDL407 datiDL407,
            ref List<GestioneDatiServizioUtile.ServizioUtile> lstServizioUtile, ref GestioneFondo.DatiFondo datiFondoGenerici, ref Utility.TipoCalcolo tipoCalcolo, out string messaggioVideo,
            bool? dimissioniAnte97 = null, char? codiceRequisiti2 = null)
        {
            bool ret = true;
            messaggioVideo = string.Empty;
            Utility.TipoAppartenenza? tipoApp = Utility.GetTipoAppartenenza(datiPensione.IndConvInt, datiPensione.Gestione);
            DateTime? decorrenzaAntePostArmonizzazione = Utility.GetDecorrenzaPensioneOrDecorrenzaDantecausa(datiPensione.DecorrenzaOriginaria, datiDanteCausa != null ? datiDanteCausa.DecorrenzaPensione : null);
            if (tipoApp == Utility.TipoAppartenenza.FS)
            {
                Utility.TipoFondo? tipoFondo = Utility.GetTipoFondoByCategoria(datiPensione.IndConvInt, datiPensione.Gestione, datiPensione.SiglaCategoria);
                switch (tipoFondo)
                {
                    case Utility.TipoFondo.EL:
                        {
                            #region Get per Controlli Incrociati
                            if (lstServizioUtile == null)
                                GestioneDatiServizioUtile.GetDatiServizioUtileByIdPensione(datiPensione.Id, out lstServizioUtile);

                            if (datiDL407 == null)
                                GestioneDL407.GetDL407ByIdPensione(datiPensione.Id, out datiDL407);

                            if (datiContributivi == null)
                                GestioneCalcolo.GetCalcoloContributivoByIdPensione(datiPensione.Id, out datiContributivi);

                            if (datiRetributivi == null)
                                GestioneCalcolo.GetCalcoloRetributivoByIdPensione(datiPensione.Id, out datiRetributivi);

                            if (tipoCalcolo == Utility.TipoCalcolo.NonValido)
                                tipoCalcolo = Utility.GetTipoCalcoloById(datiPensione.TipoCalcolo, datiPensione, Utility.GetTipoAppartenenza(datiPensione.IndConvInt, datiPensione.Gestione).GetValueOrDefault());
                            #endregion Get per Controlli Incrociati

                            bool isAnteArmonizzazione = Utility.IsDomandaAnteArmonizzazione(datiPensione, tipoFondo, decorrenzaAntePostArmonizzazione, codiceRequisiti2: codiceRequisiti2, datiFondo: datiFondoGenerici,
                                datiCalcoloRetributivo: datiRetributivi, datiServizioUtile: lstServizioUtile);
                            //Controllo per verificare se ci sono dati post armonizzazione salvati.
                            if (isAnteArmonizzazione)
                            {
                                //ANTE ARMONIZZAZIONE

                                //LiquidazionePensione\DatiGenerici
                                if (!Utility.IsDomandaReversibilita(datiPensione) && tipoCalcolo != Utility.TipoCalcolo.Retributivo && tipoCalcolo != Utility.TipoCalcolo.NonValido)
                                {
                                    messaggioVideo = string.Format("Il tipo calcolo {0} salvato è incompatibile con la decorrenza pensione inserita {1:MM/yyyy}.", tipoCalcolo.ToString(), decorrenzaAntePostArmonizzazione.GetValueOrDefault());
                                    return false;
                                }
                                //DatiCalcolo\DatiCalcolo Retributivi
                                if (!Utility.IsDomandaReversibilita(datiPensione) && datiRetributivi != null && !datiRetributivi.IsDatiCalcoloRetributivoNull())
                                {
                                    messaggioVideo = string.Format("I 'Dati Calcolo' retributivi salvati sono incompatibili con la decorrenza pensione inserita {0:MM/yyyy}.", decorrenzaAntePostArmonizzazione.GetValueOrDefault());
                                    return false;
                                }
                                //DatiCalcolo\DatiCalcolo Contributivo
                                if (!Utility.IsDomandaReversibilita(datiPensione) && datiContributivi != null && !datiContributivi.IsDatiCalcoloContributivoNull())
                                {
                                    messaggioVideo = string.Format("I 'Dati Calcolo' contributivi salvati sono incompatibili con la decorrenza pensione inserita {0:MM/yyyy}.", decorrenzaAntePostArmonizzazione.GetValueOrDefault());
                                    return false;
                                }
                                //MaggiorazioniBenefici\DL407 
                                if (datiDL407 != null && !datiDL407.IsDL407NullForPostArm())
                                {
                                    messaggioVideo = string.Format("I dati salvati in MaggiorazioniBenefici\\DL407 sono incompatibili con la decorrenza pensione {0:MM/yyyy}.", decorrenzaAntePostArmonizzazione.GetValueOrDefault());
                                    return false;
                                }
                            }
                            else
                            {
                                //POST ARMONIZZAZIONE

                                //DatiCalcolo\DatiCalcolo Retributivi
                                if ((lstServizioUtile != null && lstServizioUtile.Count > 0) || (datiFondoGenerici != null && datiFondoGenerici.RetrPondAnnuaAGOLimite.HasValue))
                                {
                                    messaggioVideo = string.Format("I 'Dati Calcolo' salvati sono incompatibili con la decorrenza pensione inserita {0:MM/yyyy}.", decorrenzaAntePostArmonizzazione.GetValueOrDefault());
                                    return false;
                                }
                                //MaggiorazioniBenefici\DL407 
                                if (datiDL407 != null && !datiDL407.IsDL407NullForAnteArm())
                                {
                                    messaggioVideo = string.Format("I dati salvati in MaggiorazioniBenefici\\DL407 sono incompatibili con la decorrenza pensione {0:MM/yyyy}.", decorrenzaAntePostArmonizzazione.GetValueOrDefault());
                                    return false;
                                }
                            }
                        }
                        break;
                    case Utility.TipoFondo.VL:
                        {
                            #region Get per Controlli Incrociati
                            if (lstServizioUtile == null)
                                GestioneDatiServizioUtile.GetDatiServizioUtileByIdPensione(datiPensione.Id, out lstServizioUtile);

                            if (datiContributivi == null)
                                GestioneCalcolo.GetCalcoloContributivoByIdPensione(datiPensione.Id, out datiContributivi);

                            if (datiRetributivi == null)
                                GestioneCalcolo.GetCalcoloRetributivoByIdPensione(datiPensione.Id, out datiRetributivi);

                            if (tipoCalcolo == Utility.TipoCalcolo.NonValido)
                                tipoCalcolo = Utility.GetTipoCalcoloById(datiPensione.TipoCalcolo, datiPensione, Utility.GetTipoAppartenenza(datiPensione.IndConvInt, datiPensione.Gestione).GetValueOrDefault());
                            #endregion Get per Controlli Incrociati

                            bool isAnteArmonizzazione = Utility.IsDomandaAnteArmonizzazione(datiPensione, tipoFondo, decorrenzaAntePostArmonizzazione);
                            //Controllo per verificare se ci sono dati post armonizzazione salvati.
                            if (isAnteArmonizzazione)
                            {
                                //ANTE ARMONIZZAZIONE

                                //LiquidazionePensione\DatiGenerici
                                if (tipoCalcolo != Utility.TipoCalcolo.Retributivo && tipoCalcolo != Utility.TipoCalcolo.NonValido)
                                {
                                    messaggioVideo = string.Format("Il tipo calcolo {0} salvato è incompatibile con la decorrenza pensione inserita {1:MM/yyyy}.", tipoCalcolo.ToString(), decorrenzaAntePostArmonizzazione.GetValueOrDefault());
                                    return false;
                                }
                                //DatiCalcolo\DatiCalcolo Retributivi
                                if (datiRetributivi != null && !datiRetributivi.IsDatiCalcoloRetributivoNull())
                                {
                                    messaggioVideo = string.Format("I 'Dati Calcolo' retributivi salvati sono incompatibili con la decorrenza pensione inserita {0:MM/yyyy}.", decorrenzaAntePostArmonizzazione.GetValueOrDefault());
                                    return false;
                                }
                                //DatiCalcolo\DatiCalcolo Contributivo
                                if (datiContributivi != null && !datiContributivi.IsDatiCalcoloContributivoNull())
                                {
                                    messaggioVideo = string.Format("I 'Dati Calcolo' contributivi salvati sono incompatibili con la decorrenza pensione inserita {0:MM/yyyy}.", decorrenzaAntePostArmonizzazione.GetValueOrDefault());
                                    return false;
                                }
                            }
                            else
                            {
                                //POST ARMONIZZAZIONE

                                //DatiCalcolo\DatiCalcolo Retributivi
                                if (lstServizioUtile != null && lstServizioUtile.Count > 0)
                                {
                                    messaggioVideo = string.Format("I 'Dati Calcolo' salvati sono incompatibili con la decorrenza pensione inserita {0:MM/yyyy}.", decorrenzaAntePostArmonizzazione.GetValueOrDefault());
                                    return false;
                                }
                            }
                        }
                        break;
                    case Utility.TipoFondo.ET:
                        {
                            #region Get per Controlli Incrociati
                            if (datiDL407 == null)
                                GestioneDL407.GetDL407ByIdPensione(datiPensione.Id, out datiDL407);

                            if (datiContributivi == null)
                                GestioneCalcolo.GetCalcoloContributivoByIdPensione(datiPensione.Id, out datiContributivi);

                            if (datiRetributivi == null)
                                GestioneCalcolo.GetCalcoloRetributivoByIdPensione(datiPensione.Id, out datiRetributivi);

                            if (tipoCalcolo == Utility.TipoCalcolo.NonValido)
                                tipoCalcolo = Utility.GetTipoCalcoloById(datiPensione.TipoCalcolo, datiPensione, Utility.GetTipoAppartenenza(datiPensione.IndConvInt, datiPensione.Gestione).GetValueOrDefault());

                            GestioneFondo.DatiFondoET datiFondoET;
                            GestioneFondo.GetFondoETByIdPensione(datiPensione.Id, out datiFondoET);

                            #endregion Get per Controlli Incrociati

                            bool isAnteArmonizzazione = Utility.IsDomandaAnteArmonizzazione(datiPensione, tipoFondo, decorrenzaAntePostArmonizzazione);
                            //Controllo per verificare se ci sono dati post armonizzazione salvati.
                            if (isAnteArmonizzazione)
                            {
                                //ANTE ARMONIZZAZIONE

                                //LiquidazionePensione\DatiGenerici
                                if (tipoCalcolo != Utility.TipoCalcolo.Retributivo && tipoCalcolo != Utility.TipoCalcolo.NonValido)
                                {
                                    messaggioVideo = string.Format("Il tipo calcolo {0} salvato è incompatibile con la decorrenza pensione inserita {1:MM/yyyy}.", tipoCalcolo.ToString(), decorrenzaAntePostArmonizzazione.GetValueOrDefault());
                                    return false;
                                }
                                //DatiCalcolo\DatiCalcolo Retributivi
                                if (datiRetributivi != null && !datiRetributivi.IsDatiCalcoloRetributivoNull())
                                {
                                    messaggioVideo = string.Format("I 'Dati Calcolo' retributivi salvati sono incompatibili con la decorrenza pensione inserita {0:MM/yyyy}.", decorrenzaAntePostArmonizzazione.GetValueOrDefault());
                                    return false;
                                }
                                //DatiCalcolo\DatiCalcolo Contributivo
                                if (datiContributivi != null && !datiContributivi.IsDatiCalcoloContributivoNull())
                                {
                                    messaggioVideo = string.Format("I 'Dati Calcolo' contributivi salvati sono incompatibili con la decorrenza pensione inserita {0:MM/yyyy}.", decorrenzaAntePostArmonizzazione.GetValueOrDefault());
                                    return false;
                                }
                                //MaggiorazioniBenefici\DL407 
                                if (datiDL407 != null && !datiDL407.IsDL407NullForPostArm())
                                {
                                    messaggioVideo = string.Format("I dati salvati in MaggiorazioniBenefici\\DL407 sono incompatibili con la decorrenza pensione {0:MM/yyyy}.", decorrenzaAntePostArmonizzazione.GetValueOrDefault());
                                    return false;
                                }
                                if (datiFondoET != null && !datiFondoET.IsNullAltraPensioneDatiAgo() &&
                                    !Utility.IsVisibleTabAltraPensioneDatiAgo(datiPensione, datiDanteCausa, decorrenzaAntePostArmonizzazione, datiPensione.NaturaPensione))
                                {
                                    messaggioVideo = string.Format("I dati salvati in DatiCalcolo\\Altra Pensione-Dati Ago sono incompatibili con la decorrenza pensione {0:MM/yyyy}.", decorrenzaAntePostArmonizzazione.GetValueOrDefault());
                                    return false;
                                }
                            }
                            else
                            {
                                //POST ARMONIZZAZIONE

                                //MaggiorazioniBenefici\DL407 
                                if (datiDL407 != null && !datiDL407.IsDL407NullForAnteArm())
                                {
                                    messaggioVideo = string.Format("I dati salvati in MaggiorazioniBenefici\\DL407 sono incompatibili con la decorrenza pensione {0:MM/yyyy}.", decorrenzaAntePostArmonizzazione.GetValueOrDefault());
                                    return false;
                                }
                                //DatiCalcolo\Altra Pensione - Dati AGO
                                if (datiFondoET != null && !datiFondoET.IsNullAltraPensioneDatiAgo())
                                {
                                    messaggioVideo = string.Format("I dati salvati in DatiCalcolo\\Altra Pensione-Dati Ago sono incompatibili con la decorrenza pensione {0:MM/yyyy}.", decorrenzaAntePostArmonizzazione.GetValueOrDefault());
                                    return false;
                                }
                            }
                        }
                        break;
                    case Utility.TipoFondo.TT:
                        {
                            #region Get per Controlli Incrociati
                            GestioneFondo.DatiFondoTT datiFondoTT = null;
                            GestioneFondo.GetFondoTTByIdPensione(datiPensione.Id, out datiFondoTT);

                            if (lstServizioUtile == null)
                                GestioneDatiServizioUtile.GetDatiServizioUtileByIdPensione(datiPensione.Id, out lstServizioUtile);

                            if (datiDL407 == null)
                                GestioneDL407.GetDL407ByIdPensione(datiPensione.Id, out datiDL407);

                            if (datiContributivi == null)
                                GestioneCalcolo.GetCalcoloContributivoByIdPensione(datiPensione.Id, out datiContributivi);

                            if (datiRetributivi == null)
                                GestioneCalcolo.GetCalcoloRetributivoByIdPensione(datiPensione.Id, out datiRetributivi);

                            if (tipoCalcolo == Utility.TipoCalcolo.NonValido)
                                tipoCalcolo = Utility.GetTipoCalcoloById(datiPensione.TipoCalcolo, datiPensione, Utility.GetTipoAppartenenza(datiPensione.IndConvInt, datiPensione.Gestione).GetValueOrDefault());
                            #endregion Get per Controlli Incrociati

                            bool isAnteArmonizzazione = Utility.IsDomandaAnteArmonizzazione(datiPensione, tipoFondo, decorrenzaAntePostArmonizzazione, dimissioniAnte97: dimissioniAnte97,
                                                            datiFondoXX: datiFondoTT);
                            //Controllo per verificare se ci sono dati post armonizzazione salvati.
                            if (isAnteArmonizzazione)
                            {
                                //ANTE ARMONIZZAZIONE

                                //LiquidazionePensione\DatiGenerici
                                if (!Utility.IsDomandaReversibilita(datiPensione) && tipoCalcolo != Utility.TipoCalcolo.Retributivo && tipoCalcolo != Utility.TipoCalcolo.NonValido)
                                {
                                    messaggioVideo = string.Format("Il tipo calcolo {0} salvato è incompatibile con la decorrenza pensione inserita {1:MM/yyyy} o con il campo Dimissioni ante 01-07-97.", tipoCalcolo.ToString(), decorrenzaAntePostArmonizzazione.GetValueOrDefault());
                                    return false;
                                }
                                //DatiCalcolo\DatiCalcolo Retributivi
                                if (!Utility.IsDomandaReversibilita(datiPensione) && datiRetributivi != null && !datiRetributivi.IsDatiCalcoloRetributivoNull())
                                {
                                    messaggioVideo = string.Format("I 'Dati Calcolo' retributivi salvati sono incompatibili con la decorrenza pensione inserita {0:MM/yyyy} o con il campo Dimissioni ante 01-07-97.", decorrenzaAntePostArmonizzazione.GetValueOrDefault());
                                    return false;
                                }
                                //DatiCalcolo\DatiCalcolo Contributivo
                                if (!Utility.IsDomandaReversibilita(datiPensione) && datiContributivi != null && !datiContributivi.IsDatiCalcoloContributivoNull())
                                {
                                    messaggioVideo = string.Format("I 'Dati Calcolo' contributivi salvati sono incompatibili con la decorrenza pensione inserita {0:MM/yyyy} o con il campo Dimissioni ante 01-07-97.", decorrenzaAntePostArmonizzazione.GetValueOrDefault());
                                    return false;
                                }
                                //MaggiorazioniBenefici\DL407 
                                if (datiDL407 != null && !datiDL407.IsDL407NullForPostArm())
                                {
                                    messaggioVideo = string.Format("I dati salvati in MaggiorazioniBenefici\\DL407 sono incompatibili con la decorrenza pensione {0:MM/yyyy} o con il campo Dimissioni ante 01-07-97.", decorrenzaAntePostArmonizzazione.GetValueOrDefault());
                                    return false;
                                }
                            }
                            else
                            {
                                //POST ARMONIZZAZIONE

                                //DatiCalcolo\DatiCalcolo Retributivi
                                if ((lstServizioUtile != null && lstServizioUtile.Count > 0) || (datiFondoGenerici != null && datiFondoGenerici.RetrPondAnnuaAGOLimite.HasValue))
                                {
                                    messaggioVideo = string.Format("I 'Dati Calcolo' salvati sono incompatibili con la decorrenza pensione inserita {0:MM/yyyy} o con il campo Dimissioni ante 01-07-97.", decorrenzaAntePostArmonizzazione.GetValueOrDefault());
                                    return false;
                                }
                                //MaggiorazioniBenefici\DL407 
                                if (datiDL407 != null && !datiDL407.IsDL407NullForAnteArm())
                                {
                                    messaggioVideo = string.Format("I dati salvati in MaggiorazioniBenefici\\DL407 sono incompatibili con la decorrenza pensione {0:MM/yyyy} o con il campo Dimissioni ante 01-07-97.", decorrenzaAntePostArmonizzazione.GetValueOrDefault());
                                    return false;
                                }

                                if (datiFondoTT != null && (datiFondoTT.PensioneMensileAl53.HasValue || datiFondoTT.ElementiAccessori.HasValue || datiFondoTT.RetribuzioneSupplementi.HasValue))
                                {
                                    messaggioVideo = string.Format("I 'Dati Calcolo' salvati sono incompatibili con la decorrenza pensione inserita {0:MM/yyyy} o con il campo Dimissioni ante 01-07-97.", decorrenzaAntePostArmonizzazione.GetValueOrDefault());
                                    return false;
                                }
                            }
                        }
                        break;
                }
            }
            return ret;
        }

        public static bool FS_VerificaFinestraMobileVecchiaiaVEL_VET_VTT(GestionePensione.DatiPensione datiPensione, DateTime? decorrenzaOriginaria, DateTime? dataPerfezionamentoRequisiti, string tipoSettimaneBeneficio,
            char? codiceSpecificoTraduzioneSuGP, char? derogaTraduzioneSuGP, out string messaggioVideo)
        {
            messaggioVideo = string.Empty;

            // Per le domande di salvaguardia L.122 dei fondi EL, TT, ET, GAS, DZ, ES, PM, PI, VL non va applicato il confronto tra data di perfezionamento requisiti e decorrenza pensione 
            if (Utility.IsDomandaSalvaguardia122_FS_2011_2012(datiPensione, derogaTraduzioneSuGP))
                return true;

            if (Utility.IsPensioneVecchiaiaOrRicostituzione(datiPensione, codiceSpecificoTraduzioneSuGP) && tipoSettimaneBeneficio == "01" && dataPerfezionamentoRequisiti.HasValue
                && decorrenzaOriginaria.HasValue && !Utility.DataStrettamenteSuccessivaA(decorrenzaOriginaria.Value, new DateTime(2011, 12, 31)))
            {
                Utility.TipoFondo? tipoFondo = Utility.GetTipoFondoByCategoria(datiPensione.IndConvInt, datiPensione.Gestione, datiPensione.SiglaCategoria);
                if (tipoFondo.HasValue)
                {
                    switch (tipoFondo.Value)
                    {
                        case Utility.TipoFondo.EL:
                        case Utility.TipoFondo.ET:
                        case Utility.TipoFondo.TT:
                            Utility.DifferenzaDateTime diff = Utility.DifferenzaBetweenDate(decorrenzaOriginaria, dataPerfezionamentoRequisiti, Utility.GetTipoAppartenenza(datiPensione.IndConvInt, datiPensione.Gestione));
                            if (diff < new Utility.DifferenzaDateTime(1, 0, 0))
                            {
                                messaggioVideo = "La differenza temporale tra il valore del campo “Decorrenza pensione” e il valore del campo “Data di perfezionamento requisiti” deve essere maggiore o uguale a 1 anno";
                                return false;
                            }
                            break;
                    }
                }
            }

            return true;
        }
        #endregion Titolare

        #region Familiari
        public static bool VerificaScadenzaContitolareNipoteNeJ(GestionePensione.DatiPensione datiPensione, List<GestioneFamiliari.Familiare> Lfamiliari, Utility.TipoAppartenenza? tipoAppartenenza, List<GestioneFamiliari.CodMaggFamiliari> listaCodMaggFamiliari, out string messaggioVideo)
        {
            messaggioVideo = string.Empty;

            Utility.TipoFondo? tipoFondo = Utility.GetTipoFondoByCategoria(tipoAppartenenza, datiPensione.SiglaCategoria);

            if (tipoAppartenenza == Utility.TipoAppartenenza.FS && Utility.IsDomandaPensioneSuperstitiOrRicostituzione(datiPensione))
            {
                if (Lfamiliari == null || Lfamiliari.Count == 0)
                    return true;

                if (Lfamiliari.Count > 0 && listaCodMaggFamiliari != null && listaCodMaggFamiliari.Count > 0)
                {
                    List<GestioneFamiliari.Familiare> LNipoti = Lfamiliari.FindAll(x => x.SiglaFamiliare == 'N' || x.SiglaFamiliare == 'J');

                    if (LNipoti != null && LNipoti.Count > 0)
                    {
                        foreach (GestioneFamiliari.Familiare nip in LNipoti)
                        {
                            if (nip.Confermato)
                            {
                                List<GestioneFamiliari.CodMaggFamiliari> listaCodMaggNipoti = listaCodMaggFamiliari.FindAll(x => x.IdAnagrafica == nip.IdAnagrafica);
                                if (listaCodMaggNipoti != null && listaCodMaggNipoti.Count > 0)
                                {
                                    int index = 0;
                                    foreach (GestioneFamiliari.CodMaggFamiliari codMaggNip in listaCodMaggNipoti)
                                    {
                                        index++;
                                        GestioneAnagrafica.DatiAnagrafici datiAnagrafici = null;
                                        GestioneAnagrafica.GetAnagraficaByIdAnagrafica(nip.IdAnagrafica, out datiAnagrafici);
                                        DateTime dataCompare = Utility.FirstDayOfMonth(datiAnagrafici.DataNascita.GetValueOrDefault().AddYears(18).AddMonths(1));

                                        if (index == listaCodMaggNipoti.Count && codMaggNip.Cessazione.HasValue && (Utility.DataStrettamenteSuccessivaA(dataCompare, codMaggNip.Cessazione.Value) || !Utility.DataSuccessivaA(dataCompare, codMaggNip.Cessazione.Value)))
                                        {
                                            messaggioVideo = string.Format("Per il soggetto {0} la data di fine carico deve essere uguale al mese successivo al compimento dei 18 anni", nip.CodiceFiscale);
                                            return false;
                                        }
                                    }
                                }
                            }
                        }
                    }
                }
            }
            return true;
        }

        public static bool VerificaContitolareNipoteO(GestionePensione.DatiPensione datiPensione, List<GestioneFamiliari.Familiare> Lfamiliari, GestioneDanteCausa.DatiDanteCausa datiDanteCausa, out string messaggioVideo)
        {
            messaggioVideo = string.Empty;

            Lfamiliari = Lfamiliari.Where(x => x.SiglaFamiliare == 'O').ToList();

            if (Lfamiliari != null && Lfamiliari.Count() > 0)
            {
                foreach (GestioneFamiliari.Familiare fam in Lfamiliari)
                {
                    if (fam.Confermato)
                    {
                        GestioneAnagrafica.DatiAnagrafici datiAnagrafici = null;
                        GestioneAnagrafica.GetAnagraficaByIdAnagrafica(fam.IdAnagrafica, out datiAnagrafici);

                        if (Utility.DataStrettamenteSuccessivaA(datiAnagrafici.DataNascita.Value, datiDanteCausa.DataMorte.Value))
                        {
                            messaggioVideo = "Il familiare non deve essere nato dopo la morte del dante causa";
                            return false;
                        }
                        if (Utility.DataSuccessivaA(datiAnagrafici.DataNascita.Value.AddYears(18), datiDanteCausa.DataMorte.Value))
                        {
                            messaggioVideo = "Il familiare deve avere compiuto 18 anni alla data morte del dante causa";
                            return false;
                        }
                    }
                }
            }
            return true;
        }

        #endregion Familiari

        #region Supplementi
        /// <summary>
        /// Verifica che per ogni supplemento presente, se la decorrenza del supplemento è diversa da tutte le possibili decorrenze del record fondo 
        ///(Supplementi.DecorrenzaSupplemento != RecordFondo.DecorrenzaValiditaDati) ==> dovrà essere presente il bonus (PensioneFondoDatiGenerici.AttribuzioneBonus = 1)
        /// </summary>
        /// <param name="listDatiSupplementi"></param>
        /// <param name="listaDatiRecordFondo"></param>
        /// <param name="AttribuzioneBonus"></param>
        /// <returns>false se ci si aspetta il bonus ma in realtà non è presente</returns>
        public static bool FS_VerificaSupplementiWithBonus(List<Entity.DatiSupplementi> listDatiSupplementi, List<GestioneRecordFondo.DatiRecordFondo> listaDatiRecordFondo, bool? AttribuzioneBonus,
            char? codiceSpecificoTraduzioneSuGP, Utility.TipoFondo? tipoFondo)
        {
            if (listDatiSupplementi == null || listDatiSupplementi.Count == 0)
                return true;

            //28-05-12: menu supplementi non più visibile per assegno di invalidità
            //if (!String.IsNullOrEmpty(Prodotto) && Prodotto.Trim() == "0011")
            //    return true;

            // Per gli assegni ordinari di invalidità dei fondi EL, ET e TT deve essere bypassato il controllo
            if (tipoFondo.HasValue && (tipoFondo.Value == Utility.TipoFondo.EL || tipoFondo.Value == Utility.TipoFondo.ET || tipoFondo.Value == Utility.TipoFondo.TT) &&
                codiceSpecificoTraduzioneSuGP.HasValue && codiceSpecificoTraduzioneSuGP.Value == 'P')
                return true;

            // Per i fondi VL, ET, PM ed ES è possibile avere dei supplementi in assenza di bonus
            if (tipoFondo.HasValue && (tipoFondo.Value == Utility.TipoFondo.VL || tipoFondo.Value == Utility.TipoFondo.ET || tipoFondo.Value == Utility.TipoFondo.PM || tipoFondo.Value == Utility.TipoFondo.ES))
                return true;

            foreach (Entity.DatiSupplementi suppl in listDatiSupplementi)
            {
                int index = listaDatiRecordFondo.FindIndex(delegate
                    (GestioneRecordFondo.DatiRecordFondo fondo)
                {
                    return (fondo.DecorrenzaValiditaDati.HasValue && DateTime.Compare(fondo.DecorrenzaValiditaDati.Value, suppl.DecorrenzaSupplemento.Value) != 0);
                });
                if (index >= 0)
                {
                    if (!AttribuzioneBonus.HasValue || !AttribuzioneBonus.Value)
                        return false;
                }
            }
            return true;
        }

        /// <summary>
        /// Verifica che se esistono i Supplementi deve essere CodGestioneSupplemento = 1 
        /// </summary>
        /// <param name="listDatiSupplementi"></param>
        /// <param name="fondoDatiGenerici"></param>
        /// <returns>false se in presenza di supplementi il CodiceSpecifico != 'P' o se CodGestioneSupplemento != 1</returns>
        public static bool FS_VerificaSupplementiCodiceSpecificoCodiceGestione(GestionePensione.DatiPensione datiPensione, List<Entity.DatiSupplementi> listDatiSupplementi, bool? attribuzioneBonus, char? codiceSpecificoTraduzioneSuGP,
            Utility.TipoFondo? tipoFondo, out string msgVideo)
        {
            msgVideo = string.Empty;
            if (listDatiSupplementi == null || listDatiSupplementi.Count == 0)
                return true;

            //28-05-12: menu supplementi non più visibile per assegno di invalidità
            //if ((!fondoDatiGenerici.CodiceSpecifico.HasValue || fondoDatiGenerici.CodiceSpecifico.Value.ToString().ToUpperInvariant() != "P") && (!fondoDatiGenerici.AttribuzioneBonus.HasValue || !fondoDatiGenerici.AttribuzioneBonus.Value))
            //{
            //    msgVideo = "Non è possibile inserire supplementi se non si è in presenza di bonus o se il codice specifico è diverso da P";
            //    return false;
            //}

            // Per gli assegni ordinari di invalidità dei fondi EL, ET e TT deve essere bypassato il controllo
            if (tipoFondo.HasValue && (((tipoFondo.Value == Utility.TipoFondo.EL || tipoFondo.Value == Utility.TipoFondo.ET || tipoFondo.Value == Utility.TipoFondo.TT) &&
                codiceSpecificoTraduzioneSuGP.HasValue && codiceSpecificoTraduzioneSuGP.Value == 'P') || tipoFondo.Value == Utility.TipoFondo.PM))
                return true;

            // Per i fondi VL e ET ed ES è possibile avere dei supplementi in assenza di bonus
            if (!(tipoFondo.HasValue && (tipoFondo.Value == Utility.TipoFondo.VL || tipoFondo.Value == Utility.TipoFondo.ET || tipoFondo.Value == Utility.TipoFondo.ES)) &&
                (!attribuzioneBonus.HasValue || !attribuzioneBonus.Value))
            {
                msgVideo = "Non è possibile inserire supplementi se non si è in presenza di bonus";
                return false;
            }

            List<string> listaCodiciAmmessi = tipoFondo.HasValue && (tipoFondo == Utility.TipoFondo.ET || tipoFondo == Utility.TipoFondo.ES)? (Utility.IsRicostituzione(datiPensione.Gruppo) ? new List<string> { "1", "2", "3", "4", "I", "M", "N", "P" } : new List<string> { "1", "2", "3", "4" }) : new List<string> { "1" };

            int index = listDatiSupplementi.FindIndex(delegate
                (Entity.DatiSupplementi suppl)
            {
                return (String.IsNullOrEmpty(suppl.CodGestioneSupplemento) || !listaCodiciAmmessi.Contains(suppl.CodGestioneSupplemento.Trim()));
            });
            if (index >= 0)
            {
                msgVideo = string.Format("Non è possibile inserire supplementi con codice gestione diverso da {0}", string.Join(", ", listaCodiciAmmessi.ToArray()));
                return false;
            }

            return true;
        }

        /// <summary>
        /// Il controllo riguarda la data di decorrenza del supplemento: è consentito inserire un supplemento solamente dopo 5 anni dalla decorrenza della pensione o del precedente supplemento.
        /// È consentita un’ unica eccezione, per cui è possibile inserire il supplemento dopo 2 anni dal precedente supplemento  o dalla decorrenza della pensione.
        /// </summary>
        /// <param name="listDatiSupplementi"></param>
        /// <param name="decorrenzaOriginaria"></param>
        /// <param name="messaggioVideo"></param>
        /// <returns></returns>
        public static bool FS_VerificaSupplementiDecorrenza(List<Entity.DatiSupplementi> listDatiSupplementi, DateTime? decorrenzaPensioneOrDiretta, GestionePensione.DatiPensione datiPensione, GestioneDanteCausa.DatiDanteCausa datiDanteCausa, out string messaggioVideo)
        {
            messaggioVideo = string.Empty;
            DateTime? appData = decorrenzaPensioneOrDiretta;
            bool flagEccezione = false;
            int anniDifferenza = 0;
            //ENG - MEMO 50/2023
            GestioneControlliDinamici.ControlloDinamico ctrl = null;
            GestioneControlliDinamici.GetControlloDinamicoByNomeControllo("AbilitazioneMemo50_2023", out ctrl);


            //ENG - RIC REVERSIBILITA 024: implementazione flusso per riconoscere le reversibilità "vecchie" 
            GestioneLavorazione.DatiLavorazione datiLavorazione = null;
            GestioneLavorazione.GetLavorazioneByIdPensione(datiPensione.Id, out datiLavorazione);

            if (!appData.HasValue)
            {
                messaggioVideo = "La decorrenza pensione non è valorizzata.";
                return false;
            }

            if (!(((ctrl != null && ctrl.ValoreControllo == "SI" && Utility.IsRicostituzione_MotiviContributivi(datiPensione) && datiPensione.Tipo == "0001") || Utility.IsRicostituzione_PerVariazioneDatiSupplemento(datiPensione)) && !Utility.IsDomandaINPDAP(datiPensione.Gestione)))
            {
                if (listDatiSupplementi != null && listDatiSupplementi.Count > 0)
                {
                    List<DateTime?> listaDecorrenze = listDatiSupplementi.GroupBy(x => x.DecorrenzaSupplemento).Select(x => x.First()).Select(x => x.DecorrenzaSupplemento).OrderBy(x => x).ToList();
                    Utility.TipoFondo? tipoFondo = Utility.GetTipoFondoByCategoria(datiPensione.IndConvInt, datiPensione.Gestione, datiPensione.SiglaCategoria);

                    DateTime? primaDecorrenza = listaDecorrenze.First();
                    anniDifferenza = (primaDecorrenza.Value - Utility.FirstDayOfMonth(appData.Value)).Days / 365;
                    if (anniDifferenza < 2)
                    {
                        foreach (Entity.DatiSupplementi supplemento in listDatiSupplementi)
                        {
                            if (!(tipoFondo.HasValue && tipoFondo == Utility.TipoFondo.ET && supplemento.QuotaSupplemento != null && supplemento.QuotaSupplemento == 'A' && supplemento.TipoSupplemento.HasValue && supplemento.TipoSupplemento.Value == 'R' && supplemento.CodGestioneSupplemento != null && supplemento.CodGestioneSupplemento == "1"))
                            {
                                if (primaDecorrenza.Value != Utility.FirstDayOfMonth(datiPensione.DecorrenzaOriginaria.GetValueOrDefault()) &&
                                    (datiDanteCausa == null || datiDanteCausa.DecorrenzaPensione == null || primaDecorrenza.Value != Utility.FirstDayOfMonth(datiDanteCausa.DecorrenzaPensione.GetValueOrDefault())))
                                {
                                    messaggioVideo = "E' consentito inserire un supplemento solamente dopo 5 anni dalla decorrenza della pensione o dal precedente supplemento (" + String.Format("{0:MM/yyyy}", appData) + ") con un'unica eccezione a 2 anni.";
                                    return false;
                                }
                                else
                                    listaDecorrenze.RemoveAt(0);
                            }
                        }
                    }
                    foreach (DateTime? decorrenzaSupplemento in listaDecorrenze)
                    {
                        if (decorrenzaSupplemento.HasValue)
                        {
                            anniDifferenza = (decorrenzaSupplemento.Value - Utility.FirstDayOfMonth(appData.Value)).Days / 365;
                            {
                                if (anniDifferenza < 2)
                                {
                                    foreach (Entity.DatiSupplementi supplemento in listDatiSupplementi)
                                    {
                                        if (!(tipoFondo.HasValue && tipoFondo == Utility.TipoFondo.ET && supplemento.QuotaSupplemento != null && supplemento.QuotaSupplemento == 'A' && supplemento.TipoSupplemento.HasValue && supplemento.TipoSupplemento.Value == 'R' && supplemento.CodGestioneSupplemento != null && supplemento.CodGestioneSupplemento == "1"))
                                        {
                                            if (decorrenzaSupplemento != Utility.FirstDayOfMonth(datiPensione.DecorrenzaOriginaria.GetValueOrDefault()) &&
                                        !(Utility.IsDomandaReversibilitaOrRicostituzione(datiPensione, datiDanteCausa, datiLavorazione) && decorrenzaSupplemento == Utility.FirstDayOfMonth(datiPensione.DecorrenzaOriginaria.Value)))
                                            {
                                                messaggioVideo = "E' consentito inserire un supplemento solamente dopo 5 anni dalla decorrenza della pensione o dal precedente supplemento (" + String.Format("{0:MM/yyyy}", appData) + ") con un'unica eccezione a 2 anni.";
                                                return false;
                                            }
                                        }
                                    }
                                }
                            }

                            if (anniDifferenza >= 2 && anniDifferenza < 5)
                            {
                                if (flagEccezione)
                                {
                                    messaggioVideo = "E' consentito un unico supplemento dopo 2 anni dalla decorrenza della pensione o dal precedente supplemento (" + String.Format("{0:MM/yyyy}", appData) + "). " +
                                        "Il successivo supplemento deve essere inserito dopo 5 anni dal precedente.";
                                    return false;
                                }
                                else
                                    flagEccezione = true;
                            }
                        }

                        appData = decorrenzaSupplemento;
                    }
                }
            }
            return true;
        }

        //ENG - MEMO 50/2023
        //Per le ric Contributive con tipo 0001 e 0193 è consentito l’inserimento di una nuova registrazione esclusivamente con pari decorrenza rispetto a quella di un supplemento già esistente
        public static bool FS_VerificaSupplementiDecorrenzaRicContributive(List<Entity.DatiSupplementi> listDatiSupplementi, GestionePensione.DatiPensione datiPensione, out string messaggioVideo)
        {
            messaggioVideo = string.Empty;
            Utility.TipoFondo? tipoFondo = Utility.GetTipoFondoByCategoria(datiPensione.IndConvInt, datiPensione.Gestione, datiPensione.SiglaCategoria);

            if (listDatiSupplementi != null && listDatiSupplementi.Count > 0)
            {
                GestioneControlliDinamici.ControlloDinamico ctrl = null;
                GestioneControlliDinamici.GetControlloDinamicoByNomeControllo("AbilitazioneMemo50_2023", out ctrl);

                if (!Utility.IsDomandaINPDAP(datiPensione.Gestione) && ((ctrl != null && ctrl.ValoreControllo == "SI" &&
                    (Utility.IsRicostituzione_MotiviContributivi(datiPensione) && datiPensione.Tipo == "0001")) || Utility.IsRicostituzione_PerVariazioneDatiSupplemento(datiPensione)))
                {
                    List<DatiSupplementi> listaSupplementiDaPrelievo = listDatiSupplementi.FindAll(x => x.IsFromPrelievo);
                    if (listaSupplementiDaPrelievo != null && listaSupplementiDaPrelievo.Count() > 0)
                    {
                        List<DateTime?> listaDecorrenzeDaPrelievo = listaSupplementiDaPrelievo.GroupBy(x => x.DecorrenzaSupplemento).Select(x => x.First()).Select(x => x.DecorrenzaSupplemento).ToList();
                        List<char> listaQuoteDaPrelievo = listaSupplementiDaPrelievo.GroupBy(x => x.QuotaSupplemento.GetValueOrDefault()).Select(x => x.First()).Select(x => x.QuotaSupplemento.GetValueOrDefault()).ToList();
                        List<DatiSupplementi> listaSupplementiRetributiviNoPrelievo = listDatiSupplementi.FindAll(x => !x.IsFromPrelievo && x.TipoSupplemento == 'R');
                        List<DatiSupplementi> listaSupplementiContributiviNoPrelievo = listDatiSupplementi.FindAll(x => !x.IsFromPrelievo && x.TipoSupplemento == 'C');
                        List<DatiSupplementi> listaSupplementiNoPrelievoTipoD = listDatiSupplementi.FindAll(x => !x.IsFromPrelievo && x.TipoSupplemento == 'D');

                        if (tipoFondo.HasValue && tipoFondo == Utility.TipoFondo.ET && Utility.IsRicostituzione_PerVariazioneDatiSupplemento(datiPensione))
                        {
                            if (listaSupplementiRetributiviNoPrelievo != null && listaSupplementiRetributiviNoPrelievo.Count() > 0)
                            {
                                foreach (DatiSupplementi supplemento in listaSupplementiRetributiviNoPrelievo)
                                {
                                    if (listaDecorrenzeDaPrelievo != null && listaDecorrenzeDaPrelievo.Count() > 0 && !listaDecorrenzeDaPrelievo.Contains(supplemento.DecorrenzaSupplemento) && listaQuoteDaPrelievo.Contains(supplemento.QuotaSupplemento.GetValueOrDefault()))
                                    {
                                        messaggioVideo = "L'inserimento di un nuovo supplemento è consentito solo per le domande di Ricostituzione per supplemento";
                                        return false;
                                    }
                                }
                            }

                            if (listaSupplementiContributiviNoPrelievo != null && listaSupplementiContributiviNoPrelievo.Count() > 0)
                            {
                                foreach (DatiSupplementi supplemento in listaSupplementiContributiviNoPrelievo)
                                {
                                    if (listaDecorrenzeDaPrelievo != null && listaDecorrenzeDaPrelievo.Count() > 0 && !listaDecorrenzeDaPrelievo.Contains(supplemento.DecorrenzaSupplemento) && listaQuoteDaPrelievo.Contains(supplemento.QuotaSupplemento.GetValueOrDefault()))
                                    {
                                        messaggioVideo = "L'inserimento di un nuovo supplemento è consentito solo per le domande di Ricostituzione per supplemento";
                                        return false;
                                    }
                                }
                            }

                            if (listaSupplementiNoPrelievoTipoD != null && listaSupplementiNoPrelievoTipoD.Count() > 0)
                            {
                                foreach (DatiSupplementi supplemento in listaSupplementiNoPrelievoTipoD)
                                {
                                    if (listaDecorrenzeDaPrelievo != null && listaDecorrenzeDaPrelievo.Count() > 0 && !listaDecorrenzeDaPrelievo.Contains(supplemento.DecorrenzaSupplemento) && listaQuoteDaPrelievo.Contains(supplemento.QuotaSupplemento.GetValueOrDefault()))
                                    {
                                        messaggioVideo = "L'inserimento di un nuovo supplemento è consentito solo per le domande di Ricostituzione per supplemento";
                                        return false;
                                    }
                                }
                            }

                            List<DatiSupplementi> listaSupplementiNoPrelievo = listDatiSupplementi.FindAll(x => !x.IsFromPrelievo);
                            foreach (DatiSupplementi supplemento in listaSupplementiNoPrelievo)
                            {
                                if (!listaQuoteDaPrelievo.Contains(supplemento.QuotaSupplemento.GetValueOrDefault()))
                                {
                                    messaggioVideo = "L'inserimento di un nuovo supplemento (Quota B) o nuova riliquidazione (QUOTA A) è consentito solo se già presente dal prelievo";
                                    return false;
                                }
                            }
                        }
                        else
                        {
                            if (listaSupplementiRetributiviNoPrelievo != null && listaSupplementiRetributiviNoPrelievo.Count() > 0)
                            {
                                foreach (DatiSupplementi supplemento in listaSupplementiRetributiviNoPrelievo)
                                {
                                    if (listaDecorrenzeDaPrelievo != null && listaDecorrenzeDaPrelievo.Count() > 0 && !listaDecorrenzeDaPrelievo.Contains(supplemento.DecorrenzaSupplemento))
                                    {
                                        messaggioVideo = "L'inserimento di un nuovo supplemento è consentito solo per le domande di Ricostituzione per supplemento";
                                        return false;
                                    }
                                }
                            }

                            if (listaSupplementiContributiviNoPrelievo != null && listaSupplementiContributiviNoPrelievo.Count() > 0)
                            {
                                foreach (DatiSupplementi supplemento in listaSupplementiContributiviNoPrelievo)
                                {
                                    if (listaDecorrenzeDaPrelievo != null && listaDecorrenzeDaPrelievo.Count() > 0 && !listaDecorrenzeDaPrelievo.Contains(supplemento.DecorrenzaSupplemento))
                                    {
                                        messaggioVideo = "L'inserimento di un nuovo supplemento è consentito solo per le domande di Ricostituzione per supplemento";
                                        return false;
                                    }
                                }
                            }

                            if (listaSupplementiNoPrelievoTipoD != null && listaSupplementiNoPrelievoTipoD.Count() > 0)
                            {
                                foreach (DatiSupplementi supplemento in listaSupplementiNoPrelievoTipoD)
                                {
                                    if (listaDecorrenzeDaPrelievo != null && listaDecorrenzeDaPrelievo.Count() > 0 && !listaDecorrenzeDaPrelievo.Contains(supplemento.DecorrenzaSupplemento))
                                    {
                                        messaggioVideo = "L'inserimento di un nuovo supplemento è consentito solo per le domande di Ricostituzione per supplemento";
                                        return false;
                                    }
                                }
                            }
                        }
                    }
                }
            }

            return true;
        }

        #endregion Supplementi

        #region TipoCalcolo

        public static bool FS_VerificaCoerenzaTipoCalcoloDecPensione(DateTime? decorrenzaOriginaria, Utility.TipoCalcolo tipoCalcolo, out string msgVideo)
        {
            msgVideo = string.Empty;

            if (decorrenzaOriginaria.HasValue)
            {
                if (!Utility.DataSuccessivaA(decorrenzaOriginaria.Value, new DateTime(2012, 2, 1)) && tipoCalcolo == Utility.TipoCalcolo.RetributivoMonti)
                {
                    msgVideo = "Il tipo calcolo selezionato non è compatibile con la decorrenza originaria. Modificare il tipo calcolo o verificare la decorrenza originaria";
                    return false;
                }
            }
            return true;
        }

        public static bool FS_VerificaCoerenzaTipoCalcolo(DateTime? decorrenzaOriginaria, DateTime? FineAssicurazione, Utility.TipoCalcolo tipoCalcolo, string gruppo, string prodotto, out string msgVideo)
        {
            msgVideo = string.Empty;

            if (!FS_VerificaCoerenzaTipoCalcoloDecPensione(decorrenzaOriginaria, tipoCalcolo, out msgVideo))
                return false;

            if (gruppo != "0002" || prodotto != "0012")
            {
                if (FineAssicurazione.HasValue)
                {
                    if ((Utility.DataSuccessivaA(FineAssicurazione.Value, new DateTime(2012, 1, 1)) && tipoCalcolo == Utility.TipoCalcolo.Retributivo) ||
                        (!Utility.DataSuccessivaA(FineAssicurazione.Value, new DateTime(2012, 1, 1)) && tipoCalcolo == Utility.TipoCalcolo.RetributivoMonti))
                    {
                        msgVideo = "Il tipo calcolo selezionato non è compatibile con la data di ultimo versamento. Modificare il tipo calcolo o verificare la data di ultimo versamento";
                        return false;
                    }
                }
                else if (tipoCalcolo == Utility.TipoCalcolo.RetributivoMonti)
                {
                    msgVideo = "Il tipo calcolo selezionato non è compatibile con la data di ultimo versamento. Modificare il tipo calcolo o verificare la data di ultimo versamento";
                    return false;
                }
            }

            return true;
        }

        public static bool FS_VerificaCoerenzaRetrAGOAnnua(decimal? RetribuzioneSettimanaleAgoQuotaA, decimal? RetribuzioneSettimanaleAgoQuotaB,
            Utility.TipoCalcolo tipoCalcolo, out string messaggioVideo)
        {
            messaggioVideo = string.Empty;

            if (tipoCalcolo == Utility.TipoCalcolo.Misto)
            {
                if (!RetribuzioneSettimanaleAgoQuotaA.HasValue && !RetribuzioneSettimanaleAgoQuotaB.HasValue)
                {
                    messaggioVideo = "Per il tipo calcolo " + tipoCalcolo.ToString() + " è obbligatorio l'inserimento " +
                        " della Retribuzione settimanale AGO quota A o B sul tab 'Dati Assicurativi'";
                    return false;
                }
            }
            else if (tipoCalcolo == Utility.TipoCalcolo.Retributivo || tipoCalcolo == Utility.TipoCalcolo.RetributivoMonti)
            {
                if (!RetribuzioneSettimanaleAgoQuotaA.HasValue)
                {
                    messaggioVideo = "La Retribuzione settimanale AGO quota A sul tab 'Dati Assicurativi' è obbligatoria per il tipo calcolo " + tipoCalcolo.ToString();
                    return false;
                }
            }

            return true;
        }
        #endregion TipoCalcolo

        #region Maggiorazioni/Benefici
        public static bool FS_ControlsTipoBeneficioArt24Comma15Bis(GestionePensione.DatiPensione datiPensione, string tipoSettimaneBeneficio, int? nSettimaneBeneficio, DateTime? decorrenzaOriginaria,
            string naturaPensione, char? sessoTitolare, DateTime? dataNascitaTitolare, char? codiceSpecificoTraduzioneSuGP, GestioneCalcolo.DatiCalcoloRetributivo datiRetributivi,
            List<GestioneCalcolo.DatiCalcoloContributivo> listaDatiContributivi, List<GestioneDatiServizioUtile.ServizioUtile> listaServizioUtile,
            List<GestioneRecordDatiFondoINPDAP.RecordDatiFondoINPDAP> listaRecordDatiFondoINPDAP, Object objectFondoXX, int? settimaneUtiliDiritto, out string messaggioVideo)
        {
            messaggioVideo = string.Empty;

            if (tipoSettimaneBeneficio == "05")
            {
                Utility.TipoAppartenenza? tipoAppartenenza = Utility.GetTipoAppartenenza(datiPensione.IndConvInt, datiPensione.Gestione);
                Utility.TipoFondo? tipoFondo = Utility.GetTipoFondoByCategoria(tipoAppartenenza, datiPensione.SiglaCategoria);
                bool isRipristino = Utility.IsDomandaRipristino(datiPensione) != null ? (bool)Utility.IsDomandaRipristino(datiPensione) : false;
                int sommaSettimaneUtiliAlDiritto = FS_GetNumeroSettimane(datiPensione, datiRetributivi, listaDatiContributivi, listaServizioUtile, Utility.IsDomandaINPDAP(datiPensione.Gestione),
                                                                         listaRecordDatiFondoINPDAP, tipoFondo, settimaneUtiliDiritto, objectFondoXX);

                if (!isRipristino && !GestioneCrossControls.ALL_IsTipoBeneficioArt24Comma15BisAmmesso(datiPensione, codiceSpecificoTraduzioneSuGP, decorrenzaOriginaria, naturaPensione, sessoTitolare,
                    dataNascitaTitolare, sommaSettimaneUtiliAlDiritto))
                {
                    messaggioVideo = "Il Tipo Beneficio non è corretto. Non sono presenti i requisiti di cui alla circolare 35/2012.";
                    return false;
                }

                if (nSettimaneBeneficio.GetValueOrDefault() > 0)
                {
                    messaggioVideo = "Il Numero settimane beneficio non è ammesso.";
                    return false;
                }
            }

            return true;
        }
        #endregion Maggiorazioni/Benefici

        public static int FS_GetNumeroSettimane(GestionePensione.DatiPensione datiPensione, GestioneCalcolo.DatiCalcoloRetributivo datiRetributivi, List<GestioneCalcolo.DatiCalcoloContributivo> listaDatiContributivi,
            List<GestioneDatiServizioUtile.ServizioUtile> listaServizioUtile, bool isINPDAP, List<GestioneRecordDatiFondoINPDAP.RecordDatiFondoINPDAP> listaRecordDatiFondoINPDAP, Utility.TipoFondo? tipoFondo,
            int? settimaneUtiliDiritto, object objectFondoXX)
        {
            //ENG - Memo 123/2024
            GestioneControlliDinamici.ControlloDinamico ctrlMemo123_2024 = null;
            GestioneControlliDinamici.GetControlloDinamicoByNomeControllo("AbilitazioneRIC_TRFMemo123_2024", out ctrlMemo123_2024);

            //ENG - Memo 123/2024
            GestioneControlliDinamici.ControlloDinamico ctrlMemo123_2024OpzioneContrib = null;
            GestioneControlliDinamici.GetControlloDinamicoByNomeControllo("AbilitazioneRIC_TRFMemo123_2024OpzioneContrib", out ctrlMemo123_2024OpzioneContrib);

            decimal coefficienteAnni = 52;
            decimal coefficienteMesi = 4.333M;
            decimal coefficienteGiorni = 6.923M;

            decimal sommaSettimaneUtiliAlDirittoApp = 0;

            if (isINPDAP)
            {
                //ENG - 024/INPDAP: bisogna considerare solo gli anni per calcolare le settimane
                if (Utility.IsDomandaQuota100(datiPensione) || Utility.IsDomandaQuota102(datiPensione) || Utility.IsDomandaAnticipataFlessibile(datiPensione) ||
                    Utility.IsDomandaAnticipataFlessibileOpzioneContributivo(datiPensione) || Utility.IsOpzioneDonna_Legge197_2022_Art1_Comma292_LetteraA(datiPensione, true, true) ||
                    Utility.IsOpzioneDonna_Legge197_2022_Art1_Comma292_LetteraB(datiPensione, true, true) || Utility.IsOpzioneDonna_Legge197_2022_Art1_Comma292_LetteraC(datiPensione, true, true) ||
                    Utility.IsRicOpzioneDonna_Legge197_2022_Art1_Comma292_LetteraA(datiPensione) || Utility.IsRicOpzioneDonna_Legge197_2022_Art1_Comma292_LetteraB(datiPensione) ||
                    Utility.IsRicOpzioneDonna_Legge197_2022_Art1_Comma292_LetteraC(datiPensione) ||
                    Utility.IsDomandaSperimentaleDonna_DL_4_2019OrRicostituzione(datiPensione) ||
                    Utility.IsDomandaTipoContributivo(datiPensione, true, false) || (!Utility.IsRicostituzione(datiPensione.Gruppo) && !Utility.IsRiaperturaDomanda(datiPensione.Id) && (Utility.IsDomandaAnticipataFlessibileLeggeBilancio2024(datiPensione) || Utility.IsDomandaAnticipataFlessibileOpzioneContributivoLeggeBilancio2024(datiPensione))) ||
                    ((Utility.IsRicostituzione(datiPensione.Gruppo) || Utility.IsRiaperturaDomanda(datiPensione.Id)) && ((ctrlMemo123_2024 != null && ctrlMemo123_2024.ValoreControllo == "SI" && Utility.IsDomandaAnticipataFlessibileLeggeBilancio2024(datiPensione)) || (ctrlMemo123_2024OpzioneContrib != null && ctrlMemo123_2024OpzioneContrib.ValoreControllo == "SI" && Utility.IsDomandaAnticipataFlessibileOpzioneContributivoLeggeBilancio2024(datiPensione)))))
                {
                    sommaSettimaneUtiliAlDirittoApp += listaRecordDatiFondoINPDAP != null ? listaRecordDatiFondoINPDAP.Sum(x => x.ServizioUtileDirittoAA.GetValueOrDefault() * coefficienteAnni) : 0;
                    if (Utility.IsDomandaOrganizzazioniInternazionali(datiPensione)) // Memo 79
                        sommaSettimaneUtiliAlDirittoApp += listaRecordDatiFondoINPDAP != null ? listaRecordDatiFondoINPDAP.Sum(x => x.ServizioUtileDirittoOIAA.GetValueOrDefault() * coefficienteAnni) : 0;
                }
                else if (datiPensione.Gruppo == "0001" && datiPensione.Prodotto == "0001" && datiPensione.Tipo == "0001")
                {
                    sommaSettimaneUtiliAlDirittoApp += listaRecordDatiFondoINPDAP != null ? listaRecordDatiFondoINPDAP.Sum(x => x.ServizioUtileDirittoAA.GetValueOrDefault() * coefficienteAnni +
                          x.ServizioUtileDirittoMM.GetValueOrDefault() * coefficienteMesi) : 0;
                    if (Utility.IsDomandaOrganizzazioniInternazionali(datiPensione))
                    {
                        sommaSettimaneUtiliAlDirittoApp += listaRecordDatiFondoINPDAP != null ? listaRecordDatiFondoINPDAP.Sum(x => x.ServizioUtileDirittoOIAA.GetValueOrDefault() * coefficienteAnni +
                          x.ServizioUtileDirittoOIMM.GetValueOrDefault() * coefficienteMesi) : 0;
                    }
                }
                else
                {
                    sommaSettimaneUtiliAlDirittoApp += listaRecordDatiFondoINPDAP != null ? listaRecordDatiFondoINPDAP.Sum(x => x.ServizioUtileDirittoAA.GetValueOrDefault() * coefficienteAnni +
                            x.ServizioUtileDirittoMM.GetValueOrDefault() * coefficienteMesi +
                            x.ServizioUtileDirittoGG.GetValueOrDefault() / coefficienteGiorni) : 0;
                    if (Utility.IsDomandaOrganizzazioniInternazionali(datiPensione))
                    {
                        sommaSettimaneUtiliAlDirittoApp += listaRecordDatiFondoINPDAP != null ? listaRecordDatiFondoINPDAP.Sum(x => x.ServizioUtileDirittoOIAA.GetValueOrDefault() * coefficienteAnni +
                            x.ServizioUtileDirittoOIMM.GetValueOrDefault() * coefficienteMesi +
                            x.ServizioUtileDirittoOIGG.GetValueOrDefault() / coefficienteGiorni) : 0;
                    }
                }
            }
            else if (tipoFondo.HasValue)
            {
                switch (tipoFondo.Value)
                {
                    case Utility.TipoFondo.FS:
                        List<GestioneFondo.DatiFondoFST> listaDatiFondoFS = objectFondoXX as List<GestioneFondo.DatiFondoFST>;
                        //ENG - 024/INPDAP: bisogna considerare solo gli anni per calcolare le settimane
                        if (Utility.IsDomandaQuota100(datiPensione) || Utility.IsDomandaQuota102(datiPensione) || Utility.IsDomandaAnticipataFlessibile(datiPensione) ||
                            Utility.IsDomandaAnticipataFlessibileOpzioneContributivo(datiPensione) || Utility.IsOpzioneDonna_Legge197_2022_Art1_Comma292_LetteraA(datiPensione, true, true) ||
                            Utility.IsOpzioneDonna_Legge197_2022_Art1_Comma292_LetteraB(datiPensione, true, true) || Utility.IsOpzioneDonna_Legge197_2022_Art1_Comma292_LetteraC(datiPensione, true, true) ||
                            Utility.IsRicOpzioneDonna_Legge197_2022_Art1_Comma292_LetteraA(datiPensione) || Utility.IsRicOpzioneDonna_Legge197_2022_Art1_Comma292_LetteraB(datiPensione) ||
                            Utility.IsRicOpzioneDonna_Legge197_2022_Art1_Comma292_LetteraC(datiPensione) ||
                            Utility.IsDomandaSperimentaleDonna_DL_4_2019OrRicostituzione(datiPensione) ||
                            Utility.IsDomandaTipoContributivo(datiPensione, true, false) || (!Utility.IsRicostituzione(datiPensione.Gruppo) && !Utility.IsRiaperturaDomanda(datiPensione.Id) && (Utility.IsDomandaAnticipataFlessibileLeggeBilancio2024(datiPensione) || Utility.IsDomandaAnticipataFlessibileOpzioneContributivoLeggeBilancio2024(datiPensione))) ||
                            ((Utility.IsRicostituzione(datiPensione.Gruppo) || Utility.IsRiaperturaDomanda(datiPensione.Id)) && ((ctrlMemo123_2024 != null && ctrlMemo123_2024.ValoreControllo == "SI" && Utility.IsDomandaAnticipataFlessibileLeggeBilancio2024(datiPensione)) || (ctrlMemo123_2024OpzioneContrib != null && ctrlMemo123_2024OpzioneContrib.ValoreControllo == "SI" && Utility.IsDomandaAnticipataFlessibileOpzioneContributivoLeggeBilancio2024(datiPensione)))))
                        {
                            sommaSettimaneUtiliAlDirittoApp += listaDatiFondoFS != null ? listaDatiFondoFS.Sum(x => x.ServizioUtileDirittoAA.GetValueOrDefault() * coefficienteAnni) : 0;
                            if (Utility.IsDomandaOrganizzazioniInternazionali(datiPensione))
                                sommaSettimaneUtiliAlDirittoApp += listaDatiFondoFS != null ? listaDatiFondoFS.Sum(x => x.ServizioUtileDirittoOIAA.GetValueOrDefault() * coefficienteAnni) : 0;
                        }
                        else if (datiPensione.Gruppo == "0001" && datiPensione.Prodotto == "0001" && datiPensione.Tipo == "0001")
                        {
                            sommaSettimaneUtiliAlDirittoApp += listaDatiFondoFS != null ? listaDatiFondoFS.Sum(x => x.ServizioUtileDirittoAA.GetValueOrDefault() * coefficienteAnni +
                                x.ServizioUtileDirittoMM.GetValueOrDefault() * coefficienteMesi) : 0;
                            if (Utility.IsDomandaOrganizzazioniInternazionali(datiPensione))
                            {
                                sommaSettimaneUtiliAlDirittoApp += listaDatiFondoFS != null ? listaDatiFondoFS.Sum(x => x.ServizioUtileDirittoOIAA.GetValueOrDefault() * coefficienteAnni +
                                    x.ServizioUtileDirittoOIMM.GetValueOrDefault() * coefficienteMesi) : 0;
                            }
                        }
                        else
                        {
                            sommaSettimaneUtiliAlDirittoApp += listaDatiFondoFS != null ? listaDatiFondoFS.Sum(x => x.ServizioUtileDirittoAA.GetValueOrDefault() * coefficienteAnni +
                                x.ServizioUtileDirittoMM.GetValueOrDefault() * coefficienteMesi +
                                x.ServizioUtileDirittoGG.GetValueOrDefault() / coefficienteGiorni) : 0;
                            if (Utility.IsDomandaOrganizzazioniInternazionali(datiPensione))
                            {
                                sommaSettimaneUtiliAlDirittoApp += listaDatiFondoFS != null ? listaDatiFondoFS.Sum(x => x.ServizioUtileDirittoOIAA.GetValueOrDefault() * coefficienteAnni +
                                    x.ServizioUtileDirittoOIMM.GetValueOrDefault() * coefficienteMesi +
                                    x.ServizioUtileDirittoOIGG.GetValueOrDefault() / coefficienteGiorni) : 0;
                            }
                        }
                        break;
                    case Utility.TipoFondo.PT:
                        List<GestioneFondo.DatiFondoPT> listaDatiFondoPT = objectFondoXX as List<GestioneFondo.DatiFondoPT>;
                        //ENG - 024/INPDAP: bisogna considerare solo gli anni per calcolare le settimane
                        if (Utility.IsDomandaQuota100(datiPensione) || Utility.IsDomandaQuota102(datiPensione) || Utility.IsDomandaAnticipataFlessibile(datiPensione) ||
                            Utility.IsDomandaAnticipataFlessibileOpzioneContributivo(datiPensione) || Utility.IsOpzioneDonna_Legge197_2022_Art1_Comma292_LetteraA(datiPensione, true, true) ||
                            Utility.IsOpzioneDonna_Legge197_2022_Art1_Comma292_LetteraB(datiPensione, true, true) || Utility.IsOpzioneDonna_Legge197_2022_Art1_Comma292_LetteraC(datiPensione, true, true) ||
                            Utility.IsRicOpzioneDonna_Legge197_2022_Art1_Comma292_LetteraA(datiPensione) || Utility.IsRicOpzioneDonna_Legge197_2022_Art1_Comma292_LetteraB(datiPensione)
                            || Utility.IsRicOpzioneDonna_Legge197_2022_Art1_Comma292_LetteraC(datiPensione) ||
                            Utility.IsDomandaSperimentaleDonna_DL_4_2019OrRicostituzione(datiPensione) ||
                            Utility.IsDomandaTipoContributivo(datiPensione, true, false) || (!Utility.IsRicostituzione(datiPensione.Gruppo) && !Utility.IsRiaperturaDomanda(datiPensione.Id) && (Utility.IsDomandaAnticipataFlessibileLeggeBilancio2024(datiPensione) || Utility.IsDomandaAnticipataFlessibileOpzioneContributivoLeggeBilancio2024(datiPensione))) ||
                           ((Utility.IsRicostituzione(datiPensione.Gruppo) || Utility.IsRiaperturaDomanda(datiPensione.Id)) && ((ctrlMemo123_2024 != null && ctrlMemo123_2024.ValoreControllo == "SI" && Utility.IsDomandaAnticipataFlessibileLeggeBilancio2024(datiPensione)) || (ctrlMemo123_2024OpzioneContrib != null && ctrlMemo123_2024OpzioneContrib.ValoreControllo == "SI" && Utility.IsDomandaAnticipataFlessibileOpzioneContributivoLeggeBilancio2024(datiPensione)))))
                        {
                            sommaSettimaneUtiliAlDirittoApp += listaDatiFondoPT != null ? listaDatiFondoPT.Sum(x => x.ServizioUtileDirittoAA.GetValueOrDefault() * coefficienteAnni) : 0;
                            if (Utility.IsDomandaOrganizzazioniInternazionali(datiPensione))
                                sommaSettimaneUtiliAlDirittoApp += listaDatiFondoPT != null ? listaDatiFondoPT.Sum(x => x.ServizioUtileDirittoOIAA.GetValueOrDefault() * coefficienteAnni) : 0;
                        }
                        else if (datiPensione.Gruppo == "0001" && datiPensione.Prodotto == "0001" && datiPensione.Tipo == "0001")
                        {
                            sommaSettimaneUtiliAlDirittoApp += listaDatiFondoPT != null ? listaDatiFondoPT.Sum(x => x.ServizioUtileDirittoAA.GetValueOrDefault() * coefficienteAnni +
                                x.ServizioUtileDirittoMM.GetValueOrDefault() * coefficienteMesi) : 0;
                            if (Utility.IsDomandaOrganizzazioniInternazionali(datiPensione))
                            {
                                sommaSettimaneUtiliAlDirittoApp += listaDatiFondoPT != null ? listaDatiFondoPT.Sum(x => x.ServizioUtileDirittoOIAA.GetValueOrDefault() * coefficienteAnni +
                                x.ServizioUtileDirittoOIMM.GetValueOrDefault() * coefficienteMesi) : 0;
                            }
                        }
                        else
                        {
                            sommaSettimaneUtiliAlDirittoApp += listaDatiFondoPT != null ? listaDatiFondoPT.Sum(x => x.ServizioUtileDirittoAA.GetValueOrDefault() * coefficienteAnni +
                                x.ServizioUtileDirittoMM.GetValueOrDefault() * coefficienteMesi +
                                x.ServizioUtileDirittoGG.GetValueOrDefault() / coefficienteGiorni) : 0;
                            if (Utility.IsDomandaOrganizzazioniInternazionali(datiPensione))
                            {
                                sommaSettimaneUtiliAlDirittoApp += listaDatiFondoPT != null ? listaDatiFondoPT.Sum(x => x.ServizioUtileDirittoOIAA.GetValueOrDefault() * coefficienteAnni +
                                    x.ServizioUtileDirittoOIMM.GetValueOrDefault() * coefficienteMesi +
                                    x.ServizioUtileDirittoOIGG.GetValueOrDefault() / coefficienteGiorni) : 0;
                            }
                        }
                        break;
                    case Utility.TipoFondo.EL:
                    case Utility.TipoFondo.ET:
                    case Utility.TipoFondo.TT:
                    case Utility.TipoFondo.VL:
                        sommaSettimaneUtiliAlDirittoApp = settimaneUtiliDiritto.GetValueOrDefault();
                        break;
                }
            }
            if (!isINPDAP && tipoFondo.HasValue && tipoFondo.Value != Utility.TipoFondo.FS && tipoFondo.Value != Utility.TipoFondo.PT && sommaSettimaneUtiliAlDirittoApp == 0)
            {
                sommaSettimaneUtiliAlDirittoApp += listaServizioUtile != null ? listaServizioUtile.Sum(x => x.ServizioUtileAA.GetValueOrDefault() * coefficienteAnni + x.ServizioUtileMM.GetValueOrDefault() * coefficienteMesi + x.ServizioUtileGG.GetValueOrDefault() / coefficienteGiorni +
                            x.ServizioUtileCessazioneAA.GetValueOrDefault() * coefficienteAnni + x.ServizioUtileCessazioneMM.GetValueOrDefault() * coefficienteMesi + x.ServizioUtileCessazioneGG.GetValueOrDefault() / coefficienteGiorni) : 0;
                sommaSettimaneUtiliAlDirittoApp += datiRetributivi != null ? datiRetributivi.NSettAnzianitaVV.GetValueOrDefault() +
                    datiRetributivi.NSettimaneEsclusiveQuotaA.GetValueOrDefault() +
                    datiRetributivi.NSettimaneEsclusiveQuotaB.GetValueOrDefault() +
                    datiRetributivi.NSettimaneQuotaA.GetValueOrDefault() +
                    datiRetributivi.NSettimaneQuotaA2.GetValueOrDefault() +
                    datiRetributivi.NSettimaneQuotaB.GetValueOrDefault() +
                    datiRetributivi.NSettimaneQuotaC.GetValueOrDefault() +
                    datiRetributivi.NSettimaneQuotaC2.GetValueOrDefault() +
                    datiRetributivi.NSettimaneQuotaD.GetValueOrDefault() : 0;
                if (listaDatiContributivi != null && listaDatiContributivi.Count > 0)
                    foreach (var datiContributivi in listaDatiContributivi)
                        sommaSettimaneUtiliAlDirittoApp += datiContributivi != null ? datiContributivi.AnzianitaAnte0697AA.GetValueOrDefault() * coefficienteAnni +
                            datiContributivi.AnzianitaAnte0697MM.GetValueOrDefault() * coefficienteMesi +
                            datiContributivi.AnzianitaAnte0697GG.GetValueOrDefault() / coefficienteGiorni +
                            datiContributivi.AnzianitaPost0697AA.GetValueOrDefault() * coefficienteAnni +
                            datiContributivi.AnzianitaPost0697MM.GetValueOrDefault() * coefficienteMesi +
                            datiContributivi.AnzianitaPost0697GG.GetValueOrDefault() / coefficienteGiorni +
                            datiContributivi.NSettimane.GetValueOrDefault() +
                            datiContributivi.NSettimaneQuotaDL214.GetValueOrDefault() : 0;
            }

            int sommaSettimaneUtiliAlDiritto = (int)Math.Ceiling(sommaSettimaneUtiliAlDirittoApp);

            if (datiPensione.Gruppo == "0001" && datiPensione.Prodotto == "0001" && datiPensione.Tipo == "0001" && (isINPDAP || tipoFondo == Utility.TipoFondo.PT || tipoFondo == Utility.TipoFondo.FS))
            {
                //devo considerare solo la parte intera
                sommaSettimaneUtiliAlDiritto = (int)Math.Truncate(sommaSettimaneUtiliAlDirittoApp);
            }

            return sommaSettimaneUtiliAlDiritto;
        }
        #endregion FS

        #region CI

        #region Anagrafica
        public static bool CI_VerificaDecorrenzaPensione(GestionePensione.DatiPensione datiPensione, bool isRiaperturaDomanda, DateTime? decorrenzaPensione, out string messaggioVideo)
        {
            messaggioVideo = string.Empty;

            string siglaCategoria = string.Empty;
            DateTime decorrenzaOriginaria = DateTime.MinValue;
            List<GestioneDatiContributiviCi.PensioniCiPrestazioniEE> listaPrestazioniEstere = null;
            GestioneDatiContributiviCi.GetPrestazioniEEByIdPensione(datiPensione.Id, out listaPrestazioniEstere);
            byte? codiceConvenzione = null;
            int codicePrimoStatoEE = 0;
            if (listaPrestazioniEstere != null && listaPrestazioniEstere.Count > 0)
            {
                codiceConvenzione = listaPrestazioniEstere[0].CodiceConvenzione;
                int.TryParse(listaPrestazioniEstere[0].CodiceStatoEE, out codicePrimoStatoEE);
            }

            #region Recupero Dati

            Utility.TipoDomanda tipologiaDomanda = Utility.GetTipoDomanda(datiPensione.Gruppo, datiPensione.Prodotto);
            decorrenzaOriginaria = decorrenzaPensione.HasValue ? decorrenzaPensione.Value : DateTime.MinValue;
            siglaCategoria = datiPensione.SiglaCategoria.Trim().ToUpperInvariant();

            #endregion Recupero Dati

            if (siglaCategoria != "IOCUM")
            {
                //Se il 1° carattere della Categoria (RACATEG) è = a “I” la Decorrenza
                //Originaria (RAU104) deve essere maggiore della Data della Domanda
                //(RAUE24)
                if (siglaCategoria.StartsWith("I"))
                {
                    if (tipologiaDomanda != Utility.TipoDomanda.Ricostituzione && tipologiaDomanda != Utility.TipoDomanda.Ripristino && tipologiaDomanda != Utility.TipoDomanda.RipristinoSuperstiti)
                    {
                        if ((Utility.IsDomandaInabilitaAmianto(datiPensione) || Utility.IsDomandaInabilitaOrdinaria(datiPensione) ||
                             Utility.IsDomandaInabilitaNavigazione(datiPensione) || Utility.IsDomandaInvaliditaOrdinaria(datiPensione) ||
                             Utility.IsDomandaAssegnoInvaliditaOrdinario(datiPensione)) ?
                            !Utility.DataStrettamenteSuccessivaA(decorrenzaOriginaria, new DateTime(datiPensione.DataPresentazioneDomanda.Year, datiPensione.DataPresentazioneDomanda.Month, 1)) :
                            !Utility.DataSuccessivaA(decorrenzaOriginaria, new DateTime(datiPensione.DataPresentazioneDomanda.Year, datiPensione.DataPresentazioneDomanda.Month, 1)))
                        {
                            messaggioVideo = "La decorrenza originaria deve essere maggiore della data di presentazione";
                            return false;
                        }
                    }
                }
            }
            if (codiceConvenzione == 58 && codicePrimoStatoEE == 58 && !Utility.DataSuccessivaA(decorrenzaOriginaria, new DateTime(2015, 12, 01)))
            {
                messaggioVideo = "Per lo Stato Israele la decorrenza pensione deve essere successiva al 01/12/2015";
                return false;
            }

            return true;
        }
        #endregion Anagrafica

