        public static bool CI_VerificaResidenzaWithCodOpzione(byte? codOpzione, string codCatastaleStatoEE)
        {
            if (codOpzione.GetValueOrDefault() == 7)
            {
                if (!string.IsNullOrEmpty(codCatastaleStatoEE) && !codCatastaleStatoEE.Trim().ToUpperInvariant().Equals("Z000"))
                    return false;
            }

            return true;
        }
