        #region Stato Civile
        #region PCIPL35
        /// <summary>
        /// Se il campo TP1STACIV (STATO CIVILE) =  2 muove “S”  nel campo W-RESOUT  e fa la PERFORM VED-CIV THRU FINE-VED-CIV  fino ad un massimo di 9(indici), impostando ad “s” il 
        /// campo W-RESOUT   se trova l’indice. Se il campo W-RESOUT  not = “S” segnala errore "REQ.ART.2 COMMA 3 D.L.503/92 INCOMPATIBILE CON COD.STATO CIVILE" 
        /// </summary>
        /// <param name="codiceRequisitiLegge50392Art2"></param>
        /// <param name="listaStatiCivili"></param>
        /// <param name="messaggioVideo"></param>
        /// <returns></returns>
        public static bool CI_VerificaCodiceRequisitiLegge50392WithStatoCivile(char? codiceRequisitiLegge50392Art2, List<GestioneAnagrafica.DatiStatoCivile> listaStatiCivili, out string messaggioVideo)
        {
            messaggioVideo = string.Empty;
            char flag = ' ';

            if (codiceRequisitiLegge50392Art2.HasValue && codiceRequisitiLegge50392Art2.Value == 'S')
            {
                if (listaStatiCivili != null && listaStatiCivili.Count > 0)
                {
                    if (listaStatiCivili.Last().Codice == '2' || listaStatiCivili.Last().Codice == '7')
                        flag = 'S';

                    for (int i = 0; i < listaStatiCivili.Count; i++)
                    {
                        if (flag == ' ')
                        {
                            if ((listaStatiCivili[i].Codice == '2' || listaStatiCivili.Last().Codice == '7') &&
                                (listaStatiCivili.Count == i + 1 || !listaStatiCivili[i + 1].Decorrenza.HasValue || Utility.DataStrettamenteSuccessivaA(listaStatiCivili[i + 1].Decorrenza.Value, new DateTime(2001, 01, 31))))
                                flag = 'S';
                        }
                        else
                            break;
                    }

                    if (flag != 'S')
                    {
                        messaggioVideo = "Req.Art.2 Comma 3 D.L.503/92 incompatibile con Cod.Stato Civile";
                        return false;
                    }
                }
            }

            return true;
        }
        #endregion PCIPL35
        #endregion Stato Civile

