        /// <summary>
        /// CodiceMaggiorazione errato o mancante
        /// </summary>
        /// <param name="codeFamiliare"></param>
        /// <param name="gruppo"></param>
        /// <param name="CodeMagg"></param>
        /// <returns></returns>
        public static bool CI_VerificaNoReversCodeMaggiorazioneConiuge(char? codeFamiliare, string gruppo, string prodotto, byte? CodeMagg)
        {
            Utility.TipoDomanda tipoDomanda = Utility.GetTipoDomanda(gruppo, prodotto);
            if (tipoDomanda != Utility.TipoDomanda.Superstiti)
            {
                if (codeFamiliare.HasValue && codeFamiliare.Value.ToString().ToUpperInvariant() == "C" && CodeMagg.GetValueOrDefault() != 1 && CodeMagg.GetValueOrDefault() != 2)
                    return false;
            }

            return true;
        }

        /// <summary>
        /// CodiceMaggiorazione non deve essere acquisito (figlio)
        /// </summary>
        /// <param name="codeFamiliare"></param>
        /// <param name="gruppo"></param>
        /// <param name="CodeMagg"></param>
        /// <returns></returns>
        public static bool CI_VerificaNoReversCodeMaggiorazioneNoConiuge(char? codeFamiliare, string gruppo, string prodotto, byte? CodeMagg, GestionePensione.DatiPensione datiPensione)
        {
            Utility.TipoDomanda tipoDomanda = Utility.GetTipoDomanda(gruppo, prodotto);

            //Memo 33: per i soggetti N e J devo permettere l'acquisizione delle maggiorazioni SI/NO
            Utility.TipoAppartenenza? tipoAppartenenza = Utility.GetTipoAppartenenza(datiPensione.IndConvInt, datiPensione.Gestione);
            GestioneControlliDinamici.ControlloDinamico abilitazioneMemo33 = null;
            GestioneControlliDinamici.GetControlloDinamicoByNomeControllo("AbilitazioneMemo33" + tipoAppartenenza.Value, out abilitazioneMemo33);

            if (abilitazioneMemo33 == null || String.IsNullOrEmpty(abilitazioneMemo33.ValoreControllo) || String.IsNullOrEmpty(abilitazioneMemo33.ValoreControllo.Trim()) || abilitazioneMemo33.ValoreControllo.Trim().ToUpperInvariant() == "NO")
            {
                if (tipoDomanda != Utility.TipoDomanda.Superstiti)
                {
                    if (codeFamiliare.HasValue && codeFamiliare.Value.ToString().ToUpperInvariant() != "C" && CodeMagg.HasValue && CodeMagg.Value > 0)
                        return false;
                }
            }

            return true;
        }

        /// <summary>
        /// CodiceMaggiorazione non deve essere acquisito (coniuge sup.)
        /// </summary>
        /// <param name="codeFamiliare"></param>
        /// <param name="gruppo"></param>
        /// <param name="CodeMagg"></param>
        /// <returns></returns>
        public static bool CI_VerificaReversCodeMaggiorazioneConiuge(char? codeFamiliare, string gruppo, string prodotto, byte? CodeMagg)
        {
            Utility.TipoDomanda tipoDomanda = Utility.GetTipoDomanda(gruppo, prodotto);
            if (tipoDomanda == Utility.TipoDomanda.Superstiti)
            {
                if (codeFamiliare.HasValue && codeFamiliare.Value.ToString().ToUpperInvariant() == "C" && CodeMagg.Value > 0)
                    return false;
            }

            return true;
        }

        /// <summary>
        /// CodiceMaggiorazione errato o mancante (SI / NO)
        /// </summary>
        /// <param name="codeFamiliare"></param>
        /// <param name="gruppo"></param>
        /// <param name="CodeMagg"></param>
        /// <returns></returns>
        public static bool CI_VerificaReversCodeMaggiorazioneNoConiuge(char? codeFamiliare, string gruppo, string prodotto, byte? CodeMagg)
        {
            Utility.TipoDomanda tipoDomanda = Utility.GetTipoDomanda(gruppo, prodotto);
            if (tipoDomanda == Utility.TipoDomanda.Superstiti)
            {
                if (codeFamiliare.HasValue && codeFamiliare.Value.ToString().ToUpperInvariant() != "C" && CodeMagg.GetValueOrDefault() != 1 && CodeMagg.GetValueOrDefault() != 2)
                    return false;
            }

            return true;
        }

        public static bool CI_ControlsQuotaContitolaritaNipote(GestionePensione.DatiPensione datiPensione, Utility.TipoAppartenenza? tipoApp, List<GestioneFamiliari.Familiare> familiariApp, List<GestioneFamiliari.CodMaggFamiliari> elencoCodMaggFamiliari, int annoCompetenza, out string msgVideo)
        {
            msgVideo = string.Empty;

            if (tipoApp == null || tipoApp != Utility.TipoAppartenenza.CI || datiPensione == null || !Utility.IsDomandaPensioneSuperstitiOrRicostituzione(datiPensione) ||
                familiariApp == null || familiariApp.Count == 0 || elencoCodMaggFamiliari == null || elencoCodMaggFamiliari.Count == 0)
                return true;

            if (familiariApp.Exists(x => x.SiglaFamiliare == 'N') || familiariApp.Exists(x => x.SiglaFamiliare == 'J'))
            {
                List<GestioneFamiliari.Familiare> listaNipoti = familiariApp.FindAll(x => x.SiglaFamiliare == 'N' || x.SiglaFamiliare == 'J');
                foreach (GestioneFamiliari.Familiare nipote in listaNipoti)
                {
                    List<GestioneFamiliari.CodMaggFamiliari> listaCodMaggNipote = elencoCodMaggFamiliari.FindAll(x => x.IdAnagrafica == nipote.IdAnagrafica).OrderBy(x => x.Decorrenza).ToList();
                    if (listaCodMaggNipote != null && listaCodMaggNipote.Count > 0)
                    {
                        GestioneFamiliari.CodMaggFamiliari ultimoCodMaggNipote = listaCodMaggNipote.Last();
                        GestioneFamiliari.CodMaggFamiliari primoCodMaggNipote = listaCodMaggNipote.First();
                        GestioneAnagrafica.DatiAnagrafici datiAnagrafici = null;
                        GestioneAnagrafica.GetAnagraficaByIdAnagrafica(nipote.IdAnagrafica, out datiAnagrafici);
                        DateTime dataCompare = Utility.FirstDayOfMonth(datiAnagrafici.DataNascita.GetValueOrDefault().AddYears(18).AddMonths(1));
                        if (ultimoCodMaggNipote.CodiceMaggiorazione.GetValueOrDefault() == 1)
                        {
                            if (ultimoCodMaggNipote.Cessazione.HasValue)
                            {
                                if (Utility.DataStrettamenteSuccessivaA(ultimoCodMaggNipote.Cessazione.GetValueOrDefault(), new DateTime(annoCompetenza + 1, 01, 01)))
                                {
                                    msgVideo = string.Format("Per il soggetto {0} la data di fine carico deve essere inferiore o uguale a Gennaio {1}", nipote.CodiceFiscale, annoCompetenza + 1);
                                    return false;
                                }

                                if (Utility.DataStrettamenteSuccessivaA(dataCompare, ultimoCodMaggNipote.Cessazione.Value))
                                {
                                    msgVideo = string.Format("Per il soggetto {0} è necessario inserire un nuovo periodo di carico con grado di parentela 'Nipote', codice maggiorazione 'NO' e con data di fine carico uguale al mese successivo al compimento dei 18 anni", nipote.CodiceFiscale);
                                    return false;
                                }
                            }
                        }
                        else if (ultimoCodMaggNipote.CodiceMaggiorazione.GetValueOrDefault() == 2)
                        {
                            if ((!nipote.DataMorte.HasValue || Utility.DataStrettamenteSuccessivaA(nipote.DataMorte.GetValueOrDefault(), dataCompare)) && Utility.DataStrettamenteSuccessivaA(dataCompare, ultimoCodMaggNipote.Cessazione.Value))
                            {
                                msgVideo = string.Format("Per il soggetto {0} la data di fine carico deve essere uguale al mese successivo al compimento dei 18 anni", nipote.CodiceFiscale);
                                return false;
                            }
                        }
                        if (primoCodMaggNipote.CodiceMaggiorazione.GetValueOrDefault() == 1 && primoCodMaggNipote.Cessazione.HasValue)
                        {
                            if (Utility.DataStrettamenteSuccessivaA(primoCodMaggNipote.Cessazione.GetValueOrDefault(), new DateTime(annoCompetenza + 1, 01, 01)))
                            {
                                msgVideo = string.Format("Per il soggetto {0} (codice maggiorazione 'SI') la data di fine carico deve essere inferiore o uguale a Gennaio {1}", nipote.CodiceFiscale, annoCompetenza + 1);
                                return false;
                            }
                            if (ultimoCodMaggNipote.CodiceMaggiorazione.GetValueOrDefault() == 2 && ultimoCodMaggNipote.Decorrenza.HasValue &&
                                Utility.DataStrettamenteSuccessivaA(ultimoCodMaggNipote.Decorrenza.GetValueOrDefault(), new DateTime(annoCompetenza + 1, 01, 01)))
                            {
                                msgVideo = "(codice maggiorazione 'NO') la data di decorrenza carico deve essere uguale alla data di fine carico (codice maggiorazione 'SI')";
                                return false;
                            }
                        }
                    }
                }
            }

            return true;
        }

        #region PCIPL11
        /// <summary>
        /// 28.	Se TP1COGNF(1) è uguale a spazi valorizzare con "04" il campo TIPO-ERRORE, con 1 il campo COL-ERR1, con 4 il campo COL-ERR2, con 5 il campo COL-ERR3,con "ERRORE: 
        /// DEVE ESSERCI ALMENO UNA REGISTRAZIONE" il campo MESSAGGIO-ERRORE, con 1 il campo FLAG-ERR e uscire da CONTROLLI-1 (70);
        /// </summary>
        /// <param name="isFamiliarePresente"></param>
        /// <param name="gruppo"></param>
        /// <param name="messaggioVideo"></param>
        /// <returns></returns>
        public static bool CI_VerificaReversObbligatorietaFamiliare(bool? isFamiliarePresente, Utility.TipoDomanda tipoDomanda, out string messaggioVideo)
        {
            messaggioVideo = string.Empty;

            if (tipoDomanda == Utility.TipoDomanda.Superstiti)
            {
                if (!isFamiliarePresente.GetValueOrDefault())
                {
                    messaggioVideo = "Deve esserci almeno un Familiare";
                    return false;
                }
            }

            return true;
        }

        /// <summary>
        /// 39.	Se TP1COACF(INDICE) non è uguale a spazi e IW4SES(INDICE) è uguale a "M" valorizzare con "12" il campo TIPO-ERRORE, con 1 il campo COL-ERR1, con 5 il campo COL-ERR2, 
        /// con "SE PRESENTE IL COGNOME ACQUISITO, IL SESSO DEVE ESSERE 'F'" il campo MESSAGGIO-ERRORE, con 1 il campo FLAG-ERR e uscire da CONTROLLI-1 (70);
        /// </summary>
        /// <param name="cognomeAcquisito"></param>
        /// <param name="sesso"></param>
        /// <param name="messaggioVideo"></param>
        /// <returns></returns>
        public static bool CI_VerificaCognomeAcquisitoWithSesso(string cognomeAcquisito, char? sesso, List<GestioneFamiliari.CodMaggFamiliari> listaCodMaggiorazione, out string messaggioVideo)
        {
            messaggioVideo = string.Empty;

            if (!string.IsNullOrEmpty(cognomeAcquisito) && sesso == 'M' && listaCodMaggiorazione != null && !listaCodMaggiorazione.Exists(x => x.SiglaFamiliare.GetValueOrDefault() == 'C' && !String.IsNullOrEmpty(x.TipoUnione) && x.TipoUnione.ToUpperInvariant() == "U"))
            {
                messaggioVideo = "Se presente il Cognome Acquisito, il Sesso deve essere 'F'";
                return false;
            }

            return true;
        }

        /// <summary>
        /// 42.	Se ( IW4SIG(INDICE) non è uguale a "C" e non è uguale a "A" ) e ( IW4NASCA(INDICE) è maggiore di 1800 e è minore di 1900 ) valorizzare con "17" il campo TIPO-ERRORE, 
        /// con 4 il campo COL-ERR1, con 6 il campo COL-ERR2, con "INCOMPATIBILITA' TRA DATA DI NASCITA E SIGLA" il campo MESSAGGIO-ERRORE, con 1 il campo FLAG-ERR e uscire da 
        /// CONTROLLI-1 (70);
        /// </summary>
        /// <param name="siglaFamiliare"></param>
        /// <param name="dataNascita"></param>
        /// <param name="messaggioVideo"></param>
        /// <returns></returns>
        public static bool CI_VerificaSiglaFamiliareWithDataNascita(GestioneFamiliari.Familiare familiare, DateTime? dataNascita, out string messaggioVideo)
        {
            messaggioVideo = string.Empty;

            if (familiare != null && !familiare.IsConiugeOrUnitoCivile() && familiare.SiglaFamiliare.GetValueOrDefault() != 'A' && dataNascita.HasValue && dataNascita.Value.Year > 1800 && dataNascita.Value.Year < 1900)
            {
                messaggioVideo = "Incompatibilita' tra Data di Nascita e Sigla";
                return false;
            }

            return true;
        }

        /// <summary>
        /// 44.	Se APPO-CAT1 è uguale a "S" effettuare le seguenti operazioni : 
        /// 44.1.	Se IW4SIG(INDICE) è uguale a "C" effettuare le seguenti operazioni : 
        /// 44.1.1.	Se IW4CMAG(INDICE) è uguale a 1 effettuare le seguenti operazioni : 
        /// 44.1.1.1.	Valorizzare con INDICE il campo W-IND-CONIUGE;
        /// 44.1.1.2.	Se W-PERMAG1-DA è uguale a 0 valorizzare con IW4ACQ(INDICE) il campo W-PERMAG1-DA; 
        /// 44.1.1.3.	Se IW4ACQ(INDICE) è minore di W-PERMAG1-DA valorizzare con IW4ACQ(INDICE) il campo W-PERMAG1-DA;     
        /// 44.1.1.4.	Se IW4CES(INDICE) è uguale a 0 valorizzare con 999999 il campo W-PERMAG1-A;                              
        /// 44.1.1.5.	Se IW4CES(INDICE) è maggiore di W-PERMAG1-A valorizzare con IW4CES(INDICE) il campo W-PERMAG1-A;      
        /// 44.1.1.6.	Se (W-PERMAG1-DA non è minore di W-PERMAGX-DA e  W-PERMAG1-DA è minore di W-PERMAGX-A) oppure (W-PERMAG1-A non è minore di W-PERMAGX-DA e  W-PERMAG1-A è 
        /// minore di W-PERMAGX-A) oppure ( W-PERMAG1-DA è minore di W-PERMAGX-DA e  W-PERMAG1-A non è minore di W-PERMAGX-DA) valorizzare con "18" il campo TIPO-ERRORE, con 3 il 
        /// campo COL-ERR1, con 6 il campo COL-ERR2, con "CODICE MAGGIORAZIONE 1 INCOMPATIBILE NEL PERIODO DI VALIDITA'" il campo MESSAGGIO-ERRORE, con 1 il campo FLAG-ERR e uscire 
        /// da CONTROLLI-1 (70) diversamente effettuare le seguenti operazioni :                                       
        /// 44.1.1.6.1.	Se W-PERMAGX-DA è uguale a 0 valorizzare con IW4ACQ(INDICE) il campo W-PERMAGX-DA;
        /// 44.1.1.6.2.	Se IW4ACQ(INDICE) è minore di W-PERMAGX-DA valorizzare con IW4ACQ(INDICE) il campo W-PERMAGX-DA;
        /// 44.1.1.6.3.	Se IW4CES(INDICE) è uguale a 0 valorizzare con 999999 il campo W-PERMAGX-A;                  
        /// 44.1.1.6.4.	Se IW4CES(INDICE) è maggiore di W-PERMAGX-A valorizzare con IW4CES(INDICE) il campo W-PERMAGX-A;
        /// </summary>
        /// <param name="tipoDomanda"></param>
        /// <param name="siglaFamiliare"></param>
        /// <param name="codiceMaggiorazione"></param>
        /// <param name="decorrenzaCarico"></param>
        /// <param name="cessazioneCarico"></param>
        /// <param name="appDecorrenzaCarico"></param>
        /// <param name="appCessazioneCarico"></param>
        /// <param name="decorrenzaCaricoCompare"></param>
        /// <param name="cessazioneCaricoCompare"></param>
        /// <param name="messaggioVideo"></param>
        /// <returns></returns>
        public static bool CI_VerificaCodiceMaggiorazioneWithPeriodo(Utility.TipoDomanda tipoDomanda, GestioneFamiliari.Familiare familiare, byte? codiceMaggiorazione, DateTime? decorrenzaCarico, DateTime? cessazioneCarico,
            ref DateTime? appDecorrenzaCarico, ref DateTime? appCessazioneCarico, ref DateTime? decorrenzaCaricoCompare, ref DateTime? cessazioneCaricoCompare, out string messaggioVideo)
        {
            messaggioVideo = string.Empty;

            if (tipoDomanda == Utility.TipoDomanda.Superstiti)
            {
                if (familiare.IsConiugeOrUnitoCivile())
                {
                    if (codiceMaggiorazione.GetValueOrDefault() == 1)
                    {
                        if (appDecorrenzaCarico.Equals(DateTime.MinValue))
                            appDecorrenzaCarico = decorrenzaCarico;
                        if (decorrenzaCarico.HasValue && !Utility.DataSuccessivaA(decorrenzaCarico.Value, appDecorrenzaCarico.Value))
                            appDecorrenzaCarico = decorrenzaCarico;

                        if (!cessazioneCarico.HasValue)
                            appCessazioneCarico = DateTime.MaxValue;
                        if (cessazioneCarico.HasValue && Utility.DataStrettamenteSuccessivaA(cessazioneCarico.Value, appCessazioneCarico.Value))
                            appCessazioneCarico = cessazioneCarico;

                        if (((appDecorrenzaCarico.HasValue && decorrenzaCaricoCompare.HasValue && cessazioneCaricoCompare.HasValue) &&
                            (Utility.DataSuccessivaA(appDecorrenzaCarico.Value, decorrenzaCaricoCompare.Value) && !Utility.DataSuccessivaA(appDecorrenzaCarico.Value, cessazioneCaricoCompare.Value))) ||
                            ((appCessazioneCarico.HasValue && decorrenzaCaricoCompare.HasValue && cessazioneCaricoCompare.HasValue) &&
                            (Utility.DataSuccessivaA(appCessazioneCarico.Value, decorrenzaCaricoCompare.Value) && !Utility.DataSuccessivaA(appCessazioneCarico.Value, cessazioneCaricoCompare.Value))) ||
                            ((appCessazioneCarico.HasValue && decorrenzaCaricoCompare.HasValue && appDecorrenzaCarico.HasValue) &&
                            (Utility.DataSuccessivaA(appCessazioneCarico.Value, decorrenzaCaricoCompare.Value) && !Utility.DataSuccessivaA(appDecorrenzaCarico.Value, decorrenzaCaricoCompare.Value))))
                        {
                            messaggioVideo = "Codice Maggiorazione 1 incompatibile nel periodo di validita'";
                            return false;
                        }
                    }
                    else
                    {
                        if (decorrenzaCaricoCompare.Equals(DateTime.MinValue))
                            decorrenzaCaricoCompare = decorrenzaCarico;
                        if (decorrenzaCarico.HasValue && !Utility.DataSuccessivaA(decorrenzaCarico.Value, decorrenzaCaricoCompare.Value))
                            decorrenzaCaricoCompare = decorrenzaCarico;

                        if (!cessazioneCarico.HasValue)
                            cessazioneCaricoCompare = DateTime.MaxValue;
                        if (cessazioneCarico.HasValue && Utility.DataStrettamenteSuccessivaA(cessazioneCarico.Value, cessazioneCaricoCompare.Value))
                            cessazioneCaricoCompare = cessazioneCarico;
                    }
                }
            }

            return true;
        }

        /// <summary>
        /// 46.	Se APPO-CAT1 è uguale a "S" effettuare le seguenti operazioni : 
        /// 46.1.	Valorizzare con IW1DMOR il campo WDAMOR8;
        /// 46.2.	Se WDAMOR-SAM è minore di WDANAS-SAM effettuare le seguenti operazioni : 
        /// 46.2.1.	Aggiungere 9 al campo WDAMOR-MM; 
        /// 46.2.2.	Se WDAMOR-MM è maggiore di 12 effettuare le seguenti operazioni : 
        /// 46.2.2.1.	Calcolare WDAMOR-MM è uguale a WDAMOR-MM – 12; 
        /// 46.2.2.2.	Calcolare WDAMOR-SA è uguale a WDAMOR-SA + 1; 
        /// 46.2.3.	Se WDAMOR-SAM è minore di WDANAS-SAM valorizzare con "23" il campo TIPO-ERRORE, con 4 il campo COL-ERR1, con "DATA NASCITA CONTITOLARE POSTERIORE A DATA MORTE + 
        /// 270 GIORNI" il campo MESSAGGIO-ERRORE;
        /// 46.2.4.	Diversamente da quando analizzato nel punto precedente (46.2.3) 
        /// 46.2.4.1.	Se WDANAS-MM è minore di 12 calcolare WAFDAL6 = WDANAS-SAM + 1, diversamente valorizzare con WDANAS-SAM il campo WAFDAL6, aggiungere 1 al campo W-AF-DAL-AA, 
        /// valorizzare con 1 il campo W-AF-DAL-MM; 
        /// 46.2.4.2.	Se IW4ACQ(INDICE) è minore di WAFDAL6 e IW4ACQ(INDICE)    non è uguale a IW1DEORIG valorizzare con "24" il campo TIPO-ERRORE, con 4 il campo COL-ERR1, con 7 
        /// il campo COL-ERR1, con "DECORRENZA NON POSTERIORE A DATA NASCITA" il campo MESSAGGIO-ERRORE, con 1 il campo FLAG-ERR e uscire da CONTROLLI-1 (70);
        /// 46.3.	Se IW4SIG(INDICE) è uguale a "Z" oppure "W" oppure "K" effettuare le seguenti operazioni : 
        /// 46.3.1.	Se (IW4NASC(INDICE) + 180000) è minore di IW1DMOR valorizzare con "24" il campo TIPO-ERRORE, con 4 il campo COL-ERR1, con 7 il campo COL-ERR1, con "NIPOTE 
        /// MAGGIORENNE ALLA DATA DI MORTE DEL DANTE CAUSA" il campo MESSAGGIO-ERRORE, con 1 il campo FLAG-ERR e uscire da CONTROLLI-1 (70);
        /// </summary>
        /// <param name="tipoDomanda"></param>
        /// <param name="dataMorteDC"></param>
        /// <param name="dataNascitaFamiliare"></param>
        /// <param name="decorrenzaCarico"></param>
        /// <param name="decorrenzaOriginaria"></param>
        /// <param name="messaggioVideo"></param>
        /// <returns></returns>
        public static bool CI_VerificaDateFamiliari(Utility.TipoDomanda tipoDomanda, DateTime? dataMorteDC, DateTime? dataNascitaFamiliare, DateTime? decorrenzaCarico, DateTime? decorrenzaOriginaria, char? siglaFamiliare, out string messaggioVideo)
        {
            messaggioVideo = string.Empty;
            DateTime? appDataMorte = null;
            DateTime? appDataNascita = null;

            if (tipoDomanda == Utility.TipoDomanda.Superstiti)
            {
                appDataMorte = new DateTime(dataMorteDC.Value.Year, dataMorteDC.Value.Month, 01);
                appDataNascita = new DateTime(dataNascitaFamiliare.Value.Year, dataNascitaFamiliare.Value.Month, 01);
                if (!Utility.DataSuccessivaA(appDataMorte.Value, appDataNascita.Value))
                {
                    appDataMorte = appDataMorte.Value.AddMonths(9);
                    if (!Utility.DataSuccessivaA(appDataMorte.Value, appDataNascita.Value))
                    {
                        messaggioVideo = "Data Nascita Contitolare posteriore a Data Morte + 270 giorni";
                        return false;
                    }
                    else
                    {
                        appDataNascita = appDataNascita.Value.AddMonths(1);
                        if (!Utility.DataSuccessivaA(decorrenzaCarico.Value, appDataNascita.Value) && !decorrenzaCarico.Equals(decorrenzaOriginaria))
                        {
                            messaggioVideo = "Decorrenza non posteriore a Data Nascita";
                            return false;
                        }
                    }
                }

                List<char> listaSigleFamiliari = new List<char> { 'Z', 'W', 'K' };
                if (listaSigleFamiliari.Contains(siglaFamiliare.Value))
                {
                    if (!Utility.DataSuccessivaA(dataNascitaFamiliare.Value.AddYears(18), dataMorteDC.Value))
                    {
                        messaggioVideo = "Nipote maggiorenne alla Data di Morte del Dante Causa";
                        return false;
                    }
                }
            }

            return true;
        }

        /// <summary>
        /// 49.	Valorizzare con IW4ACQ(INDICE) il campo WAFDAL6;                                                                         
        ///       *** LA CESSAZIONE  ACQUISITA   WAFAL6  (AAAAMM)                 
        /// 50.	Se IW4CES(INDICE) è maggiore di 0 valorizzare con IW4CES(INDICE) il campo WAFAL6, diversamente valorizzare con zero il campo WAFAL6; 
        /// 51.	Inizializzare WAFSCA6. 
        ///       *** LA CESSAZIONE  CALCOLATA   WAFSCA6 (AAAAMM)                 
        /// 52.	Se IW4SIG(INDICE) è uguale a "C" oppure è uguale a "I" oppure è uguale a "A" oppure  IW4SIG(INDICE) è uguale a "K" oppure è uguale a "Y" oppure è uguale a "F" 
        /// effettuare le seguenti operazioni : Valorizzare con 999999 il campo WAFSCA6; 
        /// 53.	Se IW4SIG(INDICE) è uguale a "M" oppure IW4SIG(INDICE) è uguale a "N" oppure è uguale a "P" oppure è uguale a "G" oppure "J" valorizzare con WDANAS-SAM il campo 
        /// WAFSCA6 e  aggiungere 1800 al campo WAFSCA6;                                   
        /// 54.	Se ( IW4SIG(INDICE) è uguale a "N" oppure è uguale a "J" ) e WAFSCA6 è maggiore di  (ANNO-COMPET * 100 + 101) calcolare WAFSCA6 = (ANNO-COMPET * 100  +  12);
        /// 55.	Se IW4SIG(INDICE) è uguale a "S" oppure è uguale a "L" oppure IW4SIG(INDICE) è uguale a "Z" valorizzare con WDANAS-SAM il campo WAFSCA6aggiungere 2100 al campo 
        /// WAFSCA6;
        /// 56.	Se IW4SIG(INDICE) è uguale a "U" oppure IW4SIG(INDICE) è uguale a "W" valorizzare con WDANAS-SAM il campo WAFSCA6 aggiungere 2600 al campo WAFSCA6;     
        /// 57.	Aggiungere 1 al campo W-AF-SCA-MM;
        ///      **** IL MESE SCADENZA DEVE ESSERE PARI                             
        ///      **** (SOLO PER CAUSA CARICO DIVERSO DA 1 E CESSAZ minore 0798           
        /// 58.	Se IW1CARIC è maggiore di 1 e WAFSCA6 è minore di 199808 effettuare le seguenti operazioni : 
        /// 58.1.	Se W-AF-SCA-MM è uguale a 3 oppure è uguale a 5 oppure è uguale a 7 oppure è uguale a 9 oppure è uguale a 11 aggiungere 1 al campo W-AF-SCA-MM;
        ///      ****                                                               
        /// 59.	Se W-AF-SCA-MM è uguale a 13 valorizzare con 1 il campo W-AF-SCA-MM e aggiungere 100 al campo WAFSCA6;
        ///      **** APPOGGIO NEL CAMPO W-DISP IL VALORE DICEMBRE ANNO IN CORSO    
        /// 60.	Valorizzare con DATA-SYS-SSAA il campo W-DISP-AA;
        /// 61.	Valorizzare con 13 il campo W-DISP-MM;
        /// INIZ******++  SOLO PER ACQUISIZIONE 2006 IN CONTO 2007                  
        /// **********       A FINE 2008 METTERLE IN CONTO 2009                     
        /// cg2008****** dal 2009 e' automatico (utilizza campo ANNO-COMPET)        
        /// 62.	Se W-DISP-AA è minore di ANNO-COMPET valorizzare con ANNO-COMPET il campo W-DISP-AA;
        /// **********++  SOLO PER ACQUISIZIONE 2006 IN CONTO 2007                  
        /// FINE******       A FINE 2008 METTERLE IN CONTO 2009                     
        /// 63.	Se WAFSCA6 è minore di 209901 effettuare le seguenti operazioni : 
        /// 63.1.	Se ( WAFSCA6 non è maggiore di W-DISP e WAFAL6 è uguale a 0 ) valorizzare con "28" il campo TIPO-ERRORE, con 8 il campo COL-ERR1, con "CESSAZ. MAGGIORAZIONE 
        /// MANCANTE (" + W-AF-SCA-MM + "/" W-AF-SCA-AA + ")" il campo MESSAGGIO-ERRORE, con 1 il campo FLAG-ERR e uscire da CONTROLLI-1 (70);
        /// 64.	Se WAFAL6 è maggiore di WAFSCA6 valorizzare con "29" il campo TIPO-ERRORE, con 6 il campo COL-ERR1, con 8 il campo COL-ERR2, con "CESSAZ. MAGGIORAZIONE INCOMPATIBILE 
        /// CON SIGLA (" + W-AF-SCA-MM + "/" + W-AF-SCA-AA + ")" il campo MESSAGGIO-ERRORE, con 1 il campo FLAG-ERR e uscire da CONTROLLI-1 (70); 
        /// 65.	Se WAFAL6 è maggiore di 0 effettuare le seguenti operazioni : 
        /// 65.1.	Se WAFAL6 non è maggiore di WAFDAL6 effettuare le seguenti operazioni : 
        /// **************** 18.1.2001                                              
        /// 65.1.1.	Se WAFAL6 è uguale a WAFDAL6 e IW1CARIC è uguale a 2 continuare l'elaborazione al punto successivo, diversamente da quando analizzato nel punto precedente 
        /// effettuare le seguenti operazioni :
        /// **************** 18.1.2001                                              
        /// 65.1.1.1.	Valorizzare con "30" il campo TIPO-ERRORE, con 7 il campo COL-ERR1, con 8 il campo COL-ERR2, con "CESSAZ. MAGGIORAZIONE ANTERIORE ALLA DECORRENZA 
        /// MAGGIORAZIONE" il campo MESSAGGIO-ERRORE, con 1 il campo FLAG-ERR e uscire da CONTROLLI-1 (70);            
        /// 66.	Diversamente da quando analizzato nel punto precedente(65) effettuare le seguenti operazioni : 
        /// 66.1.	Se WAFSCA6 non è maggiore di WAFDAL6 valorizzare con "31" il campo TIPO-ERRORE, con 7 il campo COL-ERR1, con 8 il campo COL-ERR2, con "CESSAZ. MAGGIORAZIONE 
        /// ANTERIORE ALLA DECORRENZA MAGGIORAZIONE" il campo MESSAGGIO-ERRORE, con 1 il campo FLAG-ERR e uscire da CONTROLLI-1 (70);
        /// </summary>
        /// <param name="siglaFamiliare"></param>
        /// <param name="dataNascitaFamiliare"></param>
        /// <param name="annoCompetenza"></param>
        /// <param name="causaCarico"></param>
        /// <param name="cessazioneCarico"></param>
        /// <param name="decorrenzaCarico"></param>
        /// <param name="messaggioVideo"></param>
        /// <returns></returns>
        public static bool CI_VerificaCessazioneCarico(char? siglaFamiliare, DateTime? dataNascitaFamiliare, int? annoCompetenza, byte? causaCarico, DateTime? cessazioneCarico, DateTime? decorrenzaCarico, out string messaggioVideo)
        {
            messaggioVideo = string.Empty;

            DateTime? cessazione = CalcolaCessazioneCarico(siglaFamiliare, dataNascitaFamiliare, annoCompetenza, causaCarico);
            DateTime? dataCompare = new DateTime(Utility.DataSistemaCi.Year, 12, 31);
            DateTime? cessazioneCompare = null;

            if (!cessazioneCarico.HasValue)
                if (siglaFamiliare.GetValueOrDefault() == 'N' || siglaFamiliare.GetValueOrDefault() == 'J')
                    cessazioneCarico = new DateTime(annoCompetenza.Value + 1, 01, 01);

            if (cessazioneCarico.HasValue)
                cessazioneCompare = cessazioneCarico;
            else
                cessazioneCompare = DateTime.MinValue;

            if (dataCompare.Value.Year < annoCompetenza)
                dataCompare = dataCompare.Value.AddYears(-dataCompare.Value.Year + annoCompetenza.Value);

            if (cessazione.HasValue && !Utility.DataSuccessivaA(cessazione.Value, new DateTime(2099, 01, 01)))
            {
                if (!Utility.DataStrettamenteSuccessivaA(cessazione.Value, dataCompare.Value) && cessazioneCompare.Equals(DateTime.MinValue))
                {
                    messaggioVideo = "Cessazione Maggiorazione mancante (" + cessazione.Value.Month + "/" + cessazione.Value.Year + ")";
                    return false;
                }
            }

            if (cessazione.HasValue && Utility.DataStrettamenteSuccessivaA(cessazioneCompare.Value, cessazione.Value))
            {
                messaggioVideo = "Cessazione Maggiorazione incompatibile con Sigla (" + cessazione.Value.Month.ToString().PadLeft(2, '0') + "/" + cessazione.Value.Year + ")";
                return false;
            }

            if (!cessazioneCompare.Equals(DateTime.MinValue))
            {
                if (!Utility.DataStrettamenteSuccessivaA(cessazioneCompare.Value, decorrenzaCarico.Value))
                {
                    if (!(cessazioneCompare.Equals(decorrenzaCarico) && causaCarico.GetValueOrDefault() == 2))
                    {
                        messaggioVideo = "Cessazione Maggiorazione anteriore alla Decorrenza Maggiorazione";
                        return false;
                    }
                }
            }
            else
            {
                if (cessazione.HasValue && !Utility.DataStrettamenteSuccessivaA(cessazione.Value, decorrenzaCarico.Value))
                {
                    messaggioVideo = "Cessazione Maggiorazione anteriore alla Decorrenza Maggiorazione";
                    return false;
                }
            }

            return true;
        }

        /// <summary>
        /// 69.	Se APPO-CAT1 è uguale a "S" effettuare le seguenti operazioni : 
        /// 69.1.	Se (IW4CES(INDICE) è uguale a 0 oppure IW4CESA(INDICE) è maggiore di DATA-SYS-SSAA) oppure ( IW4CESA(INDICE) è uguale a DATA-SYS-SSAA e IW4CESM(INDICE) è 
        /// maggiore di DATA-SYS-MM  +  1) effettuare le seguenti operazioni :                                                      
        ///       *** CONTROLLA SE STESSO NOME DELL'INTESTATARIO                    
        /// 69.1.1.	Se ( TP1COGNF(INDICE) è uguale a TP1COG1 e TP1NOMEF(INDICE) è uguale a TP1NOM1 e IW4SES (INDICE) è uguale a IW1SESTIT e WDANAS8 è uguale a IW1NATIT) effettuare 
        /// le seguenti operazioni :
        /// 69.1.1.1.	Valorizzare con "S" il campo PRESENZA-TITOLARE; 
        /// **********  SE INTESTATARIO CONTROLLO LA RELAZIONE DI PARENTELA         
        /// 69.1.1.2.	Se (IW4SIG(INDICE) è uguale a "C" e IRELPAR non è uguale a "CONIUGE ") oppure ((IW4SIG(INDICE) è uguale a "M" oppure "S" oppure "L" oppure "U" oppure "I" 
        /// oppure "N" oppure "J" oppure "Z" oppure "W" oppure "K") e (IRELPAR(1:3) non è uguale a "FIG" e "NIP")) oppure ( (IW4SIG(INDICE) è uguale a "A"  oppure "G" oppure "F") e 
        /// IRELPAR(1:3) non è uguale a "SOR" e "FRA" e "GEN") valorizzare con "39" il campo TIPO-ERRORE, con 6 il campo COL-ERR1, con "INCOMPATIBILITA' TRA SIGLA TITOLARE E RELAZ.
        /// PARENTELA PAN.CNV14" il campo MESSAGGIO-ERRORE, con 1 il campo FLAG-ERR e uscire da CONTROLLI-1 (70);
        /// 69.1.1.3.	Se IW4SIG(INDICE) è uguale a "C" e TP1STACIV è uguale a 2 valorizzare con "39" il campo TIPO-ERRORE, con 6 il campo COL-ERR1, con "INCOMPATIBILITA' TRA SIGLA 
        /// TITOLARE (CONIUGE) E STATO CIVILE" il campo MESSAGGIO-ERRORE, con 1 il campo FLAG-ERR e uscire da CONTROLLI-1 (70);
        /// </summary>
        /// <param name="tipoDomanda"></param>
        /// <param name="cessazioneCarico"></param>
        /// <param name="codiceFiscaleTitolare"></param>
        /// <param name="codiceFiscaleFamiliare"></param>
        /// <param name="siglaFamiliare"></param>
        /// <param name="relazioneDiParentelaDC"></param>
        /// <param name="ultimoStatoCivile"></param>
        /// <param name="annoCompetenza"></param>
        /// <param name="messaggioVideo"></param>
        /// <returns></returns>
        public static bool CI_VerificaSiglaFamiliareWithDC(Utility.TipoDomanda tipoDomanda, DateTime? cessazioneCarico, string codiceFiscaleTitolare, string codiceFiscaleFamiliare, GestioneFamiliari.Familiare familiare,
            byte? relazioneDiParentelaDC, char ultimoStatoCivile, int annoCompetenza, byte? codiceMaggiorazioneFamiliare, out string messaggioVideo)
        {
            messaggioVideo = string.Empty;
            DateTime dataSistema = Utility.DataSistemaCi;

            if (tipoDomanda == Utility.TipoDomanda.Superstiti)
            {
                if (!cessazioneCarico.HasValue)
                    if (familiare != null && (familiare.SiglaFamiliare.GetValueOrDefault() == 'N' || familiare.SiglaFamiliare.GetValueOrDefault() == 'J'))
                        cessazioneCarico = new DateTime(annoCompetenza + 1, 01, 01);

                if (!cessazioneCarico.HasValue || cessazioneCarico.Value.Year > dataSistema.Year || (cessazioneCarico.Value.Year == dataSistema.AddMonths(1).Year && cessazioneCarico.Value.Month == dataSistema.AddMonths(1).Month))
                {
                    if (familiare != null && codiceFiscaleFamiliare == codiceFiscaleTitolare)
                    {
                        if ((familiare.IsConiuge() && relazioneDiParentelaDC.HasValue && relazioneDiParentelaDC.Value != 1) ||
                            (familiare.IsUnitoCivile() && relazioneDiParentelaDC.HasValue && relazioneDiParentelaDC.Value != 21) ||
                            ((new List<char> { 'M', 'S', 'L', 'U', 'I', 'N', 'J', 'Z', 'W', 'K' }).Contains(familiare.SiglaFamiliare.GetValueOrDefault()) &&
                            (relazioneDiParentelaDC.GetValueOrDefault() != 2 && relazioneDiParentelaDC.GetValueOrDefault() != 3 && relazioneDiParentelaDC.GetValueOrDefault() != 14)) ||
                            (new List<char> { 'A', 'G', 'F' }).Contains(familiare.SiglaFamiliare.GetValueOrDefault()) && (relazioneDiParentelaDC.GetValueOrDefault() != 5 && relazioneDiParentelaDC.GetValueOrDefault() != 4 && relazioneDiParentelaDC.GetValueOrDefault() != 6))
                        {
                            messaggioVideo = "Incompatibilita' tra Sigla Titolare e Relazione di Parentela del Dante Causa";
                            return false;
                        }
                        if (familiare.IsConiuge() && ultimoStatoCivile == 2)
                        {
                            messaggioVideo = "Incompatibilita' tra Sigla Titolare (Coniuge) e Stato Civile";
                            return false;
                        }
                        if (familiare.IsUnitoCivile() && ultimoStatoCivile == 7)
                        {
                            messaggioVideo = "Incompatibilita' tra Sigla Titolare (Unito/a Civilmente) e Stato Civile";
                            return false;
                        }
                    }
                }

                if (familiare != null && familiare.SiglaFamiliare.GetValueOrDefault() == 'A')
                {

                    if (codiceMaggiorazioneFamiliare.GetValueOrDefault() != 2)
                    {
                        messaggioVideo = "Incompatibilita' tra Codice Maggiorazione e Sigla";
                        return false;
                    }
                }
            }

            return true;
        }

        /// <summary>
        /// 76.	Eseguire un ciclo a conteggio variando IND1 da 1 con incrementi di 1 fino a quando IND1 è maggiore di 15 oppure IW4SIG(IND1) è uguale a " ", nel ciclo eseguire le 
        /// seguenti istruzioni :
        /// 76.1.	Eseguire un ciclo a conteggio variando IND2 da 1 con incrementi di 1 fino a quando IND1 è maggiore di 15 oppure IW4SIG(IND2) è uguale a " ", nel ciclo eseguire 
        /// le seguenti istruzioni :          
        /// 76.1.1.	Se ( IND1 non è uguale a IND2 e TP1COGNF(IND1) è uguale a TP1COGNF(IND2) e TP1NOMEF(IND1) è uguale a TP1NOMEF(IND2) e IDATANAS(IND1) è uguale a IDATANAS(IND2)) 
        /// effettuare le seguenti operazioni : 
        /// 76.1.1.1.	Se W4CES(IND1) è maggiore di 0 valorizzare con IW4CES(IND1) il campo W-CESSAZ, diversamente valorizzare con 999999 il campo W-CESSAZ; 
        /// 76.1.1.2.	Se IW4ACQ(IND2) è maggiore di è uguale a IW4ACQ(IND1) e IW4ACQ(IND2) è minore di W-CESSAZ valorizzare con "37" il campo TIPO-ERRORE, con IND2 il campo 
        /// RIG-ERRORE, con 7 il campo COL-ERR1, con 8 il campo COL-ERR2, con "STESSO FAMILIARE CON PERIODI INCOMPATIBILI" il campo MESSAGGIO-ERRORE, con 1 il campo FLAG-ERR e 
        /// uscire da CONTROLLI-2 (78);                               
        /// </summary>
        /// <param name="listaFamiliari"></param>
        /// <param name="listaCoddMaggiorazione"></param>
        /// <param name="messaggioVideo"></param>
        /// <returns></returns>
        public static bool CI_VerificaCoerenzaPeriodi(List<GestioneFamiliari.Familiare> listaFamiliari, List<GestioneFamiliari.CodMaggFamiliari> listaCoddMaggiorazione, out string messaggioVideo)
        {
            messaggioVideo = string.Empty;

            if (listaFamiliari != null && listaFamiliari.Count > 0)
            {
                if (listaCoddMaggiorazione != null && listaCoddMaggiorazione.Count > 0)
                {
                    foreach (GestioneFamiliari.Familiare fam in listaFamiliari)
                    {
                        if (fam.Confermato)
                        {
                            List<GestioneFamiliari.CodMaggFamiliari> lCodiciMaggiorazione = listaCoddMaggiorazione.FindAll(x => x.IdAnagrafica == fam.IdAnagrafica);
                            foreach (GestioneFamiliari.CodMaggFamiliari codice1 in lCodiciMaggiorazione)
                            {
                                foreach (GestioneFamiliari.CodMaggFamiliari codice2 in lCodiciMaggiorazione)
                                {
                                    if (!codice1.Equals(codice2))
                                    {
                                        if (Utility.DataSuccessivaA(codice2.Decorrenza.Value, codice1.Decorrenza.Value) && codice1.Cessazione.HasValue && !Utility.DataSuccessivaA(codice2.Decorrenza.Value, codice1.Cessazione.Value))
                                        {
                                            messaggioVideo = "Periodi incompatibili tra i Codici Maggiorazione";
                                            return false;
                                        }
                                    }
                                }
                            }
                        }
                    }
                }
            }

            return true;
        }

        /// <summary>
        /// 77.	Se "2" è uguale a CODSCIV(1) oppure CODSCIV(2) oppure CODSCIV(3) oppure CODSCIV(4) oppure CODSCIV(5) oppure CODSCIV(6) oppure CODSCIV(7) oppure CODSCIV(8) oppure 
        /// CODSCIV(9) oppure CODSCIV(10) effettuare le seguenti operazioni : 
        /// 77.1.	Eseguire un ciclo a conteggio variando IND1 da 1 con incrementi di 1 fino a quando IND1 è maggiore di 15 oppure IW4SIG(IND1) è uguale a "C ", nel ciclo eseguire 
        /// le seguenti istruzioni :          
        /// cg2012*******   controllo per data matrimonio   18.11.2011  appunto 135 
        /// 77.1.2.	Se il valore costituito dal primo carattere contenuti nel campo IW1CAT8 è uguale a "S" e IW1DEORIG è maggiore di '201200' e DATA-MATRIM non è maggiore di 0 e 
        /// (IW4SIG(1) è uguale a "C" oppure IW4SIG(2) è uguale a "C"	oppure IW4SIG(3) è uguale a "C" oppure IW4SIG(4) è uguale a "C"	oppure IW4SIG(5) è uguale a "C" oppure 
        /// IW4SIG(6) è uguale a "C"	oppure IW4SIG(7) è uguale a "C" oppure IW4SIG(8) è uguale a "C"	oppure IW4SIG(9) è uguale a "C" oppure IW4SIG(10) è uguale a "C"	oppure 
        /// IW4SIG(11) è uguale a "C" oppure IW4SIG(12) è uguale a "C" ) valorizzare con "38" il campo TIPO-ERRORE, con "Manca data di matrimonio con dante causa nel pannello CNV14 
        /// " il campo MESSAGGIO-ERRORE, con 1 il campo FLAG-ERR;              
        /// </summary>
        /// <param name="tipoDomanda"></param>
        /// <param name="decorrenzaOriginaria"></param>
        /// <param name="presenzaConiugato"></param>
        /// <param name="presenzaConiuge"></param>
        /// <param name="dataMatrimonio"></param>
        /// <param name="messaggioVideo"></param>
        /// <returns></returns>
        public static bool CI_VerificaDataMatrimonioDC(Utility.TipoDomanda tipoDomanda, DateTime? decorrenzaOriginaria, bool presenzaConiugato, bool presenzaConiuge, DateTime? dataMatrimonio, out string messaggioVideo)
        {
            messaggioVideo = string.Empty;

            if (presenzaConiugato)
            {
                if (tipoDomanda == Utility.TipoDomanda.Superstiti && Utility.DataSuccessivaA(decorrenzaOriginaria.Value, new DateTime(2012, 01, 01)) && !dataMatrimonio.HasValue)
                {
                    if (presenzaConiuge)
                    {
                        messaggioVideo = "Manca data di matrimonio con dante causa";
                        return false;
                    }
                }
            }

            return true;
        }

        /// <summary>
        /// 72.	Se APPO-CAT1 è uguale a "S" effettuare le seguenti operazioni : 
        /// 72.1.	Se TP1CODELIM non è maggiore di "0" effettuare le seguenti operazioni : 
        /// 72.1.1.	Se PRESENZA-TITOLARE non è uguale a "S" valorizzare con "34" il campo TIPO-ERRORE, con "NESSUN CONTITOLARE HA GLI STESSI DATI ANAGRAFICI DELL'INTESTATARIO" il 
        /// campo MESSAGGIO-ERRORE, con 1 il campo FLAG-ERR e uscire da CONTROLLI-2 (78);
        /// 73.	Se TP1STACIV è uguale a 2 effettuare le seguenti operazioni : 
        /// 73.1.	Se APPO-CAT1 non è uguale a  "S" e CONIUGE non è uguale a "S" valorizzare con "35" il campo TIPO-ERRORE, con "SE STATO CIVILE = 2, DEVE ESSERCI IL CONIUGE (SENZA 
        /// CESSAZ.)" il campo MESSAGGIO-ERRORE, con 1 il campo FLAG-ERR e uscire da CONTROLLI-2 (78); 
        /// 73.2.	Diversamente da quando analizzato nel punto precedente (73.1) effettuare le seguenti operazioni :
        /// 73.2.1.	Se CONIUGE è uguale a "S" e APPO-CAT1 non è uguale a "S" effettuare le seguenti operazioni : 
        /// CG2010***************** se separato (stato civile è uguale a 4)                  
        /// ********* e gestione speciale, può esserci maggiorazione coniuge        
        /// 73.2.1.1.	Se TP1STACIV è uguale a 4 e IW1CATPEN è maggiore di ccontinuare l'elaborazione al punto successivo (74), diversamente valorizzare con "35" il campo 
        /// TIPO-ERRORE, con "STATO CIVILE DIVERSO DA 2: CONIUGE NON CESSATO" il campo MESSAGGIO-ERRORE, con 1 il campo FLAG-ERR e uscire da CONTROLLI-2 (78); 
        /// </summary>
        /// <param name="tipoDomanda"></param>
        /// <param name="codiceMotivo"></param>
        /// <param name="presenzaTitolare"></param>
        /// <param name="ultimoStatoCivile"></param>
        /// <param name="presenzaConiuge"></param>
        /// <param name="categoria"></param>
        /// <param name="messaggioVideo"></param>
        /// <returns></returns>
        public static bool CI_VerificaObbligatorietaContitolare(Utility.TipoDomanda tipoDomanda, byte? codiceMotivo, bool presenzaTitolare, char ultimoStatoCivile, bool presenzaConiuge, int categoria, out string messaggioVideo)
        {
            messaggioVideo = string.Empty;

            if (tipoDomanda == Utility.TipoDomanda.Superstiti && codiceMotivo.GetValueOrDefault() == 0 && !presenzaTitolare)
            {
                messaggioVideo = "Nessun Contitolare ha gli stessi dati anagrafici dell'Intestatario";
                return false;
            }

            if (ultimoStatoCivile == '2' || ultimoStatoCivile == '7')
            {
                if (tipoDomanda != Utility.TipoDomanda.Superstiti && !presenzaConiuge)
                {
                    messaggioVideo = "Se Stato Civile = 'Coniugato/a', deve esserci il Coniuge (Senza Cessazione)";
                    return false;
                }
            }

            return true;
        }

        /// <summary>
        /// 45.	Se TP1REVF(INDICE) è maggiore di 0 effettuare le seguenti operazioni : 
        /// 45.2.	Se IW4SIG(INDICE) non è uguale a "I" e IW4SIG(INDICE) non è uguale a "J" e  IW4SIG(INDICE) non è uguale a "K" e IW4SIG(INDICE) non è uguale a "Y" e IW1CARIC non 
        /// è uguale a 2 valorizzare con "20" il campo TIPO-ERRORE, con 6 il campo COL-ERR1, con 10 il campo COL-ERR2, con "ERRORE: INCOMPATIBILIA' TRA SIGLA E REVISIONE SANITARIA" 
        /// il campo MESSAGGIO-ERRORE, con 1 il campo FLAG-ERR e uscire da CONTROLLI-1 (70);      
        /// </summary>
        /// <param name="scadenzaRevisioneSanitaria"></param>
        /// <param name="siglaFamiliare"></param>
        /// <param name="causaCarico"></param>
        /// <param name="messaggioVideo"></param>
        /// <returns></returns>
        public static bool CI_VerificaScadenzaRevisioneSanitariaWithDatiGenerici(DateTime? scadenzaRevisioneSanitaria, char? siglaFamiliare, byte? causaCarico, out string messaggioVideo)
        {
            messaggioVideo = string.Empty;

            if (scadenzaRevisioneSanitaria.HasValue)
            {
                if (!(new List<char> { 'I', 'J', 'K', 'Y' }).Contains(siglaFamiliare.GetValueOrDefault()) && causaCarico.GetValueOrDefault() != 2)
                {
                    messaggioVideo = "Errore: incompatibilita' tra Sigla e Revisione Sanitaria";
                    return false;
                }
            }

            return true;
        }

        /// <summary>
        /// 45.	Se TP1REVF(INDICE) è maggiore di 0 effettuare le seguenti operazioni : 
        /// 45.3.	Se TP1REVF(INDICE) non è maggiore dei primi 6 caratteri del campo DATA-GIORNO valorizzare con "20" il campo TIPO-ERRORE, con 10 il campo COL-ERR2, con "ERRORE: 
        /// DATA REVISIONE SANITARIA NON POSTERIORE DATA ODIERNA" il campo ESSAGGIO-ERRORE, con 1 il campo FLAG-ERR e uscire da CONTROLLI-1 (70);
        /// 46.5.	Se IW4ACQ(INDICE) è minore di IW1DEORIG valorizzare con "20" il campo TIPO-ERRORE, con 7 il campo COL-ERR1, con "ERRORE: DECORRENZA ANTERIORE A DECORRENZA ORIGINARIA PENSIONE" il campo MESSAGGIO-ERRORE, con 1 il campo FLAG-ERR e uscire da CONTROLLI-1 (70);                             
        /// 46.6.	Se IW4ACQ(INDICE) è minore di (IW4NASC(INDICE) / 100) valorizzare con "21" il campo TIPO-ERRORE, con 4 il campo COL-ERR1, con 7 il campo COL-ERR2, con "DECORRENZA MAGGIORAZIONE ANTERIORE ALLA DATA DI NASCITA" il campo MESSAGGIO-ERRORE, con 1 il campo FLAG-ERR e uscire da CONTROLLI-1 (70); 
        /// 46.7.	Se IW4ACQ(INDICE) è maggiore di (DATA-GIORNO / 100) effettuare le seguenti operazini :                  
        /// 46.7.1.	Se IW4ACQ(INDICE) è maggiore di MESESUC valorizzare con "21" il campo TIPO-ERRORE, con 7 il campo COL-ERR1, con "DECORRENZA MAGGIORAZIONE POSTERIORE ALLA DATA ODIERNA" il campo MESSAGGIO-ERRORE, con 1 il campo FLAG-ERR e uscire da CONTROLLI-1 (70);                              
        /// 46.8.	Se APPO-CAT1 è uguale a "S" e IW4SIG(INDICE) è uguale a "C" effettuare le seguenti operazioni : 
        /// 46.8.1.	Se IW4ACQ(INDICE) non è uguale a IW1DEORIG effettuare le seguenti operazioni :                                                    
        /// 46.8.2.	Se INDICE è maggiore di 1 e IW4CMAG(INDICE) è uguale a 1 e IW4SIG(1) è uguale a "C" e IW4CMAG(1) è uguale a 2 continuare l'elaborazione al punto successivo (46) diversamente valorizzare con "22" il campo TIPO-ERRORE, con 7 il campo COL-ERR1, con "DECORRENZA CONIUGE NON UGUALE A DECORRENZA ORIGINARIA PENSIONE" il campo MESSAGGIO-ERRORE, con 1 il campo FLAG-ERR e uscire da CONTROLLI-1 (70);
        /// </summary>
        /// <param name="scadenzaRevisioneSanitaria"></param>
        /// <param name="messaggioVideo"></param>
        /// <returns></returns>
        public static bool CI_VerificaScadenzaRevisioneSanitaria(Utility.TipoDomanda tipoDomanda, DateTime? decorrenzaOriginaria, DateTime? dataNascitaFamiliare,
            int index, List<GestioneFamiliari.CodMaggFamiliari> LcodMaggFam, GestioneFamiliari.Familiare familiare, byte? codMaggPrimoFamiliare, out string messaggioVideo)
        {
            messaggioVideo = string.Empty;
            DateTime? dataNascitaFamiliareApp = null;
            DateTime dataSistema = Utility.DataSistemaCi;

            if (familiare.ScadenzaRevisioneSanitaria.HasValue)
            {
                if (!Utility.DataStrettamenteSuccessivaA(familiare.ScadenzaRevisioneSanitaria.Value, new DateTime(dataSistema.Year, dataSistema.Month, 01)))
                {
                    messaggioVideo = "Errore: Data Revisione Sanitaria non posteriore Data Odierna";
                    return false;
                }

                foreach (GestioneFamiliari.CodMaggFamiliari codFamiliare in LcodMaggFam)
                {
                    if (codFamiliare.Decorrenza.HasValue && !Utility.DataSuccessivaA(codFamiliare.Decorrenza.Value, decorrenzaOriginaria.Value))
                    {
                        messaggioVideo = "Errore: Decorrenza anteriore a decorrenza originaria pensione";
                        return false;
                    }

                    if (dataNascitaFamiliare.HasValue)
                    {
                        dataNascitaFamiliareApp = new DateTime(dataNascitaFamiliare.Value.Year, dataNascitaFamiliare.Value.Month, 01);
                        if (codFamiliare.Decorrenza.HasValue && !Utility.DataSuccessivaA(codFamiliare.Decorrenza.Value, dataNascitaFamiliareApp.Value))
                        {
                            messaggioVideo = "Decorrenza maggiorazione anteriore alla data di nascita";
                            return false;
                        }
                    }

                    if (codFamiliare.Decorrenza.HasValue && Utility.DataStrettamenteSuccessivaA(codFamiliare.Decorrenza.Value, (new DateTime(dataSistema.Year, dataSistema.Month, 01)).AddMonths(1)))
                    {
                        messaggioVideo = "Decorrenza maggiorazione posteriore alla data odierna";
                        return false;
                    }

                    if (tipoDomanda == Utility.TipoDomanda.Superstiti)
                    {
                        if (familiare.IsConiugeOrUnitoCivile() && codFamiliare.Decorrenza.HasValue && !codFamiliare.Decorrenza.Equals(decorrenzaOriginaria) && !(index > 0 && codFamiliare.CodiceMaggiorazione.GetValueOrDefault() == 1 &&
                            codMaggPrimoFamiliare.GetValueOrDefault() == 2))
                        {
                            messaggioVideo = "Decorrenza coniuge non uguale a decorrenza originaria pensione";
                            return false;
                        }
                    }
                }
            }

            return true;
        }

        /// <summary>
        /// 44.	 Se IW4SIG(INDICE) è uguale a "A" e IW4SIG(INDICE-1) non è uguale a "A" oppure  IW4SIG(INDICE) è maggiore di "A" e IW4SIG(INDICE-1) è uguale a "A" valorizzare con 
        /// "18" il campo TIPO-ERRORE, con 6 il campo COL-ERR1, con "SIGLA 'A' INCOMPATIBILE CON SIGLA PRE CEDENTE CONTITOLARE" il campo MESSAGGIO-ERRORE, con 1 il campo FLAG-ERR e 
        /// uscire da CONTROLLI-1 (70);
        /// </summary>
        /// <param name="listaFamiliari"></param>
        /// <param name="messaggioVideo"></param>
        /// <returns></returns>
        public static bool CI_VerificaSiglaFamiliareAscendente(List<GestioneFamiliari.Familiare> listaFamiliari, out string messaggioVideo)
        {
            messaggioVideo = string.Empty;

            if (listaFamiliari != null && listaFamiliari.Count > 1)
            {
                for (int i = 1; i < listaFamiliari.Count; i++)
                {
                    if (listaFamiliari[i].Confermato && ((listaFamiliari[i].SiglaFamiliare.GetValueOrDefault() == 'A' && listaFamiliari[i - 1].SiglaFamiliare.GetValueOrDefault() != 'A') ||
                        (listaFamiliari[i].SiglaFamiliare.GetValueOrDefault() > 'A' && listaFamiliari[i - 1].SiglaFamiliare.GetValueOrDefault() == 'A')))
                    {
                        messaggioVideo = "Sigla 'A' incompatibile con Sigla precedente Contitolare";
                        return false;
                    }
                }
            }

            return true;
        }

        /// <summary>
        /// 40.	Se ( (IW4SIG(INDICE) è uguale a "M" oppure "S" oppure "U" oppure "I" oppure "L") oppure (APPO-CAT1 non è uguale a "S" AND(IW4SIG(INDICE) è uguale a "N" oppure "J" oppure "G" oppure "P" oppure "Y" oppure "F" )) oppure (APPO-CAT1 è uguale a "S" e (IW4SIG(INDICE) è uguale a "N" oppure "J" oppure "Z" oppure "W" oppure "K" oppure "F")) ) effettuare le seguenti operazioni : 
        /// 40.1.	Continuare l'elaborazione al punto successivo (42);
        /// 41.	Diversamente da quando analizzato nel punto precedente effettuare le seguenti operazioni : 
        /// 41.1.	Se IW4SIG(INDICE) è uguale a "C" effettuare le seguenti operazioni : 
        /// 41.1.3.	Se (IW1CATPEN è maggiore di 6 e IW4CMAG(INDICE) è uguale a 0) 
        /// **************** 18.1.2001                                              
        ///                   e WAFAL6 non è uguale a WAFDAL6                           
        /// **************** 18.1.2001                                              
        /// valorizzare con "14" il campo TIPO-ERRORE, con 3 il campo COL-ERR1, con 6 il campo COL-ERR2, con "CODICE MAGGIORAZIONE INCOMPATIBILE CON SIGLA" il campo MESSAGGIO-ERRORE, con 
        /// 1 il campo FLAG-ERR e uscire da CONTROLLI-1 (70); 
        /// 41.1.4.	Se ( (TP1NUA + TP1NUB + ICI2SETFIT + IABNSASS ) è minore di 52 e ICI2CONV è uguale a 12 e APPO-CAT1 è uguale a "S") effettuare le seguenti operazioni : 
        /// 41.1.4.1.	Se IW1DIRET è maggiore di 0 valorizzare con IW1DIRET il campo W-DEORIG diversamente con IW1DEORIG;     
        /// 41.1.4.2.	Se W-DEORIG è maggiore di  197209 effettuare le seguenti operazioni :                                             
        /// 41.1.4.2.1.	Se (ICI2CONV è uguale a 12 e STATO(1) è uguale a 17) e (IW1DEORIG è maggiore di 200205) e (IW1DIRET è maggiore di 0 e è minore di 200206) continuare 
        /// l'elaborazione al punto successivo (42), diversamente effettuare le seguenti operazioni : 
        /// cg2011******* 25.01.2011   x appunto 8/2011 - sentenza slovenia/croazia 
        /// 41.1.4.2.2.	Se APPO-CAT1 è uguale a "S" e ICI2CONV è uguale a 12 e STATO(1) è uguale a 38 e TP1CATD è maggiore di 0 continuare l'elaborazione al punto successivo (42), 
        /// diversamente effettuare le seguenti operazioni :
        /// ******************* SE TRATTASI SO PROVENIENTE DA VECCHIA A SUA VOLTA   
        /// ******************* PROVENIENTE DA TRASFORMAZIONE DI INVALIDITA', DEVE  
        /// ******************* PASSARE (NON POSSO CONTROLLARLO, PER CUI METTO GLI  
        /// ******************* IDENTIFICATIVI DELLA PENSIONE A PROGRAMMA)          
        /// valorizzare con "15" il campo TIPO-ERRORE, con 6 il campo COL-ERR1, con "SIGLA 'C' INCOMPATIBILE CON CONTRIBUTI INFERIORI A 52" il campo MESSAGGIO-ERRORE, con 1 il campo 
        /// FLAG-ERR e uscire da CONTROLLI-1 (70); 
        /// </summary>
        /// <param name="siglaFamiliare"></param>
        /// <param name="tipoDomanda"></param>
        /// <param name="categoria"></param>
        /// <param name="listaCodMaggFamiliari"></param>
        /// <param name="messaggioVideo"></param>
        /// <returns></returns>
        public static bool CI_VerificaSiglaFamiliare(GestioneFamiliari.Familiare familiare, Utility.TipoDomanda tipoDomanda, int categoria, List<GestioneFamiliari.CodMaggFamiliari> listaCodMaggFamiliari,
            int? settimaneItalianeDiritto, int? nSettimaneOBG, int? nContributiUtiliLavoratoriAutonomi, int? nContributiVolontari, int? nSettFittiziePrepensionamento, int? nSettimaneGodimentoAssegno, byte? codiceConvenzione,
            DateTime? decorrenzaPensioneDiretta, DateTime? decorrenzaOriginaria, int? codicePrimoStatoEE, string categoriaPensioneDiretta, out string messaggioVideo)
        {
            messaggioVideo = string.Empty;
            int settimane = 0;
            DateTime? decorrenza;

            if (settimaneItalianeDiritto.HasValue)
                settimane = settimaneItalianeDiritto.Value;
            else if (nSettimaneOBG.HasValue)
                settimane = nSettimaneOBG.Value;
            else if (nContributiUtiliLavoratoriAutonomi.HasValue)
                settimane = nContributiUtiliLavoratoriAutonomi.Value;
            else settimane = 0;

            if (!((new List<char> { 'M', 'S', 'U', 'I', 'L', 'V' }).Contains(familiare.SiglaFamiliare.GetValueOrDefault()) ||
                (tipoDomanda != Utility.TipoDomanda.Superstiti && (new List<char> { 'N', 'J', 'G', 'P', 'Y', 'F' }).Contains(familiare.SiglaFamiliare.GetValueOrDefault())) ||
                (tipoDomanda == Utility.TipoDomanda.Superstiti && (new List<char> { 'N', 'J', 'Z', 'W', 'K', 'F' }).Contains(familiare.SiglaFamiliare.GetValueOrDefault()))))
            {
                if (familiare.IsConiugeOrUnitoCivile())
                {
                    if (listaCodMaggFamiliari != null && listaCodMaggFamiliari.Count > 0)
                    {
                        foreach (GestioneFamiliari.CodMaggFamiliari codMaggFamiliari in listaCodMaggFamiliari)
                        {
                            if (categoria > 6 && !(categoria == 87 || categoria == 90 || categoria == 93) && codMaggFamiliari.CodiceMaggiorazione == 0 && !codMaggFamiliari.Decorrenza.Equals(codMaggFamiliari.Cessazione))
                            {
                                messaggioVideo = "Codice Maggiorazione incompatibile con Sigla";
                                return false;
                            }
                        }
                    }

                    if ((settimane + nContributiVolontari.GetValueOrDefault() + nSettFittiziePrepensionamento.GetValueOrDefault() + nSettimaneGodimentoAssegno.GetValueOrDefault()) < 52 && codiceConvenzione.GetValueOrDefault() == 12 && tipoDomanda == Utility.TipoDomanda.Superstiti)
                    {
                        if (decorrenzaPensioneDiretta.HasValue)
                            decorrenza = decorrenzaPensioneDiretta;
                        else
                            decorrenza = decorrenzaOriginaria;

                        if (Utility.DataStrettamenteSuccessivaA(decorrenza.Value, new DateTime(1972, 09, 30)))
                        {
                            if (!((codiceConvenzione.GetValueOrDefault() == 12 && codicePrimoStatoEE.GetValueOrDefault() == 17) && Utility.DataStrettamenteSuccessivaA(decorrenzaOriginaria.Value, new DateTime(2002, 05, 31)) && (decorrenzaPensioneDiretta.HasValue && !Utility.DataSuccessivaA(decorrenzaPensioneDiretta.Value, new DateTime(2002, 06, 01)))))
                            {
                                if (!(tipoDomanda == Utility.TipoDomanda.Superstiti && codiceConvenzione.GetValueOrDefault() == 12 && codicePrimoStatoEE.GetValueOrDefault() == 38 && !string.IsNullOrEmpty(categoriaPensioneDiretta) && !string.IsNullOrEmpty(categoriaPensioneDiretta.Trim())))
                                {
                                    messaggioVideo = "Sigla 'C' incompatibile con contributi inferiori a 52";
                                    return false;
                                }
                            }
                        }
                    }
                }
                else
                {
                    if ((new List<char> { 'A', 'Z', 'W', 'K', 'O' }).Contains(familiare.SiglaFamiliare.GetValueOrDefault()))
                    {
                        if (tipoDomanda != Utility.TipoDomanda.Superstiti)
                        {
                            messaggioVideo = "Sigla 'A-Z-W-K-O' incompatibile con categoria di pensione";
                            return false;
                        }
                    }
                    else
                    {
                        messaggioVideo = "Sigla errata: C - M - S - U - I - L - A - N - J - Z - W - K - F - G - P - Y";
                        return false;
                    }
                }
            }

            return true;
        }

        #endregion PCIPL11

        #endregion Familiari

        #region Dante Causa
        #region PCIPL25
        /// <summary>
        /// PCIPL25
        /// </summary>
        /// <param name="codiceFiscale"></param>
        /// <param name="cognome"></param>
        /// <param name="nome"></param>
        /// <param name="dataNascitaDC"></param>
        /// <param name="dataMorte"></param>
        /// <param name="decorrenzaResidenza"></param>
        /// <param name="cittadinanza"></param>
        /// <param name="causaCarico"></param>
        /// <param name="statoEEResidenza"></param>
        /// <param name="decorrenzaPensioneDC"></param>
        /// <param name="parentela"></param>
        /// <param name="sessoDC"></param>
        /// <param name="sessoTitolare"></param>
        /// <param name="codiceStatoCivile"></param>
        /// <param name="cognomeAcquisito"></param>
        /// <param name="dataMatrimonio"></param>
        /// <param name="decorrenzaOriginaria"></param>
        /// <param name="listaFamiliari"></param>
        /// <param name="messaggioVideo"></param>
        /// <returns></returns>
        public static bool CI_ControlsAnagraficaDanteCausa(string codiceFiscale, string cognome, string nome, DateTime? dataNascitaDC, DateTime? dataMorte, DateTime? decorrenzaResidenza, string cittadinanza,
            byte? causaCarico, string statoEEResidenza, DateTime? decorrenzaPensioneDC, byte? parentela, char? sessoDC, char? sessoTitolare, char? codiceStatoCivile, string cognomeAcquisito,
            DateTime? dataMatrimonio, DateTime? decorrenzaOriginaria, List<GestioneFamiliari.Familiare> listaFamiliari, List<GestioneAnagrafica.DatiAnagrafici> listaAnagraficaFamiliari, string categoria, out string messaggioVideo)
        {
            messaggioVideo = string.Empty;

            if (string.IsNullOrEmpty(codiceFiscale))
            {
                messaggioVideo = "Codice Fiscale mancante o errato";
                return false;
            }
            else if (codiceFiscale.Contains("DANTEC_"))
            {
                return true;
            }

            if (!string.IsNullOrEmpty(cognome) && !Utility.VerificaRegex(cognome.Substring(0, 1), pattern: "[a-zA-Z]"))
            {
                messaggioVideo = "Cognome errato";
                return false;
            }

            if (!string.IsNullOrEmpty(nome) && !Utility.VerificaRegex(nome.Substring(0, 1), pattern: "[a-zA-Z]"))
            {
                messaggioVideo = "Nome errato";
                return false;
            }

            if (!Utility.VerificaData(dataNascitaDC, Utility.TipoAppartenenza.CI, out messaggioVideo))
            {
                messaggioVideo = "Data Nascita illogica o mancante: " + messaggioVideo;
                return false;
            }

            if (dataMorte.HasValue && Utility.DataStrettamenteSuccessivaA(dataNascitaDC.Value, dataMorte.Value))
            {
                messaggioVideo = "Data Nascita incompatibile con Data Morte";
                return false;
            }

            if (decorrenzaResidenza.HasValue && decorrenzaResidenza.Value.Year < 1930)
            {
                messaggioVideo = "Data Residenza 'Dal' errata o illogica";
                return false;
            }

            if (string.IsNullOrEmpty(cittadinanza) && causaCarico.GetValueOrDefault() != 2)
            {
                messaggioVideo = "Cittadinanza alla morte mancante";
                return false;
            }

            if (!((causaCarico.GetValueOrDefault() == 2 && !decorrenzaResidenza.HasValue) || (!decorrenzaResidenza.HasValue && string.IsNullOrEmpty(statoEEResidenza))))
            {
                if ((!decorrenzaResidenza.HasValue && !string.IsNullOrEmpty(statoEEResidenza)) || (decorrenzaResidenza.HasValue && string.IsNullOrEmpty(statoEEResidenza)))
                {
                    messaggioVideo = "Dati Residenza Estera incompatibili";
                    return false;
                }

                if (!decorrenzaPensioneDC.HasValue)
                {
                    if (decorrenzaResidenza != null && dataMorte != null &&
                        decorrenzaResidenza.Value.Year != dataMorte.Value.Year &&
                        decorrenzaResidenza.Value.Month != dataMorte.Value.Month)
                    {
                        messaggioVideo = "Data Residenza 'Dal' diversa da Data Morte";
                        return false;
                    }
                }
                else
                {
                    if (decorrenzaResidenza != null && dataMorte != null &&
                        (!Utility.DataSuccessivaA(decorrenzaResidenza.Value, decorrenzaPensioneDC.Value) ||
                        Utility.DataStrettamenteSuccessivaA(new DateTime(decorrenzaResidenza.Value.Year, decorrenzaResidenza.Value.Month, 01), new DateTime(dataMorte.Value.Year, dataMorte.Value.Month, 01))))
                    {
                        messaggioVideo = "Data Residenza 'Dal' errata";
                        return false;
                    }
                }
            }

            if (!(new List<byte> { 1, 2, 3, 4, 5, 6, 14, 21 }.Contains(parentela.GetValueOrDefault())))
            {
                messaggioVideo = "Rapporto di Parentela errato (Coniuge/Figlio-a/Sorella/Fratello/Genitore/Nipote/Unito civilmente)";
                return false;
            }

            if (parentela.GetValueOrDefault() == 1 && sessoDC == sessoTitolare)
            {
                messaggioVideo = "Parentela Coniuge incompatibile con sesso";
                return false;
            }
            if (parentela.GetValueOrDefault() == 1 && sessoTitolare == 'F' && codiceStatoCivile == 3)
            {
                if (!cognome.Equals(cognomeAcquisito))
                {
                    messaggioVideo = "Cognome Acquisito Titolare diverso da cognome coniuge Dante Causa";
                    return false;
                }
            }


            if (!(categoria.ToUpperInvariant().StartsWith("S")))
            {
                if (listaFamiliari != null && listaFamiliari.Count > 0)
                {
                    if (listaFamiliari.FindIndex(x => (x.IsConiugeOrUnitoCivile() || x.IsExConiugeOrScioltoDallUnione()) && x.Confermato) > -1 && !dataMatrimonio.HasValue)
                    {
                        messaggioVideo = "Data Matrimonio obbligatoria in presenza di un familiare avente come grado di parentela 'Coniuge' o 'Unito/a Civilmente'.";
                        return false;
                    }
                }
            }


            if (dataMatrimonio.HasValue)
            {
                if (!Utility.VerificaData(dataMatrimonio, Utility.TipoAppartenenza.CI, out messaggioVideo))
                {
                    messaggioVideo = "Data Matrimonio illogica: " + messaggioVideo;
                    return false;
                }

                if (dataMorte.HasValue && !Utility.DataSuccessivaA(dataMorte.Value, dataMatrimonio.Value))
                {
                    messaggioVideo = "Data Matrimonio successiva a Data Morte";
                    return false;
                }

                if (listaAnagraficaFamiliari != null && listaAnagraficaFamiliari.Count > 0 && listaFamiliari[0].IsConiugeOrUnitoCivile() && Utility.DataSuccessivaA(listaAnagraficaFamiliari[0].DataNascita.Value, dataMatrimonio.Value))
                {
                    messaggioVideo = "Data Matrimonio antecedente a Data Nascita Richiedente";
                    return false;
                }

                if (dataNascitaDC.HasValue && Utility.DataStrettamenteSuccessivaA(dataNascitaDC.Value, dataMatrimonio.Value))
                {
                    messaggioVideo = "Data Matrimonio antecedente a Data Nascita Dante Causa";
                    return false;
                }
            }
            else
            {
                if (decorrenzaOriginaria.Value.Year > 2012 && listaFamiliari != null)
                {
                    int index = listaFamiliari.FindIndex(x => x.IsConiugeOrUnitoCivile() && x.Confermato);
                    if (parentela.GetValueOrDefault() == 1 || parentela.GetValueOrDefault() == 21 || (index < 9 && index > -1))
                    {
                        messaggioVideo = "Data matrimonio mancante (Deve essere acquisita)";
                        return false;
                    }
                }
            }

            if (sessoDC != 'F' && sessoDC != 'M')
            {
                messaggioVideo = "Sesso del Dante Causa mancante o errato (F / M)";
                return false;
            }

            if (!Utility.VerificaData(dataMorte, Utility.TipoAppartenenza.CI, out messaggioVideo))
            {
                messaggioVideo = "Data Morte illogica o mancante: " + messaggioVideo;
                return false;
            }

            if (!Utility.DataStrettamenteSuccessivaA(dataMorte.Value, dataNascitaDC.Value))
            {
                messaggioVideo = "Data Morte non posteriore a Data Nascita";
                return false;
            }

            if (Utility.DataSuccessivaA(new DateTime(dataMorte.Value.Year, dataMorte.Value.Month, 01), new DateTime(decorrenzaOriginaria.Value.Year, decorrenzaOriginaria.Value.Month, 01)))
            {
                messaggioVideo = "Data Morte non antecedente a Decorrenza Reversibilità";
                return false;
            }

            return true;
        }

        /// <summary>
        /// PCIPL25
        /// </summary>
        /// <param name="certificato"></param>
        /// <param name="categoria"></param>
        /// <param name="sede"></param>
        /// <param name="decorrenzaPensione"></param>
        /// <param name="maggiorazione780Contributi"></param>
        /// <param name="codNaturaDC"></param>
        /// <param name="dataNascitaDC"></param>
        /// <param name="dataMorteDC"></param>
        /// <param name="categoriaPensione"></param>
        /// <param name="decorrenzaOriginaria"></param>
        /// <param name="codNaturaTitolare"></param>
        /// <param name="messaggioVideo"></param>
        /// <returns></returns>
        public static bool CI_ControlsPensioneDirettaDanteCausa(int? certificato, string categoria, string sede, DateTime? decorrenzaPensione, byte? maggiorazione780Contributi, string codNaturaDC, DateTime? dataNascitaDC, DateTime? dataMorteDC, string categoriaPensione, DateTime? decorrenzaOriginaria, string codNaturaTitolare, byte? causaCarico, out string messaggioVideo)
        {
            messaggioVideo = string.Empty;
            DateTime dataSistema = Utility.DataSistemaCi;

            if (!certificato.HasValue)
            {
                if (!string.IsNullOrEmpty(categoria) || !string.IsNullOrEmpty(sede) || decorrenzaPensione.HasValue || maggiorazione780Contributi.HasValue || (!string.IsNullOrEmpty(codNaturaDC) && !string.IsNullOrEmpty(codNaturaDC.Trim()) && !codNaturaDC.Equals("  V")))
                {
                    messaggioVideo = "Dati Pensione Dante Causa mancanti o incompatibili tra loro";
                    return false;
                }
            }
            else
            {
                if (string.IsNullOrEmpty(categoria) || !decorrenzaPensione.HasValue)
                {
                    messaggioVideo = "Dati Pensione Dante Causa mancanti o incompatibili tra loro";
                    return false;
                }
            }

            if (!string.IsNullOrEmpty(codNaturaDC))
            {
                if (!codNaturaDC.Substring(0, 1).Equals("1") && !codNaturaDC.Substring(0, 1).Equals("2") && !codNaturaDC.Substring(0, 1).Equals("3") && !codNaturaDC.Substring(0, 1).Equals("4") &&
                    !codNaturaDC.Substring(0, 1).Equals("6") && !codNaturaDC.Substring(0, 1).Equals(" "))
                {
                    messaggioVideo = "Natura Pensione errata";
                    return false;
                }

                if (codNaturaDC.Substring(1, 1) != " " && (!Utility.VerificaRegex(codNaturaDC.Substring(1, 1), pattern: "[a-zA-Z]")))
                {
                    messaggioVideo = "Natura Pensione errata";
                    return false;
                }

                if (codNaturaDC.Substring(2, 1) != " " && (!Utility.VerificaRegex(codNaturaDC.Substring(2, 1), pattern: "[a-zA-Z]")))
                {
                    messaggioVideo = "Natura Pensione errata";
                    return false;
                }
            }

            if (decorrenzaPensione.HasValue)
            {
                if (decorrenzaPensione.Value.Year > dataSistema.Year || decorrenzaPensione.Value.Year < 1930)
                {
                    messaggioVideo = "Decorrenza Pensione errata o illogica";
                    return false;
                }

                if (!Utility.DataSuccessivaA(new DateTime(decorrenzaPensione.Value.Year, decorrenzaPensione.Value.Month, 01), new DateTime(dataNascitaDC.Value.Year, dataNascitaDC.Value.Month, 01)))
                {
                    messaggioVideo = "Decorrenza Pensione incompatibile con Data di Nascita";
                    return false;
                }

                if (Utility.DataStrettamenteSuccessivaA(new DateTime(decorrenzaPensione.Value.Year, decorrenzaPensione.Value.Month, 01), new DateTime(dataMorteDC.Value.Year, dataMorteDC.Value.Month, 01)))
                {
                    if (!((new DateTime(dataMorteDC.Value.Year, dataMorteDC.Value.Month, 01)).Equals(new DateTime(decorrenzaPensione.Value.AddMonths(1).Year, decorrenzaPensione.Value.AddMonths(1).Month, 01))))
                    {
                        messaggioVideo = "Decorrenza Pensione incompatibile con Data di Morte";
                        return false;
                    }
                }
            }

            if (maggiorazione780Contributi.GetValueOrDefault() != 0 && maggiorazione780Contributi.GetValueOrDefault() != 3 && maggiorazione780Contributi.GetValueOrDefault() != 4)
            {
                messaggioVideo = "Codice Diritto 781 errato (0 - 3 - 4)";
                return false;
            }

            if (maggiorazione780Contributi.HasValue)
            {
                if (!categoriaPensione.Trim().Equals("SOS") || !certificato.HasValue || !Utility.DataSuccessivaA(decorrenzaOriginaria.Value, new DateTime(1985, 01, 01)) || Utility.DataStrettamenteSuccessivaA(decorrenzaPensione.Value, new DateTime(1989, 12, 31)))
                {
                    messaggioVideo = "Codice Diritto 781 non deve essere acquisito";
                    return false;
                }
            }
            else
            {
                if (categoriaPensione.Equals("SOS") && certificato.HasValue && Utility.DataStrettamenteSuccessivaA(decorrenzaOriginaria.Value, new DateTime(1984, 12, 31)) && decorrenzaPensione.HasValue && !Utility.DataSuccessivaA(decorrenzaPensione.Value, new DateTime(1990, 01, 01)))
                {
                    messaggioVideo = "Codice Diritto 781 mancante";
                    return false;
                }
            }

            if (decorrenzaPensione.HasValue && Utility.DataStrettamenteSuccessivaA(decorrenzaPensione.Value, new DateTime(1984, 07, 31)) && (string.IsNullOrEmpty(codNaturaTitolare) || (!codNaturaTitolare.Substring(0, 1).Equals("3") && !codNaturaTitolare.Substring(0, 1).Equals("4"))))
            {
                if (!string.IsNullOrEmpty(categoria) && (categoria.Equals("IO") || categoria.Equals("IOS") || categoria.Equals("IR") || categoria.Equals("IOART") || categoria.Equals("IOCOM") || categoria.Equals("IRS") ||
                    categoria.Equals("IOARTS") || categoria.Equals("IOCOMS")))
                {
                    messaggioVideo = "Categoria errata (l'Assegno di Invalidità non è reversibile)";
                    return false;
                }
            }

            if (!string.IsNullOrEmpty(categoria) && (categoria.Equals("SO") || categoria.Equals("SOS") || categoria.Equals("SR") || categoria.Equals("SOART") || categoria.Equals("SOCOM") || categoria.Equals("SRS") ||
                    categoria.Equals("SOARTS") || categoria.Equals("SOCOMS"))) // IMPORTANTE: MANCA LA CATEGORIA 101 NELLA TABELLA A DB
            {
                messaggioVideo = "Categoria errata (non può essere SO)";
                return false;
            }

            if (!string.IsNullOrEmpty(categoriaPensione) && categoriaPensione.Equals("SRS"))
            {
                if (decorrenzaPensione.HasValue)
                {
                    if (!Utility.DataSuccessivaA(decorrenzaPensione.Value, new DateTime(1970, 01, 01)) && !Utility.DataSuccessivaA(decorrenzaOriginaria.Value, new DateTime(1991, 01, 01)))
                    {
                        if (Utility.DataStrettamenteSuccessivaA(dataMorteDC.Value, new DateTime(1990, 08, 27)) && !Utility.DataStrettamenteSuccessivaA(dataMorteDC.Value, new DateTime(1990, 11, 30)))
                        {
                            if ((dataMorteDC.Value.Month == 8 && !decorrenzaOriginaria.Equals(new DateTime(1990, 09, 01))) ||
                                (dataMorteDC.Value.Month == 9 && !decorrenzaOriginaria.Equals(new DateTime(1990, 10, 01))) ||
                                (dataMorteDC.Value.Month == 11 && !decorrenzaOriginaria.Equals(new DateTime(1990, 11, 01))) ||
                                (dataMorteDC.Value.Month == 10 && !decorrenzaOriginaria.Equals(new DateTime(1990, 12, 01))))
                            {
                                messaggioVideo = "Decorrenza 'SRS' deve essere mese successivo Data Morte";
                                return false;
                            }
                        }
                        else
                        {
                            if (!string.IsNullOrEmpty(codNaturaTitolare) && (codNaturaTitolare.Substring(0, 1).Equals("2") || codNaturaTitolare.Substring(0, 1).Equals("4") || codNaturaTitolare.Substring(0, 1).Equals("6")))
                            {
                                if (causaCarico.GetValueOrDefault() == 1)
                                {
                                    messaggioVideo = "Decorrenza 'SRS' antecedente a 01/1991";
                                    return false;
                                }
                            }
                        }
                    }
                }
                else
                {
                    if (!Utility.DataSuccessivaA(dataMorteDC.Value, new DateTime(1969, 05, 02)) && !Utility.DataSuccessivaA(decorrenzaOriginaria.Value, new DateTime(1991, 01, 01)))
                    {
                        if (!string.IsNullOrEmpty(codNaturaTitolare) && (codNaturaTitolare.Substring(0, 1).Equals("2") || codNaturaTitolare.Substring(0, 1).Equals("4") || codNaturaTitolare.Substring(0, 1).Equals("6")))
                        {
                            if (causaCarico.GetValueOrDefault() == 1)
                            {
                                messaggioVideo = "Decorrenza 'SRS' antecedente a 01/1991";
                                return false;
                            }
                        }
                    }
                }
            }

            return true;
        }

        public static bool CI_ControlsAltraPensioneWithPensioneDiretta(string categoriaAltraPensione, string codNatura, string categoriaPensioneDiretta, out string messaggioVideo)
        {
            messaggioVideo = string.Empty;

            if (!string.IsNullOrEmpty(codNatura))
            {
                if (!string.IsNullOrEmpty(categoriaAltraPensione) && !codNatura.Substring(0, 1).Equals("2") && !codNatura.Substring(0, 1).Equals("4") &&
                    !codNatura.Substring(0, 1).Equals("6"))
                {
                    messaggioVideo = "Natura Pensione incompatibile con dati Altra Pensione";
                    return false;
                }

                if (string.IsNullOrEmpty(categoriaAltraPensione) && (codNatura.Substring(0, 1).Equals("2") || codNatura.Substring(0, 1).Equals("4") || codNatura.Substring(0, 1).Equals("6")))
                {
                    messaggioVideo = "Natura Pensione incompatibile con dati Altra Pensione";
                    return false;
                }
            }

            if (!string.IsNullOrEmpty(categoriaPensioneDiretta) && !string.IsNullOrEmpty(categoriaAltraPensione))
            {
                if (categoriaAltraPensione.Trim() == categoriaPensioneDiretta.Trim())
                {
                    messaggioVideo = "Categoria Altra Pensione uguale a Categoria Pensione in liquidazione";
                    return false;
                }
            }

            return true;
        }

        /// <summary>
        /// PCIPL25
        /// </summary>
        /// <param name="codiceUCAltraPensione"></param>
        /// <param name="decorrenzaAltraPensione"></param>
        /// <param name="dataNascitaDC"></param>
        /// <param name="dataMorteDC"></param>
        /// <param name="cessazioneAltraPensione"></param>
        /// <param name="categoriaAltraPensione"></param>
        /// <param name="messaggioVideo"></param>
        /// <returns></returns>
        public static bool CI_ControlsAltraPensioneDanteCausa(char? codiceUCAltraPensione, DateTime? decorrenzaAltraPensione, DateTime? dataNascitaDC, DateTime? dataMorteDC, DateTime? cessazioneAltraPensione, string categoriaAltraPensione, out string messaggioVideo)
        {
            messaggioVideo = string.Empty;
            DateTime dataSistema = Utility.DataSistemaCi;

            if (codiceUCAltraPensione.HasValue && codiceUCAltraPensione != 'C' && codiceUCAltraPensione != 'U')
            {
                messaggioVideo = "Categoria Altra Pensione uguale a Categoria Pensione in liquidazione";
                return false;
            }

            if (decorrenzaAltraPensione.HasValue)
            {
                if (decorrenzaAltraPensione.Value.Year > dataSistema.Year || decorrenzaAltraPensione.Value.Year < 1940)
                {
                    messaggioVideo = "Decorrenza errata";
                    return false;
                }

                if (dataNascitaDC.HasValue && dataMorteDC.HasValue)
                {
                    if (!Utility.DataSuccessivaA(new DateTime(decorrenzaAltraPensione.Value.Year, decorrenzaAltraPensione.Value.Month, 01), new DateTime(dataNascitaDC.Value.Year, dataNascitaDC.Value.Month, 01)) ||
                        Utility.DataStrettamenteSuccessivaA(new DateTime(decorrenzaAltraPensione.Value.Year, decorrenzaAltraPensione.Value.Month, 01), new DateTime(dataMorteDC.Value.Year, dataMorteDC.Value.Month, 01)))
                    {
                        messaggioVideo = "Decorrenza incompatibile con Data di Nascita/Data di Morte";
                        return false;
                    }
                }
            }

            if (cessazioneAltraPensione.HasValue && string.IsNullOrEmpty(categoriaAltraPensione))
            {
                messaggioVideo = "Cessazione incompatibile con Categoria";
                return false;
            }

            if (cessazioneAltraPensione.HasValue && decorrenzaAltraPensione.HasValue)
            {
                if (cessazioneAltraPensione.Value.Year > dataSistema.Year || cessazioneAltraPensione.Value.Year < decorrenzaAltraPensione.Value.Year)
                {
                    messaggioVideo = "Cessazione errata";
                    return false;
                }

                if (!Utility.DataSuccessivaA(cessazioneAltraPensione.Value, decorrenzaAltraPensione.Value))
                {
                    messaggioVideo = "Cessazione incompatibile con Decorrenza";
                    return false;
                }

                if (dataMorteDC.HasValue && Utility.DataStrettamenteSuccessivaA(new DateTime(cessazioneAltraPensione.Value.Year, cessazioneAltraPensione.Value.Month, 01), new DateTime(dataMorteDC.Value.Year, dataMorteDC.Value.Month, 01)))
                {
                    messaggioVideo = "Cessazione incompatibile con Data Morte";
                    return false;
                }
            }

            return true;
        }

        /// <summary>
        /// PCIPL25 - Verifica se il secondo codice natura è 'O' e la categoria nella tab pensione diretta non è valorizzata (sperimentale donna)
        /// </summary>
        /// <param name="codNatura"></param>
        /// <param name="categoria"></param>
        /// <returns></returns>
        public static bool CI_VerificaCodNaturaWithCategoriaDC(string codNatura, string categoria)
        {
            if (!string.IsNullOrEmpty(codNatura) && codNatura.Substring(1, 1).Equals("O") && string.IsNullOrEmpty(categoria))
                return false;

            return true;
        }

        /// <summary>
        /// PCIPL25 - Verifica compatibilità tra i codici natura del dante causa col titolare
        /// </summary>
        /// <param name="codNaturaDC"></param>
        /// <param name="codNaturaTitolare"></param>
        /// <returns></returns>
        public static bool CI_VerificaCodNaturaTitolareWithDC(string codNaturaDC, string codNaturaTitolare)
        {
            if (!string.IsNullOrEmpty(codNaturaDC))
            {
                if ((codNaturaDC.Substring(0, 1).Equals("3") || codNaturaDC.Substring(0, 1).Equals("4")) && (string.IsNullOrEmpty(codNaturaTitolare) || !codNaturaTitolare.Substring(0, 1).Equals("3") && !codNaturaTitolare.Substring(0, 1).Equals("4")))
                    return false;

                if ((codNaturaDC.Substring(0, 1).Equals("1") || codNaturaDC.Substring(0, 1).Equals("2")) && (string.IsNullOrEmpty(codNaturaTitolare) || !codNaturaTitolare.Substring(0, 1).Equals("1") && !codNaturaTitolare.Substring(0, 1).Equals("2")))
                    return false;
            }

            if (!(!string.IsNullOrEmpty(codNaturaTitolare) && (codNaturaTitolare.Substring(0, 1).Equals("1") || codNaturaTitolare.Substring(0, 1).Equals("2")) && (codNaturaTitolare.Substring(1, 1).Equals("X") || codNaturaTitolare.Substring(1, 1).Equals("Y"))))
            {
                if (!string.IsNullOrEmpty(codNaturaTitolare) && (codNaturaTitolare.Substring(0, 1).Equals("1") || codNaturaTitolare.Substring(0, 1).Equals("2")) && (!string.IsNullOrEmpty(codNaturaDC) && (!codNaturaDC.Substring(0, 1).Equals("1") && !codNaturaDC.Substring(0, 1).Equals("2"))))
                    return false;
            }

            return true;
        }

        public static bool CI_VerificaDecorrenzaMaggiorazioneArt6WithDecorrenzaPensioneDirettaAndDecorrenzaOriginaria(DateTime? decorrenzaMaggiorazioneArt6, DateTime? decorrenzaPensione, DateTime? decorrenzaOriginaria)
        {
            DateTime dataCompare;
            if (decorrenzaMaggiorazioneArt6.HasValue)
            {
                if (decorrenzaPensione.HasValue)
                    dataCompare = decorrenzaPensione.Value;
                else
                    dataCompare = decorrenzaOriginaria.Value;

                if (!Utility.DataSuccessivaA(decorrenzaMaggiorazioneArt6.Value, dataCompare) || !Utility.DataSuccessivaA(decorrenzaMaggiorazioneArt6.Value, new DateTime(1985, 01, 01)))
                    return false;
            }

            return true;
        }

        public static bool CI_VerificaDecorrenzaMaggiorazioneArt6WithDecorrenzaPensioneDirettaAndDataMorteAndDecorrenzaOriginaria(DateTime? decorrenzaMaggiorazioneArt6, DateTime? decorrenzaPensione, DateTime? dataMorte, DateTime? decorrenzaOriginaria)
        {
            if (decorrenzaMaggiorazioneArt6.HasValue && decorrenzaPensione.HasValue)
            {
                if (dataMorte.HasValue)
                    if ((Utility.DataStrettamenteSuccessivaA(decorrenzaMaggiorazioneArt6.Value, new DateTime(dataMorte.Value.Year, dataMorte.Value.Month, 01)) && !Utility.DataSuccessivaA(decorrenzaMaggiorazioneArt6.Value, decorrenzaOriginaria.Value)) || !Utility.DataSuccessivaA(decorrenzaMaggiorazioneArt6.Value, decorrenzaPensione.Value))
                        return false;
            }

            return true;
        }

        public static bool CI_VerificaDecorrenzaArt2DPCMWithDanteCausa(DateTime? decorrenzaArt2Dpcm, DateTime? decorrenzaPensioneDiretta, DateTime? decorrenzaOriginaria)
        {
            DateTime dataCompare;
            if (decorrenzaArt2Dpcm.HasValue)
            {
                if (decorrenzaPensioneDiretta.HasValue)
                    dataCompare = decorrenzaPensioneDiretta.Value;
                else
                    dataCompare = decorrenzaOriginaria.Value;

                if (!Utility.DataSuccessivaA(dataCompare, new DateTime(1971, 01, 01)) || Utility.DataStrettamenteSuccessivaA(dataCompare, new DateTime(1984, 12, 31)))
                    return false;
            }

            return true;
        }

        /// <summary>
        /// Verifica la compatibilità tra la categoria diretta e il codice natura del titolare
        /// </summary>
        /// <param name="codNaturaTitolare"></param>
        /// <param name="categoria"></param>
        /// <returns></returns>
        public static bool CI_VerificaCompatibilitaCategoriaDirettaWithCodNatura(string codNaturaTitolare, string categoria, DateTime? decorrenzaDiretta)
        {
            if (!string.IsNullOrEmpty(codNaturaTitolare) && (codNaturaTitolare.Substring(0, 1).Equals("1") || codNaturaTitolare.Substring(0, 1).Equals("2")) &&
                (!string.IsNullOrEmpty(categoria) && (!categoria.Trim().Equals("VO") && !categoria.Trim().Equals("VOS") && !categoria.Trim().Equals("VR") && !categoria.Trim().Equals("VOART") &&
                !categoria.Trim().Equals("VRS") && !categoria.Trim().Equals("VOCOM") && !categoria.Trim().Equals("VOCOMS") && !categoria.Trim().Equals("VOARTS")))) // IMPORTANTE: MANCA LA CATEGORIA 100 NELLA TABELLA A DB
                return false;

            if (!string.IsNullOrEmpty(codNaturaTitolare) && (codNaturaTitolare.Substring(0, 1).Equals("3") || codNaturaTitolare.Substring(0, 1).Equals("4")) && !string.IsNullOrEmpty(categoria))
            {
                if (!((categoria.Trim().Equals("IO") || categoria.Trim().Equals("IOS") || categoria.Trim().Equals("IR") || categoria.Trim().Equals("IRS") || categoria.Trim().Equals("IOART") || categoria.Trim().Equals("IOARTS") ||
                    categoria.Trim().Equals("IOCOM") || categoria.Trim().Equals("IOCOMS")) && decorrenzaDiretta.HasValue && Utility.DataStrettamenteSuccessivaA(decorrenzaDiretta.Value, new DateTime(1984, 07, 31))))
                    return false;
            }

            return true;
        }

        public static bool CI_ControlsCodiceVirtualeWithCertificatoDiretta(char? codiceVirtuale, int? certificato, byte? convenzione, byte? causaCarico, out string messaggioVideo)
        {
            messaggioVideo = string.Empty;

            if (codiceVirtuale.GetValueOrDefault() == '5' && !certificato.HasValue)
            {
                messaggioVideo = "Codice Virtuale '5'-'6' solo per SO da pensionato";
                return false;
            }

            if (convenzione.GetValueOrDefault() == 17)
            {
                if ((!codiceVirtuale.HasValue || (codiceVirtuale.Value != '5' && codiceVirtuale.Value != '6')) && certificato.HasValue)
                {
                    if (!((causaCarico.GetValueOrDefault() == 9 || causaCarico.GetValueOrDefault() == 2) && !codiceVirtuale.HasValue))
                    {
                        messaggioVideo = "Convenzione 17: Codice Virtuale non uguale a '5' o '6'";
                        return false;
                    }
                }

                if (codiceVirtuale.HasValue && !certificato.HasValue)
                {
                    messaggioVideo = "Convenzione 17: Codice Virtuale non uguale a spazio";
                    return false;
                }
            }

            return true;
        }

        public static bool CI_VerificaSettimaneIncremento1PercentoWithDanteCausa(int? nSettimaneIncremento1Percento, string categoria, DateTime? decorrenzaDiretta)
        {
            if (nSettimaneIncremento1Percento.HasValue)
            {
                if ((!string.IsNullOrEmpty(categoria) && (!categoria.Trim().Equals("VO") && !categoria.Trim().Equals("VOS"))) ||
                    (decorrenzaDiretta.HasValue && !Utility.DataSuccessivaA(decorrenzaDiretta.Value, new DateTime(1995, 01, 01))))
                    return false;
            }

            return true;
        }

        public static bool CI_VerificaSettimaneIncremento05PercentoWithDecorrenzaDiretta(int? nSettimaneIncremento05Percento, string categoria, DateTime? decorrenzaDiretta)
        {
            if (nSettimaneIncremento05Percento.HasValue)
            {
                if ((decorrenzaDiretta.HasValue && !Utility.DataSuccessivaA(decorrenzaDiretta.Value, new DateTime(1995, 01, 01))) || (!string.IsNullOrEmpty(categoria) &&
                    (!categoria.Equals("VO") && !categoria.Equals("VOS") && !categoria.Equals("VR") && !categoria.Equals("VOART") && !categoria.Equals("VOCOM") &&
                    !categoria.Equals("VRS") && !categoria.Equals("VOARTS") && !categoria.Equals("SOCOMS"))))
                    return false;
            }

            return true;
        }

        public static bool CI_VerificaSettimaneIncremento05PercentoWithSessoDanteCausa(int? nSettimaneIncremento05Percento, char? sessoDanteCausa)
        {
            if (nSettimaneIncremento05Percento.HasValue)
            {
                if (sessoDanteCausa.GetValueOrDefault() == 'M')
                    return false;
            }

            return true;
        }

        /// <summary>
        /// Se TP1DIFN è maggiore di zero effettuare i seguenti controlli : Se TP1CATD non è uguale a 4 e IW1DIRET a successiva al 197607 allora False
        /// </summary>
        /// <param name="anniDifferimento"></param>
        /// <param name="categoriaDiretta"></param>
        /// <param name="decorrenzaDiretta"></param>
        /// <returns></returns>
        public static bool CI_VerificaAnniDifferimentoWithDanteCausa(int? anniDifferimento, string categoriaDiretta, DateTime? decorrenzaDiretta)
        {
            if (anniDifferimento.HasValue)
                if (!string.IsNullOrEmpty(categoriaDiretta) && !categoriaDiretta.Equals("VOS") && decorrenzaDiretta.HasValue && Utility.DataStrettamenteSuccessivaA(decorrenzaDiretta.Value, new DateTime(1976, 07, 31)))
                    return false;

            return true;
        }

        /// <summary>
        /// 59.	Se IW1DOMOPZ è maggiore di zero effettuare i seguenti controlli :  
        /// 59.1.	Se W1DOMOPZ è maggiore del 19940100 continua con il controllo successivo; diversamente effettuare i seguenti controlli :  
        /// 59.1.1.	Se IW1DOMOPZ è posteriore al 19680500 e  antecedente al 19760132 effettuare i seguenti controlli :
        /// 59.1.1.1.	Se IW1DIRET è maggiore di zero valorizzare W-APP-DEC con IW1DIRET; diversamente  valorizzarlo con IW1DEORIG;
        /// 59.1.1.2.	Se W-APP-DEC è posteriore al 196805 impostare          MESSAGGIO-ERRORE con “DATA DOM.OPZIONE (CNV01) INCOMPA TIBILE CON DECORENZA", TIPO-ERRORE con “50”,    
        /// RIG-ERR1 con 17,  COL-ERR1 con 53,  FLAG-ERR a 1, uscire da CONTROLLI-1 (saltare al Punto 78);
        /// 59.1.1.3.	Se IW1DOMOPZ è antecedente al 19720700 effettuare i seguenti controlli :
        /// 59.1.1.3.1.	Se TP1CATD è uguale a 2  o 5   impostare MESSAGGIO-ERRORE con "DATA DOM.OPZIONE (CNV01) INCOMPATIBILE CON CATEG/DEC DIRETTA", TIPO-ERRORE con “51”,  RIG-ERR1 
        /// con 17, COL-ERR1 con 42,  FLAG-ERR a 1, uscire da CONTROLLI-1 (saltare al Punto 78);
        /// </summary>
        /// <param name="dataDomandaOpzione"></param>
        /// <param name="decorrenza"></param>
        /// <param name="categoriaDC"></param>
        /// <param name="messaggioVideo"></param>
        /// <returns></returns>
        public static bool CI_VerificaDataDomandaOpzioneWithDanteCausa(DateTime? dataDomandaOpzione, DateTime? decorrenza, string categoriaDC, out string messaggioVideo)
        {
            messaggioVideo = string.Empty;

            if (dataDomandaOpzione.HasValue)
            {
                if (!Utility.DataSuccessivaA(dataDomandaOpzione.Value, new DateTime(1994, 01, 01)))
                {
                    if (Utility.DataSuccessivaA(dataDomandaOpzione.Value, new DateTime(1968, 05, 01)) && !Utility.DataStrettamenteSuccessivaA(dataDomandaOpzione.Value, new DateTime(1976, 01, 31)))
                    {
                        if (Utility.DataStrettamenteSuccessivaA(decorrenza.Value, new DateTime(1968, 05, 31)))
                        {
                            messaggioVideo = "Data Domanda Opzione incompatibile con Decorrenza";
                            return false;
                        }

                        if (!Utility.DataSuccessivaA(dataDomandaOpzione.Value, new DateTime(1972, 07, 01)))
                        {
                            if (!string.IsNullOrEmpty(categoriaDC) && (categoriaDC.Trim().Equals("IO") || categoriaDC.Trim().Equals("IOS")))
                            {
                                messaggioVideo = "Data Domanda Opzione incompatibile con Categ/Dec Diretta";
                                return false;
                            }
                        }
                    }
                }
            }

            return true;
        }

        /// <summary>
        /// 53.	Se IREQPARD è uguale 6 e IW1CATPEN è uguale a 6 effettuare i seguenti controlli :
        /// 53.1.	Se TP1CERTD è maggiore di zero effettuare i seguenti controlli :
        /// 53.1.1.	Se TP1CATD non è uguale a 4, 5 e 6 impostare MESSAGGIO-ERRORE con "CATEGORIA INCOMPATIBILE CON REQ.PART.DIRITTO  6  (CNV01)", TIPO-ERRORE con “62”,  RIG-ERR1 con 
        /// 17, COL-ERR1 con 42,  FLAG-ERR a 1, uscire da CONTROLLI-1 (saltare al Punto 78);
        /// 53.2.	Diversamente da quanto esaminato nel punto precedente (53.1) effettuare i seguenti controlli :
        /// 53.2.1.	Se IW1DEORIG è posteriore al 198312 impostare MESSAGGIO-ERRORE con "REQUISITO PART.DIRITTO (CNV01) INCOMPATIBILE CON PENSIONE", TIPO-ERRORE con “63”,  RIG-ERR1 
        /// con 17, COL-ERR1 con 29,  FLAG-ERR a 1, uscire da CONTROLLI-1 (saltare al Punto 78);
        /// </summary>
        /// <param name="codiceRequisitiParticolari"></param>
        /// <param name="categoria"></param>
        /// <param name="certificatoDanteCausa"></param>
        /// <param name="siglaCategoriaDanteCausa"></param>
        /// <param name="decorrenzaOriginaria"></param>
        /// <param name="messaggioVideo"></param>
        /// <returns></returns>
        public static bool CI_VerificaRequisitoParticolareDirittoWithDanteCausa(byte? codiceRequisitiParticolari, int? categoria, int? certificatoDanteCausa, string siglaCategoriaDanteCausa, DateTime? decorrenzaOriginaria, out string messaggioVideo)
        {
            messaggioVideo = string.Empty;

            if (codiceRequisitiParticolari.GetValueOrDefault() == 6 && categoria.GetValueOrDefault() == 6)
            {
                if (certificatoDanteCausa.GetValueOrDefault() > 0)
                {
                    if (!(new List<string> { "VOS", "IOS", "SOS" }).Contains(siglaCategoriaDanteCausa))
                    {
                        messaggioVideo = "Categoria incompatibile con Requisito Particolare Diritto 6";
                        return false;
                    }
                }
                else
                {
                    if (Utility.DataStrettamenteSuccessivaA(decorrenzaOriginaria.Value, new DateTime(1983, 12, 31)))
                    {
                        messaggioVideo = "Requisito Particolare Diritto incompatibile con Pensione";
                        return false;
                    }
                }
            }

            return true;
        }
        #endregion PCIPL25

        #region PCIPL29

        /// <summary>
        /// PCIPL29 - Se il campo (IW1CM345(COD. ART.3,4,5/140/DPCM) > 0 AND NOT = 3 AND NOT = 4 AND NOT = 5  AND NOT = 8)  allora segnala errore 
        /// </summary>
        /// <param name="codiciVari"></param>
        /// <param name="messaggioVideo"></param>
        /// <returns></returns>
        public static bool CI_VerificaCodiciVari(byte? codiciVari, out string messaggioVideo)
        {
            messaggioVideo = string.Empty;

            if (codiciVari.HasValue && codiciVari.Value != 3 && codiciVari.Value != 4 && codiciVari.Value != 5 && codiciVari.Value != 8)
            {
                messaggioVideo = "CODICE ART.3/4/5 LEGGE 140/85 O DPCM ERRATI";
                return false;
            }


            return true;
        }

        /// <summary>
        /// Se i campi IW1780CD = 3 AND IW1DIRET < 198401 allora controlla il campo IW1CM345 NOT = 4 segnala errore  CODICE ART.4 LEGGE 140/85 MANCANTE
        /// altrimenti se il campo IW1CM345 = 4 segnala errore CODICE ART.4 LEGGE 140/85 ERRATO
        /// </summary>
        /// <param name="decorrenza"></param>
        /// <param name="maggiorazione780Contributi"></param>
        /// <param name="codiciVari"></param>
        /// <param name="messaggioVideo"></param>
        /// <returns></returns>
        public static bool CI_VerificaCodiceArt4Legge140(DateTime? decorrenzaPensioneDC, byte? maggiorazione780Contributi, byte? codiciVari, out string messaggioVideo)
        {
            messaggioVideo = string.Empty;
            DateTime dataCompare = new DateTime(1984, 01, 01);

            if (maggiorazione780Contributi.HasValue && decorrenzaPensioneDC.HasValue && maggiorazione780Contributi.Value == 3 && !Utility.DataSuccessivaA(decorrenzaPensioneDC.Value, dataCompare))
            {
                if (!codiciVari.HasValue || codiciVari.Value != 4)
                {
                    messaggioVideo = "CODICE ART.4 LEGGE 140/85 MANCANTE";
                    return false;
                }
            }
            else
            {
                if (codiciVari.HasValue && codiciVari.Value == 4)
                {
                    messaggioVideo = "CODICE ART.4 LEGGE 140/85 ERRATO";
                    return false;
                }
            }

            return true;
        }

        /// <summary>
        /// Se i campi (IW1780CD = 3 AND IW1DIRET > 198312) allora controlla il campo IW1CM345 NOT = 8 allora segnala errore "CODICE D.P.C.M. MANCANTE" 
        /// altrimenti  se IW1CM345  = 8 allora segnala errore "CODICE D.P.C.M. ERRATO".
        /// </summary>
        /// <param name="decorrenza"></param>
        /// <param name="maggiorazione780Contributi"></param>
        /// <param name="codiciVari"></param>
        /// <param name="messaggioVideo"></param>
        /// <returns></returns>
        public static bool CI_VerificaCodiceDCPM(DateTime? decorrenzaPensioneDC, byte? maggiorazione780Contributi, byte? codiciVari, out string messaggioVideo)
        {
            messaggioVideo = string.Empty;
            DateTime dataCompare = new DateTime(1983, 12, 01);

            if (maggiorazione780Contributi.HasValue && decorrenzaPensioneDC.HasValue && maggiorazione780Contributi.Value == 3 && Utility.DataStrettamenteSuccessivaA(decorrenzaPensioneDC.Value, dataCompare))
            {
                if (!codiciVari.HasValue || codiciVari.Value != 8)
                {
                    messaggioVideo = "CODICE D.P.C.M. MANCANTE";
                    return false;
                }
            }
            else
            {
                if (codiciVari.HasValue && codiciVari.Value == 8)
                {
                    messaggioVideo = "CODICE D.P.C.M. ERRATO";
                    return false;
                }
            }

            return true;
        }

        /// <summary>
        /// Se i campi (IW1780CD = 3 AND IW1DEORIG > 198912) allora controlla i campi (IW1CM345 NOT = 8 AND NOT = 4) allora segnala errore "CODICE ART41.140/D.P.C.M INCOMPATIBILI  CON COD.780 DEL PANN.CNV01"
        /// </summary>
        /// <param name="decorrenzaPensione"></param>
        /// <param name="maggiorazione780Contributi"></param>
        /// <param name="codiciVari"></param>
        /// <param name="messaggioVideo"></param>
        /// <returns></returns>
        public static bool CI_VerificaCodiceArt41(DateTime? decorrenzaPensione, byte? maggiorazione780Contributi, byte? codiciVari, out string messaggioVideo)
        {
            messaggioVideo = string.Empty;
            DateTime dataCompare = new DateTime(1989, 12, 01);

            if (maggiorazione780Contributi.HasValue && decorrenzaPensione.HasValue && maggiorazione780Contributi.Value == 3 && Utility.DataStrettamenteSuccessivaA(decorrenzaPensione.Value, dataCompare))
            {
                if (codiciVari.HasValue && codiciVari.Value != 8 && codiciVari.Value != 4)
                {
                    messaggioVideo = "CODICE ART41.140/D.P.C.M INCOMPATIBILI CON COD.780";
                    return false;
                }
            }

            return true;
        }

        /// <summary>
        /// Se i campi (IW1CATPEN (CAT.PENS.IN CODICE P18) NOT = 6 AND IW1CM345 NOT = 0) segnala errore "CODICE LEGGE 140/85 NON AMMEESSO  PER CATEGORIA DIVERSA DA SOS" 
        /// </summary>
        /// <param name="codiceCategoria"></param>
        /// <param name="codiciVari"></param>
        /// <param name="messaggioVideo"></param>
        /// <returns></returns>
        public static bool CI_VerificaLegge140WithCategoria(string codiceCategoria, byte? codiciVari, out string messaggioVideo)
        {
            messaggioVideo = string.Empty;
            string categoriaNumerica = string.Empty;
            GestioneDecodifica.GetCodCategoriaBySiglaCategoria(codiceCategoria, out categoriaNumerica);

            if (!string.IsNullOrEmpty(categoriaNumerica) && int.Parse(categoriaNumerica) != 6 && codiciVari.HasValue)
            {
                messaggioVideo = "CODICE LEGGE 140/85 NON AMMEESSO PER CATEGORIA DIVERSA DA SOS";
                return false;
            }

            return true;
        }

        /// <summary>
        /// Se  i campi (IW1TM345(TOTALE ART. 3,4,5 E DPCM) = 0 AND IW1CM345(COD. ART.3,4,5/140/DPCM) NOT = 0) allora controlla I campi (IW1DEORIG > 198412 OR IW1CM345 NOT = 3)  segnala errore "TOTALE IMPORTO ART.3/4/5 LEGGE 140/85 O D.P.C.M. ASSENTE"
        /// </summary>
        /// <param name="decorrenzaPensione"></param>
        /// <param name="importoArt345"></param>
        /// <param name="codiciVari"></param>
        /// <param name="messaggioVideo"></param>
        /// <returns></returns>
        public static bool CI_VerificaImportoArt345(DateTime? decorrenzaPensione, decimal? importoArt345, byte? codiciVari, out string messaggioVideo)
        {
            messaggioVideo = string.Empty;
            DateTime dataCompare = new DateTime(1984, 12, 01);

            if (importoArt345.HasValue && codiciVari.HasValue && importoArt345.Value == 0)
            {
                if ((decorrenzaPensione.HasValue && Utility.DataStrettamenteSuccessivaA(decorrenzaPensione.Value, dataCompare)) || codiciVari.Value != 3)
                {
                    messaggioVideo = "TOTALE IMPORTO ART.3/4/5 LEGGE 140/85 O D.P.C.M. ASSENTE";
                    return false;
                }
            }

            return true;
        }

        /// <summary>
        /// Se i campi (IW1TM345 > 0 AND IW1CM345 = 0) allora segnala errore "TOTALE IMPORTO ART.3/4/5 LEGGE 140/85 INCOMPATIBILI CON CODICE" 
        /// </summary>
        /// <param name="importoArt345"></param>
        /// <param name="codiciVari"></param>
        /// <param name="messaggioVideo"></param>
        /// <returns></returns>
        public static bool CI_VerificaImportoArt345WithCodiciVari(decimal? importoArt345, byte? codiciVari, out string messaggioVideo)
        {
            messaggioVideo = string.Empty;

            if (importoArt345.HasValue && importoArt345.Value > 0 && !codiciVari.HasValue)
            {
                messaggioVideo = "TOTALE IMPORTO ART.3/4/5 LEGGE 140/85 INCOMPATIBILI CON CODICE";
                return false;
            }

            return true;
        }

        /// <summary>
        /// 43.	Se il campo (IW1TM345 < 20,6583 AND > 41,3166) allora segnala errore "IMPORTO ART.4 NON COMPRESO TRA 20,6583 E 41,3166 EURO"
        /// </summary>
        /// <param name="importoArt345"></param>
        /// <param name="messaggioVideo"></param>
        /// <returns></returns>
        public static bool CI_VerificaRangeImportoArt345(decimal? importoArt345, out string messaggioVideo)
        {
            messaggioVideo = string.Empty;

            if (importoArt345.HasValue && (importoArt345.Value < (decimal)20.6583 || importoArt345.Value > (decimal)41.3166))
            {
                messaggioVideo = "IMPORTO ART.4 NON COMPRESO TRA 20,6583 E 41,3166 EURO";
                return false;
            }

            return true;
        }

        /// <summary>
        /// Se i campi (IW1CM345 NOT = 3 OR IW1DEORIG > 198412) allora controlla I campi (IW1CM345 NOT = 0 AND IW1DEORIG < 198501) allora segnala errore "CODICE NON AMMESSO PER DECORRENZA ANTE 1985"
        /// </summary>
        /// <param name="decorrenzaPensione"></param>
        /// <param name="codiciVari"></param>
        /// <param name="messaggioVideo"></param>
        /// <returns></returns>
        public static bool CI_VerificaCodiciVariWithDecorrenzaPensione(DateTime? decorrenzaPensione, byte? codiciVari, out string messaggioVideo)
        {
            messaggioVideo = string.Empty;
            DateTime dataCompare = new DateTime(1985, 01, 01);
            if ((!codiciVari.HasValue || codiciVari.Value != 3) || (decorrenzaPensione.HasValue && Utility.DataSuccessivaA(decorrenzaPensione.Value, dataCompare)))
            {
                if (codiciVari.HasValue && decorrenzaPensione.HasValue && !Utility.DataSuccessivaA(decorrenzaPensione.Value, dataCompare))
                {
                    messaggioVideo = "CODICE NON AMMESSO PER DECORRENZA ANTE 1985";
                    return false;
                }
            }


            return true;
        }

        /// <summary>
        /// Se i campi (IW1DART5(ECCED.ART.5 140 AL 8801) > 0 AND IW1CM345 NOT = 5)  allora segnala errore "IMPORTO ECCEDENZA INCOMPATIBILE  CON ARTICOLO LEGGE 140" 
        /// </summary>
        /// <param name="codiciVari"></param>
