        /// <returns></returns>
        /// richiamato solo in invio al calcolo in quanto eccedenzaArt5 è un dato non a video e di solo controllo
        public static bool CI_VerificaDecorrenzaPensioneWithEccedenzaArt5(DateTime? decorrenzaPensione, decimal? eccedenzaArt5, out string messaggioVideo)
        {
            messaggioVideo = string.Empty;
            DateTime dataCompare = new DateTime(1988, 01, 01);

            if (decorrenzaPensione.HasValue && eccedenzaArt5.HasValue && eccedenzaArt5.Value > 0 && Utility.DataStrettamenteSuccessivaA(decorrenzaPensione.Value, dataCompare))
            {
                messaggioVideo = "IMPORTO ECCEDENZA INCOMPATIBILE CON DECORR SO POST 01.88";
                return false;
            }

            return true;
        }

        public static bool CI_VerificaDecorrenzaArt6WithDecorrenza(int? certificato, DateTime? decorrenzaArt6, DateTime? decorrenza)
        {
            if (certificato.HasValue && certificato.Value == 0 && decorrenzaArt6.HasValue && decorrenza.HasValue && !Utility.DataSuccessivaA(decorrenzaArt6.Value, decorrenza.Value))
                return false;

            return true;
        }

        /// <summary>
        /// Il controllo non è richiamato perchè ha bisogno di una maggiore analisi.
        /// 59.	Se il campo (TP1CATD NOT = 1 AND  2 AND 4 AND  5) allora segnala errore "CODICE LEGGE 59/91 AMMESSO SOLO PER  CATEGORIE VO, VOS, IO, IOS"
        /// </summary>
        /// <param name="siglaCategoria"></param>
        /// <param name="messaggioVideo"></param>
        /// <returns></returns>
        public static bool CI_VerificaSiglaCategoria(string siglaCategoria, out string messaggioVideo)
        {
            messaggioVideo = string.Empty;

            if (!string.IsNullOrEmpty(siglaCategoria) && !string.IsNullOrEmpty(siglaCategoria.Trim()) && !siglaCategoria.Trim().Equals("VO") && !siglaCategoria.Trim().Equals("IO") && !siglaCategoria.Trim().Equals("VOS") && !siglaCategoria.Trim().Equals("IOS"))
            {
                messaggioVideo = "Codice Legge 59/91 ammesso solo per categorie VO, VOS, IO, IOS";
                return false;
            }

            return true;
        }

        /// <summary>
        /// Il controllo non è richiamato perchè ha bisogno di una maggiore analisi.
