        /// </summary>
        /// <param name="decorrenzaDiretta"></param>
        /// <param name="messaggioVideo"></param>
        /// <returns></returns>
        public static bool CI_VerificaDecorrenzaDiretta(DateTime? decorrenzaDiretta, out string messaggioVideo)
        {
            messaggioVideo = string.Empty;
            DateTime dataCompare = new DateTime(1988, 12, 01);

            if (decorrenzaDiretta.HasValue && Utility.DataStrettamenteSuccessivaA(decorrenzaDiretta.Value, dataCompare))
            {
                messaggioVideo = "CODICE LEGGE 59/91 INCOMPATIIBILE CON DEC. DANTE CAUSA POST 12/88";
                return false;
            }

            return true;
        }

        /// <summary>
        /// Se i campi (IW1TM59B(AUMENTO TOTALE LEGGE 59/91 ART.1 COMMA 9/BIS) > 0 AND IW1DEORIG < 199201) segnala errore   "IMPORTO ERRATO: INCOMPATIBILE CON  SO ANTERIORE 01/1992"
        /// </summary>
        /// <param name="decorrenzaPensione"></param>
        /// <param name="aumentoMensileLegge5991Comma9"></param>
        /// <param name="messaggioVideo"></param>
        /// <returns></returns>
        public static bool CI_VerificaLegge5991WithDecorrenzaPensione(DateTime? decorrenzaPensione, decimal? aumentoMensileLegge5991Comma9, out string messaggioVideo)
        {
            messaggioVideo = string.Empty;
            DateTime dataCompare = new DateTime(1992, 01, 01);
            if (aumentoMensileLegge5991Comma9.HasValue && aumentoMensileLegge5991Comma9.Value > 0 && decorrenzaPensione.HasValue && !Utility.DataSuccessivaA(decorrenzaPensione.Value, dataCompare))
            {
                messaggioVideo = "IMPORTO ERRATO: INCOMPATIBILE CON  SO ANTERIORE 01/1992";
                return false;
            }

            return true;
        }

        /// <summary>
        /// Se i campi ((IW1TM59B > 0) AND (IW1DEORIG > 199112 AND < 199407) AND (IW1DIRET > 198206)) segnala errore "IMP. ERRATO: SO TRA 01/92 E 06/94 E PENS. DANTE CAUSA POST. 06/82"
        /// </summary>
        /// <param name="decorrenzaPensione"></param>
        /// <param name="decorrenzaDiretta"></param>
        /// <param name="aumentoMensileLegge5991Comma9"></param>
        /// <param name="messaggioVideo"></param>
        /// <returns></returns>
        public static bool CI_VerificaLegge5991WithDecorrenze(DateTime? decorrenzaPensione, DateTime? decorrenzaDiretta, decimal? aumentoMensileLegge5991Comma9, out string messaggioVideo)
        {
            messaggioVideo = string.Empty;

            DateTime dataCompare1 = new DateTime(1991, 12, 01);
            DateTime dataCompare2 = new DateTime(1994, 07, 01);
            DateTime dataCompare3 = new DateTime(1982, 06, 01);

            if (aumentoMensileLegge5991Comma9.HasValue && aumentoMensileLegge5991Comma9.Value > 0)
            {
                if (decorrenzaPensione.HasValue && Utility.DataStrettamenteSuccessivaA(decorrenzaPensione.Value, dataCompare1) && !Utility.DataSuccessivaA(decorrenzaPensione.Value, dataCompare2))
                {
                    if (decorrenzaDiretta.HasValue && Utility.DataStrettamenteSuccessivaA(decorrenzaDiretta.Value, dataCompare3))
                    {
                        messaggioVideo = "IMP. ERRATO: SO TRA 01/92 E 06/94 E PENS. DANTE CAUSA POST. 06/82";
                        return false;
                    }
                }
            }

            return true;
        }

        /// <summary>
        /// Se i campi ((IW1CATPEN NOT = 6) OR (IABTIPEN NOT = 2  AND IW1DEOP (DECORRENZA OPZIONE) = 0))   allora controlla che il campo IW1AS72A (AUMENTO PER SENTENZA N. 72/90)  > 0 segnala errore "AUMENTO SENTENZA 72/90 INCOMPATIBILE CON CATEGORIA / TIPO PENS." 
        /// </summary>
