        /// <returns></returns>
        public static bool CI_VerificaSentenza7290Art2WithCategoria(string siglaCategoria, DateTime? decorrenzaOpzione, decimal? aumento7290, decimal? aumentoMensileLegge161289Art2, out string messaggioVideo)
        {
            messaggioVideo = string.Empty;

            if (!string.IsNullOrEmpty(siglaCategoria.Trim()) && !siglaCategoria.Trim().Equals("SOS"))
            {
                if (aumento7290.HasValue && aumento7290.Value > 0)
                {
                    messaggioVideo = "AUMENTO SENTENZA 72/90 INCOMPATIBILE CON CATEGORIA / TIPO PENS.";
                    return false;
                }

                //dato IW1AS72B mancante. controllo non implementabile
                //if (IW1AS72B.HasValue && IW1AS72B.Value > 0)
                //{
                //    messaggioVideo = "AUMENTO SENTENZA 72/90 INCOMPATIBILE CON CATEGORIA / TIPO PENS.";
                //    return false;
                //}
                /////////////////////////////////////////////////////////////////////////////////////////

                if (aumentoMensileLegge161289Art2.HasValue && aumentoMensileLegge161289Art2.Value > 0)
                {
                    messaggioVideo = "AUMENTO ART.2  DPCM INCOMPATIBILE CON CATEGORIA / TIPO PENS.";
                    return false;
                }
            }

            return true;
        }

