        #endregion PCIPL29

        #region PCIPL40
        /// <summary>
        /// Se il campo IW1IVSTOT (MPORTO IVS TOTALE CONTR)   >  0  allora controlla se i campi IW1CATPEN = 6 AND TP1CERTD(CERT. PENSIONE DIRETTA)  = 0 AND IW1DMOR minore 19680501 
        /// continua altrimenti controlla se il campo  W-DEORIG  >  197607 segnala errore  "I.V.S. AMMESSA SOLO PER DECORRENZE  ANTE 08/1976"  
        /// </summary>
        /// <param name="siglaCategoria"></param>
        /// <param name="importoIVS"></param>
        /// <param name="certificatoPensioneDiretta"></param>
        /// <param name="dataMorteDC"></param>
        /// <param name="decorrenzaDiretta"></param>
        /// <param name="decorrenzaOriginaria"></param>
        /// <param name="messaggioVideo"></param>
        /// <returns></returns>
        public static bool CI_VerificaImportoIVS(string siglaCategoria, decimal? importoIVS, int? certificatoPensioneDiretta, DateTime? dataMorteDC, DateTime? decorrenzaDiretta, DateTime? decorrenzaOriginaria, out string messaggioVideo)
        {
            messaggioVideo = string.Empty;
            DateTime? decorrenzaCompare = null;

            string categoriaNumerica = string.Empty;
            GestioneDecodifica.GetCodCategoriaBySiglaCategoria(siglaCategoria, out categoriaNumerica);
            bool IsImportoIVSVisible = false;
            if (int.Parse(categoriaNumerica) <= 6)
            {
                if (decorrenzaDiretta.HasValue)
                    decorrenzaCompare = decorrenzaDiretta;
                else
                    decorrenzaCompare = decorrenzaOriginaria;

                if (decorrenzaCompare != null && !Utility.DataSuccessivaA(decorrenzaCompare.Value, new DateTime(1976, 08, 01)))
                    IsImportoIVSVisible = true;

                if (importoIVS.HasValue && importoIVS.Value > 0)
                {
                    if (!(int.Parse(categoriaNumerica) == 6 && !certificatoPensioneDiretta.HasValue && !Utility.DataSuccessivaA(dataMorteDC.Value, new DateTime(1968, 05, 01))) &&
                        ((decorrenzaOriginaria.HasValue && decorrenzaOriginaria.Value.Year < 1996) || IsImportoIVSVisible))
                    {
                        if (Utility.DataStrettamenteSuccessivaA(decorrenzaCompare.Value, new DateTime(1976, 07, 31)))
                        {
                            messaggioVideo = "I.V.S. ammessa solo per decorrenza ante 08/1976";
                            return false;
                        }
                    }
                }
            }

            return true;
        }
        #endregion PCIPL40

        #endregion Dante Causa

        #region Supplementi
        #region PCIPL19
        /// <summary>
        /// 16.	Se IW3COGEST(INDICE) è uguale a "1" oppure "2" oppure "3" oppure "4"  oppure "I" oppure "M" oppure "N" continuare l'elaborazione al punto successivo (17), 
        /// diversamente valorizzare con "11" il campo  TIPO-ERRORE, con 09 il campo COL-ERR1, con "CODICE GESTIONE ERRATA  (1-2-3-4-I-M-N)" il campo MESSAGGIO-ERRORE, con 1 il 
        /// campo FLAG-ERR e uscire  da CONTROLLI-1 (54); 
        /// </summary>
        /// <param name="codGestioneSupplemento"></param>
        /// <param name="messaggioVideo"></param>
        /// <returns></returns>
        public static bool CI_VerificaCodiceGestione(string codGestioneSupplemento, out string messaggioVideo)
        {
            messaggioVideo = string.Empty;

            List<string> listaCodiciGestioneAmmessi = new List<string> { "1", "2", "3", "4", "I", "M", "N" };
            if (!listaCodiciGestioneAmmessi.Contains(codGestioneSupplemento))
            {
                messaggioVideo = "Codice Gestione errato (1-2-3-4-I-M-N)";
                return false;
            }

            return true;
        }

        /// <summary>
        /// 22.	Se  IW3DESUP(INDICE) è uguale a IW1DEORIG effettuare le seguenti operazioni: 
        /// 22.1.	Se IW1DEORIG è inferiore a 196805 e APPO-CAT1 non è uguale a "S" valorizzare con "33" il campo  TIPO-ERRORE, con 18 il campo COL-ERR1, con "CONTRIB. PER S.M. DA 
        /// INCLUDERE NEI CTR. POST.DEC.ORIGINARIA (CNV02/03)" il campo MESSAGGIO-ERRORE, con 1 il campo FLAG-ERR e uscire  da CONTROLLI-1 (54); 
        /// 24.	Se  ( IW3DESUP(INDICE) è inferiore a IW1DEORIG ) effettuare le seguenti operazioni: 
        /// 24.1.	Se ( APPO-CAT1 è uguale a "S" e  TP1CERTD è maggiore di zero ) effettuare le seguenti operazioni: 
        /// 24.1.1.	Se IW3DESUP(INDICE) è inferiore a IW1DIRET valorizzare con "35" il campo  TIPO-ERRORE, con 18 il campo COL-ERR1, con "DECORRENZA ANTERIORE ALLA DECORRENZA 
        /// ORIGINARIA DANTE CAUSA" il campo MESSAGGIO-ERRORE, con 1 il campo FLAG-ERR e uscire  da CONTROLLI-1 (54); 
        /// 24.2.	diversamente da quando analizzato nel punto precedente (24.1) valorizzare con "36" il campo  TIPO-ERRORE, con 18 il campo COL-ERR1, con "DECORRENZA ANTERIORE 
        /// ALLA DECORRENZA ORIGINARIA"  il campo MESSAGGIO-ERRORE, con 1 il campo FLAG-ERR e uscire  da CONTROLLI-1 (54); 
        /// 26.	Se  ( IW3DESUP(INDICE) è maggiore di IW1DEORIG ) e APPO-CAT1 è uguale a "S" valorizzare con "38" il campo  TIPO-ERRORE, con 18 il campo COL-ERR1, con "DECORRENZA 
        /// POSTERIORE A DECORR. ORIGINARIA NON CONSENTITA A REVERSIBILITA" il campo MESSAGGIO-ERRORE, con 1 il campo FLAG-ERR e uscire  da CONTROLLI-1 (54); 
        /// 27.	Se  ( IW3DESUP(INDICE) è uguale a IW1DEORIG) e (IW1CAT8 è uguale a "SOS " e TP1CERTD è uguale a 0)  effettuare le seguenti operazioni: 
        /// 27.1.	Se IW3COGEST(INDICE) è uguale a "1" valorizzare con "39" il campo  TIPO-ERRORE, con 18 il campo COL-ERR1, con "DECORR.SUPPLEMENTO UGUALE A DECORR.ORIGINARIA NON 
        /// AMMESSA PER GESTIONE '1'" il campo               MESSAGGIO-ERRORE, con 1 il campo FLAG-ERR e uscire  da CONTROLLI-1 (54); 
        /// </summary>
        /// <param name="decorrenzaSupplemento"></param>
        /// <param name="decorrenzaOriginaria"></param>
        /// <param name="gruppo"></param>
        /// <param name="messaggioVideo"></param>
        /// <returns></returns>
        public static bool CI_VerificaDecorrenzaSupplemento(DateTime? decorrenzaSupplemento, DateTime? decorrenzaOriginaria, string gruppo, int? certificatoPensioneDiretta, DateTime? decorrenzaDiretta, string siglaCategoria, string codGestioneSupplemento, out string messaggioVideo)
        {
            messaggioVideo = string.Empty;

            if (decorrenzaSupplemento.HasValue && decorrenzaOriginaria.HasValue && decorrenzaSupplemento.Equals(decorrenzaOriginaria))
            {
                if (!Utility.DataSuccessivaA(decorrenzaOriginaria.Value, new DateTime(1968, 05, 01)) && !gruppo.Equals("0003"))
                {
                    messaggioVideo = "Contrib. per S.M. da includere nei CTR. post.Dec.Originaria";
                    return false;
                }
            }

            if (decorrenzaSupplemento.HasValue && decorrenzaOriginaria.HasValue && !Utility.DataSuccessivaA(decorrenzaSupplemento.Value, decorrenzaOriginaria.Value))
            {
                if ((gruppo.Equals("0003") || gruppo.Equals("0031") || gruppo.Equals("0051")) && certificatoPensioneDiretta.GetValueOrDefault() > 0)
                {
                    if (decorrenzaDiretta.HasValue && !Utility.DataSuccessivaA(decorrenzaSupplemento.Value, decorrenzaDiretta.Value))
                    {
                        messaggioVideo = "Decorrenza anteriore alla Decorrenza Originaria Dante Causa";
                        return false;
                    }
                }
                else
                {
                    messaggioVideo = "Decorrenza anteriore alla Decorrenza Originaria";
                    return false;
                }
            }

            if (decorrenzaSupplemento.HasValue && decorrenzaOriginaria.HasValue && Utility.DataStrettamenteSuccessivaA(decorrenzaSupplemento.Value, decorrenzaOriginaria.Value) && gruppo.Equals("0003"))
            {
                messaggioVideo = "Decorrenza posteriore a Decorrenza Originaria non consentita a reversibilità";
                return false;
            }

            if (decorrenzaSupplemento.HasValue && decorrenzaOriginaria.HasValue && decorrenzaSupplemento.Equals(decorrenzaOriginaria) && !string.IsNullOrEmpty(siglaCategoria) && siglaCategoria.Trim().Equals("SOS") && certificatoPensioneDiretta.GetValueOrDefault() == 0)
            {
                if (!string.IsNullOrEmpty(codGestioneSupplemento) && codGestioneSupplemento.Equals("1"))
                {
                    messaggioVideo = "Decorrenza Supplemento uguale a Decorrenza Originaria non ammessa per Gestione '1'";
                    return false;
                }
            }

            return true;
        }

        /// <summary>
        /// 31.	Se  IW3DESUP(INDICE) è inferiore a  198107 effettuare le seguenti operazioni: 
        /// 31.1.	Se IW3IVS(INDICE) è maggiore di 52 valorizzare con "53" il campo TIPO-ERRORE, con 28 il campo COL-ERR1, con "IMPORTO 'I.V.S.' NON PUO' ESSERE MAGGIORE DI 52 EURO" 
        /// il campo MESSAGGIO-ERRORE, con 1 il campo FLAG-ERR e uscire  da CONTROLLI-1 (54);                                
        /// 32.	Diversamente da quando analizzato nel punto precedente (31) effettuare le seguenti operazioni:                                                        
        /// 32.1.	Se IW3IVS(INDICE) è maggiore di 500000 valorizzare con "53" il campo  TIPO-ERRORE, con 28 il campo COL-ERR1, con "IMPORTO 'I.V.S.' NON PUO' ESSERE MAGGIORE DI 
        /// 500.000 EURO" il campo MESSAGGIO-ERRORE, con 1 il campo FLAG-ERR e uscire  da CONTROLLI-1 (54);
        /// 33.	Se IW3RETSET(INDICE) è maggiore di 500000 valorizzare con "61" il campo TIPO-ERRORE, con 42 il campo COL-ERR1, con "IMPORTO 'R.M.S.' MAGGIORE DI 500.000 EURO"  il 
        /// campo MESSAGGIO-ERRORE, con 1 il campo FLAG-ERR e uscire  da CONTROLLI-1 (54);
        /// 34.	Se IW3IVSSOS(INDICE) è maggiore di 500000 valorizzare con "71" il campo  TIPO-ERRORE, con 56 il campo COL-ERR1, con "IMPORTO 'R.M.S.ART.2 DPCM' MAGGIORE DI 500.000 
        /// EURO" il campo MESSAGGIO-ERRORE, con 1 il campo FLAG-ERR e uscire  da CONTROLLI-1 (54);
        /// 35.	Se IW3SETANZ(INDICE) è uguale a zero valorizzare con "81" il campo TIPO-ERRORE, con 69 il campo COL-ERR1, con "NUMERO SETTIMANE MANCANTE " il campo MESSAGGIO-ERRORE, 
        /// con 1 il campo FLAG-ERR e uscire  da CONTROLLI-1 (54); 
        /// 38.	Se IW3COGEST(INDICE) è maggiore di "1" effettuare le seguenti operazioni:                                                        
        /// 38.1.	Se  IW3DESUP(INDICE) è inferiore a 198201 effettuare le seguenti operazioni:                                                      
        /// 38.1.1.	Se  IW3IVS(INDICE) è uguale a zero valorizzare con "57" il campo               TIPO-ERRORE, con 28 il campo COL-ERR1, con "PER DECORRENZE ANTE 01.82 DEVE ESSERE 
        /// PRESENTE 'I.V.S.' " il campo MESSAGGIO-ERRORE, con 1 il campo FLAG-ERR e uscire da CONTROLLI-1 (54);                                
        /// 38.1.2.	Se  IW3RETSET(INDICE) è maggiore di zero valorizzare con "63" il campo  TIPO-ERRORE, con 42 il campo COL-ERR1, con "PER DECORRENZE ANTE 01.82 NON DEVE ESSERE 
        /// PRESENTE 'R.M.S.' " il campo MESSAGGIO-ERRORE, con 1 il campo FLAG-ERR e uscire  da CONTROLLI-1 (54);                                
        /// 38.2.	Se  IW1CATPEN è maggiore di 6 e IW3DESUP(INDICE) è inferiore a 198200 e IW3DESUP(INDICE) è maggiore di zero effettuare le seguenti operazioni:                                                      
        /// 38.2.1.	Se IW3IVS(INDICE) è uguale a zero valorizzare con "58" il campo  TIPO-ERRORE, con 30 il campo COL-ERR1, con "PER DECORRENZE ANTE 01.82 DEVE ESSERE PRESENTE 
        /// 'I.V.S.' " il campo MESSAGGIO-ERRORE, con 1 il campo FLAG-ERR e uscire  da CONTROLLI-1 (54),                            
        /// 38.2.2.	diversamente da quando analizzato nel punto precedente (38.2.1) effettuare le seguenti operazioni:                                                    
        /// 38.2.2.1.	Se  IW3RETSET(INDICE) è maggiore di zero valorizzare con "64" il campo  TIPO-ERRORE, con 42 il campo COL-ERR1, con "PER DECORRENZE ANTE 01.82 NON DEVE ESSERE 
        /// PRESENTE 'R.M.S.' " il campo MESSAGGIO-ERRORE, con 1 il campo FLAG-ERR e uscire  da CONTROLLI-1 (54);   
        /// 45.	Se IW3COGEST(INDICE) è uguale a  "I" oppure "M" oppure "N"  effettuare le seguenti operazioni:  
        /// 45.1.	Se IW1CARIC è uguale a 1 e TP1CERTD è uguale a zero valorizzare con "90" il campo  TIPO-ERRORE, con 9 il campo  COL-ERR1, con "CODICE GESTIONE INCOMPATIBILE CON 
        /// CAUSA CARICO" il campo MESSAGGIO-ERRORE, con 1 il campo FLAG-ERR e uscire  da CONTROLLI-1 (54);                                
        /// 45.2.	Se IW3DESUP(INDICE) è inferiore a 199802 valorizzare con "91" il campo TIPO-ERRORE, con 9 il campo COL-ERR1, con "CODICE GESTIONE INCOMPATIBILE CON DECORRENZA" il 
        /// campo MESSAGGIO-ERRORE, con 1 il campo FLAG-ERR e uscire  da CONTROLLI-1 (54);       
        /// 45.3.	Se IW1DNAS è maggiore di zero valorizzare con IW1DNAS(1:6) il campo APPO-NAS, diversamente valorizzare con IW1NAT6 il campo APPO-NAS;                         
        /// 45.4.	Calcolare APPO-ETA = ( IW3DESUP(INDICE) - (APPO-NAS + 1)) / 100                                
        /// 45.5.	Se APPO-ETA è inferiore a 65 valorizzare con "93" il campo  TIPO-ERRORE, con 9 il campo COL-ERR1, con "CODICE GESTIONE INCOMPATIBILE CON ETA' (MINORE DI 65 ANNI)" 
        /// il campo MESSAGGIO-ERRORE, con 1 il campo FLAG-ERR e uscire da CONTROLLI-1 (54);  
        /// 50.	Se IW3DESUP(INDICE) è maggiore di 199600  effettuare le seguenti operazioni:                                                       
        /// 50.1.	Se IW3IVSSOS(INDICE) è maggiore di zero e IW3IVS(INDICE) maggiore di zero e IW3IVS(INDICE) è inferiore a IW3IVSSOS(INDICE) valorizzare con "95" il campo  
        /// TIPO-ERRORE, con 28 il campo COL-ERR1, con "MONTANTE 335/95 MINORE DI CONTRIBUTI 335/95" il campo MESSAGGIO-ERRORE, con 1 il campo FLAG-ERR e uscire da CONTROLLI-1 (54);                                
        /// </summary>
        /// <param name="decorrenzaSupplemento"></param>
        /// <param name="montanteSupplemento"></param>
        /// <param name="messaggioVideo"></param>
        /// <returns></returns>
        public static bool CI_ControlsSupplementi(DateTime? decorrenzaSupplemento, decimal? montanteSupplemento, decimal? rmsSupplemento, decimal? ammontareContributivo, int? nSettimaneSupplemento,
            string codGestioneSupplemento, int categoria, byte? causaCarico, int? certificatoPensioneDiretta, DateTime? dataNascitaDC, DateTime? dataNascitaTitolare,
            Utility.TipoAppartenenza? tipoAppartenenza, GestionePensione.DatiPensione datiPensione, out string messaggioVideo)
        {
            messaggioVideo = string.Empty;

            if (decorrenzaSupplemento.HasValue && !Utility.DataSuccessivaA(decorrenzaSupplemento.Value, new DateTime(1981, 07, 01)))
            {
                if (montanteSupplemento.GetValueOrDefault() > 52)
                {
                    messaggioVideo = "Importo 'I.V.S.' non puo' essere maggiore di 52 euro";
                    return false;
                }
            }
            else
            {
                if (montanteSupplemento.GetValueOrDefault() > 500000)
                {
                    messaggioVideo = "Importo 'I.V.S.' non puo' essere maggiore di 500.000 euro";
                    return false;
                }
            }

            if (rmsSupplemento.GetValueOrDefault() > 500000)
            {
                messaggioVideo = "Importo 'R.M.S.' maggiore di 500.000 euro";
                return false;
            }

            if (ammontareContributivo.GetValueOrDefault() > 500000)
            {
                messaggioVideo = "Importo 'R.M.S.ART.2 DPCM' maggiore di 500.000 euro";
                return false;
            }

            if (nSettimaneSupplemento.GetValueOrDefault() == 0)
            {
                messaggioVideo = "Numero Settimane mancante";
                return false;
            }

            if (!string.IsNullOrEmpty(codGestioneSupplemento) && !codGestioneSupplemento.Equals("1"))
            {
                if (decorrenzaSupplemento.HasValue && !Utility.DataSuccessivaA(decorrenzaSupplemento.Value, new DateTime(1982, 01, 01)))
                {
                    if (montanteSupplemento.GetValueOrDefault() == 0)
                    {
                        messaggioVideo = "Per Decorrenza ante 01/82 deve essere presente 'I.V.S.'";
                        return false;
                    }

                    if (rmsSupplemento.GetValueOrDefault() > 0)
                    {
                        messaggioVideo = "Per Decorrenza ante 01/82 non deve essere presente 'R.M.S.'";
                        return false;
                    }
                }

                if (categoria > 6 && decorrenzaSupplemento.HasValue && !Utility.DataSuccessivaA(decorrenzaSupplemento.Value, new DateTime(1982, 01, 01)))
                {
                    if (montanteSupplemento.GetValueOrDefault() == 0)
                    {
                        messaggioVideo = "Per Decorrenza ante 01/82 deve essere presente 'I.V.S.'";
                        return false;
                    }
                    else
                    {
                        if (rmsSupplemento.GetValueOrDefault() > 0)
                        {
                            messaggioVideo = "Per Decorrenza ante 01/82 non deve essere presente 'R.M.S.'";
                            return false;
                        }
                    }
                }
            }

            if (!string.IsNullOrEmpty(codGestioneSupplemento) && (codGestioneSupplemento.Equals("I") || codGestioneSupplemento.Equals("M") || codGestioneSupplemento.Equals("N")))
            {
                if (causaCarico.GetValueOrDefault() == 1 && certificatoPensioneDiretta.GetValueOrDefault() == 0
                    && !GestioneBypassControllo.CheckAndLockBypassControlloByNomeBypass(datiPensione, GestioneBypassControllo.NomeBypass.Suppl_Inf_A_2Anni_Per_Sent_CI.SUPPL_INF_A_2ANNI_PER_SENT_CI))
                {
                    messaggioVideo = "Codice Gestione incompatibile con Causa Carico";
                    return false;
                }

                if (decorrenzaSupplemento.HasValue && !Utility.DataSuccessivaA(decorrenzaSupplemento.Value, new DateTime(1998, 02, 01)))
                {
                    messaggioVideo = "Codice Gestione incompatibile con Decorrenza";
                    return false;
                }

                DateTime? dataNascitaCompare = null;

                if (dataNascitaDC.HasValue)
                    dataNascitaCompare = new DateTime(dataNascitaDC.Value.Year, dataNascitaDC.Value.Month, 01);
                else
                    dataNascitaCompare = new DateTime(dataNascitaTitolare.Value.Year, dataNascitaTitolare.Value.Month, 01);

                if (decorrenzaSupplemento.HasValue && (Utility.DifferenzaBetweenDate(decorrenzaSupplemento.Value, dataNascitaCompare.Value.AddMonths(1), tipoAppartenenza)).Year < 65)
                {
                    messaggioVideo = "Codice Gestione incompatibile con eta' (minore di 65 anni)";
                    return false;
                }
            }

            // Se la decorrenza del supplemento decorre dal 01/2015 allora l'ammontare dei contributi può essere maggiore del montante
            // Rif. Memo 30/2015
            if (decorrenzaSupplemento.HasValue && Utility.DataSuccessivaA(decorrenzaSupplemento.Value, new DateTime(1996, 01, 01)) &&
                !Utility.DataSuccessivaA(decorrenzaSupplemento.Value, new DateTime(2015, 01, 01)))
            {
                if (ammontareContributivo.GetValueOrDefault() > 0 && montanteSupplemento.GetValueOrDefault() > 0 && montanteSupplemento.GetValueOrDefault() < ammontareContributivo.GetValueOrDefault())
                {
                    messaggioVideo = "Montante 335/95 minore di Contributi 335/95";
                    return false;
                }
            }

            return true;
        }

        /// <summary>
        /// 58.	Se ISETMAT1 è maggiore di zero oppure ISETMAT2 è maggiore di zero oppure ISETMAT3 è maggiore di zero effettuare le seguenti operazioni: 
        /// 58.1.	Se (IW1CATPEN è inferiore a 7 e ( (IW1NSOBG +  IW1STOBG  + ICISTOBG335 +  IW1VVMISURA + ICI1VVOBG + TOT-SET-SUP-1 ) è inferiore a 260) ) oppure (IW1CATPEN è 
        /// maggiore di 6 e ((IW1SAOBG  +  IW1STOBG  +  ICISTOBG335  + IW1VVMISURA + ICI1VVOBG + TOT-SET-SUP-1 ) è inferiore a 260) )  valorizzare con "03" il campo  TIPO-ERRORE, 
        /// con 06 il campo RIG-ERRORE, con 28 il campo COL-ERR1, con "MATERNITA' DL 151/26.3.01 (CNV02) INCOMPATIBILE CON TOT.SETTIMANE " il campo MESSAGGIO-ERRORE, con 1 il campo 
        /// FLAG-ERR. 
        /// </summary>
        /// <param name="settimaneAl1292Maternita"></param>
        /// <param name="settimaneDL50392Maternita"></param>
        /// <param name="settimaneRetributiveQuotaA"></param>
        /// <param name="settimaneRetributiveQuotaB"></param>
        /// <param name="settimaneContributiveQuotaC"></param>
        /// <param name="vvMisuraAl1292"></param>
        /// <param name="vvMisuraDL50392"></param>
        /// <param name="sommaSettimaneSupplementi"></param>
        /// <param name="messaggioVideo"></param>
        /// <returns></returns>
        public static bool CI_VerificaSupplementiWithMaternita(int? settimaneAl1292Maternita, int? settimaneDL50392Maternita, int? settimaneRetributiveQuotaA, int? settimaneRetributiveQuotaB, int? settimaneContributiveQuotaC, int? vvMisuraAl1292, int? vvMisuraDL50392, int? sommaSettimaneSupplementi, out string messaggioVideo)
        {
            messaggioVideo = string.Empty;

            if (settimaneAl1292Maternita.GetValueOrDefault() > 0 || settimaneDL50392Maternita.GetValueOrDefault() > 0)
            {
                if (settimaneRetributiveQuotaA.GetValueOrDefault() + settimaneRetributiveQuotaB.GetValueOrDefault() + settimaneContributiveQuotaC.GetValueOrDefault() + vvMisuraAl1292.GetValueOrDefault() + vvMisuraDL50392.GetValueOrDefault() < 260)
                {
                    messaggioVideo = "Maternita' DL 151 del 26/3/01 incompatibile con totale Settimane";
                    return false;
                }
            }

            return true;
        }
        #endregion PCIPL19

        public static bool CI_VerificaSupplementi(List<DatiSupplementi> datiSupplementi, GestionePensione.DatiPensione datiPensione, out string messaggioVideo)
        {
            messaggioVideo = string.Empty;
            int? sommaSettimaneSupplementi = 0;
            Utility.TipoAppartenenza? tipoAppartenenza = Utility.GetTipoAppartenenza(datiPensione.IndConvInt, datiPensione.Gestione);
            DateTime dataSistema = GestioneControlliDinamici.GetDataSistema(tipoAppartenenza);
            int anniDifferenza = 0;
            bool flagEccezione = false;

            #region GetData
            BLCommon.GestioneDanteCausa.DatiDanteCausa danteCausa = null;
            BLCommon.GestioneDanteCausa.GetDanteCausabyIdPensione(datiPensione.Id, out danteCausa);

            GestioneAnagrafica.DatiAnagrafici datiAnagraficaDC = null;
            if (danteCausa != null)
                GestioneAnagrafica.GetAnagraficaByIdAnagrafica(danteCausa.IdAnagrafica, out datiAnagraficaDC);

            GestioneAnagrafica.DatiAnagrafici datiAnagrafica = null;
            GestioneAnagrafica.GetAnagraficaByIdPensione(datiPensione.Id, out datiAnagrafica);

            List<GestioneDatiContributiviCi.PensioniCiMaternitaAcna> listaMaternitaAcna = null;
            GestioneDatiContributiviCi.GetMaternitaAcnaByIdPensione(datiPensione.Id, out listaMaternitaAcna);

            List<GestioneCalcolo.DatiCalcoloRetributivo> listaDatiCalcoloRetributivo = null;
            GestioneCalcolo.GetCalcoloRetributivoCI_AGOByIdPensione(datiPensione.Id, out listaDatiCalcoloRetributivo);

            List<GestioneCalcolo.DatiCalcoloContributivo> listaDatiCalcoloContributivo = null;
            GestioneCalcolo.GetCalcoloContributivoCI_AGOByIdPensione(datiPensione.Id, out listaDatiCalcoloContributivo);

            GestioneDatiGenericiAgoCi.PensioniDatiGenerici datiGenericiAgoCi = null;
            GestioneDatiGenericiAgoCi.GetDatiGenericiByIdPensione(datiPensione.Id, out datiGenericiAgoCi);

            string categoriaNumerica = datiPensione.GetCodCategoria();
            int categoria = 0;
            int.TryParse(categoriaNumerica, out categoria);

            int? settimaneRetributiveQuotaACodGestione1 = null;
            decimal? rmsQuotaACodGestione1 = null;
            int? settimaneRetributiveQuotaBCodGestione1 = null;
            decimal? rmsQuotaBCodGestione1 = null;
            int? settimaneContributiveCodGestione1 = null;

            if (listaDatiCalcoloRetributivo != null && listaDatiCalcoloRetributivo.Count > 0)
            {
                foreach (GestioneCalcolo.DatiCalcoloRetributivo retr in listaDatiCalcoloRetributivo)
                {
                    if (retr.CodiceGestione == 1)
                    {
                        if (retr.QuotePrimeLiquidate == 'A')
                        {
                            settimaneRetributiveQuotaACodGestione1 = retr.NSettimaneQuotaA;
                            rmsQuotaACodGestione1 = retr.RMSQuotaA;
                        }
                        if (retr.QuotePrimeLiquidate == 'B')
                        {
                            settimaneRetributiveQuotaBCodGestione1 = retr.NSettimaneQuotaB;
                            rmsQuotaBCodGestione1 = retr.RMSQuotaB;
                        }
                    }
                }
            }

            if (listaDatiCalcoloContributivo != null && listaDatiCalcoloContributivo.Count > 0)
            {
                foreach (GestioneCalcolo.DatiCalcoloContributivo contr in listaDatiCalcoloContributivo)
                {
                    if (contr.CodiceGestione == 1)
                    {
                        if (contr.NSettimane.HasValue || contr.ImportoContributivoTotale.HasValue || contr.Montante.HasValue)
                        {
                            settimaneContributiveCodGestione1 = contr.NSettimane;
                        }
                    }
                }
            }

            int? settimaneAl1292Maternita = null;
            int? settimaneDL50392Maternita = null;

            if (listaMaternitaAcna != null && listaMaternitaAcna.Count > 0)
            {
                foreach (GestioneDatiContributiviCi.PensioniCiMaternitaAcna maternitaAcna in listaMaternitaAcna)
                {
                    if (maternitaAcna.Tipo == 'M')
                    {
                        settimaneAl1292Maternita = maternitaAcna.SettimaneAl1292;
                        settimaneDL50392Maternita = maternitaAcna.SettimaneDL50392;
                    }
                }
            }
            #endregion GetData

            if (datiSupplementi != null && datiSupplementi.Count > 0)
            {
                if (!string.IsNullOrEmpty(datiPensione.NaturaPensione) && (datiPensione.NaturaPensione.Substring(0, 1).Equals("3") || datiPensione.NaturaPensione.Substring(0, 1).Equals("4")) &&
                    (datiPensione.SiglaCategoria.Trim().Equals("IRS") || datiPensione.SiglaCategoria.Trim().Equals("IOARTS") || datiPensione.SiglaCategoria.Trim().Equals("IOCOMS")))
                {
                    messaggioVideo = "Supplementi non consentiti per Inabilita' Gestione Speciale";
                    return false;
                }

                DateTime? decorrenzaSupplementoRetributivoPrecedente = null;
                DateTime? decorrenzaSupplementoContributivoPrecedente = null;
                DateTime? appData = datiPensione.DecorrenzaOriginaria;
                string codGestioneSupplementoContributivoPrecedente = string.Empty;

                Utility.TipoCalcolo tipoCalcolo = Utility.GetTipoCalcolo(datiPensione);

                foreach (BLCommon.Entity.DatiSupplementi supp in datiSupplementi)
                {
                    #region Controlli comuni Retributivo - Contributivo
                    if (!supp.DecorrenzaSupplemento.HasValue)
                    {
                        messaggioVideo = "Decorrenza Supplemento obbligatoria.";
                        return false;
                    }

                    if (supp.DecorrenzaSupplemento.Value.CompareTo(dataSistema.AddMonths(1)) > 0)
                    {
                        messaggioVideo = "La Decorrenza Supplemento deve essere minore o uguale alla data odierna aumentata di 1 mese.";
                        return false;
                    }

                    // Se la decorrenza del supplemento decorre dal 01/2015 allora l'ammontare dei contributi può essere maggiore del montante
                    // Rif. Memo 30/2015
                    if (!Utility.DataSuccessivaA(supp.DecorrenzaSupplemento.Value, new DateTime(2015, 01, 01)))
                    {
                        if ((supp.AmmontareContributivo.HasValue && supp.MontanteSupplemento.HasValue) && supp.AmmontareContributivo.Value.CompareTo(supp.MontanteSupplemento.Value) > 0)
                        {
                            messaggioVideo = "L'Ammontare dei Contributi non può essere maggiore del Montante IVS.";
                            return false;
                        }
                    }

                    DateTime? decorrenzaDirettaDC = danteCausa != null ? danteCausa.DecorrenzaPensione : null;

                    //ENG - Modifica Supplementi CI Memo 177/2012
                    if (decorrenzaDirettaDC != null && supp.DecorrenzaSupplemento.Value != decorrenzaDirettaDC && !Utility.IsDomandaReversibilitaOrRicostituzione(datiPensione, danteCausa))
                    {
                        anniDifferenza = (supp.DecorrenzaSupplemento.Value - Utility.FirstDayOfMonth(decorrenzaDirettaDC.Value)).Days / 365;
                        if (anniDifferenza < 2 && !GestioneBypassControllo.CheckAndLockBypassControlloByNomeBypass(datiPensione, GestioneBypassControllo.NomeBypass.Suppl_Inf_A_2Anni_Per_Sent_CI.SUPPL_INF_A_2ANNI_PER_SENT_CI))
                        {
                            messaggioVideo = "E' consentito inserire un supplemento solamente dopo 5 anni dalla decorrenza della pensione o dal precedente supplemento (" + String.Format("{0:MM/yyyy}", decorrenzaDirettaDC) + ") con un'unica eccezione a 2 anni.";
                            return false;
                        }

                        if (anniDifferenza >= 2 && anniDifferenza < 5)
                        {
                            if (flagEccezione)
                            {
                                messaggioVideo = "E' consentito un unico supplemento dopo 2 anni dalla decorrenza della pensione o dal precedente supplemento (" + String.Format("{0:MM/yyyy}", appData) + "). " +
                                           "Il successivo supplemento deve essere inserito dopo 5 anni dal precedente.";
                                return false;
                            }
                            else
                                flagEccezione = true;
                        }
                    }
                    appData = supp.DecorrenzaSupplemento;

                    if (supp.TipoSupplemento == 'R')
                    {
                        if (!supp.QuotaSupplemento.HasValue)
                        {
                            messaggioVideo = "Quota Supplemento Retributivo obbligatorio. Valori ammessi A o B.";
                            return false;
                        }
                    }

                    if (supp.TipoSupplemento == 'C')
                    {
                        if (!supp.QuotaSupplemento.HasValue)
                        {
                            messaggioVideo = "Quota Supplemento Contributivo obbligatorio. Valori ammessi C o D.";
                            return false;
                        }
                    }

                    if (!GestioneCrossControls.CI_VerificaCodiceGestione(supp.CodGestioneSupplemento, out messaggioVideo))
                        return false;

                    if (supp.TipoSupplemento == 'R')
                    {
                        if (decorrenzaSupplementoRetributivoPrecedente.HasValue)
                        {
                            if (!Utility.DataSuccessivaA(supp.DecorrenzaSupplemento.Value, decorrenzaSupplementoRetributivoPrecedente.Value))
                            {
                                messaggioVideo = "Supplementi Retributivi: Decorrenza anteriore a Decorrenza della riga precedente";
                                return false;
                            }
                        }

                        decorrenzaSupplementoRetributivoPrecedente = supp.DecorrenzaSupplemento;

                    }

                    if (supp.TipoSupplemento == 'C')
                    {
                        //ENG - Modifica Supplementi CI Memo 177/2012
                        if (supp.QuotaSupplemento == 'D')
                        {
                            if (supp.DecorrenzaSupplemento.HasValue && !Utility.DataSuccessivaA(supp.DecorrenzaSupplemento.Value, new DateTime(2012, 02, 01)))
                            {
                                messaggioVideo = "Per i supplementi con quota D la decorrenza supplemento non può essere inferiore a 02/2012";
                                return false;
                            }
                        }
                        //ENG - Modifica Supplementi CI Memo 177/2012
                        if (datiPensione.Tipo == "0017" || datiPensione.Tipo == "0030" &&
                            datiSupplementi.Exists(x => (x.QuotaSupplemento == 'C' || x.QuotaSupplemento == 'D') && !(x.CodGestioneSupplemento == "1" || x.CodGestioneSupplemento == "2" || x.CodGestioneSupplemento == "3" || x.CodGestioneSupplemento == "4")))
                        {
                            messaggioVideo = "Per le domande con tipo 0017 e 0030 non è possibile inserire solo la gestione al 50%(I,M,N)";
                            return false;
                        }

                        if (decorrenzaSupplementoContributivoPrecedente.HasValue)
                        {
                            if (!Utility.DataSuccessivaA(supp.DecorrenzaSupplemento.Value, decorrenzaSupplementoContributivoPrecedente.Value))
                            {
                                messaggioVideo = "Supplementi Contributivi: Decorrenza anteriore a Decorrenza della riga precedente";
                                return false;
                            }

                            //ENG - Modifica Supplementi CI Memo 177/2012
                            if (supp.DecorrenzaSupplemento.HasValue && supp.DecorrenzaSupplemento.Value == decorrenzaSupplementoContributivoPrecedente)
                            {
                                if (!string.IsNullOrEmpty(codGestioneSupplementoContributivoPrecedente))
                                {
                                    //ENG - Modificato controllo per permettere anche l'inserimento delle gestione al 100% (1,2,3,4), mantenendo il vincolo su quelle al 50% (M,N,I)
                                    if ((codGestioneSupplementoContributivoPrecedente == "2" && (supp.CodGestioneSupplemento == "M" || supp.CodGestioneSupplemento == "N")) ||
                                        (codGestioneSupplementoContributivoPrecedente == "3" && (supp.CodGestioneSupplemento == "N" || supp.CodGestioneSupplemento == "I")) ||
                                        (codGestioneSupplementoContributivoPrecedente == "4" && (supp.CodGestioneSupplemento == "M" || supp.CodGestioneSupplemento == "I")))
                                    {
                                        messaggioVideo = "Gestione inserita incompatibile.";
                                        return false;
                                    }
                                }

                                if (datiSupplementi.Where(x => x.CodGestioneSupplemento == supp.CodGestioneSupplemento && x.QuotaSupplemento == supp.QuotaSupplemento && x.DecorrenzaSupplemento.GetValueOrDefault() == supp.DecorrenzaSupplemento.GetValueOrDefault()).Count() > 1)
                                {
                                    messaggioVideo = "Non è possibile inserire doppie occorrenze uguali.";
                                    return false;
                                }
                            }
                        }

                        decorrenzaSupplementoContributivoPrecedente = supp.DecorrenzaSupplemento;
                        codGestioneSupplementoContributivoPrecedente = supp.CodGestioneSupplemento;
                    }

                    if (!GestioneCrossControls.CI_VerificaDecorrenzaSupplemento(supp.DecorrenzaSupplemento, datiPensione.DecorrenzaOriginaria, datiPensione.Gruppo, danteCausa != null ? danteCausa.Certificato : null, danteCausa != null ? danteCausa.DecorrenzaPensione : null, datiPensione.SiglaCategoria, supp.CodGestioneSupplemento, out messaggioVideo))
                        return false;

                    if (!GestioneCrossControls.CI_ControlsSupplementi(supp.DecorrenzaSupplemento, supp.MontanteSupplemento, supp.RMSSupplemento, supp.AmmontareContributivo, supp.NSettimaneSupplemento,
                        supp.CodGestioneSupplemento, categoria, datiPensione.CausaCarico, danteCausa != null ? danteCausa.Certificato : null, datiAnagraficaDC != null ? datiAnagraficaDC.DataNascita : null,
                        datiAnagrafica.DataNascita, tipoAppartenenza, datiPensione, out messaggioVideo))
                        return false;

                    //verifico se è una diretta.
                    //if (datiPensione.Gruppo == "0001" || datiPensione.Gruppo == "0002")
                    //{
                    //    if (supp.DecorrenzaSupplemento.Value.CompareTo(datiPensione.DecorrenzaOriginaria.Value.AddYears(2)) <= 0)
                    //    {
                    //        messaggioVideo = "Decorrenza Supplemento: Per le dirette deve essere superiore di 2 anni dalla Decorrenza Originaria.";
                    //        return false;
                    //    }
                    //}

                    Utility.TipoDomanda tipoDomanda = Utility.GetTipoDomanda(datiPensione.Gruppo, datiPensione.Prodotto);
                    if (tipoDomanda == Utility.TipoDomanda.Superstiti)
                    {
                        if (danteCausa == null)
                        {
                            messaggioVideo = "Dati Dante Causa mancanti.";
                            return false;
                        }

                        //verifico se è una reversibilità da assicurato
                        if (datiPensione.Prodotto == "0022")
                        {
                            if (supp.DecorrenzaSupplemento.Value.CompareTo(datiPensione.DecorrenzaOriginaria.Value) != 0)
                            {
                                messaggioVideo = "Decorrenza Supplemento: Per le reversibilità da assicurato non può essere diversa dalla Decorrenza Originaria.";
                                return false;
                            }
                        }

                        //verifico se è una reversibilità da pensionato
                        if (datiPensione.Prodotto == "0021")
                        {
                            if ((danteCausa.DecorrenzaPensione.HasValue) && (supp.DecorrenzaSupplemento.Value.CompareTo(danteCausa.DecorrenzaPensione.Value) < 0) ||
                                (supp.DecorrenzaSupplemento.Value.CompareTo(datiPensione.DecorrenzaOriginaria.Value) > 0))
                            {
                                messaggioVideo = "Decorrenza Supplemento: Per le reversibilità da pensionato, la decorrenza supplemento può essere compresa tra la decorrenza originaria della diretta e la decorrenza originaria della reversibilità.";
                                return false;
                            }
                        }
                    }

                    #endregion Controlli comuni Retributivo - Contributivo

                    sommaSettimaneSupplementi = sommaSettimaneSupplementi.GetValueOrDefault() + supp.NSettimaneSupplemento.GetValueOrDefault();
                }

                if (!CI_VerificaSupplementiWithMaternita(settimaneAl1292Maternita, settimaneDL50392Maternita, settimaneRetributiveQuotaACodGestione1, settimaneRetributiveQuotaBCodGestione1,
                    settimaneContributiveCodGestione1, datiGenericiAgoCi != null ? datiGenericiAgoCi.VVMisuraAl1292 : null, datiGenericiAgoCi != null ? datiGenericiAgoCi.VVMisuraDL50392 : null,
                    sommaSettimaneSupplementi, out messaggioVideo))
                    return false;
            }

            return true;
        }
        #endregion Supplementi

        #region Routine
        #region PCIPL11

        /// <summary>
        /// 52.	Se IW4SIG(INDICE) è uguale a "C" oppure è uguale a "I" oppure è uguale a "A" oppure  IW4SIG(INDICE) è uguale a "K" oppure è uguale a "Y" oppure è uguale a "F" 
        /// effettuare le seguenti operazioni : Valorizzare con 999999 il campo WAFSCA6; 
        /// 53.	Se IW4SIG(INDICE) è uguale a "M" oppure IW4SIG(INDICE) è uguale a "N" oppure è uguale a "P" oppure è uguale a "G" oppure "J" valorizzare con WDANAS-SAM il campo 
        /// WAFSCA6 e  aggiungere 1800 al campo WAFSCA6;                                   
        /// 54.	Se ( IW4SIG(INDICE) è uguale a "N" oppure è uguale a "J" ) e WAFSCA6 è maggiore di  (ANNO-COMPET * 100 + 101) calcolare WAFSCA6 = (ANNO-COMPET * 100  +  12);
        /// 55.	Se IW4SIG(INDICE) è uguale a "S" oppure è uguale a "L" oppure IW4SIG(INDICE) è uguale a "Z" valorizzare con WDANAS-SAM il campo WAFSCA6aggiungere 2100 al campo 
        /// WAFSCA6;
        /// 56.	Se IW4SIG(INDICE) è uguale a "U" oppure IW4SIG(INDICE) è uguale a "W" valorizzare con WDANAS-SAM il campo WAFSCA6 aggiungere 2600 al campo WAFSCA6;     
        /// 57.	Aggiungere 1 al campo W-AF-SCA-MM;
        ///      **** IL MESE SCADENZA DEVE ESSERE PARI                             
        ///      **** (SOLO PER CAUSA CARICO DIVERSO DA 1 E CESSAZ minore 0798           
        /// 58.	Se IW1CARIC è maggiore di 1 e WAFSCA6 è minore di 199808 effettuare le seguenti operazioni : 
        /// 58.1.	Se W-AF-SCA-MM è uguale a 3 oppure è uguale a 5 oppure è uguale a 7 oppure è uguale a 9 oppure è uguale a 11 aggiungere 1 al campo W-AF-SCA-MM;
        /// </summary>
        /// <param name="siglaFamiliare"></param>
        /// <param name="dataNascitaFamiliare"></param>
        /// <param name="annoCompetenza"></param>
        /// <param name="causaCarico"></param>
        /// <returns></returns>
        public static DateTime? CalcolaCessazioneCarico(char? siglaFamiliare, DateTime? dataNascitaFamiliare, int? annoCompetenza, byte? causaCarico)
        {
            DateTime? appData = null;

            List<char> listaSigleFamiliari = new List<char> { 'C', 'I', 'A', 'K', 'Y', 'F' };
            if (listaSigleFamiliari.Contains(siglaFamiliare.Value))
                appData = DateTime.MaxValue;

            listaSigleFamiliari = new List<char> { 'M', 'N', 'P', 'G', 'J' };
            if (listaSigleFamiliari.Contains(siglaFamiliare.Value))
                appData = new DateTime(dataNascitaFamiliare.Value.Year + 18, dataNascitaFamiliare.Value.Month, 01);

            //listaSigleFamiliari = new List<char> { 'N', 'J' };
            //if (listaSigleFamiliari.Contains(siglaFamiliare.Value) && appData.HasValue && Utility.DataStrettamenteSuccessivaA(appData.Value, new DateTime(annoCompetenza.Value + 1, 01, 01)))
            //    appData = new DateTime(annoCompetenza.Value + 1, 12, 01);

            listaSigleFamiliari = new List<char> { 'S', 'L', 'Z' };
            if (listaSigleFamiliari.Contains(siglaFamiliare.Value))
                appData = new DateTime(dataNascitaFamiliare.Value.Year + 21, dataNascitaFamiliare.Value.Month, 01);

            listaSigleFamiliari = new List<char> { 'U', 'W' };
            if (listaSigleFamiliari.Contains(siglaFamiliare.Value))
                appData = new DateTime(dataNascitaFamiliare.Value.Year + 26, dataNascitaFamiliare.Value.Month, 01);

            if (appData.HasValue && !appData.Equals(DateTime.MaxValue))
            {
                appData = appData.Value.AddMonths(1);

                if (causaCarico.GetValueOrDefault() > 1 && !Utility.DataSuccessivaA(appData.Value, new DateTime(1998, 08, 01)))
                    if (appData.Value.Month == 3 || appData.Value.Month == 5 || appData.Value.Month == 7 || appData.Value.Month == 9 || appData.Value.Month == 11)
                        appData = appData.Value.AddMonths(1);
            }

            return appData;
        }

        #endregion PCIPL11
        #endregion Routine

        #region Maggiorazioni/Benefici
        public static bool CI_ControlsTipoBeneficioArt24Comma15Bis(GestionePensione.DatiPensione datiPensione, string tipoSettimaneBeneficio, int? nSettimaneBeneficio, DateTime? decorrenzaOriginaria,
            string naturaPensione, char? sessoTitolare, DateTime? dataNascitaTitolare, GestioneIstruttoria.DatiIstruttoria datiIstruttoria, GestioneDatiGenericiAgoCi.PensioniDatiGenerici datiPensioniDatiGenerici,
            List<GestioneDatiContributiviCi.PensioniCiPrestazioniEE> listaPensioniCiPrestazioniEE, out string messaggioVideo)
        {
            messaggioVideo = string.Empty;

            if (tipoSettimaneBeneficio == "10")
            {
                int sommaSettimaneUtiliAlDiritto = CI_GetNumeroSettimane(datiIstruttoria, datiPensioniDatiGenerici, listaPensioniCiPrestazioniEE, datiPensione);
                bool isRipristino = Utility.IsDomandaRipristino(datiPensione) != null ? (bool)Utility.IsDomandaRipristino(datiPensione) : false;

                if (!isRipristino && !GestioneCrossControls.ALL_IsTipoBeneficioArt24Comma15BisAmmesso(datiPensione, null, decorrenzaOriginaria, naturaPensione, sessoTitolare, dataNascitaTitolare,
                    sommaSettimaneUtiliAlDiritto))
                {
                    messaggioVideo = "Il Tipo Beneficio non è corretto. Non sono presenti i requisiti di cui alla circolare 35/2012.";
                    return false;
                }

                if (nSettimaneBeneficio.GetValueOrDefault() > 0)
                {
                    messaggioVideo = "Il Numero settimane beneficio non è ammesso.";
                    return false;
                }
            }

            return true;
        }
        #endregion Maggiorazioni/Benefici

        public static int CI_GetNumeroSettimane(GestioneIstruttoria.DatiIstruttoria datiIstruttoria, GestioneDatiGenericiAgoCi.PensioniDatiGenerici datiPensioniDatiGenerici,
            List<GestioneDatiContributiviCi.PensioniCiPrestazioniEE> listaPensioniCiPrestazioniEE, GestionePensione.DatiPensione datiPensione)
        {
            return CI_GetNumeroSettimane(datiIstruttoria != null ? datiIstruttoria.NSettimaneOBG.GetValueOrDefault() : 0,
                datiIstruttoria != null ? datiIstruttoria.NContributiVolontari.GetValueOrDefault() : 0,
                datiPensioniDatiGenerici != null ? datiPensioniDatiGenerici.SettimaneItalianeDiritto.GetValueOrDefault() : 0,
                listaPensioniCiPrestazioniEE, datiPensione);
        }

        public static int CI_GetNumeroSettimane(int? nSettimaneOBG, int? nContributiVolontari, int? nSettimaneItalianeDiritto, List<GestioneDatiContributiviCi.PensioniCiPrestazioniEE> listaPensioniCiPrestazioniEE, GestionePensione.DatiPensione datiPensione)
        {
            int sommaSettimaneUtiliAlDiritto = 0;
            if (Utility.IsDomandaAnticipataFlessibileOpzioneContributivo(datiPensione) || (Utility.IsDomandaAnticipataFlessibileLeggeBilancio2024(datiPensione) && datiPensione.SiglaCategoria.Trim() != "VOS") || Utility.IsDomandaAnticipataFlessibileOpzioneContributivoLeggeBilancio2024(datiPensione))
            {
                if (datiPensione.SiglaCategoria.Trim() == "VOS" || datiPensione.SiglaCategoria.Trim() == "IOS" || datiPensione.SiglaCategoria.Trim() == "SOS")
                {
                    sommaSettimaneUtiliAlDiritto += nSettimaneOBG.GetValueOrDefault();
                    sommaSettimaneUtiliAlDiritto += listaPensioniCiPrestazioniEE != null ? listaPensioniCiPrestazioniEE.Sum(x => x.ContributiEEDiritto.GetValueOrDefault()) : 0;
                }
                else
                {
                    sommaSettimaneUtiliAlDiritto += nSettimaneItalianeDiritto.GetValueOrDefault();
                    sommaSettimaneUtiliAlDiritto += listaPensioniCiPrestazioniEE != null ? listaPensioniCiPrestazioniEE.Sum(x => x.ContributiEEDiritto.GetValueOrDefault()) : 0;
                }
            }
            else
            {
                sommaSettimaneUtiliAlDiritto += nSettimaneOBG.GetValueOrDefault();
                sommaSettimaneUtiliAlDiritto += nContributiVolontari.GetValueOrDefault();
                sommaSettimaneUtiliAlDiritto += nSettimaneItalianeDiritto.GetValueOrDefault();
                sommaSettimaneUtiliAlDiritto += listaPensioniCiPrestazioniEE != null ? listaPensioniCiPrestazioniEE.Sum(x => x.ContributiEEDiritto.GetValueOrDefault()) : 0;
            }
            return sommaSettimaneUtiliAlDiritto;
        }

        #endregion CI

        #region AGO
        #region Titolare

        public static bool AGO_VerificaPerfezionamentoRequisiti_Decorrenza_ScadenzaAssegno(GestionePensione.DatiPensione datiPensione, DateTime? decorrenzaPensione, DateTime? dataPerfReq, DateTime? scadenzaAssegno,
            out string messaggioVideo)
        {
            messaggioVideo = string.Empty;

            if (Utility.IsDomandaVESO33(datiPensione.SiglaCategoria) || Utility.IsDomandaVESO92(datiPensione.SiglaCategoria) || Utility.IsDomandaVOCRED_CRED27(datiPensione.SiglaCategoria) ||
                Utility.IsDomandaVOCOOP_COOP28(datiPensione.SiglaCategoria) || Utility.IsDomandaVESO29(datiPensione.SiglaCategoria) || Utility.IsDomandaVOESO(datiPensione.SiglaCategoria) ||
                Utility.IsDomandaESOTEL(datiPensione.SiglaCategoria) || Utility.IsDomandaESOAMB(datiPensione.SiglaCategoria) || Utility.IsDomandaESPA(datiPensione.SiglaCategoria))
            {
                if (dataPerfReq.HasValue && scadenzaAssegno.HasValue && dataPerfReq > scadenzaAssegno)
                {
                    messaggioVideo = string.Format("La Data Perfezionamento Requisiti ({0}) deve essere minore o uguale alla Scadenza Assegno ({1}).", dataPerfReq.Value.ToString("dd/MM/yyyy"), scadenzaAssegno.Value.ToString("MM/yyyy"));
                    return false;
                }
            }

            if (Utility.IsDomandaESOPMI(datiPensione.SiglaCategoria))
            {
                if (dataPerfReq.HasValue && scadenzaAssegno.HasValue && dataPerfReq >= scadenzaAssegno)
                {
                    messaggioVideo = string.Format("La Data Perfezionamento Requisiti ({0}) deve essere minore della Scadenza Assegno ({1}).", dataPerfReq.Value.ToString("dd/MM/yyyy"), scadenzaAssegno.Value.ToString("MM/yyyy"));
                    return false;
                }
            }

            return true;
        }

        public static bool AGO_VerificaPerfezionamentoRequisiti_Decorrenza_InvaliditaOver80(GestionePensione.DatiPensione datiPensione, DateTime? decorrenzaPensione, DateTime? dataPerfReq, out string messaggioVideo)
        {
            messaggioVideo = string.Empty;

            if (Utility.IsDomandaVO(datiPensione.SiglaCategoria) && Utility.IsDomandaManualeInvaliditaOver80(datiPensione) && decorrenzaPensione.HasValue && dataPerfReq.HasValue
                && !GestioneBypassControllo.CheckAndLockBypassControlloByNomeBypass(datiPensione, GestioneBypassControllo.NomeBypass.Titolare_Anagrafica_AGO.BYPASS_FINESTRA_12MESI))
            {
                DateTime datacompare = Utility.FirstDayOfMonth(dataPerfReq.Value.AddMonths(13));
                if (!Utility.DataSuccessivaA(decorrenzaPensione.Value, datacompare))
                {
                    messaggioVideo = "Il periodo intercorrente tra Data Perfezionamento Requisiti e Decorrenza Pensione deve essere superiore a 12 mesi.";
                    return false;
                }
            }

            return true;
        }

        public static bool AGO_VerificaDecorrenzaPensione(DateTime? decorrenzaPensione, DateTime? dataPerfReq, GestionePensione.DatiPensione datiPensione,
            GestioneAnagrafica.DatiAnagrafici datiAnagraficiTitolare, GestioneDanteCausa.DatiDanteCausa datiDanteCausa, GestioneLavorazione.DatiLavorazione datiLavorazione,
            GestionePensione.DatiEliminazione datiEliminazione, GestioneDatiGenericiAgoCi.PensioniDatiGenerici datiGenericiAgoCi, DateTime dataSistema, bool isRiaperturaDomanda, DateTime? dataCondizioniPerComputo,
            GestionePensione.DatiPensione datiPensioneUI, out string messaggioVideo)
        {
            messaggioVideo = string.Empty;

            string siglaCategoria = string.Empty;
            string filtro = string.Empty;
            DateTime decorrenzaOriginaria = DateTime.MinValue;
            string certificato = string.Empty;
            char codNat1 = ' ';
            char codNat2 = ' ';
            char codNat3 = ' ';
            char? tipoDomanda = null;
            GestioneDecodificaAzienda.DecAzienda codiceBancaEsodati = null;
            GestioneAziendeVESO33.DecAziendeVESO33 azVESO33 = null;
            GestioneAziendeVESO29.DecAziendeVESO29 azVESO29 = null;
            GestioneAziendeCredito.DecAziendeCredito azCredito = null;
            GestioneAziendeVOESO.DecAziendeVOESO azVOESO = null;
            GestioneAziendeESOTEL.DecAziendeESOTEL azESOTEL = null;
            GestioneAziendeESOAMB.DecAziendeESOAMB azESOAMB = null;

            #region Recupero Dati

            Utility.TipoDomanda tipologiaDomanda = Utility.GetTipoDomanda(datiPensione.Gruppo, datiPensione.Prodotto);

            filtro = datiPensione.GetFiltro();
            Utility.GetCodiciNatura(datiPensione.NaturaPensione, out codNat1, out codNat2, out codNat3);
            decorrenzaOriginaria = decorrenzaPensione.HasValue ? decorrenzaPensione.Value : DateTime.MinValue;
            siglaCategoria = datiPensione.SiglaCategoria.Trim().ToUpperInvariant();
            certificato = datiPensione.NCertificato.HasValue ? datiPensione.NCertificato.Value.ToString().PadLeft(8, '0') : "00000000";
            bool isRipristino = Utility.IsDomandaRipristino(datiPensione) != null ? (bool)Utility.IsDomandaRipristino(datiPensione) : false;

            if (datiLavorazione != null)
                tipoDomanda = datiLavorazione.TipoDomanda;

            if (datiPensione.CodiceBancaEsodati.HasValue)
            {
                List<GestioneDecodificaAzienda.DecAzienda> listaDecAzienda = null;
                GestioneDecodificaAzienda.GetElencoAziendaBySiglaCategoria(siglaCategoria, datiPensione.Tipo, out listaDecAzienda);
                if (listaDecAzienda != null && listaDecAzienda.Count > 0)
                    codiceBancaEsodati = listaDecAzienda.Find(x => x.Id == datiPensione.CodiceBancaEsodati.Value);

                if (Utility.IsDomandaVESO33(siglaCategoria))
                {
                    if (codiceBancaEsodati != null)
                        GestioneAziendeVESO33.GetDecodificaAziendaVESO33ByIdCodiceAzienda(codiceBancaEsodati.Id, out azVESO33);
                }
                else if (Utility.IsDomandaVOCOOP_COOP28(siglaCategoria) || Utility.IsDomandaVOCRED_CRED27(siglaCategoria))
                {
                    if (codiceBancaEsodati != null)
                        GestioneAziendeCredito.GetDecodificaAziendaCreditoByIdCodiceAzienda(codiceBancaEsodati.Id, out azCredito);
                }
                else if (Utility.IsDomandaVESO29(siglaCategoria))
                {
                    if (codiceBancaEsodati != null)
                        GestioneAziendeVESO29.GetDecodificaAziendaVESO29ByIdCodiceAzienda(codiceBancaEsodati.Id, out azVESO29);
                }
                else if (Utility.IsDomandaVOESO(siglaCategoria))
                {
                    if (codiceBancaEsodati != null)
                        GestioneAziendeVOESO.GetDecodificaAziendaVOESOByIdCodiceAzienda(codiceBancaEsodati.Id, out azVOESO);
                }
                else if (Utility.IsDomandaESOTEL(siglaCategoria))
                {
                    if (codiceBancaEsodati != null)
                        GestioneAziendeESOTEL.GetDecodificaAziendaESOTELByIdCodiceAzienda(codiceBancaEsodati.Id, out azESOTEL);
                }
                else if (Utility.IsDomandaESOAMB(siglaCategoria))
                {
                    if (codiceBancaEsodati != null)
                        GestioneAziendeESOAMB.GetDecodificaAziendaESOAMBByIdCodiceAzienda(codiceBancaEsodati.Id, out azESOAMB);
                }
            }
            #endregion Recupero Dati

            if (!Utility.IsDomandaENPALS(datiPensione.Gestione))
            {
                DateTime? dataCompare = null;
                GestioneControlliDinamici.ControlloDinamico ctrl = null;

                //La Decorrenza Originaria (RAU104) non può essere superiore di 1 mese
                //dalla data in liquidazione (data odierna, mese ed anno)
                if (Utility.DataStrettamenteSuccessivaA(decorrenzaOriginaria, dataSistema.AddDays(1 - dataSistema.Day).AddMonths(1)))
                {
                    messaggioVideo = "La decorrenza non può essere superiore di 1 mese dalla data di liquidazione";
                    return false;
                }

                if (Utility.IsDomandaIndennitaUnaTantum_AGO(datiPensione))
                {
                    if (!Utility.DataSuccessivaA(decorrenzaOriginaria, new DateTime(1996, 2, 1)))
                    {
                        messaggioVideo = "La decorrenza non può essere inferiore a 02/1996.";
                        return false;
                    }
                }
                //else? 
                else
                {
                    switch (siglaCategoria)
                    {
                        case "VOCOOP":
                            if (!Utility.DataSuccessivaA(decorrenzaOriginaria, new DateTime(2000, 1, 1)))
                            {
                                messaggioVideo = "La decorrenza assegno non può essere inferiore a Gennaio 2000";
                                return false;
                            }
                            if (!Utility.IsRicostituzioneOrRiapertura(datiPensione, isRiaperturaDomanda) && Utility.DataStrettamenteSuccessivaA(decorrenzaOriginaria, new DateTime(2016, 12, 1)))
                            {
                                messaggioVideo = "La decorrenza assegno non può essere superiore a Dicembre 2016";
                                return false;
                            }

                            if (!AGO_VerificaDecorrenzaPensioneSuperioreVOCOOP_COOP28(decorrenzaOriginaria, azCredito, codiceBancaEsodati, siglaCategoria, out messaggioVideo))
                                return false;
                            break;
                        case "COOP28":
                            if (Utility.IsDomandaQuota100COOP28(datiPensione))
                            {
                                if (!Utility.DataSuccessivaA(decorrenzaOriginaria, new DateTime(2019, 2, 1)))
                                {
                                    messaggioVideo = "La decorrenza non può essere inferiore a 02/2019.";
                                    return false;
                                }
                                if (Utility.DataStrettamenteSuccessivaA(decorrenzaOriginaria, new DateTime(2022, 1, 1)))
                                {
                                    messaggioVideo = "La decorrenza non può essere strettamente successiva a 01/2022.";
                                    return false;
                                }
                            }
                            else
                            {
                                if (!Utility.DataSuccessivaA(decorrenzaOriginaria, new DateTime(2017, 1, 1)))
                                {
                                    messaggioVideo = "La decorrenza assegno non può essere inferiore a Gennaio 2017";
                                    return false;
                                }

                                GestioneControlliDinamici.GetControlloDinamicoByNomeControllo("DecorrenzaSuperioreCOOP28", out ctrl);
                                dataCompare = ctrl != null ? Utility.DataFromString(ctrl.ValoreControllo, Utility.FormatoData.AAAAmmGG) : null;
                                if (dataCompare.HasValue && Utility.DataStrettamenteSuccessivaA(decorrenzaOriginaria, dataCompare.Value))
                                {
                                    messaggioVideo = string.Format("La decorrenza assegno non può essere superiore al {0:MM/yyyy}", dataCompare.Value);
                                    return false;
                                }
                            }
                            if (!AGO_VerificaDecorrenzaPensioneSuperioreVOCOOP_COOP28(decorrenzaOriginaria, azCredito, codiceBancaEsodati, siglaCategoria, out messaggioVideo))
                                return false;
                            break;
                        case "VOESO":
                            if (Utility.IsAssegnoStraordinarioDipExMonopoli(datiPensione))
                            {
                                if (!Utility.DataSuccessivaA(decorrenzaOriginaria, new DateTime(2003, 1, 1)))
                                {
                                    messaggioVideo = "La decorrenza assegno non può essere inferiore a Gennaio 2003";
                                    return false;
                                }
                                if (Utility.DataStrettamenteSuccessivaA(decorrenzaOriginaria, new DateTime(2014, 7, 1)))
                                {
                                    messaggioVideo = "La decorrenza assegno non può essere superiore a Luglio 2014";
                                    return false;
                                }
                            }
                            else if (Utility.IsAssegnoStraordinarioRiscossioneTributiErariali(datiPensione))
                            {
                                if (!Utility.DataSuccessivaA(decorrenzaOriginaria, new DateTime(2004, 2, 1)))
                                {
                                    messaggioVideo = "La decorrenza assegno non può essere inferiore a Febbraio 2004";
                                    return false;
                                }
                                if (Utility.DataStrettamenteSuccessivaA(decorrenzaOriginaria, new DateTime(2022, 1, 1)))
                                {
                                    messaggioVideo = "La decorrenza assegno non può essere superiore a Gennaio 2022";
                                    return false;
                                }
                            }
                            else if (Utility.IsAssegnoStraordinarioFerrovieDelloStato(datiPensione))
                            {
                                if (!Utility.DataSuccessivaA(decorrenzaOriginaria, new DateTime(2009, 7, 1)))
                                {
                                    messaggioVideo = "La decorrenza assegno non può essere inferiore a Luglio 2009";
                                    return false;
                                }
                                if (Utility.DataStrettamenteSuccessivaA(decorrenzaOriginaria, new DateTime(2018, 12, 1)))
                                {
                                    messaggioVideo = "La decorrenza assegno non può essere superiore a Dicembre 2018";
                                    return false;
                                }
                            }
                            else if (Utility.IsAssegnoStraordinarioFerrovieDelloStatoSolidaristico(datiPensione))
                            {
                                if (!Utility.DataSuccessivaA(decorrenzaOriginaria, new DateTime(2019, 2, 1)))
                                {
                                    messaggioVideo = "La decorrenza assegno non può essere inferiore a Febbraio 2019";
                                    return false;
                                }
                            }

                            if (!AGO_VerificaDecorrenzaPensioneSuperioreVOESO(decorrenzaOriginaria, azVOESO, codiceBancaEsodati, siglaCategoria, out messaggioVideo))
                                return false;
                            break;
                        case "VOCRED":
                            if (!Utility.DataSuccessivaA(decorrenzaOriginaria, new DateTime(2000, 1, 1)))
                            {
                                messaggioVideo = "La decorrenza assegno non può essere inferiore a Gennaio 2000";
