                            }
                            if (!Utility.IsRicostituzioneOrRiapertura(datiPensione, isRiaperturaDomanda) && !Utility.DataStrettamenteSuccessivaA(new DateTime(2017, 1, 1), decorrenzaOriginaria))
                            {
                                messaggioVideo = "La decorrenza assegno non può essere superiore a Dicembre 2016";
