                            }
                            //Se la Categoria (RACATEG) è = a “VOCRED” e il Codice Banca
                            //(RACODBAN4) è = a 500 la Decorrenza Originaria (RAU104) non può
                            //essere inferiore a febbraio 2011
                            if (datiPensione.CodiceBancaEsodati.HasValue && datiPensione.CodiceBancaEsodati.Value == 500)
                            {
                                if (!Utility.DataSuccessivaA(decorrenzaOriginaria, new DateTime(2011, 2, 1)))
                                {
                                    messaggioVideo = "La decorrenza assegno non può essere inferiore a Febbraio 2011";
                                    return false;
                                }
                            }

                            if (!AGO_VerificaDecorrenzaPensioneSuperioreVOCRED_CRED27(decorrenzaOriginaria, azCredito, codiceBancaEsodati, siglaCategoria, out messaggioVideo))
                                return false;
                            break;
                        case "CRED27":
                            if (Utility.IsDomandaQuota100CRED27(datiPensione))
                            {
                                if (!Utility.DataSuccessivaA(decorrenzaOriginaria, new DateTime(2019, 2, 1)))
                                {
                                    messaggioVideo = "La decorrenza non può essere inferiore a 02/2019.";
                                    return false;
                                }
                                if (Utility.DataStrettamenteSuccessivaA(decorrenzaOriginaria, new DateTime(2022, 1, 1)))
                                {
                                    messaggioVideo = "La decorrenza non può essere strettamente successiva a 01/2022.";
                                    return false;
                                }
                            }
                            else
                            {
                                if (!Utility.DataSuccessivaA(decorrenzaOriginaria, new DateTime(2017, 1, 1)))
                                {
                                    messaggioVideo = "La decorrenza assegno non può essere inferiore a Gennaio 2017.";
                                    return false;
                                }

                                GestioneControlliDinamici.GetControlloDinamicoByNomeControllo("DecorrenzaSuperioreCRED27", out ctrl);
                                dataCompare = ctrl != null ? Utility.DataFromString(ctrl.ValoreControllo, Utility.FormatoData.AAAAmmGG) : null;
                                if (dataCompare.HasValue && Utility.DataStrettamenteSuccessivaA(decorrenzaOriginaria, dataCompare.Value))
                                {
                                    messaggioVideo = string.Format("La decorrenza assegno non può essere superiore al {0:MM/yyyy}", dataCompare.Value);
                                    return false;
                                }
                            }
                            if (!AGO_VerificaDecorrenzaPensioneSuperioreVOCRED_CRED27(decorrenzaOriginaria, azCredito, codiceBancaEsodati, siglaCategoria, out messaggioVideo))
                                return false;
                            break;
                        //Se la Categoria (RACATEG) è = a “VDAI”, “IDAI” la Decorrenza Originaria
                        //(RAU104) non può essere inferiore a gennaio 1997
                        case "VDAI":
                        case "IDAI":
                            if (!GestioneBypassControllo.CheckBypassControlloByNomeBypass(datiPensione, GestioneBypassControllo.NomeBypass.Titolare_Anagrafica_AGO.BYPASS_ANTE96_BANC_AGO))
                            {
                                if ((!Utility.DataSuccessivaA(decorrenzaOriginaria, new DateTime(1997, 1, 1))) && !(Utility.IsRicostituzione(datiPensione.Gruppo) && (datiGenericiAgoCi.DataAssunzioneCarico.HasValue && !Utility.DataSuccessivaA(datiGenericiAgoCi.DataAssunzioneCarico.Value, new DateTime(2003, 12, 1)))))
                                {
                                    messaggioVideo = "La decorrenza originaria non può essere inferiore a Gennaio 1997";
                                    return false;
                                }
                            }
                            break;
                        //Se la Categoria (RACATEG) è = a “SDAI”e il Campo DO-NOTE è diverso da
                        //“DAI” la Decorrenza Originaria (RAU104) non può essere inferiore a gennaio
                        //1997
                        case "SDAI":
                            if (!GestioneBypassControllo.CheckBypassControlloByNomeBypass(datiPensione, GestioneBypassControllo.NomeBypass.Titolare_Anagrafica_AGO.BYPASS_ANTE96_BANC_AGO))
                            {
                                if (filtro != "DAI")
                                {
                                    if ((!Utility.DataSuccessivaA(decorrenzaOriginaria, new DateTime(1997, 1, 1))) && !(Utility.IsRicostituzione(datiPensione.Gruppo) && (datiGenericiAgoCi.DataAssunzioneCarico.HasValue && !Utility.DataSuccessivaA(datiGenericiAgoCi.DataAssunzioneCarico.Value, new DateTime(2003, 12, 1)))))
                                    {
                                        messaggioVideo = "La decorrenza originaria non può essere inferiore a Gennaio 1997";
