                                //da “0” la Decorrenza Originaria (RAU104) non può essere inferiore a gennaio
                                //1998
                                if (tipoDomanda.HasValue && tipoDomanda.Value != 0)
                                {
                                    if (!Utility.DataSuccessivaA(decorrenzaOriginaria, new DateTime(1998, 1, 1)))
