                            break;
                        //Se la Categoria (RACATEG) è = a “VOTOT”, “IOTOT” la Decorrenza
                        //Originaria (RAU104) non può essere inferiore a febbraio 2006
                        case "VOTOT":
                        case "IOTOT":
                            if (!Utility.DataSuccessivaA(decorrenzaOriginaria, new DateTime(2006, 2, 1)))
                            {
                                messaggioVideo = "La decorrenza originaria non può essere inferiore a Febbraio 2006";
                                return false;
                            }

                            //Se la Categoria (RACATEG) è = a “VOTOT” e PANVEIN = "1" la Decorrenza Originaria
                            //(RAU104) deve essere maggiore della Data della Domanda (RAUE24)
                            //if (siglaCategoria == "VOTOT")
                            //{
                            //    //controllo tra data presentazione e decorrenza pensione. Il controllo va bypassato quando si è in presenza di ricostituzioni
                            //    //riferimento mail: RE: Reeng Pensioni AGO - Segnalazioni Ricostituzioni
                            //    if (tipologiaDomanda != Utility.TipoDomanda.Ricostituzione && tipologiaDomanda != Utility.TipoDomanda.Ripristino && tipologiaDomanda != Utility.TipoDomanda.RipristinoSuperstiti)
                            //    {
                            //        if ((Utility.IsDomandaInabilitaAmianto(datiPensione) ? !Utility.DataStrettamenteSuccessivaA(decorrenzaOriginaria, new DateTime(datiPensione.DataPresentazioneDomanda.Year, datiPensione.DataPresentazioneDomanda.Month, 1)) :
                            //            !Utility.DataSuccessivaA(decorrenzaOriginaria, new DateTime(datiPensione.DataPresentazioneDomanda.Year, datiPensione.DataPresentazioneDomanda.Month, 1))) &&
                            //            codNat1 != '1' && codNat1 != '2' && codNat1 != '3' && codNat1 != '4')
                            //        {
                            //            messaggioVideo = "La decorrenza originaria deve essere maggiore della data di presentazione";
                            //            return false;
                            //        }
                            //    }
                            //}
                            break;
                        case "SOTOT":
                            if (!GestioneBypassControllo.CheckAndLockBypassControlloByNomeBypass(datiPensione, GestioneBypassControllo.NomeBypass.Titolare_Anagrafica_AGO.BYPASS_DEC_TOT))
                            {
                                //Se la Categoria (RACATEG) è = a “SOTOT” ed è presente il Certificato della
                                //Diretta (DAUE12) la Decorrenza Originaria (RAU104) non può essere
                                //inferiore a marzo 2006
                                if (datiDanteCausa != null && datiDanteCausa.Certificato.HasValue && datiDanteCausa.Certificato.Value != 0)
                                {
                                    if (!Utility.DataSuccessivaA(decorrenzaOriginaria, new DateTime(2006, 3, 1)))
                                    {
                                        messaggioVideo = "La decorrenza originaria non può essere inferiore a Marzo 2006";
                                        return false;
                                    }
                                }
                                //Se la Categoria (RACATEG) è = a “SOTOT” e non è presente il Certificato
                                //della Diretta (DAUE12) la Decorrenza Originaria (RAU104) non può essere
                                //inferiore ad aprile 2006
                                else
                                {
                                    if (!Utility.DataSuccessivaA(decorrenzaOriginaria, new DateTime(2006, 4, 1)))
                                    {
                                        messaggioVideo = "La decorrenza originaria non può essere inferiore ad Aprile 2006";
                                        return false;
                                    }
                                }
                            }
                            break;
                        case "INDCOM":
                            if (tipologiaDomanda != Utility.TipoDomanda.Ricostituzione && tipologiaDomanda != Utility.TipoDomanda.Ripristino && tipologiaDomanda != Utility.TipoDomanda.RipristinoSuperstiti)
                            {
                                //Se la Categoria (RACATEG) è = a “INDCOM” e il Campo DO-NOTE è = a
                                //“VIC” la Decorrenza Originaria (RAU104) deve essere compresa tra maggio
                                //1996 e dicembre 2000
                                if (Utility.IsDomandaINDCOM124(datiPensione) || filtro == "VIC") //Tipo 124
                                {
                                    if (!Utility.DataSuccessivaA(decorrenzaOriginaria, new DateTime(1996, 2, 1)))
                                    {
