                                        return false;
                                    }
                                    if (Utility.DataStrettamenteSuccessivaA(decorrenzaOriginaria, new DateTime(1998, 12, 1)))
                                    {
                                        messaggioVideo = "La decorrenza originaria non può essere superiore a Dicembre 1998";
                                        return false;
                                    }
                                }
                                //Se la Categoria (RACATEG) è = a “INDCOM” e il Campo DO-NOTE è = a
                                //“NIC” la Decorrenza Originaria (RAU104) deve essere compres tra febbraio
                                //2009 e febbraio 2012
                                else if (Utility.IsDomandaINDCOM129(datiPensione) || filtro == "NIC") //Tipo 129
                                {
                                    if (!Utility.DataSuccessivaA(decorrenzaOriginaria, new DateTime(2009, 2, 1)))
                                    {
                                        messaggioVideo = "La decorrenza originaria non può essere inferiore a Febbraio 2009";
