                                        messaggioVideo = "La decorrenza originaria non può essere superiore a Febbraio 2012";
                                        return false;
                                    }
                                }
                                else if (Utility.IsDomandaINDCOM156(datiPensione) || filtro == "LPP") //Tipo 156
                                {

                                    if (!Utility.DataSuccessivaA(decorrenzaOriginaria, new DateTime(2014, 2, 1)))
                                    {
                                        messaggioVideo = "La decorrenza originaria non può essere inferiore a Febbraio 2014";
