                                    }
                                    if (Utility.DataStrettamenteSuccessivaA(decorrenzaOriginaria, new DateTime(2017, 2, 1)))
                                    {
                                        messaggioVideo = "La decorrenza originaria non può essere superiore a Febbraio 2017";
