                                }
                                //Se la Categoria (RACATEG) è = a “INDCOM” e il Campo DO-NOTE è
                                //diverso da “VIC”, “NIC” la Decorrenza Originaria (RAU104) deve essere
                                //compresa tra febbraio 2002 e febbraio 2008
                                else
                                {
                                    //Tipo 175 e 125
                                    if (!Utility.DataSuccessivaA(decorrenzaOriginaria, new DateTime(2002, 2, 1)))
                                    {
                                        messaggioVideo = "La decorrenza originaria non può essere inferiore a Febbraio 2002";
                                        return false;
                                    }
                                    if (Utility.IsDomandaINDCOM175(datiPensione))
                                    {
                                        if (!Utility.DataSuccessivaA(decorrenzaOriginaria, new DateTime(2019, 2, 1)))
                                        {
                                            messaggioVideo = "La decorrenza originaria non può essere inferiore a Febbraio 2019";
                                            return false;
                                        }
                                    }
                                    else if (Utility.DataStrettamenteSuccessivaA(decorrenzaOriginaria, new DateTime(2008, 2, 1)))
                                    {
                                        messaggioVideo = "La decorrenza originaria non può essere superiore a Febbraio 2008";
                                        return false;
