                                }
                                //Se la Categoria (RACATEG) è = a “INDCOM” la Decorrenza Originaria
                                //(RAU104) deve essere maggiore della Data della Domanda (RAUE24)

                                if (Utility.IsDomandaInabilitaAmianto(datiPensione) ? !Utility.DataStrettamenteSuccessivaA(decorrenzaOriginaria, new DateTime(datiPensione.DataPresentazioneDomanda.Year, datiPensione.DataPresentazioneDomanda.Month, 1)) :
                                    !Utility.DataStrettamenteSuccessivaSenzaGiorno(decorrenzaOriginaria, new DateTime(datiPensione.DataPresentazioneDomanda.Year, datiPensione.DataPresentazioneDomanda.Month, 1)))
                                {
                                    messaggioVideo = "La decorrenza originaria deve essere maggiore della data di presentazione";
                                    return false;
                                }
                            }
                            break;
                        case "VOSPED":
                            //Se la Categoria (RACATEG) è = a “VOSPED”
                            //Decorrenza Originaria (RAU104) non può essere inferiore a gennaio 1998   
                            //Se la Categoria (RACATEG) è = a “VOSPED” la Decorrenza Originaria
                            //(RAU104) deve essere maggiore della Data della Domanda (RAUE24)
                            if (tipologiaDomanda != Utility.TipoDomanda.Ricostituzione && tipologiaDomanda != Utility.TipoDomanda.Ripristino && tipologiaDomanda != Utility.TipoDomanda.RipristinoSuperstiti)
                            {
                                if (!Utility.DataSuccessivaA(decorrenzaOriginaria, new DateTime(1998, 1, 1)))
                                {
                                    messaggioVideo = "La decorrenza originaria non può essere inferiore a Gennaio 1998";
                                    return false;
                                }

                                if (Utility.IsDomandaInabilitaAmianto(datiPensione) ? !Utility.DataStrettamenteSuccessivaA(decorrenzaOriginaria, new DateTime(datiPensione.DataPresentazioneDomanda.Year, datiPensione.DataPresentazioneDomanda.Month, 1)) :
                                    !Utility.DataSuccessivaA(decorrenzaOriginaria, new DateTime(datiPensione.DataPresentazioneDomanda.Year, datiPensione.DataPresentazioneDomanda.Month, 1)))
                                {
                                    messaggioVideo = "La decorrenza originaria deve essere maggiore della data di presentazione";
                                    return false;
                                }
                            }
                            break;
                        case "SOSPED":
                        case "IOSPED":
                            if (tipologiaDomanda != Utility.TipoDomanda.Ricostituzione && tipologiaDomanda != Utility.TipoDomanda.Ripristino && tipologiaDomanda != Utility.TipoDomanda.RipristinoSuperstiti)
                            {
                                var dataConfronto = (Utility.IsDomandaReversibilita(datiPensione) && datiDanteCausa != null && datiDanteCausa.DecorrenzaPensione.HasValue) ? datiDanteCausa.DecorrenzaPensione.Value : decorrenzaOriginaria;

                                if (!Utility.DataSuccessivaA(dataConfronto, new DateTime(1998, 1, 1)))
                                {
                                    messaggioVideo = "La decorrenza originaria non può essere inferiore a Gennaio 1998";
                                    return false;
                                }
                            }
                            break;
                        case "VOBIS":
                        case "IOBIS":
                        case "VMP":
                        case "IMP":
                            if (tipologiaDomanda != Utility.TipoDomanda.Ricostituzione && tipologiaDomanda != Utility.TipoDomanda.Ripristino && tipologiaDomanda != Utility.TipoDomanda.RipristinoSuperstiti)
                            {
                                if (!Utility.DataStrettamenteSuccessivaA(decorrenzaOriginaria, datiPensione.DataPresentazioneDomanda))
                                {
                                    messaggioVideo = "La decorrenza originaria deve essere strettamente successiva alla data di presentazione ";
                                    return false;
                                }
                            }
                            break;
                        //Se la Categoria (RACATEG) è = a “IOAUT”
                        //la Decorrenza Originaria (RAU104) deve essere successiva alla Data della
                        //Domanda (RAU24)
                        case "IOAUT":
                            if (tipologiaDomanda != Utility.TipoDomanda.Ricostituzione && tipologiaDomanda != Utility.TipoDomanda.Ripristino && tipologiaDomanda != Utility.TipoDomanda.RipristinoSuperstiti)
                            {
                                if (!Utility.DataSuccessivaA(decorrenzaOriginaria, new DateTime(datiPensione.DataPresentazioneDomanda.Year, datiPensione.DataPresentazioneDomanda.Month, 1)))
                                {
                                    messaggioVideo = "La decorrenza originaria deve essere successiva alla data di presentazione";
                                    return false;
                                }
