                                    {
                                        if (Utility.IsDomandaAUTAnticipataInComputo(datiPensione, false) && dataPerfReq.HasValue && Utility.DataStrettamenteSuccessivaA(dataCondizioniPerComputo.Value, dataPerfReq.Value)
