                            {
                                if (!Utility.DataSuccessivaA(decorrenzaOriginaria, new DateTime(2019, 2, 1)))
                                {
                                    messaggioVideo = "La decorrenza non può essere inferiore a 02/2019.";
                                    return false;
                                }
                                if (Utility.DataStrettamenteSuccessivaA(decorrenzaOriginaria, new DateTime(2022, 1, 1)))
                                {
                                    messaggioVideo = "La decorrenza non può essere strettamente successiva a 01/2022.";
                                    return false;
                                }
                            }
                            else
                            {
                                if (!Utility.DataSuccessivaA(decorrenzaOriginaria, new DateTime(2011, 2, 1)))
