                                    messaggioVideo = "La decorrenza non può essere inferiore a 02/2011.";
                                    return false;
                                }
                            }
                            if (!AGO_VerificaDecorrenzaPensioneSuperioreVESO33(decorrenzaOriginaria, azVESO33, codiceBancaEsodati, siglaCategoria, out messaggioVideo))
                                return false;
                            break;
                        case "APE":
                            if (!AGO_VerificaDecorrenzaPensioneAPESociale(decorrenzaOriginaria, datiAnagraficiTitolare, siglaCategoria, datiPensione, out messaggioVideo))
                                return false;
                            break;
                        case "ESOTEL":
                            if (Utility.IsDomandaQuota100ESOTEL(datiPensione))
                            {
                                if (Utility.DataStrettamenteSuccessivaA(decorrenzaOriginaria, new DateTime(2022, 4, 1)))
                                {
                                    messaggioVideo = "La decorrenza non può essere strettamente successiva a 04/2022.";
                                    return false;
                                }

                            }
                            if (!Utility.DataSuccessivaA(decorrenzaOriginaria, new DateTime(2023, 10, 1)))
                            {
                                messaggioVideo = "La decorrenza assegno non può essere inferiore a 10/2023.";
                                return false;
                            }

                            if (!AGO_VerificaDecorrenzaPensioneSuperioreESOTEL(decorrenzaOriginaria, azESOTEL, codiceBancaEsodati, siglaCategoria, out messaggioVideo))
                                return false;
                            break;
                        case "ESOAMB":
                            if (Utility.IsDomandaQuota100ESOAMB(datiPensione))
                            {
                                if (Utility.DataStrettamenteSuccessivaA(decorrenzaOriginaria, new DateTime(2022, 4, 1)))
                                {
                                    messaggioVideo = "La decorrenza non può essere strettamente successiva a 04/2022.";
                                    return false;
                                }
                            }

                            if (!Utility.DataSuccessivaA(decorrenzaOriginaria, new DateTime(2019, 11, 1)))
                            {
                                messaggioVideo = "La decorrenza assegno non può essere inferiore a 11/2019.";
                                return false;
                            }

                            if (!AGO_VerificaDecorrenzaPensioneSuperioreESOAMB(decorrenzaOriginaria, azESOAMB, codiceBancaEsodati, siglaCategoria, out messaggioVideo))
                                return false;
                            break;
                        case "ESPA":
                            if (!Utility.DataSuccessivaA(decorrenzaOriginaria, new DateTime(2021, 1, 1)))
                            {
                                messaggioVideo = "La decorrenza assegno non può essere inferiore a 01/2021.";
                                return false;
                            }
                            break;
                        case "VOBANC":
                        case "IOBANC":
                        case "SOBANC":
                            if (!Utility.IsRicostituzioneOrRiapertura(datiPensione, isRiaperturaDomanda))
                            {
                                //bool isRipristino = (bool)Utility.IsDomandaRipristino(datiPensione);
                                if ((ConfigurationManager.AppSettings["BypassDecorrenzaRipristinoBanc"] == null || ConfigurationManager.AppSettings["BypassDecorrenzaRipristinoBanc"] != "SI") &&
                                    isRipristino && (Utility.IsDomandaVOBANC(datiPensione.SiglaCategoria) || Utility.IsDomandaIOBANC(datiPensione.SiglaCategoria)) && Utility.DataStrettamenteSuccessivaA(decorrenzaOriginaria, new DateTime(2010, 12, 31)))
                                {
                                    messaggioVideo = "La pensione deve essere riliquidata nell'assicurazione generale obbligatoria";
                                    return false;
                                }
                                if (Utility.DataStrettamenteSuccessivaA(decorrenzaOriginaria, new DateTime(2010, 12, 1)) && !isRipristino)
                                {
                                    messaggioVideo = "Categoria non più in uso dal 1/1/2011, contribuzione enti creditizi gestita come FPLD. Nuova domanda da processare in Unicarpe";
                                    return false;
                                }
                                if (!Utility.DataSuccessivaA(decorrenzaOriginaria, new DateTime(1991, 1, 1)))
                                {
                                    messaggioVideo = "La decorrenza non può essere inferiore a 01/1991.";
                                    return false;
                                }
                            }
                            break;
                        case "PSO":
                            var cert3byte = datiPensioneUI.NCertificato != null ? datiPensioneUI.NCertificato.ToString().PadLeft(8, '0').Substring(2, 1) : "";
                            if (tipologiaDomanda != Utility.TipoDomanda.Ricostituzione && tipologiaDomanda != Utility.TipoDomanda.Ripristino && tipologiaDomanda != Utility.TipoDomanda.RipristinoSuperstiti && !isRiaperturaDomanda
                                && cert3byte != "3" && cert3byte != "6")
                            {
                                if (!Utility.DataStrettamenteSuccessivaA(decorrenzaOriginaria, datiPensione.DataPresentazioneDomanda))
                                {
                                    messaggioVideo = "La decorrenza originaria deve essere strettamente successiva alla data di presentazione";
                                    return false;
                                }
                            }
                            break;
                        case "ESOPMI":
                            if (!Utility.DataSuccessivaA(decorrenzaOriginaria, new DateTime(2022, 11, 1)))
                            {
                                messaggioVideo = "La decorrenza assegno non può essere inferiore a 11/2022.";
                                return false;
                            }
                            if (Utility.DataSuccessivaA(decorrenzaOriginaria, new DateTime(2024, 12, 31)))
                            {
                                messaggioVideo = "La decorrenza assegno non può essere superiore a 12/2024.";
                                return false;
                            }
                            break;
                        default:
                            break;
                    }
                }

                switch (filtro)
                {
                    //Se il Campo DO-NOTE è = a “UAA” o “UAM” la Decorrenza Originaria
                    //(RAU104) non può essere inferiore a giugno 2011
                    case "UAA":
                    case "UAM":
                        if (!Utility.DataSuccessivaA(decorrenzaOriginaria, new DateTime(2011, 6, 1)))
                        {
                            messaggioVideo = "La decorrenza originaria non può essere inferiore a Giugno 2011";
                            return false;
                        }
                        break;
                    case "CDP":
                        //Se il Campo DO-NOTE è = a “CDP” e la Categoria (RACATEG) è = a “VO” la
                        //Decorrenza Originaria (RAU104) non può essere inferiore a gennaio 2004
                        if (siglaCategoria == "VO")
                        {
                            if (!Utility.DataSuccessivaA(decorrenzaOriginaria, new DateTime(2004, 1, 1)))
                            {
                                messaggioVideo = "La decorrenza originaria non può essere inferiore a Gennaio 2004";
                                return false;
                            }
                        }
                        //Se il Campo DO-NOTE è = a “CDP” e la Categoria (RACATEG) è = a “SO” la
                        //Decorrenza della diretta (DAU106) non può essere inferiore a gennaio 2004
                        if (siglaCategoria == "SO" && datiDanteCausa != null && datiDanteCausa.DecorrenzaPensione.HasValue)
                        {
                            if (!Utility.DataSuccessivaA(datiDanteCausa.DecorrenzaPensione.Value, new DateTime(2004, 1, 1)))
                            {
                                messaggioVideo = "La decorrenza della diretta non può essere inferiore a Gennaio 2004";
                                return false;
                            }
                        }
                        break;
                    //Se il Campo DO-NOTE è = “DAI” la Decorrenza Originaria (RAU104) non
                    //può essere inferiore a febbraio 2002
                    case "DAI":
                        if (!Utility.DataSuccessivaA(decorrenzaOriginaria, new DateTime(2002, 2, 1)))
                        {
                            messaggioVideo = "La decorrenza originaria non può essere inferiore a Febbraio 2002";
                            return false;
                        }
                        break;
                    //Se il Campo DO-NOTE è = “SUT” la Decorrenza Originaria (RAU104) non
                    //può essere inferiore a febbraio 1996
                    case "SUT":
                        if (!Utility.DataSuccessivaA(decorrenzaOriginaria, new DateTime(1996, 2, 1)))
                        {
                            messaggioVideo = "La decorrenza originaria non può essere inferiore a Febbraio 1996";
                            return false;
                        }
                        break;
                    case "ERI":
                        //Se il Campo DO-NOTE è = “ERI” la Decorrenza Originaria (RAU104) non
                        //può essere inferiore a ottobre 2002
                        if (!Utility.DataSuccessivaA(decorrenzaOriginaria, new DateTime(2002, 10, 1)))
                        {
                            messaggioVideo = "La decorrenza originaria non può essere inferiore a Ottobre 2002";
                            return false;
                        }
                        //Se il Campo DO-NOTE è = “ERI” la Decorrenza Originaria (RAU104) non
                        //può essere inferiore alla Data Residenza Estera (DATA-RES-ESTERO)
                        List<GestioneAnagrafica.DatiResidenzaEstero> elencoResEstere = null;
                        GestioneAnagrafica.GetResidenzeEstereByIdPensione(datiPensione.Id, out elencoResEstere);
                        if (elencoResEstere != null && elencoResEstere.Count > 0)
                        {
                            elencoResEstere.Sort((x, y) => DateTime.Compare(x.Decorrenza.Value, y.Decorrenza.Value));
                            if (!Utility.DataSuccessivaA(decorrenzaOriginaria, elencoResEstere[0].Decorrenza.Value))
                            {
                                messaggioVideo = "La decorrenza originaria non può essere inferiore alla data residenza estera";
                                return false;
                            }
                        }
                        break;
                    //Se il Campo DO-NOTE è = “RAL”, “R22”, R23”, “R24”, “R25”, “R44”, “R45”
                    //de il campo DAU107 è = a zero la Decorrenza Originaria (RAU104) non può
                    //essere inferiore a febbraio 2008
                    case "RAL":
                    case "R22":
                    case "R23":
                    case "R24":
                    case "R25":
                    case "R44":
                    case "R45":
                        if (datiDanteCausa == null || !datiDanteCausa.ProvenienzaPensione.HasValue || datiDanteCausa.ProvenienzaPensione.Value == 0)
                        {
                            if (!Utility.DataSuccessivaA(decorrenzaOriginaria, new DateTime(2008, 2, 1)))
                            {
                                messaggioVideo = "La decorrenza originaria non può essere inferiore a Febbraio 2008";
                                return false;
                            }
                        }
                        //Se il Campo DO-NOTE è = “RAL”, “R22”, R23”, “R24”, “R25”, “R44”, “R45”
                        //de il campo DAU107 è diverso a zero la Decorrenza Originaria (RAU104)
                        //non può essere inferiore a marzo 2008
                        if (datiDanteCausa != null && datiDanteCausa.ProvenienzaPensione.HasValue && datiDanteCausa.ProvenienzaPensione.Value != 0)
                        {
                            if (!Utility.DataSuccessivaA(decorrenzaOriginaria, new DateTime(2008, 3, 1)))
                            {
                                messaggioVideo = "La decorrenza originaria non può essere inferiore a Marzo 2008";
                                return false;
                            }
                        }
                        break;
                    //Se il Campo DO-NOTE è = “CSL”, “SSA”, “SSM” e la Categoria (RACATEG)
                    //è = a “VO”, “VDAI” la Decorrenza Originaria (RAU104) non può essere
                    //inferiore a gennaio 2009
                    case "CSL":
                    case "SSA":
                    case "SSM":
                        if (siglaCategoria == "VO" || siglaCategoria == "VDAI")
                        {
                            if (!Utility.DataSuccessivaA(decorrenzaOriginaria, new DateTime(2009, 1, 1)))
                            {
                                messaggioVideo = "La decorrenza originaria non può essere inferiore a Gennaio 2009";
                                return false;
                            }
                        }
                        //Se il Campo DO-NOTE è = “CSL”, “SSA”, “SSM” e la Categoria (RACATEG)
                        //è diversa da “VO”, “VDAI” la Decorrenza Originaria (RAU104) non può
                        //essere inferiore a luglio 2009
                        else
                        {
                            if (!Utility.DataSuccessivaA(decorrenzaOriginaria, new DateTime(2009, 7, 1)))
                            {
                                messaggioVideo = "La decorrenza originaria non può essere inferiore a Luglio 2009";
                                return false;
                            }
                        }
                        //Se il Campo DO-NOTE è = “CSL”, “SSA”, “SSM” la Decorrenza Originaria
                        //(RAU104) non può essere superiore a gennaio 2017
                        if (Utility.DataStrettamenteSuccessivaA(decorrenzaOriginaria, new DateTime(2017, 1, 1)))
                        {
                            messaggioVideo = "La decorrenza originaria non può essere superiore a Gennaio 2017";
                            return false;
                        }
                        //Se il Campo DO-NOTE è = "SAA", "SAM", "SVA", "SVM", "SSA", "SSM",
                        //"STA", "STM" la Decorrenza Originaria (RAU104) non può essere inferiore a
                        //febbraio 2011
                        if (siglaCategoria == "SSA" || siglaCategoria == "SSM")
                        {
                            if (!Utility.DataSuccessivaA(decorrenzaOriginaria, new DateTime(2011, 2, 1)))
                            {
                                messaggioVideo = "La decorrenza originaria non può essere inferiore a Febbraio 2011";
                                return false;
                            }
                        }
                        break;
                    //Se il Campo DO-NOTE è = “MPA”, “MPM”, “ESO” la Decorrenza Originaria
                    //(RAU104) non può essere inferiore a luglio 2008
                    case "MPA":
                    case "MPM":
                    case "ESO":
                        if (!Utility.DataSuccessivaA(decorrenzaOriginaria, new DateTime(2008, 7, 1)))
                        {
                            messaggioVideo = "La decorrenza originaria non può essere inferiore a Luglio 2008";
                            return false;
                        }
                        break;
                    case "TRA":
                        //Se il Campo DO-NOTE è = a “TRA” la Decorrenza Originaria (RAU104) deve
                        //essere successiva alla Data della Domanda (RAU24)
                        if (tipologiaDomanda != Utility.TipoDomanda.Ricostituzione && tipologiaDomanda != Utility.TipoDomanda.Ripristino && tipologiaDomanda != Utility.TipoDomanda.RipristinoSuperstiti)
                        {
                            if (!Utility.DataSuccessivaA(decorrenzaOriginaria, new DateTime(datiPensione.DataPresentazioneDomanda.Year, datiPensione.DataPresentazioneDomanda.Month, 1)))
                            {
                                messaggioVideo = "La decorrenza originaria deve essere successiva alla data di presentazione";
                                return false;
                            }
                        }
                        break;
                    //Se il Campo DO-NOTE è = a “BNS”, “BNX” e il 1° carattere della Categoria
                    //(RACATEG) è diverso da “S” e il 1° Codice Natura (RAU1031) è diverso da
                    //spazio e “6” la Decorrenza Originaria (RAU104) deve essere successiva alla
                    //Data della Domanda (RAU24)
                    case "BNX":
                    case "BNS":
                        if (!siglaCategoria.StartsWith("S") && codNat1 != ' ' && codNat1 != '6')
                        {
                            if (tipologiaDomanda != Utility.TipoDomanda.Ricostituzione && tipologiaDomanda != Utility.TipoDomanda.Ripristino && tipologiaDomanda != Utility.TipoDomanda.RipristinoSuperstiti)
                            {
                                if (!Utility.DataSuccessivaA(decorrenzaOriginaria, new DateTime(datiPensione.DataPresentazioneDomanda.Year, datiPensione.DataPresentazioneDomanda.Month, 1)))
                                {
                                    messaggioVideo = "La decorrenza originaria deve essere successiva alla data di presentazione";
                                    return false;
                                }
                            }
                        }
                        //Se il Campo DO-NOTE è = a “BNS”, “BNX” e il 1° carattere della Categoria
                        //(RACATEG) è uguale a “S” la Decorrenza Originaria (RAU104) deve essere successiva alla data di fine Bonus
                        if (siglaCategoria.StartsWith("S"))
                        {
                            GestioneDatiControlloFelpe.ControlloFelpe controlloFelpe = null;
                            GestioneDatiControlloFelpe.GetDatiControlloFelpeByIdPensione(datiPensione.Id, out controlloFelpe);
                            if (controlloFelpe != null && controlloFelpe.FineBonus.HasValue)
                            {
                                if (!Utility.DataSuccessivaA(decorrenzaOriginaria, controlloFelpe.FineBonus.Value))
                                {
                                    messaggioVideo = "La decorrenza originaria deve essere successiva alla data di fine bonus";
                                    return false;
                                }
                            }
                        }
                        break;
                    //Se il Campo DO-NOTE è = "SAA", "SAM", "SVA", "SVM", "SSA", "SSM",
                    //"STA", "STM" la Decorrenza Originaria (RAU104) non può essere inferiore a
                    //febbraio 2011
                    case "SAA":
                    case "SAM":
                    case "SVA":
                    case "SVM":
                    case "STA":
                    case "STM":
                    default:
                        break;
                }

                if (dataPerfReq.HasValue)
                {
                    //20151029 - Per le categorie VESO92 e VESO33 la data perfezionamento dei requisiti deve essere superiore alla decorrenzaPensione
                    //20170303 - Per le categorie VOCRED, CRED27, VOCOOP, COOP28 la data perfezionamento dei requisiti deve essere superiore alla decorrenzaPensione
                    //20171102 - Per COMPARTO_SCUOLA bypassate salto il controllo AGO_VerificaDecorrenzaPensione
                    if (!Utility.IsDomandaCumulo(datiPensione.SiglaCategoria) && !Utility.IsDomandaVESO33(datiPensione.SiglaCategoria) &&
                        !Utility.IsDomandaVESO92(datiPensione.SiglaCategoria) && !Utility.IsDomandaVOCOOP_COOP28(datiPensione.SiglaCategoria) &&
                        !Utility.IsDomandaVOCRED_CRED27(datiPensione.SiglaCategoria) && !Utility.IsDomandaVESO29(datiPensione.SiglaCategoria) &&
                        !Utility.IsDomandaVOESO(datiPensione.SiglaCategoria) && !Utility.IsDomandaESOTEL(datiPensione.SiglaCategoria) &&
                        !Utility.IsDomandaESOAMB(datiPensione.SiglaCategoria) && !Utility.IsDomandaESPA(datiPensione.SiglaCategoria) &&
                        !(Utility.IsRicostituzione(datiPensione.Gruppo) && datiPensione.SiglaCategoria.StartsWith("S")))
                    {
                        //La Decorrenza Originaria (RAU104) non può essere inferiore alla Data
                        //Perfezionamento Requisito (PERFREQ)
                        if (!Utility.DataStrettamenteSuccessivaA(decorrenzaOriginaria, new DateTime(dataPerfReq.Value.Year, dataPerfReq.Value.Month, 1)))
                        {
                            messaggioVideo = "La decorrenza originaria non può essere inferiore o uguale alla data perfezionamento requisito";
                            return false;
                        }
                    }
                    //Se il Campo DO-NOTE è = a “UAM” e la Categoria (RACATEG) è = a “VR”,
                    //“VOART”, “VOCOM” la Decorrenza Originaria (RAU104) deve essere
                    //superiore di 18 mesi la Data Perfezionamento Requisito (PERFREQ)
                    if (filtro == "UAM" && (siglaCategoria == "VR" || siglaCategoria == "VOART" || siglaCategoria == "VOCOM"))
                    {
                        if (!Utility.DataStrettamenteSuccessivaA(new DateTime(dataPerfReq.Value.Year, dataPerfReq.Value.Month, 1).AddMonths(18), new DateTime(2017, 1, 1)))
                        {
                            if (!Utility.DataStrettamenteSuccessivaA(decorrenzaOriginaria, new DateTime(dataPerfReq.Value.Year, dataPerfReq.Value.Month, 1).AddMonths(18)))
                            {
                                messaggioVideo = "La decorrenza originaria deve essere superiore di 18 mesi la data perfezionamento requisito";
                                return false;
                            }
                        }
                        else
                        {
                            if (!Utility.DataSuccessivaA(decorrenzaOriginaria, new DateTime(2017, 1, 1)))
                            {
                                messaggioVideo = "La decorrenza originaria deve essere superiore o uguale al 01/2017";
                                return false;
                            }
                        }
                    }
                    //Se il Campo DO-NOTE è = a “UAM” e la Categoria (RACATEG) è diversa da
                    //“VR”, “VOART”, “VOCOM” la Decorrenza Originaria (RAU104) deve essere
                    //superiore di 12 mesi la Data Perfezionamento Requisito (PERFREQ)
                    if (filtro == "UAM" && (siglaCategoria != "VR" && siglaCategoria != "VOART" && siglaCategoria != "VOCOM"))
                    {
                        if (!Utility.DataStrettamenteSuccessivaA(new DateTime(dataPerfReq.Value.Year, dataPerfReq.Value.Month, 1).AddMonths(12), new DateTime(2017, 1, 1)))
                        {
                            if (!Utility.DataStrettamenteSuccessivaA(decorrenzaOriginaria, new DateTime(dataPerfReq.Value.Year, dataPerfReq.Value.Month, 1).AddMonths(12)))
                            {
                                messaggioVideo = "La decorrenza originaria deve essere superiore di 12 mesi la data perfezionamento requisito";
                                return false;
                            }
                        }
                        else
                        {
                            if (!Utility.DataSuccessivaA(decorrenzaOriginaria, new DateTime(2017, 1, 1)))
                            {
                                messaggioVideo = "La decorrenza originaria deve essere superiore o uguale al 01/2017";
                                return false;
                            }
                        }
                    }
                }

                //Se è presente la Data Eliminazione (RADECELIM) la Decorrenza Originaria
                //(RAU104) deve essere almeno il mese precedente la Data Eliminazione
                //(RDECELIM)
                if (datiEliminazione != null && datiEliminazione.DecorrenzaEliminazione.HasValue)
                {
                    GestioneControlliDinamici.ControlloDinamico controlloDinamico = null;
                    GestioneControlliDinamici.GetControlloDinamicoByNomeControllo("AbilitazioneMemo102", out controlloDinamico);

                    DateTime decorrenzaOriginariaCompare = decorrenzaOriginaria;
                    if (Utility.IsDomandaPensioneInabilita(datiPensione) && Utility.IsDomandaCumulo(datiPensione.SiglaCategoria) && datiPensione.Fondo == "145")
                        decorrenzaOriginariaCompare = Utility.FirstDayOfMonth(datiPensione.DecorrenzaOriginaria.GetValueOrDefault());

                    if (controlloDinamico != null && controlloDinamico.ValoreControllo == "SI")
                    {
                        if (!(!Utility.IsRicostituzioneOrRiapertura(datiPensione, isRiaperturaDomanda) &&
                        (Utility.IsDomandaVOESO(datiPensione.SiglaCategoria) || Utility.IsDomandaVESO33(datiPensione.SiglaCategoria) || Utility.IsDomandaVESO92(datiPensione.SiglaCategoria) || Utility.IsDomandaVOCOOP_COOP28(datiPensione.SiglaCategoria) ||
                        Utility.IsDomandaVOCRED_CRED27(datiPensione.SiglaCategoria) || Utility.IsDomandaESPA(datiPensione.SiglaCategoria) || Utility.IsDomandaESOTEL(datiPensione.SiglaCategoria) || Utility.IsDomandaESOAMB(datiPensione.SiglaCategoria)) &&
                         datiEliminazione.CodiceMotivo == 6))
                        {
                            if (Utility.DataStrettamenteSuccessivaA(decorrenzaOriginariaCompare,
                            new DateTime(datiEliminazione.DecorrenzaEliminazione.Value.AddMonths(-1).Year, datiEliminazione.DecorrenzaEliminazione.Value.AddMonths(-1).Month, 1)))
                            {
                                messaggioVideo = "La decorrenza originaria non può essere successiva al mese precedente la decorrenza eliminazione";
                                return false;
                            }
                        }
                    }
                    else
                    {
                        if (Utility.DataStrettamenteSuccessivaA(decorrenzaOriginariaCompare,
                            new DateTime(datiEliminazione.DecorrenzaEliminazione.Value.AddMonths(-1).Year, datiEliminazione.DecorrenzaEliminazione.Value.AddMonths(-1).Month, 1)))
                        {
                            messaggioVideo = "La decorrenza originaria non può essere successiva al mese precedente la decorrenza eliminazione";
                            return false;
                        }
                    }

                }

                //Se il 3° Codice Natura (RAU1033) è = a “G” la Decorrenza Originaria
                //(RAU104) non può essere inferiore a febbraio 2002
                if (codNat3 == 'G')
                {
                    if (!Utility.DataSuccessivaA(decorrenzaOriginaria, new DateTime(2002, 2, 1)))
                    {
                        messaggioVideo = "La decorrenza originaria non può essere inferiore a Febbraio 2002";
                        return false;
                    }
                }

                //Se la Categoria (RACATEG) è = a “VOAUT”, “IOAUT” e il 1° Codice Natura
                //(RAU1031) è diverso da “5” la Decorrenza Originaria (RAU104) non può
                //essere inferiore ad aprile 2001
                if ((siglaCategoria == "VOAUT" || siglaCategoria == "IOAUT") && codNat1 != '5')
                {
                    if (!Utility.DataSuccessivaA(decorrenzaOriginaria, new DateTime(2001, 4, 1)))
                    {
                        messaggioVideo = "La decorrenza originaria non può essere inferiore ad Aprile 2001";
                        return false;
                    }
                }
                //Se la Categoria (RACATEG) è = a “SOAUT” e il 1° Codice Natura (RAU1031)
                //è diverso da “5” la Decorrenza Originaria (RAU104) non può essere inferiore
                //a maggio 2001
                if (siglaCategoria == "SOAUT" && codNat1 != '5')
                {
                    if (!Utility.DataSuccessivaA(decorrenzaOriginaria, new DateTime(2001, 5, 1)))
                    {
                        messaggioVideo = "La decorrenza originaria non può essere inferiore a Maggio 2001";
                        return false;
                    }
                }

                //Se il 3° Codice Natura (RAU1033) è = a “O” la Decorrenza Originaria
                //(RAU104) non può essere inferiore a 6 mesi dalla Data della Domanda
                //(RAU24)
                if ((codNat3 == 'O' && !Utility.IsRicostituzioneOrRiapertura(datiPensione, isRiaperturaDomanda)) && !isRipristino)
                {
                    DateTime? dataPresentazioneDomandaFirstDay = Utility.DataFromInt(datiPensione.DataPresentazioneDomanda.Year, datiPensione.DataPresentazioneDomanda.Month, 1);
                    if (!dataPresentazioneDomandaFirstDay.HasValue || !Utility.DataSuccessivaA(decorrenzaOriginaria, dataPresentazioneDomandaFirstDay.Value.AddMonths(-6)))
                    {
                        messaggioVideo = "La decorrenza originaria non può essere inferiore a 6 mesi dalla data di presentazione";
                        return false;
                    }
                }

                //Se 1° Codice Natura (RAU1031) è = a “5” e il 1° carattere della Categoria
                //(RACATEG) è diverso da “S” la Decorrenza Originaria (RAU104) deve
                //essere successiva alla Data della Domanda (RAU24)
                if (codNat1 == '5' && !siglaCategoria.StartsWith("S"))
                {
                    if (tipologiaDomanda != Utility.TipoDomanda.Ricostituzione && tipologiaDomanda != Utility.TipoDomanda.Ripristino && tipologiaDomanda != Utility.TipoDomanda.RipristinoSuperstiti)
                    {
                        DateTime? dataPresentazioneDomandaFirstDay = Utility.DataFromInt(datiPensione.DataPresentazioneDomanda.Year, datiPensione.DataPresentazioneDomanda.Month, 1);
                        if (!dataPresentazioneDomandaFirstDay.HasValue || !Utility.DataSuccessivaA(decorrenzaOriginaria, dataPresentazioneDomandaFirstDay.Value))
                        {
                            messaggioVideo = "La decorrenza originaria deve essere successiva alla data di presentazione";
                            return false;
                        }
                    }
                }

                if (datiAnagraficiTitolare != null && !(Utility.IsDomandaVOAUTContributivoOpzioneFiltroERI(datiPensione) || Utility.IsDomandaAGOTipoContributivoFiltroERI(datiPensione)))
                {
                    if (!AGO_ControlsPensioneLiquidabile(decorrenzaOriginaria, filtro, datiAnagraficiTitolare))
                    {
                        messaggioVideo = "La pensione non può essere liquidata";
                        return false;
                    }
                }

                if ((datiPensione.Gruppo.Equals("0001") && datiPensione.Prodotto.Equals("0002") && (datiPensione.Tipo.Equals("0009") || datiPensione.Tipo.Equals("0192"))) ||
                    (datiPensione.Gruppo.Equals("0002") && datiPensione.Prodotto.Equals("0013") && datiPensione.Tipo.Equals("0009")))
                {
                    if (tipologiaDomanda != Utility.TipoDomanda.Ricostituzione)
                    {
                        DateTime? dataPresentazioneDomandaFirstDay = Utility.DataFromInt(datiPensione.DataPresentazioneDomanda.Year, datiPensione.DataPresentazioneDomanda.Month, 1);
                        if (!dataPresentazioneDomandaFirstDay.HasValue || !Utility.DataStrettamenteSuccessivaA(decorrenzaOriginaria, dataPresentazioneDomandaFirstDay.Value))
                        {
                            messaggioVideo = "La decorrenza originaria deve essere maggiore della data di presentazione";
                            return false;
                        }
                    }
                }

                if (Utility.IsDomandaTrasformazioneInvalidita(datiPensione))
                {
                    if (tipologiaDomanda != Utility.TipoDomanda.Ricostituzione && tipologiaDomanda != Utility.TipoDomanda.Ripristino && tipologiaDomanda != Utility.TipoDomanda.RipristinoSuperstiti)
                    {
                        DateTime? dataPresentazioneDomandaFirstDay = Utility.DataFromInt(datiPensione.DataPresentazioneDomanda.Year, datiPensione.DataPresentazioneDomanda.Month, 1);
                        if (!dataPresentazioneDomandaFirstDay.HasValue || !Utility.DataSuccessivaA(decorrenzaOriginaria, dataPresentazioneDomandaFirstDay.Value))
                        {
                            messaggioVideo = "La decorrenza originaria deve essere successiva alla data di presentazione";
                            return false;
                        }
                    }
                }
            }

            if (siglaCategoria != "IOCUM" || (siglaCategoria == "IOCUM" && datiGenericiAgoCi != null && !datiGenericiAgoCi.EnteIstruttoreExInpdap.GetValueOrDefault()))
            {
                //Se il 1° carattere della Categoria (RACATEG) è = a “I” la Decorrenza
                //Originaria (RAU104) deve essere maggiore della Data della Domanda
                //(RAUE24)
                if (siglaCategoria.StartsWith("I"))
                {
                    if (tipologiaDomanda != Utility.TipoDomanda.Ricostituzione && tipologiaDomanda != Utility.TipoDomanda.Ripristino && tipologiaDomanda != Utility.TipoDomanda.RipristinoSuperstiti)
                    {
                        if (!Utility.IsDomandaIOCUM(datiPensione.SiglaCategoria) && ((Utility.IsDomandaInabilitaAmianto(datiPensione) || Utility.IsDomandaInabilitaOrdinaria(datiPensione) ||
                             Utility.IsDomandaInabilitaNavigazione(datiPensione) || Utility.IsDomandaInvaliditaOrdinaria(datiPensione) ||
                             Utility.IsDomandaAssegnoInvaliditaOrdinario(datiPensione)) ?
                            !Utility.DataStrettamenteSuccessivaA(decorrenzaOriginaria, new DateTime(datiPensione.DataPresentazioneDomanda.Year, datiPensione.DataPresentazioneDomanda.Month, 1)) :
                            !Utility.DataSuccessivaA(decorrenzaOriginaria, new DateTime(datiPensione.DataPresentazioneDomanda.Year, datiPensione.DataPresentazioneDomanda.Month, 1))))
                        {
                            messaggioVideo = "La decorrenza originaria deve essere maggiore della data di presentazione";
                            return false;
                        }
                    }
                }
            }

            if (Utility.IsPrepensionamentoEditoriaArt1c154L205_2017(datiPensione))
            {
                if (!Utility.DataSuccessivaA(decorrenzaOriginaria, new DateTime(2018, 2, 1)))
                {
                    messaggioVideo = "La decorrenza originaria non può essere inferiore a Febbraio 2018";
                    return false;
                }
            }

            if (Utility.IsPrepensionamentoEditoriaArt1c500L160_2019(datiPensione))
            {
                if (!Utility.DataSuccessivaA(decorrenzaOriginaria, new DateTime(2020, 2, 1)))
                {
                    messaggioVideo = "La decorrenza originaria non può essere inferiore a Febbraio 2020";
                    return false;
                }

                //ENG - memo 57 introdotto controllo dinamico ULTIMA_DEC_UTILE_TIPO0179
                GestioneControlliDinamici.ControlloDinamico controlloDinamico = null;
                GestioneControlliDinamici.GetControlloDinamicoByNomeControllo("ULTIMA_DEC_UTILE_TIPO0179", out controlloDinamico);
                if (controlloDinamico != null && !String.IsNullOrEmpty(controlloDinamico.ValoreControllo) && !String.IsNullOrEmpty(controlloDinamico.ValoreControllo.Trim()))
                {
                    DateTime? dataLimiteSuperiore = Utility.DataFromString(controlloDinamico.ValoreControllo.Trim(), Utility.FormatoData.AAAAmmGG);
                    if (Utility.DataStrettamenteSuccessivaA(decorrenzaOriginaria, dataLimiteSuperiore.GetValueOrDefault()))
                    {
                        messaggioVideo = string.Format("La decorrenza originaria non può essere superiore a ({0:MM/yyyy})", dataLimiteSuperiore);
                        return false;
                    }
                }
            }

            //ENG - Per memo 123/2021 del computo per le RIC/TRF di pensioni anticipate senza filtro PAV (IDTipoPLperRIC= 21). 
            //Nel Pannello Titolare rimosso messaggio "La decorrenza originaria non può essere inferiore a Gennaio 2012"
            GestioneControlliDinamici.ControlloDinamico ctrlDinamicoMemo123 = null;
            GestioneControlliDinamici.GetControlloDinamicoByNomeControllo("AbilitazioneMemo123_2021", out ctrlDinamicoMemo123);
            if (siglaCategoria == "VOAUT" && Utility.IsPensioneAnzianitaOrRicostituzione(datiPensione, null) && !(ctrlDinamicoMemo123 != null && !String.IsNullOrEmpty(ctrlDinamicoMemo123.ValoreControllo) && ctrlDinamicoMemo123.ValoreControllo.Trim().ToUpperInvariant() == "SI" && (Utility.IsDomandaAUTAnticipataInComputo(datiPensione, false) || (datiPensione.IdTipoPLPerRIC.HasValue && datiPensione.IdTipoPLPerRIC == 21))))
            {
                if (!Utility.DataSuccessivaA(decorrenzaOriginaria, new DateTime(2012, 1, 1)))
                {
                    messaggioVideo = "La decorrenza originaria non può essere inferiore a Gennaio 2012";
                    return false;
                }
            }

            if (codNat1 == '5' && (siglaCategoria == "VOAUT" || siglaCategoria == "IOAUT" || (siglaCategoria == "SOAUT" && !Utility.IsDomandaReversibilitaOrRicostituzione(datiPensione, datiDanteCausa))))
            {
                if (!Utility.DataSuccessivaA(decorrenzaOriginaria, new DateTime(1996, 5, 1)))
                {
                    messaggioVideo = "La decorrenza originaria non può essere inferiore a Maggio 1996";
                    return false;
                }
            }
            if (Utility.IsPrepensionamentoEditoriaFiltroEAA(datiPensione) && !Utility.IsRicostituzioneOrRiapertura(datiPensione, isRiaperturaDomanda))
            {
                if (Utility.DataStrettamenteSuccessivaA(datiPensione.DataPresentazioneDomanda, decorrenzaOriginaria))
                {
                    messaggioVideo = "La decorrenza originaria non può essere inferiore alla data presentazione domanda";
                    return false;
                }
            }
            return true;
        }

        public static bool AGO_VerificaDecorrenzaPensioneInabilitaAmianto(GestionePensione.DatiPensione datiPensione, DateTime? decorrenzaPensione, out string messaggioVideo)
        {
            messaggioVideo = string.Empty;

            if (Utility.IsDomandaInabilitaAmianto(datiPensione))
            {
                if (decorrenzaPensione.HasValue && !Utility.DataSuccessivaA(decorrenzaPensione.Value, new DateTime(2017, 2, 1)))
                {
                    messaggioVideo = "La decorrenza pensione non può essere antecedente al 02/2017.";
                    return false;
                }
            }

            return true;
        }

        public static bool AGO_VerificaDecorrenzaPensioneEsattoriali(GestionePensione.DatiPensione datiPensione, DateTime? decorrenzaPensione, out string messaggioVideo)
        {
            messaggioVideo = string.Empty;

            if (Utility.IsDomandaAnticipataEsattoriali(datiPensione))
            {
                if (decorrenzaPensione.HasValue && !Utility.DataSuccessivaA(decorrenzaPensione.Value, new DateTime(2017, 7, 1)))
                {
                    messaggioVideo = "La decorrenza pensione non può essere inferiore a 07/2017.";
                    return false;
                }
            }

            return true;
        }

        public static bool AGO_VerificaPerfRequisiti(DateTime? dataPerfReq, DateTime? decorrenzaPensione, DateTime? scadenzaAssegno, GestionePensione.DatiPensione datiPensione,
            GestioneIstruttoria.DatiIstruttoria datiIstruttoria, DateTime? dataCondizioniPerComputo, out string messaggioVideo)
        {
            messaggioVideo = string.Empty;

            string siglaCategoria = string.Empty;

            DateTime decorrenzaOriginaria = DateTime.MinValue;
            string certificato = string.Empty;

            if (datiPensione == null)
            {
                messaggioVideo = "Dati pensione non disponibili";
                return false;
            }

            #region Recupero Dati

            decorrenzaOriginaria = decorrenzaPensione.HasValue ? decorrenzaPensione.Value : DateTime.MinValue;
            siglaCategoria = datiPensione.SiglaCategoria.Trim().ToUpperInvariant();
            certificato = datiPensione.NCertificato.HasValue ? datiPensione.NCertificato.Value.ToString().PadLeft(8, '0') : "00000000";

            #endregion Recupero Dati

            if (dataPerfReq.HasValue)
            {
                GestioneControlliDinamici.ControlloDinamico ctrlDinamicoMemo123 = null;
                GestioneControlliDinamici.GetControlloDinamicoByNomeControllo("AbilitazioneMemo123_2021", out ctrlDinamicoMemo123);
                if (Utility.IsDomandaAUTAnticipataInComputo(datiPensione, false) && ctrlDinamicoMemo123 != null && !String.IsNullOrEmpty(ctrlDinamicoMemo123.ValoreControllo) && ctrlDinamicoMemo123.ValoreControllo == "SI")
                {
                    if (dataCondizioniPerComputo.HasValue && dataPerfReq.HasValue)
                    {
                        if (Utility.DataStrettamenteSuccessivaA(dataCondizioniPerComputo.Value, new DateTime(2011, 12, 31)) && !Utility.DataStrettamenteSuccessivaA(dataPerfReq.Value, new DateTime(2011, 12, 31)))
                        {
                            messaggioVideo = "Se data di perfezionamento delle condizioni per il computo è successiva al 31.12.2011, la data di perfezionamento dei requisiti deve essere maggiore o uguale al 2012";
                            return false;
                        }
                    }
                }

                //ENG - Memo 123/2024 
                GestioneControlliDinamici.ControlloDinamico ctrlMemo123_2024 = null;
                GestioneControlliDinamici.GetControlloDinamicoByNomeControllo("AbilitazioneRIC_TRFMemo123_2024", out ctrlMemo123_2024);

                //ENG - Memo 123/2024 
                GestioneControlliDinamici.ControlloDinamico ctrlMemo123_2024OpzioneContrib = null;
                GestioneControlliDinamici.GetControlloDinamicoByNomeControllo("AbilitazioneRIC_TRFMemo123_2024OpzioneContrib", out ctrlMemo123_2024OpzioneContrib);

                if (!Utility.IsDomandaTipoContributivo(datiPensione, null, null) && !Utility.IsDomandaVecchiaiaInComputo(datiPensione) && !Utility.IsDomandaAnticipataFlessibileOpzioneContributivo(datiPensione) && !Utility.isDomandaVecchiaiaTrasformazioneAOICalcoloContributivo(datiPensione) &&
                    !((!Utility.IsRicostituzione(datiPensione.Gruppo) && !Utility.IsRiaperturaDomanda(datiPensione.Id) && (Utility.IsDomandaAnticipataFlessibileLeggeBilancio2024(datiPensione) || Utility.IsDomandaAnticipataFlessibileOpzioneContributivoLeggeBilancio2024(datiPensione))) ||
                      ((Utility.IsRicostituzione(datiPensione.Gruppo) || Utility.IsRiaperturaDomanda(datiPensione.Id)) && ((ctrlMemo123_2024 != null && ctrlMemo123_2024.ValoreControllo == "SI" && Utility.IsDomandaAnticipataFlessibileLeggeBilancio2024(datiPensione)) || (ctrlMemo123_2024OpzioneContrib != null && ctrlMemo123_2024OpzioneContrib.ValoreControllo == "SI" && Utility.IsDomandaAnticipataFlessibileOpzioneContributivoLeggeBilancio2024(datiPensione)))) || Utility.IsDomandaVOAUTAnticipataFlessibileLeggeBilancio2024FiltroGSE(datiPensione))) //ENG - Memo 166/2023
                {
                    //La Data Perfezionamento Requisito (PERFREQ) è acquisibile se la
                    //Categoria (RACATEG) è = a "VO", "VOART", "VR", "VOCOM", "VDAI",
                    //"VOBANC", "VOAUT", "VOP", "VOSPED", "VOMIN", "VOTOT" e "PMO" con
                    //il 3° carattere del Certificato = a “1” o “4” e la Decorrenza Originaria
                    //(RAU104) è da febbraio 2011
                    //Se la Categoria (RACATEG) è = a “VOCRED”, “VOCOOP”, “VOESO” la Data
                    //Perfezionamento Requisito (PERFEREQ) deve essere presente
                    switch (siglaCategoria)
                    {
                        case "VO":
                        case "VOART":
                        case "VR":
                        case "VOCOM":
                        case "VDAI":
                        case "VOBANC":
                        case "VOP":
                        case "VOSPED":
                        case "VOMIN":
                        case "VOTOT":
                        case "VOCUM":
                        case "VESO33":
                        case "VESO92":
                        case "VESO29":
                            if (Utility.DataSuccessivaA(decorrenzaOriginaria, new DateTime(2011, 02, 01)))
                            {
                                break;
                            }
                            else
                            {
                                messaggioVideo = "La data perfezionamento requisiti non è acquisibile";
                                return false;
                            }
                        case "VOAUT":
                            return true;
                        case "PMO":
                            if (certificato.Substring(2, 1) == "1" || certificato.Substring(2, 1) == "4")
                            {
                                if (Utility.DataSuccessivaA(decorrenzaOriginaria, new DateTime(2011, 02, 01)))
                                {
                                    break;
                                }
                                else
                                {
                                    messaggioVideo = "La data perfezionamento requisiti non è acquisibile";
                                    return false;
                                }
                            }
                            else
                            {
                                messaggioVideo = "La data perfezionamento requisiti non è acquisibile";
                                return false;
                            }
                        case "VOCRED":
                        case "CRED27":
                        case "VOCOOP":
                        case "VOESO":
                        case "COOP28":
                        case "ESOTEL":
                        case "ESOAMB":
                            //Se la Categoria (RACATEG) è = a “VOCRED”, “VOCOOP”, “VOESO” e il
                            //Campo DO-NOTE è = a “SAA”, “SVA”, “SAM”, “SVM”, “SSA”, “SSM”, “STA”,
                            //“STM” la Data Perfezionamento Requisito (PERFEREQ) deve essere
                            //successiva a dicembre 2010
                            switch (datiPensione.GetFiltro())
                            {
                                case "SAA":
                                case "SVA":
                                case "SAM":
                                case "SVM":
                                case "SSA":
                                case "SSM":
                                case "STA":
                                case "STM":
                                    if (!Utility.DataStrettamenteSuccessivaA(dataPerfReq.Value, new DateTime(2010, 12, 31)))
                                    {
                                        messaggioVideo = "La data perfezionamento requisiti deve essere successiva a dicembre 2010";
                                        return false;
                                    }
                                    break;
                                default:
                                    break;
                            }

                            if (Utility.IsDomandaQuota100ESOTEL(datiPensione))
                            {
                                DateTime maxDataPerfReqQuota100ESOTEL = new DateTime(2021, 12, 31);
                                if (dataPerfReq != null && Utility.DataStrettamenteSuccessivaA(dataPerfReq.Value, maxDataPerfReqQuota100ESOTEL))
                                {
                                    messaggioVideo = string.Format("La data perfezionamento requisiti non può essere successiva al {0:dd/MM/yyyy}", maxDataPerfReqQuota100ESOTEL);
                                    return false;
                                }
                            }
                            if (Utility.IsDomandaQuota100ESOAMB(datiPensione))
                            {
                                DateTime maxDataPerfReqQuota100ESOAMB = new DateTime(2020, 12, 31);
                                if (dataPerfReq != null && Utility.DataStrettamenteSuccessivaA(dataPerfReq.Value, maxDataPerfReqQuota100ESOAMB))
                                {
                                    messaggioVideo = string.Format("La data perfezionamento requisiti non può essere successiva al {0:dd/MM/yyyy}", maxDataPerfReqQuota100ESOAMB);
                                    return false;
                                }
                            }

                            //Se la Categoria (RACATEG) è = a “VOCRED”, “VOCOOP”, “VOESO” la Data
                            //Perfezionamento Requisito (PERFEREQ) deve essere inferiore alla
                            //Scadenza Assegno (RAU112)
                            if (scadenzaAssegno.HasValue)
                            {
                                if (Utility.DataSuccessivaA(dataPerfReq.Value, scadenzaAssegno.Value))
                                {
                                    messaggioVideo = "La data perfezionamento requisiti deve essere inferiore alla Scadenza Assegno";
                                    return false;
                                }
                            }
                            break;
                        case "VOCTPS":
                        case "VOCPDEL":
                        case "VOCPI":
                        case "VOCPS":
                        case "VOCPUG":
                        case "VOCTPSS":
                        case "VOCPDELS":
                        case "VOCPIS":
                        case "VOCPSS":
                        case "VOCPUGS":
                        case "ESOPMI":
                            break;
                        case "APE":
                            DateTime? dataCompare = null;
                            GestioneControlliDinamici.ControlloDinamico ctrl = null;
                            GestioneControlliDinamici.GetControlloDinamicoByNomeControllo("DataControlloApeSociale", out ctrl);
                            if (ctrl != null)
                                dataCompare = Utility.DataFromString(ctrl.ValoreControllo, Utility.FormatoData.AAAAmmGG);
                            else
                                dataCompare = new DateTime(2019, 12, 31);
                            if (Utility.DataStrettamenteSuccessivaA(dataPerfReq.Value, dataCompare.Value))
                            {
                                messaggioVideo = string.Format("La data perfezionamento requisiti non può essere successiva al {0:dd/MM/yyyy}", dataCompare.Value);
                                return false;
                            }
                            break;
                        case "ESPA":
                            if (!Utility.DataStrettamenteSuccessivaA(dataPerfReq.Value, new DateTime(2020, 12, 31)))
                            {
                                messaggioVideo = "La data perfezionamento requisiti deve essere successiva a dicembre 2020";
                                return false;
                            }
                            break;
                        case "VOPGI":
                            if (!Utility.IsDomandaVOPGI_AGI(datiPensione) && !Utility.DataSuccessivaA(dataPerfReq.Value, new DateTime(2022, 07, 01))
                                && !Utility.IsOpzioneDonna_Legge197_2022_Art1_Comma292_LetteraA(datiPensione, true, true) && !Utility.IsOpzioneDonna_Legge197_2022_Art1_Comma292_LetteraB(datiPensione, true, true)
                                && !Utility.IsOpzioneDonna_Legge197_2022_Art1_Comma292_LetteraC(datiPensione, true, true)
                                && !(Utility.IsRicostituzione(datiPensione.Gruppo) && datiPensione.GP1AV91B == "2"))
                            {
                                //ENG - per le domande con categoria VOPGI, tipo= 0162 e filtro "EBA" rimuovere il controllo, mentre per il filtro "EAA"
                                //modificare il messaggio in:"La data perfezionamento requisiti non può essere antecedente al 1° Luglio 2022"
                                if ((datiPensione.Tipo == "0162" && !string.IsNullOrEmpty(datiPensione.GetFiltro()) && datiPensione.GetFiltro().ToUpperInvariant().Equals("EAA"))
                                    || Utility.GetEnumTipoPLPerRICbyId(datiPensione.IdTipoPLPerRIC) == Utility.TipoPLPerRIC.RicPrepensionamentoEditoriaArt37L416_1981_LetteraA)
                                {
                                    messaggioVideo = "La data perfezionamento requisiti non può essere antecedente al 1° Luglio 2022";
                                    return false;
                                }
                                else if ((string.IsNullOrEmpty(datiPensione.GetFiltro()) && Utility.GetEnumTipoPLPerRICbyId(datiPensione.IdTipoPLPerRIC) != Utility.TipoPLPerRIC.RicPrepensionamentoEditoriaArt37L416_1981_LetteraB) || (!string.IsNullOrEmpty(datiPensione.GetFiltro()) && !datiPensione.GetFiltro().ToUpperInvariant().Equals("EBA")))
                                {
                                    messaggioVideo = "Pensione senza diritto autonomo INPGI avente data perfezionamento requisiti antecedente al 1° Luglio 2022 non ammissibile. In presenza di diritto autonomo, inserire in domanda la tipologia ‘AGI’ tramite procedura Webdom e riprelevare in IVS";
                                    return false;
                                }
                            }
                            break;
                        //ENG - Aggiornamento Memo 68/2022 IOPGI
                        case "IOPGI":
                            if (!Utility.IsDomandaIOPGI_AGI(datiPensione) && !Utility.DataSuccessivaA(dataPerfReq.Value, new DateTime(2022, 07, 01)) &&
                                !(Utility.IsRicostituzione(datiPensione.Gruppo) && datiPensione.GP1AV91B == "2"))
                            {
                                messaggioVideo = "La data perfezionamento requisiti deve essere successiva o uguale al 01/07/2022";
                                return false;
                            }
                            break;
                        default:
                            if (!(siglaCategoria.StartsWith("S") && Utility.IsRicostituzione(datiPensione.Gruppo))
                                && !(Utility.IsDomandaPensioneIndiretta(datiPensione) && datiPensione.Tipo == "0001" && datiPensione.CodiceTipoRichiesta == "56"))
                            {
                                messaggioVideo = "La data perfezionamento requisiti non è acquisibile";
                                return false;
                            }
                            else
                                return true;

                    }
                }


            }
            else
            {
                //Se la Categoria (RACATEG) è = a “VOCRED”, “VOCOOP”, “VOESO” la Data
                //Perfezionamento Requisito (PERFEREQ) deve essere presente
                switch (siglaCategoria)
                {
                    case "VOCRED":
                    case "CRED27":
                    case "VOCOOP":
                    case "VOESO":
                    case "COOP28":
                    case "VESO29":
                    case "ESOAMB":
                    case "ESOTEL":
                        messaggioVideo = "La data perfezionamento requisiti deve essere presente";
                        return false;
                    default:
                        break;
                }
            }

            return true;
        }

        public static bool AGO_VerificaCodiceSindacato(GestionePensione.DatiSindacato datiSindacato, DateTime? decorrenzaPensione, GestionePensione.DatiPensione datiPensione, out string messaggioVideo)
        {
            messaggioVideo = string.Empty;

            string siglaCategoria = string.Empty;

            DateTime decorrenzaOriginaria = DateTime.MinValue;
            string certificato = string.Empty;
            string codiceSindacato = datiSindacato != null ? (!string.IsNullOrEmpty(datiSindacato.CodiceSindacato) && Utility.IsSindacatoPresente(datiSindacato.CodiceSindacato)) ? datiSindacato.CodiceSindacato.Trim().ToUpperInvariant() : string.Empty : string.Empty;
            if (datiPensione == null)
            {
                messaggioVideo = "Dati pensione non disponibili";
                return false;
            }

            #region Recupero Dati


            decorrenzaOriginaria = decorrenzaPensione.HasValue ? decorrenzaPensione.Value : DateTime.MinValue;
            siglaCategoria = datiPensione.SiglaCategoria.Trim().ToUpperInvariant();
            certificato = datiPensione.NCertificato.HasValue ? datiPensione.NCertificato.Value.ToString().PadLeft(8, '0') : "00000000";
            #endregion Recupero Dati

            switch (siglaCategoria)
            {
                //Se la Categoria (RACATEG) è = a "INDCOM", "SOSPED",
                //"VOSPED","IOSPED", "VOBIS ", "IOBIS ", "VMP ", "IMP ", il Codice Sindacato (RAUCODSIND) deve essere 0
                //(zero)
                case "INDCOM":
                case "SOSPED":
                case "VOSPED":
                case "IOSPED":
                case "VOBIS":
                case "IOBIS":
                case "VMP":
                case "IMP":
                    if (Utility.IsSindacatoPresente(codiceSindacato))
                    {
                        messaggioVideo = "Il sindacato non deve essere acquisito";
                        return false;
                    }
                    break;

                case "VOCOOP":
                case "COOP28":
                    //Se la Categoria (RACATEG) è = a “VOCOOP” e il Campo DO-NOTE è = a
                    //“AGO” il Codice Sindacato (RAUCODSIND) deve essere 0 (zero)
                    if (datiPensione.GetFiltro() == "AGO" && Utility.IsSindacatoPresente(codiceSindacato))
                    {
                        messaggioVideo = "Il sindacato non deve essere acquisito";
                        return false;
                    }
                    //Se la Categoria (RACATEG) è = a “VOCOOP” e il Campo DO-NOTE è = a
                    //“PT” e il Codice Banca (RADODBANC4) è diverso da 801 il Codice
                    //Sindacato (RAUCODSIND) deve essere 0 (zero)
                    if (datiPensione.GetFiltro() == "PT" && Utility.IsSindacatoPresente(codiceSindacato) &&
                        (!datiPensione.CodiceBancaEsodati.HasValue || datiPensione.CodiceBancaEsodati.Value != 801))
                    {
                        messaggioVideo = "Il sindacato non deve essere acquisito";
                        return false;
                    }
                    break;
                default:
                    break;
            }


            switch (codiceSindacato)
            {
                // A4 non ammesso
                case "A4":
                    messaggioVideo = "Il sindacato selezionato non è ammesso";
                    return false;

                case "C6":
                case "C8":
                case "C0":
                case "H2":
                case "C9":
                case "H8":
                case "H9":
                case "D5":

                    switch (siglaCategoria)
                    {
                        case "VOSPED":
                        case "IOSPED":
                        case "SOSPED":
                        case "VOBIS":
                        case "IOBIS":
                        case "VOBANC":
                        case "IOBANC":
                        case "VMP":
                        case "IMP":
                        case "INDCOM":
                            messaggioVideo = "Il sindacato selezionato non è ammesso";
                            return false;

                        case "SOBANC":
                            // SOBANC ammesso SOLO per H2, H8, H9
                            if (codiceSindacato != "H2" &&
                                codiceSindacato != "H8" &&
                                codiceSindacato != "H9")
                            {
                                messaggioVideo = "Il sindacato selezionato non è ammesso";
                                return false;
                            }
                            break;
                    }

                    // Regola specifica H2
                    if (codiceSindacato == "H2")
                    {
                        switch (siglaCategoria)
                        {
                            case "VOBANC":
                            case "IOBANC":
                                // SOBANC volutamente escluso
                                messaggioVideo = "Il sindacato selezionato non è ammesso";
                                return false;
                        }
                    }

                    break;
            }


            return true;
        }

        private static bool AGO_ControlsPensioneLiquidabile(DateTime decorrenzaOriginaria, string filtro, GestioneAnagrafica.DatiAnagrafici datiAnagrafici)
        {
            if (filtro == "ERI")
            {
                //Se il Campo DO-NOTE è = “ERI” e la Decorrenza Originaria (RAU104) è
                //superiore a dicembre 2006 e la Provincia Residenza (RAUA05) è = a “BG”,
                //“RO” la pensione non può essere liquidata
                if (Utility.DataSuccessivaA(decorrenzaOriginaria, new DateTime(2006, 12, 1))
                    && !string.IsNullOrEmpty(datiAnagrafici.CodiceComuneResidenza) && datiAnagrafici.CodiceComuneResidenza.StartsWith("Z") &&
                    !string.IsNullOrEmpty(datiAnagrafici.ProvinciaResidenza) &&
                    (datiAnagrafici.ProvinciaResidenza.Trim().ToUpperInvariant() == "BG" || datiAnagrafici.ProvinciaResidenza.Trim().ToUpperInvariant() == "RO"))
                    return false;
                //Se il Campo DO-NOTE è = “ERI” e la Decorrenza Originaria (RAU104) è
                //superiore ad aprile 2004 e la Provincia Residenza (RAUA05) è = a “PL”,
                //“CZ”,"SK", "SLO", "LT", "LV", "CY", "H", "EST", "M" la pensione non può
                //essere liquidata
                if (Utility.DataSuccessivaA(decorrenzaOriginaria, new DateTime(2004, 4, 1))
                    && !string.IsNullOrEmpty(datiAnagrafici.CodiceComuneResidenza) && datiAnagrafici.CodiceComuneResidenza.StartsWith("Z") &&
                    !string.IsNullOrEmpty(datiAnagrafici.ProvinciaResidenza))
                {
                    switch (datiAnagrafici.ProvinciaResidenza.Trim().ToUpperInvariant())
                    {
                        case "PL":
                        case "CZ":
                        case "SK":
                        case "SLO":
                        case "LT":
                        case "LV":
                        case "CY":
                        case "H":
                        case "EST":
                        case "M":
                            return false;
                        default:
                            break;
                    }
                }
                //Se il Campo DO-NOTE è = “ERI” e la Decorrenza Originaria (RAU104) è
                //superiore a maggio 2002 e la Provincia Residenza (RAUA05) è = a “CH” la
                //pensione non può essere liquidata
                if (Utility.DataSuccessivaA(decorrenzaOriginaria, new DateTime(2002, 5, 1))
                    && !string.IsNullOrEmpty(datiAnagrafici.CodiceComuneResidenza) && datiAnagrafici.CodiceComuneResidenza.StartsWith("Z") &&
                    !string.IsNullOrEmpty(datiAnagrafici.ProvinciaResidenza) &&
                    datiAnagrafici.ProvinciaResidenza.Trim().ToUpperInvariant() == "CH")
                    return false;
                //Se il Campo DO-NOTE è = “ERI” e la Decorrenza Originaria (RAU104) è
                //superiore ad aprile 1995 e la Provincia Residenza (RAUA05) è = a “FL” la
                //pensione non può essere liquidata
                if (Utility.DataSuccessivaA(decorrenzaOriginaria, new DateTime(1995, 4, 1))
                    && !string.IsNullOrEmpty(datiAnagrafici.CodiceComuneResidenza) && datiAnagrafici.CodiceComuneResidenza.StartsWith("Z") &&
                    !string.IsNullOrEmpty(datiAnagrafici.ProvinciaResidenza) &&
                    datiAnagrafici.ProvinciaResidenza.Trim().ToUpperInvariant() == "FL")
                    return false;
                //Se il Campo DO-NOTE è = ERI” e la Decorrenza Originaria (RAU104) è
                //superiore a dicembre 1993 e la Provincia Residenza (RAUA05) è = a "S",
                //"FIN", "SF", "N", "A", "IS" la pensione non può essere liquidata
                if (Utility.DataSuccessivaA(decorrenzaOriginaria, new DateTime(1993, 12, 1))
                    && !string.IsNullOrEmpty(datiAnagrafici.CodiceComuneResidenza) && datiAnagrafici.CodiceComuneResidenza.StartsWith("Z") &&
                    !string.IsNullOrEmpty(datiAnagrafici.ProvinciaResidenza))
                {
                    switch (datiAnagrafici.ProvinciaResidenza.Trim().ToUpperInvariant())
                    {
                        case "S":
                        case "FIN":
                        case "SF":
                        case "N":
                        case "A":
                        case "IS":
                            return false;
                        default:
                            break;
                    }
                }
                //Se il Campo DO-NOTE è = ERI” e la Decorrenza Originaria (RAU104) è
                //superiore a giugno 1992 e la Provincia Residenza (RAUA05) è = a "F", "D",
                //"DK", "NL", "L", "B", "E", "P", "GR", "GB", "IRL" la pensione non può essere
                //liquidata
                if (Utility.DataSuccessivaA(decorrenzaOriginaria, new DateTime(1992, 6, 1))
                    && !string.IsNullOrEmpty(datiAnagrafici.CodiceComuneResidenza) && datiAnagrafici.CodiceComuneResidenza.StartsWith("Z") &&
                    !string.IsNullOrEmpty(datiAnagrafici.ProvinciaResidenza))
                {
                    switch (datiAnagrafici.ProvinciaResidenza.Trim().ToUpperInvariant())
                    {
                        case "F":
                        case "D":
                        case "DK":
                        case "NL":
                        case "L":
                        case "B":
                        case "E":
                        case "P":
                        case "GR":
                        case "GB":
                        case "IRL":
                            return false;
                        default:
                            break;
                    }
                }
            }
            return true;
        }

