        /// <summary>
        /// Verifica i limite della decorrenza pensione per le domande VESO92
        /// </summary>
        /// <param name="datiPensione"></param>
        /// <param name="decorrenzaOriginaria"></param>
        /// <param name="codiceBancaEsodatiTraduzioneSuGP"></param>
        /// <param name="annoBancaFideiussoria"></param>
        /// <param name="progressivoBancaFideiussoria"></param>
        /// <param name="cognomeTitolare"></param>
        /// <param name="listaDecBancaFideiussione"></param>
        /// <param name="messaggioVideo"></param>
        /// <returns></returns>
        public static bool VerificaDecorrenzaOriginariaVESO92(GestionePensione.DatiPensione datiPensione, DateTime? decorrenzaOriginaria, string codiceBancaEsodatiTraduzioneSuGP,
            short? annoBancaFideiussoria, byte? progressivoBancaFideiussoria, string cognomeTitolare, string codiceFiscaleTitolare, List<GestioneBancheFideiussione.DecBancaFideiussione> listaDecBancaFideiussione, out string messaggioVideo)
        {
            messaggioVideo = string.Empty;

            if (Utility.IsDomandaVESO92(datiPensione.SiglaCategoria))
            {
                if (listaDecBancaFideiussione != null && listaDecBancaFideiussione.Count > 0)
                {
                    GestioneBancheFideiussione.DecBancaFideiussione decBancaFideiussione = listaDecBancaFideiussione.SingleOrDefault(x => x.CodiceAzienda == codiceBancaEsodatiTraduzioneSuGP &&
                        x.Anno == annoBancaFideiussoria && x.Progressivo == progressivoBancaFideiussoria);
                    if (decBancaFideiussione != null)
                    {
                        if (!(Utility.DataSuccessivaA(decorrenzaOriginaria.Value, decBancaFideiussione.InizioEsodo.Value) &&
                            !Utility.DataStrettamenteSuccessivaA(decorrenzaOriginaria.Value, decBancaFideiussione.FineEsodo.Value)))
                        {
                            messaggioVideo = string.Format("La decorrenza assegno ammessa deve essere compresa tra il {0:dd/MM/yyyy} e il {1:dd/MM/yyyy}.",
                                decBancaFideiussione.InizioEsodo.Value, decBancaFideiussione.FineEsodo.Value);
                            return false;
                        }

                        if (decBancaFideiussione.CodiceAzienda == "1002")
                        {
                            switch (decBancaFideiussione.Anno.GetValueOrDefault())
                            {
                                case 2015:
                                    // Per CodiceAzienda 1002, Anno 2015 e Progressivo 1 il cognome del titolare deve iniziare con una lettera tra la A e la I
                                    if (decBancaFideiussione.Progressivo.GetValueOrDefault() == 1)
                                    {
                                        if (cognomeTitolare.ToUpperInvariant()[0] < 'A' || cognomeTitolare.ToUpperInvariant()[0] > 'I')
                                        {
                                            messaggioVideo = "Per l'azienda " + decBancaFideiussione.CodiceAzienda + " con Anno " + decBancaFideiussione.Anno + " e Progressivo " + decBancaFideiussione.Progressivo +
                                                " il cognome del titolare (" + cognomeTitolare + ") deve iniziare con una lettera tra la A e la I.";
                                            return false;
                                        }
                                    }
                                    // Per CodiceAzienda 1002, Anno 2015 e Progressivo 2 il cognome del titolare deve iniziare con una lettera tra la L e la Z
                                    else if (decBancaFideiussione.Progressivo.GetValueOrDefault() == 2)
                                    {
                                        if (cognomeTitolare.ToUpperInvariant()[0] < 'L' || cognomeTitolare.ToUpperInvariant()[0] > 'Z')
                                        {
                                            messaggioVideo = "Per l'azienda " + decBancaFideiussione.CodiceAzienda + " con Anno " + decBancaFideiussione.Anno + " e Progressivo " + decBancaFideiussione.Progressivo +
                                                " il cognome del titolare (" + cognomeTitolare + ") deve iniziare con una lettera tra la L e la Z.";
                                            return false;
                                        }
                                    }
                                    break;
                                case 2019:
                                    // Per CodiceAzienda 1002, Anno 2019 e Progressivo 3 il codice fiscale del titolare deve iniziare con una lettera tra B e L
                                    if (decBancaFideiussione.Progressivo.GetValueOrDefault() == 3)
                                    {
                                        List<char> listaInizialiAmmesse = new List<char> { 'B', 'C', 'D', 'E', 'F', 'G', 'H', 'I', 'J', 'K', 'L' };
                                        if (!listaInizialiAmmesse.Contains(codiceFiscaleTitolare.ElementAtOrDefault(0)))
                                        {
                                            messaggioVideo = string.Format("Per l'azienda {0} con Anno {1} e Progressivo {2} il codice fiscale del titolare deve iniziare per {3}",
                                                decBancaFideiussione.CodiceAzienda, decBancaFideiussione.Anno, decBancaFideiussione.Progressivo, string.Join(", ", listaInizialiAmmesse.Select(x => x.ToString()).ToArray()));
                                            return false;
                                        }
                                    }
                                    else if (decBancaFideiussione.Progressivo.GetValueOrDefault() == 4)
                                    {
                                        List<char> listaInizialiAmmesse = new List<char> { 'M', 'N', 'O', 'P', 'Q', 'R', 'S', 'T', 'U', 'V', 'W', 'X', 'Y', 'Z' };
                                        if (!listaInizialiAmmesse.Contains(codiceFiscaleTitolare.ElementAtOrDefault(0)))
                                        {
                                            messaggioVideo = string.Format("Per l'azienda {0} con Anno {1} e Progressivo {2} il codice fiscale del titolare deve iniziare per {3}",
                                                decBancaFideiussione.CodiceAzienda, decBancaFideiussione.Anno, decBancaFideiussione.Progressivo, string.Join(", ", listaInizialiAmmesse.Select(x => x.ToString()).ToArray()));
                                            return false;
                                        }
                                    }
                                    break;
                            }
                        }
                    }
                }
            }

            return true;
        }

