        public static bool AGO_VerificaDecorrenzaPensioneAPESociale(DateTime? decorrenzaOriginaria, GestioneAnagrafica.DatiAnagrafici datiAnagrafici, string siglaCategoria, GestionePensione.DatiPensione datiPensione, out string messaggioVideo)
        {
            messaggioVideo = string.Empty;

            if (Utility.IsDomandaAPESociale(siglaCategoria))
            {
                //ENG - Memo 57_2023
                GestioneControlliDinamici.ControlloDinamico controlloDinamicoAbilitazioneMemo57_2023 = null;
                GestioneControlliDinamici.GetControlloDinamicoByNomeControllo("AbilitazioneMemo57_2023", out controlloDinamicoAbilitazioneMemo57_2023);

                if (decorrenzaOriginaria.HasValue && !Utility.DataSuccessivaA(decorrenzaOriginaria.Value, new DateTime(2017, 5, 1)))
                {
                    messaggioVideo = "La Decorrenza Pensione deve essere successiva al 05/2017";
                    return false;
                }

                int annoMonitoraggio = 0;
                Int32.TryParse(datiPensione.AnnoMonitoraggio, out annoMonitoraggio);
                DateTime? dataControlloApeSociale = null;
                GestioneControlliDinamici.ControlloDinamico ctrl = null;
                GestioneControlliDinamici.GetControlloDinamicoByNomeControllo("DataControlloApeSociale", out ctrl);
                if (ctrl != null && ctrl.ValoreControllo != null)
                    dataControlloApeSociale = Utility.DataFromString(ctrl.ValoreControllo, Utility.FormatoData.AAAAmmGG);

                if (controlloDinamicoAbilitazioneMemo57_2023 == null || String.IsNullOrEmpty(controlloDinamicoAbilitazioneMemo57_2023.ValoreControllo) ||
                    controlloDinamicoAbilitazioneMemo57_2023.ValoreControllo.Trim().ToUpperInvariant() == "NO" || String.IsNullOrEmpty(datiPensione.AnnoMonitoraggio)
                    || String.IsNullOrEmpty(datiPensione.AnnoMonitoraggio.Trim()) || annoMonitoraggio < 2024)
                {
                    if (decorrenzaOriginaria.HasValue &&
                        (Utility.DataStrettamenteSuccessivaA(datiAnagrafici.DataNascita.Value.AddYears(63), decorrenzaOriginaria.Value)))
                    {
                        messaggioVideo = "Il titolare deve avere almeno 63 anni di età in corrispondenza alla decorrenza pensione";
                        return false;
                    }
                }
                else if (controlloDinamicoAbilitazioneMemo57_2023 != null && !String.IsNullOrEmpty(controlloDinamicoAbilitazioneMemo57_2023.ValoreControllo) &&
                   controlloDinamicoAbilitazioneMemo57_2023.ValoreControllo.Trim().ToUpperInvariant() == "SI" && dataControlloApeSociale.HasValue && annoMonitoraggio >= 2024 && annoMonitoraggio <= dataControlloApeSociale.Value.Year)
                {
                    if (decorrenzaOriginaria.HasValue)
                    {
                        //63 anni e 5 mesi devono essere compiuti
                        DateTime dataCompare = Utility.FirstDayOfMonth(datiAnagrafici.DataNascita.Value).AddMonths(1).AddYears(63).AddMonths(5);
                        if (!Utility.DataSuccessivaA(decorrenzaOriginaria.Value, dataCompare))
                        {
                            messaggioVideo = "Il titolare deve avere almeno 63 anni e 5 mesi di età in corrispondenza alla decorrenza pensione";
                            return false;
                        }
                    }
                }
            }

            return true;
        }

        /// <summary>
        /// Verifica la data limite superiore della Decorrenza Pensione per le domande VOESO
        /// </summary>
        /// <param name="decorrenzaOriginaria"></param>
        /// <param name="codiceBancaEsodati"></param>
        /// <param name="siglaCategoria"></param>
        /// <param name="messaggioVideo"></param>
        /// <returns></returns>
        public static bool AGO_VerificaDecorrenzaPensioneSuperioreVOESO(DateTime? decorrenzaOriginaria, GestioneAziendeVOESO.DecAziendeVOESO azVOESO, GestioneDecodificaAzienda.DecAzienda codiceBancaEsodati,
            string siglaCategoria, out string messaggioVideo)
        {
            messaggioVideo = string.Empty;

            if (Utility.IsDomandaVOESO(siglaCategoria) && codiceBancaEsodati != null && azVOESO != null)
            {
                if (decorrenzaOriginaria.HasValue && azVOESO.UltimaDecorrenzaAmmessa.HasValue && Utility.DataStrettamenteSuccessivaA(decorrenzaOriginaria.Value, azVOESO.UltimaDecorrenzaAmmessa.Value))
                {
                    messaggioVideo = string.Format("La Decorrenza Pensione non può essere successiva al {0:dd/MM/yyyy} per l'azienda {1} - {2}.",
                        azVOESO.UltimaDecorrenzaAmmessa.Value, codiceBancaEsodati.TraduzioneSuGP, codiceBancaEsodati.Descrizione);
                    return false;
                }
            }

            return true;
        }

        public static bool AGO_ControlsCompartoScuola(GestionePensione.DatiPensione datiPensione, long? enteCassa, bool? enteIstruttoreExInpdap, List<GestioneCalcolo.QuotePensione> listaQuotePensione,
            char? derogaTraduzioneSuGP, bool isRiaperturaDomanda, out string messaggioVideo)
        {
            messaggioVideo = string.Empty;

            if (!Utility.IsDomandaCumulo(datiPensione.SiglaCategoria) || datiPensione.SiglaCategoria.StartsWith("S") || datiPensione.SiglaCategoria.StartsWith("I"))
                return true;

            // condizione completa per indicare il comparto scuola
            if (!(!string.IsNullOrEmpty(datiPensione.NaturaPensione) && datiPensione.NaturaPensione.Substring(2, 1) == "S"))
            {
                if (!ALL_VerificaPerfezRequisitiDecorPensione(datiPensione, datiPensione.DecorrenzaOriginaria, datiPensione.DataPerfezionamentoRequisiti, derogaTraduzioneSuGP, isRiaperturaDomanda,
                    out messaggioVideo))
                    return false;
            }

            return true;
        }

        /// <summary>
        /// Verifica il requisito di età per le domande con categoria VMP
        /// </summary>
        /// <param name="datiPensioneDB"></param>
        /// <param name="dataNascitaTitolare"></param>
        /// <param name="messaggioVideo"></param>
        /// <returns></returns>
        public static bool AGO_VerificaRequisitoEtaDomandaVMP(GestionePensione.DatiPensione datiPensioneDB, DateTime? decorrenzaOriginaria, DateTime? dataNascitaTitolare, out string messaggioVideo)
        {
            messaggioVideo = null;

            if (!string.IsNullOrEmpty(datiPensioneDB.SiglaCategoria) && datiPensioneDB.SiglaCategoria.Trim() == "VMP")
            {
                if (!dataNascitaTitolare.HasValue)
                {
                    messaggioVideo = "Errore: data nascita del titolare non presente.";
                    return false;
                }

                int anniRichiesti;
                if (Utility.DataSuccessivaA(decorrenzaOriginaria.GetValueOrDefault(), 1997, 2, 1))
                    anniRichiesti = 57;
                else
                    anniRichiesti = 65;

                if (Utility.DataSuccessivaA(dataNascitaTitolare.Value.AddYears(anniRichiesti), decorrenzaOriginaria.GetValueOrDefault()))
                {
                    messaggioVideo = string.Format("Il titolare deve aver compiuto {0} anni alla Decorrenza Pensione {1:MM/yyyy}", anniRichiesti, decorrenzaOriginaria);
                    return false;
                }
            }

            return true;
        }

        public static bool AGO_VerificaRequisitoEtaPrepensionamentoEBA(GestionePensione.DatiPensione datiPensione, DateTime? dataPerfezionamentoRequisiti, DateTime? dataNascitaTitolare, out string messaggioVideo)
        {
            messaggioVideo = null;

            if (Utility.IsPrepensionamentoEditoriaFiltroEBA(datiPensione) && !Utility.IsRicostituzione(datiPensione.Gruppo))
            {
                if (dataPerfezionamentoRequisiti.HasValue)
                {
                    if (dataNascitaTitolare.HasValue && Utility.DataStrettamenteSuccessivaA(dataNascitaTitolare.Value.AddYears(62), dataPerfezionamentoRequisiti.Value))
                    {
                        messaggioVideo = string.Format("Alla data perfezionamento requisiti ({0:dd/MM/yyyy}) non è stato raggiunto il requisito di età di 62 anni", dataPerfezionamentoRequisiti.Value);
                        return false;
                    }
                }
            }
            return true;
        }
        #endregion Titolare

        #region Familiari
        public static bool AGO_VerificaFamiliari(string cfFamiliareAttuale, List<GestioneFamiliari.Familiare> Lfamiliare, List<GestioneFamiliari.CodMaggFamiliari> elencoCodMaggFamiliari,
            GestionePensione.DatiPensione datiPensione, List<GestioneAnagrafica.DatiStatoCivile> elencoStatiCivili, GestioneDanteCausa.DatiDanteCausa datiDanteCausa, char? cumuloEsterno,
            DateTime dataSistema, bool isRiaperturaDomanda, out string messaggioVideo)
        {
            messaggioVideo = string.Empty;

            string siglaCategoria = string.Empty;
            DateTime decorrenzaOriginaria = DateTime.MinValue;
            string certificato = string.Empty;
            int pdirsup = 0;

            #region Recupero Dati
            if (datiPensione == null)
            {
                messaggioVideo = "Dati pensione non disponibili";
                return false;
            }

            siglaCategoria = datiPensione.SiglaCategoria.Trim().ToUpperInvariant();

            certificato = datiPensione.NCertificato.HasValue ? datiPensione.NCertificato.Value.ToString().PadLeft(8, '0') : "00000000";
            decorrenzaOriginaria = datiPensione.DecorrenzaOriginaria.HasValue ? datiPensione.DecorrenzaOriginaria.Value : DateTime.MinValue;

            if ((Utility.IsDomandaPensioneSuperstitiOrRicostituzione(datiPensione) && !Utility.IsDomandaSpacchettamentoENPALS(datiPensione) && !Utility.IsDomandaSpacchettamentoSOPGIPost072022(datiPensione, datiDanteCausa) &&
                !Utility.IsDomandaSpacchettamentoSO(datiPensione, isRiaperturaDomanda) && !Utility.IsDomandaSpacchettamentoSOART(datiPensione, isRiaperturaDomanda) && !Utility.IsDomandaSpacchettamentoSOCOM(datiPensione, isRiaperturaDomanda) && !Utility.IsDomandaSpacchettamentoSR(datiPensione, isRiaperturaDomanda)) ||
                (siglaCategoria == "PMO" && (certificato.Substring(2, 1) == "3" || certificato.Substring(2, 1) == "6")))
                pdirsup = 1;

            byte codProv = 0;
            if (datiDanteCausa != null)
                codProv = datiDanteCausa.ProvenienzaPensione.HasValue ? datiDanteCausa.ProvenienzaPensione.Value : (byte)0;

            if (Utility.IsDomandaIOCUM(datiPensione.SiglaCategoria))
            {
                decorrenzaOriginaria = new DateTime(decorrenzaOriginaria.Year, decorrenzaOriginaria.Month, 1);
            }

            Utility.TipoAppartenenza? tipoAppartenenza = Utility.GetTipoAppartenenza(datiPensione.IndConvInt, datiPensione.Gestione);
            GestioneControlliDinamici.ControlloDinamico abilitazioneMemo33 = null;
            GestioneControlliDinamici.GetControlloDinamicoByNomeControllo("AbilitazioneMemo33" + tipoAppartenenza.Value, out abilitazioneMemo33);
            #endregion Recupero Dati

            foreach (GestioneFamiliari.Familiare fam in Lfamiliare)
            {
                if (fam.Confermato)
                {
                    if (fam.SiglaFamiliare.HasValue)
                    {
                        GestioneAnagrafica.DatiAnagrafici datiAnagrafici = null;
                        GestioneAnagrafica.GetAnagraficaByIdAnagrafica(fam.IdAnagrafica, out datiAnagrafici);

                        switch (fam.SiglaFamiliare.Value)
                        {
                            //Le Sigle (FASIGLA) “X”, “B”, “D” sono valide solo per la Categoria
                            //(RACATEG) = a “SOTOT”
                            //La Sigla (FASIGLA) “X” è ammessa con il Campo Provenienza
                            //(DAU107) = a zero e il Codice Ente (RACODBAN4) = a 821
                            //Le Sigle (FASIGLA) “B”, “D” sono ammesse con il Campo Provenienza
                            //(DAU107) = a zero e il Codice Ente (RACODBAN4) = a 814
                            case 'X':
                                if (!(siglaCategoria == "SOTOT" && codProv == 0 && datiPensione.CodiceBancaEsodati.HasValue && datiPensione.CodiceBancaEsodati.Value == 821))
                                {
                                    messaggioVideo = "La sigla X è ammessa solo per la categoria SOTOT con campo provenienza pari a zero e il codice ente pari a 821";
                                    return false;
                                }
                                break;
                            case 'B':
                            case 'D':
                                if (!(siglaCategoria == "SOTOT" && codProv == 0 && datiPensione.CodiceBancaEsodati.HasValue && datiPensione.CodiceBancaEsodati.Value == 814))
                                {
                                    messaggioVideo = "La sigla B o D è ammessa solo per la categoria SOTOT con campo provenienza pari a zero e il codice ente pari a 814";
                                    return false;
                                }
                                break;
                            //Per le Categorie di Reversibilità (PDIRSUP = a 1):
                            //le Sigle (FASIGLA) “P”, “Y” non sono ammesse
                            //non sono ammesse le Sigle (FASIGLA) “L”, “G”, “P”, “Y”
                            case 'P':
                            case 'Y':
                            case 'L':
                            case 'G':
                                if (pdirsup == 1)
                                {
                                    messaggioVideo = "Le sigle L, G, P e Y non sono ammesse per categorie di reversibilità";
                                    return false;
                                }
                                break;
                            //Per le Categorie dirette (PDIRSUP = a zero)
                            //non è ammessa la Sigla (FASIGLA) “A”
                            case 'A':
                                if (pdirsup == 0)
                                {
                                    messaggioVideo = "La sigla A non è ammessa per categorie dirette";
                                    return false;
                                }
                                break;
                            //Per le Categorie di Reversibilità (PDIRSUP = a 1) se il Dante Causa (il
                            //defunto) è maschio rilevabile dal Campo Sesso Dante Causa (DAU108)
                            //nessuno degli eventuali figli presenti in Tabella Familiari (FATAB) con Sigla
                            //(FASIGLA) = a “I”, “M”, “S”, “U”, “L” deve essere nato dopo il trecentesimo
                            //giorno successivo alla morte rilevabile dal Campo Data Morte Dante Causa
                            //(DAU1010); se il Sesso del Dante Causa è “F” nessun figlio deve essere
                            //nato dopo la data del decesso
                            case 'I':
                            case 'M':
                            case 'S':
                            case 'U':
                                if (pdirsup == 1)
                                {
                                    if (datiDanteCausa != null && datiDanteCausa.DataMorte.HasValue)
                                    {
                                        GestioneAnagrafica.DatiAnagrafici datiAnDA = null;
                                        GestioneAnagrafica.GetAnagraficaByIdAnagrafica(datiDanteCausa.IdAnagrafica, out datiAnDA);
                                        if (datiAnDA != null)
                                        {
                                            if (datiAnDA.Sesso.HasValue && datiAnDA.Sesso.Value == 'M')
                                            {
                                                if (!GestioneBypassControllo.CheckAndLockBypassControlloByNomeBypass(datiPensione, GestioneBypassControllo.NomeBypass.Sentenza_Nati_Dopo_300_Giorni.SENTENZA_NATI_DOPO_300_GIORNI)
                                                    && Utility.DataStrettamenteSuccessivaA(datiAnagrafici.DataNascita.Value, datiDanteCausa.DataMorte.Value.AddDays(300)))
                                                {
                                                    messaggioVideo = "Il familiare non deve essere nato dopo il trecentesimo giorno successivo alla morte del dante causa";
                                                    return false;
                                                }
                                            }
                                            else if (datiAnDA.Sesso.HasValue && datiAnDA.Sesso.Value == 'F')
                                            {
                                                if (Utility.DataStrettamenteSuccessivaA(datiAnagrafici.DataNascita.Value, datiDanteCausa.DataMorte.Value))
                                                {
                                                    messaggioVideo = "Il familiare non deve essere nato dopo la morte del dante causa";
                                                    return false;
                                                }
                                            }
                                        }
                                    }
                                }
                                break;
                            default:
                                break;
                        }

                        List<GestioneFamiliari.CodMaggFamiliari> LcodMaggFam = elencoCodMaggFamiliari.FindAll(x => x.IdAnagrafica == fam.IdAnagrafica).OrderBy(x => x.Decorrenza).ToList();
                        if (LcodMaggFam != null && LcodMaggFam.Count > 0)
                        {
                            if (fam.IsConiugeOrUnitoCivile())
                            {
                                //Se la Sigla (FASIGLA) è = a “C” la Decorrenza Carico (FADACQ) deve
                                //essere uguale alla Decorrenza Originaria (RAU104) ovvero alla data di
                                //matrimonio se successiva alla Decorrenza Originaria ad eccezione delle
                                //Reversibilità (PDIRSUP = 1) dove è obbligatorio che sia uguale alla
                                //Decorrenza Originaria
                                if (pdirsup == 1)
                                {
                                    if (LcodMaggFam.FirstOrDefault().Decorrenza.HasValue)
                                    {
                                        if (!Utility.DataSuccessivaA(LcodMaggFam.FirstOrDefault().Decorrenza.Value, decorrenzaOriginaria) ||
                                            Utility.DataStrettamenteSuccessivaA(LcodMaggFam.FirstOrDefault().Decorrenza.Value, decorrenzaOriginaria))
                                        {
                                            messaggioVideo = "La data decorrenza carico deve essere pari alla decorrenza originaria";
                                            return false;
                                        }
                                    }
                                }
                                else
                                {
                                    GestioneFamiliari.CodMaggFamiliari codMaggFam = LcodMaggFam.FirstOrDefault();
                                    if (codMaggFam.Decorrenza.HasValue)
                                    {
                                        DateTime dataCompare = decorrenzaOriginaria;
                                        List<GestioneAnagrafica.DatiStatoCivile> LstCiv = elencoStatiCivili.FindAll(x => x.Codice == '2' || x.Codice == '7');
                                        if (LstCiv != null && LstCiv.Count > 0)
                                        {
                                            foreach (GestioneAnagrafica.DatiStatoCivile sC in LstCiv)
                                            {
                                                if (sC.Decorrenza.HasValue)
                                                {
                                                    if (Utility.DataStrettamenteSuccessivaA(sC.Decorrenza.Value, dataCompare) &&
                                                        (!Utility.IsRicostituzioneOrRiapertura(datiPensione, isRiaperturaDomanda) || !codMaggFam.Cessazione.HasValue || !Utility.DataSuccessivaA(sC.Decorrenza.Value, codMaggFam.Cessazione.Value)))
                                                    {
                                                        dataCompare = sC.Decorrenza.Value;
                                                    }
                                                }
                                            }
                                        }

                                        if (codMaggFam.Decorrenza.Value != dataCompare)
                                        {
                                            messaggioVideo = "La data decorrenza carico deve essere pari alla decorrenza originaria ovvero alla data di matrimonio se successiva alla decorrenza originaria";
                                            return false;
                                        }
                                    }
                                }

                                //Se la Sigla (FASIGLA) è = a “C” esaminare a Tabella dello Stato Civile
                                //(RASTATOCIV) e prendere l'eventuale Data presente (RASTDEC)
                                //successiva al Codice (RASTCIV) = a 2:
                                elencoStatiCivili.Sort(delegate
                                    (GestioneAnagrafica.DatiStatoCivile c1, GestioneAnagrafica.DatiStatoCivile c2)
                                { return c1.Decorrenza.Value.CompareTo(c2.Decorrenza); });
                                DateTime? dataVariazione = null;
                                bool presenteC = false;
                                DateTime? inizioC = null;
                                foreach (GestioneAnagrafica.DatiStatoCivile sC in elencoStatiCivili)
                                {
                                    if (presenteC)
                                    {
                                        dataVariazione = sC.Decorrenza;
                                        //se presente la Data variazione Stato Civile la Data Fine Carico
                                        //(FADACE) deve essere presente e deve essere uguale alla data della variazione
                                        if (dataVariazione.HasValue)
                                        {
                                            GestioneFamiliari.CodMaggFamiliari codMaggFam = LcodMaggFam.Last();
                                            if (codMaggFam.Decorrenza.HasValue && Utility.DataStrettamenteSuccessivaA(dataVariazione.Value, codMaggFam.Decorrenza.Value) &&
                                                inizioC.HasValue && Utility.DataSuccessivaA(codMaggFam.Decorrenza.Value, inizioC.Value))
                                            {
                                                if (!codMaggFam.Cessazione.HasValue || codMaggFam.Cessazione.Value != dataVariazione.Value)
                                                {
                                                    messaggioVideo = string.Format("La data fine carico deve essere presente e uguale alla data della variazione stato civile per il familiare {0}", fam.CodiceFiscale);
                                                    return false;
                                                }
                                            }
                                        }
                                    }

                                    if (sC.Codice == '2' || sC.Codice == '7')
                                    {
                                        presenteC = true;
                                        inizioC = sC.Decorrenza;
                                    }
                                    else
                                        presenteC = false;
                                }
                            }
                            else
                            {
                                if (Utility.IsDomandaVOAUT_IOAUT(datiPensione.SiglaCategoria))
                                {
                                    messaggioVideo = "Per le categorie pensione VOAUT e IOAUT i familiari ammessi sono coniuge e unito civile";
                                    return false;
                                }

                                if (Utility.IsDomandaVOSPED(datiPensione.SiglaCategoria) || Utility.IsDomandaIOSPED(datiPensione.SiglaCategoria))
                                {
                                    messaggioVideo = "Per le categorie pensione VOSPED e IOSPED i familiari ammessi sono coniuge e unito civile";
                                    return false;
                                }
                            }

                            foreach (GestioneFamiliari.CodMaggFamiliari c in LcodMaggFam)
                            {
                                if (c.Decorrenza.HasValue)
                                {
                                    //La Data Decorrenza Carico (FADACQ) deve essere superiore al mese della
                                    //data di nascita del soggetto
                                    if (Utility.IsDomandaPensioneSuperstitiOrRicostituzione(datiPensione))
                                    {
                                        if (!Utility.DataStrettamenteSuccessivaA(c.Decorrenza.Value, datiAnagrafici.DataNascita.Value))
                                        {
                                            messaggioVideo = "La data decorrenza carico deve essere superiore al mese della data di nascita del soggetto";
                                            return false;
                                        }
                                    }
                                    else
                                    {
                                        if (!Utility.DataSuccessivaA(c.Decorrenza.Value, Utility.FirstDayOfMonth(datiAnagrafici.DataNascita.Value)))
                                        {
                                            messaggioVideo = "La decorrenza carico non può essere precedente alla data nascita del soggetto";
                                            return false;
                                        }
                                    }

                                    switch (c.SiglaFamiliare.Value)
                                    {
                                        //Se la Sigla (FASIGLA) è = a “M”, “N”, “J”, “G”, “P” il familiare non deve avere
                                        //compiuto 18 anni alla Data Decorrenza Carico (FADACQ)
                                        case 'M':
                                        case 'N':
                                        case 'J':
                                        case 'G':
                                        case 'P':
                                            if (!Utility.DataSuccessivaA(datiAnagrafici.DataNascita.Value.AddYears(18), c.Decorrenza.Value))
                                            {
                                                messaggioVideo = "Il familiare non deve avere compiuto 18 anni alla data decorrenza carico";
                                                return false;
                                            }
                                            break;
                                        //Se la Sigla (FASIGLA) è = a “K” il familiare deve avere compiuto 18 anni alla
                                        //Data Decorrenza Carico (FADACQ)
                                        case 'K':
                                        case 'O':
                                        //Per le Categorie dirette (PDIRSUP = a zero) se la Sigla (FASIGLA) è = a “S”,
                                        //“Z”, “U”, “W” il familiare deve avere compiuto 18 anni alla Data Decorrenza
                                        //Carico (FADACQ)
                                        case 'S':
                                        case 'Z':
                                        case 'U':
                                            if (Utility.DataStrettamenteSuccessivaA(datiAnagrafici.DataNascita.Value.AddYears(18), c.Decorrenza.Value))
                                            {
                                                messaggioVideo = "Il familiare deve avere compiuto 18 anni alla data decorrenza carico";
                                                return false;
                                            }
                                            break;
                                        case 'W':
                                            if (Utility.DataStrettamenteSuccessivaA(datiAnagrafici.DataNascita.Value.AddYears(21), c.Decorrenza.Value))
                                            {
                                                messaggioVideo = "Il familiare deve avere compiuto 21 anni alla data decorrenza carico";
                                                return false;
                                            }
                                            break;
                                        //Per le Categorie di Reversibilità (PDIRSUP = a 1) il superstite con Sigla
                                        //(FASIGLA) = a “A” deve aver compiuto 65 anni alla data della Decorrenza
                                        //Originaria (RAU104)
                                        case 'A':
                                            if (pdirsup == 1)
                                            {
                                                if (Utility.DataStrettamenteSuccessivaA(datiAnagrafici.DataNascita.Value.AddYears(65), c.Decorrenza.Value))
                                                {
                                                    messaggioVideo = "Il familiare deve avere compiuto 65 anni alla data decorrenza carico";
                                                    return false;
                                                }
                                            }
                                            break;
                                        default:
                                            break;
                                    }

                                    //Se la Categoria (RACATEG) è = a “SOTOT”:
                                    if (siglaCategoria == "SOTOT")
                                    {
                                        switch (c.SiglaFamiliare.Value)
                                        {
                                            //se la Sigla (FASIGLA) è = a “X” il familiare deve avere compiuto 18
                                            //anni e non superato 23 anni alla data Data Decorrenza Carico
                                            //(FADACQ)
                                            case 'X':
                                                if (Utility.DataStrettamenteSuccessivaA(datiAnagrafici.DataNascita.Value.AddYears(18), c.Decorrenza.Value))
                                                {
                                                    messaggioVideo = "Il familiare deve avere compiuto 18 anni alla data decorrenza carico";
                                                    return false;
                                                }
                                                if (!Utility.DataSuccessivaA(datiAnagrafici.DataNascita.Value.AddYears(24), c.Decorrenza.Value))
                                                {
                                                    messaggioVideo = "Il familiare non deve avere superato 23 anni alla data decorrenza carico";
                                                    return false;
                                                }
                                                break;
                                            //se la Sigla (FASIGLA) è = a “B” il familiare deve avere compiuto 18
                                            //anni e non superato 21 anni alla data Data Decorrenza Carico
                                            //(FADACQ)
                                            case 'B':
                                                if (Utility.DataStrettamenteSuccessivaA(datiAnagrafici.DataNascita.Value.AddYears(18), c.Decorrenza.Value))
                                                {
                                                    messaggioVideo = "Il familiare deve avere compiuto 18 anni alla data decorrenza carico";
                                                    return false;
                                                }
                                                if (!Utility.DataSuccessivaA(datiAnagrafici.DataNascita.Value.AddYears(22), c.Decorrenza.Value))
                                                {
                                                    messaggioVideo = "Il familiare non deve avere superato 21 anni alla data decorrenza carico";
                                                    return false;
                                                }
                                                break;
                                            //se la Sigla (FASIGLA) è = a “D” il familiare deve avere compiuto 21
                                            //anni alla data Data Decorrenza Carico (FADACQ)
                                            case 'D':
                                                if (Utility.DataStrettamenteSuccessivaA(datiAnagrafici.DataNascita.Value.AddYears(21), c.Decorrenza.Value))
                                                {
                                                    messaggioVideo = "Il familiare deve avere compiuto 21 anni alla data decorrenza carico";
                                                    return false;
                                                }
                                                break;
                                            //se la Sigla (FASIGLA) è = a “S” il familiare non deve avere compiuto
                                            //21 anni alla data Data Decorrenza Carico (FADACQ)
                                            case 'S':
                                                if (!Utility.DataSuccessivaA(datiAnagrafici.DataNascita.Value.AddYears(21), c.Decorrenza.Value))
                                                {
                                                    messaggioVideo = "Il familiare non deve avere compiuto 21 anni alla data decorrenza carico";
                                                    return false;
                                                }
                                                break;
                                        }
                                    }
                                }

                                if (c.Cessazione.HasValue)
                                {
                                    //La Data Fine Carico (FADACE) non può essere superiore di 100 anni dalla
                                    //data del Sistema
                                    if (Utility.DataStrettamenteSuccessivaA(c.Cessazione.Value, dataSistema.AddYears(100)))
                                    {
                                        messaggioVideo = "La data fine carico non può essere superiore di 100 anni dalla data odierna";
                                        return false;
                                    }

                                    //La Data Fine Carico (FADACE) non può essere inferiore alla Data
                                    //Decorrenza Carico (FADACQ)
                                    if (c.Decorrenza.HasValue)
                                    {
                                        if (!Utility.DataStrettamenteSuccessivaA(c.Cessazione.Value, c.Decorrenza.Value))
                                        {
                                            messaggioVideo = "Per il familiare " + fam.CodiceFiscale + " la data fine carico non può essere inferiore alla data decorrenza carico";
                                            if (string.IsNullOrEmpty(cfFamiliareAttuale) || cfFamiliareAttuale == fam.CodiceFiscale)
                                                return false;
                                        }
                                    }

                                    //Se la Sigla (FASIGLA) è = a "M", "N", "J", "G", "P", "L", "S", "Z", "U", "W",,
                                    //"X","B", "D" ed è presente la Data Fine Carico (FADACE):
                                    switch (c.SiglaFamiliare.Value)
                                    {
                                        //se la Sigla (FASIGLA) è = a “M”, “N”, “J”, “G”, “P” la Data Fine Carico
                                        //(FADACE) non può essere successiva alla data del 18° anno del
                                        //familiare
                                        case 'M':
                                        case 'N':
                                        case 'J':
                                        case 'G':
                                        case 'P':
                                            if (Utility.DataStrettamenteSuccessivaA(c.Cessazione.Value, datiAnagrafici.DataNascita.Value.AddYears(18).AddMonths(1)))
                                            {
                                                messaggioVideo = "La data fine carico non può essere successiva alla data del 18° anno del familiare";
                                                return false;
                                            }
                                            break;
                                        //se la Sigla (FASIGLA) è = a “S”, “Z”, “B” la Data Fine Carico (FADACE)
                                        //non può essere successiva alla data del 21° anno del familiare
                                        case 'L':
                                        case 'S':
                                        case 'Z':
                                        case 'B':
                                            if (Utility.DataStrettamenteSuccessivaA(c.Cessazione.Value, datiAnagrafici.DataNascita.Value.AddYears(21).AddMonths(1)))
                                            {
                                                messaggioVideo = "La data fine carico non può essere successiva alla data del 21° anno del familiare";
                                                return false;
                                            }
                                            break;
                                        //se la Sigla (FASIGLA) è = a “X” la Data Fine Carico (FADACE) non può
                                        //essere successiva alla data del 23° anno del familiare
                                        case 'X':
                                            if (Utility.DataStrettamenteSuccessivaA(c.Cessazione.Value, datiAnagrafici.DataNascita.Value.AddYears(23)))
                                            {
                                                messaggioVideo = "La data fine carico non può essere successiva alla data del 23° anno del familiare";
                                                return false;
                                            }
                                            break;
                                        //se la Sigla (FASIGLA) è = a “U”, “W”, “D” la Data Fine Carico
                                        //(FADACE) non può essere successiva alla data del 26° anno del
                                        //familiare
                                        case 'U':
                                        case 'W':
                                        case 'D':
                                            if (Utility.DataStrettamenteSuccessivaA(c.Cessazione.Value, datiAnagrafici.DataNascita.Value.AddYears(26).AddMonths(1)))
                                            {
                                                messaggioVideo = "La data fine carico non può essere successiva alla data del 26° anno del familiare";
                                                return false;
                                            }
                                            break;
                                    }

                                }
                                else
                                {
                                    switch (c.SiglaFamiliare.Value)
                                    {
                                        case 'M':
                                        case 'N':
                                        case 'J':
                                        case 'S':
                                        case 'L':
                                        case 'B':
                                        case 'U':
                                        case 'D':
                                        case 'X':
                                            messaggioVideo = "La data fine carico deve essere presente";
                                            return false;
                                        default:
                                            break;
                                    }
                                }

                                //Se la Sigla (FASIGLA) è = a “G”, “P”, “Z”, “W” è obbligatorio inserire la Data
                                //Fine Carico (FADACE)
                                switch (c.SiglaFamiliare.Value)
                                {
                                    case 'G':
                                    case 'P':
                                    case 'Z':
                                    case 'W':
                                        if (!c.Cessazione.HasValue)
                                        {
                                            messaggioVideo = "E' obbligatorio inserire la data di fine carico";
                                            return false;
                                        }
                                        break;
                                    default:
                                        break;
                                }
                            }

                            foreach (GestioneFamiliari.CodMaggFamiliari c in LcodMaggFam.FindAll(x => x.SiglaFamiliare == fam.SiglaFamiliare && x.TipoUnione == fam.TipoUnione))
                            {
                                if (c.CodiceMaggiorazione.HasValue && c.CodiceMaggiorazione.Value != 0)   // SI o NO
                                {
                                    //Per le Categorie dirette (PDIRSUP = a zero) se la Sigla (FASIGLA) è diversa
                                    //da “C” il Codice Maggiorazione (FACODMAG) deve essere assente

                                    // controllo commentato a fronte della mail 'RE: Reeng Pensioni AGO - Stato Segnalazioni del Thu 4/9/2013 09:32'
                                    //if (pdirsup == 0)
                                    //{
                                    //    if (fam.SiglaFamiliare.Value != 'C')
                                    //    {
                                    //        messaggioVideo = "Il codice Maggiorazione deve essere assente";
                                    //        return false;
                                    //    }
                                    //}

                                    //Il seguente controllo deve essere effettuato solo se il Memo 33 non è abilitato perchè per le sigle familiari N e J deve essere prevista la valorizzazione del codice Maggiorazione SI/NO
                                    if (abilitazioneMemo33 == null || String.IsNullOrEmpty(abilitazioneMemo33.ValoreControllo) || String.IsNullOrEmpty(abilitazioneMemo33.ValoreControllo.Trim()) || abilitazioneMemo33.ValoreControllo.Trim().ToUpperInvariant() == "NO")
                                    {
                                        if (pdirsup == 0 && !Utility.IsDomandaSpacchettamentoENPALS(datiPensione) && !Utility.IsDomandaSpacchettamentoSOPGIPost072022(datiPensione, datiDanteCausa) && !Utility.IsDomandaSpacchettamentoSO(datiPensione, isRiaperturaDomanda)
                                            && !Utility.IsDomandaSpacchettamentoSOART(datiPensione, isRiaperturaDomanda) && !Utility.IsDomandaSpacchettamentoSOCOM(datiPensione, isRiaperturaDomanda) && !Utility.IsDomandaSpacchettamentoSR(datiPensione, isRiaperturaDomanda))
                                        {
                                            if (!fam.IsConiugeOrUnitoCivile())
                                            {
                                                messaggioVideo = "Il codice Maggiorazione deve essere valorizzato diversamente da SI e  da NO";
                                                return false;
                                            }
                                        }
                                    }

                                    //Per PDIRSUP = a 1 e le ENPALS se la Sigla (FASIGLA) è =
                                    //a “C”, “A”, “F” il Codice Maggiorazione (FACODMAG) deve essere assente
                                    if ((pdirsup == 1 && !Utility.IsDomandaPensioneSuperstitiOrRicostituzione(datiPensione) || Utility.IsDomandaSpacchettamentoENPALS(datiPensione) || Utility.IsDomandaSpacchettamentoSOPGIPost072022(datiPensione, datiDanteCausa) ||
                                        Utility.IsDomandaSpacchettamentoSO(datiPensione, isRiaperturaDomanda) || Utility.IsDomandaSpacchettamentoSOART(datiPensione, isRiaperturaDomanda) || Utility.IsDomandaSpacchettamentoSOCOM(datiPensione, isRiaperturaDomanda) || Utility.IsDomandaSpacchettamentoSR(datiPensione, isRiaperturaDomanda)) &&
                                        (fam.IsConiugeOrUnitoCivile() || fam.SiglaFamiliare.Value == 'A' || fam.SiglaFamiliare.Value == 'F') && !Utility.IsDomandaSOAUT(datiPensione.SiglaCategoria))
                                    {
                                        messaggioVideo = "Il codice Maggiorazione deve essere assente";
                                        return false;
                                    }
                                }
                                else // null o 0 = string.Empty
                                {
                                    if (!Utility.IsDomandaAUT(datiPensione) && !Utility.IsDomandaSPED(datiPensione) && !Utility.IsDomandaPescatori(datiPensione.SiglaCategoria) && !Utility.IsDomandaBancari(datiPensione.SiglaCategoria) &&
                                        !Utility.IsDomandaPSO(datiPensione.SiglaCategoria) && !Utility.IsDomandaPMO(datiPensione.SiglaCategoria))
                                    {
                                        //Per le Categorie di Reversibilità (PDIRSUP = a 1) se la Sigla (FASIGLA) è =
                                        //a "I", "M", "S", "U", "N", "J", "Z", "W", "K", "X", "B", "D" il Codice
                                        //Maggiorazione (FACODMAG) deve essere presente
                                        if (pdirsup == 1 || Utility.IsDomandaSpacchettamentoENPALS(datiPensione) || Utility.IsDomandaSpacchettamentoSOPGIPost072022(datiPensione, datiDanteCausa) ||
                                            Utility.IsDomandaSpacchettamentoSO(datiPensione, isRiaperturaDomanda) || Utility.IsDomandaSpacchettamentoSOART(datiPensione, isRiaperturaDomanda) || Utility.IsDomandaSpacchettamentoSOCOM(datiPensione, isRiaperturaDomanda)
                                            || Utility.IsDomandaSpacchettamentoSR(datiPensione, isRiaperturaDomanda))
                                        {
                                            switch (fam.SiglaFamiliare.Value)
                                            {
                                                case 'I':
                                                case 'M':
                                                case 'S':
                                                case 'U':
                                                case 'N':
                                                case 'J':
                                                case 'Z':
                                                case 'W':
                                                case 'K':
                                                case 'O':
                                                case 'X':
                                                case 'B':
                                                case 'D':
                                                    messaggioVideo = "Il codice Maggiorazione deve essere presente";
                                                    return false;
                                                default:
                                                    break;
                                            }
                                        }
                                        else if (pdirsup == 0 && !Utility.IsDomandaSpacchettamentoENPALS(datiPensione) && !Utility.IsDomandaSpacchettamentoSOPGIPost072022(datiPensione, datiDanteCausa)
                                            && !Utility.IsDomandaSpacchettamentoSO(datiPensione, isRiaperturaDomanda) && !Utility.IsDomandaSpacchettamentoSOART(datiPensione, isRiaperturaDomanda) && !Utility.IsDomandaSpacchettamentoSOCOM(datiPensione, isRiaperturaDomanda)
                                            && !Utility.IsDomandaSpacchettamentoSR(datiPensione, isRiaperturaDomanda))
                                        {
                                            if (!Utility.IsDomandaVOCOOP_COOP28(siglaCategoria) && !Utility.IsDomandaVOCRED_CRED27(siglaCategoria) && !Utility.IsDomandaVOESO(datiPensione.SiglaCategoria) &&
                                                !Utility.IsDomandaAPESociale(datiPensione.SiglaCategoria) && !Utility.IsDomandaINDCOM(datiPensione.SiglaCategoria) &&
                                                !Utility.IsRenditaCasalinghe(datiPensione) && !Utility.IsRenditaFacoltativa(datiPensione) &&
                                                fam.IsConiugeOrUnitoCivile())
                                            {
                                                messaggioVideo = "Il codice Maggiorazione del pannello familiari deve essere valorizzato a SI o a NO";
                                                return false;
                                            }
                                        }
                                    }
                                }

                                if (c.Decorrenza.HasValue)
                                {
                                    if (!fam.IsConiugeOrUnitoCivile())
                                    {
                                        //Se la Sigla (FASIGLA) è diversa da “C” la Decorrenza Carico (FADACQ) non
                                        //può essere inferiore alla Decorrenza Originaria (RAU104)
                                        if (!Utility.DataSuccessivaA(c.Decorrenza.Value, decorrenzaOriginaria))
                                        {
                                            messaggioVideo = "La data decorrenza carico non può essere inferiore alla decorrenza originaria";
                                            return false;
                                        }
                                    }

                                    //La Data Decorrenza Carico (FADACQ) non può essere superiore alla data
                                    //del Sistema più un mese
                                    if (fam.SiglaFamiliare != 'N' &&
                                        Utility.DataStrettamenteSuccessivaA(c.Decorrenza.Value, dataSistema.AddMonths(1)))
                                    {
                                        messaggioVideo = "La data decorrenza carico non può essere superiore alla data odierna più un mese";
                                        return false;
                                    }

                                    //Per le Categorie di Reversibilità (PDIRSUP = a 1) la Data Decorrenza Carico
                                    //(FADACQ) deve essere successiva al 31 dicembre 1964
                                    if (pdirsup == 1 && !(Utility.IsRicostituzione(datiPensione.Gruppo) && Utility.IsDomandaPMO(datiPensione.SiglaCategoria)) &&
                                        !(Utility.IsDomandaAnte96(datiPensione, datiPensione, datiDanteCausa, isRiaperturaDomanda) != null && Utility.IsRicostituzione(datiPensione.Gruppo)))
                                    {
                                        if (!Utility.DataStrettamenteSuccessivaA(c.Decorrenza.Value, new DateTime(1964, 12, 31)))
                                        {
                                            messaggioVideo = "La data decorrenza carico deve essere successiva al 31 dicembre 1964";
                                            return false;
                                        }
                                    }
                                }

                                //Se la Sigla (FASIGLA) è = a “C” esaminare a Tabella dello Stato Civile
                                //(RASTATOCIV) e prendere l'eventuale Data presente (RASTDEC)
                                //successiva al Codice (RASTCIV) = a 2:
                                if (fam.IsConiugeOrUnitoCivile())
                                {
                                    elencoStatiCivili.Sort(delegate
                                        (GestioneAnagrafica.DatiStatoCivile c1, GestioneAnagrafica.DatiStatoCivile c2)
                                    { return c1.Decorrenza.Value.CompareTo(c2.Decorrenza); });
                                    DateTime? dataVariazione = null;
                                    bool presenteC = false;
                                    foreach (GestioneAnagrafica.DatiStatoCivile sC in elencoStatiCivili)
                                    {
                                        if (presenteC)
                                            dataVariazione = sC.Decorrenza;

                                        if (sC.Codice == '2' || sC.Codice == '7')
                                            presenteC = true;
                                        else
                                            presenteC = false;
                                    }

                                    //se non è presente la Data variazione Stato Civile per le Categorie di
                                    //Reversibilità (PDIRSUP = a 1) esaminare se si è nel 2° elemento della
                                    //Tabella Familiari (FATAB) con la Sigla (FASIGLA) = a “C” e il 1°
                                    //elemento della Tabella Familiari (FATAB) non ha la Sigla (FASIGLA) =
                                    //a “C”: in questo caso il Codice Maggiorazione (FACODMAG) deve
                                    //essere assente e la Data Fine Carico (FADACE) deve essere presente
                                    //e non può essere maggiore della data del Sistema
                                    if (!dataVariazione.HasValue)
                                    {
                                        if (pdirsup == 1)
                                        {
                                            // la sigla familiare = 'C' è verificata sopra
                                            if (fam.TipoComponente != 'T' && Lfamiliare.Exists(x => x.TipoComponente == 'T') && !Lfamiliare.FirstOrDefault(x => x.TipoComponente == 'T').IsConiugeOrUnitoCivile())
                                            {
                                                if (c.CodiceMaggiorazione.HasValue && c.CodiceMaggiorazione.Value != 0 && !Utility.IsDomandaSOAUT(datiPensione.SiglaCategoria))
                                                {
                                                    messaggioVideo = "Il codice maggiorazione deve essere assente";
                                                    return false;
                                                }
                                                if (!c.Cessazione.HasValue || Utility.DataStrettamenteSuccessivaA(c.Cessazione.Value, dataSistema.AddMonths(1)))
                                                {
                                                    messaggioVideo = "La data fine carico deve essere presente e non può essere maggiore della data odierna + 1 mese";
                                                    return false;
                                                }
                                            }
                                        }
                                    }
                                }

                                if (c.Cessazione.HasValue)
                                {
                                    //Se la Sigla (FASIGLA) è diversa da “C” ed è presente la Data Ripristino
                                    //(RAU105) la Data Fine Carico (FADACE) non può essere inferiore alla Data
                                    //Ripristino (RAU105)
                                    if (!Utility.IsRicostituzione(datiPensione.Gruppo) && !fam.IsConiugeOrUnitoCivile() && datiPensione.DataInizioCalcolo.HasValue && !Utility.IsDomandaRipristinoOrRiliquidazione(datiPensione))
                                    {
                                        if (!Utility.DataSuccessivaA(c.Cessazione.Value, datiPensione.DataInizioCalcolo.Value))
                                        {
                                            messaggioVideo = "La data fine carico non può essere inferiore alla data ripristino";
                                            return false;
                                        }
                                    }
                                }
                            }
                        }
                        else
                        {
                            //Per le Categorie di Reversibilità (PDIRSUP = a 1) se la Sigla (FASIGLA) è =
                            //a "I", "M", "S", "U", "N", "J", "Z", "W", "K", "X", "B", "D" il Codice
                            //Maggiorazione (FACODMAG) deve essere presente
                            if (!Utility.IsDomandaAUT(datiPensione) && !Utility.IsDomandaSPED(datiPensione))
                            {
                                if (pdirsup == 1)
                                {
                                    switch (fam.SiglaFamiliare.Value)
                                    {
                                        case 'I':
                                        case 'M':
                                        case 'S':
                                        case 'U':
                                        case 'N':
                                        case 'J':
                                        case 'Z':
                                        case 'W':
                                        case 'K':
                                        case 'O':
                                        case 'X':
                                        case 'B':
                                        case 'D':
                                            messaggioVideo = "Il codice Maggiorazione deve essere presente";
                                            return false;
                                        default:
                                            break;
                                    }
                                }
                            }
                        }

                        if (fam.ScadenzaRevisioneSanitaria.HasValue)
                        {
                            //Per la Categoria (RACATEG) = a "INDCOM", "VOBIS", "IOBIS", "VMP",
                            //"IMP", "VOSPED", "IOSPED", "SOSPED", "VOCRED", "VOCOOP",
                            //"VOAUT", "IOAUT ", "SOAUT”,(“VOESO” con il Codice Banca
                            //(RACODBAN4) diverso da “99”) la Data Scadenza Revisione Sanitaria
                            //(FAREVSAN) deve essere assente
                            switch (siglaCategoria)
                            {
                                case "INDCOM":
                                case "VOBIS":
                                case "IOBIS":
                                case "VMP":
                                case "IMP":
                                case "VOSPED":
                                case "IOSPED":
                                case "SOSPED":
                                case "VOCRED":
                                case "CRED27":
                                case "VOCOOP":
                                case "VOAUT":
                                case "IOAUT":
                                case "SOAUT":
                                case "VESO92":
                                case "VESO33":
                                case "COOP28":
                                case "ESPA":
                                    messaggioVideo = "La data scadenza revisione sanitaria deve essere assente";
                                    return false;
                                case "VOESO":
                                    if (!datiPensione.CodiceBancaEsodati.HasValue || datiPensione.CodiceBancaEsodati.Value != 99)
                                    {
                                        messaggioVideo = "La data scadenza revisione sanitaria deve essere assente";
                                        return false;
                                    }
                                    break;
                                default:
                                    break;
                            }

                            //La Data Scadenza Revisione Sanitaria (FAREVSAN) può essere presente
                            //solo per i familiari con Sigla (FASIGLA) = a “I”, “C
                            if (!fam.IsConiugeOrUnitoCivile() && fam.SiglaFamiliare.Value != 'I')
                            {
                                messaggioVideo = "La data scadenza revisione sanitaria può essere presente solo per i familiari con sigla pari a I o pari a C";
                                return false;
                            }
                            //La Data Scadenza Revisione Sanitaria (FAREVSAN) non può essere
                            //inferiore alla Data del Sistema
                            DateTime dataOdierna = new DateTime(dataSistema.Year, dataSistema.Month, 1);
                            if (!Utility.DataSuccessivaA(fam.ScadenzaRevisioneSanitaria.Value, dataOdierna))
                            {
                                messaggioVideo = "La data scadenza revisione sanitaria non può essere inferiore alla data odierna";
                                return false;
                            }
                        }
                    }

                    //Se la Categoria (RACATEG) è = a "INDCOM", "VOBIS", "IOBIS", "VMP",
                    //"IMP", "VOAUT", "IOAUT", "VOCRED", "VOCOOP", (“VOESO” con il Codice
                    //Banca (RACODBAN4) diverso da “99”) si può acquisire un solo familiare che
                    //sia il Coniuge, quindi con il Codice Sigla (FASIGLA) = a “C”
                    switch (siglaCategoria)
                    {
                        case "VOESO":
                            if (!datiPensione.CodiceBancaEsodati.HasValue || datiPensione.CodiceBancaEsodati.Value != 99)
                            {
                                if (Lfamiliare.Count(x => x.Confermato && x.SiglaFamiliare.HasValue) > 1 ||
                                    (Lfamiliare.Count(x => x.Confermato && x.SiglaFamiliare.HasValue) > 0 && !Lfamiliare.First(x => x.Confermato && x.SiglaFamiliare.HasValue).IsConiugeOrUnitoCivile()))
                                {
                                    messaggioVideo = "E' possibile acquisire un solo familiare di tipo 'Coniuge' o 'Unito/a Civilmente'.";
                                    return false;
                                }
                            }
                            break;
                    }

                    if (pdirsup == 1)
                    {
                        //Per le Categorie di Reversibilità (PDIRSUP = a 1) non possono essere
                        //presenti in Tabella Familiari (FATAB) contemporaneamente le Sigle
                        //(FASIGLA) “A” e “F”; inoltre se presente un superstite con Sigla (FASIGLA) =
                        //a “A” o “F” non possono essere presenti superstiti con sigle diverse
                        if (Lfamiliare.Find(x => x.SiglaFamiliare.HasValue && x.SiglaFamiliare.Value == 'A') != null &&
                            Lfamiliare.Find(x => x.SiglaFamiliare.HasValue && x.SiglaFamiliare.Value == 'F') != null)
                        {
                            messaggioVideo = "Non possono essere presenti contemporaneamente le sigle A ed F";
                            return false;
                        }
                        if (Lfamiliare.Find(x => x.SiglaFamiliare.HasValue && (x.SiglaFamiliare.Value == 'A' || x.SiglaFamiliare.Value == 'F')) != null &&
                            Lfamiliare.Find(x => x.SiglaFamiliare.HasValue && x.SiglaFamiliare.Value != 'A' && x.SiglaFamiliare.Value != 'F') != null)
                        {
                            messaggioVideo = "Se presente un superstite con sigla pari ad A o pari ad F, non possono essere presenti superstiti con sigle diverse";
                            return false;
                        }
                    }

                    if (siglaCategoria == "VOCUM" && cumuloEsterno.GetValueOrDefault() == 'M')
                    {
                        if (elencoCodMaggFamiliari.Exists(x => x.IdAnagrafica == fam.IdAnagrafica && x.CodiceMaggiorazione.GetValueOrDefault() == 2))
                        {
                            messaggioVideo = string.Format("Non è possibile acquisire il codice maggiorazione a SI per il familiare {0}", fam.CodiceFiscale);
                            return false;
                        }
                    }

                    if (Utility.IsRicostituzioneOrRiapertura(datiPensione, isRiaperturaDomanda))
                    {
                        List<GestioneFamiliari.CodMaggFamiliari> LcodMaggFam = elencoCodMaggFamiliari.FindAll(x => x.IdAnagrafica == fam.IdAnagrafica).OrderBy(x => x.Decorrenza).ToList();
                        if (LcodMaggFam != null && LcodMaggFam.Count > 0)
                        {
                            bool wasNotConiugeOrUnitoCivilmente = false;
                            foreach (var codMaggFam in LcodMaggFam)
                            {
                                if (wasNotConiugeOrUnitoCivilmente && codMaggFam.SiglaFamiliare == 'C')
                                {
                                    messaggioVideo = "Non è possibile variare la relazione familiare in Coniuge o Unito/a Civilmente";
                                    return false;
                                }

                                if (codMaggFam.SiglaFamiliare != 'C')
                                    wasNotConiugeOrUnitoCivilmente = true;
                            }
                        }
                    }
                }
            }

            return true;
        }

        public static bool AGO_VerificaStatiCiviliConDataMorteFamiliari(List<GestioneAnagrafica.DatiStatoCivile> elencoStatiCivili,
            List<GestioneFamiliari.Familiare> Lfamiliare, List<GestioneFamiliari.CodMaggFamiliari> listaCodMaggFamiliari, out string messaggioVideo)
        {
            messaggioVideo = string.Empty;
            if (Lfamiliare != null && Lfamiliare.Count > 0 && elencoStatiCivili != null && elencoStatiCivili.Count > 0 &&
                elencoStatiCivili.Any(x => x.Codice == '3' || x.Codice == 'C') && elencoStatiCivili.Any(x => x.Codice == '2' || x.Codice == '7') &&
                Lfamiliare.Count(x => x.IsConiugeOrUnitoCivile()) == elencoStatiCivili.Count(x => x.Codice == '2' || x.Codice == '7'))
            {
                List<GestioneDecodifica.StatoCivile> elencoDecStatiCivili = null;
                GestioneDecodifica.GetStatiCivili(out elencoDecStatiCivili);

                DateTime? decorrenzaConiugato = null;
                string strErrore = "Attenzione: E' presente un'incongruenza tra {0} e lo stato civile '{1}' con decorrenza '{2}'.";
                foreach (var statoCivile in elencoStatiCivili)
                {
                    if ((statoCivile.Codice == '3' || statoCivile.Codice == 'C') && decorrenzaConiugato.HasValue)
                    {
                        if (Lfamiliare.Any(x => x.IsConiugeOrUnitoCivile() && x.DataMorte.HasValue) &&
                            !Lfamiliare.Any(x => x.IsConiugeOrUnitoCivile() && x.DataMorte.HasValue && statoCivile.Decorrenza.Value == Utility.FirstDayOfMonth(x.DataMorte.Value.AddMonths(1)) &&
                                                 (listaCodMaggFamiliari == null || listaCodMaggFamiliari.Count == 0 || listaCodMaggFamiliari.Count(y => x.IdAnagrafica == x.IdAnagrafica) == 0 ||
                                                  listaCodMaggFamiliari.Any(y => y.IdAnagrafica == x.IdAnagrafica && y.Decorrenza == decorrenzaConiugato))))
                        {
                            string strDataMorte = string.Empty;

                            if (Lfamiliare.Count(x => x.IsConiugeOrUnitoCivile() && x.DataMorte.HasValue) > 1)
                                strDataMorte = string.Format("le date di morte ({0}) dei Coniugi/Uniti Civilmente", string.Join("; ", Lfamiliare.FindAll(x => x.IsConiugeOrUnitoCivile() && x.DataMorte.HasValue).Select(x => x.DataMorte.Value.ToString("dd/MM/yyyy")).ToArray()));
                            else
                                strDataMorte = string.Format("la data di morte ({0}) del Coniuge/Unito Civilmente", Lfamiliare.FirstOrDefault(x => x.IsConiugeOrUnitoCivile() && x.DataMorte.HasValue).DataMorte.Value.ToString("dd/MM/yyyy"));

                            messaggioVideo = string.Format(strErrore, strDataMorte, elencoDecStatiCivili.FirstOrDefault(x => x.Id == statoCivile.Codice).Descrizione, statoCivile.Decorrenza.Value.ToString("MM/yyyy"));
                            return false;
                        }

                        decorrenzaConiugato = null;
                    }

                    if (statoCivile.Codice == '2' || statoCivile.Codice == '7')
                    {
                        if (!Lfamiliare.Any(x => x.IsConiugeOrUnitoCivile() && (listaCodMaggFamiliari == null || listaCodMaggFamiliari.Count == 0 || listaCodMaggFamiliari.Count(y => x.IdAnagrafica == x.IdAnagrafica) == 0 ||
                                                 listaCodMaggFamiliari.Any(y => y.IdAnagrafica == x.IdAnagrafica && y.Decorrenza == statoCivile.Decorrenza))))
                        {
                            string strDecorrenzaErrata = string.Empty;
                            string[] listaDecorrenze = listaCodMaggFamiliari.Where(x => Lfamiliare.Any(y => y.IdAnagrafica == x.IdAnagrafica && y.IsConiugeOrUnitoCivile())).GroupBy(x => x.IdAnagrafica).Select(x => x.FirstOrDefault()).Where(x => !elencoStatiCivili.Any(z => z.Decorrenza == x.Decorrenza)).Select(x => x.Decorrenza.Value.ToString("MM/yyyy")).ToArray();
                            if (listaDecorrenze.Count() > 1)
                                strDecorrenzaErrata = string.Format("le decorrenze carico ({0}) dei Coniugi/Uniti Civilmente", string.Join("; ", listaDecorrenze));
                            else if (listaDecorrenze.Count() == 1)
                                strDecorrenzaErrata = string.Format("la decorrenza carico ({0}) del Coniuge/Unito Civilmente", listaDecorrenze[0]);
                            else
                                strDecorrenzaErrata = "la decorrenza carico del Coniuge/Unito Civilmente";

                            messaggioVideo = string.Format(strErrore, strDecorrenzaErrata, elencoDecStatiCivili.FirstOrDefault(x => x.Id == statoCivile.Codice).Descrizione, statoCivile.Decorrenza.Value.ToString("MM/yyyy"));
                            return false;
                        }

                        decorrenzaConiugato = statoCivile.Decorrenza;
                    }
                }
            }
            return true;
        }

        public static bool AGO_VerificaPresenzaFamiliariInAventiDiritto(string cfFamiliareAttuale, GestionePensione.DatiPensione datiPensione, Utility.TipoAppartenenza? tipoAppartenenza,
            List<GestioneFamiliari.Familiare> listaFamiliari, List<GestioneAventiDiritto.AventiDiritto> listaAventiDiritto,
            GestioneAnagrafica.DatiAnagrafici datiAnagraficiTitolare, List<GestioneFamiliari.CodMaggFamiliari> listaCodMaggFamiliari, GestioneDanteCausa.DatiDanteCausa danteCausa, out string messaggioVideo)
        {
            messaggioVideo = string.Empty;
            string msg = string.Empty;

            if (tipoAppartenenza != Utility.TipoAppartenenza.AGO || (!Utility.IsDomandaSpacchettamentoENPALS(datiPensione) && !Utility.IsDomandaSpacchettamentoSOPGIPost072022(datiPensione, danteCausa) && !Utility.IsDomandaSpacchettamentoSO(datiPensione, Utility.IsRiaperturaDomanda(datiPensione.Id))
                && !Utility.IsDomandaSpacchettamentoSOART(datiPensione, Utility.IsRiaperturaDomanda(datiPensione.Id)) && !Utility.IsDomandaSpacchettamentoSOCOM(datiPensione, Utility.IsRiaperturaDomanda(datiPensione.Id)) && !Utility.IsDomandaSpacchettamentoSR(datiPensione, Utility.IsRiaperturaDomanda(datiPensione.Id))))
                return true;

            if (datiAnagraficiTitolare == null)
            {
                messaggioVideo = "Dati Familiari: Dati Anagrafici del Titolare non presenti";
                return false;
            }

            if (listaFamiliari != null && listaFamiliari.Count > 0 && listaAventiDiritto != null && listaAventiDiritto.Count > 0)
            {
                GestioneAventiDiritto.AventiDiritto datiAventeDirittoTit = listaAventiDiritto.FirstOrDefault(x => x.IdAnagrafica == datiAnagraficiTitolare.Id);
                if (datiAventeDirittoTit == null)
                {
                    messaggioVideo = "Dati Familiari: Non sono presenti i dati sull'avente diritto Titolare";
                    return false;
                }

                List<GestioneFamiliari.Familiare> listaFamiliApp = listaFamiliari.FindAll(x => !listaAventiDiritto.Any(y => y.IdAnagrafica == x.IdAnagrafica));
                if (listaFamiliApp != null && listaFamiliApp.Count > 0)
                {
                    if (datiAventeDirittoTit.DecParentelaDA == 'C')
                    {
                        msg = "Dati Familiari: Non è possibile inserire il familiare {0} in quanto non presente tra gli Aventi Diritto";
                        if (listaFamiliApp.Count > 1)
                            msg = "Dati Familiari: Non è possibile inserire i familiari {0} in quanto non presenti tra gli Aventi Diritto";
                        messaggioVideo = string.Format(msg, string.Join(", ", listaFamiliApp.Select(x => x.CodiceFiscale).ToArray()));
                        return !listaFamiliApp.Exists(x => x.CodiceFiscale == cfFamiliareAttuale);
                    }

                    if (listaFamiliApp.Exists(x => !x.IsConiugeOrUnitoCivile()))
                    {
                        msg = "Dati Familiari: Non è possibile inserire il familiare {0} con parentela con il Titolare diversa da 'Coniuge' o 'Unito/a Civilmente'";
                        if (listaFamiliApp.Count(x => !x.IsConiugeOrUnitoCivile()) > 1)
                            msg = "Dati Familiari: Non è possibile inserire i familiari {0} con parentela con il Titolare diversa da 'Coniuge' o 'Unito/a Civilmente'";
                        messaggioVideo = string.Format(msg, string.Join(", ", listaFamiliApp.Where(x => !x.IsConiugeOrUnitoCivile()).Select(x => x.CodiceFiscale).ToArray()));
                        return !listaFamiliApp.FindAll(x => !x.IsConiugeOrUnitoCivile()).Exists(x => x.CodiceFiscale == cfFamiliareAttuale);
                    }

                    if (listaFamiliApp.FindAll(x => x.IsConiugeOrUnitoCivile()).Exists(x => listaCodMaggFamiliari.Any(y => y.IdAnagrafica == x.IdAnagrafica && y.CodiceMaggiorazione == 1)))
                    {
                        List<string> listaCFFamiliari = listaFamiliApp.FindAll(x => x.IsConiugeOrUnitoCivile()).Where(x => listaCodMaggFamiliari.Any(y => y.IdAnagrafica == x.IdAnagrafica && y.CodiceMaggiorazione == 1)).Select(x => x.CodiceFiscale).ToList();
                        msg = "Dati Familiari: Per il soggetto {0} il codice maggiorazione deve essere NO";
                        if (listaCFFamiliari.Count > 1)
                            msg = "Dati Familiari: Per i soggetti {0} il codice maggiorazione deve essere NO";
                        messaggioVideo = string.Format(msg, string.Join(", ", listaCFFamiliari.ToArray()));
                    }
                }
            }
            return true;
        }
        #endregion Familiari

        #region Supplementi
        public static bool AGO_VerificaDecorrenzaSupplemento(List<BLCommon.Entity.DatiSupplementi> listaSupplementi, GestionePensione.DatiPensione datiPensione,
           out string messaggioVideo)
        {
            messaggioVideo = string.Empty;
            if (Utility.IsDomandaRiliquidazioneIndiretta(datiPensione) && Utility.IsDomandaSO(datiPensione.SiglaCategoria))
            {
                if (listaSupplementi != null)
                {
                    foreach (var sup in listaSupplementi)
                    {
                        if (sup.DecorrenzaSupplemento.HasValue)
                        {
                            if (DateTime.Compare(sup.DecorrenzaSupplemento.Value, datiPensione.DecorrenzaOriginaria.Value) != 0)
                            {
                                messaggioVideo = "Per tutte le registrazioni la decorrenza del supplemento deve essere uguale alla decorrenza pensione";
                                return false;
                            }
                        }
                    }
                }
            }
            else if (Utility.IsDomandaRiliquidazioneIndiretta(datiPensione))
            {
                if (listaSupplementi != null)
                {
                    foreach (var sup in listaSupplementi)
                    {
                        if (sup.DecorrenzaSupplemento.HasValue)
                        {
                            if (Utility.DataStrettamenteSuccessivaA(sup.DecorrenzaSupplemento.Value, datiPensione.DecorrenzaOriginaria.Value))
                            {
                                messaggioVideo = "Per tutte le registrazioni la decorrenza del supplemento deve essere inferiore o uguale alla decorrenza pensione";
                                return false;
                            }
                        }
                    }
                }
            }

            return true;
        }
        public static bool AGO_VerificaSupplementi(List<BLCommon.Entity.DatiSupplementi> listaSupplementi, GestionePensione.DatiPensione datiPensione,
            out string messaggioVideo)
        {
            messaggioVideo = string.Empty;
            DateTime dataSistema = GestioneControlliDinamici.GetDataSistema(Utility.GetTipoAppartenenza(datiPensione.IndConvInt, datiPensione.Gestione));
            string siglaCategoria = string.Empty;
            DateTime decorrenzaOriginaria = DateTime.MinValue;
            string certificato = string.Empty;
            string filtro = string.Empty;
            int pdirsup = 0;
            char codNat1 = ' ';
            char codNat2 = ' ';
            char codNat3 = ' ';

            #region Recupero Dati
            if (datiPensione == null)
            {
                messaggioVideo = "Dati pensione non disponibili";
                return false;
            }

            filtro = datiPensione.GetFiltro();
            Utility.GetCodiciNatura(datiPensione.NaturaPensione, out codNat1, out codNat2, out codNat3);
            siglaCategoria = datiPensione.SiglaCategoria.Trim().ToUpperInvariant();

            certificato = datiPensione.NCertificato.HasValue ? datiPensione.NCertificato.Value.ToString().PadLeft(8, '0') : "00000000";
            decorrenzaOriginaria = datiPensione.DecorrenzaOriginaria.HasValue ? datiPensione.DecorrenzaOriginaria.Value : DateTime.MinValue;

            Utility.TipoDomanda tipoDomanda = Utility.GetTipoDomanda(datiPensione.Gruppo, datiPensione.Prodotto);

            if (Utility.IsDomandaPensioneSuperstitiOrRicostituzione(datiPensione) ||
              (siglaCategoria == "PMO" && (certificato.Substring(2, 1) == "3" || certificato.Substring(2, 1) == "6")))
                pdirsup = 1;

            GestioneDanteCausa.DatiDanteCausa datiDA = null;
            GestioneDanteCausa.GetDanteCausabyIdPensione(datiPensione.Id, out datiDA);

            byte codProv = 0;
            if (datiDA != null)
                codProv = datiDA.ProvenienzaPensione.HasValue ? datiDA.ProvenienzaPensione.Value : (byte)0;

            GestioneAnagrafica.DatiAnagrafici datiAnagraficiTitolare = null;
            GestioneAnagrafica.GetAnagraficaByIdPensione(datiPensione.Id, out datiAnagraficiTitolare);

            GestioneAnagrafica.DatiAnagrafici datiAnagraficiDC = null;
            if (datiDA != null)
                GestioneAnagrafica.GetAnagraficaByIdAnagrafica(datiDA.IdAnagrafica, out datiAnagraficiDC);

            Utility.TipoCalcolo tipoCalcolo = Utility.GetTipoCalcolo(datiPensione);

            // Escludo la quota fittizia dai controlli
            List<BLCommon.Entity.DatiSupplementi> listaSupplementiSenzaQuotaFittizia = listaSupplementi != null ?
                listaSupplementi.FindAll(x => !((x.RMSSupplemento == 0.004M || x.RMSSupplemento == 0.0005M) && x.NSettimaneSupplemento == 1)) : null;

            //ENG - MEMO 50/2023
            bool isMemo50 = false;
            GestioneControlliDinamici.ControlloDinamico ctrlAbilitazioneMemo50_2023 = null;
            GestioneControlliDinamici.GetControlloDinamicoByNomeControllo("AbilitazioneMemo50_2023", out ctrlAbilitazioneMemo50_2023);
            if ((ctrlAbilitazioneMemo50_2023 != null && ctrlAbilitazioneMemo50_2023.ValoreControllo == "SI" && Utility.IsRicostituzione_Supplemento(datiPensione)) || Utility.IsRicostituzione_PerVariazioneDatiSupplemento(datiPensione))
                isMemo50 = true;

            #endregion Recupero Dati

            if (!Utility.IsDomandaRiliquidazioneIndiretta(datiPensione))
            {
                if (listaSupplementi != null)
                {
                    foreach (var sup in listaSupplementi)
                    {
                        if (sup.DecorrenzaSupplemento.HasValue)
                        {
                            //la Data Decorrenza Supplementi (VSDEC) non può essere superiore a quella
                            //del Sistema più 1 mese
                            if (Utility.DataStrettamenteSuccessivaA(sup.DecorrenzaSupplemento.Value, dataSistema.AddMonths(1)))
                            {
                                messaggioVideo = "La decorrenza supplementi non può essere superiore alla data odierna + 1 mese" + GetDescrizioneSupplemento(sup);
                                return false;
                            }
                        }
                    }
                }

                if (listaSupplementiSenzaQuotaFittizia != null)
                {
                    int i = 0;
                    GestioneControlliDinamici.ControlloDinamico ctrl = null;
                    GestioneControlliDinamici.GetControlloDinamicoByNomeControllo("AbilitazioneRilascioRIC_31082020", out ctrl);

                    if (Utility.IsDomandaBancari(siglaCategoria))
                    {
                        if (listaSupplementi.Where(x => !x.QuotaSupplemento.HasValue && x.TipoSupplemento == 'R').ToList().Any())
                        {
                            messaggioVideo = "Quota obbligatoria";
                            return false;
                        }

                        if ((listaSupplementi.GroupBy(x => new { x.DecorrenzaSupplemento, x.QuotaSupplemento, x.CodGestioneSupplemento })).ToList().Where(y => y.Count() > 1).Any())
                        {
                            messaggioVideo = "Non è ammesso lo stesso codice gestione per più registrazioni dello stesso supplemento";
                            return false;
                        }
                    }

                    foreach (BLCommon.Entity.DatiSupplementi sup in listaSupplementiSenzaQuotaFittizia)
                    {
                        if (Utility.IsDomandaAUT(datiPensione) && sup.CodGestioneSupplemento != "G" && !GestioneBypassControllo.CheckAndLockBypassControlloByNomeBypass(datiPensione, GestioneBypassControllo.NomeBypass.Titolare_Anagrafica_AGO.APPLICAZIONE_SENTENZA_VOAUT))
                        {
                            messaggioVideo = "L'unico codice Gestione ammesso è G";
                            return false;
                        }

                        //i Codici Gestione Supplementi (VSGES) ammessi sono “1”, “2”, “3”, “4”, “5”,
                        //“6”, “7”, “8”, “H”, “I”, “M”, “N”
                        switch (sup.CodGestioneSupplemento)
                        {
                            case "1":
                            case "2":
                            case "3":
                            case "4":
                            case "5":
                            case "6":
                            case "7":
                            case "8":
                            case "G":
                            case "I":
                            case "M":
                            case "N":
                                if (Utility.IsDomandaINPDAI(siglaCategoria))
                                {
                                    if (sup.CodGestioneSupplemento == "5" || sup.CodGestioneSupplemento == "6" || sup.CodGestioneSupplemento == "7" || sup.CodGestioneSupplemento == "8" || sup.CodGestioneSupplemento == "G" || sup.CodGestioneSupplemento == "H")
                                    {
                                        messaggioVideo = "I codici Gestione ammessi sono 1, 2, 3, 4, A, I, M, N";
                                        return false;
                                    }
                                }
                                break;
                            //se il Campo DO-NOTE = a "RAL", "R22", "R23", "R24", "R25", "R44", "R45" i
                            //Codici Gestione Supplementi (VSGES) ammessi oltre ai precedenti sono
                            //“2H”, “3H”, “4H”
                            case "2H":
                            case "3H":
                            case "4H":
                                switch (filtro)
                                {
                                    case "RAL":
                                    case "R22":
                                    case "R23":
                                    case "R24":
                                    case "R25":
                                    case "R44":
                                    case "R45":
                                        break;
                                    default:
                                        if (Utility.IsDomandaINPDAI(siglaCategoria))
                                            messaggioVideo = "I codici Gestione ammessi sono 1, 2, 3, 4, A, I, M, N";
                                        else
                                            messaggioVideo = "I codici Gestione ammessi sono 1, 2, 3, 4, 5, 6, 7, 8, G, H, I, M, N";
                                        return false;
                                }
                                break;
                            case "A":
                                if (!Utility.IsDomandaINPDAI(siglaCategoria))
                                {
                                    messaggioVideo = "I codici Gestione ammessi sono 1, 2, 3, 4, 5, 6, 7, 8, G, H, I, M, N";
                                    return false;
                                }
                                break;
                            case "H":
                                if (sup.DecorrenzaSupplemento.HasValue &&
                                    !(listaSupplementiSenzaQuotaFittizia
                                    .Where(x => x.CodGestioneSupplemento == "1"
                                && x.DecorrenzaSupplemento == sup.DecorrenzaSupplemento && x.QuotaSupplemento == sup.QuotaSupplemento).Any()))
                                {
                                    messaggioVideo = "La gestione H deve essere acquisita con la gestione 1 per ogni supplemento";
                                    return false;
                                }

                                if (Utility.IsDomandaINPDAI(siglaCategoria))
                                {
                                    if (sup.CodGestioneSupplemento == "5" || sup.CodGestioneSupplemento == "6")
                                    {
                                        messaggioVideo = "I codici Gestione ammessi sono 1, 2, 3, 4, A, I, M, N, H";
                                        return false;
                                    }
                                }
                                break;
                            default:
                                if (Utility.IsDomandaINPDAI(siglaCategoria))
                                    messaggioVideo = "I codici Gestione ammessi sono 1, 2, 3, 4, A, I, M, N";
                                else
                                    messaggioVideo = "I codici Gestione ammessi sono 1, 2, 3, 4, 5, 6, 7, 8, G, H, I, M, N";
                                return false;
                        }

                        if (Utility.IsDomandaINPDAI(siglaCategoria) && sup.TipoSupplemento == 'R' && !IsTipoQuotaValido(sup.CodGestioneSupplemento, sup.QuotaSupplemento, sup.CodTipoQuota, out messaggioVideo))
                            return false;

                        //le Categorie (RACATEG) “VOBANC”, “IOBANC”, “SOBANC” debbono avere
                        //solo il Codice Gestione Supplementi (VSGES) = a “1”
                        switch (siglaCategoria)
                        {
                            case "VOBANC":
                            case "IOBANC":
                            case "SOBANC":
                                if (sup.CodGestioneSupplemento != "1" && sup.CodGestioneSupplemento != "2" && sup.CodGestioneSupplemento != "3" && sup.CodGestioneSupplemento != "4" && sup.CodGestioneSupplemento != "M" && sup.CodGestioneSupplemento != "N" && sup.CodGestioneSupplemento != "I" && sup.CodGestioneSupplemento != "H")
                                {
                                    messaggioVideo = "Per le categoria VOBANC, IOBANC e SOBANC il codice gestione deve essere pari a 1, 2, 3, 4, M, N, I, H";
                                    return false;
                                }
                                break;
                            default:
                                break;
                        }

                        //i Codici Gestione (VSGES) = a “I”, “M”, “N” non sono ammessi nei seguenti
                        //casi:
                        switch (sup.CodGestioneSupplemento)
                        {
                            case "I":
                            case "M":
                            case "N":
                                //se il 2° Codice Natura (RAU1032) è = a “Y” e il Campo PDIRSUP è = a
                                //zero e la Data Decorrenza Supplementi (VSDEC) è = alla Decorrenza
                                //Originaria (RAU104)
                                if (codNat2 == 'Y' && pdirsup == 0 && sup.DecorrenzaSupplemento.HasValue &&
                                    Utility.DataSuccessivaA(sup.DecorrenzaSupplemento.Value, decorrenzaOriginaria) &&
                                    !Utility.DataStrettamenteSuccessivaA(sup.DecorrenzaSupplemento.Value, decorrenzaOriginaria) &&
                                    !(Utility.IsRicostituzione_Supplemento(datiPensione) && isMemo50) && !Utility.IsRicostituzione_PerVariazioneDatiSupplemento(datiPensione))
                                {
                                    messaggioVideo = "I codici gestione I, M, N non sono ammessi";
                                    return false;
                                }

                                //se il 2° Codice Natura (RAU1032) è = a “Y” e il Campo PDIRSUP è = a
                                //1 e il Codice Provenienza (DAU107) è = a zero e la Data Decorrenza
                                //Supplementi (VSDEC) è = alla Decorrenza Originaria (RAU104)
                                if (codNat2 == 'Y' && pdirsup == 1 && sup.DecorrenzaSupplemento.HasValue && datiDA != null && (!datiDA.ProvenienzaPensione.HasValue ||
                                    datiDA.ProvenienzaPensione.Value == 0) &&
                                    Utility.DataSuccessivaA(sup.DecorrenzaSupplemento.Value, decorrenzaOriginaria) &&
                                    !Utility.DataStrettamenteSuccessivaA(sup.DecorrenzaSupplemento.Value, decorrenzaOriginaria) &&
                                    !(Utility.IsRicostituzione_Supplemento(datiPensione) && isMemo50) && !Utility.IsRicostituzione_PerVariazioneDatiSupplemento(datiPensione))
                                {
                                    messaggioVideo = "I codici gestione I, M, N non sono ammessi";
                                    return false;
                                }

                                //se il 2° Codice Natura (RAU1032) è = a “Y” e iil Campo PDIRSUP è =
                                //a 1 e il Codice Provenienza (DAU107) è diverso da zero e la Data
                                //Decorrenza Supplementi (VSDEC) è = alla Decorrenza della Diretta
                                //(DAU106)
                                if (codNat2 == 'Y' && pdirsup == 1 && sup.DecorrenzaSupplemento.HasValue && datiDA != null && datiDA.ProvenienzaPensione.HasValue &&
                                    datiDA.ProvenienzaPensione.Value != 0 && datiDA.DecorrenzaPensione.HasValue &&
                                    Utility.DataSuccessivaA(sup.DecorrenzaSupplemento.Value, datiDA.DecorrenzaPensione.Value) &&
                                    !Utility.DataStrettamenteSuccessivaA(sup.DecorrenzaSupplemento.Value, datiDA.DecorrenzaPensione.Value) &&
                                    !(Utility.IsRicostituzione_Supplemento(datiPensione) && isMemo50) && !Utility.IsRicostituzione_PerVariazioneDatiSupplemento(datiPensione))
                                {
                                    messaggioVideo = "I codici gestione I, M, N non sono ammessi";
                                    return false;
                                }

                                //se la Data Decorrenza Supplemento (VSDEC) è inferiore a febbraio
                                //1998
                                if (sup.DecorrenzaSupplemento.HasValue && !Utility.DataSuccessivaA(sup.DecorrenzaSupplemento.Value, new DateTime(1998, 2, 1)) &&
                                    !(Utility.IsRicostituzione_Supplemento(datiPensione) && isMemo50) && !Utility.IsRicostituzione_PerVariazioneDatiSupplemento(datiPensione))
                                {
                                    messaggioVideo = "I codici gestione I, M, N non sono ammessi";
                                    return false;
                                }
                                //se il pensionando non ha compiuto 65 anni alla Data Decorrenza
                                //Supplemento (VSDEC)
                                DateTime? dataNascitaCompare = null;
                                if (Utility.IsDomandaPensioneSuperstitiOrRicostituzione(datiPensione))
                                    dataNascitaCompare = datiAnagraficiDC != null ? datiAnagraficiDC.DataNascita : null;
                                else
                                    dataNascitaCompare = datiAnagraficiTitolare != null ? datiAnagraficiTitolare.DataNascita : null;
                                if (dataNascitaCompare.HasValue && sup.DecorrenzaSupplemento.HasValue &&
                                    Utility.DataStrettamenteSuccessivaA(dataNascitaCompare.Value.AddYears(65), sup.DecorrenzaSupplemento.Value) &&
                                    !(Utility.IsRicostituzione_Supplemento(datiPensione) && isMemo50) && !Utility.IsRicostituzione_PerVariazioneDatiSupplemento(datiPensione))
                                {
                                    messaggioVideo = "I codici gestione I, M, N non sono ammessi";
                                    return false;
                                }

                                if (Utility.IsDomandaINPDAI(siglaCategoria))
                                {
                                    if (sup.QuotaSupplemento.HasValue && sup.QuotaSupplemento.Value == 'A')
                                    {
                                        if (sup.NSettimaneSupplemento != 1)
                                        {
                                            messaggioVideo = "Per i codici gestione I, M, N con quota A è necessario inserire un numero di settimane pari a 1";
                                            return false;
                                        }
                                        if (sup.RMSSupplemento != 0.0040m)
                                        {
                                            messaggioVideo = "Per i codici gestione I, M, N con quota A è necessario insere una retribuzione media settimanale pari a 0,0040";
                                            return false;
                                        }
                                    }
                                }
                                break;
                            default:
                                break;
                        }

                        if (sup.CodGestioneSupplemento == "5")
                        {
                            //il Codice Gestione (VSGES) = a “5” è ammesso solo se la Decorrenza
                            //Originaria (RAU104) è anteriore ad agosto 1972 oppure, nel caso di
                            //Reversibilità da Pensionato (1° carattere Categoria (RACATEG) = a “S” e
                            //Campo DAU107 = a 1 o 2), se la Decorrenza della Diretta (DAU106) è
                            //anteriore ad agosto 1972 R5
                            if (Utility.DataSuccessivaA(decorrenzaOriginaria, new DateTime(1972, 8, 1)) ||
                                (datiDA != null && datiDA.DecorrenzaPensione.HasValue && Utility.DataSuccessivaA(datiDA.DecorrenzaPensione.Value, new DateTime(1972, 8, 1))))
                            {
                                messaggioVideo = "Il codice gestione pari a 5 è ammesso solo se la decorrenza originaria o la decorrenza della diretta è anteriore ad agosto 1972";
                                return false;
                            }

                            //il Codice Gestione (VSGES) = a “5” è ammesso solo se la Data Decorrenza
                            //Supplemento (VSDEC) è = a maggio 1972 R5
                            if (sup.DecorrenzaSupplemento.HasValue && (Utility.DataStrettamenteSuccessivaA(sup.DecorrenzaSupplemento.Value, new DateTime(1972, 5, 1)) ||
                                !Utility.DataSuccessivaA(sup.DecorrenzaSupplemento.Value, new DateTime(1972, 5, 1))))
                            {
                                messaggioVideo = "Il codice gestione pari a 5 è ammesso solo se la decorrenza supplemento è pari a maggio 1972";
                                return false;
                            }
                        }

                        //se il Codice Gestione Supplementi (VSGES) è = a “8” 
                        if (sup.CodGestioneSupplemento == "8")
                        {
                            //deve essere presente solo l'Importo IVS (VSIVS) RX8
                            if ((sup.AmmontareContributivo.HasValue && sup.AmmontareContributivo.Value > 0) ||
                                    (sup.CodiceLiquidazione.HasValue && sup.CodiceLiquidazione.Value > 0) ||
                                    (sup.NSettimaneSupplemento.HasValue && sup.NSettimaneSupplemento.Value > 0) ||
                                    (sup.QuotaSupplemento.HasValue) ||
                                    (sup.RMSSupplemento.HasValue && sup.RMSSupplemento.Value > 0M) ||
                                    (!sup.MontanteSupplemento.HasValue || sup.MontanteSupplemento.Value == 0M))
                            {
                                messaggioVideo = "Deve essere presente solo il montante IVS" + GetDescrizioneSupplemento(sup);
                                return false;
                            }

                            //la Categoria (RACATEG) deve essere = a “PMO” e la Decorrenza
                            //Supplementi (VSDEC) deve essere = ad aprile 1973 WB1
                            if (siglaCategoria != "PMO" || !sup.DecorrenzaSupplemento.HasValue ||
                                (!Utility.DataSuccessivaA(sup.DecorrenzaSupplemento.Value, new DateTime(1973, 4, 1)) ||
                                Utility.DataStrettamenteSuccessivaA(sup.DecorrenzaSupplemento.Value, new DateTime(1973, 4, 1))))
                            {
                                messaggioVideo = "Il codice gestione 8 può essere inserito solo per la categoria PMO con decorrenza supplementi pari ad aprile 1973";
                                return false;
                            }
                        }

                        //se il Codice Gestione Supplementi (VSGES) è = a “7” la Categoria
                        //(RACATEG) deve essere = a “VOMIN”, “SOMIN” W52
                        if (sup.CodGestioneSupplemento == "7")
                        {
                            if (!Utility.IsDomandaMIN(siglaCategoria))
                            {
                                messaggioVideo = "Il codice gestione pari a 7 può essere inserito solo per categorie VOMIN, SOMIN e IOMIN";
                                return false;
                            }
                            else if (sup.TipoSupplemento.Value != 'R')
                            {
                                messaggioVideo = "Il codice gestione pari a 7 può essere inserito solo per tipo supplemento retributivo";
                                return false;
                            }
                        }

                        //se il Codice Gestione Supplementi (VSGES) è = a “5”, “6” la Categoria
                        //(RACATEG) deve essere = a "VO", "IO", "SO", "VOMIN", "IOMIN", "SOMIN",
                        //"VOP", "IOP", "SOP", "PMO", "VOBANC", "SOBANC", "IOBANC" W53
                        if (sup.CodGestioneSupplemento == "5" || sup.CodGestioneSupplemento == "6")
                        {
                            switch (siglaCategoria)
                            {
                                case "VO":
                                case "IO":
                                case "SO":
                                case "VOMIN":
                                case "IOMIN":
                                case "SOMIN":
                                case "VOP":
                                case "IOP":
                                case "SOP":
                                case "PMO":
                                case "VOBANC":
                                case "SOBANC":
                                case "IOBANC":
                                    break;
                                default:
                                    messaggioVideo = "Il codice gestione 5 o 6 può essere inserito solo per le seguenti categorie: VO, IO, SO, VOMIN, IOMIN, " +
                                        "SOMIN, VOP, IOP, SOP, PMO, VOBANC, SOBANC, IOBANC";
                                    return false;
                            }
                        }

                        //se il Codice Gestione Supplementi (VSGES) è = “6” non può esistere
                        //un'altra registrazione con lo stesso Codice Gestione (VSGES) = a “6” W9
                        if (sup.CodGestioneSupplemento == "6")
                        {
                            if (listaSupplementiSenzaQuotaFittizia.FindAll(x => x.CodGestioneSupplemento == "6").Count > 1)
                            {
                                messaggioVideo = "Non può esistere più di una registrazione con codice gestione pari a 6";
                                return false;
                            }
                        }

                        //se il Codice Gestione Supplementi (VSGES) è = “7” e la Categoria
                        //(RACATEG) è = a “VOMIN” non può esistere un'altra registrazione con lo
                        //stesso Codice Gestione (VSGES) = a “7” WA1
                        if (sup.CodGestioneSupplemento == "7" && siglaCategoria == "VOMIN")
                        {
                            if (listaSupplementiSenzaQuotaFittizia.FindAll(x => x.CodGestioneSupplemento == "7").Count > 1)
                            {
                                messaggioVideo = "Non può esistere più di una registrazione con codice gestione pari a 7";
                                return false;
                            }
                        }

                        //se il Codice Gestione Supplementi (VSGES) è = “7” e la Categoria
                        //(RACATEG) è = a “SOMIN” possono esistere solo 2 registrazioni con lo
                        //stesso Codice Gestione (VSGES) = a “7” e la seconda registrazione deve
                        //avere la Decorrenza Supplementi (VSDEC) = alla Decorrenza Originaria
                        //(RAU104) WA2 WA3
                        if (sup.CodGestioneSupplemento == "7" && siglaCategoria == "SOMIN")
                        {
                            if (listaSupplementiSenzaQuotaFittizia.FindAll(x => x.CodGestioneSupplemento == "7").Count > 2)
                            {
                                messaggioVideo = "Non possono esistere più di due registrazioni con codice gestione pari a 7";
                                return false;
                            }
                            else if (listaSupplementiSenzaQuotaFittizia.FindAll(x => x.CodGestioneSupplemento == "7").Count == 2)
                            {
                                if (!listaSupplementiSenzaQuotaFittizia.Exists(x => x.CodGestioneSupplemento == "7" && x.DecorrenzaSupplemento.HasValue &&
                                    Utility.DataSuccessivaA(x.DecorrenzaSupplemento.Value, decorrenzaOriginaria) &&
                                    !Utility.DataStrettamenteSuccessivaA(x.DecorrenzaSupplemento.Value, decorrenzaOriginaria)))
                                {
                                    messaggioVideo = "In presenza di due registrazioni con codice gestione pari a 7 è necessario che almeno una decorrenza supplementi sia" +
                                        "pari alla decorrenza originaria";
                                    return false;
                                }
                            }
                        }

                        if (sup.CodGestioneSupplemento != "G" && (sup.TipoSupplemento.HasValue && sup.TipoSupplemento.Value == 'C') && Utility.IsDomandaVOAUT_IOAUT(datiPensione.SiglaCategoria)
                            && !GestioneBypassControllo.CheckAndLockBypassControlloByNomeBypass(datiPensione, GestioneBypassControllo.NomeBypass.Titolare_Anagrafica_AGO.APPLICAZIONE_SENTENZA_VOAUT))
                        {
                            messaggioVideo = "Il codice Gestione G è l'unico ammesso per i supplementi contributivi.";
                            return false;
                        }

                        if (sup.DecorrenzaSupplemento.HasValue)
                        {
                            //se il Codice Gestione (VSGES) = a “5” la Data Decorrenza Supplementi
                            //(VSDEC) deve essere = a maggio 1972
                            if (sup.CodGestioneSupplemento == "5" && (!Utility.DataSuccessivaA(sup.DecorrenzaSupplemento.Value, new DateTime(1972, 5, 1)) ||
                                Utility.DataStrettamenteSuccessivaA(sup.DecorrenzaSupplemento.Value, new DateTime(1972, 5, 1))))
                            {
                                messaggioVideo = "La decorrenza supplementi deve essere uguale a maggio 1972" + GetDescrizioneSupplemento(sup);
                                return false;
                            }

                            //la Data Decorrenza Supplementi (VSDEC) deve essere superiore di 2 anni
                            //alla Decorrenza Originaria (RAU104) per le pensioni dirette, cioè il Campo
                            //PDIRSUP è = a zero RY
                            if (pdirsup == 0)
                            {
                                if (!GestioneBypassControllo.CheckAndLockBypassControlloByNomeBypass(datiPensione, GestioneBypassControllo.NomeBypass.SUP_INF_2AN_SENT_O_ART6_L40790.SUP_INF_2AN_SENT_O_ART6_L40790))
                                {
                                    if (filtro != "BNS" && filtro != "BNX" && !(Utility.IsRicostituzioneOrRiaperturaAGOAbilitata(datiPensione, false) && codNat2 == 'Y') &&
                                        !((siglaCategoria == "VO" || siglaCategoria == "IO" || siglaCategoria == "VR") && codNat3 == 'M' && sup.CodGestioneSupplemento == "2" && (sup.QuotaSupplemento == 'A' || sup.QuotaSupplemento == 'B') && sup.DecorrenzaSupplemento == decorrenzaOriginaria))
                                    {
                                        //20151023 G.Arru - Se il codice natura 2 è 'V' o 'Y' il controllo non deve scattare (Oggetto mail - 'RE: LIQPENS - Rilascio Sviluppo INPS v20151022_1') 
                                        if (codNat2 != 'V' && !(codNat2 == 'Y' && Utility.IsDomandaBancari(siglaCategoria)) && !Utility.DataSuccessivaA(sup.DecorrenzaSupplemento.Value, decorrenzaOriginaria.AddYears(2)))
                                        {
                                            messaggioVideo = "La decorrenza supplementi deve essere pari o superiore di 2 anni alla decorrenza originaria per le pensioni dirette" + GetDescrizioneSupplemento(sup);
                                            return false;
                                        }
                                    }
                                }
                            }
                            //la Data Decorrenza Supplementi (VSDEC) deve = alla Decorrenza Originaria
                            //(RAU104) per le pensioni di reversibilità da assicurato, cioè il Campo
                            //PDIRSUP è = a 1 e il Campo DAU107 = a zero RY
                            else if (pdirsup == 1 && datiDA != null && (!datiDA.ProvenienzaPensione.HasValue || datiDA.ProvenienzaPensione.Value == 0))
                            {
                                if (!Utility.DataSuccessivaA(sup.DecorrenzaSupplemento.Value, decorrenzaOriginaria) ||
                                    Utility.DataStrettamenteSuccessivaA(sup.DecorrenzaSupplemento.Value, decorrenzaOriginaria))
                                {
                                    messaggioVideo = "La decorrenza supplementi deve essere uguale alla decorrenza originaria" + GetDescrizioneSupplemento(sup);
                                    return false;
                                }
                            }
                            //la Data Decorrenza Supplementi (VSDEC) può essere compresa tra la
                            //Decorrenza Originaria della Diretta (DAU106) e la Decorrenza Originaria
                            //(RAU104) per le pensioni di reversibilità da pensionato, cioè il Campo
                            //PDIRSUP è = a 1 e il Campo DAU107 = a 1, 2 RY
                            else if (pdirsup == 1 && datiDA != null && datiDA.ProvenienzaPensione.HasValue &&
                                (datiDA.ProvenienzaPensione.Value == 1 || datiDA.ProvenienzaPensione.Value == 2))
                            {
                                if (datiDA.DecorrenzaPensione.HasValue && Utility.DataStrettamenteSuccessivaA(decorrenzaOriginaria, datiDA.DecorrenzaPensione.Value))
                                {
                                    if (!Utility.DataSuccessivaA(sup.DecorrenzaSupplemento.Value, datiDA.DecorrenzaPensione.Value) || Utility.DataStrettamenteSuccessivaA(sup.DecorrenzaSupplemento.Value, decorrenzaOriginaria))
                                    {
                                        messaggioVideo = "La decorrenza supplementi deve essere compresa tra la decorrenza della diretta e la decorrenza originaria" + GetDescrizioneSupplemento(sup);
                                        return false;
                                    }
                                }
                                else if (datiDA.DecorrenzaPensione.HasValue)
                                {
                                    if (!Utility.DataSuccessivaA(sup.DecorrenzaSupplemento.Value, decorrenzaOriginaria) || Utility.DataStrettamenteSuccessivaA(sup.DecorrenzaSupplemento.Value, datiDA.DecorrenzaPensione.Value))
                                    {
                                        messaggioVideo = "La decorrenza supplementi deve essere compresa tra la decorrenza originaria e la decorrenza della diretta" + GetDescrizioneSupplemento(sup);
                                        return false;
                                    }
                                }
                            }

                            //se l'anno della Data Decorrenza Supplementi (VSDECAA) è compreso tra il
                            //1993 e il 1995 e il Codice Gestione Supplementi (VSGES) è = a “2”, “3”, “4”
                            //e l'Importo IVS (VIVS) è = a zero il Numero Settimane Supplementi (VSSET)
                            //e la Retribuzione Media Settimanale Supplementi (VSRETR) devono
                            //contenere 1 RF1
                            if (Utility.DataStrettamenteSuccessivaA(sup.DecorrenzaSupplemento.Value, new DateTime(1992, 12, 31)) &&
                                !Utility.DataSuccessivaA(sup.DecorrenzaSupplemento.Value, new DateTime(1996, 1, 1)))
                            {
                                if ((sup.CodGestioneSupplemento == "2" || sup.CodGestioneSupplemento == "3" || sup.CodGestioneSupplemento == "4") &&
                                    (!sup.MontanteSupplemento.HasValue || sup.MontanteSupplemento.Value == 0M))
                                {
                                    if (!sup.NSettimaneSupplemento.HasValue || sup.NSettimaneSupplemento.Value != 1 || !sup.RMSSupplemento.HasValue || sup.RMSSupplemento.Value != 1)
                                    {
                                        messaggioVideo = "Il numero settimane e la retribuzione media settimanale devono contenere 1" + GetDescrizioneSupplemento(sup);
                                        return false;
                                    }
                                }
                            }

                            //se l'anno della Data Decorrenza Supplementi (VSDECAA) è inferiore al 1982
                            //e il Codice Gestione Supplementi (VSGES) è = a “2”, “3”, “4” l'Importo IVS
                            //(VSIVS) deve essere presente RF2
                            if (sup.DecorrenzaSupplemento.Value.Year < 1982 &&
                                (sup.CodGestioneSupplemento == "2" || sup.CodGestioneSupplemento == "3" || sup.CodGestioneSupplemento == "4"))
                            {
                                if (!sup.MontanteSupplemento.HasValue || sup.MontanteSupplemento.Value == 0M)
                                {
                                    messaggioVideo = "Il montante IVS deve essere > 0" + GetDescrizioneSupplemento(sup);
                                    return false;
                                }
                            }

                            //se l'anno della Data Decorrenza Supplementi (VSDEC) è compreso tra il
                            //gennaio 1981 e giugno 1990 e il Codice Gestione Supplementi (VSGES) è =
                            //a “2”, “3”, “4” l'Importo IVS (VSIVS), il Numero Settimane Supplementi
                            //(VSSET) e la Retribuzione Media Settimanale Supplementi (VSRETR)
                            //devono essere presenti RF9
                            if (Utility.DataSuccessivaA(sup.DecorrenzaSupplemento.Value, new DateTime(1981, 1, 1)) &&
                                !Utility.DataStrettamenteSuccessivaA(sup.DecorrenzaSupplemento.Value, new DateTime(1990, 6, 1)) &&
                                (sup.CodGestioneSupplemento == "2" || sup.CodGestioneSupplemento == "3" || sup.CodGestioneSupplemento == "4"))
                            {
                                if (!sup.MontanteSupplemento.HasValue || sup.MontanteSupplemento.Value == 0M ||
                                    !sup.NSettimaneSupplemento.HasValue || sup.NSettimaneSupplemento.Value == 0 ||
                                    !sup.RMSSupplemento.HasValue || sup.RMSSupplemento.Value == 0M)
                                {
                                    messaggioVideo = "Il montante IVS, il numero settimane e la retribuzione media settimanale devono essere > 0" + GetDescrizioneSupplemento(sup);
                                    return false;
                                }
                            }

                            //se l'anno della Data Decorrenza Supplementi (VSDEC) è compreso tra il
                            //luglio 1990 e dicembre 1995 e il Codice Gestione Supplementi (VSGES) è =
                            //a “2”, “3”, “4” :
                            if (Utility.DataSuccessivaA(sup.DecorrenzaSupplemento.Value, new DateTime(1990, 7, 1)) &&
                                !Utility.DataStrettamenteSuccessivaA(sup.DecorrenzaSupplemento.Value, new DateTime(1995, 12, 1)) &&
                                (sup.CodGestioneSupplemento == "2" || sup.CodGestioneSupplemento == "3" || sup.CodGestioneSupplemento == "4"))
                            {
                                //se il 3° Codice natura (RAU1033) è = a “M”
                                if (codNat3 == 'M')
                                {
                                    //l'Importo IVS (VSIVS) deve essere presente RF7
                                    if (!sup.MontanteSupplemento.HasValue || sup.MontanteSupplemento.Value == 0M)
                                    {
                                        messaggioVideo = "Il montante IVS deve essere > 0" + GetDescrizioneSupplemento(sup);
                                        return false;
                                    }
                                    //il Numero Settimane Supplementi (VSSET) e la Retribuzione Media
                                    //Settimanale Supplementi (VSRETR) devono entrambi essere presenti
                                    //o entrambi assenti RF8 RF9
                                    if ((sup.NSettimaneSupplemento.HasValue && !sup.RMSSupplemento.HasValue) ||
                                        (sup.RMSSupplemento.HasValue && !sup.NSettimaneSupplemento.HasValue) ||
                                        (sup.NSettimaneSupplemento.HasValue && sup.RMSSupplemento.HasValue &&
                                        ((sup.NSettimaneSupplemento.Value == 0 && sup.RMSSupplemento.Value != 0) ||
                                        (sup.NSettimaneSupplemento.Value != 0 && sup.RMSSupplemento.Value == 0))))
                                    {
                                        messaggioVideo = "Il numero settimane e la retribuzione media settimanale devono entrambi essere presenti o entrambi assenti" + GetDescrizioneSupplemento(sup);
                                        return false;
                                    }
                                }
                                //se il 3° Codice natura (RAU1033) è diverso da “M”
                                else
                                {
                                    //se il mese della Data Decorrenza Supplementi (VSDECMM) è
                                    //superiore a 13 il Numero Settimane Supplementi (VSSET), la
                                    //Retribuzione Media Settimanale Supplementi (VSRETR) e l'Importo
                                    //IVS (VSIVS) devono essere presenti RFA
                                    if (sup.DecorrenzaSupplemento.Value.Month > 13)
                                    {
                                        if (!sup.RMSSupplemento.HasValue || sup.RMSSupplemento.Value == 0M || !sup.MontanteSupplemento.HasValue || sup.MontanteSupplemento.Value == 0M)
                                        {
                                            messaggioVideo = "La retribuzione media settimanale e il montante IVS devono essere > 0" + GetDescrizioneSupplemento(sup);
                                            return false;
                                        }
                                    }

                                    //se il mese della Data Decorrenza Supplementi (VSDECMM) è inferiore
                                    //a 14 e il Numero Settimane Supplementi (VSSET) e la Retribuzione
                                    //Media Settimanale Supplementi (VSRETR) contengono 1 l'Importo IVS
                                    //(VSIVS) deve essere assente RF6
                                    if (sup.DecorrenzaSupplemento.Value.Month < 14)
                                    {
                                        if (sup.NSettimaneSupplemento.HasValue && sup.NSettimaneSupplemento.Value == 1 &&
                                            sup.RMSSupplemento.HasValue && sup.RMSSupplemento.Value == 1M)
                                        {
                                            if (sup.MontanteSupplemento.HasValue && sup.MontanteSupplemento.Value > 0M)
                                            {
                                                messaggioVideo = "Il montante IVS deve essere 0" + GetDescrizioneSupplemento(sup);
                                                return false;
                                            }
                                        }
                                    }
                                    //se il Numero Settimane Supplementi (VSSET) e la Retribuzione Media
                                    //Settimanale Supplementi (VSRETR) sono assenti l'Importo IVS
                                    //(VSIVS) deve essere assente RFC
                                    if ((!sup.NSettimaneSupplemento.HasValue || sup.NSettimaneSupplemento.Value == 0) &&
                                        (!sup.RMSSupplemento.HasValue || sup.RMSSupplemento.Value == 0M))
                                    {
                                        messaggioVideo = "Il montante IVS deve essere 0" + GetDescrizioneSupplemento(sup);
                                        return false;
                                    }
                                }
                            }
                            //se l'anno della Data Decorrenza Supplementi (VSDECAA) è inferiore al 1996
                            //e il Codice Gestione Supplementi (VSGES) è = a “2”, “3”, “4” e l'Importo IVS
                            //(VSIVS) è assente e il Numero Settimane Supplementi (VSSET) e la
                            //Retribuzione Media Settimanale Supplementi (VSRETR) contengono 1
                            //verificare che ci sia in tabella un altro Anno Decorrenza Supplementi
                            //(VSDECAA) uguale con l'Importo IVS (VSIVS) presente, il Numero
                            //Settimane Supplementi (VSSET) presente e la Retribuzione Media
                            //Settimanale Supplementi (VSRETR) superiore a 1 RFB
                            if (sup.DecorrenzaSupplemento.Value.Year < 1996 &&
                                (sup.CodGestioneSupplemento == "2" || sup.CodGestioneSupplemento == "3" || sup.CodGestioneSupplemento == "4") &&
                                (!sup.MontanteSupplemento.HasValue || sup.MontanteSupplemento.Value == 0M) &&
                                (sup.NSettimaneSupplemento.HasValue && sup.NSettimaneSupplemento.Value == 1) &&
                                (sup.RMSSupplemento.HasValue && sup.RMSSupplemento.Value == 1M))
                            {
                                if (!listaSupplementiSenzaQuotaFittizia.Exists(x => x.DecorrenzaSupplemento.HasValue && x.DecorrenzaSupplemento.Value.Year == sup.DecorrenzaSupplemento.Value.Year &&
                                    x.MontanteSupplemento.HasValue && x.MontanteSupplemento.Value > 0 && x.NSettimaneSupplemento.HasValue && x.NSettimaneSupplemento.Value > 0 &&
                                    x.RMSSupplemento.HasValue && x.RMSSupplemento.Value > 1))
                                {
                                    messaggioVideo = GetDescrizioneSupplemento(sup) + " è necessario che ci sia un ulteriore supplemento con lo stesso anno decorrenza, " +
                                        "montante IVS > 0, numero settimane > 0 e retribuzione media settimanale > 1";
                                    return false;
                                }
                            }
                            //se il Codice Gestione Supplementi è = a “6” la Decorrenza Supplementi
                            //(VSDEC) non può essere inferiore a gennaio 1969 RH1
                            if (!Utility.DataSuccessivaA(sup.DecorrenzaSupplemento.Value, new DateTime(1969, 1, 1)) && sup.CodGestioneSupplemento == "6")
                            {
                                messaggioVideo = "La decorenza supplementi non può essere inferiore a gennaio 1969" + GetDescrizioneSupplemento(sup);
                                return false;
                            }

                            if (!GestioneBypassControllo.CheckBypassControlloByNomeBypass(datiPensione, GestioneBypassControllo.NomeBypass.Supplementi_Supplementi_AGO.SUPP_CHECK_SETT_RMS_IMP_IVS))
                            {
                                //se il Codice Gestione Supplementi (VSGES) è = a “1”, “6” e la Decorrenza
                                //Supplementi (VSDEC) è precedente a giugno 1981 deve essere presente
                                //solo l'Importo IVS (VSIVS) RX1 RX2
                                if (!Utility.DataSuccessivaA(sup.DecorrenzaSupplemento.Value, new DateTime(1981, 6, 1)) &&
                                (sup.CodGestioneSupplemento == "1" || sup.CodGestioneSupplemento == "6"))
                                {
                                    if ((sup.AmmontareContributivo.HasValue && sup.AmmontareContributivo.Value > 0) ||
                                        (sup.CodiceLiquidazione.HasValue && sup.CodiceLiquidazione.Value > 0) ||
                                        (sup.NSettimaneSupplemento.HasValue && sup.NSettimaneSupplemento.Value > 0) ||
                                        (sup.QuotaSupplemento.HasValue) ||
                                        (sup.RMSSupplemento.HasValue && sup.RMSSupplemento.Value > 0M) ||
                                        (!sup.MontanteSupplemento.HasValue || sup.MontanteSupplemento.Value == 0M))
                                    {
                                        messaggioVideo = "Deve essere presente solo il montante IVS" + GetDescrizioneSupplemento(sup);
                                        return false;
                                    }
                                }

                                //se il Codice Gestione Supplementi (VSGES) è = a “1”, “6” e la Decorrenza
                                //Supplementi (VSDEC) è compresa tra luglio 1981 dicembre 1995 devono
                                //essere presenti solo il Numero Settimane Supplementi (VSSET) e la
                                //Retribuzione Media Settimanale Supplementi (VSRETR) RX3 RX4
                                if (Utility.DataSuccessivaA(sup.DecorrenzaSupplemento.Value, new DateTime(1981, 7, 1)) &&
                                    !Utility.DataStrettamenteSuccessivaA(sup.DecorrenzaSupplemento.Value, new DateTime(1995, 12, 1)) &&
                                    (sup.CodGestioneSupplemento == "1" || sup.CodGestioneSupplemento == "6"))
                                {
                                    if ((sup.AmmontareContributivo.HasValue && sup.AmmontareContributivo.Value > 0) ||
                                            (sup.CodiceLiquidazione.HasValue && sup.CodiceLiquidazione.Value > 0) ||
                                            (!sup.NSettimaneSupplemento.HasValue || sup.NSettimaneSupplemento.Value == 0) ||
                                            (sup.QuotaSupplemento.HasValue) ||
                                            (!sup.RMSSupplemento.HasValue || sup.RMSSupplemento.Value == 0M) ||
                                            (sup.MontanteSupplemento.HasValue && sup.MontanteSupplemento.Value > 0M))
                                    {
                                        messaggioVideo = "Deve essere presenti solo il numero settimane e la retribuzione media settimanale" + GetDescrizioneSupplemento(sup);
                                        return false;
                                    }
                                }
                                //se il Codice Gestione Supplementi (VSGES) è = a “1”, “6” e la Decorrenza
                                //Supplementi (VSDEC) è = a giugno 1981 devo essere presenti o solo
                                //l'Importo IVS (VSIVS) o il Numero Settimane Supplementi (VSSET) e la
                                //Retribuzione Media Settimanale Supplementi (VSRETR) RX5 RX6
                                if (Utility.DataSuccessivaA(sup.DecorrenzaSupplemento.Value, new DateTime(1981, 6, 1)) &&
                                    !Utility.DataStrettamenteSuccessivaA(sup.DecorrenzaSupplemento.Value, new DateTime(1981, 6, 1)) &&
                                    (sup.CodGestioneSupplemento == "1" || sup.CodGestioneSupplemento == "6"))
                                {
                                    if ((sup.AmmontareContributivo.HasValue && sup.AmmontareContributivo.Value > 0) ||
                                            (sup.CodiceLiquidazione.HasValue && sup.CodiceLiquidazione.Value > 0) ||
                                            (sup.QuotaSupplemento.HasValue) ||
                                            (!sup.RMSSupplemento.HasValue || sup.RMSSupplemento.Value == 0M) ||
                                            ((!sup.MontanteSupplemento.HasValue || sup.MontanteSupplemento.Value == 0M) &&
                                            (!sup.NSettimaneSupplemento.HasValue || sup.NSettimaneSupplemento.Value == 0)))
                                    {
                                        messaggioVideo = "Deve essere presenti solo il montante IVS o il numero settimane e la retribuzione media settimanale" + GetDescrizioneSupplemento(sup);
                                        return false;
                                    }
                                }
                            }

                            if (filtro == "BNS" || filtro == "BNX")
                            {
                                if (sup.DecorrenzaSupplemento.Value != decorrenzaOriginaria)
                                {
                                    messaggioVideo = "La decorrenza per ogni supplemento deve essere uguale alla decorrenza della pensione in liquidazione (" + String.Format("{0:MM/yyyy}", decorrenzaOriginaria) + ").";
                                    return false;
                                }
                            }

                            // Rimozione richiesta con la revisione 6.9 del documento "LiqPens AGO - Interventi Puntuali@20180724_v6.9.docx"
                            //if (Utility.IsPensioneAnzianitaOrRicostituzione(datiPensione, null) &&
                            //    (filtro != "BNS" && filtro != "BNX" && !(Utility.IsRicostituzione(datiPensione.Gruppo) && codNat2 == 'Y')))
                            //{
                            //    if (datiAnagrafici != null && datiAnagrafici.Sesso.HasValue)
                            //    {
                            //        int limiteEta = 0;
                            //        switch (datiAnagrafici.Sesso.Value)
                            //        {
                            //            case 'M':
                            //                limiteEta = 65;
                            //                break;
                            //            case 'F':
                            //                limiteEta = 60;
                            //                break;
                            //        }
                            //        if (!Utility.DataSuccessivaA(sup.DecorrenzaSupplemento.Value, Utility.FirstDayOfMonth(datiAnagrafici.DataNascita.Value.AddYears(limiteEta))))
                            //        {
                            //            messaggioVideo = string.Format("Il titolare deve aver compiuto {0} anni alla decorrenza del supplemento ({1:MM/yyyy})", limiteEta, sup.DecorrenzaSupplemento);
                            //            return false;
                            //        }
                            //    }
                            //}
                        }
                        else
                        {
                            messaggioVideo = "La decorrenza supplementi è obbligatoria";
                            return false;
                        }

                        if (sup.NSettimaneSupplemento.HasValue && sup.NSettimaneSupplemento.Value > 0)
                        {
                            //il Numero Settimane Supplementi (VSSET) deve essere 1 se il Codice Quota
                            //Supplementi (VSQUO) è = a “A” e il 2° Codice Natura (RAU1032) è = a “Y” e:
                            if (sup.QuotaSupplemento.HasValue && sup.QuotaSupplemento.Value == 'A' && codNat2 == 'Y' &&
                                //se il Campo PDIRSUP è = a zero e la Data Decorrenza Supplementi
                                //(VSDEC) è = alla Decorrenza Originaria (RAU104)
                                ((pdirsup == 0 && sup.DecorrenzaSupplemento.HasValue && Utility.DataSuccessivaA(sup.DecorrenzaSupplemento.Value, decorrenzaOriginaria) &&
                                    !Utility.DataStrettamenteSuccessivaA(sup.DecorrenzaSupplemento.Value, decorrenzaOriginaria)) ||
                                //se il Campo PDIRSUP è = a 1 e il Codice Provenienza (DAU107) è = a
                                //zero e la Data Decorrenza Supplementi (VSDEC) è = alla Decorrenza
                                //Originaria (RAU104)
                                (pdirsup == 1 && datiDA != null && (!datiDA.ProvenienzaPensione.HasValue ||
                                    datiDA.ProvenienzaPensione.Value == 0) && sup.DecorrenzaSupplemento.HasValue &&
                                    Utility.DataSuccessivaA(sup.DecorrenzaSupplemento.Value, decorrenzaOriginaria) &&
                                    !Utility.DataStrettamenteSuccessivaA(sup.DecorrenzaSupplemento.Value, decorrenzaOriginaria)) ||
                                //se il Campo PDIRSUP è = a 1 e il Codice Provenienza (DAU107) è
                                //diverso da zero e la Data Decorrenza Supplementi (VSDEC) è = alla
                                //Decorrenza della Diretta (DAU106)
                                (pdirsup == 1 && sup.DecorrenzaSupplemento.HasValue && datiDA != null && datiDA.ProvenienzaPensione.HasValue &&
                                    datiDA.ProvenienzaPensione.Value != 0 && datiDA.DecorrenzaPensione.HasValue &&
                                    Utility.DataSuccessivaA(sup.DecorrenzaSupplemento.Value, datiDA.DecorrenzaPensione.Value) &&
                                    !Utility.DataStrettamenteSuccessivaA(sup.DecorrenzaSupplemento.Value, datiDA.DecorrenzaPensione.Value))))
                            {
                                if (sup.NSettimaneSupplemento != 1)
                                {
                                    messaggioVideo = "Il supplemento retributivo può essere solo di quota B.";
                                    return false;
                                }
                            }

                            //se il Campo PDIRSUP è = a 1 e il Codice Provenienza (DAU107) è = a zero
                            //il Numero Settimane Supplementi (VSSET) non può superare la capienza di
                            //settimane calcolata dalla Data della 1^ Decorrenza della tabella Retributiva
                            //(VRDEC) alla Data morte del De Cuius (DAU1010)

                            //negli altri casi il Numero Settimane Supplementi (VSSET) non può superare
                            //la capienza di settimane calcolata dalla Data della 1^ Decorrenza della
                            //tabella Retributiva (VRDEC) alla Decorrenza Originaria (RAU104)
                        }
                        else
                        {
                            messaggioVideo = "Il numero settimane supplementi deve essere maggiore di 0" + GetDescrizioneSupplemento(sup);
                            return false;
                        }

                        if (sup.TipoSupplemento.HasValue && sup.TipoSupplemento.Value != 'R')
                        {
                            if (sup.MontanteSupplemento.HasValue && sup.MontanteSupplemento.Value > 0)
                            {
                                //se la Data Decorrenza Supplementi (VSDEC) è inferiore a febbraio 1996 il
                                //Montante Supplementi (VSMON335) deve essere assente
                                if (sup.DecorrenzaSupplemento.HasValue && !Utility.DataSuccessivaA(sup.DecorrenzaSupplemento.Value, new DateTime(1996, 2, 1)))
                                {
                                    messaggioVideo = "Il Montante IVS deve essere 0" + GetDescrizioneSupplemento(sup);
                                    return false;
                                }

                                //se il 2° Codice Natura (RAU1032) è = a “Y” il Montante Supplementi
                                //(VSMON335) deve essere assente nei seguenti casi:
                                if (codNat2 == 'Y')
                                {
                                    //se il Campo PDIRSUP è = a zero e la Data Decorrenza Supplementi
                                    //(VSDEC) è = alla Decorrenza Originaria (RAU104) 
                                    //e il codice liquidazione è diversa da 4 (quota D) e Decorrenza maggiore 01/2012
                                    if ((pdirsup == 0 && sup.DecorrenzaSupplemento.HasValue && Utility.DataSuccessivaA(sup.DecorrenzaSupplemento.Value, decorrenzaOriginaria) &&
                                        !Utility.DataStrettamenteSuccessivaA(sup.DecorrenzaSupplemento.Value, decorrenzaOriginaria) &&
                                        ((sup.CodiceLiquidazione.GetValueOrDefault() != 4) ||
                                        (sup.CodiceLiquidazione.GetValueOrDefault() == 4 && !Utility.DataStrettamenteSuccessivaA(sup.DecorrenzaSupplemento.Value, new DateTime(2012, 1, 1))))) ||
                                        //se il Campo PDIRSUP è = a 1 e il Codice Provenienza (DAU107) è = a
                                        //zero e la Data Decorrenza Supplementi (VSDEC) è = alla Decorrenza
                                        //Originaria (RAU104)
                                        (pdirsup == 1 && datiDA != null && (!datiDA.ProvenienzaPensione.HasValue ||
                                        datiDA.ProvenienzaPensione.Value == 0) && sup.DecorrenzaSupplemento.HasValue &&
                                        Utility.DataSuccessivaA(sup.DecorrenzaSupplemento.Value, decorrenzaOriginaria) &&
                                        !Utility.DataStrettamenteSuccessivaA(sup.DecorrenzaSupplemento.Value, decorrenzaOriginaria)))
                                    {
                                        //ENG - permettere per le indirette 0003-0022-0001 con filtro BNS l' inserimento del Montante IVS con codice liquidazione D
                                        if (datiPensione.Gruppo == "0003" && datiPensione.Prodotto == "0022" && datiPensione.Tipo == "0001" && datiPensione.CodiceTipoRichiesta == "56")
                                        {
                                            if (sup.CodiceLiquidazione.GetValueOrDefault() == 3)
                                            {
                                                messaggioVideo = "Il codice liquidazione ammesso è 4";
                                                return false;
                                            }
                                        }
                                        else
                                        {
                                            messaggioVideo = "Il montante IVS deve essere 0" + GetDescrizioneSupplemento(sup);
                                            return false;
                                        }
                                    }
                                }
                                //se il Montante Supplementi (VSMON335) è presente deve essere presente
                                //anche l'Importo IVS (VSIVS)
                                if (!sup.AmmontareContributivo.HasValue || sup.AmmontareContributivo.Value == 0)
                                {
                                    messaggioVideo = "In presenza del montante IVS deve essere presente anche l'ammontare contributi";
                                    return false;
                                }
                                //il Montante Supplementi (VSMON335) non può essere inferiore all'Importo
                                //IVS (VSIVS)
                                else
                                {
                                    // Se la decorrenza del supplemento decorre dal 01/2015 allora l'ammontare dei contributi può essere maggiore del montante
                                    // Rif. Memo 30/2015
                                    if (!Utility.DataSuccessivaA(sup.DecorrenzaSupplemento.Value, new DateTime(2015, 01, 01)))
                                    {
                                        if (sup.MontanteSupplemento.Value < sup.AmmontareContributivo.Value)
                                        {
                                            messaggioVideo = "L'ammontare dei contributi non può essere maggiore del montante.";
                                            return false;
                                        }
                                    }
                                }
                            }
                            else
                            {
                                //se il Codice Gestione Supplementi (VSGES) è = a “G” l'Importo IVS (VSIVS)
                                //deve essere presente
                                if (sup.CodGestioneSupplemento == "G")
                                {
                                    messaggioVideo = "Il montante IVS deve essere > 0" + GetDescrizioneSupplemento(sup);
                                    return false;
                                }
                                //se la Data Decorrenza Supplementi (VSDEC) è inferiore a febbraio 1996
                                //l'Importo IVS (VSIVS) deve essere presente
                                if (sup.DecorrenzaSupplemento.HasValue && !Utility.DataSuccessivaA(sup.DecorrenzaSupplemento.Value, new DateTime(1996, 2, 1)))
                                {
                                    messaggioVideo = "Il montante IVS deve essere > 0" + GetDescrizioneSupplemento(sup);
                                    return false;
                                }
                                //ENG - per le indirette 0003-0022-0001 con filtro BNS Montante IVS deve essere presente
                                if (datiPensione.Gruppo == "0003" && datiPensione.Prodotto == "0022" && datiPensione.Tipo == "0001" && datiPensione.CodiceTipoRichiesta == "56")
                                {
                                    messaggioVideo = "Il montante IVS deve essere > 0" + GetDescrizioneSupplemento(sup);
                                    return false;
                                }
                            }

                            if (sup.AmmontareContributivo.HasValue && sup.AmmontareContributivo.Value > 0)
                            {
                                //se il 2° Codice Natura (RAU1032) è = a “Y” l'Importo IVS (VSIVS) deve
                                //essere assente nei seguenti casi:
                                if (codNat2 == 'Y')
                                {
                                    //se il Campo PDIRSUP è = a zero e la Data Decorrenza Supplementi
                                    //(VSDEC) è = alla Decorrenza Originaria (RAU104)
                                    if ((pdirsup == 0 && sup.DecorrenzaSupplemento.HasValue && Utility.DataSuccessivaA(sup.DecorrenzaSupplemento.Value, decorrenzaOriginaria) &&
                                        !Utility.DataStrettamenteSuccessivaA(sup.DecorrenzaSupplemento.Value, decorrenzaOriginaria) &&
                                        ((sup.CodiceLiquidazione.GetValueOrDefault() != 4) ||
                                        (sup.CodiceLiquidazione.GetValueOrDefault() == 4 && !Utility.DataStrettamenteSuccessivaA(sup.DecorrenzaSupplemento.Value, new DateTime(2012, 1, 1))))) ||
                                        //se il Campo PDIRSUP è = a 1 e il Codice Provenienza (DAU107) è = a
                                        //zero e la Data Decorrenza Supplementi (VSDEC) è = alla Decorrenza
                                        //Originaria (RAU104)
                                        (pdirsup == 1 && datiDA != null && (!datiDA.ProvenienzaPensione.HasValue ||
                                        datiDA.ProvenienzaPensione.Value == 0) && sup.DecorrenzaSupplemento.HasValue &&
                                        Utility.DataSuccessivaA(sup.DecorrenzaSupplemento.Value, decorrenzaOriginaria) &&
                                        !Utility.DataStrettamenteSuccessivaA(sup.DecorrenzaSupplemento.Value, decorrenzaOriginaria)))
                                    {
                                        //ENG - permettere per le indirette 0003-0022-0001 con filtro BNS l' inserimento dell' Ammontare Contributi con codice liquidazione D
                                        if (datiPensione.Gruppo == "0003" && datiPensione.Prodotto == "0022" && datiPensione.Tipo == "0001" && datiPensione.CodiceTipoRichiesta == "56")
                                        {
                                            if (sup.CodiceLiquidazione.GetValueOrDefault() == 3)
                                            {
                                                messaggioVideo = "Il codice liquidazione ammesso è 4";
                                                return false;
                                            }
                                        }
                                        else
                                        {
                                            messaggioVideo = "L' ammontare contributi deve essere 0" + GetDescrizioneSupplemento(sup);
                                            return false;
                                        }
                                    }
                                }
                            }
                            else
                            {
                                //se il Codice Gestione Supplementi (VSGES) è = a “G” il Montante
                                //Supplementi (VSMON335) deve essere presente
                                if (sup.CodGestioneSupplemento == "G")
                                {
                                    messaggioVideo = "L'ammontare contributi deve essere > 0" + GetDescrizioneSupplemento(sup);
                                    return false;
                                }

                                //se il Codice Liquidazione Supplementi (VSCLIQ) è = a 3, 4 il Montante
                                //Supplementi (VSMON335) deve essere presente
                                if (sup.CodiceLiquidazione.HasValue && (sup.CodiceLiquidazione.Value == 3 || sup.CodiceLiquidazione.Value == 4))
                                {
                                    messaggioVideo = "L'ammontare contributi deve essere > 0" + GetDescrizioneSupplemento(sup);
                                    return false;
                                }
                            }

                            if (sup.CodiceLiquidazione.HasValue && sup.CodiceLiquidazione.Value > 0)
                            {
                                //i Codici Liquidazione Supplementi (VSCLIQ) ammessi sono 3 o 4
                                switch (sup.CodiceLiquidazione.Value)
                                {
                                    case 3:
                                    case 4:
                                        break;
                                    default:
                                        messaggioVideo = "I codici liquidazione ammessi sono 3 o 4";
                                        return false;
                                }

                                //il Codice Liquidazione Supplementi (VSCLIQ) non è ammesso se mancano il
                                //Montante Supplementi (VSMON335) e l'Importo IVS (VSIVS)
                                if (!sup.MontanteSupplemento.HasValue || !sup.AmmontareContributivo.HasValue)
                                {
                                    messaggioVideo = "Il codice liquidazione non è ammesso se mancano il montante IVS e l'ammontare contributi";
                                    return false;
                                }
                                //se la Categoria è = a "IO" , "IR" , "IOART" , "IOBANC", "IOCOM" , "IDAI",
                                //"VO", "VOMIN", "VOP", "VR", "VOART", "VOCOM", "VOBANC", "VDAI",
                                //"SO", "SOP", "SR" , "SOART", "SOCOM", "SOBANC", "SDAI" e la Data
                                //Decorrenza Supplementi (VSDEC) è superiore a gennaio 2012 il Codice
                                //Liquidazione Supplementi (VSCLIQ) puo' essere 4
                                if (sup.CodiceLiquidazione.Value == 4)
                                {
                                    switch (siglaCategoria)
                                    {
                                        case "IO":
                                        case "IR":
                                        case "IOART":
                                        case "IOBANC":
                                        case "IOCOM":
                                        case "IDAI":
                                        case "IOP":
                                        case "VO":
                                        case "VOMIN":
                                        case "VOP":
                                        case "VR":
                                        case "VOART":
                                        case "VOCOM":
                                        case "VOBANC":
                                        case "VDAI":
                                        case "SO":
                                        case "SOP":
                                        case "SR":
                                        case "SOART":
                                        case "SOCOM":
                                        case "SOBANC":
                                        case "SDAI":
                                        case "VOAUT":
                                        case "IOAUT":
                                        case "SOAUT":
                                            if (sup.DecorrenzaSupplemento.HasValue && !Utility.DataSuccessivaA(sup.DecorrenzaSupplemento.Value, new DateTime(2012, 1, 1)))
                                            {
                                                messaggioVideo = "Il codice liquidazione non può essere 4" + GetDescrizioneSupplemento(sup);
                                                return false;
                                            }
                                            break;
                                        default:
                                            messaggioVideo = "Il codice liquidazione non può essere 4" + GetDescrizioneSupplemento(sup);
                                            return false;
                                    }
                                }
                            }
                        }
                        else
                        {
                            if (sup.QuotaSupplemento.HasValue)
                            {
                                //il Codice Quota Supplementi (VSQUO) ammessi sono “A”, “B”
                                switch (sup.QuotaSupplemento.Value)
                                {
                                    case 'A':
                                    case 'B':
                                        break;
                                    default:
                                        messaggioVideo = "Il codice quota può essere pari ad A o B" + GetDescrizioneSupplemento(sup);
                                        return false;

                                }

                                switch (sup.CodGestioneSupplemento)
                                {
                                    //se il Codice Gestione Supplementi (VSGES) è = a “5”, “6”, “8” il Codice
                                    //Quota Supplementi (VSQUO) deve essere assente
                                    case "5":
                                    case "6":
                                    case "8":
                                        messaggioVideo = "Il codice quota deve essere assente" + GetDescrizioneSupplemento(sup);
                                        return false;
                                    //se il Codice Gestione Supplementi (VSGES) è = “I”, “M”, “N” il Codice
                                    //Gestione Supplementi (VSGES) deve essere “B”
                                    case "I":
                                    case "M":
                                    case "N":
                                        if (sup.QuotaSupplemento.Value != 'B' && !(sup.QuotaSupplemento == 'A' && sup.NSettimaneSupplemento.GetValueOrDefault() == 1 && sup.RMSSupplemento.GetValueOrDefault() < 1 &&
                                            (((Utility.IsRicostituzione_Supplemento(datiPensione) || (Utility.IsRicostituzione_MotiviContributivi(datiPensione) && datiPensione.Tipo == "0001")) && ctrlAbilitazioneMemo50_2023 != null && ctrlAbilitazioneMemo50_2023.ValoreControllo == "SI") || Utility.IsRicostituzione_PerVariazioneDatiSupplemento(datiPensione)
                                            || Utility.IsRicostituzione(datiPensione.Gruppo))))
                                        {
                                            messaggioVideo = "Il codice quota deve essere B" + GetDescrizioneSupplemento(sup);
                                            return false;
                                        }
                                        break;
                                    default:
                                        break;
                                }

                                //il 1° Codice Quota Supplementi (VSQUO(1)) deve essere “B” nel caso in cui
                                //il 2° Codice Natura (RAU1032) è = a “Y” e:
                                if (codNat2 == 'Y')
                                {
                                    //se il Campo PDIRSUP è = a zero e la Data Decorrenza Supplementi
                                    //(VSDEC) è = alla Decorrenza Originaria (RAU104)
                                    if (((pdirsup == 0 && sup.DecorrenzaSupplemento.HasValue && Utility.DataSuccessivaA(sup.DecorrenzaSupplemento.Value, decorrenzaOriginaria) &&
                                        !Utility.DataStrettamenteSuccessivaA(sup.DecorrenzaSupplemento.Value, decorrenzaOriginaria)) ||
                                        //se il Campo PDIRSUP è = a 1 e il Codice Provenienza (DAU107) è = a
                                        //zero e la Data Decorrenza Supplementi (VSDEC) è = alla Decorrenza
                                        //Originaria (RAU104)
                                        (pdirsup == 1 && datiDA != null && (!datiDA.ProvenienzaPensione.HasValue ||
                                        datiDA.ProvenienzaPensione.Value == 0) && sup.DecorrenzaSupplemento.HasValue &&
                                        Utility.DataSuccessivaA(sup.DecorrenzaSupplemento.Value, decorrenzaOriginaria) &&
                                        !Utility.DataStrettamenteSuccessivaA(sup.DecorrenzaSupplemento.Value, decorrenzaOriginaria)) ||
                                        //se il Campo PDIRSUP è = a 1 e il Codice Provenienza (DAU107) è
                                        //diverso da zero e la Data Decorrenza Supplementi (VSDEC) è = alla
                                        //Decorrenza della Diretta (DAU106)
                                        (pdirsup == 1 && sup.DecorrenzaSupplemento.HasValue && datiDA != null && datiDA.ProvenienzaPensione.HasValue &&
                                        datiDA.ProvenienzaPensione.Value != 0 && datiDA.DecorrenzaPensione.HasValue &&
                                        Utility.DataSuccessivaA(sup.DecorrenzaSupplemento.Value, datiDA.DecorrenzaPensione.Value) &&
                                        !Utility.DataStrettamenteSuccessivaA(sup.DecorrenzaSupplemento.Value, datiDA.DecorrenzaPensione.Value)))
                                        //le RIC da bonus (riconoscibili dalla Y al 2° byte del codice natura) con decorrenza
                                        //contestuale alla decorrenza pensione di rimuovere il controllo
                                        && !(Utility.IsRicostituzione(datiPensione.Gruppo) && sup.DecorrenzaSupplemento.HasValue &&
                                        sup.DecorrenzaSupplemento.Value == decorrenzaOriginaria)
                                        )
                                    {
                                        if (sup.QuotaSupplemento.Value != 'B')
                                        {
                                            messaggioVideo = "Il codice quota deve essere B" + GetDescrizioneSupplemento(sup);
                                            return false;
                                        }
                                    }
                                }

                                //se il 2° Codice Natura è diverso da “Y”, “V” e la Data Decorrenza
                                //Supplementi (VSDEC) è = alla Decorrenza Originaria (RAU104) e il Campo
                                //PDIRSUP è = a zero non è ammessa il Codice Quota Supplementi (VSQUO)
                                //= a “B”
                                if (codNat2 != 'Y' && codNat2 != 'V' && sup.DecorrenzaSupplemento.HasValue &&
                                        Utility.DataSuccessivaA(sup.DecorrenzaSupplemento.Value, decorrenzaOriginaria) &&
                                        !Utility.DataStrettamenteSuccessivaA(sup.DecorrenzaSupplemento.Value, decorrenzaOriginaria) && pdirsup == 0)
                                {
                                    if (!(codNat3 == 'M' && sup.CodGestioneSupplemento == "2") && sup.QuotaSupplemento.Value == 'B')
                                    {
                                        messaggioVideo = "Il codice quota non può essere B" + GetDescrizioneSupplemento(sup);
                                        return false;
                                    }
                                }

                                //se la Data Decorrenza Supplementi (VSDEC) è inferiore a febbraio 1993 il
                                //Codice Quota Supplementi (VSQUO) deve essere assente
                                if (sup.DecorrenzaSupplemento.HasValue && !Utility.DataSuccessivaA(sup.DecorrenzaSupplemento.Value, new DateTime(1993, 2, 1)))
                                {
                                    messaggioVideo = "Il codice quota deve essere assente" + GetDescrizioneSupplemento(sup);
                                    return false;
                                }

                                //se il Campo DO-NOTE = a "RAL", "R22", "R23", "R24", "R25", "R44", "R45"
                                //e il 2° Codice Natura (RAU1032) è diverso da “Y” e la Data Decorrenza
                                //Supplementi (VSDEC) è = alla Decorrenza Originaria (RAU104) non è
                                //ammessa la Quota Supplementi (VSQUO) = a “B”
                                if (codNat2 != 'Y' && sup.DecorrenzaSupplemento.HasValue && Utility.DataSuccessivaA(sup.DecorrenzaSupplemento.Value, decorrenzaOriginaria) &&
                                        !Utility.DataStrettamenteSuccessivaA(sup.DecorrenzaSupplemento.Value, decorrenzaOriginaria))
                                {
                                    switch (filtro)
                                    {
                                        case "RAL":
                                        case "R22":
                                        case "R23":
                                        case "R24":
                                        case "R25":
                                        case "R44":
                                        case "R45":
                                            if (sup.QuotaSupplemento.Value == 'B')
                                            {
                                                messaggioVideo = "Il codice quota non può essere pari a B" + GetDescrizioneSupplemento(sup);
                                                return false;
                                            }
                                            break;
                                        default:
                                            break;
                                    }
                                }
                            }
                            else
                            {
                                //se la Data Decorrenza Supplementi (VSDEC) è successiva a gennaio 1993 e
                                //il Codice Gestione Supplementi (VSGES) è = a “1”, “2”, “3”, “4”, “7” il Codice
                                //Quota Supplementi (VSQUO) deve essere presente
                                if (sup.DecorrenzaSupplemento.HasValue && Utility.DataStrettamenteSuccessivaA(sup.DecorrenzaSupplemento.Value, new DateTime(1993, 1, 1)) && !Utility.IsDomandaBancari(siglaCategoria))
                                {
                                    switch (sup.CodGestioneSupplemento)
                                    {
                                        case "1":
                                        case "2":
                                        case "3":
                                        case "4":
                                        case "7":
                                            messaggioVideo = "Il codice quota deve essere presente" + GetDescrizioneSupplemento(sup);
                                            return false;
                                        default:
                                            break;
                                    }
                                }
                            }

                            if (sup.RMSSupplemento.HasValue && sup.RMSSupplemento.Value > 0)
                            {
                                //se il Campo DO-NOTE è = a “CSL”, “SSA”, “SSM” la Retribuzione Media
                                //Settimanale Supplementi (VSRETR) deve essere assente a meno che
                                //contenga il valore 0,0040 e contemporaneamente il Numero Settimane
                                //Supplementi (VSSET) contiene il valore 1
                                switch (filtro)
                                {
                                    case "CSL":
                                    case "SSA":
                                    case "SSM":
                                        if (!(sup.RMSSupplemento.Value == 0.0040M && sup.NSettimaneSupplemento.HasValue && sup.NSettimaneSupplemento.Value == 1))
                                        {
                                            messaggioVideo = "La retribuzione media settimanale deve essere 0" + GetDescrizioneSupplemento(sup);
                                            return false;
                                        }
                                        break;
                                    default:
                                        break;
                                }

                                //se il Codice Quota Supplementi (VSQUO) è = ad “A” La retribuzione Media
                                //Settimanale (VSRETR) deve essere 0,0040, se invece è “B” non può essere
                                //0,0040 nei seguenti casi:
                                if (sup.QuotaSupplemento.HasValue && (sup.QuotaSupplemento.Value == 'A' || sup.QuotaSupplemento.Value == 'B'))
                                {
                                    if (codNat2 == 'Y')
                                    {
                                        //se il Campo PDIRSUP è = a zero e la Data Decorrenza Supplementi
                                        //(VSDEC) è = alla Decorrenza Originaria (RAU104)
                                        if ((pdirsup == 0 && sup.DecorrenzaSupplemento.HasValue && Utility.DataSuccessivaA(sup.DecorrenzaSupplemento.Value, decorrenzaOriginaria) &&
                                            !Utility.DataStrettamenteSuccessivaA(sup.DecorrenzaSupplemento.Value, decorrenzaOriginaria)) ||
                                            //se il Campo PDIRSUP è = a 1 e il Codice Provenienza (DAU107) è = a
                                            //zero e la Data Decorrenza Supplementi (VSDEC) è = alla Decorrenza
                                            //Originaria (RAU104)
                                            (pdirsup == 1 && datiDA != null && (!datiDA.ProvenienzaPensione.HasValue ||
                                            datiDA.ProvenienzaPensione.Value == 0) && sup.DecorrenzaSupplemento.HasValue &&
                                            Utility.DataSuccessivaA(sup.DecorrenzaSupplemento.Value, decorrenzaOriginaria) &&
                                            !Utility.DataStrettamenteSuccessivaA(sup.DecorrenzaSupplemento.Value, decorrenzaOriginaria)) ||
                                            //se il Campo PDIRSUP è = a 1 e il Codice Provenienza (DAU107) è
                                            //diverso da zero e la Data Decorrenza Supplementi (VSDEC) è = alla
                                            //Decorrenza della Diretta (DAU106)
                                            (pdirsup == 1 && sup.DecorrenzaSupplemento.HasValue && datiDA != null && datiDA.ProvenienzaPensione.HasValue &&
                                            datiDA.ProvenienzaPensione.Value != 0 && datiDA.DecorrenzaPensione.HasValue &&
                                            Utility.DataSuccessivaA(sup.DecorrenzaSupplemento.Value, datiDA.DecorrenzaPensione.Value) &&
                                            !Utility.DataStrettamenteSuccessivaA(sup.DecorrenzaSupplemento.Value, datiDA.DecorrenzaPensione.Value)))
                                        {
                                            if (sup.QuotaSupplemento.Value == 'A')
                                            {
                                                if (Utility.IsRicostituzione(datiPensione.Gruppo))
                                                {
                                                    if (sup.RMSSupplemento.Value >= 1)
                                                    {
                                                        messaggioVideo = "La retribuzione media settimanale deve essere strettamente inferiore a 1" + GetDescrizioneSupplemento(sup);
                                                        return false;

                                                    }
                                                }
                                                else if (sup.RMSSupplemento.Value != 0.0040M)
                                                {
                                                    messaggioVideo = "La retribuzione media settimanale deve essere pari a 0.0040" + GetDescrizioneSupplemento(sup);
                                                    return false;
                                                }
                                            }


                                            if (sup.QuotaSupplemento.Value == 'B' && sup.RMSSupplemento.Value == 0.0040M)
                                            {
                                                messaggioVideo = "La retribuzione media settimanale non deve essere pari a 0.0040" + GetDescrizioneSupplemento(sup);
                                                return false;
                                            }
                                        }
                                    }
                                }

                                //la Retribuzione Media Settimanale Supplementi (VSRETR) delle Gestioni “I”,
                                //“M”, “N” della Quota “B” deve essere uguale alla corrispondente Gestione
                                //(VSGEST) della Quota “B”; le Gestioni Corrispondenti sono “1”, “2”, “3”, “4”
                                if (sup.QuotaSupplemento.HasValue && sup.QuotaSupplemento.Value == 'B' && sup.CodGestioneSupplemento == "I")
                                {
                                    if (listaSupplementiSenzaQuotaFittizia.Exists(x => x.QuotaSupplemento.HasValue && x.QuotaSupplemento.Value == 'B' && x.CodGestioneSupplemento == "2" &&
                                        x.DecorrenzaSupplemento.HasValue && sup.DecorrenzaSupplemento.HasValue && x.DecorrenzaSupplemento.Value == sup.DecorrenzaSupplemento.Value) &&
                                        !listaSupplementiSenzaQuotaFittizia.Exists(x => x.QuotaSupplemento.HasValue && x.QuotaSupplemento.Value == 'B' && x.CodGestioneSupplemento == "2" &&
                                        x.DecorrenzaSupplemento.HasValue && sup.DecorrenzaSupplemento.HasValue && x.DecorrenzaSupplemento.Value == sup.DecorrenzaSupplemento.Value &&
                                        x.RMSSupplemento.HasValue && x.RMSSupplemento.Value == sup.RMSSupplemento.Value))
                                    {
                                        messaggioVideo = "La retribuzione media settimanale deve essere uguale alla corrispondente gestione del supplemento con quota B e codice gestione pari a 2" +
                                            GetDescrizioneSupplemento(sup);
                                        return false;
                                    }
                                }
                                if (sup.QuotaSupplemento.HasValue && sup.QuotaSupplemento.Value == 'B' && sup.CodGestioneSupplemento == "M")
                                {
                                    if (listaSupplementiSenzaQuotaFittizia.Exists(x => x.QuotaSupplemento.HasValue && x.QuotaSupplemento.Value == 'B' && x.CodGestioneSupplemento == "3" &&
                                        x.DecorrenzaSupplemento.HasValue && sup.DecorrenzaSupplemento.HasValue && x.DecorrenzaSupplemento.Value == sup.DecorrenzaSupplemento.Value) &&
                                        !listaSupplementiSenzaQuotaFittizia.Exists(x => x.QuotaSupplemento.HasValue && x.QuotaSupplemento.Value == 'B' && x.CodGestioneSupplemento == "3" &&
                                        x.DecorrenzaSupplemento.HasValue && sup.DecorrenzaSupplemento.HasValue && x.DecorrenzaSupplemento.Value == sup.DecorrenzaSupplemento.Value &&
                                        x.RMSSupplemento.HasValue && x.RMSSupplemento.Value == sup.RMSSupplemento.Value))
                                    {
                                        messaggioVideo = "La retribuzione media settimanale deve essere uguale alla corrispondente gestione del supplemento con quota B e codice gestione pari a 3" +
                                            GetDescrizioneSupplemento(sup);
                                        return false;
                                    }
                                }
                                if (sup.QuotaSupplemento.HasValue && sup.QuotaSupplemento.Value == 'B' && sup.CodGestioneSupplemento == "N")
                                {
                                    if (listaSupplementiSenzaQuotaFittizia.Exists(x => x.QuotaSupplemento.HasValue && x.QuotaSupplemento.Value == 'B' && x.CodGestioneSupplemento == "4" &&
                                        x.DecorrenzaSupplemento.HasValue && sup.DecorrenzaSupplemento.HasValue && x.DecorrenzaSupplemento.Value == sup.DecorrenzaSupplemento.Value) &&
                                        !listaSupplementiSenzaQuotaFittizia.Exists(x => x.QuotaSupplemento.HasValue && x.QuotaSupplemento.Value == 'B' && x.CodGestioneSupplemento == "4" &&
                                        x.DecorrenzaSupplemento.HasValue && sup.DecorrenzaSupplemento.HasValue && x.DecorrenzaSupplemento.Value == sup.DecorrenzaSupplemento.Value &&
                                        x.RMSSupplemento.HasValue && x.RMSSupplemento.Value == sup.RMSSupplemento.Value))
                                    {
                                        messaggioVideo = "La retribuzione media settimanale deve essere uguale alla corrispondente gestione del supplemento con quota B e codice gestione pari a 4" +
                                            GetDescrizioneSupplemento(sup);
                                        return false;
                                    }
                                }
                            }
                            else
                            {
                                //se il Campo DO-NOTE è diverso da “CSL”, “SSA”, “SSM” e il 2° Codice
                                //natura (RAU1032) è diverso da “O” la Retribuzione Media Settimanale
                                //Supplementi (VSRETR) deve essere presente
                                if (filtro != "CSL" && filtro != "SSA" && filtro != "SSM" && codNat2 != 'O')
                                {
                                    messaggioVideo = "La retribuzione media settimanale deve essere > 0" + GetDescrizioneSupplemento(sup);
                                    return false;
                                }
                                //se il Campo DO-NOTE = a "RAL", "R22", "R23", "R24", "R25", "R44", "R45"
                                //la Retribuzione Media Settimanale Supplementi (VSRETR) deve essere
                                //presente
                                switch (filtro)
                                {
                                    case "RAL":
                                    case "R22":
                                    case "R23":
                                    case "R24":
                                    case "R25":
                                    case "R44":
                                    case "R45":
                                        messaggioVideo = "La retribuzione media settimanale deve essere > 0" + GetDescrizioneSupplemento(sup);
                                        return false;
                                    default:
                                        break;
                                }
                            }
                        }

                        for (int j = i + 1; j < listaSupplementiSenzaQuotaFittizia.Count; j++)
                        {
                            //Non possono esistere 2 registrazioni con la stessa Gestione (VSGEST),
                            //Quota (VSQUO), tipo quota (per domande INPDAI) e Decorrenza (VSDEC) RJ
                            if (!Utility.IsDomandaINPDAI(siglaCategoria) && sup.CodGestioneSupplemento == listaSupplementiSenzaQuotaFittizia[j].CodGestioneSupplemento &&
                                sup.QuotaSupplemento.HasValue && listaSupplementiSenzaQuotaFittizia[j].QuotaSupplemento.HasValue &&
                                sup.QuotaSupplemento.Value == listaSupplementiSenzaQuotaFittizia[j].QuotaSupplemento.Value &&
                                (Utility.IsDomandaINPDAI(siglaCategoria) ? sup.CodTipoQuota == listaSupplementiSenzaQuotaFittizia[j].CodTipoQuota : true) &&
                                sup.DecorrenzaSupplemento.HasValue && listaSupplementiSenzaQuotaFittizia[j].DecorrenzaSupplemento.HasValue &&
                                Utility.DataSuccessivaA(sup.DecorrenzaSupplemento.Value, listaSupplementiSenzaQuotaFittizia[j].DecorrenzaSupplemento.Value) &&
                                !Utility.DataStrettamenteSuccessivaA(sup.DecorrenzaSupplemento.Value, listaSupplementiSenzaQuotaFittizia[j].DecorrenzaSupplemento.Value))
                            {
                                messaggioVideo = Utility.IsDomandaINPDAI(siglaCategoria) ? "Non possono esistere 2 registrazioni con la stessa gestione, quota, tipo quota e decorrenza" :
                                                                                           "Non possono esistere 2 registrazioni con la stessa gestione, quota e decorrenza";
                                return false;
                            }

                            //Non possono esistere 2 registrazioni con la stessa Gestione (VSGEST),
                            //Decorrenza (VSDEC) e codice liquidazione RJ
                            if (sup.CodGestioneSupplemento == listaSupplementiSenzaQuotaFittizia[j].CodGestioneSupplemento &&
                                sup.CodiceLiquidazione.HasValue && listaSupplementiSenzaQuotaFittizia[j].CodiceLiquidazione.HasValue &&
                                sup.CodiceLiquidazione.Value == listaSupplementiSenzaQuotaFittizia[j].CodiceLiquidazione.Value &&
                                sup.DecorrenzaSupplemento.HasValue && listaSupplementiSenzaQuotaFittizia[j].DecorrenzaSupplemento.HasValue &&
                                Utility.DataSuccessivaA(sup.DecorrenzaSupplemento.Value, listaSupplementiSenzaQuotaFittizia[j].DecorrenzaSupplemento.Value) &&
                                !Utility.DataStrettamenteSuccessivaA(sup.DecorrenzaSupplemento.Value, listaSupplementiSenzaQuotaFittizia[j].DecorrenzaSupplemento.Value))
                            {
                                messaggioVideo = "Non possono esistere 2 registrazioni con la stessa gestione, decorrenza e codice liquidazione";
                                return false;
                            }

                            //per quote B, per particolari gestioni il mese decorrenza viene modificato
                            //per tale motivo il controllo va eseguito su gestione, quota, tipo quota (per domande INPDAI) e anno decorrenza
                            if (!(ctrl != null && ctrl.ValoreControllo != "NO" && Utility.IsDomandaReversibilitaOrRicostituzione(datiPensione, datiDA) && sup.DecorrenzaSupplemento.HasValue && sup.DecorrenzaSupplemento <= datiPensione.DecorrenzaOriginaria) &&
                                sup.CodGestioneSupplemento == listaSupplementiSenzaQuotaFittizia[j].CodGestioneSupplemento &&
                                sup.QuotaSupplemento.HasValue && listaSupplementiSenzaQuotaFittizia[j].QuotaSupplemento.HasValue &&
                                sup.QuotaSupplemento.Value == listaSupplementiSenzaQuotaFittizia[j].QuotaSupplemento.Value &&
                                sup.QuotaSupplemento.Value == 'B' &&
                                (Utility.IsDomandaINPDAI(siglaCategoria) ? sup.CodTipoQuota == listaSupplementiSenzaQuotaFittizia[j].CodTipoQuota : true) &&
                                sup.DecorrenzaSupplemento.HasValue && listaSupplementiSenzaQuotaFittizia[j].DecorrenzaSupplemento.HasValue)
                            {
                                switch (sup.CodGestioneSupplemento)
                                {
                                    case "A":
                                    case "I":
                                    case "M":
                                    case "N":
                                    case "1":
                                    case "2":
                                    case "3":
                                    case "4":
                                    case "7":
                                    case "H":
                                        if (sup.DecorrenzaSupplemento.Value.Year == listaSupplementiSenzaQuotaFittizia[j].DecorrenzaSupplemento.Value.Year)
                                        {
                                            messaggioVideo = Utility.IsDomandaINPDAI(siglaCategoria) ? "Non possono esistere 2 registrazioni quota B, tipo quota " + sup.CodTipoQuota + " e gestione " + sup.CodGestioneSupplemento + " con lo stesso anno decorrenza" :
                                                                                                       "Non possono esistere 2 registrazioni quota B e gestione " + sup.CodGestioneSupplemento + " con lo stesso anno decorrenza";
                                            return false;
                                        }
                                        break;
                                }
                            }
                        }
                        if (!AGO_CI_ControlsCodiceLiquidazioneForContributivo(sup, out messaggioVideo))
                            return false;

                        if (!Utility.IsDomandaBancRicAnte1991(datiPensione, datiDA))
                            if (!GestioneBypassControllo.CheckAndLockBypassControlloByNomeBypass(datiPensione, GestioneBypassControllo.NomeBypass.Supplementi_Supplementi_AGO.SUPPLEMENTI_FUORI_PERIODO) &&
                                !AGO_ControlsCodiceLiquidazioneWithTipoCalcolo(sup, tipoCalcolo, out messaggioVideo))
                                return false;

                        //commentato per ereditare controlli a carattere generale
                        ////non può esistere più di un supplemento contributivo, la cui decorrenza minima dovrà
                        ////essere pari alla decorrenza pensione della domanda in questione incrementata di due anni
                        //if (Utility.IsDomandaVOAUT_IOAUT(datiPensione.SiglaCategoria))
                        //{
                        //    if (listaSupplementiSenzaQuotaFittizia.Count(x => x.TipoSupplemento == 'C') > 1)
                        //    {
                        //        messaggioVideo = "Non può esistere più di un supplemento contributivo";
                        //        return false;
                        //    }
                        //    else
                        //    {
                        //        if (sup.DecorrenzaSupplemento.HasValue && (sup.DecorrenzaSupplemento != datiPensione.DecorrenzaOriginaria.Value.AddYears(2)))
                        //        {
                        //            messaggioVideo = "La decorrenza minima dovrà essere pari alla decorrenza pensione incrementata di due anni.";
                        //            return false;
                        //        }
                        //    }
                        //}

                        // Per le domande VO con secondo byte del codice natura a 'V', il primo supplemento deve avere Decorrenza pari alla Decorrenza Originaria e gestione 2, 3 o 4
                        if (i == 0 && siglaCategoria == "VO" && codNat2 == 'V')
                        {
                            if (sup.DecorrenzaSupplemento != datiPensione.DecorrenzaOriginaria)
                            {
                                messaggioVideo = "Il primo supplemento deve avere Decorrenza pari alla Decorrenza Pensione.";
                                return false;
                            }

                            if (!(new List<string> { "2", "3", "4" }).Contains(sup.CodGestioneSupplemento))
                            {
                                messaggioVideo = "Il primo supplemento deve avere Codice Gestione pari a 2, 3 o 4.";
                                return false;
                            }
                        }

                        if (ctrl != null && ctrl.ValoreControllo != "NO" && Utility.IsDomandaReversibilitaOrRicostituzione(datiPensione, datiDA) && sup.TipoSupplemento == 'R')
                        {
                            if (sup.DecorrenzaSupplemento == datiPensione.DecorrenzaOriginaria)
                            {
                                if (sup.QuotaSupplemento != 'B' && sup.CodiceLiquidazione.HasValue)
                                {
                                    messaggioVideo = "Il supplemento con decorrenza pari alla decorrenza della pensione deve essere di quota B";
                                    return false;
                                }
                                if (listaSupplementiSenzaQuotaFittizia.Exists(x => x.DecorrenzaSupplemento < datiPensione.DecorrenzaOriginaria &&
                                    x.DecorrenzaSupplemento.Value.Year == datiPensione.DecorrenzaOriginaria.Value.Year && x.QuotaSupplemento == sup.QuotaSupplemento && x.CodGestioneSupplemento == sup.CodGestioneSupplemento))
                                {
                                    if (!sup.CodiceLiquidazione.HasValue)
                                    {
                                        messaggioVideo = "Il supplemento con decorrenza pari alla decorrenza della pensione deve avere codice liquidazione 6";
                                        return false;
                                    }
                                }
                                else if (sup.CodiceLiquidazione.HasValue)
                                {
                                    messaggioVideo = string.Format("Non è consentito inserire il codice liquidazione per il supplemento con decorrenza {0}", sup.DecorrenzaSupplemento.Value.ToString("MM/yyyy"));
                                    return false;
                                }
                            }
                            else
                            {
                                if (sup.CodiceLiquidazione.HasValue)
                                {
                                    messaggioVideo = "Il codice liquidazione 6 è ammesso solo per la quota B con decorrenza pari alla decorrenza della pensione";
                                    return false;
                                }
                            }
                        }
                        i++;

                    }
                }
            }
            //ENG - MEMO 50/2023
            if (((Utility.IsRicostituzione_Supplemento(datiPensione) || (Utility.IsRicostituzione_MotiviContributivi(datiPensione) && datiPensione.Tipo == "0001")) && ctrlAbilitazioneMemo50_2023 != null && ctrlAbilitazioneMemo50_2023.ValoreControllo == "SI") || Utility.IsRicostituzione_PerVariazioneDatiSupplemento(datiPensione))
            {
                //ENG - Per le RIC per supplemento (GPT 0031/0102-0302-0402/0001) deve esserci necessariamente un supplemento non proveniente dal prelievo
                if (Utility.IsRicostituzione_Supplemento(datiPensione) && datiPensione.Tipo == "0001")
                {
                    int numeroSupplementiNoPrelievo = listaSupplementi.Count(x => !x.IsFromPrelievo);

                    if (numeroSupplementiNoPrelievo == 0)
                    {
                        messaggioVideo = "Per le Ricostituzioni per supplemento è necessario inserire almeno un supplemento";
                        return false;
                    }
                }


                //ENG - Per le gestione "M","N" ed "I" rimane il funzionamento che c'era. Corretta la casistica che permetteva di inserire solo quote fittizie A senza la presenza delle quota B
                List<DatiSupplementi> listaSupplementiRetributivi = listaSupplementi.FindAll(x => x.TipoSupplemento == 'R' && (x.CodGestioneSupplemento == "M" || x.CodGestioneSupplemento == "N" || x.CodGestioneSupplemento == "I")).ToList();
                List<DatiSupplementi> listDatiSupplementiQuotaB = (listaSupplementiRetributivi) != null ? listaSupplementiRetributivi.FindAll(x => x.QuotaSupplemento == 'B').ToList() : null;
                if (listaSupplementiRetributivi != null && listaSupplementiRetributivi.Count() > 0)
                {
                    foreach (BLCommon.Entity.DatiSupplementi supp in listaSupplementiRetributivi)
                    {
                        //if (listaSupplementiRetributivi.Exists(x => x.QuotaSupplemento == 'B')) commentato perchè non possono essere inserite solo quote fittizie A
                        //{
                        if (!listaSupplementiRetributivi.Exists(x => x.QuotaSupplemento == 'A' && x.NSettimaneSupplemento == 1 && x.RMSSupplemento < 1) && listaSupplementiRetributivi.Exists(x => x.QuotaSupplemento == 'B'))
                        {
                            messaggioVideo = "Se è presente la quota B deve essere inserito un supplemento di quota A “fittizia” con stessa decorrenza del supplemento di quota B, stessa gestione, settimane 1.";
                            return false;
                        }

                        if ((!supp.IsFromPrelievo || (supp.IsFromPrelievo && supp.QuotaSupplemento == 'A' && supp.NSettimaneSupplemento == 1 && supp.RMSSupplemento < 1))
                            && listaSupplementiRetributivi.FindAll(x => x.QuotaSupplemento == 'A' && x.NSettimaneSupplemento == 1 && x.RMSSupplemento.GetValueOrDefault() < 1).Count() != listaSupplementiRetributivi.FindAll(x => x.QuotaSupplemento == 'B').Count())
                        {
                            messaggioVideo = "Se è presente la quota B deve essere inserito un supplemento di quota A “fittizia” con stessa decorrenza del supplemento di quota B, stessa gestione, settimane 1.";
                            return false;
                        }

                        if ((!supp.IsFromPrelievo || (supp.IsFromPrelievo && supp.NSettimaneSupplemento == 1 && supp.RMSSupplemento < 1))
                            && listaSupplementiRetributivi.FindAll(x => x.QuotaSupplemento == 'A' && x.NSettimaneSupplemento == 1 && x.RMSSupplemento.GetValueOrDefault() < 1).Count() == listaSupplementiRetributivi.FindAll(x => x.QuotaSupplemento == 'B').Count()
                            && supp.QuotaSupplemento == 'A' && (supp.NSettimaneSupplemento == 1 || supp.RMSSupplemento < 1)
                            && listDatiSupplementiQuotaB != null && listDatiSupplementiQuotaB.Where(x => x.DecorrenzaSupplemento == supp.DecorrenzaSupplemento && x.CodGestioneSupplemento == supp.CodGestioneSupplemento && supp.NSettimaneSupplemento == 1 && supp.RMSSupplemento < 1).Count() == 0)
                        {
                            messaggioVideo = "Se è presente la quota B deve essere inserito un supplemento di quota A “fittizia” con stessa decorrenza del supplemento di quota B, stessa gestione, settimane 1.";
                            return false;
                        }
                        //}
                    }
                }

                //ENG - Nuovi controlli per le Gestioni al 100% (NO Gestioni "M", "N" ed "I")
                List<DatiSupplementi> listaSupplementiRetributiviNO50 = listaSupplementi.FindAll(x => x.TipoSupplemento == 'R' && (x.CodGestioneSupplemento != "M" && x.CodGestioneSupplemento != "N" && x.CodGestioneSupplemento != "I")).ToList();
                if (listaSupplementiRetributiviNO50 != null && listaSupplementiRetributiviNO50.Count() > 0)
                {

                    foreach (DatiSupplementi supplemento in listaSupplementiRetributiviNO50)
                    {
                        //se il supplemento è di quota B, deve esserci obbligatoriamente una quota A con stessa gestione e decorrenza (la quota A  può essere non fittizia (settimane maggiore di 1 e RMS maggiore/uguale ad 1 oppure settimane pari ad 1 ) oppure fittizia (settimane pari ad 1 e RMS minore di 1))
                        if (supplemento.QuotaSupplemento == 'B')
                        {
                            if (!listaSupplementiRetributiviNO50.Exists(x => (x.QuotaSupplemento == 'A' && x.CodGestioneSupplemento == supplemento.CodGestioneSupplemento && x.DecorrenzaSupplemento == supplemento.DecorrenzaSupplemento && x.NSettimaneSupplemento >= 1 && x.RMSSupplemento >= 1)
                                || (x.QuotaSupplemento == 'A' && x.CodGestioneSupplemento == supplemento.CodGestioneSupplemento && x.DecorrenzaSupplemento == supplemento.DecorrenzaSupplemento && x.NSettimaneSupplemento == 1 && x.RMSSupplemento < 1)))
                            {
                                messaggioVideo = "Se è presente la quota B deve essere inserito un supplemento di quota A “fittizia” con stessa decorrenza del supplemento di quota B, stessa gestione, settimane 1.";
                                return false;
                            }

                            //non possono esserci più quote B con stessa gestione e decorrenza
                            //Il controllo "Non possono esistere 2 registrazioni con la stessa gestione, quota e decorrenza" non funzionava se veniva inserito RMS pari a 0,004
                            if (listaSupplementiRetributiviNO50.Count(x => x.QuotaSupplemento == 'B' && x.CodGestioneSupplemento == supplemento.CodGestioneSupplemento
                                 && x.DecorrenzaSupplemento == supplemento.DecorrenzaSupplemento) > 1)
                            {
                                //messaggio non parlante per questa casistica
                                messaggioVideo = "Se è presente la quota B deve essere inserito un supplemento di quota A “fittizia” con stessa decorrenza del supplemento di quota B, stessa gestione, settimane 1.";
                                return false;
                            }
                        }

                        if (supplemento.QuotaSupplemento == 'A')
                        {
                            //quota A fittizia: bisogna controllare che questa quota sia associata ad una quota B. Infatti le quote A fittizie non possono essere inserite da sole
                            if (supplemento.NSettimaneSupplemento == 1 && supplemento.RMSSupplemento < 1)
                            {
                                if (!listaSupplementiRetributiviNO50.Exists(x => x.QuotaSupplemento == 'B' && x.CodGestioneSupplemento == supplemento.CodGestioneSupplemento && x.DecorrenzaSupplemento == supplemento.DecorrenzaSupplemento))
                                {
                                    //messaggio non parlante per questa casistica
                                    messaggioVideo = "Se è presente la quota B deve essere inserito un supplemento di quota A “fittizia” con stessa decorrenza del supplemento di quota B, stessa gestione, settimane 1.";
                                    return false;
                                }
                            }

                            //non possono esserci più quote A con stessa gestione e decorrenza
                            //Il controllo "Non possono esistere 2 registrazioni con la stessa gestione, quota e decorrenza" non funzionava se veniva inserito RMS pari a 0,004
                            if (listaSupplementiRetributiviNO50.Count(x => x.QuotaSupplemento == 'A' && x.CodGestioneSupplemento == supplemento.CodGestioneSupplemento
                                 && x.DecorrenzaSupplemento == supplemento.DecorrenzaSupplemento) > 1)
                            {
                                //messaggio non parlante per questa casistica
                                messaggioVideo = "Se è presente la quota B deve essere inserito un supplemento di quota A “fittizia” con stessa decorrenza del supplemento di quota B, stessa gestione, settimane 1.";
                                return false;
                            }

                            //quota A errata (Settimane maggiore di 1 ed RMS minore di 1)
                            //quota A: la casistica Settimane = 1 ed RMS maggiore di 1 è valida 
                            if (supplemento.NSettimaneSupplemento > 1 && supplemento.RMSSupplemento < 1)
                            {
                                //messaggio non parlante per questa casistica
                                messaggioVideo = "Se è presente la quota B deve essere inserito un supplemento di quota A “fittizia” con stessa decorrenza del supplemento di quota B, stessa gestione, settimane 1.";
                                return false;
                            }
                        }
                    }
                }
            }

            return true;
        }

        public static bool AGO_VerificaSupplementiBase(decimal? renditaFacoltativaOrdinaria, decimal? renditaFacoltativaConvenzionale, GestionePensione.DatiPensione datiPensione,
            out string messaggioVideo)
        {
            messaggioVideo = string.Empty;

            //se presente la Quota facoltativa ordinaria (VFAORD) non può essere
            //presente la Quota facoltativa convenzionale (VFACON)
            //se presente la Quota facoltativa convenzionale (VFACON) (VFAORD) non
            //può essere presente la Quota facoltativa ordinaria (VFAORD)
            if (!Utility.IsDomandaRiliquidazioneIndiretta(datiPensione))
            {
                if (renditaFacoltativaOrdinaria.HasValue && renditaFacoltativaConvenzionale.HasValue)
                {
                    messaggioVideo = "Se presente la Quota facoltativa ordinaria non può essere presente la Quota facoltativa convenzionale e viceversa";
                    return false;
                }
            }
            return true;
        }

        public static bool AGO_VerificaIntArt11(BLCommon.Entity.IntegrazioneArt11 intArt11, List<BLCommon.Entity.DatiSupplementi> listaSupplementi,
            GestionePensione.DatiPensione datiPensione, out string messaggioVideo)
        {
            messaggioVideo = string.Empty;

            //il dato non è obbligatorio
            //se esiste un elemento con Codice Gestione (VSGES) = a 5 la Decorrenza
            //Integrazione art. 11 DPR N. 488/68 (VDAR11) è obbligatoria

            if (listaSupplementi != null && listaSupplementi.Count > 0)
            {
                if (listaSupplementi.Exists(x => x.CodGestioneSupplemento == "5") && (intArt11 == null || !intArt11.Decorrenza.HasValue))
                {
                    messaggioVideo = "La decorrenza Integrazione art. 11 DPR N. 488/68 è obbligatoria";
                    return false;
                }
            }

            if (intArt11 != null)
            {
                //se esiste la Decorrenza Integrazione art. 11 DPR N. 488/68 (VDAR11) deve
                //essere presente anche l'Importo IVS Integrazione art. 11 DPR. N. 488/68
                //(VIAR11)
                if (intArt11.Decorrenza.HasValue && !intArt11.ImportoIVS.HasValue)
                {
                    messaggioVideo = "Se esiste la Decorrenza Integrazione art. 11 DPR N. 488/68 deve essere presente anche l'Importo IVS Integrazione art. 11 DPR. N. 488/68";
                    return false;
                }

                //se esiste un elemento con Codice Gestione (VSGES) = a 5 l'Importo IVS
                //(VSIVS) relativo non può essere superiore all'Importo IVS Integrazione art.
                //11 DPR. N. 488/68 (VIAR11)
                if (listaSupplementi != null && listaSupplementi.Exists(x => x.CodGestioneSupplemento == "5" && x.MontanteSupplemento.HasValue && x.MontanteSupplemento.Value > 0)
                    && intArt11.ImportoIVS.HasValue)
                {
                    if ((from s in listaSupplementi where s.CodGestioneSupplemento == "5" && s.MontanteSupplemento.HasValue && s.MontanteSupplemento.Value > 0 select s.MontanteSupplemento).FirstOrDefault().Value >
                        intArt11.ImportoIVS.Value)
                    {
                        messaggioVideo = "Se esiste un elemento con Codice Gestione = a 5 l'Importo IVS relativo non può essere superiore all'Importo IVS Integrazione art. 11 DPR. N. 488/68";
                        return false;
                    }
                }
            }

            return true;
        }

        public static bool AGO_ControlDatiSupplementiEnpalsByDatiPensione(GestionePensione.DatiPensione datiPensione, List<BLCommon.Entity.DatiSupplementiENPALS> datiSupplementi, out string messaggioVideo)
        {
            messaggioVideo = string.Empty;

            if (datiSupplementi != null)
            {
                if (datiPensione == null)
                {
                    messaggioVideo = "Dati Pensione non valorizzati";
                    return false;
                }
            }

            //13-03-2015 Introdotti controlli per evitare di passare valori al calcolo non corretti.
            if (datiSupplementi == null)
                return true;

            //Controllo su RM 9(7)V9(4)
            if (datiSupplementi.Exists(x => !Utility.VerificaRegex(x.RM, cifreIntere: 7, cifreDecimali: 4)))
            {
                messaggioVideo = "Il campo 'RM' deve avere al massimo 7 interi e 4 decimali.";
                return false;
            }
            //Controllo su ImportoContributivoTotale 9(7)V9(4)
            if (datiSupplementi.Exists(x => !Utility.VerificaRegex(x.ImportoContributivoTotale, cifreIntere: 7, cifreDecimali: 4)))
            {
                messaggioVideo = "Il campo 'Importo Contributibo Totale' deve avere al massimo 7 interi e 4 decimali.";
                return false;
            }
            //Controllo su Montante 9(7)V9(4)
            if (datiSupplementi.Exists(x => !Utility.VerificaRegex(x.Montante, cifreIntere: 7, cifreDecimali: 4)))
            {
                messaggioVideo = "Il campo 'Montante' deve avere al massimo 7 interi e 4 decimali.";
                return false;
            }

            return true;
        }

        public static bool AGO_VerificaSupplementiAnte96(List<Entity.DatiSupplementi> listaSupplementi, GestionePensione.DatiPensione datiPensione, GestioneDanteCausa.DatiDanteCausa datiDanteCausa, DateTime? decorrenzaPensioneOrDiretta,
          bool isRiaperturaDomanda, bool isControlloDaEffettuare, out string messaggioVideo)
        {
            messaggioVideo = string.Empty;
            if (Utility.IsPannelloSupplementiAnte96(datiPensione, datiPensione, datiDanteCausa, isRiaperturaDomanda) == false)
                return true;

            DateTime? appData = decorrenzaPensioneOrDiretta;
            bool flagEccezione = false;
            int anniDifferenza = 0;
            char codNat1 = ' ';
            char codNat2 = ' ';
            char codNat3 = ' ';
            string siglaCategoria = datiPensione.SiglaCategoria.Trim().ToUpperInvariant();
            string filtro = datiPensione.GetFiltro();
            Utility.GetCodiciNatura(datiPensione.NaturaPensione, out codNat1, out codNat2, out codNat3);

            List<DatiSupplementi> listaSupplementiRetributivi = listaSupplementi.FindAll(x => x.TipoSupplemento == 'R' && (x.DecorrenzaSupplemento.HasValue && x.DecorrenzaSupplemento.Value > new DateTime(1995, 12, 31))).ToList();
            List<DatiSupplementi> listDatiSupplementiQuotaB = listaSupplementiRetributivi.FindAll(x => x.QuotaSupplemento == 'B').ToList();
            List<DatiSupplementi> listDatiSupplementiQuotaA = listaSupplementiRetributivi.FindAll(x => x.QuotaSupplemento == 'A').ToList();
            List<BLCommon.Entity.DatiSupplementi> listaSupplementiSenzaQuotaFittizia = listaSupplementi != null ?
        listaSupplementi.FindAll(x => !((x.RMSSupplemento == 0.004M || x.RMSSupplemento == 0.0005M) && x.NSettimaneSupplemento == 1)) : null;
            List<DatiSupplementi> suppCodGestione2 = listDatiSupplementiQuotaB.FindAll(x => x.CodGestioneSupplemento == "2").ToList();
            List<DatiSupplementi> suppCodGestione3 = listDatiSupplementiQuotaB.FindAll(x => x.CodGestioneSupplemento == "3").ToList();
            List<DatiSupplementi> suppCodGestione4 = listDatiSupplementiQuotaB.FindAll(x => x.CodGestioneSupplemento == "4").ToList();

            DateTime dataLimiteSupplementi = new DateTime(1996, 01, 01);

            if (listaSupplementiRetributivi.Exists(x => x.QuotaSupplemento == 'B'))
            {
                foreach (BLCommon.Entity.DatiSupplementi supp in listaSupplementiRetributivi)
                {

                    if (listaSupplementiRetributivi.Exists(x => x.QuotaSupplemento == 'A'))
                    {
                        if (Utility.DataSuccessivaA(supp.DecorrenzaSupplemento.GetValueOrDefault(), dataLimiteSupplementi) && ((supp.QuotaSupplemento == 'B' && listDatiSupplementiQuotaB.Where(x => (x.DecorrenzaSupplemento == supp.DecorrenzaSupplemento && x.CodGestioneSupplemento == supp.CodGestioneSupplemento)).Count() > 1) ||
                                  (supp.QuotaSupplemento == 'A' && listDatiSupplementiQuotaA.Where(x => x.DecorrenzaSupplemento == supp.DecorrenzaSupplemento && x.CodGestioneSupplemento == supp.CodGestioneSupplemento).Count() > 1)))
                        {
                            messaggioVideo = "Non possono esistere 2 registrazioni con la stessa gestione, decorrenza e quota supplemento.";
                            return false;
                        }
                    }

                    if (supp.QuotaSupplemento == 'B' && listDatiSupplementiQuotaA.Where(x => x.DecorrenzaSupplemento == supp.DecorrenzaSupplemento && (x.CodGestioneSupplemento == supp.CodGestioneSupplemento)).Count() == 0)
                    {
                        messaggioVideo = "Se è presente la quota B deve essere inserito un supplemento di quota A “fittizia” con stessa decorrenza del supplemento di quota B, stessa gestione, settimane 1.";
                        return false;
                    }

                    if (supp.NSettimaneSupplemento == 1 && supp.RMSSupplemento >= 1 && supp.QuotaSupplemento == 'A')
                    {
                        messaggioVideo = "Se il numero settimane è uguale a 1 l'RMS deve essere minore di 1.";
                        return false;
                    }

                    if ((supp.CodGestioneSupplemento == "I" || supp.CodGestioneSupplemento == "M" || supp.CodGestioneSupplemento == "N") && supp.QuotaSupplemento == 'B' && Utility.DataStrettamenteSuccessivaA(supp.DecorrenzaSupplemento.GetValueOrDefault(), new DateTime(1995, 12, 31)))
                    {

                        var supplementoTemp = supp.CodGestioneSupplemento == "I" ? suppCodGestione2.Find(x => x.DecorrenzaSupplemento == supp.DecorrenzaSupplemento) :
                                                      supp.CodGestioneSupplemento == "M" ? suppCodGestione3.Find(x => x.DecorrenzaSupplemento == supp.DecorrenzaSupplemento) :
                                                      supp.CodGestioneSupplemento == "N" ? suppCodGestione4.Find(x => x.DecorrenzaSupplemento == supp.DecorrenzaSupplemento) :
                                                      null;
                        if (supplementoTemp != null && supplementoTemp.RMSSupplemento != supp.RMSSupplemento)
                        {
                            messaggioVideo = string.Format("La retribuzione media settimanale deve essere uguale alla corrispondente gestione del supplemento con quota B e codice gestione pari a {0} per il supplemento retributivo con gestione pari a {1}.", supp.CodGestioneSupplemento, supplementoTemp.CodGestioneSupplemento);
                            return false;
                        }
                    }

                }
            }

            if (listaSupplementi != null && listaSupplementi.Count > 0)
            {

                if (!AGO_VerificaSupplementiAnte96Incrociati(listaSupplementi, datiPensione, datiDanteCausa, decorrenzaPensioneOrDiretta, isRiaperturaDomanda, out messaggioVideo))
                    return false;

                List<DateTime?> listaDecorrenze = listaSupplementi.Where(x => x.DecorrenzaSupplemento > new DateTime(1989, 12, 31)).GroupBy(x => x.DecorrenzaSupplemento).Select(x => x.First()).Select(x => x.DecorrenzaSupplemento).OrderBy(x => x).ToList();

                //INC000001491746 - INC000001533425 - supplementi mezzadri - AGO Interventi Puntuali §4.4.1.8   
                if (((siglaCategoria == "VO" || siglaCategoria == "IO" || siglaCategoria == "SO") && codNat3 == 'M' && listaSupplementi.Count(x => x.DecorrenzaSupplemento == listaDecorrenze.First().Value && x.CodGestioneSupplemento == "2" && x.QuotaSupplemento == 'A') > 0))
                {
                    listaDecorrenze.RemoveAt(0);
                }

                foreach (DateTime? decorrenzaSupplemento in listaDecorrenze)
                {
                    anniDifferenza = (decorrenzaSupplemento.Value - Utility.FirstDayOfMonth(appData.Value)).Days / 365;
                    if (!(Utility.IsDomandaReversibilitaOrRicostituzione(datiPensione, datiDanteCausa) &&
                        decorrenzaSupplemento == Utility.FirstDayOfMonth(datiPensione.DecorrenzaOriginaria.Value)))
                    {
                        if (anniDifferenza < 2 && !GestioneBypassControllo.CheckAndLockBypassControlloByNomeBypass(datiPensione, GestioneBypassControllo.NomeBypass.SUP_INF_2AN_SENT_O_ART6_L40790.SUP_INF_2AN_SENT_O_ART6_L40790))
                        {
                            messaggioVideo = "E' consentito inserire un supplemento solamente dopo 5 anni dalla decorrenza della pensione o dal precedente supplemento (" + String.Format("{0:MM/yyyy}", appData) + ") con un'unica eccezione a 2 anni.";
                            return false;
                        }

                        if (anniDifferenza >= 2 && anniDifferenza < 5)
                        {
                            if (flagEccezione)
                            {
                                messaggioVideo = "E' consentito un unico supplemento dopo 2 anni dalla decorrenza della pensione o dal precedente supplemento (" + String.Format("{0:MM/yyyy}", appData) + "). " +
                                       "Il successivo supplemento deve essere inserito dopo 5 anni dal precedente.";
                                return false;
                            }
                            else
                                flagEccezione = true;
                        }
                    }
                    appData = decorrenzaSupplemento;
                }
            }
            return true;
        }

        public static bool AGO_VerificaSupplementiAnte96Incrociati(List<Entity.DatiSupplementi> listaSupplementi, GestionePensione.DatiPensione datiPensione, GestioneDanteCausa.DatiDanteCausa datiDanteCausa, DateTime? decorrenzaPensioneOrDiretta,
        bool isRiaperturaDomanda, out string messaggioVideo)
        {
            messaggioVideo = string.Empty;
            if (Utility.IsPannelloSupplementiAnte96(datiPensione, datiPensione, datiDanteCausa, isRiaperturaDomanda) == false)
                return true;

            //l’inserimento di un nuovo supplemento deve essere reso obbligatorio 
            if (Utility.IsRicostituzione_Supplemento(datiPensione) && (listaSupplementi == null || listaSupplementi.Count == 0 || (listaSupplementi != null && listaSupplementi.Count > 0 && listaSupplementi.Find(x => !x.IsFromPrelievo) == null)))
            {
                messaggioVideo = "Con il prodotto di supplemento è obbligatorio inserire almeno un nuovo supplemento.";
                return false;
            }

            if (listaSupplementi != null && listaSupplementi.Count > 0)
            {
                if (Utility.IsRicostituzione_PerVariazioneDatiSupplemento(datiPensione) && listaSupplementi.Find(x => !x.IsFromPrelievo) != null)
                {
                    List<DateTime?> listaDecorrenzeNuoviInserimenti = listaSupplementi.Where(x => !x.IsFromPrelievo).GroupBy(x => x.DecorrenzaSupplemento).Select(x => x.First()).Select(x => x.DecorrenzaSupplemento).OrderBy(x => x).ToList();
                    var listaSupplementiFromPrelievo = listaSupplementi.Where(x => x.IsFromPrelievo).ToList();
                    foreach (DateTime? decorrenzaSupplemento in listaDecorrenzeNuoviInserimenti)
                    {
                        if (listaSupplementiFromPrelievo == null || listaSupplementiFromPrelievo.Find(x => x.DecorrenzaSupplemento == decorrenzaSupplemento) == null)
                        {
                            messaggioVideo = "E' consentito l’inserimento di un nuovo supplemento esclusivamente con pari decorrenza di uno già presente nella pensione";
                            return false;
                        }
                    }
                }
            }

            return true;
        }
        /// <summary>
        /// Il controllo riguarda la data di decorrenza del supplemento: è consentito inserire un supplemento solamente dopo 5 anni dalla decorrenza della pensione o del precedente supplemento.
        /// È consentita un’ unica eccezione, per cui è possibile inserire il supplemento dopo 2 anni dal precedente supplemento  o dalla decorrenza della pensione.
        /// </summary>
        /// <param name="listDatiSupplementi"></param>
        /// <param name="decorrenzaOriginaria"></param>
        /// <param name="messaggioVideo"></param>
        /// <returns></returns>
        public static bool AGO_VerificaSupplementiDecorrenza(List<Entity.DatiSupplementi> listDatiSupplementi, GestionePensione.DatiPensione datiPensione, GestioneDanteCausa.DatiDanteCausa datiDanteCausa, BLCommon.GestioneAnagrafica.DatiAnagrafici datiAnagrafici, DateTime? decorrenzaPensioneOrDiretta,
        bool isRiaperturaDomanda, bool isControlloDaEffettuare, out string messaggioVideo)
        {

            messaggioVideo = string.Empty;
            if (!Utility.IsDomandaRiliquidazioneIndiretta(datiPensione))
            {
                DateTime? appData = decorrenzaPensioneOrDiretta;
                bool flagEccezione = false;
                int anniDifferenza = 0;
                char codNat1 = ' ';
                char codNat2 = ' ';
                char codNat3 = ' ';
                string siglaCategoria = datiPensione.SiglaCategoria.Trim().ToUpperInvariant();
                string filtro = datiPensione.GetFiltro();
                Utility.GetCodiciNatura(datiPensione.NaturaPensione, out codNat1, out codNat2, out codNat3);

                if (!appData.HasValue)
                {
                    messaggioVideo = "La decorrenza pensione non è valorizzata.";
                    return false;
                }

                if (listDatiSupplementi != null && listDatiSupplementi.Count > 0)
                {
                    List<DateTime?> listaDecorrenze = listDatiSupplementi.GroupBy(x => x.DecorrenzaSupplemento).Select(x => x.First()).Select(x => x.DecorrenzaSupplemento).OrderBy(x => x).ToList();
                    GestioneLavorazione.DatiLavorazione datiLavorazione = null;
                    GestioneLavorazione.GetLavorazioneByIdPensione(datiPensione.Id, out datiLavorazione);
                    GestioneControlliDinamici.ControlloDinamico ctrl = null;
                    GestioneControlliDinamici.GetControlloDinamicoByNomeControllo("AbilitazioneRilascioRIC_31082020", out ctrl);
                    //ENG - MEMO 50/2023
                    GestioneControlliDinamici.ControlloDinamico ctrlAbilitazioneMemo50_2023 = null;
                    GestioneControlliDinamici.GetControlloDinamicoByNomeControllo("AbilitazioneMemo50_2023", out ctrlAbilitazioneMemo50_2023);

                    //13/05/2022 Per le domande FPLD, Gestione Autonomi, Inpdai, Aut in caso di RIC CONTRIBUTIVE / DOCUMENTALI si può inserire un Supplemento con decorrenza uguale a 
                    // quella del Supplemento già presente (ovvero proveniente dal prelievo). 
                    if ((Utility.IsRicostituzione_MotiviContributivi(datiPensione) || Utility.IsRicostituzione_MotiviDocumentali(datiPensione))
                        && (Utility.IsDomandaFPLD(datiPensione.SiglaCategoria) || Utility.IsDomandaGestioneAutonomi(datiPensione.SiglaCategoria) || Utility.IsDomandaINPDAI(datiPensione.SiglaCategoria) || Utility.IsDomandaAUT(datiPensione)))
                    {
                        List<BLCommon.Entity.DatiSupplementi> listaSupplementiStorico = null;
                        BLCommon.GestioneSupplementi.GetSupplementiStoricoByIdPensione(datiPensione.Id, out listaSupplementiStorico);
                        List<DatiSupplementi> listaSupplementiDaPrelievo = new List<DatiSupplementi>();
                        //ENG - MEMO 50/2023
                        if (ctrlAbilitazioneMemo50_2023 != null && ctrlAbilitazioneMemo50_2023.ValoreControllo == "SI" &&
                            listaSupplementiStorico != null && listaSupplementiStorico.Count() > 0 && Utility.IsRicostituzione_MotiviContributivi(datiPensione) && datiPensione.Tipo == "0001")
                            listaSupplementiDaPrelievo = listaSupplementiStorico;
                        else
                            listaSupplementiDaPrelievo = listDatiSupplementi.FindAll(x => x.IsFromPrelievo);

                        if (listaSupplementiDaPrelievo != null && listaSupplementiDaPrelievo.Count() > 0)
                        {
                            List<DateTime?> listaDecorrenzeDaPrelievo = listaSupplementiDaPrelievo.GroupBy(x => x.DecorrenzaSupplemento).Select(x => x.First()).Select(x => x.DecorrenzaSupplemento).ToList();
                            List<DatiSupplementi> listaSupplementiRetributiviNoPrelievo = listDatiSupplementi.FindAll(x => !x.IsFromPrelievo && x.TipoSupplemento == 'R');
                            if (listaSupplementiRetributiviNoPrelievo != null && listaSupplementiRetributiviNoPrelievo.Count() > 0)
                            {
                                foreach (DatiSupplementi supplemento in listaSupplementiRetributiviNoPrelievo)
                                {
                                    if (listaDecorrenzeDaPrelievo != null && listaDecorrenzeDaPrelievo.Count() > 0 && !listaDecorrenzeDaPrelievo.Contains(supplemento.DecorrenzaSupplemento))
                                    {
                                        messaggioVideo = "L'inserimento di un nuovo supplemento è consentito solo per le domande di Ricostituzione per supplemento";
                                        return false;
                                    }
                                }
                            }

                            List<DatiSupplementi> listaSupplementiContributiviNoPrelievo = listDatiSupplementi.FindAll(x => !x.IsFromPrelievo && x.TipoSupplemento == 'C');
                            if (listaSupplementiContributiviNoPrelievo != null && listaSupplementiContributiviNoPrelievo.Count() > 0)
                            {
                                foreach (DatiSupplementi supplemento in listaSupplementiContributiviNoPrelievo)
                                {
                                    if (listaDecorrenzeDaPrelievo != null && listaDecorrenzeDaPrelievo.Count() > 0 && !listaDecorrenzeDaPrelievo.Contains(supplemento.DecorrenzaSupplemento))
                                    {
                                        messaggioVideo = "L'inserimento di un nuovo supplemento è consentito solo per le domande di Ricostituzione per supplemento";
                                        return false;
                                    }
                                }
                            }
                        }
                    }

                    //ENG - MEMO 50/2023
                    //Può essere inserito un nuovo supplemento solo se viene cancellato uno eistente dal prelievo e dovrà avere la stessa gestione, decorrenza e stesse settimane
                    if (Utility.IsRicostituzione_MotiviContributivi(datiPensione) && datiPensione.Tipo == "0001" && isControlloDaEffettuare)
                    {
                        if (ctrlAbilitazioneMemo50_2023 != null && ctrlAbilitazioneMemo50_2023.ValoreControllo == "SI")
                        {
                            List<BLCommon.Entity.DatiSupplementi> listaSupplementiStorico = null;
                            BLCommon.GestioneSupplementi.GetSupplementiStoricoByIdPensione(datiPensione.Id, out listaSupplementiStorico);
                            List<BLCommon.Entity.DatiSupplementi> listaSupplementiSenzaQuotaFittizia = listDatiSupplementi.FindAll(x => !(x.QuotaSupplemento == 'A' && x.NSettimaneSupplemento.GetValueOrDefault() == 1 && x.RMSSupplemento.GetValueOrDefault() < 1));
                            List<BLCommon.Entity.DatiSupplementi> listaSupplementiNoPrelievo = listaSupplementiSenzaQuotaFittizia.FindAll(x => !x.IsFromPrelievo);
                            GestioneIstruttoria.DatiIstruttoria datiIstruttoria = null;
                            GestioneIstruttoria.GetIstruttoriaByIdPensione(datiPensione.Id, out datiIstruttoria);
                            bool isTipoCalcoloModificato = false;
                            if (datiPensione.TipoCalcolo.HasValue && datiIstruttoria != null && datiIstruttoria.TipoCalcoloPrecedente.HasValue && datiPensione.TipoCalcolo != datiIstruttoria.TipoCalcoloPrecedente)
                                isTipoCalcoloModificato = true;

                            if (listaSupplementiStorico != null && listaSupplementiStorico.Count() > 0)
                            {
                                if (isTipoCalcoloModificato && listaSupplementiSenzaQuotaFittizia.Count() != listaSupplementiStorico.Count())
                                {
                                    messaggioVideo = "L'inserimento di un nuovo supplemento è consentito solo se viene eliminato uno già presente dal prelievo";
                                    return false;
                                }

                                List<BLCommon.Entity.DatiSupplementi> listaSupplementiEliminati = new List<BLCommon.Entity.DatiSupplementi>();
                                foreach (DatiSupplementi supStorico in listaSupplementiStorico)
                                {
                                    if (supStorico.TipoSupplemento == 'R')
                                    {
                                        if (!listaSupplementiSenzaQuotaFittizia.Exists(x => x.QuotaSupplemento == supStorico.QuotaSupplemento && x.NSettimaneSupplemento == supStorico.NSettimaneSupplemento &&
                                            x.DecorrenzaSupplemento == supStorico.DecorrenzaSupplemento && x.CodGestioneSupplemento == supStorico.CodGestioneSupplemento && x.RMSSupplemento == supStorico.RMSSupplemento))
                                            listaSupplementiEliminati.Add(supStorico);
                                    }
                                    else if (supStorico.TipoSupplemento == 'C')
                                    {
                                        if (!listaSupplementiSenzaQuotaFittizia.Exists(x => x.CodiceLiquidazione == supStorico.CodiceLiquidazione && x.NSettimaneSupplemento == supStorico.NSettimaneSupplemento &&
                                            x.DecorrenzaSupplemento == supStorico.DecorrenzaSupplemento && x.CodGestioneSupplemento == supStorico.CodGestioneSupplemento && x.MontanteSupplemento == supStorico.MontanteSupplemento && x.AmmontareContributivo == supStorico.AmmontareContributivo))
                                            listaSupplementiEliminati.Add(supStorico);
                                    }
                                }

                                if (listaSupplementiNoPrelievo != null && listaSupplementiNoPrelievo.Count() > 0 && listaSupplementiEliminati != null && listaSupplementiEliminati.Count() > 0)
                                {
                                    foreach (DatiSupplementi supp in listaSupplementiNoPrelievo)
                                    {
                                        if (isTipoCalcoloModificato && !listaSupplementiEliminati.Exists(x => x.CodGestioneSupplemento == supp.CodGestioneSupplemento && x.DecorrenzaSupplemento == supp.DecorrenzaSupplemento && x.NSettimaneSupplemento == supp.NSettimaneSupplemento &&
                                            ((x.TipoSupplemento == 'R' && x.QuotaSupplemento != supp.QuotaSupplemento) || (x.TipoSupplemento == 'C' && x.CodiceLiquidazione != supp.CodiceLiquidazione))))
                                        {
                                            messaggioVideo = "L'inserimento di un nuovo supplemento è consentito solo con pari decorrenza, codice gestione e settimane in quota diversa da quella in cui era precedentemente registrato";
                                            return false;
                                        }
                                    }
                                }
                            }
                        }
                    }

                    if (filtro == "BNS" || filtro == "BNX" ||
                        (Utility.IsRicostituzioneOrRiapertura(datiPensione, isRiaperturaDomanda) && (codNat2 == 'Y' || Utility.IsDomandaPensioneSuperstitiOrRicostituzione(datiPensione) && !(ctrl != null && ctrl.ValoreControllo != "NO" && Utility.IsDomandaReversibilitaOrRicostituzione(datiPensione, datiDanteCausa)))) ||
                        ((siglaCategoria == "VO" || siglaCategoria == "IO" || siglaCategoria == "SO" || siglaCategoria == "VR") && codNat3 == 'M' && listDatiSupplementi.Count(x => x.DecorrenzaSupplemento == listaDecorrenze.First().Value && x.CodGestioneSupplemento == "2" && x.QuotaSupplemento == 'A') > 0) ||
                        (siglaCategoria == "VO" && codNat2 == 'V' && datiLavorazione != null && (datiLavorazione.CodFase == "0036" || datiLavorazione.CodFase == "0033" || datiLavorazione.CodFase == "0034" || datiLavorazione.CodFase == "0035" || datiLavorazione.CodFase == "0038") &&
                         listDatiSupplementi.Count(x => (x.CodGestioneSupplemento == "2" || x.CodGestioneSupplemento == "3" || x.CodGestioneSupplemento == "4") && x.DecorrenzaSupplemento == decorrenzaPensioneOrDiretta) > 0) ||
                        (Utility.IsRicostituzione(datiPensione.Gruppo) && siglaCategoria.StartsWith("V") && (codNat1 == ' ' || codNat1 == '6') && codNat2 == 'V' &&
                         listDatiSupplementi.Count(x => (x.CodGestioneSupplemento == "2" || x.CodGestioneSupplemento == "3" || x.CodGestioneSupplemento == "4") && x.DecorrenzaSupplemento == decorrenzaPensioneOrDiretta) > 0) ||
                        (Utility.IsDomandaPensioneIndirettaOrRicostituzione(datiPensione, datiDanteCausa) && siglaCategoria == "SO" &&
                        listDatiSupplementi.Count(x => new List<string> { "2", "3", "4", "I", "M", "N" }.Contains(x.CodGestioneSupplemento) && x.DecorrenzaSupplemento == decorrenzaPensioneOrDiretta) > 0) ||
                        (Utility.IsRicostituzioneOrRiapertura(datiPensione, isRiaperturaDomanda) && codNat2 == 'V' && (siglaCategoria == "VO" || siglaCategoria == "IO" || siglaCategoria == "SO") &&
                         listDatiSupplementi.Count(x => (x.CodGestioneSupplemento == "2" || x.CodGestioneSupplemento == "3" || x.CodGestioneSupplemento == "4") && x.DecorrenzaSupplemento == decorrenzaPensioneOrDiretta) > 0))
                    {
                        DateTime? primaDecorrenza = listaDecorrenze.First();
                        anniDifferenza = (primaDecorrenza.Value - Utility.FirstDayOfMonth(appData.Value)).Days / 365;
                        if (anniDifferenza < 2)
                        {
                            if (primaDecorrenza.Value != Utility.FirstDayOfMonth(datiPensione.DecorrenzaOriginaria.GetValueOrDefault()) &&
                                (datiDanteCausa == null || datiDanteCausa.DecorrenzaPensione == null || primaDecorrenza.Value != Utility.FirstDayOfMonth(datiDanteCausa.DecorrenzaPensione.GetValueOrDefault()))
                                && !GestioneBypassControllo.CheckAndLockBypassControlloByNomeBypass(datiPensione, GestioneBypassControllo.NomeBypass.SUP_INF_2AN_SENT_O_ART6_L40790.SUP_INF_2AN_SENT_O_ART6_L40790))
                            {
                                messaggioVideo = "E' consentito inserire un supplemento solamente dopo 5 anni dalla decorrenza della pensione o dal precedente supplemento (" + String.Format("{0:MM/yyyy}", appData) + ") con un'unica eccezione a 2 anni.";
                                return false;
                            }
                            else
                                listaDecorrenze.RemoveAt(0);
                        }
                    }

                    if (!Utility.IsDomandaAUT(datiPensione))
                    {
                        GestioneControlliDinamici.ControlloDinamico AbilitazioneCtrlSupplementi = null;
                        GestioneControlliDinamici.GetControlloDinamicoByNomeControllo("AbilitazioneCtrlSupplementi", out AbilitazioneCtrlSupplementi);
                        bool applicaControlli = AbilitazioneCtrlSupplementi != null && !String.IsNullOrEmpty(AbilitazioneCtrlSupplementi.ValoreControllo) && AbilitazioneCtrlSupplementi.ValoreControllo.Trim().ToUpperInvariant() == "SI";

                        foreach (DateTime? decorrenzaSupplemento in listaDecorrenze)
                        {
                            anniDifferenza = (decorrenzaSupplemento.Value - Utility.FirstDayOfMonth(appData.Value)).Days / 365;
                            if (!(ctrl != null && ctrl.ValoreControllo != "NO" && Utility.IsDomandaReversibilitaOrRicostituzione(datiPensione, datiDanteCausa) &&
                                decorrenzaSupplemento == Utility.FirstDayOfMonth(datiPensione.DecorrenzaOriginaria.Value)) &&
                                !(Utility.IsRicostituzione(datiPensione.Gruppo) && Utility.IsDomandaReversibilitaOrRicostituzione(datiPensione, datiDanteCausa) && codNat2 == 'V' &&
                                  datiDanteCausa != null && datiDanteCausa.DecorrenzaPensione.HasValue && decorrenzaSupplemento == Utility.FirstDayOfMonth(datiDanteCausa.DecorrenzaPensione.Value)))
                            {

                                if (anniDifferenza < 2 && !GestioneBypassControllo.CheckAndLockBypassControlloByNomeBypass(datiPensione, GestioneBypassControllo.NomeBypass.SUP_INF_2AN_SENT_O_ART6_L40790.SUP_INF_2AN_SENT_O_ART6_L40790))
                                {
                                    messaggioVideo = "E' consentito inserire un supplemento solamente dopo 5 anni dalla decorrenza della pensione o dal precedente supplemento (" + String.Format("{0:MM/yyyy}", appData) + ") con un'unica eccezione a 2 anni.";
                                    return false;
                                }

                                int reqMM = 0;
                                int reqAA = 0;
                                GestioneDecodifica.GetCtrlRequisitoEta_Avanzato(decorrenzaSupplemento.Value, datiPensione.GetCodCategoria(), datiAnagrafici.Sesso, Utility.TipoAppartenenza.AGO.ToString(), datiPensione.Tipo, out reqAA, out reqMM);

                                if (anniDifferenza >= 2 && anniDifferenza < 5)
                                {
                                    if (flagEccezione)
                                    {
                                        messaggioVideo = "E' consentito un unico supplemento dopo 2 anni dalla decorrenza della pensione o dal precedente supplemento (" + String.Format("{0:MM/yyyy}", appData) + "). " +
                                               "Il successivo supplemento deve essere inserito dopo 5 anni dal precedente.";
                                        return false;
                                    }
                                    else
                                    //supplemento infraquinquennale
                                    {
                                        if (applicaControlli && datiPensione.TipoAutomazione != null && datiPensione.TipoAutomazione == 1 && decorrenzaSupplemento < datiAnagrafici.DataNascita.Value.AddMonths(reqMM).AddYears(reqAA))
                                        {
                                            messaggioVideo = "Attenzione il supplemento infraquinquennale non rispetta il requisito di età";
                                            return false;
                                        }

                                        flagEccezione = true;
                                    }
                                }

                                if (applicaControlli && datiPensione.TipoAutomazione != null && datiPensione.TipoAutomazione == 1 && (datiPensione.SiglaCategoria == "VO" || datiPensione.SiglaCategoria == "IO") && Utility.isGestioneAutonoma(datiPensione.Gestione))
                                {
                                    if (decorrenzaSupplemento < datiAnagrafici.DataNascita.Value.AddMonths(reqMM).AddYears(reqAA))
                                    {
                                        messaggioVideo = "Attenzione il supplemento di gestione autonoma su pensione FPLD non rispetta il requisito di età";
                                        return false;
                                    }
                                }
                            }

                            appData = decorrenzaSupplemento;
                        }
                    }
                    else
                    {
                        flagEccezione = false;
                        appData = decorrenzaPensioneOrDiretta;
                        bool permettiInserimentoUnaSolaVoltaConBypass = true;

                        foreach (DateTime? decorrenzaSupplemento in listaDecorrenze)
                        {
                            anniDifferenza = (decorrenzaSupplemento.Value - Utility.FirstDayOfMonth(appData.Value)).Days / 365;
                            if (!(ctrl != null && ctrl.ValoreControllo != "NO" && Utility.IsDomandaReversibilitaOrRicostituzione(datiPensione, datiDanteCausa) &&
                                decorrenzaSupplemento == Utility.FirstDayOfMonth(datiPensione.DecorrenzaOriginaria.Value)))
                            {
                                if (anniDifferenza < 2 && !GestioneBypassControllo.CheckAndLockBypassControlloByNomeBypass(datiPensione, GestioneBypassControllo.NomeBypass.SUP_INF_2AN_SENT_O_ART6_L40790.SUP_INF_2AN_SENT_O_ART6_L40790))
                                {
                                    messaggioVideo = "E' consentito inserire un supplemento solamente dopo 5 anni dalla decorrenza della pensione o dal precedente supplemento (" + String.Format("{0:MM/yyyy}", appData) + ") con un'unica eccezione a 2 anni.";
                                    return false;
                                }

                                if (anniDifferenza >= 2 && anniDifferenza < 5)
                                {
                                    if (flagEccezione)
                                    {
                                        //ENG - Il bypass consente di inserire una sola volta un supplemento con decorrenza inferiore ai 5 anni dal precedente supplemento
                                        if (!GestioneBypassControllo.CheckAndLockBypassControlloByNomeBypass(datiPensione, GestioneBypassControllo.NomeBypass.Suppl_2_5_Anni_Sentenza_VOAUT.SUPPL_2_5_ANNI_SENTENZA_VOAUT) || !permettiInserimentoUnaSolaVoltaConBypass)
                                        {
                                            messaggioVideo = "Solo per la prima volta (primo supplemento) è consentito l'inserimento dopo 2 anni dalla decorrenza della pensione. Il successivo supplemento deve essere inserito dopo 5 anni dal precedente.";
                                            return false;
                                        }

                                        permettiInserimentoUnaSolaVoltaConBypass = false;
                                    }
                                }
                            }
                            //per le AUT il supplemento dopo 2 anni è ammesso solo per il primo supplemento e non per gli altri
                            flagEccezione = true;
                            appData = decorrenzaSupplemento;
                        }
                    }
                }
            }
            return true;
        }

        /// <summary>
        /// Il controllo riguarda la data di decorrenza del supplemento: è consentito inserire un supplemento solamente dopo 5 anni dalla decorrenza della pensione o del precedente supplemento.
        /// È consentita un’ unica eccezione, per cui è possibile inserire il supplemento dopo 2 anni dal precedente supplemento  o dalla decorrenza della pensione.
        /// </summary>
        /// <param name="listDatiSupplementi"></param>
        /// <param name="decorrenzaOriginaria"></param>
        /// <param name="messaggioVideo"></param>
        /// <returns></returns>
        public static bool AGO_VerificaSupplementiDecorrenza(List<DatiSupplementiCumulo> listDatiSupplementi, GestionePensione.DatiPensione datiPensione, DateTime? decorrenzaPensione,
            bool isRiaperturaDomanda, BLCommon.GestioneDanteCausa.DatiDanteCausa datiDanteCausa, List<GestioneDecodifica.DecEnteGestioneFondo> listaDecEnteGestioneFondo, out string messaggioVideo, ref List<string> codiciMessaggio)
        {
            messaggioVideo = string.Empty;
            DateTime? appData = decorrenzaPensione;
            bool flagEccezione = false;
            int anniDifferenza = 0;
            bool isRicREV = false;
            bool isRicCumulo = false;
            List<long> listaIdEnte = null;
            if (!Utility.IsDomandaRiliquidazioneIndiretta(datiPensione))
            {
                if (Utility.IsRicostituzione(datiPensione.Gruppo) && Utility.IsDomandaPensioneReversibilitaOrRicostituzione(datiPensione, datiDanteCausa))
                    isRicREV = true;

                if (((Utility.IsRicostituzione(datiPensione.Gruppo) && Utility.IsDomandaCumulo(datiPensione.SiglaCategoria)) || (Utility.IsDomandaTotalizzazione(datiPensione.SiglaCategoria) && (Utility.IsRicostituzioneOrRiapertura(datiPensione, isRiaperturaDomanda)))) && !isRicREV)
                    isRicCumulo = true;

                if (isRicCumulo)
                {
                    listaIdEnte = listaDecEnteGestioneFondo.Where(x => x.Codice == "A1" || x.Codice == "A2" || x.Codice == "A3" || x.Codice == "A4" || x.Codice == "A5" || x.Codice == "B6").Select(x => x.Id).ToList();
                    //ENG - Ric Cumulo: la gestione A9 segue le stesse regole delle gestioni A1, A2, A3, A4 e A5
                    if (Utility.IsRicostituzione(datiPensione.Gruppo) && Utility.IsDomandaCumulo(datiPensione.SiglaCategoria) && listaDecEnteGestioneFondo.Exists(x => x.Codice == "A9"))
                        listaIdEnte.Add(listaDecEnteGestioneFondo.Find(x => x.Codice == "A9").Id);

                    //ENG - Ric Cumulo: la gestione A8 segue le stesse regole delle gestioni A1, A2, A3, A4, A5 e A9
                    if (Utility.IsRicostituzione(datiPensione.Gruppo) && Utility.IsDomandaCumulo(datiPensione.SiglaCategoria) && listaDecEnteGestioneFondo.Exists(x => x.Codice == "A8"))
                        listaIdEnte.Add(listaDecEnteGestioneFondo.Find(x => x.Codice == "A8").Id);
                }
                else
                    listaIdEnte = listaDecEnteGestioneFondo.Where(x => x.Codice == "A1" || x.Codice == "A2" || x.Codice == "A3" || x.Codice == "A4").Select(x => x.Id).ToList();

                if (!appData.HasValue)
                {
                    messaggioVideo = "La decorrenza pensione non è valorizzata.";
                    return false;
                }

                if (listDatiSupplementi != null && listDatiSupplementi.Count > 0)
                {
                    if (!isRicREV)
                    {
                        if (!Utility.IsDomandaSOCUM(datiPensione.SiglaCategoria) && !Utility.IsDomandaSOTOT(datiPensione.SiglaCategoria) &&
                        isRicREV && listDatiSupplementi.Count(x => x.Decorrenza == datiPensione.DecorrenzaOriginaria) > 1)
                        {
                            messaggioVideo = "E' consentito inserire un unico supplemento contestuale alla Decorrenza Pensone";
                            return false;
                        }
                        List<KeyValuePair<bool, DateTime?>> listaDecorrenze = null;
                        if (isRicCumulo)
                        {
                            listaDecorrenze = listDatiSupplementi.Where(x => x.EnteGestioneFondo != 14).Select(x => new KeyValuePair<bool, DateTime?>(listaIdEnte.Contains(x.EnteGestioneFondo), x.Decorrenza)).OrderBy(x => x.Value).ThenByDescending(x => x.Key).ToList();
                        }
                        else
                            listaDecorrenze = listDatiSupplementi.GroupBy(x => new { IsIn = listaIdEnte.Contains(x.EnteGestioneFondo), x.Decorrenza }).Select(x => x.First()).Select(x => new KeyValuePair<bool, DateTime?>(listaIdEnte.Contains(x.EnteGestioneFondo), x.Decorrenza)).OrderBy(x => x.Value).ThenByDescending(x => x.Key).ToList();

                        if (!isRicCumulo && (datiPensione.GetFiltro() == "BNS" || datiPensione.GetFiltro() == "BNX" ||
                            (Utility.IsRicostituzioneOrRiapertura(datiPensione, isRiaperturaDomanda) &&
                            ((!string.IsNullOrEmpty(datiPensione.NaturaPensione) && datiPensione.NaturaPensione.Substring(1, 1) == "Y") || Utility.IsDomandaPensioneSuperstitiOrRicostituzione(datiPensione)))))
                        {
                            var primaDecorrenza = listaDecorrenze.First();
                            anniDifferenza = (primaDecorrenza.Value.Value - Utility.FirstDayOfMonth(appData.Value)).Days / 365;
                            if (anniDifferenza < 2 && primaDecorrenza.Key)
                            {
                                if (listaDecorrenze.First().Value != Utility.FirstDayOfMonth(appData.Value) && !GestioneBypassControllo.CheckAndLockBypassControlloByNomeBypass(datiPensione, GestioneBypassControllo.NomeBypass.SUP_INF_2AN_SENT_O_ART6_L40790.SUP_INF_2AN_SENT_O_ART6_L40790))
                                {
                                    messaggioVideo = "E' consentito inserire un supplemento solamente dopo 5 anni dalla decorrenza della pensione o dal precedente supplemento (" + String.Format("{0:MM/yyyy}", appData) + ") con un'unica eccezione a 2 anni.";
                                    return false;
                                }
                                else
                                    listaDecorrenze.RemoveAt(0);
                            }
                        }

                        if (!isRicCumulo)
                        {
                            var isDec = false;
                            foreach (var decorrenzaSupplemento in listaDecorrenze)
                            {
                                if (decorrenzaSupplemento.Value.HasValue && appData.HasValue)
                                {
                                    if (isRicREV && !isDec && decorrenzaSupplemento.Value == datiPensione.DecorrenzaOriginaria.Value)
                                    {
                                        isDec = true;
                                        continue;
                                    }

                                    anniDifferenza = (decorrenzaSupplemento.Value.Value - Utility.FirstDayOfMonth(appData.Value)).Days / 365;
                                    if (anniDifferenza < 2 && !GestioneBypassControllo.CheckAndLockBypassControlloByNomeBypass(datiPensione, GestioneBypassControllo.NomeBypass.SUP_INF_2AN_SENT_O_ART6_L40790.SUP_INF_2AN_SENT_O_ART6_L40790))
                                    {
                                        messaggioVideo = "E' consentito inserire un supplemento solamente dopo 5 anni dalla decorrenza della pensione o dal precedente supplemento (" + String.Format("{0:MM/yyyy}", appData) + ") con un'unica eccezione a 2 anni.";
                                        return false;
                                    }

                                    if (anniDifferenza >= 2 && anniDifferenza < 5)
                                    {
                                        if (flagEccezione || !decorrenzaSupplemento.Key)
                                        {
                                            messaggioVideo = "E' consentito un unico supplemento dopo 2 anni dalla decorrenza della pensione o dal precedente supplemento (" + String.Format("{0:MM/yyyy}", appData) + "). " +
                                                "Il successivo supplemento deve essere inserito dopo 5 anni dal precedente.";
                                            return false;
                                        }
                                        else
                                            flagEccezione = true;
                                    }
                                }

                                appData = decorrenzaSupplemento.Value;
                            }
                        }
                        else
                        {
                            foreach (var decorrenzaSupplemento in listaDecorrenze)
                            {
                                if (decorrenzaSupplemento.Value.HasValue && appData.HasValue)
                                {
                                    if (decorrenzaSupplemento.Value != appData.Value)
                                    {
                                        anniDifferenza = (decorrenzaSupplemento.Value.Value - Utility.FirstDayOfMonth(appData.Value)).Days / 365;
                                        if (anniDifferenza < 2)
                                        {
                                            messaggioVideo = "E' consentito inserire un supplemento solamente dopo 5 anni dalla decorrenza della pensione o dal precedente supplemento (" + String.Format("{0:MM/yyyy}", appData) + ") con un'unica eccezione a 2 anni.";
                                            return false;
                                        }

                                        if (anniDifferenza >= 2 && anniDifferenza < 5)
                                        {
                                            if (flagEccezione || !decorrenzaSupplemento.Key)
                                            {
                                                messaggioVideo = "E' consentito un unico supplemento dopo 2 anni dalla decorrenza della pensione o dal precedente supplemento (" + String.Format("{0:MM/yyyy}", appData) + "). " +
                                                    "Il successivo supplemento deve essere inserito dopo 5 anni dal precedente.";
                                                return false;
                                            }
                                            else
                                                flagEccezione = true;
                                        }
                                    }
                                }

                                appData = decorrenzaSupplemento.Value;
                            }

                            flagEccezione = false;
                            if (isRicCumulo && listDatiSupplementi.Any(x => x.EnteGestioneFondo == 14))
                            {
                                listaDecorrenze = listDatiSupplementi.Where(x => x.EnteGestioneFondo == 14).Select(x => new KeyValuePair<bool, DateTime?>(listaIdEnte.Contains(x.EnteGestioneFondo), x.Decorrenza)).ToList();
                                appData = decorrenzaPensione;

                                foreach (var decorrenzaSupplemento in listaDecorrenze)
                                {
                                    if (decorrenzaSupplemento.Value.HasValue && appData.HasValue)
                                    {
                                        anniDifferenza = (decorrenzaSupplemento.Value.Value - Utility.FirstDayOfMonth(appData.Value)).Days / 365;
                                        if (anniDifferenza < 2)
                                        {
                                            messaggioVideo = "Attenzione in gestione separata il supplemento dopo due anni dalla decorrenza della pensione può essere concesso solo se trattasi di primo supplemento.";
                                            return false;
                                        }
                                        if (anniDifferenza >= 2 && anniDifferenza < 5)
                                        {
                                            if (flagEccezione)
                                            {
                                                messaggioVideo = "Attenzione in gestione separata il supplemento dopo due anni dalla decorrenza della pensione può essere concesso solo se trattasi di primo supplemento.";
                                                return false;
                                            }
                                        }
                                    }

                                    flagEccezione = true;
                                    appData = decorrenzaSupplemento.Value;
                                }
                            }
                        }
                    }
                    else
                    {
                        codiciMessaggio = new List<string> { "A1", "A2", "A3", "A4" };
                        bool isDec = false;
                        List<KeyValuePair<bool, DateTime?>> listaDecorrenze = listDatiSupplementi.GroupBy(x => new { IsIn = listaIdEnte.Contains(x.EnteGestioneFondo), x.Decorrenza }).Select(x => x.First()).Select(x => new KeyValuePair<bool, DateTime?>(listaIdEnte.Contains(x.EnteGestioneFondo), x.Decorrenza)).OrderBy(x => x.Value).ThenByDescending(x => x.Key).Where(x => x.Key == true).ToList();
                        foreach (var decorrenzaSupplemento in listaDecorrenze)
                        {
                            if (decorrenzaSupplemento.Value.HasValue && appData.HasValue)
                            {
                                if (isRicREV && !isDec && decorrenzaSupplemento.Value == datiPensione.DecorrenzaOriginaria.Value)
                                {
                                    isDec = true;
                                    continue;
                                }
                                anniDifferenza = (decorrenzaSupplemento.Value.Value - Utility.FirstDayOfMonth(appData.Value)).Days / 365;
                                if (anniDifferenza < 2)
                                {
                                    messaggioVideo = "E' consentito inserire un supplemento solamente dopo 2 anni dalla decorrenza della pensione diretta";
                                    return false;
                                }
                                if (anniDifferenza >= 2)
                                {
                                    if (flagEccezione || !decorrenzaSupplemento.Key)
                                    {
                                        messaggioVideo = "E' consentito un unico supplemento dopo 2 anni dalla decorrenza della pensione";
                                        return false;
                                    }
                                    else
                                        flagEccezione = true;
                                }
                            }
                        }
                    }
                }
            }
            return true;
        }

        public static bool AGO_ControlDatiSupplementiCumulo(GestionePensione.DatiPensione datiPensione, List<DatiSupplementiCumulo> listaSupplementiCumulo,
            List<GestioneDecodifica.DecEnteGestioneFondo> listaDecEnteGestioneFondo, List<GestioneCalcolo.QuotePensione> listaQuotePensione, bool isRiaperturaDomanda, BLCommon.GestioneDanteCausa.DatiDanteCausa datiDanteCausa, out string messaggioVideo)
        {
            messaggioVideo = string.Empty;
            bool isRicREV = false;
            if (!Utility.IsDomandaRiliquidazioneIndiretta(datiPensione))
            {
                if (Utility.IsRicostituzione(datiPensione.Gruppo) && Utility.IsDomandaPensioneReversibilitaOrRicostituzione(datiPensione, datiDanteCausa))
                    isRicREV = true;

                if (listaSupplementiCumulo != null && listaSupplementiCumulo.Count > 0)
                {
                    // Quando si inserisce/modifica un supplemento “Importo Quota” e “Settimane” sono obbligatori
                    if (listaSupplementiCumulo.Exists(x => !x.Importo.HasValue || !x.Settimane.HasValue))
                    {
                        //ENG - RIC SUPPLEMENTO ORDINARIO VOCUM (GPT 0031/0102/0001) e RIC CONTRIBUTIVE VOCUM: saltare il controllo per i supplementi di tipo "pro quota casse" che hanno Ente/gestioneFondo esterno
                        if (((Utility.IsRicostituzione_Supplemento(datiPensione) && datiPensione.Prodotto == "0102") || Utility.IsRicostituzione_MotiviContributivi(datiPensione))
                            && Utility.IsDomandaVOCUM(datiPensione.SiglaCategoria))
                        {
                            GestioneDatiGenericiAgoCi.PensioniDatiGenerici datiPensioniDatiGenerici = null;
                            GestioneDatiGenericiAgoCi.GetDatiGenericiByIdPensione(datiPensione.Id, out datiPensioniDatiGenerici);
                            List<string> listaCodiciGestioneFondoEsterni = new List<string> { "F1", "G0", "H0", "I0", "J0", "K0", "L0", "M0", "N0", "O0", "P0", "Q0", "R0", "S0", "T0", "U0", "V0", "Z0", "Z1" };

                            if (listaSupplementiCumulo.Exists(x => (!x.Importo.HasValue || !x.Settimane.HasValue)
                                && (!x.AdeguamentoProQuotaCasse.GetValueOrDefault() || (!listaDecEnteGestioneFondo.Exists(y => y.Id == x.EnteGestioneFondo) || !listaCodiciGestioneFondoEsterni.Contains(listaDecEnteGestioneFondo.Find(y => y.Id == x.EnteGestioneFondo).Codice)))))
                            {
                                messaggioVideo = "I campi Importo Quota e Settimane sono obbligatori";
                                return false;
                            }
                        }
                        else
                        {
                            messaggioVideo = "I campi Importo Quota e Settimane sono obbligatori";
                            return false;
                        }

                    }

                    if (listaDecEnteGestioneFondo != null && listaDecEnteGestioneFondo.Count > 0)
                    {
                        if (isRicREV && (Utility.IsDomandaSOCUM(datiPensione.SiglaCategoria) || Utility.IsDomandaSOTOT(datiPensione.SiglaCategoria)))
                        {
                            // Verificare che la decorrenza del supplemento si trovi all'interno dell'intervallo composto dalla decorrenza della pensione del dante causa e la decorrenza della pensione ai superstiti (estremi inclusi)
                            if (listaSupplementiCumulo
                                .Any(x =>
                                    !Utility.DataSuccessivaA(x.Decorrenza.GetValueOrDefault(), datiDanteCausa.DecorrenzaPensione.GetValueOrDefault()) ||
                                    Utility.DataStrettamenteSuccessivaA(x.Decorrenza.GetValueOrDefault(), datiPensione.DecorrenzaOriginaria.GetValueOrDefault())
                                    )
                                )
                            {
                                messaggioVideo = string.Format("La decorrenza dei supplementi deve rientrare nell'intervallo tra la decorrenza della pensione del dante causa {0:dd/MM/yyyy} e la decorrenza della pensione ai superstiti {1:dd/MM/yyyy} (estremi inclusi)",
                                    datiDanteCausa.DecorrenzaPensione.GetValueOrDefault(), datiPensione.DecorrenzaOriginaria.GetValueOrDefault());
                                return false;
                            }
                        }

                        // Per gli enti con codici A5,A6,A7,A8,A9,B1,B2,B3,B4,B5,B6,C1,C2,C3,C4,C5,D1,E1,E2,F0,F1,G0,H0,I0,J0,K0,L0,M0,N0,O0,P0,Q0,R0,S0,T0,U0,V0,Z0,Z1
                        // Si deve verificare che per ogni codice ente ricevuto in GP2BE02 esista almeno un record corrispondente in GP2BB05 con il medesimo codice ente
                        List<string> listaCodiciEnte = new List<string> { "A6", "A7", "A8", "A9", "B1", "B2", "B3", "B4", "B5", "B6", "C1", "C2", "C3", "C4", "C5", "D1", "E1", "E2", "F0", "F1",
                        "G0", "H0", "I0", "J0", "K0", "L0", "M0", "N0", "O0", "P0", "Q0", "R0", "S0", "T0", "U0", "V0", "Z0", "Z1" };
                        if (!Utility.IsDomandaTotalizzazione(datiPensione.SiglaCategoria) && !(Utility.IsRicostituzione(datiPensione.Gruppo) && Utility.IsDomandaCumulo(datiPensione.SiglaCategoria)))
                            listaCodiciEnte.Add("A5");
                        if (Utility.IsRicostituzione(datiPensione.Gruppo) && Utility.IsDomandaCumulo(datiPensione.SiglaCategoria))
                            listaCodiciEnte.Remove("B6");
                        List<GestioneDecodifica.DecEnteGestioneFondo> listaAppDec = listaDecEnteGestioneFondo.FindAll(x => listaCodiciEnte.Contains(x.Codice) &&
                            listaSupplementiCumulo.Exists(y => y.EnteGestioneFondo == x.Id) && !listaQuotePensione.Exists(y => y.EnteGestioneFondo == x.Id));
                        if (listaAppDec.Count > 0 && !(Utility.IsRicostituzione(datiPensione.Gruppo) && Utility.IsDomandaCumulo(datiPensione.SiglaCategoria)))
                        {
                            messaggioVideo = string.Format("Tra le quote pensione mancano le registrazioni con codice ente {0}", string.Join(", ", listaAppDec.Select(x => x.Codice).ToArray()));
                            return false;
                        }

                        // Per gli enti con codici A1,A2,A3,A4
                        // Si deve verificare che per ogni codice ente ricevuto in GP2BE02 esista almeno un record corrispondente in GP2BB05 con codice ente che inizi per “A”
                        listaCodiciEnte = new List<string> { "A1", "A2", "A3", "A4" };
                        if (listaDecEnteGestioneFondo.Exists(x => listaCodiciEnte.Contains(x.Codice) && listaSupplementiCumulo.Exists(y => y.EnteGestioneFondo == x.Id)) &&
                            !listaDecEnteGestioneFondo.Exists(x => x.Codice.StartsWith("A") && listaQuotePensione.Exists(y => y.EnteGestioneFondo == x.Id)))
                        {
                            messaggioVideo = string.Format("Per i supplementi con Ente/Gestione Fondo {0} è richiesta la presenza di almeno una registrazione di quote pensione che abbia Ente/Gestione Fondo {1}",
                                string.Join(", ", listaCodiciEnte.ToArray()), string.Join(", ", listaDecEnteGestioneFondo.FindAll(x => x.Codice.StartsWith("A")).Select(x => x.Codice).ToArray()));
                            return false;
                        }

                        if (!(Utility.IsRicostituzione(datiPensione.Gruppo) && Utility.IsDomandaCumulo(datiPensione.SiglaCategoria) &&
                            (datiPensione.Prodotto == "0102" || datiPensione.Prodotto == "0302" || datiPensione.Prodotto == "0402") && datiPensione.Tipo == "0184"))
                        {
                            listaCodiciEnte = new List<string> { "A1", "A2", "A3", "A4" };
                            if (Utility.IsDomandaSOCUM(datiPensione.SiglaCategoria) || Utility.IsDomandaTotalizzazione(datiPensione.SiglaCategoria))
                            {
                                if (Utility.IsDomandaTotalizzazione(datiPensione.SiglaCategoria))
                                    listaCodiciEnte.Add("A5");


                                //Verificare che sia possibile inserire solo le gestioni presenti nei dati di calcolo o in presenza di A1, A2, A3 o A4, una di queste
                                if (listaDecEnteGestioneFondo.Where(x => !listaCodiciEnte.Exists(y => y == x.Codice)).Any(x => listaSupplementiCumulo.Exists(y => y.EnteGestioneFondo == x.Id) && !listaQuotePensione.Exists(y => y.EnteGestioneFondo == x.Id)))
                                {
                                    messaggioVideo = string.Format("Sono ammessi solo i seguenti valori per Ente/Gestione Fondo: {0}", string.Join(", ", listaDecEnteGestioneFondo.Where(x => listaQuotePensione.Find(y => y.EnteGestioneFondo == x.Id) != null).Select(x => x.Codice).ToList().ToArray()));
                                    return false;
                                }

                                //Verificare che il supplimento di getione A1, A2, A3 e A4 siano inseribili solo se uno di questi è presente tra le quote pensione
                                if (listaDecEnteGestioneFondo.Where(x => listaCodiciEnte.Exists(y => y == x.Codice)).Any(x => listaSupplementiCumulo.Exists(y => y.EnteGestioneFondo == x.Id)) &&
                                    !listaDecEnteGestioneFondo.Where(x => listaCodiciEnte.Exists(y => y == x.Codice)).Any(x => listaQuotePensione.Exists(y => y.EnteGestioneFondo == x.Id)))
                                {
                                    messaggioVideo = string.Format("I valori {0} di Ente/Gestione Fondo sono ammessi solo se almeno uno di questi è presente tra le quote pensione", string.Join(", ", listaCodiciEnte.ToArray()));
                                    return false;
                                }
                            }
                            else
                            {
                                if (!(Utility.IsRicostituzione(datiPensione.Gruppo) && Utility.IsDomandaCumulo(datiPensione.SiglaCategoria)))
                                {
                                    //Verificare che sia possibile inserire solo le gestioni presenti nei dati di calcolo
                                    if (listaDecEnteGestioneFondo.Exists(x => listaSupplementiCumulo.Exists(y => y.EnteGestioneFondo == x.Id) && !listaQuotePensione.Exists(y => y.EnteGestioneFondo == x.Id)))
                                    {
                                        messaggioVideo = string.Format("Sono ammessi solo i seguenti valori per Ente/Gestione Fondo: {0}", string.Join(", ", listaDecEnteGestioneFondo.Where(x => listaQuotePensione.Find(y => y.EnteGestioneFondo == x.Id) != null).Select(x => x.Codice).ToList().ToArray()));
                                        return false;
                                    }
                                }
                                else
                                {
                                    //RIC Cumulo: le gestioni A1, A2, A3, A4, A5 possono essere inserite se tra le quote pensione esiste almeno una tra queste
                                    //Tutte le altre gestioni INTERNE (tranne A1, A2, A3, A4, A5 e B6) possono essere inserite solo se presenti anche nelle quote pensione
                                    List<string> listaCodiciInterni = new List<string> { "A1", "A2", "A3", "A4", "A5", "A6", "A7", "A8", "A9", "B1", "B2", "B4", "B6", "C1", "C2", "C3", "C4", "C5", "D1", "E1", "E2", "F0" };
                                    List<GestioneDecodifica.DecEnteGestioneFondo> listaDecEnteCodiciInterni = listaDecEnteGestioneFondo.Where(x => listaCodiciInterni.Exists(y => y == x.Codice)).ToList();
                                    listaCodiciEnte.Add("A5");
                                    if (listaDecEnteCodiciInterni != null && listaDecEnteCodiciInterni.Count > 0)
                                    {
                                        if (listaDecEnteCodiciInterni.Where(x => !listaCodiciEnte.Exists(y => y == x.Codice) && x.Id != 14).Any(x => listaSupplementiCumulo.Exists(y => y.EnteGestioneFondo == x.Id) && !listaQuotePensione.Exists(y => y.EnteGestioneFondo == x.Id))
                                            || ((listaDecEnteCodiciInterni.Where(x => listaCodiciEnte.Exists(y => y == x.Codice)).Any(x => listaSupplementiCumulo.Exists(y => y.EnteGestioneFondo == x.Id)) &&
                                                !listaDecEnteCodiciInterni.Where(x => listaCodiciEnte.Exists(y => y == x.Codice)).Any(x => listaQuotePensione.Exists(y => y.EnteGestioneFondo == x.Id)))))
                                        {
                                            messaggioVideo = string.Format("Sono ammessi solo i seguenti valori per Ente/Gestione Fondo: {0}", string.Join(", ", listaDecEnteCodiciInterni.Where(x => listaQuotePensione.Find(y => y.EnteGestioneFondo == x.Id) != null).Select(x => x.Codice).ToList().ToArray()));
                                            return false;
                                        }
                                    }
                                }
                            }
                        }

                        // Per i seguenti codici gestione (GP2BE02) la decorrenza pensione deve essere strettamente maggiore del 01/2017:
                        // G0,H0,I0,J0,K0,L0,M0,N0,O0,P0,Q0,R0,S0,T0,U0,V0,Z0,Z1
                        listaCodiciEnte = new List<string> { "G0", "H0", "I0", "J0", "K0", "L0", "M0", "N0", "O0", "P0", "Q0", "R0", "S0", "T0", "U0", "V0", "Z0", "Z1" };
                        if (!Utility.IsDomandaTotalizzazione(datiPensione.SiglaCategoria) && listaDecEnteGestioneFondo.Exists(x => listaCodiciEnte.Contains(x.Codice) && listaSupplementiCumulo.Exists(y => y.EnteGestioneFondo == x.Id)) &&
                            datiPensione.DecorrenzaOriginaria.HasValue && !Utility.DataStrettamenteSuccessivaA(datiPensione.DecorrenzaOriginaria.Value, new DateTime(2017, 1, 1)))
                        {
                            messaggioVideo = string.Format("In presenza di supplementi con Ente/Gestione Fondo {0} la Decorrenza Pensione deve essere strettamente maggiore del 01/2017",
                                string.Join(", ", listaCodiciEnte.ToArray()));
                            return false;
                        }

                        // Per gli enti con codici A1,A2,A3,A4,A5,A6,A7,A8,A9,B1,B2,B4,B6 deve essere applicato il controllo generale dei 2 / 5 anni sulla decorrenza del supplemento in relazione 
                        // alla decorrenza pensione/ decorrenza dell’ultimo supplemento.
                        //Per i supplementi per le RIC da reversibilità i controlli devono puntare alla decorrenza pensione del dante causa
                        DateTime? decorrenza;
                        if (Utility.IsRicostituzione(datiPensione.Gruppo) && Utility.IsDomandaPensioneReversibilitaOrRicostituzione(datiPensione, datiDanteCausa))
                            decorrenza = datiDanteCausa != null ? datiDanteCausa.DecorrenzaPensione : null;
                        else
                            decorrenza = datiPensione.DecorrenzaOriginaria;


                        listaCodiciEnte = new List<string> { "A1", "A2", "A3", "A4", "A5", "A6", "A7", "A8", "A9", "B1", "B2", "B4", "B6" };
                        List<string> codiciMessaggio = new List<string> { "A1", "A2", "A3", "A4", "A5", "A6", "A7", "A8", "A9", "B1", "B2", "B4", "B6" };
                        var listaApp = listaSupplementiCumulo.FindAll(x => listaDecEnteGestioneFondo.Exists(y => y.Id == x.EnteGestioneFondo && listaCodiciEnte.Contains(y.Codice)));
                        if ((!datiPensione.IsCumuloAutomatica.GetValueOrDefault() || !GestioneBypassControllo.CheckAndLockBypassControlloByNomeBypass(datiPensione, GestioneBypassControllo.NomeBypass.Supplementi_Supplementi_AGO.SUPPLEMENTI_CUMULO_AUTOMATICA))
                            && listaApp != null && !AGO_VerificaSupplementiDecorrenza(listaApp, datiPensione, decorrenza, isRiaperturaDomanda, datiDanteCausa, listaDecEnteGestioneFondo, out messaggioVideo, ref codiciMessaggio))
                        {
                            if (!(Utility.IsRicostituzione(datiPensione.Gruppo) && Utility.IsDomandaCumulo(datiPensione.SiglaCategoria)))
                                messaggioVideo = string.Format("Errore per le registrazioni con Ente/Gestione Fondo {0}: {1}", string.Join(", ", codiciMessaggio.ToArray()), messaggioVideo);
                            return false;
                        }

                        // Per le domande per le quali nella scheda “Quote Pensione” siano presenti registrazioni che abbiano la quota fittizia (01/01/9999), allora non dovrà essere possibile 
                        // avere un supplemento che abbia la medesima Ente/Gestione
                        listaCodiciEnte = listaDecEnteGestioneFondo.FindAll(x =>
                            listaQuotePensione.Exists(y => y.Decorrenza.HasValue && y.Decorrenza.Value.Year == 9999 && y.EnteGestioneFondo == x.Id) &&
                            listaSupplementiCumulo.Exists(y => y.EnteGestioneFondo == x.Id)).Select(x => x.Codice).ToList();
                        if (listaCodiciEnte != null && listaCodiciEnte.Count > 0)
                        {
                            messaggioVideo = string.Format("Non è possibile acquisire le registrazioni con Ente/Gestione Fondo {0} perché i codici corrispondono a quote pensione fittizie",
                                string.Join(", ", listaCodiciEnte.ToArray()));
                            return false;
                        }

                        if (isRicREV && (Utility.IsDomandaSOCUM(datiPensione.SiglaCategoria) || Utility.IsDomandaSOTOT(datiPensione.SiglaCategoria)))
                        {
                            // Verificare che la decorrenza del supplemento si trovi all'interno dell'intervallo composto dalla decorrenza della pensione del dante causa e la decorrenza della pensione ai superstiti (estremi inclusi)
                            if (listaSupplementiCumulo
                                .Any(x =>
                                    !Utility.DataSuccessivaA(x.Decorrenza.GetValueOrDefault(), datiDanteCausa.DecorrenzaPensione.GetValueOrDefault()) ||
                                    Utility.DataStrettamenteSuccessivaA(x.Decorrenza.GetValueOrDefault(), datiPensione.DecorrenzaOriginaria.GetValueOrDefault())
                                    )
                                )
                            {
                                messaggioVideo = string.Format("La decorrenza dei supplementi deve rientrare nell'intervallo tra la decorrenza della pensione del dante causa {0:dd/MM/yyyy} e la decorrenza della pensione ai superstiti {1:dd/MM/yyyy} (estremi inclusi)",
                                    datiDanteCausa.DecorrenzaPensione.GetValueOrDefault(), datiPensione.DecorrenzaOriginaria.GetValueOrDefault());
                                return false;
                            }
                        }
                    }
                }
            }
            return true;
        }

        #region private members
        public static string GetDescrizioneSupplemento(BLCommon.Entity.DatiSupplementi supplemento)
        {
            if (supplemento != null)
            {
                return " per il supplemento " + (supplemento.TipoSupplemento.HasValue ? supplemento.TipoSupplemento.Value == 'R' ? "retributivo" : "contributivo" : "") +
                                        " con gestione pari a " + supplemento.CodGestioneSupplemento;
            }
            else
                return string.Empty;
        }

        private static bool IsTipoQuotaValido(string codGestione, char? quota, string codTipoQuota, out string errore)
        {
            errore = string.Empty;
            bool isValido = false;
            switch (codGestione)
            {
                case "A":
                    switch (quota)
                    {
                        case 'A':
                            isValido = String.IsNullOrEmpty(codTipoQuota) || codTipoQuota == "A1";
                            if (!isValido)
                                errore = "Per il codice gestione 'A' con quota 'A' sono ammessi valori di tipo quota pari a '' oppure 'A1'";
                            break;
                        case 'B':
                            isValido = codTipoQuota == "B1" || codTipoQuota == "B2" || codTipoQuota == "B3" || codTipoQuota == "B4" || codTipoQuota == "B6";
                            if (!isValido)
                                errore = "Per il codice gestione 'A' con quota 'B' sono ammessi valori di tipo quota pari a B1, B2, B3, B4, B6";
                            break;
                        default:
                            errore = "La terna Gestione '" + codGestione + "', Quota '" + quota + "' e Tipo Quota '" + codTipoQuota + "' non è valida.";
                            break;
                    }
                    break;
                case "1":
                case "2":
                case "3":
                case "4":
                    switch (quota)
                    {
                        case 'A':
                            isValido = String.IsNullOrEmpty(codTipoQuota);
                            if (!isValido)
                                errore = "Per il codice gestione '" + codGestione + "' con quota 'A' sono ammessi valori di tipo quota pari a ''";
                            break;
                        case 'B':
                            isValido = codTipoQuota == "B" || codTipoQuota == "B9";
                            if (!isValido)
                                errore = "Per il codice gestione '" + codGestione + "' con quota 'B' sono ammessi valori di tipo quota pari a B9";
                            break;
                        default:
                            errore = "La terna Gestione '" + codGestione + "', Quota '" + quota + "' e Tipo Quota '" + codTipoQuota + "' non è valida.";
                            break;
                    }
                    break;
                case "I":
                case "M":
                case "N":
                    isValido = String.IsNullOrEmpty(codTipoQuota);
                    if (!isValido)
                        errore = "Per il codice gestione '" + codGestione + "' con quota 'A' sono ammessi valori di tipo quota pari a ''";
                    break;
                default:
                    errore = "La terna Gestione '" + codGestione + "', Quota '" + quota + "' e Tipo Quota '" + codTipoQuota + "' non è valida.";
                    break;
            }
            return isValido;
        }
        #endregion private members
        #endregion Supplementi

        #region Dati Contributivi
        public static bool AGO_ControlsTipoCalcoloForDatiContributivi(byte? TipoCalcolo, DateTime? FineAssicurazione, GestionePensione.DatiPensione datiPensione, List<GestioneCalcolo.DatiCalcoloContributivo> datiCalcoloContributivo, List<GestioneCalcolo.DatiCalcoloRetributivo> datiCalcoloRetributivo, bool IsPensioneInabilitaPost2012, bool IsDeleteOperation)
        {
            if ((datiCalcoloContributivo == null && datiCalcoloRetributivo == null) ||
                (Utility.IsRiaperturaDomanda(datiPensione.Id) && Utility.IsDomandaCRED27(datiPensione.SiglaCategoria) && !string.IsNullOrEmpty(datiPensione.CodiceTipoRichiesta) && datiPensione.CodiceTipoRichiesta == "67"))
                return true;

            if (IsDeleteOperation)
                return false;

            Utility.TipoAppartenenza? tipoApp = Utility.GetTipoAppartenenza(datiPensione.IndConvInt, datiPensione.Gestione);
            List<GestioneDecodifica.TipoCalcolo> elencoTipoCalcolo = null;
            GestioneDecodifica.GetTipoCalcolo(out elencoTipoCalcolo);
            GestioneDecodifica.TipoCalcolo tipoCalcolo = elencoTipoCalcolo.Find(x => x.Id == TipoCalcolo.Value.ToString() && x.Tipologia.Trim().ToUpperInvariant() == tipoApp.ToString().ToUpperInvariant() && x.Tipo.Trim() == "Inps");
            if (tipoCalcolo != null)
            {
                if ((tipoCalcolo.TraduzioneSuGP == 1 && datiCalcoloRetributivo != null) ||
                    (tipoCalcolo.TraduzioneSuGP == 2 && !IsPensioneInabilitaPost2012 && datiCalcoloContributivo != null && (!FineAssicurazione.HasValue || !Utility.DataSuccessivaA(FineAssicurazione.Value, new DateTime(2012, 01, 01)))) ||
                    (tipoCalcolo.TraduzioneSuGP == 2 && datiCalcoloContributivo != null && datiCalcoloContributivo.FindIndex(x => x.IsQuotaL335Presente(datiPensione)) > -1) ||
                    (tipoCalcolo.TraduzioneSuGP == 9 && (datiCalcoloContributivo == null || datiCalcoloRetributivo == null)) ||
                    (tipoCalcolo.TraduzioneSuGP != 2 && datiCalcoloRetributivo != null && datiCalcoloRetributivo.Exists(x => x.NSettimane707.HasValue)))
                    return false;
            }
            return true;
        }

        public static bool AGO_ControlsFineAssicurazioneForDatiContributivi(Utility.TipoCalcolo tipoCalcolo, DateTime? FineAssicurazione, List<GestioneCalcolo.DatiCalcoloContributivo> datiCalcoloContributivo,
            List<GestioneCalcolo.DatiCalcoloRetributivo> datiCalcoloRetributivo, bool IsPensioneInabilitaPost2012, Utility.TipoUnicarpe tipoUnicarpe, bool? isPLUnicarpe, bool IsDeleteOperation)
        {
            if (datiCalcoloRetributivo == null && datiCalcoloContributivo == null) //controllo necessario quando il quadro dati calcolo non è ancora stato salvato
                return true;

            if (tipoUnicarpe == Utility.TipoUnicarpe.Automatica || isPLUnicarpe.GetValueOrDefault())
                return true;

            if (tipoCalcolo == Utility.TipoCalcolo.Contributivo)      // contrib
            {
                if (datiCalcoloContributivo == null)
                    return false;

                if (!Utility.DataSuccessivaA(FineAssicurazione.Value, new DateTime(2012, 01, 01))) // ante 2012 
                {
                    if (!IsPensioneInabilitaPost2012)
                    {
                        if (datiCalcoloContributivo.FindIndex(x => (x.NSettimaneQuotaDL214.HasValue || x.MontanteQuotaDL214.HasValue || x.ImportoContribTotaleQuotaDL214.HasValue)) > -1)
                            return false;
                    }
                }
                else
                {
                    if (datiCalcoloContributivo.FindIndex(x => (x.NSettimaneQuotaDL214.HasValue || x.MontanteQuotaDL214.HasValue || x.ImportoContribTotaleQuotaDL214.HasValue)) == -1)
                        return false;
                }
            }
            else if (tipoCalcolo == Utility.TipoCalcolo.Retributivo) // retrib
            {
                if (!Utility.DataSuccessivaA(FineAssicurazione.Value, new DateTime(2012, 01, 01))) // ante 2012 
                {
                    if (datiCalcoloContributivo != null)
                    {
                        if (!(IsPensioneInabilitaPost2012 && datiCalcoloContributivo.Count > 0 && datiCalcoloContributivo.FindIndex(x => (x.NSettimaneQuotaDL214.HasValue || x.MontanteQuotaDL214.HasValue || x.ImportoContribTotaleQuotaDL214.HasValue)) > -1 &&
                                datiCalcoloContributivo.FindIndex(x => (x.NSettimane.HasValue || x.MontanteContributivo.HasValue || x.ImportoContributivoTotale.HasValue)) == -1))
                        {
                            return false;
                        }
                    }
                }
                else
                {
                    if (datiCalcoloRetributivo == null || datiCalcoloContributivo == null)
                        return false;

                    if (datiCalcoloContributivo.FindIndex(x => (x.NSettimane.HasValue || x.Montante.HasValue || x.ImportoContributivoTotale.HasValue)) > -1)
                        return false;
                }
            }
            else if (tipoCalcolo == Utility.TipoCalcolo.Misto) // mista
            {
                if (datiCalcoloRetributivo == null || datiCalcoloContributivo == null)
                    return false;

                if (!Utility.DataSuccessivaA(FineAssicurazione.Value, new DateTime(2012, 01, 01))) // ante 2012 
                {
                    if (!IsPensioneInabilitaPost2012)
                    {
                        if (datiCalcoloContributivo.FindIndex(x => (x.NSettimaneQuotaDL214.HasValue || x.MontanteQuotaDL214.HasValue || x.ImportoContribTotaleQuotaDL214.HasValue)) > -1)
                            return false;
                    }
                }
                else
                {
                    if (datiCalcoloContributivo.FindIndex(x => (x.NSettimaneQuotaDL214.HasValue || x.MontanteQuotaDL214.HasValue || x.ImportoContribTotaleQuotaDL214.HasValue)) == -1)
                        return false;
                }
            }
            return true;
        }
