        public static bool AGO_ControlsDataMortePerCumulo(DateTime? dataMorteDC, out string messaggioVideo)
        {
            messaggioVideo = string.Empty;

            DateTime dataLimite = new DateTime(2013, 1, 1);
            if (dataMorteDC.HasValue && !Utility.DataSuccessivaA(dataMorteDC.Value, dataLimite))
            {
                messaggioVideo = "La data morte non può essere antecedente al " + string.Format("{0:dd/MM/yyyy}", dataLimite) + ".";
                return false;
            }

            return true;
        }

        public static bool AGO_ControlsCodNatura1WithDecPensForAut(string naturaPensione, DateTime? decorrenzaPensione, out string messaggioVideo)
        {
            messaggioVideo = string.Empty;

            if (decorrenzaPensione.HasValue)
            {
                string codNatura1 = naturaPensione.Substring(0, 1);
                if (codNatura1 != "5" && decorrenzaPensione < new DateTime(2001, 4, 1))
                {
                    messaggioVideo = "Se il primo codice natura è diverso da '5', la decorrenza della pensione non può essere antecedente al 04/2001.";
                    return false;
                }
                if (codNatura1 == "5" && decorrenzaPensione < new DateTime(1996, 02, 1))
                {
                    messaggioVideo = "Se il primo codice natura è uguale a '5', la decorrenza della pensione non può essere antecedente al 02/1996.";
                    return false;
                }
            }
            return true;
        }

