        public static bool AGO_ControlsTipoBeneficioArt24Comma15Bis(GestionePensione.DatiPensione datiPensione, string tipoSettimaneBeneficio, char? sessoTitolare, DateTime? dataNascitaTitolare,
            short? aaDirittoEnpals, short? mmDirittoEnpals, int? nSettimaneOBG, int? nContributiVolontari, DateTime? decorrenzaOriginaria, string naturaPensione, out string messaggioVideo)
        {
            messaggioVideo = string.Empty;

            if (tipoSettimaneBeneficio == "10" && !(Utility.IsRicostituzione(datiPensione.Gruppo) && Utility.IsDomandaPensioneSuperstitiOrRicostituzione(datiPensione)))
            {
                bool isRipristino = Utility.IsDomandaRipristino(datiPensione) != null ? (bool)Utility.IsDomandaRipristino(datiPensione) : false;

                int settimaneUtiliAlDiritto = AGO_GetNumeroSettimane(datiPensione, aaDirittoEnpals, mmDirittoEnpals, nSettimaneOBG, nContributiVolontari);
                if (!isRipristino && !GestioneCrossControls.ALL_IsTipoBeneficioArt24Comma15BisAmmesso(datiPensione, null, decorrenzaOriginaria, naturaPensione, sessoTitolare, dataNascitaTitolare,
                    settimaneUtiliAlDiritto))
                {
                    messaggioVideo = "Il Tipo Beneficio non è corretto. Non sono presenti i requisiti di cui alla circolare 35/2012.";
                    return false;
                }
            }

            return true;
        }

