        public static bool AGO_ControlsOneriPrepensionamentoEditoria(GestionePensione.DatiPensione datiPensione, GestioneIstruttoria.DatiIstruttoria datiIstruttoria,
            List<GestioneOneri.DatiOneri> listaOneri, bool isRiaperturaDomanda, out string messaggioVideo)
        {
            messaggioVideo = string.Empty;

            if (Utility.IsPrepensionamentoEditoriaFiltroEAA(datiPensione))
            {
                string codeTypeOneriEditoria = Utility.GetTypeOneriEditoria(datiPensione, datiIstruttoria, isRiaperturaDomanda);

                if (codeTypeOneriEditoria != null)
                {
                    if (listaOneri != null && listaOneri.Count > 0)
                    {
                        DateTime? dataScadenza1 = null;
                        DateTime? dataDecorrenza2 = null;

                        List<GestioneDecodifica.SottoGruppoOneri> listaSottoGruppoOneriDB = null;
                        GestioneDecodifica.GetSottoGruppoOneri(out listaSottoGruppoOneriDB);

                        foreach (GestioneOneri.DatiOneri onere in listaOneri)
                        {
                            string codSottoGruppoOnere = listaSottoGruppoOneriDB.Find(x => x.Id == onere.IdCodeSottoGruppo).Code;

                            if (codSottoGruppoOnere != null && codSottoGruppoOnere == "0904")
                            {
                                dataScadenza1 = onere.Scadenza;
                            }
                            if (codSottoGruppoOnere != null && (codSottoGruppoOnere == "0901" || codSottoGruppoOnere == "0903"))
                            {
                                dataDecorrenza2 = onere.Decorrenza;
                            }
                        }

                        if (dataScadenza1 != null && dataDecorrenza2 != null && Utility.DataSuccessivaA(dataScadenza1.Value, dataDecorrenza2.Value))
                        {
                            messaggioVideo = "La decorrenza onere del SottoGruppo 0901 (" + dataDecorrenza2.Value.ToString("dd-MM-yyyy") +
                                    ") deve essere maggiore della scadenza onere del SottoGruppo 0904 (" + dataScadenza1.Value.ToString("dd-MM-yyyy") + ")";
                            return false;
                        }
                    }
                }
                else
                {
                    messaggioVideo = "Prima di salvare gli oneri bisogna inserire il codice su istruttoria.";
                    return false;
                }
            }

            return true;
        }

        public static bool AGO_ControlsOneriDataCessazioneAndScadenzaIndennita(GestionePensione.DatiPensione datiPensione, bool isRiaperturaDomanda, DateTime? dataScadenzaIndennita, List<GestioneOneri.DatiOneri> listaOneri, out string messaggioVideo)
        {
            messaggioVideo = string.Empty;

            if (Utility.IsDomandaAPESociale(datiPensione.SiglaCategoria) && !Utility.IsRicostituzioneOrRiapertura(datiPensione, isRiaperturaDomanda) &&
                dataScadenzaIndennita != null && listaOneri != null && listaOneri.Count > 0)
            {
                DateTime? dataCessazioneBeneficioOnere = null;

                foreach (GestioneOneri.DatiOneri onere in listaOneri)
                {
                    if (onere.IdCodeGruppo != null && onere.IdCodeGruppo == 16)
                    {
                        dataCessazioneBeneficioOnere = onere.Scadenza;
                    }
                }

                if (dataCessazioneBeneficioOnere != null && DateTime.Compare(dataScadenzaIndennita.Value, dataCessazioneBeneficioOnere.Value) != 0)
                {
                    messaggioVideo = "La data di scadenza dell'indennità (" + dataScadenzaIndennita.Value.ToString("dd-MM-yyyy") +
                            ") deve essere uguale alla data di cessazione del beneficio dell'onere (" + dataCessazioneBeneficioOnere.Value.ToString("dd-MM-yyyy") + ")";
                    return false;
                }
            }

            return true;
        }

        public static bool ALL_VerificaPresenzaOneriObbligatori(GestionePensione.DatiPensione datiPensione, bool isRiaperturaDomanda, List<GestioneOneri.DatiOneri> listaOneri, List<GestioneDecodifica.GruppoOneri> listaDecCodeOneri, out string messaggioVideo)
        {
            messaggioVideo = string.Empty;

            //ENG - Memo 123/2024
            GestioneControlliDinamici.ControlloDinamico ctrlMemo123_2024 = null;
            GestioneControlliDinamici.GetControlloDinamicoByNomeControllo("AbilitazioneRIC_TRFMemo123_2024", out ctrlMemo123_2024);

            //ENG - Memo 123/2024
            GestioneControlliDinamici.ControlloDinamico ctrlMemo123_2024OpzioneContrib = null;
            GestioneControlliDinamici.GetControlloDinamicoByNomeControllo("AbilitazioneRIC_TRFMemo123_2024OpzioneContrib", out ctrlMemo123_2024OpzioneContrib);

            if (listaOneri != null && listaOneri.Count > 0)
            {
                GestioneDecodifica.GruppoOneri onereApp = null;
                if (Utility.IsDomandaAPEPrecoci(datiPensione))
                    onereApp = listaDecCodeOneri.FirstOrDefault(x => x.Code == "5000");
                if (Utility.IsDomandaInabilitaAmianto(datiPensione))
                    onereApp = listaDecCodeOneri.FirstOrDefault(x => x.Code == "5100");
                if (Utility.IsDomandaQuota100(datiPensione))
                    onereApp = listaDecCodeOneri.FirstOrDefault(x => x.Code == "5300");
                if (Utility.IsDomandaSperimentaleDonna_DL_4_2019OrRicostituzione(datiPensione))
                    onereApp = listaDecCodeOneri.FirstOrDefault(x => x.Code == "5500");
                if (Utility.IsDomandaAnzianitaPerLeggeBilancio2019OrRicostituzione(datiPensione))
                    onereApp = listaDecCodeOneri.FirstOrDefault(x => x.Code == "5400");
                if (Utility.IsDomandaQuota102(datiPensione))
                    onereApp = listaDecCodeOneri.FirstOrDefault(x => x.Code == "5800");
                if (Utility.IsDomandaAnticipataFlessibile(datiPensione) || Utility.IsDomandaAnticipataFlessibileOpzioneContributivo(datiPensione))
                    onereApp = listaDecCodeOneri.FirstOrDefault(x => x.Code == "6000");
                if ((!Utility.IsRicostituzioneOrRiapertura(datiPensione, isRiaperturaDomanda) && (Utility.IsDomandaAnticipataFlessibileLeggeBilancio2024(datiPensione) || Utility.IsDomandaAnticipataFlessibileOpzioneContributivoLeggeBilancio2024(datiPensione))) ||
                   (Utility.IsRicostituzioneOrRiapertura(datiPensione, isRiaperturaDomanda) && ((ctrlMemo123_2024 != null && ctrlMemo123_2024.ValoreControllo == "SI" && Utility.IsDomandaAnticipataFlessibileLeggeBilancio2024(datiPensione)) || (ctrlMemo123_2024OpzioneContrib != null && ctrlMemo123_2024OpzioneContrib.ValoreControllo == "SI" && Utility.IsDomandaAnticipataFlessibileOpzioneContributivoLeggeBilancio2024(datiPensione)))) ||
                    Utility.IsDomandaVOAUTAnticipataFlessibileLeggeBilancio2024FiltroGSE(datiPensione))
                    onereApp = listaDecCodeOneri.FirstOrDefault(x => x.Code == "6100");

                if (onereApp != null && !listaOneri.Any(x => x.IdCodeGruppo == onereApp.Id))
                {
                    messaggioVideo = "Oneri incongruenti con il tipo di domanda";
                    return false;
                }
            }

            return true;
        }
