        public static bool AGO_ControlsSessoAventiDirittoWithParentela(List<GestioneAventiDiritto.AventiDiritto> listaAventiDiritto, List<GestioneAnagrafica.DatiAnagrafici> anagraficaAventiDiritto,
            char? sessoDanteCausa, out string messaggioVideo)
        {
            messaggioVideo = string.Empty;

            if (sessoDanteCausa.HasValue && listaAventiDiritto != null && listaAventiDiritto.Count > 0)
            {
                foreach (GestioneAventiDiritto.AventiDiritto aventeDiritto in listaAventiDiritto)
                {
                    if (new List<char> { 'C', 'R' }.Contains(aventeDiritto.DecParentelaDA.GetValueOrDefault()))
                    {
                        GestioneAnagrafica.DatiAnagrafici anagrafica = anagraficaAventiDiritto.FirstOrDefault(x => x.Id == aventeDiritto.IdAnagrafica);
                        if (anagrafica != null)
                        {
                            switch (aventeDiritto.TipoUnione.Trim())
                            {
                                case "U":
                                    if (anagrafica.Sesso != sessoDanteCausa.Value)
                                    {
                                        messaggioVideo = string.Format("L'avente diritto {0} non può avere sesso diverso dal Dante Causa per la relazione di parentela {1}", anagrafica.CodiceFiscale,
                                            aventeDiritto.DecParentelaDA == 'C' ? "C - Unito Civilmente" : aventeDiritto.DecParentelaDA == 'R' ? "R - Sciolto dall'unione" : "N/A");
                                        return false;
                                    }
                                    break;
                                case "M":
                                case " ":
                                    if (anagrafica.Sesso == sessoDanteCausa.Value)
                                    {
                                        messaggioVideo = string.Format("L'avente diritto {0} non può avere sesso uguale al Dante Causa per la relazione di parentela {1}", anagrafica.CodiceFiscale,
                                            aventeDiritto.DecParentelaDA == 'C' ? "C - Coniuge" : aventeDiritto.DecParentelaDA == 'R' ? "R - Ex Coniuge" : "N/A");
                                        return false;
                                    }
                                    break;
                            }
                        }
                    }
                }
            }

            return true;
        }

        public static bool AGO_ControlsCombinazioneCodiceNucleo(List<GestioneAventiDiritto.AventiDiritto> listaAventiDiritto, out string messaggioVideo)
        {
            messaggioVideo = String.Empty;

            //Recupero il codice nucleo con il valore più alto
            if (listaAventiDiritto != null)
            {
                string codiceNucleoMax = listaAventiDiritto.Max(x => x.CodiceNucleo).Substring(1, 1);
                byte? lstcodNucleoLenght = Utility.StringToNullableByte(codiceNucleoMax);
                List<string> lstcodNucleo = new List<string>();

                for (int i = 1; i <= lstcodNucleoLenght.Value; i++)
                {
                    lstcodNucleo.Add(String.Format("N{0}", i));
                }

                foreach (string codNucleo in lstcodNucleo)
                {
                    if (!listaAventiDiritto.Exists(x => x.CodiceNucleo == codNucleo))
                    {
                        messaggioVideo = String.Format("Il Codice Nucleo {0} è mancante.", codNucleo);
                        return false;
                    }
                }
            }

            return true;
        }

        public static bool AGO_ControlsVincoliAventiDiritto(List<GestioneAventiDiritto.AventiDiritto> listaAventiDiritto, out string messaggioVideo)
        {
            messaggioVideo = string.Empty;
            GestioneAventiDiritto.AventiDiritto aventeDirittoConiuge = new GestioneAventiDiritto.AventiDiritto();
            List<GestioneAventiDiritto.AventiDiritto> lstAventiDirittoExConiugi = new List<GestioneAventiDiritto.AventiDiritto>();
            List<GestioneAventiDiritto.AventiDiritto> lstAventiDirittoF = new List<GestioneAventiDiritto.AventiDiritto>();
            List<GestioneAventiDiritto.AventiDiritto> lstAventiDirittoA = new List<GestioneAventiDiritto.AventiDiritto>();

            if (listaAventiDiritto != null && listaAventiDiritto.Count > 0)
            {
                aventeDirittoConiuge = listaAventiDiritto.FirstOrDefault(x => x.DecParentelaDA == 'C');

                //Creo liste
                foreach (GestioneAventiDiritto.AventiDiritto aventeDiritto in listaAventiDiritto)
                {
                    if (aventeDiritto.DecParentelaDA == 'R')
                        lstAventiDirittoExConiugi.Add(aventeDiritto);
                    else if (aventeDiritto.DecParentelaDA == 'F')
                        lstAventiDirittoF.Add(aventeDiritto);
                    else if (aventeDiritto.DecParentelaDA == 'A')
                        lstAventiDirittoA.Add(aventeDiritto);
                }

                if (lstAventiDirittoExConiugi.Count > 0 && aventeDirittoConiuge != null)
                {
                    foreach (GestioneAventiDiritto.AventiDiritto aventeDirittoExConiuge in lstAventiDirittoExConiugi)
                    {
                        if (aventeDirittoExConiuge.CodiceNucleo == aventeDirittoConiuge.CodiceNucleo)
                        {
                            messaggioVideo = "Gli aventi diritto con grado di parentela C e R devono avere dei Codici Nucleo differenti.";
                            return false;
                        }
                    }
                }

                if (lstAventiDirittoA.Count > 0)
                {
                    foreach (GestioneAventiDiritto.AventiDiritto aventeDiritto in listaAventiDiritto)
                        foreach (GestioneAventiDiritto.AventiDiritto aventeDirittoA in lstAventiDirittoA)
                        {
                            if ((aventeDiritto.DecParentelaDA == 'C' || aventeDiritto.DecParentelaDA == 'R'
                                || (aventeDiritto.DecParentelaDA == 'M' || aventeDiritto.DecParentelaDA == 'S' || aventeDiritto.DecParentelaDA == 'U' || aventeDiritto.DecParentelaDA == 'I')
                                || (aventeDiritto.DecParentelaDA == 'N' || aventeDiritto.DecParentelaDA == 'Z' || aventeDiritto.DecParentelaDA == 'W' || aventeDiritto.DecParentelaDA == 'J'
                                || aventeDiritto.DecParentelaDA == 'K'))
                                && (aventeDiritto.CodiceNucleo == aventeDirittoA.CodiceNucleo))
                            {
                                messaggioVideo = String.Format("I gradi di parentela A e {0} devono avere dei Codici Nucleo differenti.", aventeDiritto.DecParentelaDA);
                                return false;
                            }
                        }
                }

                if (lstAventiDirittoF.Count > 0)
                {
                    foreach (GestioneAventiDiritto.AventiDiritto aventeDiritto in listaAventiDiritto)
                        foreach (GestioneAventiDiritto.AventiDiritto aventeDirittoF in lstAventiDirittoF)
                        {
                            if ((aventeDiritto.DecParentelaDA == 'C' || aventeDiritto.DecParentelaDA == 'R'
                                || (aventeDiritto.DecParentelaDA == 'M' || aventeDiritto.DecParentelaDA == 'S' || aventeDiritto.DecParentelaDA == 'U' || aventeDiritto.DecParentelaDA == 'I')
                                || (aventeDiritto.DecParentelaDA == 'N' || aventeDiritto.DecParentelaDA == 'Z' || aventeDiritto.DecParentelaDA == 'W' || aventeDiritto.DecParentelaDA == 'J'
                                || aventeDiritto.DecParentelaDA == 'K'))
                                && (aventeDiritto.CodiceNucleo == aventeDirittoF.CodiceNucleo))
                            {
                                messaggioVideo = String.Format("I gradi di parentela F e {0} devono avere dei Codici Nucleo differenti.", aventeDiritto.DecParentelaDA);
                                return false;
                            }
                        }
                }
            }

            return true;
        }

        public static bool AGO_ControlsQuotaContitolaritaNipote(GestionePensione.DatiPensione datiPensione, Utility.TipoAppartenenza? tipoApp, List<GestioneFamiliari.Familiare> familiariApp, List<GestioneFamiliari.CodMaggFamiliari> elencoCodMaggFamiliari, int annoCompetenza, out string msgVideo)
        {
            msgVideo = string.Empty;

            if (tipoApp == null || tipoApp != Utility.TipoAppartenenza.AGO || datiPensione == null || !Utility.IsDomandaPensioneSuperstitiOrRicostituzione(datiPensione) ||
                familiariApp == null || familiariApp.Count == 0 || elencoCodMaggFamiliari == null || elencoCodMaggFamiliari.Count == 0)
                return true;

            if (familiariApp.Exists(x => x.SiglaFamiliare == 'N'))
            {
                List<GestioneFamiliari.Familiare> listaNipoti = familiariApp.FindAll(x => x.SiglaFamiliare == 'N' && x.Confermato);
                foreach (GestioneFamiliari.Familiare nipote in listaNipoti)
                {
                    List<GestioneFamiliari.CodMaggFamiliari> listaCodMaggNipote = elencoCodMaggFamiliari.FindAll(x => x.IdAnagrafica == nipote.IdAnagrafica).OrderBy(x => x.Decorrenza).ToList();
                    if (listaCodMaggNipote != null && listaCodMaggNipote.Count > 0)
                    {
                        GestioneFamiliari.CodMaggFamiliari ultimoCodMaggNipote = listaCodMaggNipote.Last();
                        GestioneAnagrafica.DatiAnagrafici datiAnagrafici = null;
                        GestioneAnagrafica.GetAnagraficaByIdAnagrafica(nipote.IdAnagrafica, out datiAnagrafici);
                        DateTime dataCompare = Utility.FirstDayOfMonth(datiAnagrafici.DataNascita.GetValueOrDefault().AddYears(18).AddMonths(1));
                        if (ultimoCodMaggNipote.CodiceMaggiorazione.GetValueOrDefault() == 2)
                        {
                            if (ultimoCodMaggNipote.Cessazione.HasValue)
                            {
                                if (Utility.DataStrettamenteSuccessivaA(ultimoCodMaggNipote.Cessazione.GetValueOrDefault(), new DateTime(annoCompetenza + 1, 01, 01)))
                                {
                                    msgVideo = string.Format("Per il soggetto {0} la data di fine carico deve essere inferiore o uguale a Gennaio {1}", nipote.CodiceFiscale, annoCompetenza + 1);
                                    return false;
                                }
                                if (Utility.DataStrettamenteSuccessivaA(dataCompare, ultimoCodMaggNipote.Cessazione.Value))
                                {
                                    msgVideo = string.Format("Per il soggetto {0} è necessario inserire un nuovo periodo di carico con grado di parentela 'Nipote', codice maggiorazione 'NO' e con data di fine carico uguale al mese successivo al compimento dei 18 anni", nipote.CodiceFiscale);
                                    return false;
                                }
                            }
                        }
                        else if (ultimoCodMaggNipote.CodiceMaggiorazione.GetValueOrDefault() == 1)
                        {
                            if ((!nipote.DataMorte.HasValue || Utility.DataStrettamenteSuccessivaA(nipote.DataMorte.GetValueOrDefault(), dataCompare)) && Utility.DataStrettamenteSuccessivaA(dataCompare, ultimoCodMaggNipote.Cessazione.Value))
                            {
                                msgVideo = string.Format("Per il soggetto {0} la data di fine carico deve essere uguale al mese successivo al compimento dei 18 anni", nipote.CodiceFiscale);
                                return false;
                            }
                        }
                    }
                }
            }

            return true;
        }
        #endregion Aventi Diritto

        public static bool AGO_ControlsDataCessazioneFamiliari(GestionePensione.DatiPensione datiPensione, Utility.TipoAppartenenza? tipoApp, List<GestioneFamiliari.Familiare> familiariApp, List<GestioneFamiliari.CodMaggFamiliari> elencoCodMaggFamiliari, string siglaCategoria, GestionePensione.DatiEliminazione datiEliminazione, out string messaggioVideo)
        {
            messaggioVideo = string.Empty;

            DateTime? dataSistema = null;
            dataSistema = Utility.DataSistemaAgo;

            if (tipoApp == Utility.TipoAppartenenza.AGO && Utility.IsRicostituzione(datiPensione.Gruppo) && siglaCategoria.Trim() == "SO" && datiEliminazione == null)
            {
                if (familiariApp.Count > 0 && elencoCodMaggFamiliari != null && elencoCodMaggFamiliari.Count > 0)
                {
                    if (!elencoCodMaggFamiliari.Exists(x => !x.Cessazione.HasValue) &&
                        !elencoCodMaggFamiliari.Exists(x => Utility.DataStrettamenteSuccessivaA(x.Cessazione.Value, Utility.DataSistemaAgo)))
                    {
                        messaggioVideo = "Tutti i contitolari sono cessati. Verificare se devono essere prorogati oltre la fine calcolo arretrati oppure eliminare la pensione e ricostituire come pensione eliminata";
                        return false;
                    }
                }
            }
            return true;
        }

        public static int AGO_GetNumeroSettimane(GestionePensione.DatiPensione datiPensione, short? aaDirittoEnpals, short? mmDirittoEnpals, int? nSettimaneOBG, int? nContributiVolontari)
        {
            decimal settimaneUtiliAlDirittoApp = 0;
            if (Utility.IsDomandaENPALS(datiPensione.Gestione))
                settimaneUtiliAlDirittoApp += aaDirittoEnpals.GetValueOrDefault() * 52 + mmDirittoEnpals.GetValueOrDefault() * 4.333M;
            else
                if (Utility.IsDomandaAnticipataFlessibileOpzioneContributivo(datiPensione) || Utility.IsDomandaAnticipataFlessibileOpzioneContributivoLeggeBilancio2024(datiPensione))
                    settimaneUtiliAlDirittoApp = nSettimaneOBG.GetValueOrDefault();
                else
                    settimaneUtiliAlDirittoApp = nSettimaneOBG.GetValueOrDefault() + nContributiVolontari.GetValueOrDefault();

            int settimaneUtiliAlDiritto = (int)Math.Ceiling(settimaneUtiliAlDirittoApp);
            return settimaneUtiliAlDiritto;
        }

        #endregion AGO


        // ENG - Domande IOPGI
        public static bool ALL_VerificaDecorrenzaPensioneIOPGI(GestionePensione.DatiPensione datiPensione, DateTime? decorrenzaOriginaria, DateTime? dataPerfezionamentoRequisiti,
           out string messaggioVideo)
        {
            messaggioVideo = string.Empty;

            if (Utility.IsDomandaIOPGI(datiPensione.SiglaCategoria) && !Utility.IsDomandaIOPGI_AGI(datiPensione))
            {
                GestioneControlliDinamici.ControlloDinamico ctrlAperturaIOPGI_Migrate = null;
                GestioneControlliDinamici.GetControlloDinamicoByNomeControllo("AperturaIOPGI_Migrate", out ctrlAperturaIOPGI_Migrate);
                if (ctrlAperturaIOPGI_Migrate != null && !String.IsNullOrEmpty(ctrlAperturaIOPGI_Migrate.ValoreControllo) && !String.IsNullOrEmpty(ctrlAperturaIOPGI_Migrate.ValoreControllo.Trim()) &&
                    ctrlAperturaIOPGI_Migrate.ValoreControllo == "SI" && Utility.IsRicostituzione(datiPensione.Gruppo) && datiPensione.GP1AV91B == "2")
                    return true;

                if (!dataPerfezionamentoRequisiti.HasValue)
                {
                    messaggioVideo = "Data Perfezionamento Requisiti obbligatoria";
                    return false;
                }

                if (!decorrenzaOriginaria.HasValue || !Utility.DataSuccessivaA(decorrenzaOriginaria.Value, new DateTime(2022, 08, 01)))
                {
                    messaggioVideo = "La decorrenza originaria deve essere maggiore o uguale al 01/08/2022";
                    return false;
                }
            }

            return true;
        }

        //ENG - Memo 48_2023
        //Segnalazione 33631 spostare il controllo dal pannello "Titolare" al pannello "Liquidazione Pensione" dati generici alla selezione "Esenzione Fiscale Residente Estero".
        public static bool VerificaResidenzaCittadinanzaTitolareBulgaria(GestionePensione.DatiPensione datiPensione, string cittadinanza, string codiceComuneResidenza, out string messaggioVideo)
        {
            messaggioVideo = string.Empty;

            if (datiPensione == null)
            {
                messaggioVideo = "Dati pensione non disponibili";
                return false;
            }

            if (!GestioneBypassControllo.CheckAndLockBypassControlloByNomeBypass(datiPensione, GestioneBypassControllo.NomeBypass.LiquidazionePensione_Generici_AGO.DETASSAZIONE_BULGARIA))
            {
                if (Utility.IsRicostituzione(datiPensione.Gruppo))
                {
                    string codiceStatoBulgaria = "Z104";
                    string cittadinanzaTitolare = !String.IsNullOrEmpty(cittadinanza) ? cittadinanza.Trim().ToUpperInvariant() : "";
                    string residenzaTitolare = !String.IsNullOrEmpty(codiceComuneResidenza) ? codiceComuneResidenza.Trim().ToUpperInvariant() : "";
                    if ((cittadinanzaTitolare == codiceStatoBulgaria && residenzaTitolare != codiceStatoBulgaria)
                        || (cittadinanzaTitolare != codiceStatoBulgaria && residenzaTitolare == codiceStatoBulgaria))
                    {
                        messaggioVideo = "Per i residenti in Bulgaria, ai fini dell'applicazione della detassazione, è necessario che il pensionato abbia la cittadinanza bulgara (anche se non esclusiva)";
                        return false;
                    }
                }
            }

            return true;
        }

        //ENG - Vecchiaia in Computo
        public static bool VerificaPerfezionamentoRequisitiVecchiaiaInComputo(GestionePensione.DatiPensione datiPensioneDB, GestionePensione.DatiPensione datiPensioneUI, Utility.TipoAppartenenza? tipoAppartenenza, out string errori)
        {
            errori = string.Empty;

            GestioneControlliDinamici.ControlloDinamico ctrl = null;
            GestioneControlliDinamici.GetControlloDinamicoByNomeControllo("AbilitazioneMemo123_2021", out ctrl);

            if (ctrl != null && !String.IsNullOrEmpty(ctrl.ValoreControllo) && ctrl.ValoreControllo.Trim().ToUpperInvariant() == "SI" && tipoAppartenenza == Utility.TipoAppartenenza.AGO && Utility.IsDomandaVecchiaiaInComputo(datiPensioneDB))
            {
                if (Utility.DataStrettamenteSuccessivaA(datiPensioneUI.DataCondizioniPerComputo.GetValueOrDefault(), new DateTime(2011, 12, 31)))
                {
                    if (!Utility.DataStrettamenteSuccessivaA(datiPensioneUI.DataPerfezionamentoRequisiti.GetValueOrDefault(), new DateTime(2011, 12, 31)))
                    {
                        errori = string.Format("La data di perfezionamento dei requisiti deve essere maggiore o uguale al 2012");
                        return false;
                    }
                }
            }

            return true;
        }
    
        private static bool ControlloEsecuzioneControlliDecorrenzaMemoAlbania(GestionePensione.DatiPensione datiPensione,
            GestioneDanteCausa.DatiDanteCausa datiDanteCausa)
        {
            bool eseguiControlloDecorrenzaPerMemoAlbania = true;
            bool flagCheckIndiretta = Utility.IsDomandaPensioneIndiretta(datiPensione);
            List<GestioneDatiContributiviCi.PensioniCiPrestazioniEE> listaPrestazioniEstere = null;
            GestioneDatiContributiviCi.GetPrestazioniEEByIdPensione(datiPensione.Id, out listaPrestazioniEstere);

            if (!(datiDanteCausa == null) && !(listaPrestazioniEstere == null) && datiDanteCausa.DataMorte.HasValue)
            {
                bool flagCheckDataMorteDC = DateTime.Compare((DateTime)datiDanteCausa.DataMorte, new DateTime(2025, 06, 01)) < 0;

                bool controlloAlbania = false;
                foreach (GestioneDatiContributiviCi.PensioniCiPrestazioniEE statoEstero in listaPrestazioniEstere)
                {
                    bool controlloCondiceStatoEE = statoEstero.CodiceStatoEE == "59";
                    bool controlloCodiceConvenzione = statoEstero.CodiceConvenzione == 61;
                    if (controlloCondiceStatoEE && controlloCodiceConvenzione)
                        controlloAlbania = true;
                }

                if (flagCheckIndiretta && flagCheckDataMorteDC && controlloAlbania)
                    eseguiControlloDecorrenzaPerMemoAlbania = false;
            }
            return eseguiControlloDecorrenzaPerMemoAlbania;
        }
    }
